class CompactFormLayout(QGridLayout):
    def __init__(self):
        super().__init__()
        self._next_row = 0
        self._label_alignment = Qt.AlignRight | Qt.AlignVCenter

    def setLabelAlignment(self, alignment):
        self._label_alignment = alignment

    def addRow(self, label, field=None):
        if field is None:
            self.addWidget(label, self._next_row, 0, 1, 2)
        else:
            if isinstance(label, str):
                label = QLabel(label)
            label.setAlignment(self._label_alignment)
            self.addWidget(label, self._next_row, 0)
            self.addWidget(field, self._next_row, 1)
        self._next_row += 1


