# ── data model ────────────────────────────────────────────────────────────────
class Vertex:
    def __init__(self, x, y, locked=False):
        self.x = float(x); self.y = float(y)
        self.locked = locked      # excluded from solving (reference geometry or rigid text)
    def xy(self): return (self.x, self.y)

class Segment:
    def __init__(self, v0, v1, construction=False, reference=False):
        self.v0 = v0; self.v1 = v1
        self.construction = construction or reference   # support geometry: never extruded
        self.reference = reference                      # projected edge of the sketch face
    def length(self):
        return math.hypot(self.v1.x-self.v0.x, self.v1.y-self.v0.y)
    def midpoint(self):
        return ((self.v0.x+self.v1.x)/2, (self.v0.y+self.v1.y)/2)
    def midpoint_of(self, P):
        (ax, ay), (bx, by) = P(self.v0), P(self.v1)
        return ((ax+bx)/2, (ay+by)/2)
    def axis(self):
        if abs(self.v1.y-self.v0.y) < AXIS_TOL: return 'H'
        if abs(self.v1.x-self.v0.x) < AXIS_TOL: return 'V'
        return 'D'

class SketchText:
    """Rigid outline geometry; only whole-label moves and uniform scaling change its vertices."""
    def __init__(self, label, segments, *, box_vertices=None, font_family="Arial",
                 font_size=12.0, bold=False, italic=False, underline=False, align="left"):
        self.label = label
        self.segments = list(segments)
        self.box_vertices = list(box_vertices or [])
        self.font_family = str(font_family or "Arial")
        self.font_size = float(font_size)
        self.bold = bool(bold)
        self.italic = bool(italic)
        self.underline = bool(underline)
        self.align = align if align in ("left", "center", "right") else "left"
        for v in self.vertices(): v.locked = True

    def vertices(self):
        verts = {v for s in self.segments for v in (s.v0, s.v1)}
        verts.update(self.box_vertices)
        return verts

    def bounds(self):
        verts = self.vertices()
        return (min(v.x for v in verts), min(v.y for v in verts),
                max(v.x for v in verts), max(v.y for v in verts))

    def corners(self):
        if len(self.box_vertices) >= 4:
            return [v.xy() for v in self.box_vertices[:4]]
        x0, y0, x1, y1 = self.bounds()
        return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]

    def constraint_points(self):
        if len(self.box_vertices) >= 9:
            return [v.xy() for v in self.box_vertices[:9]]
        corners = self.corners()
        (x0, y0), (x1, _), (_, y1), _ = corners
        xm, ym = (x0 + x1)/2, (y0 + y1)/2
        return corners + [(xm, y0), (x1, ym), (xm, y1), (x0, ym), (xm, ym)]

class Circle:
    def __init__(self, center, radius=10.0, construction=False, reference=False):
        self.center = center; self.radius = radius
        self.construction = construction or reference
        self.reference = reference
        self.locked = reference   # radius is not a solver variable

class Arc:
    """Partial circle running CCW from v_start to v_end around center.
    Radius is |center→v_start|; an implicit equation keeps v_end on that radius."""
    def __init__(self, center, v_start, v_end, construction=False, reference=False):
        self.center = center; self.v_start = v_start; self.v_end = v_end
        self.construction = construction or reference
        self.reference = reference
    def radius(self):
        return math.hypot(self.v_start.x-self.center.x, self.v_start.y-self.center.y)
    def angles(self):
        """(start angle, CCW sweep) in radians."""
        a0 = math.atan2(self.v_start.y-self.center.y, self.v_start.x-self.center.x)
        a1 = math.atan2(self.v_end.y-self.center.y, self.v_end.x-self.center.x)
        sweep = (a1-a0) % (2*math.pi)
        if sweep < 1e-9: sweep = 2*math.pi
        return a0, sweep
    def mid_angle(self):
        a0, sw = self.angles(); return a0 + sw/2
    def tess(self):
        a0, sw = self.angles(); r = self.radius()
        n = curve_segments(r, sw)
        cx, cy = self.center.x, self.center.y
        pts = [(cx+r*math.cos(a0+sw*i/n), cy+r*math.sin(a0+sw*i/n)) for i in range(n+1)]
        pts[0] = self.v_start.xy(); pts[-1] = self.v_end.xy()
        return pts

class Ellipse:
    """Smooth ellipse defined by four endpoints of two centered perpendicular diameters."""
    def __init__(self, major_start, major_end, minor_start, minor_end,
                 construction=False, reference=False):
        self.major_start = major_start; self.major_end = major_end
        self.minor_start = minor_start; self.minor_end = minor_end
        self.construction = construction or reference
        self.reference = reference

    def vertices(self):
        return (self.major_start, self.major_end, self.minor_start, self.minor_end)

    def axes(self):
        major_start, major_end, minor_start, minor_end = (v.xy() for v in self.vertices())
        center = tuple((major_start[i] + major_end[i] + minor_start[i] + minor_end[i]) / 4
                       for i in range(2))
        major = ((major_end[0]-major_start[0])/2, (major_end[1]-major_start[1])/2)
        minor = ((minor_end[0]-minor_start[0])/2, (minor_end[1]-minor_start[1])/2)
        return center, major, minor

    def tess(self):
        center, major, minor = self.axes()
        count = curve_segments(max(math.hypot(*major), math.hypot(*minor)))
        return [(center[0] + major[0]*math.cos(2*math.pi*i/count) +
                 minor[0]*math.sin(2*math.pi*i/count),
                 center[1] + major[1]*math.cos(2*math.pi*i/count) +
                 minor[1]*math.sin(2*math.pi*i/count)) for i in range(count)]

class SketchGroup:
    """Rigid group of sketch elements. Its members keep their shape relative to each other
    (they move and rotate as one body); constraints to geometry outside the group still act.
    ref holds each member vertex's position in the group's own frame, radii the circle radii."""
    def __init__(self, segments=(), circles=(), arcs=(), ellipses=(), points=()):
        self.segments = list(segments); self.circles = list(circles); self.arcs = list(arcs)
        self.ellipses = list(ellipses); self.points = list(points)
        self.ref = {}; self.radii = {}
        self.snapshot()

    def elements(self):
        return self.segments + self.circles + self.arcs + self.ellipses + self.points

    def vertices(self):
        verts = set(self.points)
        for s in self.segments: verts |= {s.v0, s.v1}
        for c in self.circles: verts.add(c.center)
        for a in self.arcs: verts |= {a.center, a.v_start, a.v_end}
        for e in self.ellipses: verts.update(e.vertices())
        return verts

    def snapshot(self):
        """Take the current shape as the rigid reference shape."""
        self.ref = {v: (v.x, v.y) for v in self.vertices()}
        self.radii = {c: c.radius for c in self.circles}

    def contains(self, element):
        if isinstance(element, Vertex): return element in self.vertices()
        return any(element is e for e in self.elements())

    def bounds(self):
        xs, ys = [], []
        for v in self.vertices(): xs.append(v.x); ys.append(v.y)
        for c in self.circles:
            xs += [c.center.x-c.radius, c.center.x+c.radius]
            ys += [c.center.y-c.radius, c.center.y+c.radius]
        for e in self.ellipses:
            for x, y in e.tess(): xs.append(x); ys.append(y)
        for a in self.arcs:
            for x, y in a.tess(): xs.append(x); ys.append(y)
        if not xs: return None
        return min(xs), min(ys), max(xs), max(ys)

class PlanetaryRatioSpinBox(QDoubleSpinBox):
    """Step across valid planetary tooth-count ratios rather than arbitrary decimals."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self._planetary_steps = None

    def set_planetary_steps(self, values):
        self._planetary_steps = sorted(set(float(value) for value in values)) if values else None

    def stepBy(self, steps):
        if not self._planetary_steps:
            return super().stepBy(steps)
        values = self._planetary_steps
        current_index = min(range(len(values)), key=lambda index: abs(values[index] - self.value()))
        target_index = min(max(current_index + int(steps), 0), len(values) - 1)
        self.setValue(values[target_index])

# ── constraints ───────────────────────────────────────────────────────────────
# Every constraint is an equation system solved by SketchSystem (Newton / least squares).
class CFixed:
    """Fixes a vertex at the position it had when the constraint was created."""
    kind = "fixed"
    def __init__(self, vertex):
        self.vertex = vertex; self.x0 = vertex.x; self.y0 = vertex.y

class CDimension:
    """Driving dimension. target: Segment (length) | (Vertex,Vertex) (H/V/aligned distance)
    | Circle (diameter or radius, see dim_mode) | Arc (radius)."""
    kind = "dim"
    def __init__(self, target, value, orient=None):
        self.target   = target
        self.value    = value
        self.orient   = orient        # "H"/"V"/"D" for vertex-pair dimensions
        self.dim_mode = "diameter"    # circles only
        self.sign     = 1.0           # direction of H/V pair dimensions
        if isinstance(target, tuple) and orient in ("H", "V"):
            a, b = target
            d = (b.x-a.x) if orient == "H" else (b.y-a.y)
            self.sign = 1.0 if d >= 0 else -1.0
        # drawing placement (user-draggable); None = automatic
        self.off_mm = None; self.side = None; self.t_frac = 0.5; self.angle = None
    def label(self): return f"{self.value:.2f}"

class CPerpendicular:
    """Two segments are perpendicular."""
    kind = "perp"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CCoincident:
    """vertex_move lies on vertex_target."""
    kind = "coincident"
    def __init__(self, vertex_move, vertex_target):
        self.vertex_move   = vertex_move
        self.vertex_target = vertex_target

class CPointOnLine:
    """Vertex lies on the (infinite) line through a segment."""
    kind = "ptline"
    def __init__(self, vertex, seg):
        self.vertex = vertex; self.seg = seg

class CHorizontal:
    """Segment is horizontal."""
    kind = "horiz"
    def __init__(self, seg): self.seg = seg

class CVertical:
    """Segment is vertical."""
    kind = "vert"
    def __init__(self, seg): self.seg = seg

class CPointOnCurve:
    """Vertex lies on a circle / arc (on its full circle)."""
    kind = "ptcurve"
    def __init__(self, vertex, curve):
        self.vertex = vertex; self.curve = curve

class CEqual:
    """Two segments have equal length or two circles have equal radius."""
    kind = "equal"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CParallel:
    """Two segments are parallel."""
    kind = "parallel"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CCollinear:
    """Two segments lie on the same infinite line."""
    kind = "collinear"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CSymmetric:
    """Two segments or two vertices are symmetric about a center line or center point.
    center: Segment (axis of symmetry) or Vertex (center point).
    Two segments are symmetric by their midpoints. lines_only (set when Trim cuts one of the
    segments): only the lines are mirror images — the mirrored midpoint of seg_a lies on the
    line of seg_b — so where the (shortened) pieces end along their lines is free."""
    kind = "symmetric"
    lines_only = False
    def __init__(self, seg_a, seg_b, center):
        self.seg_a = seg_a; self.seg_b = seg_b; self.center = center

def symmetric_lines_only(c):
    """True when the symmetric constraint c acts on the lines only (see CSymmetric)."""
    return bool(getattr(c, "lines_only", False)) and isinstance(c.seg_a, Segment) and \
        isinstance(c.seg_b, Segment)

def _symmetric_mirror(c, point, pos):
    """point mirrored about the centre line / centre point of CSymmetric c."""
    if isinstance(c.center, Segment):
        (ax, ay), (bx, by) = pos(c.center.v0), pos(c.center.v1)
        dx, dy = bx-ax, by-ay; length2 = dx*dx + dy*dy or 1e-12
        t = ((point[0]-ax)*dx + (point[1]-ay)*dy)/length2
        return 2*(ax+t*dx) - point[0], 2*(ay+t*dy) - point[1]
    cx, cy = pos(c.center)
    return 2*cx - point[0], 2*cy - point[1]

def _segment_mid(seg, pos):
    (x0, y0), (x1, y1) = pos(seg.v0), pos(seg.v1)
    return (x0+x1)/2, (y0+y1)/2

def symmetric_line_residual(c, pos):
    """Distance (mm) of seg_a's mirrored midpoint from the line through seg_b."""
    mx, my = _symmetric_mirror(c, _segment_mid(c.seg_a, pos), pos)
    (x0, y0), (x1, y1) = pos(c.seg_b.v0), pos(c.seg_b.v1)
    dx, dy = x1-x0, y1-y0; length = math.hypot(dx, dy) or 1e-12
    return (dx*(my-y0) - dy*(mx-x0))/length

def symmetric_mid_error(c, pos):
    """How far (mm) seg_b's midpoint is from seg_a's mirrored midpoint."""
    mx, my = _symmetric_mirror(c, _segment_mid(c.seg_a, pos), pos)
    bx, by = _segment_mid(c.seg_b, pos)
    return math.hypot(bx-mx, by-my)

class CMirrorPoint:
    """A point and its mirror about a sketch axis or a segment."""
    kind = "mirror"
    def __init__(self, vertex_move, vertex_target, axis):
        self.vertex_move = vertex_move
        self.vertex_target = vertex_target
        self.axis = axis

class CTangential:
    """A line and curve, or two curves, are tangent in their current branch."""
    kind = "tangent"
    def __init__(self, entity_a, entity_b):
        self.entity_a = entity_a; self.entity_b = entity_b
        if isinstance(entity_a, Segment) or isinstance(entity_b, Segment):
            line = entity_a if isinstance(entity_a, Segment) else entity_b
            curve = entity_b if line is entity_a else entity_a
            self.side = 1.0 if _signed_line_dist(
                line.v0.xy(), line.v1.xy(), curve.center.xy()) >= 0.0 else -1.0
            self.external = True
        else:
            def radius(curve):
                return curve.radius if isinstance(curve, Circle) else math.dist(
                    curve.center.xy(), curve.v_start.xy())
            distance = math.dist(entity_a.center.xy(), entity_b.center.xy())
            ra, rb = radius(entity_a), radius(entity_b)
            self.external = abs(distance - (ra + rb)) <= abs(distance - abs(ra - rb))
            self.side = 1.0 if ra >= rb else -1.0


def _constraint_pts(e):
    """Vertex → its point; Segment → (start, end) points."""
    return e.xy() if isinstance(e, Vertex) else (e.v0.xy(), e.v1.xy())

def _signed_line_dist(a, b, p):
    """Signed distance of point p from the infinite line a→b (left = positive)."""
    dx, dy = b[0]-a[0], b[1]-a[1]; L = math.hypot(dx, dy)
    return 0.0 if L < 1e-12 else (dx*(p[1]-a[1]) - dy*(p[0]-a[0]))/L

def _line_angle(a0, a1, b0, b1):
    """Signed angle (rad) from direction a0→a1 to direction b0→b1."""
    ax, ay = a1[0]-a0[0], a1[1]-a0[1]; bx, by = b1[0]-b0[0], b1[1]-b0[1]
    return math.atan2(ax*by - ay*bx, ax*bx + ay*by)

def _angle_ray_sides(line_a, line_b, point_a, point_b):
    """Return endpoint-direction signs for the clicked rays at the lines' intersection."""
    ax, ay = line_a.v0.xy(); adx = line_a.v1.x-ax; ady = line_a.v1.y-ay
    bx, by = line_b.v0.xy(); bdx = line_b.v1.x-bx; bdy = line_b.v1.y-by
    denominator = adx*bdy - ady*bdx
    if abs(denominator) < 1e-12:
        return None
    t = ((bx-ax)*bdy - (by-ay)*bdx) / denominator
    ix, iy = ax+t*adx, ay+t*ady
    side_a = 1.0 if (point_a[0]-ix)*adx + (point_a[1]-iy)*ady >= 0 else -1.0
    side_b = 1.0 if (point_b[0]-ix)*bdx + (point_b[1]-iy)*bdy >= 0 else -1.0
    return side_a, side_b

class CDistance:
    """Distance between two entities: point–point, point–line, line–line or circle–circle.
    Line–line becomes parallel at the given distance; circle–circle measures center distance,
    or the difference between radii when the circles are concentric. Circle–line measures
    clearance from the circumference.
    Line–line may instead use mode "angle" (degrees).
    driving=False → information only (support-geometry mode): no equation, just displayed."""
    kind = "dist"
    def __init__(self, a, b, value=None, mode="distance", driving=True, orient="D",
                 angle_sides=None):
        if isinstance(a, Segment) and isinstance(b, Vertex): a, b = b, a   # point first
        if isinstance(a, Segment) and isinstance(b, Circle): a, b = b, a   # circle first
        self.a = a; self.b = b; self.mode = mode; self.driving = driving
        self.angle_sides = tuple(angle_sides) if angle_sides is not None else None
        self.orient = orient if isinstance(a, Vertex) and isinstance(b, Vertex) else "D"
        self.dim_mode = None
        self.circle_relation = None
        self.circle_outer = None
        self.circle_side = None
        if isinstance(a, Circle) and isinstance(b, Segment):
            side = _signed_line_dist(b.v0.xy(), b.v1.xy(), a.center.xy())
            self.circle_side = 1.0 if side >= 0.0 else -1.0
        if isinstance(a, Circle) and isinstance(b, Circle):
            center_distance = math.hypot(a.center.x - b.center.x, a.center.y - b.center.y)
            if center_distance <= 1e-9:
                self.circle_relation = "concentric"
                self.circle_outer = a if a.radius >= b.radius else b
            else:
                self.circle_relation = "center"
        m = self.measure_signed()
        self.sign = 1.0 if m >= 0 else -1.0
        self.value = abs(m) if value is None else value
        self.off_mm = None; self.side = None; self.t_frac = 0.5; self.angle = None

    @property
    def pair(self):
        kind = lambda entity: "v" if isinstance(entity, Vertex) else \
                              "s" if isinstance(entity, Segment) else \
                              "c" if isinstance(entity, Circle) else "a"
        return kind(self.a) + kind(self.b)

    def measure_signed(self, P=None):
        """Current signed value (mm, or degrees in angle mode). P maps vertex → (x,y)."""
        P = P or (lambda v: v.xy())
        a, b = self.a, self.b
        if self.pair == "vv":
            (ax, ay), (bx, by) = P(a), P(b)
            orient = getattr(self, "orient", "D")
            if orient == "H": return bx - ax          # horizontal distance (signed)
            if orient == "V": return by - ay          # vertical distance (signed)
            return math.hypot(bx-ax, by-ay)
        if self.pair == "cc":
            center_distance = math.hypot(
                P(a.center)[0] - P(b.center)[0],
                P(a.center)[1] - P(b.center)[1])
            if self.circle_relation == "center":
                return center_distance
            if self.circle_relation == "concentric":
                inner = b if self.circle_outer is a else a
                return self.circle_outer.radius - inner.radius
            if self.circle_relation == "nested":
                inner = b if self.circle_outer is a else a
                return self.circle_outer.radius - inner.radius - center_distance
            return center_distance - a.radius - b.radius
        if isinstance(a, Segment) and isinstance(b, Vertex):
            return _signed_line_dist(P(a.v0), P(a.v1), P(b))
        if isinstance(a, Vertex) and isinstance(b, Segment):
            return _signed_line_dist(P(b.v0), P(b.v1), P(a))
        if isinstance(a, Circle) and isinstance(b, Segment):
            return abs(_signed_line_dist(P(b.v0), P(b.v1), P(a.center))) - a.radius
        if self.mode == "angle":
            sides = getattr(self, "angle_sides", None)
            if sides is not None:
                ax, ay = P(a.v1)[0]-P(a.v0)[0], P(a.v1)[1]-P(a.v0)[1]
                bx, by = P(b.v1)[0]-P(b.v0)[0], P(b.v1)[1]-P(b.v0)[1]
                return math.degrees(_line_angle((0.0, 0.0),
                                                (ax*sides[0], ay*sides[0]),
                                                (0.0, 0.0), (bx*sides[1], by*sides[1])))
            return math.degrees(_line_angle(P(a.v0), P(a.v1), P(b.v0), P(b.v1)) % math.pi)
        return _signed_line_dist(P(a.v0), P(a.v1), b.midpoint_of(P))

    def measure(self):
        return abs(self.measure_signed())

    def label(self):
        v = self.value if self.driving else self.measure()
        txt = f"{v:.2f}°" if self.mode == "angle" else f"{v:.2f}"
        return txt if self.driving else f"({txt})"

def constraint_refs(c):
    """Geometry objects (vertices/segments/circles/arcs) referenced by a constraint."""
    if isinstance(c, CFixed):         return {c.vertex}
    if isinstance(c, CDimension):
        return set(c.target) if isinstance(c.target, tuple) else {c.target}
    if isinstance(c, CPerpendicular): return {c.seg_a, c.seg_b}
    if isinstance(c, CCoincident):    return {c.vertex_move, c.vertex_target}
    if isinstance(c, CPointOnLine):   return {c.vertex, c.seg}
    if isinstance(c, CPointOnCurve):  return {c.vertex, c.curve}
    if isinstance(c, (CHorizontal, CVertical)): return {c.seg}
    if isinstance(c, CDistance):      return {c.a, c.b}
    if isinstance(c, CEqual):         return {c.seg_a, c.seg_b}
    if isinstance(c, CParallel):      return {c.seg_a, c.seg_b}
    if isinstance(c, CCollinear):     return {c.seg_a, c.seg_b}
    if isinstance(c, CSymmetric):     return {c.seg_a, c.seg_b, c.center}
    if isinstance(c, CMirrorPoint):
        refs = {c.vertex_move, c.vertex_target}
        if isinstance(c.axis, Segment): refs.add(c.axis)
        return refs
    if isinstance(c, CTangential):    return {c.entity_a, c.entity_b}
    return set()

def describe_constraint(sk, c):
    """Human-readable one-liner for the constraint list."""
    def P(v): return f"P{sk.vertices.index(v)}" if v in sk.vertices else "P?"
    def L(s):
        axis = getattr(s, "sketch_axis", None)
        if axis is not None: return f"{axis.upper()} axis"
        return f"L{sk.segments.index(s)}" if s in sk.segments else "L?"
    if isinstance(c, CFixed):
        at = " at origin" if (c.x0, c.y0) == (0.0, 0.0) else ""
        return f"📌 Fixed  {P(c.vertex)}{at}"
    if isinstance(c, CPerpendicular): return f"⊾ Perpendicular  {L(c.seg_a)} ⟂ {L(c.seg_b)}"
    if isinstance(c, CCoincident):    return f"● Coincident  {P(c.vertex_move)} → {P(c.vertex_target)}"
    if isinstance(c, CPointOnLine):   return f"⊸ Point on line  {P(c.vertex)} on {L(c.seg)}"
    if isinstance(c, CPointOnCurve):
        cu = c.curve
        if isinstance(cu, Circle):
            name = f"circle C{sk.circles.index(cu)}" if cu in sk.circles else "circle C?"
        else:
            name = f"arc A{sk.arcs.index(cu)}" if cu in sk.arcs else "arc A?"
        return f"◌ Point on curve  {P(c.vertex)} on {name}"
    if isinstance(c, CHorizontal):    return f"― Horizontal  {L(c.seg)}"
    if isinstance(c, CVertical):      return f"| Vertical  {L(c.seg)}"
    if isinstance(c, CEqual):
        if isinstance(c.seg_a, Circle) and isinstance(c.seg_b, Circle):
            a = f"C{sk.circles.index(c.seg_a)}" if c.seg_a in sk.circles else "C?"
            b = f"C{sk.circles.index(c.seg_b)}" if c.seg_b in sk.circles else "C?"
            return f"= Equal diameter  {a} = {b}"
        return f"= Equal length  {L(c.seg_a)} = {L(c.seg_b)}"
    if isinstance(c, CParallel):      return f"∥ Parallel  {L(c.seg_a)} ∥ {L(c.seg_b)}"
    if isinstance(c, CCollinear):    return f"↔ Collinear  {L(c.seg_a)}, {L(c.seg_b)}"
    if isinstance(c, CSymmetric):
        ctr = L(c.center) if isinstance(c.center, Segment) else P(c.center)
        first = P(c.seg_a) if isinstance(c.seg_a, Vertex) else L(c.seg_a)
        second = P(c.seg_b) if isinstance(c.seg_b, Vertex) else L(c.seg_b)
        lines = " (lines)" if getattr(c, "lines_only", False) else ""
        return f"⇔ Symmetric{lines}  {first}, {second} about {ctr}"
    if isinstance(c, CMirrorPoint):
        axis = L(c.axis) if isinstance(c.axis, Segment) else c.axis + " axis"
        return f"⇔ Mirror  {P(c.vertex_move)}, {P(c.vertex_target)} about {axis}"
    if isinstance(c, CTangential):
        def E(entity):
            if isinstance(entity, Segment): return L(entity)
            if isinstance(entity, Circle):
                return f"C{sk.circles.index(entity)}" if entity in sk.circles else "C?"
            return f"A{sk.arcs.index(entity)}" if entity in sk.arcs else "A?"
        return f"⌒ Tangential  {E(c.entity_a)} to {E(c.entity_b)}"
    if isinstance(c, CDistance):
        def E(entity):
            if isinstance(entity, Vertex): return P(entity)
            if isinstance(entity, Segment): return L(entity)
            if isinstance(entity, Circle):
                return f"C{sk.circles.index(entity)}" if entity in sk.circles else "C?"
            return f"A{sk.arcs.index(entity)}" if entity in sk.arcs else "A?"
        if c.mode == "angle":
            head = f"∠ Angle {c.value:.2f}°" if c.driving else f"ⓘ Angle ({c.measure():.2f}°)"
        else:
            name = {"H": "Horiz. length", "V": "Vert. length"}.get(
                getattr(c, "orient", "D"), "Clearance" if c.pair in ("cc", "cs") else "Length")
            head = f"↔ {name} {c.value:.2f}" if c.driving else f"ⓘ {name} ({c.measure():.2f})"
        sep = {"vv": "–", "vs": " to ", "ss": " ∥ " if c.mode == "distance" else ", ",
               "cc": " ↔ ", "cs": " to "}[c.pair]
        return f"{head}  {E(c.a)}{sep}{E(c.b)}"
    if isinstance(c, CDimension):
        t = c.target
        if isinstance(t, Segment): return f"📏 Length {c.value:.2f}  {L(t)}"
        if isinstance(t, tuple):
            kind = {"H": "Horiz. dist", "V": "Vert. dist"}.get(c.orient, "Distance")
            return f"📏 {kind} {c.value:.2f}  {P(t[0])}–{P(t[1])}"
        if isinstance(t, Circle):
            i = sk.circles.index(t) if t in sk.circles else "?"
            sym = "⌀" if c.dim_mode == "diameter" else "R"
            return f"📏 {sym}{c.value:.2f}  Circle C{i}"
        if isinstance(t, Arc):
            i = sk.arcs.index(t) if t in sk.arcs else "?"
            return f"📏 R{c.value:.2f}  Arc A{i}"
    return type(c).__name__

# ── constraint solver ─────────────────────────────────────────────────────────
class SketchSystem:
    """Equation system of a sketch. Unknowns: x,y of every used, non-locked vertex and the
    radius of every non-locked circle. Solved with damped Gauss-Newton (minimum-norm steps,
    so geometry moves as little as possible). DOF = unknowns − rank(Jacobian)."""
    FD_H = 1e-6

    def __init__(self, sk):
        self.sk = sk
        used = self.sk.used_vertices()
        self.order = [v for v in sk.vertices if v in used]
        self.order += [v for v in used if v not in self.order]
        self.text_vertex_group = {v: group for group in sk.text_groups for v in group.vertices()}
        self.vix, self.rix, n = {}, {}, 0
        for v in self.order:
            if not v.locked and v not in self.text_vertex_group:
                self.vix[v] = n; n += 2
        self.tix = {}
        for group in sk.text_groups:
            if group.vertices():
                self.tix[group] = n; n += 2
        for c in sk.circles:
            if not c.locked: self.rix[c] = n; n += 1
        # rigid groups: per group the position of its reference centre (gx, gy) and, when it
        # has two or more points, its rotation (stored as arc length rot*L, so it is in mm)
        self.gix, self.ginfo = {}, {}
        circle_set, segment_set = set(sk.circles), set(sk.segments)
        for group in getattr(sk, "groups", []):
            pts, circles = sk.group_solver_points(group, segment_set, circle_set)
            pts = [v for v in pts if v in group.ref]
            circles = [c for c in circles if c in group.radii and c in self.rix]
            if not pts: continue
            cx = sum(group.ref[v][0] for v in pts)/len(pts)
            cy = sum(group.ref[v][1] for v in pts)/len(pts)
            local = {v: (group.ref[v][0]-cx, group.ref[v][1]-cy) for v in pts}
            L = math.sqrt(sum(x*x + y*y for x, y in local.values())/len(pts))
            rot = L > 1e-6
            self.gix[group] = n; n += 3 if rot else 2
            self.ginfo[group] = (pts, circles, local, max(L, 1.0), rot)
        self.n = n
        self.eqs = []          # (owner, row0, nrows, var indices, func)
        self.m = 0
        X0 = self.pack()
        for group, (pts, circles, local, L, rot) in self.ginfo.items():
            g = self.gix[group]
            for v in pts:
                lx, ly = local[v]
                def f(X, v=v, lx=lx, ly=ly, g=g, L=L, rot=rot):
                    x, y = self.P(v, X)
                    if rot:
                        t = X[g+2]/L; cs, sn = math.cos(t), math.sin(t)
                        return [x - (X[g] + cs*lx - sn*ly), y - (X[g+1] + sn*lx + cs*ly)]
                    return [x - (X[g] + lx), y - (X[g+1] + ly)]
                self._add(group, [v], [], f, X0=X0, extra=range(g, g+(3 if rot else 2)))
            for c in circles:
                def f(X, c=c, r0=group.radii[c]):
                    return [self.R(c, X) - r0]
                self._add(group, [], [c], f, X0=X0)
        for c in sk.constraints:
            eq = self._equations(c)
            if eq: self._add(c, *eq, X0=X0)
        for a in sk.arcs:      # implicit: both arc ends on the same radius
            def f(X, a=a):
                cx, cy = self.P(a.center, X); sx, sy = self.P(a.v_start, X)
                ex, ey = self.P(a.v_end, X)
                return [math.hypot(ex-cx, ey-cy) - math.hypot(sx-cx, sy-cy)]
            self._add(a, [a.center, a.v_start, a.v_end], [], f, X0=X0)
        for ellipse in sk.ellipses:
            def f(X, ellipse=ellipse):
                a0, a1, b0, b1 = ellipse.vertices()
                (x0, y0), (x1, y1), (u0, v0), (u1, v1) = (
                    self.P(vertex, X) for vertex in (a0, a1, b0, b1))
                cx_a, cy_a = (x0+x1)/2, (y0+y1)/2
                cx_b, cy_b = (u0+u1)/2, (v0+v1)/2
                ax, ay = x1-x0, y1-y0
                bx, by = u1-u0, v1-v0
                scale = math.hypot(ax, ay)*math.hypot(bx, by)
                perpendicular = (ax*bx+ay*by)/scale if scale > 1e-18 else 0.0
                return [cx_a-cx_b, cy_a-cy_b, perpendicular]
            self._add(ellipse, ellipse.vertices(), [], f, X0=X0)

    def _add(self, owner, verts, circles, f, X0, extra=()):
        idx = []
        for v in verts:
            i = self.vix.get(v)
            if i is None:
                group = self.text_vertex_group.get(v)
                i = self.tix.get(group)
            if i is not None and i not in idx: idx += [i, i+1]
        for c in circles:
            i = self.rix.get(c)
            if i is not None: idx.append(i)
        idx += [j for j in extra if j not in idx]
        nrows = len(f(X0))
        self.eqs.append((owner, self.m, nrows, idx, f)); self.m += nrows

    def P(self, v, X):
        i = self.vix.get(v)
        if i is not None:
            return X[i], X[i+1]
        group = self.text_vertex_group.get(v)
        if group is not None:
            i = self.tix[group]
            return v.x + X[i], v.y + X[i+1]
        return v.x, v.y

    def R(self, c, X):
        i = self.rix.get(c)
        return X[i] if i is not None else c.radius

    def _equations(self, c):
        P, R = self.P, self.R
        if isinstance(c, CFixed):
            v = c.vertex
            def f(X):
                x, y = P(v, X); return [x-c.x0, y-c.y0]
            return [v], [], f
        if isinstance(c, CCoincident):
            a, b = c.vertex_move, c.vertex_target
            def f(X):
                (ax, ay), (bx, by) = P(a, X), P(b, X); return [ax-bx, ay-by]
            return [a, b], [], f
        if isinstance(c, (CHorizontal, CVertical)):
            a, b = c.seg.v0, c.seg.v1; k = 1 if isinstance(c, CHorizontal) else 0
            def f(X):
                return [P(b, X)[k] - P(a, X)[k]]
            return [a, b], [], f
        if isinstance(c, CPerpendicular):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (p, q), (r, s) = P(a0, X), P(a1, X); (t, u), (w, z) = P(b0, X), P(b1, X)
                dax, day, dbx, dby = r-p, s-q, w-t, z-u
                la, lb = math.hypot(dax, day), math.hypot(dbx, dby)
                if la < 1e-9 or lb < 1e-9: return [0.0]
                return [(dax*dbx + day*dby)/(la*lb)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CPointOnLine):
            a, b, v = c.seg.v0, c.seg.v1, c.vertex
            def f(X):
                (ax, ay), (bx, by), (px, py) = P(a, X), P(b, X), P(v, X)
                dx, dy = bx-ax, by-ay; L = math.hypot(dx, dy)
                if L < 1e-9: return [0.0]
                return [(dx*(py-ay) - dy*(px-ax))/L]
            return [a, b, v], [], f
        if isinstance(c, CPointOnCurve):
            v, cu = c.vertex, c.curve
            if isinstance(cu, Circle):
                def f(X):
                    (cx, cy), (px, py) = P(cu.center, X), P(v, X)
                    return [math.hypot(px-cx, py-cy) - R(cu, X)]
                return [cu.center, v], [cu], f
            def f(X):
                (cx, cy), (sx, sy), (px, py) = P(cu.center, X), P(cu.v_start, X), P(v, X)
                return [math.hypot(px-cx, py-cy) - math.hypot(sx-cx, sy-cy)]
            return [cu.center, cu.v_start, v], [], f
        if isinstance(c, CDimension):
            t = c.target
            if isinstance(t, Segment) or isinstance(t, tuple):
                a, b = (t.v0, t.v1) if isinstance(t, Segment) else t
                orient = c.orient if isinstance(t, tuple) else None
                def f(X):
                    (ax, ay), (bx, by) = P(a, X), P(b, X)
                    if orient == "H": return [(bx-ax)*c.sign - c.value]
                    if orient == "V": return [(by-ay)*c.sign - c.value]
                    return [math.hypot(bx-ax, by-ay) - c.value]
                return [a, b], [], f
            if isinstance(t, Circle):
                def f(X):
                    target = c.value/2 if c.dim_mode == "diameter" else c.value
                    return [R(t, X) - target]
                return [], [t], f
            if isinstance(t, Arc):
                def f(X):
                    (cx, cy), (sx, sy) = P(t.center, X), P(t.v_start, X)
                    return [math.hypot(sx-cx, sy-cy) - c.value]
                return [t.center, t.v_start], [], f
        if isinstance(c, CDistance):
            if not c.driving: return None
            a, b = c.a, c.b
            if c.pair == "cc":
                if c.circle_relation == "concentric":
                    inner = b if c.circle_outer is a else a
                    def f(X):
                        return [R(c.circle_outer, X) - R(inner, X) - c.value*c.sign]
                    return [], [a, b], f
                def f(X):
                    (ax, ay), (bx, by) = P(a.center, X), P(b.center, X)
                    center_distance = math.sqrt((bx-ax)**2 + (by-ay)**2 + 1e-18)
                    if c.circle_relation == "center":
                        return [center_distance - c.value*c.sign]
                    if c.circle_relation == "nested":
                        inner = b if c.circle_outer is a else a
                        return [R(c.circle_outer, X) - R(inner, X) -
                                center_distance - c.value*c.sign]
                    return [center_distance - R(a, X) - R(b, X) - c.value*c.sign]
                return [a.center, b.center], [] if c.circle_relation == "center" else [a, b], f
            if c.pair == "cs":
                def f(X):
                    distance = _signed_line_dist(P(b.v0, X), P(b.v1, X), P(a.center, X))
                    return [distance*c.circle_side - R(a, X) - c.value*c.sign]
                return [a.center, b.v0, b.v1], [a], f
            verts = [a] if isinstance(a, Vertex) else [a.v0, a.v1]
            verts += [b] if isinstance(b, Vertex) else [b.v0, b.v1]
            if c.pair == "ss" and c.mode == "distance":
                    def f(X):
                        Pv = lambda v: P(v, X)
                        a0, a1, b0, b1 = Pv(a.v0), Pv(a.v1), Pv(b.v0), Pv(b.v1)
                        ang = _line_angle(a0, a1, b0, b1)
                        return [math.sin(ang),                       # parallel (or anti-parallel)
                                _signed_line_dist(a0, a1, b.midpoint_of(Pv))*c.sign - c.value]
                    return verts, [], f
            if c.pair == "ss":
                    def f(X):
                        Pv = lambda v: P(v, X)
                        sides = getattr(c, "angle_sides", None)
                        if sides is not None:
                            ax, ay = Pv(a.v1)[0]-Pv(a.v0)[0], Pv(a.v1)[1]-Pv(a.v0)[1]
                            bx, by = Pv(b.v1)[0]-Pv(b.v0)[0], Pv(b.v1)[1]-Pv(b.v0)[1]
                            angle = _line_angle((0.0, 0.0), (ax*sides[0], ay*sides[0]),
                                                (0.0, 0.0), (bx*sides[1], by*sides[1]))
                            d = angle - math.radians(c.value)*c.sign
                            return [math.atan2(math.sin(d), math.cos(d))]
                        d = _line_angle(Pv(a.v0), Pv(a.v1), Pv(b.v0), Pv(b.v1)) \
                            - math.radians(c.value)
                        return [0.5*math.atan2(math.sin(2*d), math.cos(2*d))]
                    return verts, [], f
            def f(X):
                    m = c.measure_signed(lambda v: P(v, X))
                    return [m*c.sign - c.value]
            return verts, [], f
        if isinstance(c, CEqual):
            if isinstance(c.seg_a, Circle) and isinstance(c.seg_b, Circle):
                def f(X):
                    return [R(c.seg_a, X) - R(c.seg_b, X)]
                return [], [c.seg_a, c.seg_b], f
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                return [math.hypot(bx-ax, by-ay) - math.hypot(dx-cx, dy-cy)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CParallel):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                return [(bx-ax)*(dy-cy) - (by-ay)*(dx-cx)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CCollinear):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                ux, uy = bx-ax, by-ay
                vx, vy = dx-cx, dy-cy
                length = math.hypot(ux, uy)
                other_length = math.hypot(vx, vy)
                if length < 1e-9 or other_length < 1e-9: return [0.0, 0.0]
                return [(ux*vy-uy*vx)/(length*other_length),
                        (ux*(cy-ay)-uy*(cx-ax))/length]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CTangential):
            a, b = c.entity_a, c.entity_b
            if isinstance(a, Segment) or isinstance(b, Segment):
                line = a if isinstance(a, Segment) else b
                curve = b if line is a else a
                if isinstance(curve, Segment): return None
                def radius(X):
                    if isinstance(curve, Circle): return R(curve, X)
                    (cx, cy), (sx, sy) = P(curve.center, X), P(curve.v_start, X)
                    return math.hypot(sx-cx, sy-cy)
                def f(X):
                    center = P(curve.center, X)
                    distance = _signed_line_dist(P(line.v0, X), P(line.v1, X), center)
                    return [distance - c.side*radius(X)]
                verts = [line.v0, line.v1, curve.center]
                circles = [curve] if isinstance(curve, Circle) else []
                if isinstance(curve, Arc): verts.append(curve.v_start)
                return verts, circles, f
            def radius(curve, X):
                if isinstance(curve, Circle): return R(curve, X)
                (cx, cy), (sx, sy) = P(curve.center, X), P(curve.v_start, X)
                return math.hypot(sx-cx, sy-cy)
            def f(X):
                (ax, ay), (bx, by) = P(a.center, X), P(b.center, X)
                distance = math.sqrt((bx-ax)**2 + (by-ay)**2 + 1e-18)
                ra, rb = radius(a, X), radius(b, X)
                target = ra + rb if c.external else c.side*(ra-rb)
                return [distance-target]
            verts = [a.center, b.center]
            circles = []
            for curve in (a, b):
                if isinstance(curve, Circle): circles.append(curve)
                else: verts.append(curve.v_start)
            return verts, circles, f
        if isinstance(c, CSymmetric):
            a0, a1 = (c.seg_a, c.seg_a) if isinstance(c.seg_a, Vertex) else (c.seg_a.v0, c.seg_a.v1)
            b0, b1 = (c.seg_b, c.seg_b) if isinstance(c.seg_b, Vertex) else (c.seg_b.v0, c.seg_b.v1)
            if symmetric_lines_only(c):
                center = c.center
                def f(X):
                    return [symmetric_line_residual(c, lambda v: P(v, X))]
                verts = [a0, a1, b0, b1] + ([center.v0, center.v1] if isinstance(center, Segment)
                                            else [center])
                return verts, [], f
            if isinstance(c.center, Segment):
                cv0, cv1 = c.center.v0, c.center.v1
                def f(X):
                    ma = ((P(a0,X)[0]+P(a1,X)[0])/2, (P(a0,X)[1]+P(a1,X)[1])/2)
                    mb = ((P(b0,X)[0]+P(b1,X)[0])/2, (P(b0,X)[1]+P(b1,X)[1])/2)
                    da = _signed_line_dist(P(cv0,X), P(cv1,X), ma)
                    db = _signed_line_dist(P(cv0,X), P(cv1,X), mb)
                    (lx,ly),(rx,ry) = P(cv0,X), P(cv1,X)
                    dx2,dy2 = rx-lx, ry-ly; L2 = dx2*dx2+dy2*dy2 or 1e-12
                    ta = ((ma[0]-lx)*dx2+(ma[1]-ly)*dy2)/L2
                    tb = ((mb[0]-lx)*dx2+(mb[1]-ly)*dy2)/L2
                    return [da + db, ta - tb]
                return [a0, a1, b0, b1, cv0, cv1], [], f
            else:
                cv = c.center
                def f(X):
                    ma = ((P(a0,X)[0]+P(a1,X)[0])/2, (P(a0,X)[1]+P(a1,X)[1])/2)
                    mb = ((P(b0,X)[0]+P(b1,X)[0])/2, (P(b0,X)[1]+P(b1,X)[1])/2)
                    cx2, cy2 = P(cv, X)
                    return [(ma[0]+mb[0])/2 - cx2, (ma[1]+mb[1])/2 - cy2]
                return [a0, a1, b0, b1, cv], [], f
        if isinstance(c, CMirrorPoint):
            source, mirror = c.vertex_move, c.vertex_target
            if isinstance(c.axis, Segment):
                a, b = c.axis.v0, c.axis.v1
                def f(X):
                    (x, y), (mx, my) = P(source, X), P(mirror, X)
                    (ax, ay), (bx, by) = P(a, X), P(b, X)
                    dx, dy = bx-ax, by-ay
                    length2 = dx*dx + dy*dy
                    if length2 < 1e-18:
                        return [1.0, 1.0]
                    t = ((x-ax)*dx + (y-ay)*dy) / length2
                    return [mx - (2*(ax+t*dx)-x), my - (2*(ay+t*dy)-y)]
                return [source, mirror, a, b], [], f
            def f(X):
                (x, y), (mx, my) = P(source, X), P(mirror, X)
                return [mx-x, my+y] if c.axis == "horizontal" else [mx+x, my-y]
            return [source, mirror], [], f
        return None

    # ── state vector ─────────────────────────────────────────────────────────
    def pack(self):
        X = [0.0]*self.n
        for v, i in self.vix.items(): X[i] = v.x; X[i+1] = v.y
        for c, i in self.rix.items(): X[i] = c.radius
        for group, i in self.gix.items():
            # best-fit rigid placement of the reference shape onto the current points
            pts, _, local, L, rot = self.ginfo[group]
            cur = [self.P(v, X) for v in pts]
            mx = sum(p[0] for p in cur)/len(cur); my = sum(p[1] for p in cur)/len(cur)
            X[i] = mx; X[i+1] = my
            if rot:
                s_dot = s_cross = 0.0
                for v, (x, y) in zip(pts, cur):
                    lx, ly = local[v]; bx, by = x-mx, y-my
                    s_dot += lx*bx + ly*by; s_cross += lx*by - ly*bx
                X[i+2] = math.atan2(s_cross, s_dot)*L
        return X

    def unpack(self, X):
        for v, i in self.vix.items(): v.x = float(X[i]); v.y = float(X[i+1])
        for group, i in self.tix.items():
            dx, dy = float(X[i]), float(X[i+1])
            if dx or dy:
                for v in group.vertices():
                    v.x += dx; v.y += dy
        for c, i in self.rix.items(): c.radius = float(X[i])

    def indices_of(self, verts):
        idx = []
        for v in verts:
            i = self.vix.get(v)
            if i is None:
                i = self.tix.get(self.text_vertex_group.get(v))
            if i is not None and i not in idx: idx += [i, i+1]
        return idx

    def rows_of(self, owner):
        return [r for o, r0, nr, _, _ in self.eqs if o is owner for r in range(r0, r0+nr)]

    # ── numerics ─────────────────────────────────────────────────────────────
    def residuals(self, X):
        r = []
        for _, _, _, _, f in self.eqs: r += f(X)
        return np.array(r, dtype=float)

    def jacobian(self, X):
        X = list(X); h = self.FD_H
        J = np.zeros((self.m, self.n))
        for _, r0, nr, idx, f in self.eqs:
            for j in idx:
                old = X[j]
                X[j] = old + h; fp = f(X)
                X[j] = old - h; fm = f(X)
                X[j] = old
                for k in range(nr): J[r0+k, j] = (fp[k]-fm[k])/(2*h)
        return J

    @staticmethod
    def _rank_tol(S):
        return 1e-5*max(1.0, float(S[0])) if len(S) else 1.0

    def rank(self, J=None):
        if J is None: J = self.jacobian(self.pack())
        if J.size == 0: return 0
        S = np.linalg.svd(J, compute_uv=False)
        return int((S > self._rank_tol(S)).sum())

    def solve(self, X, lock=(), heavy=()):
        """Gauss-Newton with backtracking. Variables in `lock` stay put; variables in `heavy`
        are weighted so they move as little as possible. Returns (ok, X)."""
        X = list(X)
        if self.m == 0: return True, X
        lockset, heavyset = set(lock), set(heavy)
        free = [j for j in range(self.n) if j not in lockset]
        wts = np.array([1e3 if j in heavyset else 1.0 for j in free])
        r = self.residuals(X)
        for _ in range(60):
            if np.abs(r).max() < 1e-9: return True, X
            if not free: break
            J = self.jacobian(X)[:, free] / wts
            dx = np.linalg.lstsq(J, -r, rcond=None)[0] / wts
            nr = np.linalg.norm(r); step = 1.0; improved = False
            for _ in range(12):
                Xn = list(X)
                for k, j in enumerate(free): Xn[j] += step*dx[k]
                rn = self.residuals(Xn)
                if np.linalg.norm(rn) < nr:
                    X, r, improved = Xn, rn, True; break
                step *= 0.5
            if not improved: break
        return bool(np.abs(r).max() < 1e-6), X

    def analyse(self):
        """DOF and which vertices / circles are fully determined."""
        locked = {v for v in self.order if v.locked}
        if self.n == 0:
            return {"dof": 0, "dof_all": 0, "det_v": set(self.order), "det_c": set(self.sk.circles)}
        J = self.jacobian(self.pack())
        if J.shape[0]:
            _, S, Vt = np.linalg.svd(J)
            rank = int((S > self._rank_tol(S)).sum())
            N = Vt[rank:]
        else:
            rank, N = 0, np.eye(self.n)
        def det(cols):
            return N.shape[0] == 0 or float(np.abs(N[:, cols]).max()) < 1e-4
        det_v = set(locked)
        for v, i in self.vix.items():
            if det([i, i+1]): det_v.add(v)
        det_c = set()
        for c in self.sk.circles:
            i = self.rix.get(c)
            if c.center in det_v and (i is None or det([i])): det_c.add(c)
        # only profile geometry must be constrained; support geometry and points are optional
        mand = set()
        for s in self.sk.segments:
            if not s.construction: mand |= {s.v0, s.v1}
        for a in self.sk.arcs:
            if not a.construction: mand |= {a.center, a.v_start, a.v_end}
        for ellipse in self.sk.ellipses:
            if not ellipse.construction: mand.update(ellipse.vertices())
        cols = []
        for c in self.sk.circles:
            if not c.construction:
                mand.add(c.center)
                if c in self.rix: cols.append(self.rix[c])
        for v in mand:
            if v in self.vix: cols += [self.vix[v], self.vix[v]+1]
        if cols and N.shape[0]:
            sub = N[:, sorted(cols)]
            Ss = np.linalg.svd(sub, compute_uv=False)
            dof_req = int((Ss > 1e-6).sum())
        else:
            dof_req = 0
        return {"dof": dof_req, "dof_all": self.n - rank, "det_v": det_v, "det_c": det_c}

def solve_sketch(sk):
    """Solve all constraints in place. Returns True when every equation is satisfied."""
    return sk.solve()

# ── sketch ────────────────────────────────────────────────────────────────────
def plane_frame(plane):
    """(origin, u, v, w) — sketch x/y axes and extrusion direction of a base plane."""
    e = np.eye(3); ax, ay, az = PLANE_AXES[plane]
    return (np.zeros(3), e[ax].copy(), e[ay].copy(), e[az].copy())

def rotated_face_frame(frame, rotation):
    origin, u, v, normal = (np.asarray(a, float) for a in frame)
    cosine, sine = rotation
    return origin, cosine*u+sine*v, -sine*u+cosine*v, normal

class FaceOutlineChanged(ValueError):
    """A face outline gained or lost edges: sketch references are rebuilt, not moved."""

def face_reference_sketch(face, frame):
    """Create fixed face outlines with stable links to their boundary primitives."""
    sk = Sketch("Face", frame=frame)
    origin, u, v, normal = sk.frame
    def vertex(point):
        delta = np.asarray(point, dtype=float) - origin
        xy = (float(delta @ u), float(delta @ v))
        existing = next((item for item in sk.vertices if math.dist(item.xy(), xy) < 1e-6),
                        None)
        if existing is None:
            existing = Vertex(*xy, locked=True)
            sk.vertices.append(existing)
        return existing
    for index, primitive in enumerate(face.get("boundary", [])):
        if primitive[0] == "line":
            a, b = vertex(primitive[1]), vertex(primitive[2])
            if a is b:
                continue
            element = Segment(a, b, reference=True)
            sk.segments.append(element)
        elif primitive[0] == "circle":
            element = Circle(vertex(primitive[1]), primitive[2], reference=True)
            sk.circles.append(element)
        elif primitive[0] == "arc":
            _, center, start, end, axis = primitive
            if float(np.dot(axis, normal)) < 0:
                start, end = end, start
            element = Arc(vertex(center), vertex(start), vertex(end), reference=True)
            sk.arcs.append(element)
        else:
            continue
        element.reference_boundary = index
    return sk

def _tag_reference_source(element, source, kind, index):
    """Remember which source-sketch element a projected reference was made from, so a later
    refresh moves this reference (and everything constrained to it) instead of replacing it."""
    if index is not None:
        element.reference_source = (str(source.name), kind, int(index))

def project_sketch_segments(source, target):
    """Add source sketch lines to a face sketch as fixed reference segments."""
    origin, axis_u, axis_v, _ = (np.asarray(axis, float) for axis in target.frame)
    def project(vertex):
        point = np.asarray(source.to3d(vertex.xy()), dtype=float) - origin
        return float(point @ axis_u), float(point @ axis_v)

    boundary = [segment for segment in target.segments if segment.reference]
    boundary_a = np.asarray([segment.v0.xy() for segment in boundary], dtype=float).reshape(-1, 2)
    boundary_b = np.asarray([segment.v1.xy() for segment in boundary], dtype=float).reshape(-1, 2)
    mapped_vertices = {}
    vertex_index = {vertex: i for i, vertex in enumerate(source.vertices)}
    for segment_index, segment in enumerate(source.segments):
        if segment.reference:
            continue
        a, b = project(segment.v0), project(segment.v1)
        if math.dist(a, b) < 1e-6:
            continue
        samples = [((1.0 - t) * np.asarray(a) + t * np.asarray(b))
                   for t in (0.0, 0.25, 0.5, 0.75, 1.0)]
        if boundary and all(min_seg_dist(point, boundary_a, boundary_b) < 1e-5
                            for point in samples):
            continue
        va = mapped_vertices.get(segment.v0)
        if va is None:
            va = Vertex(*a, locked=True)
            _tag_reference_source(va, source, "v", vertex_index.get(segment.v0))
            mapped_vertices[segment.v0] = va
            target.vertices.append(va)
        vb = mapped_vertices.get(segment.v1)
        if vb is None:
            vb = Vertex(*b, locked=True)
            _tag_reference_source(vb, source, "v", vertex_index.get(segment.v1))
            mapped_vertices[segment.v1] = vb
            target.vertices.append(vb)
        if va is not vb:
            projected = Segment(va, vb, reference=True)
            _tag_reference_source(projected, source, "s", segment_index)
            target.segments.append(projected)

def project_sketch_points(source, target):
    """Project standalone source points into a face sketch as fixed reference points."""
    origin, axis_u, axis_v, _ = (np.asarray(axis, float) for axis in target.frame)
    projected = 0
    vertex_index = {vertex: i for i, vertex in enumerate(source.vertices)}
    for point in source.points_free:
        if point.locked:
            continue
        delta = np.asarray(source.to3d(point.xy()), dtype=float) - origin
        xy = (float(delta @ axis_u), float(delta @ axis_v))
        existing = next((vertex for vertex in target.vertices
                         if vertex.locked and math.dist(vertex.xy(), xy) < 1e-6), None)
        if existing is not None:
            if existing not in target.points_free:
                target.points_free.append(existing)
                projected += 1
            continue
        vertex = Vertex(*xy, locked=True)
        _tag_reference_source(vertex, source, "v", vertex_index.get(point))
        target.vertices.append(vertex)
        target.points_free.append(vertex)
        projected += 1
    return projected

def project_sketch_circles(source, target):
    """Project parallel source-sketch circles into a face sketch as fixed references."""
    source_normal = np.asarray(source.frame[3], dtype=float)
    target_origin, axis_u, axis_v, target_normal = (
        np.asarray(axis, dtype=float) for axis in target.frame)
    if abs(float(source_normal @ target_normal)) < 1.0 - 1e-6:
        return
    vertex_index = {vertex: i for i, vertex in enumerate(source.vertices)}
    for circle_index, circle in enumerate(source.circles):
        if circle.reference:
            continue
        center = np.asarray(source.to3d(circle.center.xy()), dtype=float) - target_origin
        xy = (float(center @ axis_u), float(center @ axis_v))
        if any(existing.reference and
               math.dist(existing.center.xy(), xy) < 1e-5 and
               abs(existing.radius - circle.radius) < 1e-5
               for existing in target.circles):
            continue
        vertex = next((v for v in target.vertices
                       if v.locked and math.dist(v.xy(), xy) < 1e-6), None)
        if vertex is None:
            vertex = Vertex(*xy, locked=True)
            _tag_reference_source(vertex, source, "v", vertex_index.get(circle.center))
            target.vertices.append(vertex)
        projected = Circle(vertex, circle.radius, reference=True)
        _tag_reference_source(projected, source, "c", circle_index)
        target.circles.append(projected)

def project_sketch_curves(source, target):
    """Project source arcs and non-parallel circles as fixed polylines."""
    origin, axis_u, axis_v, target_normal = (
        np.asarray(axis, dtype=float) for axis in target.frame)
    source_normal = np.asarray(source.frame[3], dtype=float)
    parallel_planes = abs(float(source_normal @ target_normal)) >= 1.0 - 1e-6

    def project(points):
        world = source.to3d_many(points)
        relative = world - origin
        return np.column_stack((relative @ axis_u, relative @ axis_v))

    mapped_vertices = {}

    def vertex(xy):
        key = (round(float(xy[0]), 8), round(float(xy[1]), 8))
        result = mapped_vertices.get(key)
        if result is None:
            result = Vertex(*key, locked=True)
            mapped_vertices[key] = result
            target.vertices.append(result)
        return result

    curves = [(arc.tess(), False) for arc in source.arcs if not arc.reference]
    curves.extend((ellipse.tess(), True) for ellipse in source.ellipses
                  if not ellipse.reference)
    if not parallel_planes:
        curves.extend((circle_pts(circle.center.x, circle.center.y, circle.radius), True)
                      for circle in source.circles if not circle.reference)
    added = 0
    for points, closed in curves:
        projected = project(points)
        if len(projected) < 2:
            continue
        pairs = zip(projected, np.roll(projected, -1, axis=0)) if closed else \
            zip(projected[:-1], projected[1:])
        for start, end in pairs:
            if float(np.linalg.norm(end - start)) < 1e-6:
                continue
            a, b = vertex(start), vertex(end)
            if a is b or any(
                    (math.dist(existing.v0.xy(), a.xy()) < 1e-6 and
                     math.dist(existing.v1.xy(), b.xy()) < 1e-6) or
                    (math.dist(existing.v0.xy(), b.xy()) < 1e-6 and
                     math.dist(existing.v1.xy(), a.xy()) < 1e-6)
                    for existing in target.segments):
                continue
            target.segments.append(Segment(a, b, reference=True))
            added += 1
    return added

def datum_surface_frame(base_frame, offset, rotation):
    """Apply local XYZ offsets and X-then-Y-then-Z rotations to a reference frame."""
    origin, u, v, normal = (np.asarray(axis, float) for axis in base_frame)
    basis = np.column_stack((u, v, normal))
    x, y, z = np.radians(np.asarray(rotation, dtype=float))
    cx, sx = math.cos(x), math.sin(x)
    cy, sy = math.cos(y), math.sin(y)
    cz, sz = math.cos(z), math.sin(z)
    rx = np.array([[1, 0, 0], [0, cx, -sx], [0, sx, cx]])
    ry = np.array([[cy, 0, sy], [0, 1, 0], [-sy, 0, cy]])
    rz = np.array([[cz, -sz, 0], [sz, cz, 0], [0, 0, 1]])
    transformed = basis @ (rz @ ry @ rx)
    placed_origin = origin + basis @ np.asarray(offset, dtype=float)
    return (placed_origin, transformed[:, 0], transformed[:, 1], transformed[:, 2])

def tangent_face_frame(entry, face_index):
    """Build an automatic tangent frame at the highest vertex of a curved mesh face."""
    faces = entry.get("faces", [])
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces):
        raise ValueError("The curved reference face is no longer available.")
    face = faces[face_index]
    if face.get("planar") or not face.get("tris"):
        raise ValueError("Choose a curved face for automatic tangent placement.")
    solid = entry.get("solid")
    if not isinstance(solid, (tuple, list)) or len(solid) != 2:
        raise ValueError("The curved reference face has no usable mesh.")
    vertices, triangles = solid
    points = np.asarray(vertices, dtype=float)
    tris = np.asarray(triangles, dtype=int).reshape(-1, 3)
    face_triangle_ids = np.asarray(face["tris"], dtype=int)
    if not len(points) or not len(face_triangle_ids) or \
            np.any(face_triangle_ids < 0) or np.any(face_triangle_ids >= len(tris)):
        raise ValueError("The curved reference face has no usable mesh.")
    face_triangles = tris[face_triangle_ids]
    if np.any(face_triangles < 0) or np.any(face_triangles >= len(points)) or \
            not np.isfinite(points).all():
        raise ValueError("The curved reference face has no usable mesh.")

    face_vertex_ids = np.unique(face_triangles)
    highest_z = float(points[face_vertex_ids, 2].max())
    tolerance = max(1e-8, float(np.ptp(points[face_vertex_ids, 2])) * 1e-8)
    candidates = face_vertex_ids[
        points[face_vertex_ids, 2] >= highest_z - tolerance]
    mesh_center = points.mean(axis=0)
    triangle_normals = np.cross(
        points[face_triangles[:, 1]] - points[face_triangles[:, 0]],
        points[face_triangles[:, 2]] - points[face_triangles[:, 0]])
    triangle_centers = points[face_triangles].mean(axis=1)
    inward = np.einsum("ij,ij->i", triangle_normals, triangle_centers-mesh_center) < 0
    triangle_normals[inward] *= -1

    candidates_with_normals = []
    for vertex_id in candidates:
        incident = np.any(face_triangles == vertex_id, axis=1)
        normal = triangle_normals[incident].sum(axis=0)
        length = float(np.linalg.norm(normal))
        if length > 1e-12:
            normal /= length
            candidates_with_normals.append((vertex_id, normal))
    if not candidates_with_normals:
        raise ValueError("Could not determine a tangent direction for the curved face.")
    vertex_id, normal = max(
        candidates_with_normals,
        key=lambda item: (float(item[1][2]), -int(item[0])))
    origin = points[vertex_id]

    reference = np.array([0.0, 0.0, 1.0])
    if abs(float(reference @ normal)) > 0.95:
        reference = np.array([0.0, 1.0, 0.0])
    axis_u = _unit(np.cross(reference, normal))
    axis_v = _unit(np.cross(normal, axis_u))
    return origin, axis_u, axis_v, normal

def _fit_curved_surface(entry, face_index):
    if not isinstance(entry, dict):
        return None
    faces = entry.get("faces", [])
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces):
        return None
    face = faces[face_index]
    solid = entry.get("solid")
    if face.get("planar") or not face.get("tris") or \
            not isinstance(solid, (tuple, list)) or len(solid) != 2:
        return None
    vertices, triangles = solid
    points = np.asarray(vertices, dtype=float)
    tris = np.asarray(triangles, dtype=int).reshape(-1, 3)
    tri_ids = np.asarray(face["tris"], dtype=int)
    if not len(tri_ids) or np.any(tri_ids < 0) or np.any(tri_ids >= len(tris)):
        return None
    face_tris = tris[tri_ids]
    if np.any(face_tris < 0) or np.any(face_tris >= len(points)) or \
            not np.isfinite(points).all():
        return None
    face_points = points[np.unique(face_tris)]
    if len(face_points) < 6:
        return None
    triangle_points = points[face_tris]
    normals = np.cross(triangle_points[:, 1] - triangle_points[:, 0],
                       triangle_points[:, 2] - triangle_points[:, 0])
    normal_lengths = np.linalg.norm(normals, axis=1)
    normals = normals[normal_lengths > 1e-12] / normal_lengths[normal_lengths > 1e-12, None]
    cylinder_axis = None
    if len(normals) >= 3:
        normal_eigenvalues, normal_eigenvectors = np.linalg.eigh(
            normals.T @ normals / len(normals))
        if normal_eigenvalues[-1] > 1e-9 and \
                normal_eigenvalues[0] / normal_eigenvalues[-1] <= 0.08:
            cylinder_axis = normal_eigenvectors[:, 0]

    surface_type = str(face.get("surface_type", "")).upper()
    # A least-squares sphere fit makes the controls independent of mesh orientation.
    sphere_matrix = np.column_stack((2.0 * face_points, np.ones(len(face_points))))
    sphere_rhs = np.einsum("ij,ij->i", face_points, face_points)
    sphere_fit, _, sphere_rank, _ = np.linalg.lstsq(sphere_matrix, sphere_rhs, rcond=None)
    if sphere_rank == 4:
        sphere_center = sphere_fit[:3]
        sphere_radius = math.sqrt(max(0.0, float(sphere_fit[3] + sphere_center @ sphere_center)))
        sphere_error = float(np.sqrt(np.mean(
            (np.linalg.norm(face_points - sphere_center, axis=1) - sphere_radius) ** 2)))
        if (surface_type == "SPHERE" or
                (surface_type != "CYLINDER" and cylinder_axis is None)) and \
                sphere_radius > 1e-9 and \
                sphere_error <= max(1e-5, sphere_radius * 0.01):
            return "sphere", sphere_center, sphere_radius

    # Cylinder normals share one zero-variance direction: the cylinder axis.
    if cylinder_axis is None:
        return None
    axis = cylinder_axis
    major = int(np.argmax(np.abs(axis)))
    if axis[major] < 0:
        axis = -axis
    reference = np.array((0.0, 0.0, 1.0))
    radial_u = reference - float(reference @ axis) * axis
    if float(np.linalg.norm(radial_u)) < 1e-8:
        reference = np.array((1.0, 0.0, 0.0))
        radial_u = reference - float(reference @ axis) * axis
    radial_u = _unit(radial_u)
    radial_v = _unit(np.cross(axis, radial_u))
    x, y = face_points @ radial_u, face_points @ radial_v
    circle_matrix = np.column_stack((2.0 * x, 2.0 * y, np.ones(len(x))))
    circle_fit, _, circle_rank, _ = np.linalg.lstsq(
        circle_matrix, x * x + y * y, rcond=None)
    if circle_rank < 3:
        return None
    center_u, center_v, constant = circle_fit
    radius = math.sqrt(max(0.0, float(constant + center_u**2 + center_v**2)))
    radial_error = float(np.sqrt(np.mean(
        (np.hypot(x - center_u, y - center_v) - radius) ** 2)))
    if radius <= 1e-9 or radial_error > max(1e-5, radius * 0.02):
        return None
    face_axial = face_points @ axis
    solid_axial = points @ axis
    axial_center = float((solid_axial.min() + solid_axial.max()) / 2.0)
    axial_limits = (float(face_axial.min() - axial_center),
                    float(face_axial.max() - axial_center))
    center = center_u * radial_u + center_v * radial_v + axial_center * axis
    axial_default = axial_limits[1] if axis[2] > 1e-8 else \
        axial_limits[0] if axis[2] < -1e-8 else 0.0
    return ("cylinder", center, axis, radial_u, radial_v, radius,
            axial_limits, (0.0, axial_default))

def curved_surface_frame(entry, face_index, position=None):
    """Return a positioned tangent frame and shape metadata for spherical/cylindrical mesh faces."""
    if not isinstance(entry, dict):
        return None
    faces = entry.get("faces", [])
    solid = entry.get("solid")
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces) or \
            not isinstance(solid, (tuple, list)) or len(solid) != 2:
        return None
    cache = entry.setdefault("_curved_surface_cache", {})
    cached = cache.get(face_index)
    face = faces[face_index]
    if cached is not None and cached[0] is solid[0] and \
            cached[1] is solid[1] and cached[2] is face:
        definition = cached[3]
    else:
        definition = _fit_curved_surface(entry, face_index)
        cache[face_index] = (solid[0], solid[1], face, definition)
    if definition is None:
        return None

    if position is not None:
        position = np.asarray(position, dtype=float)
        if position.shape != (2,) or not np.isfinite(position).all():
            raise ValueError("Tangent position values must be finite numbers.")
    shape = definition[0]
    if shape == "sphere":
        _, center, radius = definition
        limits, default_position = (-90.0, 90.0), (0.0, 90.0)
        azimuth, elevation = np.radians(default_position if position is None else position)
        normal = np.array((math.cos(elevation) * math.cos(azimuth),
                           math.cos(elevation) * math.sin(azimuth),
                           math.sin(elevation)))
        axis_u = np.array((-math.sin(azimuth), math.cos(azimuth), 0.0))
        axis_v = _unit(np.cross(normal, axis_u))
        frame = (center + radius * normal, axis_u, axis_v, normal)
        return frame, shape, limits, default_position
    _, center, axis, radial_u, radial_v, radius, limits, default_position = definition
    _, center, axis, radial_u, radial_v, radius, limits, default_position = definition
    if position is None:
        position = default_position
    angle = math.radians(float(position[0]))
    axial_position = float(position[1])
    normal = math.cos(angle) * radial_u + math.sin(angle) * radial_v
    axis_u = axis
    axis_v = _unit(np.cross(normal, axis_u))
    frame = (center + axial_position * axis + radius * normal,
             axis_u, axis_v, normal)
    return frame, shape, limits, default_position

class Sketch:
    _ctr = [0]
    def __init__(self, plane, name=None, frame=None):
        Sketch._ctr[0] += 1
        self.name        = name or f"sketch{Sketch._ctr[0]:02d}"
        self.plane       = plane          # "XY"/"XZ"/"YZ", "Face" or a datum "Surface"
        self.frame       = tuple(np.asarray(a, float) for a in frame) if frame is not None \
                           else plane_frame(plane)
        self.face_rotation = (1.0, 0.0)
        self.vertices    = []
        self.segments    = []
        self.circles     = []
        self.arcs        = []
        self.ellipses    = []
        self.points_free = []   # standalone sketch points (e.g. created by Point-on-Line)
        self.reference_generated_levels = []
        self.legacy_reference_levels = False
        self.text_groups = []
        self.groups      = []   # rigid SketchGroups (Group / Ungroup in Select mode)
        self.constraints = []
        self._an_key = None; self._an = None

    # ── rigid groups ─────────────────────────────────────────────────────────
    def group_for(self, element):
        """The rigid group containing element (segment / circle / arc / ellipse / vertex)."""
        return next((g for g in getattr(self, "groups", []) if g.contains(element)), None)

    def group_solver_points(self, group, segment_set=None, circle_set=None):
        """(points, circles) through which the solver holds a group rigid. Members no longer
        in the sketch are skipped; a text label (rigid, translate-only) is represented by two
        of its points instead of every glyph vertex."""
        segment_set = set(self.segments) if segment_set is None else segment_set
        circle_set = set(self.circles) if circle_set is None else circle_set
        segs = [s for s in group.segments if s in segment_set]
        verts = set(v for v in group.points if v in self.points_free)
        texts = set()
        for s in segs:
            text = self.text_group_for(s)
            if text is not None: texts.add(text)
            else: verts |= {s.v0, s.v1}
        circles = [c for c in group.circles if c in circle_set]
        verts.update(c.center for c in circles)
        arcs, ellipses = set(self.arcs), set(self.ellipses)
        for a in group.arcs:
            if a in arcs: verts |= {a.center, a.v_start, a.v_end}
        for e in group.ellipses:
            if e in ellipses: verts.update(e.vertices())
        for text in texts:
            glyph = sorted({v for s in text.segments for v in (s.v0, s.v1)},
                           key=lambda v: (v.x, v.y))
            verts.update(glyph[:1] + glyph[-1:])
        ordered = [v for v in self.vertices if v in verts]
        ordered += [v for v in verts if v not in ordered]
        return ordered, circles

    def _group_members(self, segs=(), circles=(), arcs=(), ellipses=(), points=()):
        """Editable members of a selection (text labels are taken as a whole)."""
        segs = self.expand_text_selection(s for s in segs if not s.reference)
        return ([s for s in self.segments if s in segs],
                [c for c in self.circles if c in circles and not c.reference],
                [a for a in self.arcs if a in arcs and not a.reference],
                [e for e in self.ellipses if e in ellipses and not e.reference],
                [v for v in self.points_free if v in points and not v.locked])

    def make_group(self, segs=(), circles=(), arcs=(), ellipses=(), points=()):
        """Group the given elements rigidly; existing groups they touch are merged into the
        new group. Returns (group, number of merged groups) or (None, 0)."""
        members = self._group_members(segs, circles, arcs, ellipses, points)
        if not any(members): return None, 0
        touched = [g for g in self.groups
                   if any(g.contains(e) for part in members for e in part)]
        for g in touched:
            members[0].extend(s for s in g.segments if s in self.segments)
            members[1].extend(c for c in g.circles if c in self.circles)
            members[2].extend(a for a in g.arcs if a in self.arcs)
            members[3].extend(e for e in g.ellipses if e in self.ellipses)
            members[4].extend(v for v in g.points if v in self.points_free)
        lists = (self.segments, self.circles, self.arcs, self.ellipses, self.points_free)
        members = [[e for e in lst if e in set(part)] for lst, part in zip(lists, members)]
        self.groups = [g for g in self.groups if g not in touched]
        group = SketchGroup(*members)
        self.groups.append(group)
        self._an_key = None
        return group, len(touched)

    def ungroup(self, elements):
        """Dissolve every group containing one of the elements. Returns the count."""
        elements = list(elements)
        gone = [g for g in self.groups if any(g.contains(e) for e in elements)]
        self.groups = [g for g in self.groups if g not in gone]
        if gone: self._an_key = None
        return len(gone)

    def prune_groups(self):
        """Drop group members that left the sketch and groups that became empty."""
        segs, circles, arcs = set(self.segments), set(self.circles), set(self.arcs)
        ellipses, points = set(self.ellipses), set(self.points_free)
        keep = []
        for g in getattr(self, "groups", []):
            g.segments = [s for s in g.segments if s in segs]
            g.circles = [c for c in g.circles if c in circles]
            g.arcs = [a for a in g.arcs if a in arcs]
            g.ellipses = [e for e in g.ellipses if e in ellipses]
            g.points = [v for v in g.points if v in points]
            verts = g.vertices()
            g.ref = {v: p for v, p in g.ref.items() if v in verts}
            for v in verts - set(g.ref): g.ref[v] = (v.x, v.y)   # (should not happen)
            g.radii = {c: r for c, r in g.radii.items() if c in set(g.circles)}
            if g.elements(): keep.append(g)
        self.groups = keep

    def _make_text_box_vertices(self, segments):
        """Create locked virtual points on a text bounding box: corners, edge mids, center."""
        if not segments:
            return []
        verts = {v for s in segments for v in (s.v0, s.v1)}
        x0 = min(v.x for v in verts); y0 = min(v.y for v in verts)
        x1 = max(v.x for v in verts); y1 = max(v.y for v in verts)
        xm, ym = (x0+x1)/2.0, (y0+y1)/2.0
        points = [(x0, y0), (x1, y0), (x1, y1), (x0, y1),
                  (xm, y0), (x1, ym), (xm, y1), (x0, ym), (xm, ym)]
        made = []
        for x, y in points:
            v = Vertex(x, y, locked=True)
            self.vertices.append(v)
            made.append(v)
        return made

    # ── placement ────────────────────────────────────────────────────────────
    def to3d(self, xy, z=0.0):
        O, u, v, w = self.frame
        return tuple(float(c) for c in O + xy[0]*u + xy[1]*v + z*w)

    def to3d_many(self, pts):
        O, u, v, _ = self.frame
        P = np.asarray(pts, dtype=float).reshape(-1, 2)
        return O + P[:, :1]*u + P[:, 1:2]*v

    def get_or_merge(self, x, y, snap):
        independent_vertices = self.text_vertices() | self.reference_vertices()
        for v in self.vertices:
            if v in independent_vertices: continue
            if hasattr(v, "reference_level"): continue
            if math.hypot(v.x-x, v.y-y) <= snap: return v
        v = Vertex(x, y); self.vertices.append(v); return v

    def text_vertices(self):
        return {v for group in self.text_groups for v in group.vertices()}

    def reference_vertices(self):
        vertices = {v for s in self.segments if s.reference for v in (s.v0, s.v1)}
        vertices.update(c.center for c in self.circles if c.reference)
        vertices.update(v for a in self.arcs if a.reference
                        for v in (a.center, a.v_start, a.v_end))
        vertices.update(v for ellipse in self.ellipses if ellipse.reference
                for v in ellipse.vertices())
        vertices.update(v for v in self.points_free if v.locked)
        return vertices

    def text_group_for(self, element):
        return next((group for group in self.text_groups
                     if element in group.segments or
                     (isinstance(element, Vertex) and element in group.vertices())), None)

    def expand_text_selection(self, segs):
        segs = set(segs)
        for group in self.text_groups:
            if segs.intersection(group.segments): segs.update(group.segments)
        return segs

    def add_svg_contours(self, contours, text_groups=()):
        """Insert ordinary SVG geometry and independently owned, rigid text outlines."""
        owners = {i: group for group in text_groups for i in group["contours"]}
        made = {id(group): [] for group in text_groups}
        added = 0
        for i, contour in enumerate(contours):
            group = owners.get(i)
            if group is None:
                vertices = [self.get_or_merge(x, y, MERGE_TOL) for x, y in contour]
            else:
                # Close each glyph contour locally, never merging it with other sketch geometry.
                vertices = []
                for x, y in contour:
                    v = next((v for v in vertices if math.hypot(v.x-x, v.y-y) <= MERGE_TOL), None)
                    if v is None:
                        v = Vertex(x, y, locked=True); self.vertices.append(v)
                    vertices.append(v)
                if len(vertices) > 2 and vertices[-1] is not vertices[0]:
                    vertices.append(vertices[0])
            segments = [Segment(a, b) for a, b in zip(vertices, vertices[1:]) if a is not b]
            self.segments.extend(segments); added += len(segments)
            if group is not None: made[id(group)].extend(segments)
        for group in text_groups:
            segs = made[id(group)]
            if not segs:
                continue
            self.text_groups.append(SketchText(
                group.get("label", ""), segs,
                box_vertices=self._make_text_box_vertices(segs),
                font_family=group.get("font_family", "Arial"),
                font_size=group.get("font_size", 12.0),
                bold=group.get("bold", False),
                italic=group.get("italic", False),
                underline=group.get("underline", False),
                align=group.get("align", "left"),
            ))
        self._an_key = None
        return added

    def add_text_label(self, at_xy, label, style):
        """Add a rigid text outline at sketch position at_xy (mm)."""
        contours = text_contours(str(label or ""),
                                 font_family=style.get("font_family", "Arial"),
                                 font_size=style.get("font_size", 12.0),
                                 bold=style.get("bold", False),
                                 italic=style.get("italic", False),
                                 underline=style.get("underline", False),
                                 align=style.get("align", "left"))
        if not contours:
            return None, 0
        ox, oy = float(at_xy[0]), float(at_xy[1])
        segs = []
        for contour in contours:
            vertices = []
            for x, y in contour:
                v = next((v for v in vertices
                          if math.hypot(v.x-(ox+x), v.y-(oy+y)) <= MERGE_TOL), None)
                if v is None:
                    v = Vertex(ox+x, oy+y, locked=True)
                    self.vertices.append(v)
                vertices.append(v)
            made = [Segment(a, b) for a, b in zip(vertices, vertices[1:]) if a is not b]
            self.segments.extend(made)
            segs.extend(made)
        if not segs:
            return None, 0
        group = SketchText(str(label), segs,
                           box_vertices=self._make_text_box_vertices(segs),
                           font_family=style.get("font_family", "Arial"),
                           font_size=float(style.get("font_size", 12.0)),
                           bold=bool(style.get("bold", False)),
                           italic=bool(style.get("italic", False)),
                           underline=bool(style.get("underline", False)),
                           align=style.get("align", "left"))
        self.text_groups.append(group)
        self._an_key = None
        return group, len(segs)

    def transform_text(self, group, original, scale=1.0, center=(0.0, 0.0), offset=(0.0, 0.0)):
        """Transform a complete label from a drag-start snapshot; reject conflicting constraints."""
        if group not in self.text_groups or set(original) != group.vertices():
            raise ValueError("A text transform must contain every vertex of an existing text group")
        if not all(math.isfinite(value) for value in (scale, *center, *offset)) or scale <= 0:
            return False
        positions = {v: (v.x, v.y) for v in self.vertices}
        radii = {c: c.radius for c in self.circles}
        for v, (x, y) in original.items():
            v.x = center[0] + (x-center[0])*scale + offset[0]
            v.y = center[1] + (y-center[1])*scale + offset[1]
        if self.solve():
            self._an_key = None
            return True
        for v, (x, y) in positions.items(): v.x, v.y = x, y
        for c, r in radii.items(): c.radius = r
        return False

    # ── topology ─────────────────────────────────────────────────────────────
    def used_vertices(self):
        used = set(self.points_free)
        for s in self.segments: used |= {s.v0, s.v1}
        for a in self.arcs:     used |= {a.center, a.v_start, a.v_end}
        for c in self.circles:  used.add(c.center)
        for ellipse in self.ellipses: used.update(ellipse.vertices())
        for group in self.text_groups: used |= group.vertices()
        return used

    def axis_segment(self, key):
        """The sketch's X ("x", y = 0) or Y ("y", x = 0) axis as a fixed line constraints can
        refer to. It is not part of the sketch geometry lists (never drawn, picked, snapped,
        trimmed or extruded; the view draws the axes itself). Its vertices are locked, so the
        solver treats them as constants."""
        axes = self.__dict__.setdefault("_axes", {})
        if key not in axes:
            if key not in ("x", "y"):
                raise ValueError(f"unknown sketch axis {key!r}")
            end = (1.0, 0.0) if key == "x" else (0.0, 1.0)
            segment = Segment(Vertex(0.0, 0.0, locked=True), Vertex(*end, locked=True),
                              construction=True)
            segment.sketch_axis = key
            axes[key] = segment
        return axes[key]

    def axis_segments(self):
        """The axis lines created so far (see axis_segment)."""
        return set(self.__dict__.get("_axes", {}).values())

    def _known_geometry(self):
        """Every geometry object a constraint may legally refer to."""
        return (set(self.vertices) | self.used_vertices() | set(self.segments) |
                set(self.circles) | set(self.arcs) | set(self.ellipses) | self.axis_segments())

    def missing_refs(self, c, known=None):
        """Geometry referenced by constraint c that is no longer part of this sketch."""
        if known is None: known = self._known_geometry()
        return {o for o in constraint_refs(c) if o is not None and o not in known}

    def prune_dangling_constraints(self):
        """Drop constraints that refer to deleted geometry (they cannot be solved or
        saved). Returns the number of constraints removed."""
        known = self._known_geometry()
        keep = [c for c in self.constraints if not self.missing_refs(c, known)]
        dropped = len(self.constraints) - len(keep)
        if dropped: self.constraints = keep
        return dropped

    def _edge_records(self):
        recs = [{"kind": "line", "a": s.v0, "b": s.v1, "pts": [s.v0.xy(), s.v1.xy()]}
                for s in self.segments if not s.construction]
        recs += [{"kind": "arc", "a": a.v_start, "b": a.v_end, "pts": a.tess(),
                  "center": a.center.xy(), "start": a.v_start.xy(), "end": a.v_end.xy()}
                 for a in self.arcs if not a.construction]
        return recs

    def profile_closed(self):
        """True when non-construction profile edges form closed loops."""
        edges = self._edge_records()
        has_closed_curve = (any(not c.construction for c in self.circles) or
                    any(not ellipse.construction for ellipse in self.ellipses))
        if not edges and not has_closed_curve: return bool(self.text_groups)
        deg = {}
        for e in edges:
            if e["a"] is e["b"]: return False
            deg[e["a"]] = deg.get(e["a"], 0) + 1; deg[e["b"]] = deg.get(e["b"], 0) + 1
        return all(d == 2 for d in deg.values())

    def open_profile_parts(self):
        """Where the profile is not closed → (edges, vertices): the profile lines and arcs
        that lie on no closed loop (dangling chains) and the vertices that make it open —
        loose ends, branch points (more than two edges) and edges that end where they start."""
        edges, bad = [], set()
        for element, a, b in [(s, s.v0, s.v1) for s in self.segments if not s.construction] + \
                [(arc, arc.v_start, arc.v_end) for arc in self.arcs if not arc.construction]:
            if a is b: bad.add(a)
            else: edges.append((element, a, b))
        degree = collections.Counter()
        for _element, a, b in edges: degree[a] += 1; degree[b] += 1
        bad |= {v for v, d in degree.items() if d == 1}
        dangling, changed = [], True
        while changed:                       # peel loose chains off, end by end
            changed, keep = False, []
            for edge in edges:
                _element, a, b = edge
                if degree[a] == 1 or degree[b] == 1:
                    dangling.append(edge[0]); degree[a] -= 1; degree[b] -= 1; changed = True
                else:
                    keep.append(edge)
            edges = keep
        bad |= {v for v, d in degree.items() if d > 2}
        return dangling, bad

    @property
    def closed(self): return self.profile_closed()

    def profile_loop_edges(self):
        """Closed profile loops as lists of edge records whose pts run along the loop
        (support geometry excluded). Full circles form single-edge loops."""
        loops = []
        edges = self._edge_records()
        unused = list(range(len(edges)))
        while unused:
            e0 = edges[unused.pop(0)]
            v_first, v_cur = e0["a"], e0["b"]
            loop = [dict(e0)]
            while v_cur is not v_first:
                nxt = next((j for j in unused
                            if edges[j]["a"] is v_cur or edges[j]["b"] is v_cur), None)
                if nxt is None: break
                unused.remove(nxt)
                e = dict(edges[nxt])
                if e["a"] is v_cur: v_cur = e["b"]
                else:               e["pts"] = e["pts"][::-1]; v_cur = e["a"]
                loop.append(e)
            if v_cur is v_first and sum(len(e["pts"])-1 for e in loop) >= 3:
                loops.append(loop)
        for c in self.circles:
            if not c.construction:
                pts = circle_pts(c.center.x, c.center.y, c.radius)
                loops.append([{"kind": "circle", "pts": pts + [pts[0]],
                               "center": c.center.xy(), "radius": c.radius}])
        for ellipse in self.ellipses:
            if not ellipse.construction:
                pts = ellipse.tess()
                loops.append([{"kind": "line", "pts": [a, b]}
                              for a, b in zip(pts, pts[1:] + pts[:1])])
        return loops

    def profile_loops(self):
        """Closed profile loops as lists of (x,y) mm points."""
        return [[p for e in loop for p in e["pts"][:-1]] for loop in self.profile_loop_edges()]

    def replace_vertex(self, old, new):
        """Redirect every reference of vertex old to vertex new and drop old."""
        if old is new: return
        if self.text_group_for(old) is not None or self.text_group_for(new) is not None:
            raise ValueError("Rigid text vertices cannot be merged with other geometry")
        for s in self.segments:
            if s.v0 is old: s.v0 = new
            if s.v1 is old: s.v1 = new
        for a in self.arcs:
            if a.center is old:  a.center = new
            if a.v_start is old: a.v_start = new
            if a.v_end is old:   a.v_end = new
        for c in self.circles:
            if c.center is old: c.center = new
        for ellipse in self.ellipses:
            for attr in ("major_start", "major_end", "minor_start", "minor_end"):
                if getattr(ellipse, attr) is old: setattr(ellipse, attr, new)
        pts = []
        for v in self.points_free:
            v = new if v is old else v
            if v not in pts: pts.append(v)
        self.points_free = pts
        for g in getattr(self, "groups", []):
            if old in g.ref:
                pos = g.ref.pop(old)
                g.ref.setdefault(new, pos)
            g.points = [new if v is old else v for v in g.points]
        for c in self.constraints:
            for attr in ("vertex", "vertex_move", "vertex_target", "a", "b",
                         "seg_a", "seg_b", "center"):
                if getattr(c, attr, None) is old: setattr(c, attr, new)
            if isinstance(c, CDimension) and isinstance(c.target, tuple):
                c.target = tuple(new if v is old else v for v in c.target)
        # a coincidence between two now-identical vertices is meaningless
        self.constraints = [c for c in self.constraints if not (
            isinstance(c, CCoincident) and c.vertex_move is c.vertex_target)]
        if old in self.vertices: self.vertices.remove(old)

    def merge_duplicate_geometry(self, tol_digits=5):
        """Remove lines, arcs and circles lying exactly on top of an equal element of the same
        kind (e.g. a symmetric shape mirrored onto itself by an older version — the doubled
        loops cancel each other in the profile). The duplicate's vertices are merged into
        the kept element's, constraints follow. Returns the number of removed elements."""
        def key(v): return (round(v.x, tol_digits) + 0.0, round(v.y, tol_digits) + 0.0)
        merge = {}
        def find(v):
            while v in merge: v = merge[v]
            return v
        def unify(dup, keep):
            dup, keep = find(dup), find(keep)
            if dup is not keep and not dup.locked: merge[dup] = keep
        text = self.text_vertices()
        dups, seen = {}, {}
        for s in self.segments:
            if s.reference or s.v0 in text or key(s.v0) == key(s.v1): continue
            k = ("s", s.construction, frozenset((key(s.v0), key(s.v1))))
            other = seen.setdefault(k, s)
            if other is s: continue
            same = key(s.v0) == key(other.v0)
            unify(s.v0, other.v0 if same else other.v1); unify(s.v1, other.v1 if same else other.v0)
            dups[s] = other
        for a in self.arcs:
            if a.reference: continue
            k = ("a", a.construction, key(a.center), key(a.v_start), key(a.v_end))
            other = seen.setdefault(k, a)
            if other is a: continue
            unify(a.center, other.center); unify(a.v_start, other.v_start); unify(a.v_end, other.v_end)
            dups[a] = other
        for c in self.circles:
            if c.reference: continue
            k = ("c", c.construction, key(c.center), round(c.radius, tol_digits))
            other = seen.setdefault(k, c)
            if other is c: continue
            unify(c.center, other.center); dups[c] = other
        if not dups: return 0
        for old in list(merge):
            self.replace_vertex(old, find(old))
        self.segments = [s for s in self.segments if s not in dups]
        self.arcs = [a for a in self.arcs if a not in dups]
        self.circles = [c for c in self.circles if c not in dups]
        for group in getattr(self, "groups", []):
            group.segments = [s for s in group.segments if s not in dups]
            group.arcs = [a for a in group.arcs if a not in dups]
            group.circles = [c for c in group.circles if c not in dups]
        # constraints on a removed duplicate act on the kept element; drop the ones that
        # became meaningless (a point mirrored onto itself, an element equal to itself)
        # or are now the same as another one
        kept, signatures = [], set()
        for c in self.constraints:
            for name, value in list(vars(c).items()):
                if isinstance(value, (Segment, Arc, Circle)) and value in dups:
                    setattr(c, name, dups[value])
            if isinstance(c, CMirrorPoint) and c.vertex_move is c.vertex_target: continue
            if isinstance(c, CEqual) and c.seg_a is c.seg_b: continue
            if isinstance(c, (CMirrorPoint, CEqual)):
                pair = (c.vertex_move, c.vertex_target) if isinstance(c, CMirrorPoint) \
                       else (c.seg_a, c.seg_b)
                extra = id(c.axis) if isinstance(c, CMirrorPoint) and isinstance(c.axis, Segment) \
                        else getattr(c, "axis", None)
                signature = (type(c).__name__, frozenset(map(id, pair)), extra)
            else:
                signature = (type(c).__name__, tuple(sorted(
                    (name, id(value) if isinstance(value, (Vertex, Segment, Arc, Circle)) else repr(value))
                    for name, value in vars(c).items() if not name.startswith("_"))))
            if signature in signatures: continue
            signatures.add(signature); kept.append(c)
        self.constraints = kept
        self.prune_groups()
        self._an_key = None
        return len(dups)

    def remove_geometry(self, segs=(), circles=(), arcs=(), points=(), ellipses=()):
        """Remove editable geometry and its constraints; projected reference geometry survives."""
        segs = {s for s in segs if not s.reference}
        circles = {c for c in circles if not c.reference}
        arcs = {a for a in arcs if not a.reference}
        points = {v for v in points if not v.locked}
        ellipses = {ellipse for ellipse in ellipses if not ellipse.reference}
        ellipses.update(ellipse for ellipse in self.ellipses
                if set(ellipse.vertices()) & points)
        segs = self.expand_text_selection(segs)
        self.text_groups = [group for group in self.text_groups
                            if not segs.intersection(group.segments)]
        before = self.used_vertices()
        self.segments    = [s for s in self.segments if s not in segs]
        self.circles     = [c for c in self.circles if c not in circles]
        self.arcs        = [a for a in self.arcs if a not in arcs]
        self.ellipses    = [ellipse for ellipse in self.ellipses if ellipse not in ellipses]
        self.points_free = [v for v in self.points_free if v not in points]
        after   = self.used_vertices()
        orphans = (before - after) | (points - after)
        self.vertices = [v for v in self.vertices if v not in orphans]
        gone = segs | circles | arcs | ellipses | orphans
        self.constraints = [c for c in self.constraints if not (constraint_refs(c) & gone)]
        self.prune_groups()

    def remove_unused_references(self, elements):
        """Remove the given reference segments / circles / arcs unless a constraint uses them
        or one of their vertices; vertices left without geometry go too. Returns the count."""
        used = set()
        for constraint in self.constraints:
            used |= constraint_refs(constraint)
        def removable(element):
            ends = {getattr(element, name, None)
                    for name in ("v0", "v1", "center", "v_start", "v_end")} - {None}
            return element.reference and element not in used and not (ends & used)
        gone = {element for element in elements if removable(element)}
        if not gone: return 0
        before = self.used_vertices()
        self.segments = [s for s in self.segments if s not in gone]
        self.circles  = [c for c in self.circles if c not in gone]
        self.arcs     = [a for a in self.arcs if a not in gone]
        orphans = before - self.used_vertices() - set(self.points_free)
        self.vertices = [v for v in self.vertices if v not in orphans]
        return len(gone)

    # ── scissor (trim) ───────────────────────────────────────────────────────
    def _trim_cuts(self, target):
        """Cut positions on target: crossings with every other element (incl. support and
        reference geometry) plus existing points lying on it.
        → (curve, [[param, point, vertex|None, [cutting elements]], …] sorted by param)."""
        cv = curve_of(target)
        own = ({target.v0, target.v1} if isinstance(target, Segment) else
               {target.center} if isinstance(target, Circle) else
               {target.center, target.v_start, target.v_end})
        cand = []
        for other in self.segments + self.circles + self.arcs:
            if other is target: continue
            for P in curve_intersections(cv, curve_of(other)):
                cand.append((curve_param(cv, P), P, None, other))
        independent_vertices = self.text_vertices() | self.reference_vertices()
        for v in self.used_vertices():
            if v not in own and dist_to_curve(cv, v.xy()) < TRIM_TOL:
                cand.append((curve_param(cv, v.xy()), v.xy(),
                             None if v in independent_vertices else v, None))
        end = curve_end(cv)
        closed = cv[0] == "circle" and cv[3] is None
        eps = TRIM_TOL if cv[0] == "line" else TRIM_TOL/max(cv[2], 1e-9)
        cuts = []
        for s, P, v, other in sorted(cand, key=lambda k: k[0]):
            if closed: s %= 2*math.pi
            elif s <= eps or s >= end - eps: continue
            dup = next((c for c in cuts if abs(c[0]-s) < eps or
                        (closed and abs(abs(c[0]-s) - 2*math.pi) < eps)), None)
            if dup is None:
                cuts.append([s, P, v, [other] if other is not None else []])
            else:
                if dup[2] is None and v is not None: dup[1], dup[2] = P, v
                if other is not None: dup[3].append(other)
        return cv, cuts

    def trim_range(self, target, click):
        """Part of target removed by a scissor click at `click` (mm).
        → (curve, cuts, lo, hi): lo / hi index the cut before / after the click (None = start /
        end of the element). lo = hi = None: the whole element goes (no cut points, or a full
        circle with fewer than two)."""
        cv, cuts = self._trim_cuts(target)
        sc, end = curve_param(cv, click), curve_end(cv)
        if cv[0] == "circle" and cv[3] is None:
            n = len(cuts)
            if n < 2: return cv, cuts, None, None
            for k in range(n):
                a, b = cuts[k][0], cuts[(k+1) % n][0] + (2*math.pi if k == n-1 else 0.0)
                s = sc if sc >= a else sc + 2*math.pi
                if a <= s <= b: return cv, cuts, k, (k+1) % n
            return cv, cuts, n-1, 0
        if not cuts: return cv, cuts, None, None
        if cv[0] == "line": sc = min(max(sc, 0.0), end)
        elif sc > end:  sc = end if sc - end < 2*math.pi - sc else 0.0
        lo = hi = None
        for k, c in enumerate(cuts):
            if c[0] <= sc: lo = k
            elif hi is None: hi = k
        return cv, cuts, lo, hi

    def trim_preview(self, target, click):
        """Polyline (mm) of the part a scissor click would remove."""
        cv, cuts, lo, hi = self.trim_range(target, click)
        end = curve_end(cv)
        a = cuts[lo][0] if lo is not None else 0.0
        b = cuts[hi][0] if hi is not None else end
        if lo is not None and hi is not None and b < a: b += 2*math.pi   # circle wrap-around
        if cv[0] == "line": return [curve_point(cv, a), curve_point(cv, b)]
        n = max(2, int(abs(b-a)/(2*math.pi)*64) + 1)
        return [curve_point(cv, a + (b-a)*i/n) for i in range(n+1)]

    def trim(self, target, click):
        """Scissor: remove the part of target between the two cut points around click.
        New end points stay attached to the cutting geometry (Point on Line / on Curve).
        Returns (ok, message)."""
        if target.reference: return False, "reference geometry cannot be cut"
        if self.text_group_for(target) is not None:
            return False, "text is rigid; move or resize the whole label in Select mode"
        if self.group_for(target) is not None:
            return False, "grouped geometry is rigid; ungroup it first"
        cv, cuts, lo, hi = self.trim_range(target, click)
        if lo is None and hi is None:
            self.remove_geometry(segs=[target] if isinstance(target, Segment) else (),
                                 circles=[target] if isinstance(target, Circle) else (),
                                 arcs=[target] if isinstance(target, Arc) else ())
            return True, "whole element removed (no cut points)"
        extra = []
        def vert(k):
            c = cuts[k]
            if c[2] is None:
                v = Vertex(*c[1]); self.vertices.append(v); c[2] = v
                for o in c[3]:
                    if o.reference: continue
                    extra.append(CPointOnLine(v, o) if isinstance(o, Segment) else CPointOnCurve(v, o))
            return c[2]
        con = target.construction
        if isinstance(target, Segment):
            pieces = ([Segment(target.v0, vert(lo), con)] if lo is not None else []) + \
                     ([Segment(vert(hi), target.v1, con)] if hi is not None else [])
        elif isinstance(target, Circle):
            pieces = [Arc(target.center, vert(hi), vert(lo), con)]
        else:
            pieces = ([Arc(target.center, target.v_start, vert(lo), con)] if lo is not None else []) + \
                     ([Arc(target.center, vert(hi), target.v_end, con)] if hi is not None else [])
        self._replace_element(target, pieces, extra)
        return True, f"cut — {len(pieces)} piece(s) left"

    @staticmethod
    def _trivial(c):
        """Point-on constraints whose point is an end point of the element itself."""
        if isinstance(c, CPointOnLine):  return c.vertex in (c.seg.v0, c.seg.v1)
        if isinstance(c, CPointOnCurve): return isinstance(c.curve, Arc) and \
                                                c.vertex in (c.curve.v_start, c.curve.v_end)
        return False

    def _replace_element(self, target, pieces, extra=()):
        """Swap target for its trimmed pieces and carry its constraints over."""
        before = self.used_vertices()
        first = pieces[0] if pieces else None
        if isinstance(target, Segment):
            i = self.segments.index(target); self.segments[i:i+1] = pieces
        elif isinstance(target, Circle):
            self.circles.remove(target); self.arcs += pieces
        else:
            i = self.arcs.index(target); self.arcs[i:i+1] = pieces
        add, keep = list(extra), []
        for c in self.constraints:
            if target not in constraint_refs(c): keep.append(c); continue
            if isinstance(c, (CHorizontal, CVertical)):
                add += [type(c)(p) for p in pieces]; continue
            if isinstance(c, CDimension):
                if isinstance(target, Circle) and first is not None:
                    add.append(CDimension(first, c.value/2 if c.dim_mode == "diameter" else c.value))
                elif isinstance(target, Arc) and first is not None:
                    c.target = first; keep.append(c)
                continue        # a line's length does not apply to its pieces
            if first is None: continue
            if isinstance(c, CSymmetric) and isinstance(target, Segment) and \
                    target in (c.seg_a, c.seg_b):
                # a piece has another midpoint: keep the lines symmetric, not the midpoints
                c.lines_only = True
            for attr in ("seg", "seg_a", "seg_b", "curve", "a", "b"):
                if getattr(c, attr, None) is target: setattr(c, attr, first)
            keep.append(c)
        if len(pieces) == 2:    # pieces of a line stay collinear, pieces of an arc concentric
            p0, p1 = pieces
            add += [CPointOnLine(p1.v0, p0), CPointOnLine(p1.v1, p0)] if isinstance(p0, Segment) \
                   else [CPointOnCurve(p1.v_start, p0)]
        orphans = before - self.used_vertices()
        self.vertices = [v for v in self.vertices if v not in orphans]
        self.constraints = [c for c in keep
                            if not (constraint_refs(c) & orphans) and not self._trivial(c)]
        for c in add:
            if not (constraint_refs(c) & orphans) and not self._trivial(c):
                self.try_add_constraint(c)

    # ── support geometry switch / clipboard ──────────────────────────────────
    @staticmethod
    def set_construction(elements, on):
        """Switch elements between profile and support geometry. Returns the count changed."""
        n = 0
        for e in elements:
            if getattr(e, "reference", False) or e.construction == on: continue
            e.construction = on; n += 1
        return n

    def mirror_geometry(self, segments, circles, arcs, ellipses, points, axis):
        segments, circles, arcs = set(segments), set(circles), set(arcs)
        ellipses, points = set(ellipses), set(points)
        elements = segments | circles | arcs | ellipses
        if not (elements or points):
            raise ValueError("Select geometry to mirror")
        if any(getattr(element, "reference", False) for element in elements) or \
                any(point.locked for point in points):
            raise ValueError("Reference geometry cannot be mirrored")
        if any(self.text_group_for(element) is not None for element in segments | points):
            raise ValueError("Text cannot be mirrored")
        if isinstance(axis, Segment):
            if axis in segments:
                raise ValueError("Choose an axis outside the selected geometry")
            ax, ay = axis.v0.xy()
            dx, dy = axis.v1.x-ax, axis.v1.y-ay
            length2 = dx*dx + dy*dy
            if length2 < 1e-18:
                raise ValueError("The mirror axis has zero length")
            def reflect(x, y):
                t = ((x-ax)*dx + (y-ay)*dy) / length2
                return 2*(ax+t*dx)-x, 2*(ay+t*dy)-y
        elif axis == "horizontal":
            def reflect(x, y): return x, -y
        elif axis == "vertical":
            def reflect(x, y): return -x, y
        else:
            raise ValueError("Choose a horizontal or vertical mirror axis")
        vertices = set(points)
        for segment in segments: vertices.update((segment.v0, segment.v1))
        for circle in circles: vertices.add(circle.center)
        for arc in arcs: vertices.update((arc.center, arc.v_start, arc.v_end))
        for ellipse in ellipses: vertices.update(ellipse.vertices())
        if vertices & self.text_vertices():
            raise ValueError("Text cannot be mirrored")
        # a mirrored point that lands on an existing point uses it (a shape that is already
        # symmetric about the axis maps onto itself), so nothing is drawn twice on top of
        # itself — doubled loops would cancel each other in the profile
        def position_key(x, y): return (round(x, 5) + 0.0, round(y, 5) + 0.0)
        existing = {}
        for vertex in self.vertices:
            existing.setdefault(position_key(vertex.x, vertex.y), vertex)
        mapping, created = {}, []
        for vertex in self.vertices:
            if vertex not in vertices: continue
            x, y = reflect(vertex.x, vertex.y)
            target = existing.get(position_key(x, y))
            if target is None:
                target = Vertex(x, y); created.append(target)
            mapping[vertex] = target
        if len(mapping) != len(vertices):
            raise ValueError("Selected geometry contains a missing vertex")
        segment_keys = {frozenset((s.v0, s.v1)) for s in self.segments}
        new_segments = []
        for s in self.segments:
            if s not in segments: continue
            k = frozenset((mapping[s.v0], mapping[s.v1]))
            if len(k) < 2 or k in segment_keys: continue
            segment_keys.add(k); new_segments.append(Segment(mapping[s.v0], mapping[s.v1], s.construction))
        pairs = []
        for circle in self.circles:
            if circle not in circles: continue
            center = mapping[circle.center]
            if any(c.center is center and abs(c.radius - circle.radius) < 1e-6
                   for c in self.circles + [m for _, m in pairs]):
                continue
            pairs.append((circle, Circle(center, circle.radius, circle.construction)))
        arc_keys = {(a.center, a.v_start, a.v_end) for a in self.arcs}
        new_arcs = []
        for a in self.arcs:
            if a not in arcs: continue
            k = (mapping[a.center], mapping[a.v_end], mapping[a.v_start])
            if k in arc_keys or k[1] is k[2]: continue
            arc_keys.add(k); new_arcs.append(Arc(*k, a.construction))
        ellipse_keys = {frozenset(e.vertices()) for e in self.ellipses}
        new_ellipses = []
        for ellipse in self.ellipses:
            if ellipse not in ellipses: continue
            mirrored = [mapping[vertex] for vertex in ellipse.vertices()]
            if frozenset(mirrored) in ellipse_keys: continue
            ellipse_keys.add(frozenset(mirrored))
            new_ellipses.append(Ellipse(*mirrored, construction=ellipse.construction))
        new_points = [mapping[point] for point in self.points_free
                      if point in points and mapping[point] in created]
        created_set = set(created)
        self.vertices.extend(created)
        self.segments.extend(new_segments)
        self.circles.extend(mirror for _, mirror in pairs)
        self.arcs.extend(new_arcs)
        self.ellipses.extend(new_ellipses)
        self.points_free.extend(new_points)
        # new points follow their originals; two existing points that are mirror images get
        # the mirror constraint only when it adds something (not redundant / conflicting)
        self.constraints.extend(CMirrorPoint(source, mirror, axis)
                                for source, mirror in mapping.items() if mirror in created_set)
        self.constraints.extend(CEqual(source, mirror) for source, mirror in pairs)
        done = set()
        for source, mirror in mapping.items():
            pair = frozenset((source, mirror))
            if mirror in created_set or mirror is source or pair in done: continue
            done.add(pair)
            if not (source.locked and mirror.locked):
                self.try_add_constraint(CMirrorPoint(source, mirror, axis))
        self._an_key = None
        return len(new_segments) + len(pairs) + len(new_arcs) + len(new_ellipses) + len(new_points)

    def extract(self, segs=(), circles=(), arcs=(), points=(), ellipses=()):
        """Independent copy of elements plus the constraints among them (Fix constraints and
        reference geometry are left out). Used by Copy / Cut and Multiple. Ellipses come
        with any of their points; rigid groups whose members are all copied are copied too."""
        segs = self.expand_text_selection(segs)
        segs    = [s for s in self.segments if s in segs and not s.reference]
        circles = [c for c in self.circles if c in circles and not c.reference]
        arcs    = [a for a in self.arcs if a in arcs and not a.reference]
        points  = set(points)
        ellipses = [e for e in self.ellipses if not e.reference and
                    (e in ellipses or set(e.vertices()) & points)]
        points  = [v for v in self.points_free if v in points]
        text_groups = [group for group in self.text_groups
                       if any(segment in segs for segment in group.segments)]
        if not (segs or circles or arcs or points or ellipses):
            return None
        verts = set(points)
        for s in segs:    verts |= {s.v0, s.v1}
        for c in circles: verts.add(c.center)
        for arc in arcs:  verts.update((arc.center, arc.v_start, arc.v_end))
        for e in ellipses: verts.update(e.vertices())
        for group in text_groups: verts.update(group.vertices())
        ordered_verts = [v for v in self.vertices if v in verts]
        ordered_verts.extend(v for v in verts if v not in self.vertices)
        vertex_map = {v: Vertex(v.x, v.y, v.locked) for v in ordered_verts}
        data = {
            "vertices": list(vertex_map.values()),
            "segments": [Segment(vertex_map[s.v0], vertex_map[s.v1], s.construction)
                         for s in segs],
            "circles": [Circle(vertex_map[c.center], c.radius, c.construction) for c in circles],
            "arcs": [Arc(vertex_map[a.center], vertex_map[a.v_start], vertex_map[a.v_end],
                         a.construction) for a in arcs],
            "points": [vertex_map[v] for v in points],
            "ellipses": [Ellipse(*(vertex_map[v] for v in e.vertices()),
                                 construction=e.construction) for e in ellipses],
            "text_groups": [],
            "groups": [],
            "constraints": [],
        }
        object_map = dict(vertex_map)
        object_map.update(zip(segs, data["segments"]))
        object_map.update(zip(circles, data["circles"]))
        object_map.update(zip(arcs, data["arcs"]))
        object_map.update(zip(ellipses, data["ellipses"]))
        for group in text_groups:
            data["text_groups"].append(SketchText(
                group.label, [object_map[s] for s in group.segments],
                box_vertices=[vertex_map[v] for v in group.box_vertices],
                font_family=group.font_family, font_size=group.font_size,
                bold=group.bold, italic=group.italic, underline=group.underline,
                align=group.align))
        for group in self.groups:
            members = group.elements()
            if members and all(e in object_map for e in members):
                data["groups"].append(SketchGroup(*([object_map[e] for e in part] for part in (
                    group.segments, group.circles, group.arcs, group.ellipses, group.points))))
        allowed = set(segs) | set(circles) | set(arcs) | verts
        for constraint in self.constraints:
            refs = constraint_refs(constraint)
            if isinstance(constraint, CFixed) or \
                    (isinstance(constraint, CMirrorPoint) and not isinstance(constraint.axis, Segment)) or \
                    not refs or not refs <= allowed:
                continue
            copied = type(constraint).__new__(type(constraint))
            for name, value in constraint.__dict__.items():
                setattr(copied, name, self._remap_clip_value(value, object_map))
            data["constraints"].append(copied)
        return data

    @staticmethod
    def _remap_clip_value(value, object_map):
        if isinstance(value, tuple):
            return tuple(Sketch._remap_clip_value(item, object_map) for item in value)
        if isinstance(value, (Vertex, Segment, Circle, Arc)):
            return object_map.get(value, value)
        return value

    @staticmethod
    def clip_vertices(data):
        return data["vertices"]

    @staticmethod
    def mirror_clipboard(data, axis):
        if axis not in ("x", "y"):
            raise ValueError("Clipboard mirror axis must be 'x' or 'y'")
        vertices = data["vertices"]
        if not vertices:
            return
        x0, x1 = min(v.x for v in vertices), max(v.x for v in vertices)
        y0, y1 = min(v.y for v in vertices), max(v.y for v in vertices)
        cx, cy = (x0+x1)/2, (y0+y1)/2
        if data.get("anchor_xy") is not None:
            ax, ay = data["anchor_xy"]
            data["anchor_xy"] = (ax, 2*cy - ay) if axis == "x" else (2*cx - ax, ay)
        for vertex in vertices:
            if axis == "x":
                vertex.y = 2*cy - vertex.y
            else:
                vertex.x = 2*cx - vertex.x
        for arc in data["arcs"]:
            arc.v_start, arc.v_end = arc.v_end, arc.v_start
        for constraint in data["constraints"]:
            if isinstance(constraint, CDimension) and isinstance(constraint.target, tuple):
                if (axis == "x" and constraint.orient == "V") or \
                        (axis == "y" and constraint.orient == "H"):
                    constraint.sign *= -1
            elif isinstance(constraint, CDistance):
                if constraint.pair == "vv":
                    if (axis == "x" and constraint.orient == "V") or \
                            (axis == "y" and constraint.orient == "H"):
                        constraint.sign *= -1
                elif constraint.pair == "vs" or \
                        (constraint.pair == "ss" and constraint.mode == "distance"):
                    constraint.sign *= -1
                elif constraint.pair == "cs":
                    constraint.circle_side *= -1
                elif constraint.pair == "ss" and constraint.mode == "angle":
                    if constraint.angle_sides is not None:
                        constraint.sign *= -1
                    else:
                        constraint.value = 180.0 - constraint.value
            elif isinstance(constraint, CTangential) and (
                    isinstance(constraint.entity_a, Segment) or
                    isinstance(constraint.entity_b, Segment)):
                constraint.side *= -1

    def insert(self, data, dx=0.0, dy=0.0):
        """Insert an extracted clipboard snapshot, offsetting it by (dx, dy)."""
        vertex_map = {v: Vertex(v.x + dx, v.y + dy, v.locked) for v in data["vertices"]}
        inserted = {
            "vertices": list(vertex_map.values()),
            "segments": [Segment(vertex_map[s.v0], vertex_map[s.v1], s.construction)
                         for s in data["segments"]],
            "circles": [Circle(vertex_map[c.center], c.radius, c.construction)
                        for c in data["circles"]],
            "arcs": [Arc(vertex_map[a.center], vertex_map[a.v_start], vertex_map[a.v_end],
                         a.construction) for a in data["arcs"]],
            "points": [vertex_map[v] for v in data["points"]],
            "ellipses": [Ellipse(*(vertex_map[v] for v in e.vertices()),
                                 construction=e.construction)
                         for e in data.get("ellipses", [])],
            "text_groups": [],
            "groups": [],
            "constraints": [],
        }
        object_map = dict(vertex_map)
        object_map.update(zip(data["segments"], inserted["segments"]))
        object_map.update(zip(data["circles"], inserted["circles"]))
        object_map.update(zip(data["arcs"], inserted["arcs"]))
        object_map.update(zip(data.get("ellipses", []), inserted["ellipses"]))
        for group in data.get("groups", []):
            # the copy is rigid in its own (possibly mirrored) current shape
            inserted["groups"].append(SketchGroup(*([object_map[e] for e in part] for part in (
                group.segments, group.circles, group.arcs, group.ellipses, group.points))))
        for group in data["text_groups"]:
            inserted["text_groups"].append(SketchText(
                group.label, [object_map[s] for s in group.segments],
                box_vertices=[vertex_map[v] for v in group.box_vertices],
                font_family=group.font_family, font_size=group.font_size,
                bold=group.bold, italic=group.italic, underline=group.underline,
                align=group.align))
        for constraint in data["constraints"]:
            copied = type(constraint).__new__(type(constraint))
            for name, value in constraint.__dict__.items():
                setattr(copied, name, self._remap_clip_value(value, object_map))
            inserted["constraints"].append(copied)
        self.vertices.extend(inserted["vertices"])
        self.segments.extend(inserted["segments"])
        self.circles.extend(inserted["circles"])
        self.arcs.extend(inserted["arcs"])
        self.points_free.extend(inserted["points"])
        self.ellipses.extend(inserted["ellipses"])
        self.text_groups.extend(inserted["text_groups"])
        self.groups.extend(inserted["groups"])
        self.constraints.extend(inserted["constraints"])
        self._an_key = None; self._an = None
        return inserted

    @staticmethod
    def clip_bounds(data):
        """Bounding box (x0, y0, x1, y1) of clipboard geometry including curve extents."""
        xs = [v.x for v in data["vertices"]]; ys = [v.y for v in data["vertices"]]
        for c in data["circles"]:
            xs += [c.center.x-c.radius, c.center.x+c.radius]
            ys += [c.center.y-c.radius, c.center.y+c.radius]
        for curve in list(data["arcs"]) + list(data.get("ellipses", [])):
            for x, y in curve.tess(): xs.append(x); ys.append(y)
        if not xs: return 0.0, 0.0, 0.0, 0.0
        return min(xs), min(ys), max(xs), max(ys)

    @staticmethod
    def clip_closed(data):
        """True when the copied profile consists of closed contours only (every line / arc
        end meets exactly one other end; circles and ellipses are closed by themselves)."""
        degree = {}
        for e in list(data["segments"]) + list(data["arcs"]):
            a, b = (e.v0, e.v1) if isinstance(e, Segment) else (e.v_start, e.v_end)
            if a is b: return False
            degree[a] = degree.get(a, 0) + 1; degree[b] = degree.get(b, 0) + 1
        if not degree and not (data["circles"] or data.get("ellipses")): return False
        return all(d == 2 for d in degree.values())

    # orientation-bound constraints that a rotated copy cannot keep
    @staticmethod
    def _orientation_bound(c):
        if isinstance(c, (CHorizontal, CVertical)): return True
        if isinstance(c, CDimension) and isinstance(c.target, tuple) and c.orient in ("H", "V"):
            return True
        if isinstance(c, CDistance) and c.pair == "vv" and getattr(c, "orient", "D") in ("H", "V"):
            return True
        return isinstance(c, CMirrorPoint) and not isinstance(c.axis, Segment)

    @staticmethod
    def pattern_clipboard(data, placements, support=None):
        """Several copies of clipboard data in one snapshot. placements: [(dx, dy, angle)] —
        each copy is rotated by angle (rad) about the centre of the source bounds, then shifted
        by (dx, dy). Rotated copies drop horizontal / vertical constraints (they no longer
        hold); everything else among the copied elements is kept. support: support geometry
        {"lines": [(a, b)], "arcs": [(centre, start, end)], "circles": [(centre, r)]} with
        points as offsets from the source centre (see SketchPatternDialog.support_geometry);
        coinciding points share one vertex."""
        x0, y0, x1, y1 = Sketch.clip_bounds(data)
        cx, cy = (x0+x1)/2, (y0+y1)/2
        out = Sketch("XY"); Sketch._ctr[0] -= 1      # scratch sketch: keep the name counter
        for dx, dy, angle in placements:
            ins = out.insert(data)
            cs, sn = math.cos(angle), math.sin(angle)
            for v in ins["vertices"]:
                x, y = v.x-cx, v.y-cy
                v.x, v.y = cx + cs*x - sn*y + dx, cy + sn*x + cs*y + dy
            if abs(math.remainder(angle, 2*math.pi)) > 1e-9:
                bound = [c for c in ins["constraints"] if Sketch._orientation_bound(c)]
                out.constraints = [c for c in out.constraints if not any(c is b for b in bound)]
            for g in ins["groups"]: g.snapshot()
        result = {"vertices": out.vertices, "segments": out.segments, "circles": out.circles,
                  "arcs": out.arcs, "points": out.points_free, "ellipses": out.ellipses,
                  "text_groups": out.text_groups, "groups": out.groups,
                  "constraints": out.constraints}
        bx0, by0, bx1, by1 = Sketch.clip_bounds(result)
        result["anchor_xy"] = ((bx0+bx1)/2, (by0+by1)/2)   # centre of the copies only
        if support:
            made = {}
            def vertex(q):
                key = (round(q[0], 6), round(q[1], 6))
                if key not in made:
                    made[key] = Vertex(cx+q[0], cy+q[1]); result["vertices"].append(made[key])
                return made[key]
            for a, b in support.get("lines", []):
                result["segments"].append(Segment(vertex(a), vertex(b), construction=True))
            for c, s, e in support.get("arcs", []):
                result["arcs"].append(Arc(vertex(c), vertex(s), vertex(e), construction=True))
            for c, r in support.get("circles", []):
                result["circles"].append(Circle(vertex(c), r, construction=True))
        return result

    def _solve_with(self, system, prefer_lock=()):
        X = system.pack()
        if prefer_lock:
            idx = system.indices_of(prefer_lock)
            if idx:
                ok, X2 = system.solve(X, heavy=idx)
                if ok:
                    # Preserve variables that barely moved, then solve with them held.
                    still = [j for j in idx if abs(X2[j] - X[j]) < 1e-3]
                    if still:
                        X3 = list(X2)
                        for j in still:
                            X3[j] = X[j]
                        ok3, X3 = system.solve(X3, still)
                        if ok3:
                            X2 = X3
                if ok:
                    system.unpack(X2)
                    return True
        ok, X2 = system.solve(X)
        if ok:
            system.unpack(X2)
        return ok

    def solve(self, prefer_lock=()):
        return self._solve_with(SketchSystem(self), prefer_lock)

    def try_add_constraint(self, c, prefer_lock=()):
        """Add c only if it removes at least one DOF (i.e. is not redundant / dependent on
        existing constraints) and can be satisfied. Returns (ok, message)."""
        if self.missing_refs(c):        # e.g. a stale pick from before an undo / trim / delete
            _dbg(f"try_add_constraint: rejected {type(c).__name__}, geometry no longer in sketch")
            return False, "refers to geometry that no longer exists — pick it again"
        if isinstance(c, CDistance) and not c.driving:
            self.constraints.append(c)            # information only: never constrains
            return True, "information only"
        r0 = SketchSystem(self).rank()
        self.constraints.append(c)
        system = SketchSystem(self)
        r1 = system.rank()
        if r1 <= r0:
            self.constraints.remove(c)
            return False, "redundant — already defined by other constraints (over-constrained)"
        if not self._solve_with(system, prefer_lock):
            self.constraints.remove(c)
            return False, "conflicts with existing constraints"
        rows = len(system.rows_of(c))
        return True, ("partially redundant" if r1 - r0 < rows else "")

    def remove_constraint(self, c):
        if c in self.constraints: self.constraints.remove(c)

    def set_dimension_value(self, c, value, dim_mode=None):
        """Change a driving dimension; reverts and returns False if it cannot be satisfied."""
        old = (c.value, c.dim_mode)
        c.value = value
        if dim_mode: c.dim_mode = dim_mode
        prefer_lock = (c.a.v0, c.a.v1) if isinstance(c, CDistance) and c.mode == "angle" \
            and c.pair == "ss" else ()
        if self.solve(prefer_lock=prefer_lock): return True
        c.value, c.dim_mode = old
        return False

    def drag(self, moves):
        """Move vertices toward targets {vertex: (x,y)} while honouring all constraints.
        First the dragged vertices are held at their targets and the rest follows; if that
        is impossible, the nearest valid configuration is used (vertex slides / stays)."""
        snap = {v: (v.x, v.y) for v in self.vertices}
        rad  = {c: c.radius for c in self.circles}
        for v, (x, y) in moves.items():
            if not v.locked: v.x, v.y = x, y
        system = SketchSystem(self); X = system.pack()
        ok, X2 = system.solve(X, system.indices_of(moves.keys()))
        if not ok: ok, X2 = system.solve(X)
        if ok:
            system.unpack(X2); return True
        for v, (x, y) in snap.items(): v.x, v.y = x, y
        for c, r in rad.items(): c.radius = r
        return False

    def analysis(self):
        key = (tuple((id(v), v.x, v.y) for v in self.vertices),
               tuple((id(c), id(c.center), c.radius, c.construction) for c in self.circles),
               tuple((id(s.v0), id(s.v1), s.construction) for s in self.segments),
               tuple((id(a.center), id(a.v_start), id(a.v_end), a.construction)
                     for a in self.arcs),
               tuple((tuple(id(v) for v in ellipse.vertices()), ellipse.construction)
                   for ellipse in self.ellipses),
               tuple((id(c), getattr(c, "value", None), getattr(c, "dim_mode", None),
                      getattr(c, "mode", None)) for c in self.constraints),
               tuple(id(p) for p in self.points_free),
               tuple((id(g), len(g.ref), len(g.elements())) for g in getattr(self, "groups", [])))
        if key != self._an_key:
            self._an = SketchSystem(self).analyse(); self._an_key = key
        return self._an

    # ── status ───────────────────────────────────────────────────────────────
    def total_dof(self):
        """Remaining DOF of the profile geometry (support geometry and points are optional)."""
        return self.analysis()["dof"]

    def optional_dof(self):
        """Remaining DOF that only affect support geometry / points (informational)."""
        an = self.analysis(); return max(0, an["dof_all"] - an["dof"])

    def blocking_issues(self):
        """Issues that prevent accepting the sketch."""
        return [] if self.profile_closed() else ["Profile not closed"]

    def open_issues(self):
        issues = self.blocking_issues()
        dof = self.total_dof()
        if dof > 0:
            issues.append(f"{dof} DOF remaining (accept still allowed)")
            if not any(isinstance(c, CFixed) for c in self.constraints) and \
               not any(v.locked for v in self.vertices):
                issues.append("Tip: fix one vertex to anchor position")
        return issues

    def points(self):
        return [s.v0.xy() for s in self.segments]

# ── geometry helpers ──────────────────────────────────────────────────────────
CURVE_CHORD_TOL = 0.005    # mm — max. deviation of a tessellated circle / arc from the true curve

def curve_segments(r, sweep=2*math.pi, lo=32, hi=256):
    """Segment count keeping the chord error below CURVE_CHORD_TOL (scaled to the sweep)."""
    frac = sweep/(2*math.pi)
    if r <= CURVE_CHORD_TOL: return max(4, int(math.ceil(lo*frac)))
    n = math.ceil(math.pi/math.acos(1.0 - CURVE_CHORD_TOL/r))
    return max(4, int(math.ceil(min(max(n, lo), hi)*frac)))

def circle_pts(cx, cy, r, n=None):
    if n is None: n = curve_segments(r)
    return [(cx+r*math.cos(2*math.pi*i/n), cy+r*math.sin(2*math.pi*i/n)) for i in range(n)]

def poly_area(pts):
    return 0.5*sum(pts[i][0]*pts[(i+1)%len(pts)][1]-pts[(i+1)%len(pts)][0]*pts[i][1]
                   for i in range(len(pts)))

def triangulate_polygon(pts):
    """Ear clipping for a simple CCW polygon; returns index triples.
    Collinear boundary vertices are kept (never clipped as zero-area ears and never
    skipped by a diagonal): the side walls of an extrusion use every profile vertex, so
    dropping one would leave a T-junction and an open (non-watertight) mesh."""
    def cross(o, a, b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    def same(p, q): return p[0] == q[0] and p[1] == q[1]
    def side(a, b, p):
        """+1 left of a→b, -1 right, 0 on the line (relative tolerance)."""
        cr = cross(a, b, p)
        scale = math.hypot(b[0]-a[0], b[1]-a[1]) * math.hypot(p[0]-a[0], p[1]-a[1])
        if abs(cr) <= 1e-9 * scale: return 0
        return 1 if cr > 0 else -1
    def turn(a, b, c):
        """+1 convex, -1 reflex, 0 straight at b."""
        return side(a, b, c)
    def in_triangle(a, b, c, p):         # inside or on the boundary
        return side(a, b, p) >= 0 and side(b, c, p) >= 0 and side(c, a, p) >= 0
    idx = list(range(len(pts))); tris = []
    while len(idx) > 3:
        m = len(idx)
        turns = [turn(pts[idx[k-1]], pts[idx[k]], pts[idx[(k+1)%m]]) for k in range(m)]
        # reflex and straight vertices can lie inside / on the diagonal of a candidate ear
        blockers = [idx[k] for k in range(m) if turns[k] <= 0]
        for k in range(m):
            i0, i1, i2 = idx[k-1], idx[k], idx[(k+1)%m]
            a, b, c = pts[i0], pts[i1], pts[i2]
            if same(a, b) or same(b, c):   # duplicate vertex: drop it
                idx.pop(k); break
            if turns[k] <= 0: continue
            if any(j not in (i0, i1, i2) and not (same(pts[j], a) or same(pts[j], c)) and
                   in_triangle(a, b, c, pts[j]) for j in blockers):
                continue
            tris.append((i0, i1, i2)); idx.pop(k); break
        else:
            if all(t == 0 for t in turns):
                return tris                # only a degenerate sliver is left
            # no ear found (self-intersecting input) → fan the remainder
            tris += [(idx[0], idx[k], idx[k+1]) for k in range(1, len(idx)-1)]
            return tris
    if len(idx) == 3 and turn(*(pts[i] for i in idx)) != 0: tris.append(tuple(idx))
    return tris

def _face_boundary_loop(entry, face_index):
    """Return the vertex ids around the single closed boundary of a triangulated face."""
    face = entry["faces"][face_index]
    triangles = entry["solid"][1]
    edge_counts = {}
    for tri_index in face.get("tris", []):
        a, b, c = triangles[tri_index]
        for start, end in ((a, b), (b, c), (c, a)):
            edge = (min(start, end), max(start, end))
            edge_counts[edge] = edge_counts.get(edge, 0) + 1
    boundary = [edge for edge, count in edge_counts.items() if count == 1]
    if not boundary:
        return []
    adjacent = {}
    for a, b in boundary:
        adjacent.setdefault(a, []).append(b)
        adjacent.setdefault(b, []).append(a)
    if len(boundary) < 3 or any(len(neighbors) != 2 for neighbors in adjacent.values()):
        raise ValueError("Each selected face must have one simple closed boundary.")
    if not adjacent:
        raise ValueError("The selected face has no boundary.")
    loop = [min(adjacent)]
    previous = None
    while True:
        current = loop[-1]
        next_vertex = next(vertex for vertex in adjacent[current] if vertex != previous)
        if next_vertex == loop[0]:
            break
        if next_vertex in loop:
            raise ValueError("Each selected face must have one simple closed boundary.")
        loop.append(next_vertex)
        previous, current = current, next_vertex
    if len(loop) != len(adjacent):
        raise ValueError("Faces with holes or multiple boundaries cannot be bridged.")
    return loop

def _bridge_face_frame(entry, face_index, loop):
    """Estimate an outward frame and boundary vertex normals for a planar or curved face."""
    face = entry["faces"][face_index]
    if face.get("planar") and "frame" in face:
        origin, u, v, normal = (np.asarray(axis, dtype=float) for axis in face["frame"])
        normal = _unit(normal)
        u = _unit(u)
        v = _unit(np.cross(normal, u))
        if float(v @ np.asarray(face["frame"][2], dtype=float)) < 0:
            v = -v
        return origin, u, v, normal, [normal.copy() for _ in loop]

    vertices = np.asarray(entry["solid"][0], dtype=float)
    triangles = np.asarray(entry["solid"][1], dtype=int)
    face_triangles = np.asarray(face.get("tris", []), dtype=int)
    if not len(face_triangles):
        raise ValueError("The selected curved face has no triangles.")
    selected = triangles[face_triangles]
    tri_points = vertices[selected]
    tri_normals = np.cross(tri_points[:, 1] - tri_points[:, 0],
                           tri_points[:, 2] - tri_points[:, 0])
    face_normal = _unit(np.sum(tri_normals, axis=0))
    if np.linalg.norm(face_normal) < 1e-9:
        raise ValueError("Could not determine the selected curved face normal.")
    center = tri_points.reshape(-1, 3).mean(axis=0)
    reference = np.array((1.0, 0.0, 0.0)) if abs(face_normal[0]) < 0.9 \
        else np.array((0.0, 1.0, 0.0))
    u = _unit(np.cross(reference, face_normal))
    v = _unit(np.cross(face_normal, u))

    vertex_normals = {}
    for tri, tri_normal in zip(selected, tri_normals):
        for vertex_id in tri:
            vertex_normals[vertex_id] = vertex_normals.get(vertex_id, np.zeros(3)) + tri_normal
    normals = []
    for vertex_id in loop:
        normal = _unit(vertex_normals.get(vertex_id, face_normal))
        if float(normal @ face_normal) < 0:
            normal = -normal
        normals.append(normal)
    return center, u, v, face_normal, normals

def _resample_bridge_loop(points, normals, count):
    """Resample a closed face outline evenly while interpolating its local normals."""
    lengths = [float(np.linalg.norm(points[(i + 1) % len(points)] - points[i]))
               for i in range(len(points))]
    perimeter = sum(lengths)
    if perimeter < 1e-9:
        raise ValueError("A selected face boundary has zero length.")
    cumulative = np.cumsum([0.0] + lengths)
    sampled_points, sampled_normals = [], []
    for distance in np.linspace(0.0, perimeter, count, endpoint=False):
        edge = min(int(np.searchsorted(cumulative, distance, side="right") - 1),
                   len(points) - 1)
        fraction = (distance - cumulative[edge]) / max(lengths[edge], 1e-12)
        next_index = (edge + 1) % len(points)
        sampled_points.append(points[edge] * (1 - fraction) + points[next_index] * fraction)
        normal = normals[edge] * (1 - fraction) + normals[next_index] * fraction
        sampled_normals.append(_unit(normal))
    return sampled_points, sampled_normals

def _bridge_loop_params(points):
    """Normalised arc-length position (0 … 1) of each vertex of a closed loop."""
    lengths = np.array([float(np.linalg.norm(points[(i + 1) % len(points)] - points[i]))
                        for i in range(len(points))])
    perimeter = float(lengths.sum())
    if perimeter < 1e-9:
        raise ValueError("A selected face boundary has zero length.")
    return np.concatenate(([0.0], np.cumsum(lengths)[:-1])) / perimeter

def _sample_bridge_loop(points, normals, params):
    """Points / normals of a closed loop at normalised arc-length positions `params`."""
    own = _bridge_loop_params(points)
    count = len(points)
    sampled_points, sampled_normals = [], []
    for t in params:
        t = float(t) % 1.0
        edge = min(max(int(np.searchsorted(own, t, side="right")) - 1, 0), count - 1)
        following = (edge + 1) % count
        end = own[following] if following else 1.0
        fraction = (t - own[edge]) / max(end - own[edge], 1e-12)
        sampled_points.append(points[edge] * (1 - fraction) + points[following] * fraction)
        sampled_normals.append(_unit(normals[edge] * (1 - fraction) +
                                     normals[following] * fraction))
    return sampled_points, sampled_normals

def _match_bridge_loops(points_a, normals_a, points_b, normals_b, u, v):
    """Pair the outlines of the two bridged faces so every corner stays a corner (an even
    resampling put the points of e.g. a long thin rectangle mid-edge, which twisted the
    bridge). Same corner count: corners are paired directly (best rotation). Otherwise each
    loop also gets a point where the other one has a corner. Returns the paired loops."""
    points_a = [np.asarray(p, dtype=float) for p in points_a]
    points_b = [np.asarray(p, dtype=float) for p in points_b]
    normals_a = [np.asarray(n, dtype=float) for n in normals_a]
    normals_b = [np.asarray(n, dtype=float) for n in normals_b]
    limit = 256
    if len(points_a) > limit:
        points_a, normals_a = _resample_bridge_loop(points_a, normals_a, limit)
    if len(points_b) > limit:
        points_b, normals_b = _resample_bridge_loop(points_b, normals_b, limit)

    def area(points):
        return poly_area([(float(p @ u), float(p @ v)) for p in points])
    if area(points_a) * area(points_b) < 0:       # same turning sense seen along the bridge
        points_b.reverse(); normals_b.reverse()
    same = len(points_a) == len(points_b)
    params_a = None if same else _bridge_loop_params(points_a)
    best = None
    for shift in range(len(points_b)):
        candidate = points_b[shift:] + points_b[:shift]
        candidate_normals = normals_b[shift:] + normals_b[:shift]
        if same:
            score = sum(float((a - b) @ (a - b)) for a, b in zip(points_a, candidate))
        else:
            at_a, _ = _sample_bridge_loop(candidate, candidate_normals, params_a)
            at_b, _ = _sample_bridge_loop(points_a, normals_a, _bridge_loop_params(candidate))
            score = sum(float((a - b) @ (a - b)) for a, b in zip(points_a, at_a)) + \
                sum(float((a - b) @ (a - b)) for a, b in zip(at_b, candidate))
        if best is None or score < best[0]:
            best = (score, candidate, candidate_normals)
    _, points_b, normals_b = best
    if same:
        return points_a, normals_a, points_b, normals_b
    params = sorted(set(np.round(np.concatenate((params_a, _bridge_loop_params(points_b))),
                                 9).tolist()))
    params = [t for i, t in enumerate(params) if i == 0 or t - params[i - 1] > 1e-6]
    points_a, normals_a = _sample_bridge_loop(points_a, normals_a, params)
    points_b, normals_b = _sample_bridge_loop(points_b, normals_b, params)
    return points_a, normals_a, points_b, normals_b

def _simplify_bridge_loop(vertices, ids):
    """Drop boundary vertices lying on a straight run (e.g. the extra vertices the fusing of
    bodies inserts into face edges), so the corners of a face stay corners when the boundary
    is resampled."""
    ids = list(ids)
    changed = True
    while changed and len(ids) > 3:
        changed = False
        for position in range(len(ids)):
            before = np.asarray(vertices[ids[position - 1]], dtype=float)
            here = np.asarray(vertices[ids[position]], dtype=float)
            after = np.asarray(vertices[ids[(position + 1) % len(ids)]], dtype=float)
            incoming, outgoing = here - before, after - here
            lengths = float(np.linalg.norm(incoming) * np.linalg.norm(outgoing))
            if lengths < 1e-12:
                straight = True
            else:
                straight = float(np.linalg.norm(np.cross(incoming, outgoing))) / lengths < 1e-4 \
                    and float(incoming @ outgoing) > 0
            if straight:
                del ids[position]
                changed = True
                break
    return ids

def _bridge_faces(entry_a, face_index_a, entry_b, face_index_b):
    """Build a closed bridge between two facing face boundaries."""
    if entry_a is entry_b and face_index_a == face_index_b:
        raise ValueError("Select two different faces.")
    try:
        ids_a = _simplify_bridge_loop(entry_a["solid"][0], _face_boundary_loop(entry_a, face_index_a))
    except ValueError:
        ids_a = []
    try:
        ids_b = _simplify_bridge_loop(entry_b["solid"][0], _face_boundary_loop(entry_b, face_index_b))
    except ValueError:
        ids_b = []
    if not ids_a and ids_b:
        entry_a, entry_b = entry_b, entry_a
        face_index_a, face_index_b = face_index_b, face_index_a
        ids_a, ids_b = ids_b, ids_a
    if not ids_a:
        raise ValueError("At least one selected face needs a simple closed boundary.")
    if len(ids_a) < 3 or (ids_b and len(ids_b) < 3):
        raise ValueError("The selected faces need at least three boundary points.")
    if not ids_b:       # projected bridge: keep every outline vertex so face A's triangles fit
        ids_a = _face_boundary_loop(entry_a, face_index_a)

    points_a = [np.asarray(entry_a["solid"][0][index], dtype=float) for index in ids_a]
    frame_a = _bridge_face_frame(entry_a, face_index_a, ids_a)
    center_a = np.mean(points_a, axis=0)
    normal_a = frame_a[3]
    if ids_b:
        points_b = [np.asarray(entry_b["solid"][0][index], dtype=float) for index in ids_b]
        frame_b = _bridge_face_frame(entry_b, face_index_b, ids_b)
        normals_b = frame_b[4]
    else:
        target_face = entry_b["faces"][face_index_b]
        target_triangles = np.asarray(entry_b["solid"][1], dtype=int)[
            np.asarray(target_face.get("tris", []), dtype=int)]
        if not len(target_triangles):
            raise ValueError("The selected target face has no triangles.")
        target_vertices = np.asarray(entry_b["solid"][0], dtype=float)
        target_center = target_vertices[np.unique(target_triangles)].mean(axis=0)
        target_direction = _unit(normal_a)
        hit_distance = _ray_nearest(points_a, target_direction, target_vertices, target_triangles)
        if not np.isfinite(hit_distance).all():
            reverse_direction = -target_direction
            reverse_hits = _ray_nearest(
                points_a, reverse_direction, target_vertices, target_triangles)
            if np.isfinite(reverse_hits).all() and \
                    float(reverse_direction @ (target_center - center_a)) > \
                    float(target_direction @ (target_center - center_a)):
                target_direction, hit_distance = reverse_direction, reverse_hits
        if not np.isfinite(hit_distance).all():
            raise ValueError("The boundary does not reach the selected closed surface.")
        points_b = [point + target_direction * distance
                    for point, distance in zip(points_a, hit_distance)]
        normal_b = -target_direction
        reference = np.array((1.0, 0.0, 0.0)) if abs(normal_b[0]) < 0.9 \
            else np.array((0.0, 1.0, 0.0))
        target_u = _unit(np.cross(reference, normal_b))
        target_v = _unit(np.cross(normal_b, target_u))
        frame_b = (np.mean(points_b, axis=0), target_u, target_v, normal_b,
                   [normal_b.copy() for _ in points_b])
        normals_b = frame_b[4]
    center_b = np.mean(points_b, axis=0)
    normal_b = frame_b[3]
    direction = center_b - center_a
    distance = float(np.linalg.norm(direction))
    if distance < 1e-4:
        raise ValueError("The selected face centers are too close to bridge.")
    direction /= distance
    if float(normal_a @ normal_b) > -0.8 or \
            float(normal_a @ direction) < 0.2 or float(-normal_b @ direction) < 0.2:
        raise ValueError("Select two faces that face each other across the gap.")

    projected = not ids_b
    if projected:
        # the target loop is the projection of the source loop: keep the exact face outline,
        # resampling would leave slivers of the source face exposed around the bridge
        count = len(points_a)
        normals_a = [np.asarray(normal, dtype=float) for normal in frame_a[4]]
        normals_b = list(normals_b)
    else:
        points_a, normals_a, points_b, normals_b = _match_bridge_loops(
            points_a, frame_a[4], points_b, normals_b, frame_a[1], frame_a[2])
        count = len(points_a)
    frame_u, frame_v = frame_a[1], frame_a[2]
    projected_a = [((point - center_a) @ frame_u, (point - center_a) @ frame_v)
                   for point in points_a]
    if poly_area(projected_a) * float(np.cross(frame_u, frame_v) @ normal_a) < 0:
        ids_a = list(reversed(ids_a))
        points_a.reverse()
        points_b.reverse()
        normals_a.reverse()
        normals_b.reverse()

    inset = min(0.02, distance * 0.01)
    # a projected bridge starts flush on face A (an inset would poke out of curved bodies)
    loop_a = list(points_a) if projected else \
        [point - normal * inset for point, normal in zip(points_a, normals_a)]
    loop_b = [point - normal * inset for point, normal in zip(points_b, normals_b)]
    vertices = [point.tolist() for point in loop_a + loop_b]
    triangles = []
    faces = []

    def add_face(kind, indices, boundary_indices, normal, frame, planar=True):
        start = len(triangles)
        for tri in indices:
            a, b, c = (np.asarray(vertices[index], dtype=float) for index in tri)
            if float(np.cross(b - a, c - a) @ normal) < 0:
                tri = (tri[0], tri[2], tri[1])
            triangles.append(tuple(tri))
        boundary_points = [vertices[index] for index in boundary_indices]
        boundary = [["line", boundary_points[i], boundary_points[(i + 1) % len(boundary_points)]]
                    for i in range(len(boundary_points))]
        record = {"kind": kind, "tris": list(range(start, len(triangles))),
                  "planar": planar}
        if planar:
            record["frame"] = [np.asarray(axis, dtype=float).tolist() for axis in frame]
            record["boundary"] = boundary
        faces.append(record)

    def cap_triangles(points, frame, offset):
        origin, u, v, _ = (np.asarray(axis, dtype=float) for axis in frame)
        projected = [((point - origin) @ u, (point - origin) @ v) for point in points]
        if poly_area(projected) < 0:
            projected.reverse()
            mapped = list(reversed(range(len(points))))
        else:
            mapped = list(range(len(points)))
        return [tuple(offset + mapped[index] for index in tri)
                for tri in triangulate_polygon(projected)]

    desired_a, desired_b = -direction, direction
    face_frame_a = [frame_a[0], frame_a[1], frame_a[2], frame_a[3]]
    face_frame_b = [frame_b[0], frame_b[1], frame_b[2], frame_b[3]]
    bridge_frame_a = [loop_a[0], frame_a[1], _unit(np.cross(desired_a, frame_a[1])), desired_a]
    bridge_frame_b = [loop_b[0], frame_b[1], _unit(np.cross(desired_b, frame_b[1])), desired_b]
    if projected:
        # face A's own triangles (reversed by add_face) cancel exactly against face A in the union
        index_of = {vertex_id: position for position, vertex_id in enumerate(ids_a)}
        source_vertices = entry_a["solid"][0]
        cap_a = []
        for tri in np.asarray(entry_a["solid"][1], dtype=int)[
                np.asarray(entry_a["faces"][face_index_a]["tris"], dtype=int)].tolist():
            for vertex_id in tri:
                if vertex_id not in index_of:
                    index_of[vertex_id] = len(vertices)
                    vertices.append([float(x) for x in source_vertices[vertex_id]])
            cap_a.append(tuple(index_of[vertex_id] for vertex_id in tri))
    else:
        cap_a = cap_triangles(loop_a, face_frame_a, 0)
    add_face("bridge end", cap_a, list(range(count)), desired_a, bridge_frame_a)
    add_face("bridge end", cap_triangles(loop_b, face_frame_b, count),
             list(range(count, 2 * count)), desired_b, bridge_frame_b)

    quads = []
    for index in range(count):
        following = (index + 1) % count
        quad = (index, following, count + following, count + index)
        side_tris = [(quad[0], quad[1], quad[2]), (quad[0], quad[2], quad[3])]
        points = [np.asarray(vertices[i], dtype=float) for i in quad]
        side_normal = np.cross(points[1] - points[0], points[2] - points[0])
        sweep = ((points[3] - points[0]) + (points[2] - points[1])) / 2.0
        expected_normal = np.cross(points[1] - points[0], sweep)
        if float(side_normal @ expected_normal) < 0:
            side_tris = [(a, c, b) for a, b, c in side_tris]
            side_normal = -side_normal
        side_normal = _unit(side_normal)
        planar = abs(float((points[3] - points[0]) @ side_normal)) < 1e-5
        quads.append((side_tris, side_normal, planar))

    # one side face per smooth run of quads (a round bridge gets one curved face, no seams)
    smooth = math.cos(math.radians(30.0))
    creases = [i for i in range(count) if float(quads[i - 1][1] @ quads[i][1]) < smooth]
    groups = [[(c + k) % count for k in range((creases[(j + 1) % len(creases)] - c) % count or count)]
              for j, c in enumerate(creases)] if creases else [list(range(count))]
    for group in groups:
        normal = quads[group[0]][1]
        flat = len(group) < count and all(quads[i][2] and float(normal @ quads[i][1]) > 1 - 1e-9
                                          for i in group)
        start = len(triangles)
        for i in group:
            triangles.extend(tuple(tri) for tri in quads[i][0])
        record = {"kind": "bridge side", "tris": list(range(start, len(triangles))), "planar": flat}
        if flat:
            last = (group[-1] + 1) % count
            ids = group + [last, count + last] + [count + i for i in reversed(group)]
            corner = np.asarray(vertices[group[0]], dtype=float)
            side_u = _unit(np.asarray(vertices[last], dtype=float) - corner)
            record["frame"] = [corner.tolist(), side_u.tolist(),
                               np.cross(normal, side_u).tolist(), normal.tolist()]
            record["boundary"] = [["line", vertices[ids[i]], vertices[ids[(i + 1) % len(ids)]]]
                                  for i in range(len(ids))]
        faces.append(record)

    if not _mesh_is_closed(triangles) or abs(mesh_volume(vertices, triangles)) < 1e-9:
        raise ValueError("The selected face boundaries do not form a valid bridge.")
    return vertices, triangles, faces

def _opposing_bridge_face_pairs(entry_a, entry_b):
    """Return boundary-to-opposing or boundary-to-surface pairs, nearest first."""
    faces_a = []
    for face_index, face in enumerate(entry_a.get("faces", [])):
        if not face.get("tris"):
            continue
        try:
            loop = _face_boundary_loop(entry_a, face_index)
            if len(loop) < 3:
                continue
            points = np.asarray([entry_a["solid"][0][index] for index in loop], dtype=float)
            frame = _bridge_face_frame(entry_a, face_index, loop)
            faces_a.append((face_index, points.mean(axis=0), frame[3]))
        except (ValueError, IndexError):
            continue

    faces_b = []
    for face_index, face in enumerate(entry_b.get("faces", [])):
        if not face.get("tris"):
            continue
        try:
            loop = _face_boundary_loop(entry_b, face_index)
            if len(loop) >= 3:
                points = np.asarray([entry_b["solid"][0][index] for index in loop], dtype=float)
                frame = _bridge_face_frame(entry_b, face_index, loop)
                faces_b.append((face_index, points.mean(axis=0), frame[3], True))
                continue
        except (ValueError, IndexError):
            pass
        triangles = np.asarray(entry_b["solid"][1], dtype=int)[
            np.asarray(face.get("tris", []), dtype=int)]
        if not len(triangles):
            continue
        vertices = np.asarray(entry_b["solid"][0], dtype=float)
        points = vertices[np.unique(triangles)]
        faces_b.append((face_index, points.mean(axis=0), None, False))

    pairs = []
    for face_a, center_a, normal_a in faces_a:
        for face_b, center_b, normal_b, has_boundary in faces_b:
            direction = center_b - center_a
            distance = float(np.linalg.norm(direction))
            if distance < 1e-4:
                continue
            direction /= distance
            faces_opposed = has_boundary and float(normal_a @ normal_b) <= -0.8 and \
                float(-normal_b @ direction) >= 0.2
            faces_toward_target = not has_boundary and float(normal_a @ direction) >= 0.2
            if float(normal_a @ direction) >= 0.2 and (faces_opposed or faces_toward_target):
                pairs.append((distance, face_a, face_b))
    return [(face_a, face_b) for _, face_a, face_b in sorted(pairs)]

def _pt_in_poly(pt, poly):
    """Ray-cast point-in-polygon test (2-D)."""
    x, y = pt; n = len(poly); inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]; xj, yj = poly[j]
        if ((yi > y) != (yj > y)) and (x < (xj-xi)*(y-yi)/(yj-yi+1e-12) + xi):
            inside = not inside
        j = i
    return inside

def _bridge_hole(outer, hole):
    """Merge a CW hole into a CCW outer polygon via a bridge edge.
    Finds the rightmost hole vertex and the visible outer vertex to its right.
    Returns a single merged polygon (list of pts) with duplicated bridge vertices."""
    # find rightmost hole vertex
    hi = max(range(len(hole)), key=lambda i: hole[i][0])
    M = hole[hi]
    # find the outer vertex that is visible from M (rightmost intersection)
    best_x, best_oi = -math.inf, 0
    for oi in range(len(outer)):
        a, b = outer[oi], outer[(oi+1) % len(outer)]
        # does the ray M→+x cross edge a→b?
        if abs(b[1]-a[1]) < 1e-12: continue
        t = (M[1]-a[1])/(b[1]-a[1])
        if not (0.0 <= t <= 1.0): continue
        ix = a[0] + t*(b[0]-a[0])
        if ix >= M[0] and ix > best_x:
            best_x = ix; best_oi = oi
    # pick the vertex at best_oi or best_oi+1 that is more to the right
    oi1 = (best_oi+1) % len(outer)
    oi = oi1 if outer[oi1][0] > outer[best_oi][0] else best_oi
    # build merged polygon: outer[0..oi] + bridge + hole[hi..] + hole[..hi] + bridge back
    merged = list(outer[:oi+1])
    merged += [hole[(hi+k) % len(hole)] for k in range(len(hole))]
    merged += [hole[hi], outer[oi]]
    merged += list(outer[oi+1:])
    return merged

class _EcNode:
    __slots__ = ("i", "x", "y", "prev", "next", "steiner")
    def __init__(self, i, x, y):
        self.i = i; self.x = x; self.y = y; self.prev = self.next = None; self.steiner = False

def _ec_area(p, q, r): return (q.y - p.y)*(r.x - q.x) - (q.x - p.x)*(r.y - q.y)
def _ec_eq(a, b): return a.x == b.x and a.y == b.y
def _ec_pit(ax, ay, bx, by, cx, cy, px, py):
    return ((cx-px)*(ay-py) >= (ax-px)*(cy-py) and (ax-px)*(by-py) >= (bx-px)*(ay-py)
            and (bx-px)*(cy-py) >= (cx-px)*(by-py))
def _ec_remove(p): p.next.prev = p.prev; p.prev.next = p.next
def _ec_sign(v): return (v > 0) - (v < 0)
def _ec_on_seg(p, q, r):
    return min(p.x, r.x) <= q.x <= max(p.x, r.x) and min(p.y, r.y) <= q.y <= max(p.y, r.y)
def _ec_intersects(p1, q1, p2, q2):
    o1 = _ec_sign(_ec_area(p1, q1, p2)); o2 = _ec_sign(_ec_area(p1, q1, q2))
    o3 = _ec_sign(_ec_area(p2, q2, p1)); o4 = _ec_sign(_ec_area(p2, q2, q1))
    if o1 != o2 and o3 != o4: return True
    return ((o1 == 0 and _ec_on_seg(p1, p2, q1)) or (o2 == 0 and _ec_on_seg(p1, q2, q1)) or
            (o3 == 0 and _ec_on_seg(p2, p1, q2)) or (o4 == 0 and _ec_on_seg(p2, q1, q2)))
def _ec_local_inside(a, b):
    if _ec_area(a.prev, a, a.next) < 0:
        return _ec_area(a, b, a.next) >= 0 and _ec_area(a, a.prev, b) >= 0
    return _ec_area(a, b, a.prev) < 0 or _ec_area(a, a.next, b) < 0
def _ec_middle_inside(a, b):
    p = a; inside = False; px = (a.x + b.x)/2; py = (a.y + b.y)/2
    while True:
        if ((p.y > py) != (p.next.y > py)) and p.next.y != p.y and \
           px < (p.next.x - p.x)*(py - p.y)/(p.next.y - p.y) + p.x:
            inside = not inside
        p = p.next
        if p is a: return inside
def _ec_intersects_poly(a, b):
    p = a
    while True:
        if p.i != a.i and p.next.i != a.i and p.i != b.i and p.next.i != b.i and \
           _ec_intersects(p, p.next, a, b): return True
        p = p.next
        if p is a: return False
def _ec_valid_diagonal(a, b):
    return (a.next.i != b.i and a.prev.i != b.i and not _ec_intersects_poly(a, b) and
            ((_ec_local_inside(a, b) and _ec_local_inside(b, a) and _ec_middle_inside(a, b) and
              (_ec_area(a.prev, a, b.prev) != 0 or _ec_area(a, b.prev, b) != 0)) or
             (_ec_eq(a, b) and _ec_area(a.prev, a, a.next) > 0 and _ec_area(b.prev, b, b.next) > 0)))
def _ec_split(a, b):
    a2 = _EcNode(a.i, a.x, a.y); b2 = _EcNode(b.i, b.x, b.y)
    an = a.next; bp = b.prev
    a.next = b; b.prev = a; a2.next = an; an.prev = a2
    b2.next = a2; a2.prev = b2; bp.next = b2; b2.prev = bp
    return b2
def _ec_filter(start, end=None):
    if start is None: return None
    if end is None: end = start
    p = start
    while True:
        again = False
        if not p.steiner and (_ec_eq(p, p.next) or _ec_area(p.prev, p, p.next) == 0):
            _ec_remove(p); p = end = p.prev
            if p is p.next: break
            again = True
        else:
            p = p.next
        if not again and p is end: break
    return end
def _ec_is_ear(ear):
    a, b, c = ear.prev, ear, ear.next
    if _ec_area(a, b, c) >= 0: return False
    min_x = min(a.x, b.x, c.x); max_x = max(a.x, b.x, c.x)
    min_y = min(a.y, b.y, c.y); max_y = max(a.y, b.y, c.y)
    p = c.next
    while p is not a:
        if min_x <= p.x <= max_x and min_y <= p.y <= max_y and \
           _ec_pit(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and \
           _ec_area(p.prev, p, p.next) >= 0:
            return False
        p = p.next
    return True
def _ec_cure(start, out):
    p = start
    while True:
        a = p.prev; b = p.next.next
        if not _ec_eq(a, b) and _ec_intersects(a, p, p.next, b) and \
           _ec_local_inside(a, b) and _ec_local_inside(b, a):
            out.append((a.i, p.i, b.i)); _ec_remove(p); _ec_remove(p.next); p = start = b
        p = p.next
        if p is start: return _ec_filter(p)
def _ec_split_earcut(start, out):
    a = start
    while True:
        b = a.next.next
        while b is not a.prev:
            if a.i != b.i and _ec_valid_diagonal(a, b):
                c = _ec_split(a, b)
                a = _ec_filter(a, a.next); c = _ec_filter(c, c.next)
                _ec_linked(a, out, 0); _ec_linked(c, out, 0)
                return
            b = b.next
        a = a.next
        if a is start: return
def _ec_linked(ear, out, pas):
    if ear is None: return
    stop = ear
    while ear.prev is not ear.next:
        prev, nxt = ear.prev, ear.next
        if _ec_is_ear(ear):
            out.append((prev.i, ear.i, nxt.i)); _ec_remove(ear)
            ear = stop = nxt.next; continue
        ear = nxt
        if ear is stop:
            if pas == 0: _ec_linked(_ec_filter(ear), out, 1)
            elif pas == 1:
                ear = _ec_cure(_ec_filter(ear), out); _ec_linked(ear, out, 2)
            else: _ec_split_earcut(ear, out)
            break
def _ec_ring(pts, base):
    """Circular doubly linked list of the points (outer ring CCW, holes CW for y up)."""
    last = None; first = None
    for k in range(len(pts)):
        n = _EcNode(base + k, pts[k][0], pts[k][1])
        if last is None: first = n
        else: n.prev = last; last.next = n
        last = n
    last.next = first; first.prev = last
    if _ec_eq(first, first.prev): _ec_remove(first); first = first.next
    return first
def _ec_bridge(hole, outer):
    p = outer; hx, hy = hole.x, hole.y; qx = -math.inf; m = None
    if _ec_eq(hole, p): return p
    while True:
        if _ec_eq(hole, p.next): return p.next
        if hy <= p.y and hy >= p.next.y and p.next.y != p.y:
            x = p.x + (hy - p.y)*(p.next.x - p.x)/(p.next.y - p.y)
            if x <= hx and x > qx:
                qx = x; m = p if p.x < p.next.x else p.next
                if x == hx: return m
        p = p.next
        if p is outer: break
    if m is None: return None
    stop = m; mx, my = m.x, m.y; tan_min = math.inf; p = m
    while True:
        if hx >= p.x >= mx and hx != p.x and _ec_pit(hx if hy < my else qx, hy, mx, my,
                                                      qx if hy < my else hx, hy, p.x, p.y):
            tn = abs(hy - p.y)/(hx - p.x)
            if _ec_local_inside(p, hole) and (tn < tan_min or (tn == tan_min and (
                    p.x > m.x or (p.x == m.x and _ec_area(m.prev, m, p.prev) < 0 and
                                  _ec_area(p.next, m, m.next) < 0)))):
                m = p; tan_min = tn
        p = p.next
        if p is stop: return m

@lru_cache(maxsize=16)
def _triangulate_profile_cached(outer, holes):
    if not holes:
        return tuple(triangulate_polygon(outer)), outer
    pts = list(outer); starts = []
    for h in holes: starts.append(len(pts)); pts += list(h)
    outer_node = _ec_ring(outer, 0)
    queue = []
    for s, h in zip(starts, holes):
        ring = _ec_ring(h, s)
        if ring is ring.next: ring.steiner = True
        left = ring; p = ring.next
        while p is not ring:
            if p.x < left.x or (p.x == left.x and p.y < left.y): left = p
            p = p.next
        queue.append(left)
    queue.sort(key=lambda n: n.x)
    for hole in queue:
        bridge = _ec_bridge(hole, outer_node)
        if bridge is None: continue
        rev = _ec_split(bridge, hole)
        _ec_filter(rev, rev.next)
        outer_node = _ec_filter(bridge, bridge.next)
    out = []
    _ec_linked(_ec_filter(outer_node), out, 0)
    return tuple(out), tuple(pts)

def triangulate_with_holes(outer, holes):
    """Triangulate a CCW outer polygon with zero or more CW hole polygons (earcut).
    Returns (tris, pts): CCW index triples into pts (= the outer points followed by the
    hole points). Results are cached by profile coordinates for repeated extrusions."""
    outer_key = tuple((float(p[0]), float(p[1])) for p in outer)
    holes_key = tuple(tuple((float(p[0]), float(p[1])) for p in hole) for hole in holes)
    tris, pts = _triangulate_profile_cached(outer_key, holes_key)
    return list(tris), list(pts)

def _unit(a):
    a = np.asarray(a, float); n = np.linalg.norm(a)
    return a/n if n > 1e-12 else a

GEAR_FILLET_RADIUS = 0.38   # basic-rack tip radius as a module fraction (ISO 53 profile A)


def _involute(angle):
    return math.tan(angle) - angle


def _inverse_involute(value):
    angle = max(1e-6, (3.0 * value) ** (1.0 / 3.0))
    for _ in range(40):
        step = (_involute(angle) - value) / (math.tan(angle) ** 2)
        angle -= step
        if abs(step) < 1e-14:
            break
    return angle


def undercut_free_shift(teeth, pressure_angle=20.0):
    """Smallest profile shift that keeps a rack-generated gear free of undercut."""
    return 1.0 - float(teeth) * math.sin(math.radians(pressure_angle)) ** 2 / 2.0


def involute_pair_geometry(module, teeth_1, teeth_2, pressure_angle, shift_1=0.0, shift_2=0.0):
    """(centre distance, working pressure angle in degrees, tip shortening factor) of an
    external profile-shifted pair. The tips of both gears are shortened by the factor times
    the module so the standard 0.25·m tip clearance is kept."""
    alpha = math.radians(pressure_angle)
    teeth_sum = float(teeth_1 + teeth_2)
    shift_sum = float(shift_1 + shift_2)
    reference = module * teeth_sum / 2.0
    if abs(shift_sum) < 1e-12:
        return reference, float(pressure_angle), 0.0
    working = _inverse_involute(2.0 * math.tan(alpha) * shift_sum / teeth_sum + _involute(alpha))
    distance = reference * math.cos(alpha) / math.cos(working)
    return distance, math.degrees(working), max(0.0, shift_sum - (distance - reference) / module)


def bevel_pitch_angles(teeth_1, teeth_2, shaft_angle=90.0):
    """Pitch-cone angles (degrees) of two straight bevel gears meshing at the shaft angle."""
    shaft = math.radians(shaft_angle)
    first = math.atan2(math.sin(shaft), teeth_2 / teeth_1 + math.cos(shaft))
    return math.degrees(first), math.degrees(shaft - first)


def gear_outside_from_module(kind, module, teeth, profile_shift=0.0, bevel_angle=45.0):
    """Nominal tip diameter; a bevel gear's is measured at the heel (back-cone crown)."""
    if kind == "bevel":
        return module * (teeth + 2.0 * (1.0 + profile_shift) * math.cos(math.radians(bevel_angle)))
    if kind == "internal":
        return module * (teeth + 7.5)
    return module * (teeth + 2.0 + 2.0 * profile_shift)


def gear_module_from_outside(kind, outside_diameter, teeth, profile_shift=0.0, bevel_angle=45.0):
    return outside_diameter / gear_outside_from_module(kind, 1.0, teeth, profile_shift, bevel_angle)


def _generated_flank(module, teeth, pressure_angle, profile_shift, backlash, tip_radius,
                     fillet_samples=80, flank_samples=120):
    """One flank of an external gear generated by a basic-rack cutter.

    Returns (points, undercut): Cartesian points in a frame whose tooth centre line is +X,
    running from the middle of the tooth space (polar angle pi/teeth) over the root fillet
    and the involute to the tip circle. `teeth` may be fractional (virtual bevel gear)."""
    m, z = float(module), float(teeth)
    alpha = math.radians(pressure_angle)
    r = m * z / 2.0
    shift = float(profile_shift) * m
    half_space = math.pi * m / 4.0 + float(backlash) * m / 2.0       # cutter tooth half width
    dedendum = 1.25 * m
    tip_half = half_space - dedendum * math.tan(alpha)
    if tip_half < 0.02 * m:
        raise ValueError("Pressure angle or backlash too large for full-depth teeth.")
    corner = (math.pi / 2.0 + alpha) / 2.0
    rho = min(GEAR_FILLET_RADIUS * m, 0.95 * tip_half * math.tan(corner))
    u_c, v_c = tip_half - rho / math.tan(corner), -dedendum + rho  # fillet centre (rack coords)
    rack_line = r + shift                                          # rack reference line (world Y)
    rotate_to_tooth = -(math.pi / 2.0 - math.pi / z)               # space centre +Y -> pi/z
    cr, sr = math.cos(rotate_to_tooth), math.sin(rotate_to_tooth)
    raw = []

    def add(qx, qy, phi):
        c, s = math.cos(phi), math.sin(phi)
        gx, gy = c * qx - s * qy, s * qx + c * qy
        raw.append((cr * gx - sr * gy, sr * gx + cr * gy))

    add(0.0, rack_line - dedendum, 0.0)
    if u_c > 1e-12:
        add(0.0, rack_line - dedendum, -u_c / r)
    for index in range(1, fillet_samples + 1):                      # trochoid of the tip fillet
        beta = (math.pi / 2.0 - alpha) * math.sin(math.pi / 2.0 * index / fillet_samples)
        phi = (-(shift + v_c) * math.tan(beta) - u_c) / r
        add(u_c + r * phi + rho * math.sin(beta), rack_line + v_c - rho * math.cos(beta), phi)
    v_start, v_end = v_c - rho * math.sin(alpha), 1.05 * m
    for index in range(1, flank_samples + 1):                       # involute from the rack flank
        v = v_start + (v_end - v_start) * (index / flank_samples) ** 1.5
        lam = -(shift + v) / math.sin(alpha)
        phi = (lam * math.cos(alpha) - half_space - v * math.tan(alpha)) / r
        add(lam * math.cos(alpha), r - lam * math.sin(alpha), phi)

    points, undercut = _remove_loop(raw)
    clipped = [points[0]]
    for a, b in zip(points, points[1:]):
        ra, rb = math.hypot(*a), math.hypot(*b)
        if rb >= tip_radius:
            t = (tip_radius - ra) / (rb - ra) if rb > ra else 1.0
            clipped.append((a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])))
            break
        clipped.append(b)
    else:
        raise ValueError("The tooth flank does not reach the tip circle.")
    if any(y <= 0.0 for _, y in clipped[1:]):
        raise ValueError("The teeth become pointed; reduce the profile shift or the tooth height.")
    return _simplify_polyline(clipped, 0.004 * m), undercut


def _simplify_polyline(points, tolerance):
    """Douglas-Peucker reduction that keeps both end points."""
    keep = [False] * len(points)
    keep[0] = keep[-1] = True
    stack = [(0, len(points) - 1)]
    while stack:
        first, last = stack.pop()
        ax, ay = points[first]
        bx, by = points[last]
        length = math.hypot(bx - ax, by - ay) or 1e-30
        worst, index = 0.0, None
        for k in range(first + 1, last):
            px, py = points[k]
            distance = abs((bx - ax) * (ay - py) - (ax - px) * (by - ay)) / length
            if distance > worst:
                worst, index = distance, k
        if index is not None and worst > tolerance:
            keep[index] = True
            stack.extend(((first, index), (index, last)))
    return [point for point, kept in zip(points, keep) if kept]


def _segments_cross(p1, p2, q1, q2):
    d = (p2[0] - p1[0]) * (q2[1] - q1[1]) - (p2[1] - p1[1]) * (q2[0] - q1[0])
    if abs(d) < 1e-18:
        return None
    t = ((q1[0] - p1[0]) * (q2[1] - q1[1]) - (q1[1] - p1[1]) * (q2[0] - q1[0])) / d
    s = ((q1[0] - p1[0]) * (p2[1] - p1[1]) - (q1[1] - p1[1]) * (p2[0] - p1[0])) / d
    if 0.0 <= t <= 1.0 and 0.0 <= s <= 1.0:
        return p1[0] + t * (p2[0] - p1[0]), p1[1] + t * (p2[1] - p1[1])
    return None


def _remove_loop(points):
    """Cut the undercut loop where the fillet trochoid crosses the involute."""
    for i in range(len(points) - 1):
        for j in range(len(points) - 2, i + 1, -1):
            hit = _segments_cross(points[i], points[i + 1], points[j], points[j + 1])
            if hit is not None:
                return points[:i + 1] + [hit] + points[j + 1:], True
    return points, False


def _assemble_outline(flank, teeth, tip_samples=3):
    """Full closed outline (counter-clockwise) from one flank of the tooth centred on +X."""
    mirrored = [(x, -y) for x, y in flank]
    tip_radius = math.hypot(*flank[-1])
    tip_angle = math.atan2(flank[-1][1], flank[-1][0])
    arc = [(tip_radius * math.cos(a), tip_radius * math.sin(a))
           for a in (tip_angle * (2.0 * k / tip_samples - 1.0) for k in range(1, tip_samples))]
    tooth = mirrored + arc + flank[::-1]
    tooth = tooth[:-1]
    outline = []
    for k in range(teeth):
        angle = 2.0 * math.pi * k / teeth
        c, s = math.cos(angle), math.sin(angle)
        outline.extend((c * x - s * y, s * x + c * y) for x, y in tooth)
    return outline


def external_gear_outline(module, teeth, pressure_angle=20.0, profile_shift=0.0, backlash=0.0,
                          tip_reduction=0.0, bevel_angle=None):
    """(outline points, info) of a rack-generated external gear; with `bevel_angle` the
    heel section of a straight bevel gear (Tredgold back-cone tooth form, flanks projected
    from the cone apex onto the plane through the crown)."""
    module = float(module)
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Gear module must be a finite positive number.")
    if not isinstance(teeth, int) or teeth < 6:
        raise ValueError("An external gear requires at least 6 teeth.")
    if not math.isfinite(pressure_angle) or not 10.0 <= pressure_angle <= 35.0:
        raise ValueError("Pressure angle must be between 10° and 35°.")
    if not -1.0 <= profile_shift <= 1.5:
        raise ValueError("Profile shift must be between -1.0 and 1.5.")
    if not 0.0 <= backlash <= 0.5:
        raise ValueError("Backlash must be between 0 and 0.5 module.")
    addendum = (1.0 + profile_shift - tip_reduction) * module
    if bevel_angle is None:
        virtual = teeth
    else:
        delta = math.radians(bevel_angle)
        if not 1.0 <= bevel_angle <= 75.0:
            raise ValueError("Bevel cone angle must be between 1° and 75°.")
        virtual = teeth / math.cos(delta)
    virtual_radius = module * virtual / 2.0
    flank, undercut = _generated_flank(module, virtual, pressure_angle, profile_shift, backlash,
                                       virtual_radius + addendum)
    pitch_radius = module * teeth / 2.0
    apex_height = None
    if bevel_angle is not None:
        cone_height = pitch_radius / math.tan(delta)
        crown = addendum * math.sin(delta)
        apex_height = cone_height - crown
        mapped = []
        for x, y in flank:
            slant = math.hypot(x, y) - virtual_radius
            angle = math.atan2(y, x) * virtual / teeth
            radius = (pitch_radius + slant * math.cos(delta)) * apex_height / \
                     (cone_height - slant * math.sin(delta))
            mapped.append((radius * math.cos(angle), radius * math.sin(angle)))
        flank = mapped
    tip_angle = math.atan2(flank[-1][1], flank[-1][0])
    tip_radius = math.hypot(*flank[-1])
    info = {"undercut": undercut, "root_radius": min(math.hypot(*p) for p in flank),
            "tip_radius": tip_radius, "tip_land": 2.0 * tip_radius * tip_angle,
            "pitch_radius": pitch_radius, "apex_height": apex_height}
    return _assemble_outline(flank, teeth), info


def internal_gear_outline(module, teeth, pressure_angle=20.0, backlash=0.0, flank_samples=10):
    """Inner outline of a ring gear: the tooth spaces are external-gear teeth (true internal
    involute). A ring tooth is centred on +X."""
    m, z = float(module), int(teeth)
    alpha = math.radians(pressure_angle)
    r = m * z / 2.0
    base = r * math.cos(alpha)
    tip, root = r - m, r + 1.25 * m
    if tip <= 0:
        raise ValueError("The ring gear tooth count is too small for this module.")

    def half_space(radius):
        radius = max(radius, base)
        return math.pi / (2.0 * z) + backlash / z + _involute(alpha) - \
               _involute(math.acos(min(1.0, base / radius)))

    start = max(tip, base)
    if half_space(root) <= 0:
        raise ValueError("The ring gear tooth spaces become pointed.")
    flank = []                                        # space centred on angle 0, upper side
    if tip < base:
        flank.append((tip, half_space(base)))
    flank.extend((start + (root - start) * k / flank_samples,
                  half_space(start + (root - start) * k / flank_samples))
                 for k in range(flank_samples + 1))
    pitch = 2.0 * math.pi / z
    if flank[0][1] >= pitch / 2.0:
        raise ValueError("The ring gear teeth become pointed.")
    space = [(radius, -angle) for radius, angle in flank] + \
            [(root, flank[-1][1] * f) for f in (-0.5, 0.0, 0.5)] + flank[::-1]
    tooth_tip = [(tip, flank[0][1] + (pitch - 2.0 * flank[0][1]) * f) for f in (0.25, 0.5, 0.75)]
    period = [(radius, angle + pitch / 2.0) for radius, angle in space + tooth_tip]
    outline = []
    for k in range(z):
        offset = k * pitch
        outline.extend((radius * math.cos(angle + offset), radius * math.sin(angle + offset))
                       for radius, angle in period)
    return outline


def gear_module(parameters):
    """Module of a generated gear from its stored outside diameter (rack: stored module)."""
    kind = parameters.get("kind", "spur")
    if kind == "rack":
        return float(parameters["module"])
    teeth = int(parameters["teeth"])
    outside = float(parameters["outside_diameter"])
    if kind == "internal":
        return float(parameters.get("module", outside / (teeth + 7.5)))
    tredgold = kind == "bevel" and parameters.get("bevel_profile") == "tredgold"
    return gear_module_from_outside("bevel" if tredgold else "spur", outside, teeth,
                                    float(parameters.get("profile_shift", 0.0)),
                                    float(parameters.get("bevel_angle", 45.0)))


def bevel_apex_height(parameters):
    """Distance from the heel (sketch plane) to the cone apex of a Tredgold bevel gear,
    or None for bevel gears made before the true cone geometry existed."""
    if parameters.get("bevel_profile") != "tredgold":
        return None
    module = gear_module(parameters)
    delta = math.radians(float(parameters.get("bevel_angle", 45.0)))
    addendum = (1.0 + float(parameters.get("profile_shift", 0.0))) * module
    return module * int(parameters["teeth"]) / 2.0 / math.tan(delta) - addendum * math.sin(delta)


def make_gear_sketch(name, parameters, frame=None):
    """Build the editable XY profile of a rack-generated external gear (profile shift,
    backlash, undercut); a Tredgold bevel gear gets its heel section."""
    teeth = int(parameters["teeth"])
    tredgold = parameters.get("kind") == "bevel" and parameters.get("bevel_profile") == "tredgold"
    outline, info = external_gear_outline(
        gear_module(parameters), teeth, float(parameters.get("pressure_angle", 20.0)),
        float(parameters.get("profile_shift", 0.0)), float(parameters.get("backlash", 0.0)),
        float(parameters.get("tip_reduction", 0.0)),
        float(parameters.get("bevel_angle", 45.0)) if tredgold else None)
    root_radius = info["root_radius"]
    bore = float(parameters.get("bore_diameter", 0.0))
    if not math.isfinite(bore) or bore < 0 or bore >= 2.0 * root_radius:
        raise ValueError("Bore diameter must be zero or smaller than the gear root diameter.")
    sketch = Sketch("XY", name=name, frame=frame)
    vertices = [Vertex(x, y) for x, y in outline]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(
        Segment(vertices[i], vertices[(i + 1) % len(vertices)])
        for i in range(len(vertices)))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    if bore:
        sketch.circles.append(Circle(Vertex(0.0, 0.0), bore / 2.0))
    return sketch

# ── pump: hollow housing, lid with smooth round intake, and a bladed impeller (three bodies) ──
PUMP_ROLES = ("housing", "lid", "impeller")
PUMP_AXIAL_CLEARANCE = 0.6      # mm between the impeller and the floor / lid
PUMP_BLADE_ANGLE = 45.0         # blade angle from the tangent at every radius (backward curved)
PUMP_SEAL_HOUSING_SHARE = 0.6   # of the seal height is cut into the housing rim, the rest into the lid
PUMP_SEAL_LAND = 0.8            # mm of rim left standing on each side of the seal groove
PUMP_MIN_RIM = 2.0              # mm radial casing wall without a seal
PUMP_OUTLET_MIN_ROUND = 5.0     # mm of full round tube clear of the casing, before the extra length
PUMP_OUTLET_EXTRA = 5.0         # mm added to the outlet
PUMP_INTAKE_SHORTER = 5.0       # mm taken off the intake

def pump_default_plate(diameter, seal_height):
    """Thickness of floor and lid (it also sets the walls of the connection tubes)."""
    return max(2.0, 0.06 * diameter, (1.2 * seal_height + 1.6) if seal_height > 0 else 0.0)

def pump_min_rim(seal_thickness, seal_height):
    """Smallest radial wall (outer minus inner radius) that holds the seal."""
    if seal_thickness > 0 and seal_height > 0:
        return max(PUMP_MIN_RIM, seal_thickness + 2.0 * PUMP_SEAL_LAND)
    return PUMP_MIN_RIM

def pump_dimensions(p):
    """All derived dimensions of a pump from its parameters (outer and inner diameter, seal
    thickness, height, inlet / outlet
    angle, inlet / outlet bore diameter, shaft diameter, blade count, fixings, screw diameter,
    seal height);
    raises ValueError when the parts cannot fit."""
    D, H = float(p["diameter"]), float(p["height"])
    shaft, blades = float(p.get("shaft_diameter", 5.0)), int(p.get("blades", 6))
    screw, fixings = float(p.get("screw_diameter", 3.0)), int(p.get("fixings", 4))
    seal = float(p.get("seal_height", 0.0))
    common = p.get("port_diameter") or 0.25 * D          # pumps saved with one diameter for both
    d_in = float(p.get("inlet_diameter") or common)
    d_out = float(p.get("outlet_diameter") or common)
    if not all(math.isfinite(x) for x in (D, H, shaft, screw, seal, d_in, d_out)) \
            or D < 20.0 or shaft <= 0:
        raise ValueError("Pump diameter must be at least 20 mm and the shaft diameter positive.")
    if not 0 <= fixings <= 8 or not 1.0 <= screw <= 10.0:
        raise ValueError("Use 0 to 8 fixings and a screw diameter of 1 to 10 mm.")
    if not 0.0 <= seal <= 6.0:
        raise ValueError("The seal height is 0 (none) to 6 mm.")
    wall = pump_default_plate(D, seal)                   # floor and lid
    # pumps saved before inner diameter and seal thickness existed: rim = plate, seal 1.2 x height
    inner = float(p.get("inner_diameter") or D - 2.0 * wall)
    seal_t = float(p["seal_thickness"]) if p.get("seal_thickness") is not None else 1.2 * seal
    if not math.isfinite(inner) or not math.isfinite(seal_t) or not 0.0 <= seal_t <= 20.0:
        raise ValueError("The seal thickness is 0 (no seal) to 20 mm.")
    if seal_t <= 0:
        seal = 0.0                                       # no groove without a thickness
    ro = D / 2.0
    rc = inner / 2.0
    rim = ro - rc
    if rim < pump_min_rim(seal_t, seal) - 1e-6:
        raise ValueError(f"The outer diameter must be at least {inner + 2.0 * pump_min_rim(seal_t, seal):.1f} mm "
                         "for this inner diameter and seal.")
    if rc < 6.0:
        raise ValueError("The inner diameter is too small.")
    floor = wall
    chamber = H - floor
    back = max(1.5, 0.04 * D)
    d = {"D": D, "H": H, "wall": wall, "ro": ro, "rc": rc, "d_in": d_in, "d_out": d_out, "floor": floor,
         "chamber": chamber, "back": back, "shaft": shaft, "blades": blades,
         "gap": max(1.5, 0.06 * rc), "clr": PUMP_AXIAL_CLEARANCE,
         "tw": 0.8 * wall, "fixings": fixings, "screw": screw,
         "hub_r": shaft / 2.0 + max(2.0, 0.04 * D), "seal": seal}
    d["ri"] = rc - d["gap"]
    d["rb"] = d_in / 2.0                                # bore radius of the intake
    d["rt"] = d["rb"] + d["tw"]                         # outer radius of the intake tube
    d["rb_out"] = d_out / 2.0
    # the outlet is reinforced: a thicker tube wall (as far as it stays within the casing
    # height) and a solid full-height boss where the tube leaves the casing
    d["tw_out"] = max(d["tw"], min(1.5 * wall, H / 2.0 - d["rb_out"]))
    d["rt_out"] = d["rb_out"] + d["tw_out"]
    d["boss"] = math.sqrt(max(ro * ro - rc * rc, 0.0)) + wall
    # distance along the outlet at which the whole round tube has left the casing (its side
    # towards the pump axis stays inside longest); a full circle must stand free beyond it
    deepest = max(rc - 2.0 * d["rb_out"] - d["tw_out"], 0.0)
    d["outlet_clear"] = math.sqrt(max(ro * ro - deepest * deepest, 0.0))
    d["stub"] = max(d["boss"] + 0.25 * D, d["outlet_clear"] + PUMP_OUTLET_MIN_ROUND) + PUMP_OUTLET_EXTRA
    d["bend"] = 1.4 * d["rt"]                           # centre-line radius of the intake elbow
    d["zc"] = wall + d["bend"]                          # height of the intake axis when horizontal
    tilt = float(p.get("inlet_tilt", 0.0))              # 0 = horizontal, 90 = straight up
    if not 0.0 <= tilt <= 90.0:
        raise ValueError("The inlet tilt is 0 (horizontal) to 90 degrees (straight up).")
    d["tilt"] = math.radians(tilt)
    d["straight"] = max(_pump_intake_length(d) - d["bend"], 0.2 * D)    # tube after the bend
    d["eye"] = max(d["rb"], d["hub_r"] + 1.5)           # opening of the lid towards the impeller
    d["h_imp"] = chamber - 2.0 * d["clr"]
    d["lug_r"] = screw / 2.0 + 2.8                      # half width of a screw lug, and its round end
    d["lug_ring"] = ro + screw / 2.0 + 1.0              # screw circle: the holes lie outside the casing
    d["head_r"] = screw / 2.0 + 2.2                     # room a screw head needs
    d["seal_housing"] = PUMP_SEAL_HOUSING_SHARE * seal
    d["seal_lid"] = seal - d["seal_housing"]
    d["rim"] = rim
    d["seal_width"] = seal_t if seal > 0 else 0.0
    d["seal_mid"] = rc + rim / 2.0
    if blades < 2 or blades > 16:
        raise ValueError("A pump impeller has 2 to 16 blades.")
    for label, value in (("inlet", d_in), ("outlet", d_out)):
        if value < 4.0 or value > 0.7 * rc:
            raise ValueError(f"The {label} diameter does not fit the housing diameter "
                             f"(4 to {0.7 * rc:.1f} mm).")
    if d["rb_out"] > H / 2.0 - wall - 0.5:
        raise ValueError(f"The outlet does not fit the housing height: increase the height or reduce the "
                         f"outlet diameter (up to {max(H - 2.0 * wall - 1.0, 0.0):.1f} mm).")
    if d["h_imp"] < d["back"] + 3.0:
        raise ValueError("The pump is too low for the impeller: increase the height.")
    if shaft / 2.0 + 1.0 >= d["hub_r"] or d["eye"] > 0.7 * d["ri"] or d["eye"] - d["rb"] > 2.5 * wall:
        raise ValueError("The shaft or inlet diameter does not fit this pump diameter.")
    sweep = math.pi / 2.0 - d["tilt"]                    # angle of the intake bend
    end_z = wall + d["bend"] * math.sin(sweep) + d["straight"] * math.cos(sweep)
    d["lid_h"] = max(wall + (d["bend"] + d["rt"]) * math.sin(sweep), end_z + d["rt"] * math.sin(sweep))
    d["intake_s"] = d["bend"] * (1.0 - math.cos(sweep)) + d["straight"] * math.sin(sweep) \
        + d["rt"] * math.cos(sweep)                      # how far the intake reaches sideways
    return d

# rough performance estimate (water, 20 degC); the factors are engineering guesses, not fits
PUMP_ESTIMATE_SPEEDS = (60, 600, 3000)  # rpm always listed in the panel
PUMP_SHUTOFF_FACTOR = 0.65      # share of the Euler head (with slip) that is left at zero flow
PUMP_INTAKE_LOSS = 1.0          # loss coefficient on the intake bore velocity (bend, eye)
PUMP_OUTLET_LOSS = 1.5          # on the outlet bore velocity (round chamber without volute, exit)
PUMP_EFFICIENCY = 0.30          # shaft to water, around half of the free flow
PUMP_LOW_REYNOLDS = 2.0e4       # below this tip Reynolds number the estimate is hardly meaningful

def pump_performance(d, rpm):
    """Rough pressure and flow of the pump at `rpm` from its dimensions `d`: Euler head with
    Wiesner slip, less the velocity losses in the two bores; no hoses, no lift. Returns
    shut-off pressure (Pa), free flow (L/min), pressure (Pa) and shaft power (W) at half
    the free flow, and the impeller tip Reynolds number."""
    rho, nu, g = 998.0, 1.0e-6, 9.81
    thick = max(1.6, 0.03 * d["D"]) / 1000.0
    d2 = 2.0 * d["ri"] / 1000.0 - thick                          # blade tip diameter (m)
    width = (d["h_imp"] - d["back"]) / 1000.0                    # blade height
    blades, beta = d["blades"], math.radians(PUMP_BLADE_ANGLE)
    open_share = max(1.0 - blades * thick / (math.pi * d2 * math.sin(beta)), 0.3)
    outflow_area = math.pi * d2 * width * open_share
    slip = max(1.0 - math.sqrt(math.sin(beta)) / blades ** 0.7, 0.2)
    u2 = math.pi * d2 * rpm / 60.0
    shutoff = PUMP_SHUTOFF_FACTOR * slip * u2 * u2 / g           # head (m)
    area_in = math.pi * (d["d_in"] / 2000.0) ** 2
    area_out = math.pi * (d["d_out"] / 2000.0) ** 2
    square = (PUMP_INTAKE_LOSS / area_in ** 2 + PUMP_OUTLET_LOSS / area_out ** 2) / (2.0 * g)
    linear = PUMP_SHUTOFF_FACTOR * u2 / (g * outflow_area * math.tan(beta))   # backward curved blades
    flow = (-linear + math.sqrt(linear * linear + 4.0 * square * shutoff)) / (2.0 * square)
    half = flow / 2.0
    half_head = shutoff - linear * half - square * half * half
    return {"shutoff_pa": rho * g * shutoff, "free_lpm": flow * 60000.0,
            "half_pa": rho * g * half_head, "half_power_w": rho * g * half_head * half / PUMP_EFFICIENCY,
            "reynolds": u2 * d2 / nu}

def pump_estimate_html(d, speeds):
    """The estimate table of the pump panel."""
    def number(value):
        if value >= 100.0:
            return f"{value:.0f}"
        return f"{value:.1f}" if value >= 10.0 else f"{value:.2g}"
    rows, slow = [], False
    for rpm in sorted(set(speeds)):
        r = pump_performance(d, rpm)
        mark = "*" if r["reynolds"] < PUMP_LOW_REYNOLDS else ""
        slow = slow or bool(mark)
        cells = (f"{rpm:g}{mark}", number(r["shutoff_pa"] / 1000.0), number(r["free_lpm"]),
                 number(r["half_pa"] / 1000.0), number(r["half_power_w"]))
        rows.append("<tr>" + "".join(f"<td align='right'>{c}&nbsp;</td>" for c in cells) + "</tr>")
    head = ("rpm", "max.<br>kPa", "max.<br>L/min", "kPa at<br>\u00bd flow", "shaft<br>W")
    return ("<table cellspacing='0' cellpadding='1' width='100%'><tr>"
            + "".join(f"<th align='right'>{c}&nbsp;</th>" for c in head) + "</tr>" + "".join(rows)
            + "</table>Rough hand estimate for water without hoses or lift, about \u00b130\u201350 %; "
              "not measured or simulated. 10 kPa \u2248 1 m of water."
            + (" <br>* Very slow: viscosity and friction dominate; expect practically no pumping."
               if slow else ""))

def pump_part_height(role, d):
    return {"housing": d["H"], "lid": d["lid_h"], "impeller": d["h_imp"]}[role]

def pump_part_origin_z(role, d):
    """World Z of the part's base: the casing on the floor, the lid on the casing rim, the
    impeller lifted by the axial clearance (assembled position)."""
    return {"housing": 0.0, "lid": d["H"], "impeller": d["floor"] + d["clr"]}[role]

def _pump_part_reach(role, d):
    """Largest distance of a part from its own axis, whatever the port angles are."""
    if role == "impeller":
        return d["ri"]
    reach = max(d["ro"], d["lug_ring"] + d["lug_r"] if d["fixings"] else 0.0)
    if role == "lid":
        return max(reach, math.hypot(_pump_intake_length(d), d["rt"]))
    corners = _pump_outlet_polygon(d, 0.0, -d["tw_out"], 2.0 * d["rb_out"] + d["tw_out"], d["stub"])
    return max([reach] + [math.hypot(x, y) for x, y in corners])

def pump_part_origins(d, side_by_side):
    """Position of each part's base. Assembled: the pump axis with the parts stacked. Side by
    side: all on the XY plane in a row along +X, housing at the origin; the spacing does not
    depend on the port angles, so the parts stay put while an angle is turned."""
    if not side_by_side:
        return {role: np.array([0.0, 0.0, pump_part_origin_z(role, d)]) for role in PUMP_ROLES}
    gap = max(5.0, 0.1 * d["D"])
    origins, x, previous = {}, 0.0, None
    for role in PUMP_ROLES:
        reach = _pump_part_reach(role, d)
        if previous is not None:
            x += previous + gap + reach
        origins[role] = np.array([x, 0.0, 0.0])
        previous = reach
    return origins

def _pump_strip(angle, s0, s1, a0, a1):
    """Rectangle in the XY plane: along direction `angle` from s0 to s1, lateral (counter-
    clockwise side positive) from a0 to a1."""
    ux, uy = math.cos(angle), math.sin(angle)
    nx, ny = -uy, ux
    return [(s0 * ux + a0 * nx, s0 * uy + a0 * ny), (s1 * ux + a0 * nx, s1 * uy + a0 * ny),
            (s1 * ux + a1 * nx, s1 * uy + a1 * ny), (s0 * ux + a1 * nx, s0 * uy + a1 * ny)]

def _pump_outlet_polygon(d, outlet_angle, a0, a1, length):
    """Footprint of the tangential outlet: lateral 0 is the tangent line at the chamber circle
    (the water leaves counter-clockwise), positive towards the pump centre."""
    outlet = math.radians(float(outlet_angle))
    px, py = d["rc"] * math.cos(outlet), d["rc"] * math.sin(outlet)
    return [(x + px, y + py) for x, y in _pump_strip(outlet + math.pi / 2.0, 0.0, length, a0, a1)]

def _pump_intake_length(d):
    return d["ro"] + 0.3 * d["D"] - PUMP_INTAKE_SHORTER

def _pump_point_polygon_distance(point, polygon):
    x, y = point
    inside = False
    best = float("inf")
    for i in range(len(polygon)):
        (x0, y0), (x1, y1) = polygon[i], polygon[(i + 1) % len(polygon)]
        if (y0 > y) != (y1 > y) and x < x0 + (y - y0) * (x1 - x0) / (y1 - y0):
            inside = not inside
        dx, dy = x1 - x0, y1 - y0
        t = 0.0 if dx == dy == 0 else max(0.0, min(1.0, ((x - x0) * dx + (y - y0) * dy) / (dx * dx + dy * dy)))
        best = min(best, math.hypot(x - x0 - t * dx, y - y0 - t * dy))
    return 0.0 if inside else best

def _pump_fixing_margin(p, d, outlet_clearance):
    """margin(angle in rad) of a screw lug: negative where its hole would come within
    `outlet_clearance` of the outlet bore or its screw head under the intake tube."""
    outlet = _pump_outlet_polygon(d, p["outlet_angle"], 0.0, d["d_out"], d["stub"] + d["wall"] + 1.0)
    tube = _pump_strip(math.radians(float(p["inlet_angle"])), -d["rt"], max(d["rt"], d["intake_s"]),
                       -d["rt"], d["rt"])

    def margin(angle):
        x, y = d["lug_ring"] * math.cos(angle), d["lug_ring"] * math.sin(angle)
        return min(_pump_point_polygon_distance((x, y), outlet) - outlet_clearance,
                   _pump_point_polygon_distance((x, y), tube) - d["head_r"])
    return margin

def _pump_even_angles(first_deg, count):
    return [math.radians(first_deg) + 2.0 * math.pi * k / count for k in range(count)]

def pump_free_fixing_angle(p, d, wanted):
    """The fixing angle (deg) nearest to `wanted` at which all evenly spaced lugs are free,
    or None when no rotation fits that many."""
    count = d["fixings"]
    if count <= 0:
        return wanted
    margin = _pump_fixing_margin(p, d, 0.5 * d["screw"] + 1.5)
    for step in range(721):
        for sign in (1.0, -1.0):
            angle = wanted + sign * 0.5 * step
            if all(margin(t) >= 0.0 for t in _pump_even_angles(angle, count)):
                return (angle + 360.0) % 360.0 if abs(angle) > 360.0 else angle
    return None

def pump_fixing_angles(p, d):
    """Angles (rad) of the screw lugs, shared by housing and lid: evenly spaced (360 / count)
    from the fixing angle. Pumps saved without a fixing angle keep their automatic places."""
    count = d["fixings"]
    if count <= 0:
        return []
    if p.get("fixing_angle") is not None:
        wanted = float(p["fixing_angle"])
        margin = _pump_fixing_margin(p, d, 0.5 * d["screw"] + 1.5)
        angles = _pump_even_angles(wanted, count)
        if all(margin(t) >= 0.0 for t in angles):
            return angles
        free = pump_free_fixing_angle(p, d, wanted)
        raise ValueError(
            f"No evenly spaced place for {count} fixings between the outlet and the inlet: use fewer."
            if free is None else
            f"A fixing meets the outlet or the intake at this fixing angle; the nearest free one is "
            f"{free:g}\u00b0.")
    return _pump_automatic_fixing_angles(p, d)

def _pump_automatic_fixing_angles(p, d):
    """Placement of pumps saved before the fixing angle existed: the lugs are spread over
    the free positions as evenly as those allow."""
    count = d["fixings"]
    outlet = _pump_outlet_polygon(d, p["outlet_angle"], 0.0, d["d_out"], d["stub"] + d["wall"] + 1.0)
    tube = _pump_strip(math.radians(float(p["inlet_angle"])), -d["rt"], max(d["rt"], d["intake_s"]),
                       -d["rt"], d["rt"])
    need_outlet = 0.5 * d["screw"] + 1.2 + d["tw"]
    need_tube = d["head_r"]

    def margin(angle):
        x, y = d["lug_ring"] * math.cos(angle), d["lug_ring"] * math.sin(angle)
        return min(_pump_point_polygon_distance((x, y), outlet) - need_outlet,
                   _pump_point_polygon_distance((x, y), tube) - need_tube)
    free = [math.radians(a) for a in range(360) if margin(math.radians(a)) >= 0.0]
    gap = 2.0 * math.asin(min(1.0, (2.0 * d["lug_r"] + 1.0) / (2.0 * d["lug_ring"])))   # lugs must not touch

    def apart(a, b):
        delta = abs(a - b) % (2.0 * math.pi)
        return min(delta, 2.0 * math.pi - delta)
    chosen = []
    if free:
        runs, run = [], [free[0]]
        for angle in free[1:]:
            if angle - run[-1] <= math.radians(1.01):
                run.append(angle)
            else:
                runs.append(run); run = [angle]
        runs.append(run)
        if len(runs) > 1 and 2.0 * math.pi - runs[-1][-1] <= math.radians(1.01) + 1e-9 \
                and runs[0][0] <= math.radians(1.01):
            runs[0] = runs.pop() + runs[0]
        largest = max(runs, key=len)
        chosen = [largest[len(largest) // 2]]
        while len(chosen) < count:
            candidate = max(free, key=lambda a: min(apart(a, c) for c in chosen))
            if min(apart(candidate, c) for c in chosen) < gap:
                break
            chosen.append(candidate)
    if len(chosen) < count:
        raise ValueError("No room for that many fixings between the outlet and the inlet: use fewer.")
    return sorted(chosen)

def _pump_prism(frame, z0, h, polygon=None, circles=()):
    """Prism from one polygon and / or circles, each a radius or (radius, x, y); with a
    polygon-free profile of several circles the inner ones are holes."""
    sketch = Sketch("XY", name="pump", frame=frame)
    if polygon is not None:
        vertices = [Vertex(x, y) for x, y in polygon]
        sketch.vertices.extend(vertices)
        sketch.segments.extend(Segment(vertices[i], vertices[(i + 1) % len(vertices)])
                               for i in range(len(vertices)))
    for circle in circles:
        radius, cx, cy = circle if isinstance(circle, tuple) else (circle, 0.0, 0.0)
        sketch.circles.append(Circle(Vertex(cx, cy), radius))
    return extrude_profile(sketch.profile_loop_edges(), h, frame, z0)

def _pump_join(base, parts, union=True):
    result = csg_subtract(base, parts, label="", union=union)
    if not _mesh_is_closed(result[1]):
        raise ValueError("The pump part could not be built as a closed solid.")
    return result

def _pump_lug(d, frame, angle, z0, h):
    """One screw lug: a half circle around the screw hole whose two sides run straight into
    the casing, so the lug keeps its full width where it joins (no narrow neck)."""
    half = d["lug_r"]
    ux, uy = math.cos(angle), math.sin(angle)
    nx, ny = -uy, ux

    def point(radial, across):
        return Vertex(radial * ux + across * nx, radial * uy + across * ny)
    inner = math.sqrt(max(d["ro"] ** 2 - half ** 2, 0.0)) - 0.5      # just inside the casing
    start, begin = point(inner, -half), point(d["lug_ring"], -half)
    end, finish = point(d["lug_ring"], half), point(inner, half)
    centre = point(d["lug_ring"], 0.0)
    sketch = Sketch("XY", name="pump", frame=frame)
    sketch.vertices.extend((start, begin, end, finish, centre))
    sketch.segments.extend((Segment(start, begin), Segment(end, finish), Segment(finish, start)))
    sketch.arcs.append(Arc(centre, begin, end))
    return extrude_profile(sketch.profile_loop_edges(), h, frame, z0)

def _pump_lugs(d, frame, angles, z0, h):
    return [_pump_lug(d, frame, t, z0, h) for t in angles]

def _pump_holes(d, frame, angles, radius, z0, h):
    return [_pump_prism(frame, z0, h, circles=((radius, d["lug_ring"] * math.cos(t),
                                                d["lug_ring"] * math.sin(t)),))
            for t in angles]

def _pump_tube_frame(frame, point, angle):
    """Frame whose Z axis runs horizontally along `angle` (rad from the part's +X) through
    `point` (part coordinates): prisms made in it are round tubes along that direction."""
    origin, u, v, w = (np.asarray(axis, float) for axis in frame)
    direction = math.cos(angle) * u + math.sin(angle) * v
    return (origin + point[0] * u + point[1] * v + point[2] * w, w, np.cross(direction, w), direction)

def _pump_intake_sweep(frame, angle, bend, z_bend, radius, z_start, straight, tilt):
    """One round solid along the whole intake centre line: up the part's Z axis from z_start
    to z_bend, through the bend towards `angle`, then `straight` on, rising at `tilt` (rad,
    0 = horizontal after a quarter bend, 90 degrees = straight up without a bend). It is a
    single mesh on purpose: straight and bent pieces joined end to end leave thin walls
    inside the passage wherever rounding keeps their end faces from coinciding."""
    origin, u, v, w = (np.asarray(axis, float) for axis in frame)
    direction = math.cos(angle) * u + math.sin(angle) * v
    side = np.cross(w, direction)
    sweep = math.pi / 2.0 - tilt
    stations = []                                 # (point, tangent) as (along direction, height)
    if z_bend - z_start > 1e-9:
        stations.append(((0.0, z_start), (0.0, 1.0)))
    if sweep > 1e-6:
        quarter = max(12, curve_segments(bend, math.pi / 2.0, hi=96))
        bend_steps = max(2, int(math.ceil(quarter * sweep / (math.pi / 2.0))))
        angles = [sweep * i / bend_steps for i in range(bend_steps + 1)]
    else:
        sweep, angles = 0.0, [0.0]
    for t in angles:
        stations.append(((bend - bend * math.cos(t), z_bend + bend * math.sin(t)),
                         (math.sin(t), math.cos(t))))
    (s_last, z_last), (ts, tz) = stations[-1]
    stations.append(((s_last + straight * ts, z_last + straight * tz), (ts, tz)))
    count = max(24, curve_segments(radius, 2.0 * math.pi, hi=128))
    verts, rings = [], []
    for (s_pos, z_pos), (ts, tz) in stations:
        centre = origin + s_pos * direction + z_pos * w
        inward = -tz * direction + ts * w          # in the bend plane, square to the path
        rings.append(range(len(verts), len(verts) + count))
        for k in range(count):
            phi = 2.0 * math.pi * k / count
            verts.append(centre + radius * (math.cos(phi) * inward + math.sin(phi) * side))
    tris = []
    for lower, upper in zip(rings[:-1], rings[1:]):
        for k in range(count):
            k2 = (k + 1) % count
            tris.append((lower[k], lower[k2], upper[k2]))
            tris.append((lower[k], upper[k2], upper[k]))
    side_ids = list(range(len(tris)))
    caps = []
    for ring, station, sign in ((rings[0], stations[0], -1.0), (rings[-1], stations[-1], 1.0)):
        (s_pos, z_pos), (ts, tz) = station
        centre_index = len(verts)
        verts.append(origin + s_pos * direction + z_pos * w)
        first = len(tris)
        for k in range(count):
            k2 = (k + 1) % count
            pair = (ring[k], ring[k2]) if sign > 0 else (ring[k2], ring[k])
            tris.append((centre_index, pair[0], pair[1]))
        caps.append((list(range(first, len(tris))), centre_index, sign * (ts * direction + tz * w)))
    V = np.asarray(verts, float)
    T = np.asarray(tris, int)
    if np.einsum("ij,ij->i", V[T[:, 0]], np.cross(V[T[:, 1]], V[T[:, 2]])).sum() < 0:
        tris = [(i, k, j) for i, j, k in tris]    # wind the triangles outwards
    faces = [{"kind": "side", "tris": side_ids, "planar": False}]
    for ids, centre_index, normal in caps:
        normal = _unit(normal)
        x_axis = _unit(side)
        faces.append({"kind": "top", "tris": ids, "planar": True,
                      "frame": (V[centre_index], x_axis, np.cross(normal, x_axis), normal),
                      "boundary": [("circle", V[centre_index], radius)]})
    return [tuple(p) for p in V.tolist()], [tuple(int(i) for i in t) for t in tris], faces

def _pump_revolved(frame, points):
    """Solid of revolution about the part's Z axis from a polygon of (radius, z) points."""
    origin, u, v, w = (np.asarray(axis, float) for axis in frame)
    profile_frame = (origin, u, w, np.cross(u, w))
    sketch = Sketch("XY", name="pump", frame=profile_frame)
    vertices = [Vertex(r, z) for r, z in points]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(Segment(vertices[i], vertices[(i + 1) % len(vertices)])
                           for i in range(len(vertices)))
    return revolve_profile(sketch.profile_loop_edges(), profile_frame, origin, w, 0.0, 2.0 * math.pi, 0.0)

def pump_housing_mesh(d, frame, p):
    rb, rt, wall, stub = d["rb_out"], d["rt_out"], d["wall"], d["stub"]
    angles = pump_fixing_angles(p, d)
    outlet = math.radians(float(p["outlet_angle"]))
    # round outlet: the tube's inner edge touches the chamber circle at the outlet angle and
    # leaves counter-clockwise along the tangent, at half the housing height
    axis_point = ((d["rc"] - rb) * math.cos(outlet), (d["rc"] - rb) * math.sin(outlet), d["H"] / 2.0)
    tube = _pump_tube_frame(frame, axis_point, outlet + math.pi / 2.0)
    body = _pump_prism(frame, 0.0, d["H"], circles=(d["ro"],))
    boss = _pump_outlet_polygon(d, p["outlet_angle"], -d["tw_out"], 2.0 * rb + d["tw_out"], d["boss"])
    body = _pump_join(body, [_pump_prism(tube, 0.0, stub, circles=(rt,)),
                             _pump_prism(frame, 0.0, d["H"], polygon=boss)]
                      + _pump_lugs(d, frame, angles, 0.0, d["H"]))
    cuts = [_pump_prism(frame, d["floor"], d["chamber"] + 1.0, circles=(d["rc"],)),
            _pump_prism(tube, 0.0, stub + wall + 1.0, circles=(rb,)),
            _pump_prism(frame, -1.0, d["floor"] + 2.0, circles=(d["shaft"] / 2.0 + 0.5,))]
    cuts += _pump_holes(d, frame, angles, 0.85 * d["screw"] / 2.0, -1.0, d["H"] + 2.0)   # pilot holes
    if d["seal_housing"] > 0:                                    # groove in the rim for the seal
        r_in, r_out = d["seal_mid"] - d["seal_width"] / 2.0, d["seal_mid"] + d["seal_width"] / 2.0
        cuts.append(_pump_prism(frame, d["H"] - d["seal_housing"], d["seal_housing"] + 1.0,
                                circles=(r_out, r_in)))
    return _pump_join(body, cuts, union=False)

def pump_lid_mesh(d, frame, p):
    """Lid: disc with screw lugs and a round intake. The intake arrives horizontally or tilted
    upwards, bends and runs straight down into the eye above the impeller;
    a cone widens the eye towards the impeller."""
    wall, rb, rt, bend = d["wall"], d["rb"], d["rt"], d["bend"]
    straight, tilt = d["straight"], d["tilt"]
    angles = pump_fixing_angles(p, d)
    inlet = math.radians(float(p["inlet_angle"]))
    lid = _pump_prism(frame, 0.0, wall, circles=(d["ro"],))
    lid = _pump_join(lid, [_pump_intake_sweep(frame, inlet, bend, wall, rt, wall / 2.0, straight, tilt)]
                     + _pump_lugs(d, frame, angles, 0.0, wall))
    cuts = [_pump_intake_sweep(frame, inlet, bend, wall, rb, -1.0, straight + 1.0, tilt)]
    if d["eye"] - rb > 1e-6:                                     # bell mouth towards the impeller
        cuts += [_pump_prism(frame, -1.0, 1.0, circles=(d["eye"],)),
                 _pump_revolved(frame, [(0.6 * rb, -0.5), (d["eye"], -0.5), (d["eye"], 0.0),
                                        (rb - 0.05, wall * (d["eye"] - rb + 0.05) / (d["eye"] - rb)),
                                        (0.6 * rb, wall * (d["eye"] - rb + 0.05) / (d["eye"] - rb))])]
    cuts += _pump_holes(d, frame, angles, (d["screw"] + 0.4) / 2.0, -1.0, wall + 2.0)
    if d["seal_lid"] > 0:                                        # smaller groove for the seal
        r_in, r_out = d["seal_mid"] - d["seal_width"] / 2.0, d["seal_mid"] + d["seal_width"] / 2.0
        cuts.append(_pump_prism(frame, -1.0, d["seal_lid"] + 1.0, circles=(r_out, r_in)))
    return _pump_join(lid, cuts, union=False)

def pump_impeller_outline(d):
    """Outline of the hub together with all blades, as one polygon (counter-clockwise): the
    backward curved blades leave the hub through a fillet on both sides, so there is no step
    or notch at the root. Returns (points, fillet radius, root circle radius); with many
    blades the fillet gets smaller and, if the roots would still run into each other, the
    root circle larger."""
    ri, hub_r, bore, blades = d["ri"], d["hub_r"], d["shaft"] / 2.0, d["blades"]
    thick = max(1.6, 0.03 * d["D"])
    tan_b = math.tan(math.radians(PUMP_BLADE_ANGLE))
    r_ref = hub_r - 0.4                  # where the centre line of blade 0 crosses angle 0
    r_tip = ri - thick / 2.0             # so the square tip's corners stay within the backplate
    r_low = max(hub_r - 2.0 * thick, bore + 0.2)

    def side(r, sign):
        """Point on one flank at centre line radius r, and the flank's outward normal."""
        th = -math.log(r / r_ref) / tan_b                      # backward curved log spiral
        tx, ty = math.cos(th) + math.sin(th) / tan_b, math.sin(th) - math.cos(th) / tan_b
        length = math.hypot(tx, ty)
        nx, ny = -sign * ty / length, sign * tx / length
        return (r * math.cos(th) + nx * thick / 2.0, r * math.sin(th) + ny * thick / 2.0), (nx, ny)

    def root(sign, circle, fillet):
        """The fillet touching the flank and the root circle from outside: (flank parameter,
        fillet centre)."""
        def centre(r):
            (x, y), (nx, ny) = side(r, sign)
            return x + fillet * nx, y + fillet * ny

        def beyond(r):
            return math.hypot(*centre(r)) - (circle + fillet)
        low = r_low
        if beyond(low) >= 0.0:
            raise ValueError("The blade roots do not fit this hub.")
        for i in range(1, 401):
            high = r_low + (r_tip - r_low) * i / 400.0
            if beyond(high) >= 0.0:
                for _ in range(50):
                    middle = (low + high) / 2.0
                    low, high = (low, middle) if beyond(middle) >= 0.0 else (middle, high)
                return high, centre(high)
            low = high
        raise ValueError("The blades are too short for this hub.")

    pitch = 2.0 * math.pi / blades
    circle, fillet = hub_r, 1.2 * thick
    for _ in range(300):
        (r_right, f_right), (r_left, f_left) = root(-1.0, circle, fillet), root(1.0, circle, fillet)
        on_right = math.atan2(f_right[1], f_right[0])          # where the fillets meet the circle
        on_left = math.atan2(f_left[1], f_left[0])
        gap = pitch - (on_left - on_right) % (2.0 * math.pi)
        if 0.02 <= gap < pitch:
            break
        if fillet > 0.4:
            fillet *= 0.9
        else:
            circle += 0.1
    else:
        raise ValueError("The blade roots run into each other: use fewer blades or a larger pump.")

    def on_circle(angle):
        return circle * math.cos(angle), circle * math.sin(angle)

    def fillet_arc(centre, start, end):
        a0 = math.atan2(start[1] - centre[1], start[0] - centre[0])
        a1 = math.atan2(end[1] - centre[1], end[0] - centre[0])
        turn = (a1 - a0 + math.pi) % (2.0 * math.pi) - math.pi
        steps = max(4, int(math.ceil(abs(turn) / math.radians(8.0))))
        return [(centre[0] + fillet * math.cos(a0 + turn * i / steps),
                 centre[1] + fillet * math.sin(a0 + turn * i / steps)) for i in range(steps + 1)]
    samples = 32
    flank_right = [side(r_right + (r_tip - r_right) * i / samples, -1.0)[0] for i in range(samples + 1)]
    flank_left = [side(r_tip + (r_left - r_tip) * i / samples, 1.0)[0] for i in range(samples + 1)]
    steps = max(1, int(math.ceil(gap / math.radians(6.0))))
    one = (fillet_arc(f_right, on_circle(on_right), flank_right[0])[:-1]
           + flank_right                                           # out along one flank, the tip,
           + flank_left                                            # and back along the other
           + fillet_arc(f_left, flank_left[-1], on_circle(on_left))[1:]
           + [on_circle(on_left + gap * i / steps) for i in range(1, steps)])
    points = []
    for k in range(blades):
        c, sn = math.cos(pitch * k), math.sin(pitch * k)
        points += [(x * c - y * sn, x * sn + y * c) for x, y in one]
    return points, fillet, circle

def _pump_merge_smooth_walls(mesh, axis):
    """Join the upright face records that run smoothly into each other (flank strips, fillets,
    hub arcs) to one curved face each, so they shade smoothly and are picked as one surface.
    Sharp corners (more than 25 degrees) stay face borders."""
    V = np.asarray(mesh[0], float).reshape(-1, 3)
    T = np.asarray(mesh[1], int).reshape(-1, 3)
    faces = mesh[2]
    N = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])
    N /= np.maximum(np.linalg.norm(N, axis=1), 1e-30)[:, None]
    upright = np.abs(N @ np.asarray(axis, float)) < 0.2
    parent = list(range(len(faces)))

    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    owner = {}
    for index, face in enumerate(faces):
        for k in face["tris"]:
            if not upright[k]:
                continue
            a, b, c = (int(i) for i in T[k])
            for edge in ((a, b), (b, c), (c, a)):
                key = (min(edge), max(edge))
                if key not in owner:
                    owner[key] = (index, k)
                    continue
                other, k_other = owner[key]
                if other != index and float(N[k] @ N[k_other]) > math.cos(math.radians(25.0)):
                    parent[root(index)] = root(other)
    groups = {}
    for index, face in enumerate(faces):
        if face["tris"]:
            groups.setdefault(root(index), []).append(index)

    def line_key(prim):
        return tuple(sorted(tuple(np.round(np.asarray(p, float), 5)) for p in prim[1:3]))
    merged = []
    for members in sorted(groups.values(), key=min):
        if len(members) == 1:
            merged.append(faces[members[0]])
            continue
        prims = [prim for i in members for prim in faces[i].get("boundary", [])]
        lines = {}
        for prim in prims:
            if prim[0] == "line":
                lines[line_key(prim)] = lines.get(line_key(prim), 0) + 1
        merged.append({"kind": "side", "planar": False,
                       "tris": [k for i in members for k in faces[i]["tris"]],
                       # the borders between two strips are no edges of the joined surface
                       "boundary": [prim for prim in prims
                                    if prim[0] != "line" or lines[line_key(prim)] == 1]})
    return mesh[0], mesh[1], merged

def pump_impeller_mesh(d, frame):
    bore, back, h = d["shaft"] / 2.0, d["back"], d["h_imp"]
    plate = _pump_prism(frame, 0.0, back, circles=(d["ri"], bore))
    points = pump_impeller_outline(d)[0]
    sketch = Sketch("XY", name="pump", frame=frame)
    vertices = [Vertex(x, y) for x, y in points]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(Segment(vertices[i], vertices[(i + 1) % len(vertices)])
                           for i in range(len(vertices)))
    sketch.circles.append(Circle(Vertex(0.0, 0.0), bore))          # shaft bore: a hole
    upper = extrude_profile(sketch.profile_loop_edges(), h - back + 0.2, frame, back - 0.2)
    return _pump_join(plate, [upper])

def _pump_merge_flat_faces(mesh):
    """Join the face records of one flat surface. The booleans keep a record per tool, so the
    casing's bottom came out as disc + outlet boss + one per screw lug, and every border
    between them showed as a line across the surface. Records are joined when they lie in the
    same plane (same outward normal) and share a triangle edge."""
    V = np.asarray(mesh[0], float).reshape(-1, 3)
    T = np.asarray(mesh[1], int).reshape(-1, 3)
    faces = mesh[2]
    planes = {}
    for index, face in enumerate(faces):
        if not face["tris"]:
            continue
        P = V[T[face["tris"]]]
        normals = np.cross(P[:, 1] - P[:, 0], P[:, 2] - P[:, 0])
        total = normals.sum(axis=0)
        length = float(np.linalg.norm(total))
        if length < 1e-12:
            continue
        normal = total / length
        offsets = P.reshape(-1, 3) @ normal
        if float(np.ptp(offsets)) < 1e-5:                           # flat
            planes[index] = (normal, float(offsets.mean()))
    parent = list(range(len(faces)))

    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    owner = {}
    for index in planes:
        for k in faces[index]["tris"]:
            a, b, c = (int(i) for i in T[k])
            for edge in ((a, b), (b, c), (c, a)):
                other = owner.setdefault((min(edge), max(edge)), index)
                if other != index and float(planes[other][0] @ planes[index][0]) > 1.0 - 1e-8 \
                        and abs(planes[other][1] - planes[index][1]) < 1e-5:
                    parent[root(index)] = root(other)
    groups = {}
    for index, face in enumerate(faces):
        if face["tris"]:
            groups.setdefault(root(index), []).append(index)
    merged = []
    for members in sorted(groups.values(), key=min):
        largest = max(members, key=lambda i: len(faces[i]["tris"]))
        face = dict(faces[largest], tris=[k for i in members for k in faces[i]["tris"]])
        if len(members) > 1 and "frame" in face:
            face["planar"] = True
        merged.append(face)
    return mesh[0], mesh[1], refresh_face_boundaries(mesh[0], mesh[1], merged)

def pump_mesh(parameters, frame):
    """Mesh (verts, tris, faces) of one pump part (parameters["role"]) in its own frame."""
    d = pump_dimensions(parameters)
    role = parameters.get("role", "housing")
    if role == "housing":
        mesh = pump_housing_mesh(d, frame, parameters)
    elif role == "lid":
        mesh = pump_lid_mesh(d, frame, parameters)
    else:
        return _pump_merge_smooth_walls(_pump_merge_flat_faces(pump_impeller_mesh(d, frame)), frame[3])
    return _pump_merge_flat_faces(mesh)

def make_pump_sketch(name, parameters, frame=None):
    """Reference profile of a pump part: its outer circle (the shape itself is generated)."""
    d = pump_dimensions(parameters)
    role = parameters.get("role", "housing")
    sketch = Sketch("XY", name=name, frame=frame)
    sketch.circles.append(Circle(Vertex(0.0, 0.0), d["ri"] if role == "impeller" else d["ro"]))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch

def make_internal_gear_sketch(name, parameters, frame=None):
    """Build an annular ring gear with inward-facing involute teeth."""
    teeth = int(parameters["teeth"])
    outside_diameter = float(parameters["outside_diameter"])
    module = float(parameters.get("module", outside_diameter / (teeth + 7.5)))
    pressure_angle = float(parameters.get("pressure_angle", 20.0))
    if not math.isfinite(outside_diameter) or outside_diameter <= 0:
        raise ValueError("Ring outside diameter must be finite and positive.")
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Ring gear module must be finite and positive.")
    inner_outline = internal_gear_outline(module, teeth, pressure_angle,
                                          float(parameters.get("backlash", 0.0)))
    outer_radius = outside_diameter / 2.0
    if outer_radius <= max(math.hypot(x, y) for x, y in inner_outline):
        raise ValueError("Ring outside diameter leaves no material behind its teeth.")

    sketch = Sketch("XY", name=name, frame=frame)
    sketch.circles.append(Circle(Vertex(0.0, 0.0), outer_radius))
    vertices = [Vertex(x, y) for x, y in inner_outline]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(
        Segment(vertices[index], vertices[(index + 1) % len(vertices)])
        for index in range(len(vertices)))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch

def make_rack_sketch(name, parameters, frame=None):
    """Build a straight-sided involute-rack approximation with the given module."""
    module = float(parameters["module"])
    teeth = int(parameters["teeth"])
    pressure_angle = float(parameters.get("pressure_angle", 20.0))
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Rack module must be a finite positive number.")
    if teeth < 1:
        raise ValueError("A rack must have at least one tooth.")
    if not math.isfinite(pressure_angle) or not 10.0 <= pressure_angle <= 45.0:
        raise ValueError("Pressure angle must be between 10° and 45°.")

    backlash_factor = float(parameters.get("backlash", 0.1))
    if not math.isfinite(backlash_factor) or backlash_factor < 0:
        raise ValueError("Rack backlash must be a finite nonnegative module fraction.")
    tooth_radius = float(parameters.get("tooth_radius", 0.0))
    if not math.isfinite(tooth_radius) or tooth_radius < 0:
        raise ValueError("Rack tooth radius must be finite and nonnegative.")
    pitch = math.pi * module
    half_pitch_tooth = pitch / 4.0 - module * backlash_factor / 2.0
    tip_half_width = half_pitch_tooth - module * math.tan(math.radians(pressure_angle))
    root_half_width = half_pitch_tooth + 1.25 * module * math.tan(math.radians(pressure_angle))
    if tip_half_width <= 0 or root_half_width >= pitch / 2.0:
        raise ValueError("The rack tooth proportions are invalid for this pressure angle.")
    # body length: at least the toothed length; a longer rack gets flat lands at the root
    # line on both ends, with the teeth centred on the origin
    rack_length = float(parameters.get("rack_length", 0.0) or 0.0)
    if not math.isfinite(rack_length) or rack_length < 0:
        raise ValueError("Rack length must be a finite positive number.")
    end_length = float(parameters.get("end_length", 0.0) or 0.0)
    if not math.isfinite(end_length) or end_length < 0:
        raise ValueError("The flat end length must be zero or positive.")
    length = max(rack_length, teeth * pitch + 2.0 * end_length)
    base_y = -2.5 * module
    points = [(length / 2.0, base_y), (length / 2.0, -1.25 * module)]
    tip_corners = []
    for index in reversed(range(teeth)):
        center = (index + 0.5 - teeth / 2.0) * pitch
        first = len(points)
        points.extend(((center + root_half_width, -1.25 * module),
                       (center + tip_half_width, module),
                       (center - tip_half_width, module),
                       (center - root_half_width, -1.25 * module)))
        tip_corners.extend((first + 1, first + 2))
    points.extend(((-length / 2.0, -1.25 * module), (-length / 2.0, base_y)))

    sketch = Sketch("XY", name=name, frame=frame)
    rounded = {}
    trims = {}
    if tooth_radius > 0 and parameters.get("round_tips", False):
        for index in tip_corners:
            previous = np.asarray(points[index - 1], float)
            point = np.asarray(points[index], float)
            following = np.asarray(points[index + 1], float)
            incoming = _unit(point - previous)
            outgoing = _unit(following - point)
            toward_previous = _unit(previous - point)
            toward_following = _unit(following - point)
            interior_angle = math.acos(float(np.clip(
                np.dot(toward_previous, toward_following), -1.0, 1.0)))
            turn = incoming[0] * outgoing[1] - incoming[1] * outgoing[0]
            if turn <= 0 or interior_angle <= 0:
                raise ValueError("Rack tooth corners cannot be rounded with this profile.")
            trim = tooth_radius / math.tan(interior_angle / 2.0)
            trims[index] = trim
            center = point + _unit(toward_previous + toward_following) * \
                     (tooth_radius / math.sin(interior_angle / 2.0))
            rounded[index] = (point + toward_previous * trim,
                              point + toward_following * trim, center)
        for index in range(len(points)):
            following = (index + 1) % len(points)
            if trims.get(index, 0.0) + trims.get(following, 0.0) >= \
                    math.dist(points[index], points[following]) - 1e-9:
                raise ValueError("Rack tooth radius is too large; adjacent rounded corners overlap.")

    vertices = {index: Vertex(x, y) for index, (x, y) in enumerate(points)
                if index not in rounded}
    arcs = {}
    for index, (start, end, center) in rounded.items():
        arcs[index] = (Vertex(*start), Vertex(*end), Vertex(*center))
    for index in range(len(points)):
        following = (index + 1) % len(points)
        start = arcs[index][1] if index in arcs else vertices[index]
        end = arcs[following][0] if following in arcs else vertices[following]
        sketch.segments.append(Segment(start, end))
    sketch.arcs.extend(Arc(center, start, end) for start, end, center in arcs.values())
    sketch.vertices.extend(vertices.values())
    sketch.vertices.extend(vertex for arc in arcs.values() for vertex in arc)
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch

# ── timing-belt pulleys ──────────────────────────────────────────────────────────────────
# pitch, pitch-line offset (OD = z·p/π - 2·offset), groove depth and width at the outside
# diameter, groove form ("round": curvilinear GT2 / HTD, "trapezoid": T-series, 40°)
BELT_PROFILES = {
    "GT2_2mm": {"label": "GT2 2 mm", "pitch": 2.0, "offset": 0.254, "depth": 0.764, "width": 1.494, "form": "round"},
    "GT2_3mm": {"label": "GT2 3 mm", "pitch": 3.0, "offset": 0.381, "depth": 1.169, "width": 2.310, "form": "round"},
    "HTD_3M":  {"label": "HTD 3M", "pitch": 3.0, "offset": 0.381, "depth": 1.289, "width": 2.270, "form": "round"},
    "HTD_5M":  {"label": "HTD 5M", "pitch": 5.0, "offset": 0.5715, "depth": 2.199, "width": 3.781, "form": "round"},
    "T5":      {"label": "T5", "pitch": 5.0, "offset": 0.425, "depth": 1.190, "width": 3.264, "form": "trapezoid"},
}


def _mech_arc(center, radius, a0, a1, segments):
    return [(center[0] + radius * math.cos(a0 + (a1 - a0) * k / segments),
             center[1] + radius * math.sin(a0 + (a1 - a0) * k / segments)) for k in range(segments + 1)]


def _belt_groove_profile(profile, clearance):
    """Groove widened by `clearance` (mm, total); cross-section as (x, depth) points from the left edge at the outside diameter
    (depth 0) to the right edge; x is measured along the circumference from the groove centre."""
    depth = profile["depth"]
    half = profile["width"] / 2.0 + clearance / 2.0
    if profile["form"] == "round":
        # circular groove through both edges (depth 0) and the floor (x = 0, depth = depth);
        # centre at depth c, angle psi measured from the floor direction
        c = (depth * depth - half * half) / (2.0 * depth)
        radius = depth - c
        start, stop = math.atan2(-half, -c), math.atan2(half, -c)
        return [(radius * math.sin(start + (stop - start) * k / 16),
                 c + radius * math.cos(start + (stop - start) * k / 16)) for k in range(17)]
    flank = math.radians(20.0)                           # T-series: 40° included groove angle
    bottom = half - depth * math.tan(flank)
    if bottom <= 0.05 * half:
        raise ValueError("The trapezoid groove is too narrow for its depth.")
    return [(-half, 0.0), (-bottom, depth), (bottom, depth), (half, 0.0)]


def pulley_outline(profile_key, teeth, clearance=0.0):
    profile = BELT_PROFILES[profile_key]
    pitch = profile["pitch"]
    if teeth < 8:
        raise ValueError("A timing pulley needs at least 8 teeth.")
    outside_radius = teeth * pitch / math.pi / 2.0 - profile["offset"]
    groove = _belt_groove_profile(profile, clearance)
    span = (groove[-1][0] - groove[0][0]) / outside_radius
    if span >= 0.9 * 2.0 * math.pi / teeth:
        raise ValueError("Too few teeth for this belt profile (grooves would overlap).")
    if outside_radius - max(d for _, d in groove) <= 0.5:
        raise ValueError("The pulley is too small for this belt profile.")
    points = []
    for k in range(teeth):
        centre = 2.0 * math.pi * (k + 0.5) / teeth
        for x, depth in groove:
            angle = centre + x / outside_radius
            radius = outside_radius - depth
            points.append((radius * math.cos(angle), radius * math.sin(angle)))
        # land (tooth top) up to the next groove, sampled on the outside circle
        land_from = centre + span / 2.0
        land_to = 2.0 * math.pi * (k + 1.5) / teeth - span / 2.0
        steps = max(1, int(math.ceil((land_to - land_from) / math.radians(6.0))))
        for s in range(1, steps):
            angle = land_from + (land_to - land_from) * s / steps
            points.append((outside_radius * math.cos(angle), outside_radius * math.sin(angle)))
    return points, {"outside_diameter": 2.0 * outside_radius,
                    "pitch_diameter": teeth * pitch / math.pi,
                    "root_radius": outside_radius - max(d for _, d in groove)}


# ── roller-chain sprockets (ISO 606 tooth form) ──────────────────────────────────────────
CHAIN_SIZES = {
    "04C": ("04C / ANSI 25", 6.35, 3.30, 3.10),
    "06C": ("06C / ANSI 35", 9.525, 5.08, 4.68),
    "08A": ("08A / ANSI 40", 12.70, 7.92, 7.85),
    "10A": ("10A / ANSI 50", 15.875, 10.16, 9.40),
    "12A": ("12A / ANSI 60", 19.05, 11.91, 12.57),
    "05B": ("05B", 8.00, 5.00, 3.00),
    "06B": ("06B", 9.525, 6.35, 5.72),
    "08B": ("08B", 12.70, 8.51, 7.75),
    "10B": ("10B", 15.875, 10.16, 9.65),
    "12B": ("12B", 19.05, 12.07, 11.68),
    "081": ("Bicycle 1/2 × 1/8 in", 12.70, 7.75, 3.30),
    "BIKE332": ("Bicycle 1/2 × 3/32 in", 12.70, 7.75, 2.38),
}


def sprocket_geometry(chain_key, teeth):
    _, pitch, roller, inner_width = CHAIN_SIZES[chain_key]
    z = int(teeth)
    if z < 6:
        raise ValueError("A sprocket needs at least 6 teeth.")
    pitch_d = pitch / math.sin(math.pi / z)
    tip_d = min(pitch * (0.6 + 1.0 / math.tan(math.pi / z)), pitch_d + 1.25 * pitch - roller)
    seat_r = 0.505 * roller + 0.069 * roller ** (1.0 / 3.0)      # ISO 606 r_i (max)
    seat_angle = math.radians(130.0 - 90.0 / z)                   # between α_min and α_max
    flank_r = (0.12 * roller * (z + 2) + 0.008 * roller * (z * z + 180)) / 2.0   # mid r_e
    width = (0.93 if pitch <= 12.7 else 0.95) * inner_width      # tooth width b_f1
    return {"pitch": pitch, "roller": roller, "pitch_diameter": pitch_d, "outside_diameter": tip_d,
            "seat_radius": seat_r, "seat_angle": seat_angle, "flank_radius": flank_r,
            "tooth_width": width, "root_diameter": pitch_d - 2.0 * seat_r}


def _mech_circle_intersections(c0, r0, c1, r1):
    dx, dy = c1[0] - c0[0], c1[1] - c0[1]
    d = math.hypot(dx, dy)
    if d < 1e-12 or d > r0 + r1 or d < abs(r0 - r1):
        return []
    a = (r0 * r0 - r1 * r1 + d * d) / (2 * d)
    h = math.sqrt(max(r0 * r0 - a * a, 0.0))
    mx, my = c0[0] + a * dx / d, c0[1] + a * dy / d
    return [(mx + h * dy / d, my - h * dx / d), (mx - h * dy / d, my + h * dx / d)]


def _mech_polar(p):
    return math.atan2(p[1], p[0])


def sprocket_outline(chain_key, teeth):
    g = sprocket_geometry(chain_key, teeth)
    z = int(teeth)
    R, Ra = g["pitch_diameter"] / 2.0, g["outside_diameter"] / 2.0
    ri, re, alpha = g["seat_radius"], g["flank_radius"], g["seat_angle"]
    # per gap: roller seat centre c, and for its low / high side (by polar angle) the seat
    # end e, the seat angle a about c and the flank centre f (flank tangent to the seat)
    gaps = []
    for k in range(z):
        theta = 2.0 * math.pi * k / z
        c = (R * math.cos(theta), R * math.sin(theta))
        inward = theta + math.pi
        sides = []
        for sign in (-1.0, 1.0):
            a = inward + sign * alpha / 2.0
            e = (c[0] + ri * math.cos(a), c[1] + ri * math.sin(a))
            f = (c[0] + (ri + re) * math.cos(a), c[1] + (ri + re) * math.sin(a))
            sides.append({"a": a, "e": e, "f": f})
        sides.sort(key=lambda s: (_mech_polar(s["e"]) - theta + math.pi) % (2 * math.pi) - math.pi)
        gaps.append({"c": c, "low": sides[0], "high": sides[1]})

    def tip_point(side):
        hits = _mech_circle_intersections(side["f"], re, (0.0, 0.0), Ra)
        if not hits:
            raise ValueError("The sprocket tooth flank does not reach the tip circle.")
        return min(hits, key=lambda p: math.dist(p, side["e"]))

    # each tooth ends at the tip circle, or pointed where its two flanks meet below it
    for k in range(z):
        high, low = gaps[k]["high"], gaps[(k + 1) % z]["low"]
        ph, pl = tip_point(high), tip_point(low)
        span = (_mech_polar(pl) - _mech_polar(ph)) % (2 * math.pi)
        if span > math.pi:                                   # the flanks cross first
            hits = _mech_circle_intersections(high["f"], re, low["f"], re)
            if not hits:
                raise ValueError("Sprocket teeth cannot be formed; use more teeth.")
            mid = ((ph[0] + pl[0]) / 2.0, (ph[1] + pl[1]) / 2.0)
            ph = pl = min(hits, key=lambda p: math.dist(p, mid))
        high["tip"], low["tip"] = ph, pl

    def flank(side):
        f, e, tip = side["f"], side["e"], side["tip"]
        a0 = math.atan2(e[1] - f[1], e[0] - f[0])
        a1 = math.atan2(tip[1] - f[1], tip[0] - f[0])
        while a1 - a0 > math.pi: a1 -= 2 * math.pi
        while a1 - a0 < -math.pi: a1 += 2 * math.pi
        return _mech_arc(f, re, a0, a1, 8)                           # seat end -> tip

    points = []
    for k in range(z):
        gap = gaps[k]
        low, high = flank(gap["low"]), flank(gap["high"])
        seat = _mech_arc(gap["c"], ri, gap["low"]["a"], gap["high"]["a"], 12)
        points.extend(low[::-1][:-1] + seat + high[1:])
        start, stop = _mech_polar(gap["high"]["tip"]), _mech_polar(gaps[(k + 1) % z]["low"]["tip"])
        sweep = (stop - start) % (2 * math.pi)
        if sweep > 1e-9 and sweep < math.pi:                   # land on the tip circle
            steps = max(1, int(math.ceil(sweep / math.radians(4.0))))
            points.extend((Ra * math.cos(start + sweep * s / steps), Ra * math.sin(start + sweep * s / steps))
                          for s in range(1, steps))
    # a pointed tooth: its tip point appears twice in a row
    cleaned = [p for i, p in enumerate(points) if math.dist(p, points[i - 1]) > 1e-9]
    return cleaned, g


# ── ratchet wheel and pawl ───────────────────────────────────────────────────────────────
def ratchet_points(teeth, outside_diameter, depth, undercut=5.0):
    """Sawtooth wheel turning freely counter-clockwise; each locking face at angle 2πk/z,
    leaning `undercut` degrees into its tooth gap (the gap lies clockwise of the face)."""
    z = int(teeth)
    ra = outside_diameter / 2.0
    rf = ra - depth
    if z < 6 or depth <= 0 or rf <= 0.3 * ra:
        raise ValueError("Ratchet tooth count, diameter or depth is invalid.")
    gamma = math.radians(undercut)
    pts, roots, tips = [], [], []
    for k in range(z):
        phi = 2.0 * math.pi * k / z
        root = (rf * math.cos(phi), rf * math.sin(phi))
        # face direction: radial turned clockwise by the undercut angle
        d = (math.cos(phi - gamma), math.sin(phi - gamma))
        b = root[0] * d[0] + root[1] * d[1]
        s = -b + math.sqrt(b * b - (rf * rf - ra * ra))
        tip = (root[0] + s * d[0], root[1] + s * d[1])
        lean = (_mech_polar(tip) - phi + math.pi) % (2 * math.pi) - math.pi
        if lean < -0.45 * 2 * math.pi / z:
            raise ValueError("The undercut is too large for this tooth pitch.")
        pts += [root, tip]
        roots.append(root); tips.append(tip)
    return pts, roots, tips


def _mech_seg_cross(p1, p2, q1, q2):
    def orient(a, b, c): return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    d1, d2 = orient(q1, q2, p1), orient(q1, q2, p2)
    d3, d4 = orient(p1, p2, q1), orient(p1, p2, q2)
    return (d1 > 0) != (d2 > 0) and (d3 > 0) != (d4 > 0)


def _mech_inside(p, poly):
    x, y, inside = p[0], p[1], False
    for i in range(len(poly)):
        x1, y1 = poly[i]; x2, y2 = poly[i - 1]
        if (y1 > y) != (y2 > y) and x < x1 + (y - y1) * (x2 - x1) / (y2 - y1):
            inside = not inside
    return inside


def _mech_polygons_overlap(a, b):
    if any(_mech_inside(p, b) for p in a) or any(_mech_inside(p, a) for p in b):
        return True
    return any(_mech_seg_cross(a[i - 1], a[i], b[j - 1], b[j]) for i in range(len(a)) for j in range(len(b)))


def _mech_offset_point(p, toward, distance):
    d = math.dist(p, toward)
    return (p[0] + (toward[0] - p[0]) * distance / d, p[1] + (toward[1] - p[1]) * distance / d)


def _mech_convex_hull(points):
    pts = sorted(set(points))
    def half(seq):
        out = []
        for p in seq:
            while len(out) >= 2 and (out[-1][0] - out[-2][0]) * (p[1] - out[-2][1]) - \
                    (out[-1][1] - out[-2][1]) * (p[0] - out[-2][0]) <= 0:
                out.pop()
            out.append(p)
        return out
    lower, upper = half(pts), half(pts[::-1])
    return lower[:-1] + upper[:-1]


def pawl_outline(teeth, outside_diameter, depth, undercut, pivot_bore, clearance=0.2):
    """Pawl seated in the gap of the face at angle 0, pivoting outside the wheel on the
    face normal. Returns (outline in wheel coordinates, pivot, hub radius)."""
    wheel, roots, tips = ratchet_points(teeth, outside_diameter, depth, undercut)
    z = int(teeth)
    ra, rf = outside_diameter / 2.0, outside_diameter / 2.0 - depth
    root, tip, prev_tip = roots[0], tips[0], tips[-1]
    gap_mid = ((root[0] + prev_tip[0]) / 2.0, (root[1] + prev_tip[1]) / 2.0)
    # wedge: corner at the face root, up the face, back along the slope (with clearance)
    corner = _mech_offset_point(root, gap_mid, clearance * 1.5)
    # face normal pointing into the gap (away from the tooth the face belongs to)
    fx, fy = tip[0] - root[0], tip[1] - root[1]
    fl = math.hypot(fx, fy)
    face_n = (fy / fl, -fx / fl)
    if face_n[0] * (gap_mid[0] - root[0]) + face_n[1] * (gap_mid[1] - root[1]) < 0:
        face_n = (-face_n[0], -face_n[1])
    face_top = (root[0] + fx * 0.8 + clearance * face_n[0], root[1] + fy * 0.8 + clearance * face_n[1])
    # the arm runs parallel to the back slope of the gap (root -> previous tip), offset by the
    # clearance, so it passes over the previous tooth; the pivot lies beyond that tooth
    ux, uy = prev_tip[0] - root[0], prev_tip[1] - root[1]
    ul = math.hypot(ux, uy)
    ux, uy = ux / ul, uy / ul
    slope_n = (-uy, ux) if (-uy * root[0] + ux * root[1]) > 0 else (uy, -ux)   # away from the hub
    slope = (root[0] + 0.35 * ul * ux + clearance * slope_n[0],
             root[1] + 0.35 * ul * uy + clearance * slope_n[1])
    # wedge corner: where the face and slope lines, both offset by the clearance, meet
    p1 = (root[0] + clearance * face_n[0], root[1] + clearance * face_n[1])
    p2 = (root[0] + clearance * slope_n[0], root[1] + clearance * slope_n[1])
    det = (fx / fl) * (-uy) - (fy / fl) * (-ux)
    if abs(det) > 1e-12:
        s = ((p2[0] - p1[0]) * (-uy) - (p2[1] - p1[1]) * (-ux)) / det
        corner = (p1[0] + s * fx / fl, p1[1] + s * fy / fl)
    hub = pivot_bore / 2.0 + max(1.5, 0.5 * pivot_bore)
    def distance_to(poly, p):
        best = float("inf")
        for i in range(len(poly)):
            (ax, ay), (bx, by) = poly[i - 1], poly[i]
            dx, dy = bx - ax, by - ay
            t = max(0.0, min(1.0, ((p[0] - ax) * dx + (p[1] - ay) * dy) / (dx * dx + dy * dy or 1e-30)))
            best = min(best, math.hypot(p[0] - ax - t * dx, p[1] - ay - t * dy))
        return best

    def clear(outline):
        """No overlap with the wheel, and every other tooth tip keeps the clearance."""
        if _mech_polygons_overlap(outline, wheel):
            return False
        # the previous tip sits exactly one clearance below the arm by construction
        return all(distance_to(outline, t) >= 0.9 * clearance for t in tips[1:])
    for extra in [0.0] + [0.05 * ra * k for k in range(1, 60)]:
        along = hub * 1.5 + extra
        pivot = (prev_tip[0] + along * ux + (hub + clearance) * slope_n[0],
                 prev_tip[1] + along * uy + (hub + clearance) * slope_n[1])
        circle =[(pivot[0] + hub * math.cos(2 * math.pi * k / 32),
                   pivot[1] + hub * math.sin(2 * math.pi * k / 32)) for k in range(32)]
        outline = _mech_convex_hull([corner, face_top, slope] + circle)
        # keep counter-clockwise
        if sum(outline[i - 1][0] * outline[i][1] - outline[i][0] * outline[i - 1][1]
               for i in range(len(outline))) < 0:
            outline = outline[::-1]
        if clear(outline):
            return outline, pivot, hub
    raise ValueError("No collision-free pawl position found; change depth or undercut.")


# ── Geneva drive ─────────────────────────────────────────────────────────────────────────
def geneva_geometry(slots, center_distance, pin_diameter, clearance=0.2):
    n, C = int(slots), float(center_distance)
    if not 3 <= n <= 18:
        raise ValueError("A Geneva wheel needs 3 to 18 slots.")
    a, b = C * math.sin(math.pi / n), C * math.cos(math.pi / n)
    w = pin_diameter + clearance
    wheel_r = math.sqrt(b * b + (w / 2.0) ** 2)
    lock_r = a - pin_diameter                       # driver locking disc
    slot_end = C - a                                # innermost pin centre position
    if lock_r <= 0.2 * a or slot_end - w / 2.0 <= 0:
        raise ValueError("Pin too large for this centre distance and slot count.")
    if slot_end * math.sin(math.pi / n) <= w / 2.0 + 0.5:
        raise ValueError("The slots meet at the centre; increase the centre distance.")
    return {"slots": n, "center_distance": C, "crank_radius": a, "wheel_radius": wheel_r,
            "slot_width": w, "slot_end": slot_end, "lock_radius": lock_r,
            "lock_arc_radius": lock_r + clearance, "pin_diameter": pin_diameter,
            "clearance": clearance, "plate_radius": a + pin_diameter / 2.0 + max(2.0, 0.4 * pin_diameter)}


def geneva_wheel_outline(g):
    n, C, Rw, w = g["slots"], g["center_distance"], g["wheel_radius"], g["slot_width"]
    RL = g["lock_arc_radius"]
    cos_b = (C * C + Rw * Rw - RL * RL) / (2.0 * C * Rw)
    if not -1.0 < cos_b < 1.0:
        raise ValueError("The locking arc does not meet the wheel rim.")
    beta = math.acos(cos_b)
    delta = math.asin((w / 2.0) / Rw)
    if beta >= math.pi / n - delta - math.radians(0.5):
        raise ValueError("The locking arcs reach into the slots; reduce the pin diameter.")
    pts = []
    for k in range(n):
        bis = 2.0 * math.pi * k / n                      # locking arc faces this direction
        lc = (C * math.cos(bis), C * math.sin(bis))
        a0 = math.atan2(Rw * math.sin(bis - beta) - lc[1], Rw * math.cos(bis - beta) - lc[0])
        a1 = math.atan2(Rw * math.sin(bis + beta) - lc[1], Rw * math.cos(bis + beta) - lc[0])
        # through the side facing the wheel centre (angle bis + pi), clockwise around lc
        while a1 > a0: a1 -= 2 * math.pi
        pts += _mech_arc(lc, RL, a0, a1, 24)
        # horn up to the slot, then the slot
        sigma = bis + math.pi / n
        e, t = (math.cos(sigma), math.sin(sigma)), (-math.sin(sigma), math.cos(sigma))
        rim = math.sqrt(Rw * Rw - (w / 2.0) ** 2)
        horn_from, horn_to = bis + beta, sigma - delta
        pts += [(Rw * math.cos(horn_from + (horn_to - horn_from) * s / 4),
                 Rw * math.sin(horn_from + (horn_to - horn_from) * s / 4)) for s in range(1, 4)]
        lower_rim = (rim * e[0] - w / 2 * t[0], rim * e[1] - w / 2 * t[1])
        inner = g["slot_end"]
        lower_in = (inner * e[0] - w / 2 * t[0], inner * e[1] - w / 2 * t[1])
        pts += [lower_rim, lower_in]
        start = math.atan2(-t[1], -t[0])
        pts += _mech_arc((inner * e[0], inner * e[1]), w / 2.0, start, start - math.pi, 12)[1:-1]
        upper_in = (inner * e[0] + w / 2 * t[0], inner * e[1] + w / 2 * t[1])
        upper_rim = (rim * e[0] + w / 2 * t[0], rim * e[1] + w / 2 * t[1])
        pts += [upper_in, upper_rim]
        nxt = bis + 2.0 * math.pi / n - beta
        pts += [(Rw * math.cos(sigma + delta + (nxt - sigma - delta) * s / 4),
                 Rw * math.sin(sigma + delta + (nxt - sigma - delta) * s / 4)) for s in range(1, 4)]
    return pts


def geneva_driver_outline(g):
    """Driver in its own frame (centre at the origin, wheel at -X): locking disc with the
    relief cut on the pin side (+X), and the pin. Returns (disc outline, pin centre)."""
    C, a, rl = g["center_distance"], g["crank_radius"], g["lock_radius"]
    relief_c, relief_r = (C, 0.0), g["wheel_radius"] + g["clearance"]
    hits = _mech_circle_intersections((0.0, 0.0), rl, relief_c, relief_r)
    if len(hits) < 2:
        raise ValueError("The driver relief cut does not cross the locking disc.")
    upper = max(hits, key=lambda p: p[1])
    a_up = math.atan2(upper[1], upper[0])
    disc = _mech_arc((0.0, 0.0), rl, a_up, 2 * math.pi - a_up, 72)        # long way, away from +X
    r0 = math.atan2(-upper[1] - relief_c[1], upper[0] - relief_c[0])
    r1 = math.atan2(upper[1] - relief_c[1], upper[0] - relief_c[0])
    while r1 > r0: r1 -= 2 * math.pi                                   # concave, clockwise
    relief = _mech_arc(relief_c, relief_r, r0, r1, 24)[1:-1]
    return disc + relief, (a, 0.0)


# ── sketches and solids of the mechanism parts (gear generator types) ────────────────────
MECHANISM_KINDS = ("pulley", "sprocket", "ratchet", "geneva", "worm_wheel")


def _polygon_sketch(name, frame, outline, circles=()):
    """Sketch of one closed polyline plus circles ((cx, cy), r); a locked centre point."""
    sketch = Sketch("XY", name=name, frame=frame)
    vertices = [Vertex(x, y) for x, y in outline]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(Segment(vertices[i], vertices[(i + 1) % len(vertices)])
                           for i in range(len(vertices)))
    for (cx, cy), radius in circles:
        sketch.circles.append(Circle(Vertex(cx, cy), radius))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch


def _bore_circles(bore, limit_radius, what):
    bore = float(bore or 0.0)
    if not math.isfinite(bore) or bore < 0:
        raise ValueError("Bore diameter must be zero or positive.")
    if bore and bore / 2.0 >= limit_radius - 0.3:
        raise ValueError(f"Bore diameter must be smaller than {2.0 * (limit_radius - 0.3):.2f} mm "
                         f"({what}).")
    return [((0.0, 0.0), bore / 2.0)] if bore else []


def make_pulley_sketch(name, parameters, frame=None):
    outline, info = pulley_outline(parameters["belt_profile"], int(parameters["teeth"]),
                                   float(parameters.get("clearance", 0.2)))
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0), info["root_radius"], "groove root"))


def make_sprocket_sketch(name, parameters, frame=None):
    outline, geometry = sprocket_outline(parameters["chain"], int(parameters["teeth"]))
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0), geometry["root_diameter"] / 2.0, "root diameter"))


def make_ratchet_sketch(name, parameters, frame=None):
    depth = float(parameters["ratchet_depth"])
    outline, _, _ = ratchet_points(int(parameters["teeth"]), float(parameters["outside_diameter"]),
                                   depth, float(parameters.get("ratchet_undercut", 5.0)))
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0),
        float(parameters["outside_diameter"]) / 2.0 - depth, "tooth root"))


def ratchet_pawl(parameters):
    """(outline relative to the pivot, pivot in wheel coordinates, hub radius)."""
    outline, pivot, hub = pawl_outline(
        int(parameters["teeth"]), float(parameters["wheel_diameter"]),
        float(parameters["ratchet_depth"]), float(parameters.get("ratchet_undercut", 5.0)),
        float(parameters.get("bore_diameter", 3.0)), float(parameters.get("clearance", 0.2)))
    return [(x - pivot[0], y - pivot[1]) for x, y in outline], pivot, hub


def make_pawl_sketch(name, parameters, frame=None):
    outline, _, hub = ratchet_pawl(parameters)
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0), hub, "pawl hub"))


def _geneva(parameters):
    return geneva_geometry(int(parameters["slots"]), float(parameters["center_distance"]),
                           float(parameters["pin_diameter"]), float(parameters.get("clearance", 0.2)))


def make_geneva_wheel_sketch(name, parameters, frame=None):
    geometry = _geneva(parameters)
    return _polygon_sketch(name, frame, geneva_wheel_outline(geometry), _bore_circles(
        parameters.get("bore_diameter", 0.0),
        geometry["slot_end"] - geometry["slot_width"] / 2.0, "slot ends"))


def make_geneva_driver_sketch(name, parameters, frame=None):
    """Locking disc with its relief cut and the drive pin (an island); the crank plate that
    carries the pin is added below the profile plane by gear_extrusion."""
    geometry = _geneva(parameters)
    disc, pin = geneva_driver_outline(geometry)
    limit = min(geometry["lock_radius"],
                geometry["center_distance"] - geometry["wheel_radius"] - geometry["clearance"])
    circles = _bore_circles(parameters.get("bore_diameter", 0.0), limit, "locking disc")
    circles.append((pin, geometry["pin_diameter"] / 2.0))
    return _polygon_sketch(name, frame, disc, circles)


def _disc_layer(frame, z, height, radius, bore):
    """Prism of a disc (with an optional bore) on the profile frame, from z to z + height."""
    def loop(r):
        pts = circle_pts(0.0, 0.0, r)
        return [{"kind": "circle", "pts": pts + [pts[0]], "center": (0.0, 0.0), "radius": r}]
    loops = [loop(radius)] + ([loop(bore / 2.0)] if bore else [])
    return extrude_profile(loops, height, frame, z)


def _stacked(main, frame, layers):
    """Union of the main prism and disc layers (z, height, radius, bore) touching it."""
    tools = [_disc_layer(frame, *layer) for layer in layers if layer[1] > 1e-6 and layer[2] > 0]
    if not tools:
        return main
    result = csg_subtract(main, tools, label="", union=True)
    if not _mesh_is_closed(result[1]):
        raise ValueError("The layered body could not be joined into one solid.")
    return result


def pulley_layers(parameters, z0, h):
    """Flanges (both ends) and hub (below the bottom flange) of a timing pulley."""
    bore = float(parameters.get("bore_diameter", 0.0))
    outside = float(parameters["outside_diameter"])
    layers, bottom = [], z0
    if parameters.get("flanges"):
        thickness = float(parameters.get("flange_thickness", 1.0))
        radius = outside / 2.0 + float(parameters.get("flange_height", 1.5))
        layers += [(z0 - thickness, thickness, radius, bore), (z0 + h, thickness, radius, bore)]
        bottom = z0 - thickness
    hub_d, hub_l = float(parameters.get("hub_diameter", 0.0)), float(parameters.get("hub_length", 0.0))
    if hub_d > 0 and hub_l > 0:
        if hub_d / 2.0 <= bore / 2.0 + 0.5:
            raise ValueError("The hub diameter must be larger than the bore.")
        layers.append((bottom - hub_l, hub_l, hub_d / 2.0, bore))
    return layers


# ── worm drive: ZA worm (straight-sided axial profile) and a hob-generated, throated wheel ──
def worm_geometry(module, wheel_teeth, starts, worm_diameter, pressure_angle=20.0, backlash=0.0):
    """Dimensions of a 90° worm drive (axial module = wheel transverse module)."""
    m, z2, z1, d1 = float(module), int(wheel_teeth), int(starts), float(worm_diameter)
    alpha = math.radians(float(pressure_angle))
    if not math.isfinite(m) or m <= 0:
        raise ValueError("The module must be a finite positive number.")
    if not 1 <= z1 <= 4:
        raise ValueError("A worm has 1 to 4 starts.")
    if z2 < 12:
        raise ValueError("A worm wheel needs at least 12 teeth.")
    if not 10.0 <= float(pressure_angle) <= 30.0:
        raise ValueError("The worm pressure angle must be between 10° and 30°.")
    if not 5.0 * m <= d1 <= 40.0 * m:
        raise ValueError(f"The worm pitch diameter must lie between {5 * m:g} and {40 * m:g} mm "
                         "(5 to 40 × module).")
    pitch = math.pi * m
    lead = z1 * pitch
    r1, r2 = d1 / 2.0, m * z2 / 2.0
    tan_a = math.tan(alpha)
    worm_half = (pitch / 2.0 - backlash * m) / 2.0          # half thread thickness at r1
    hob_half = (pitch / 2.0 + backlash * m) / 2.0           # the generating hob: wheel backlash
    if worm_half - m * tan_a < 0.05 * m:
        raise ValueError("The worm thread becomes pointed; reduce the pressure angle or backlash.")
    if pitch / 2.0 - (hob_half + 1.25 * m * tan_a) < 0.05 * m:
        raise ValueError("The wheel teeth become pointed; reduce the pressure angle or backlash.")
    throat = (m * z2 + 2.0 * m) / 2.0
    outer = throat + {1: 1.0, 2: 0.75, 3: 0.75}.get(z1, 0.5) * m
    return {"module": m, "wheel_teeth": z2, "starts": z1, "pitch": pitch, "lead": lead,
            "r1": r1, "r2": r2, "center_distance": r1 + r2, "tan_alpha": tan_a,
            "lead_angle": math.atan(lead / (2.0 * math.pi * r1)),
            "worm_tip": r1 + m, "worm_root": r1 - 1.25 * m, "worm_half": worm_half,
            "hob_tip": r1 + 1.25 * m, "hob_half": hob_half, "throat_radius": r1 - m,
            "wheel_throat": throat, "wheel_outer": outer, "wheel_root": r2 - 1.25 * m}


def worm_default_length(module, wheel_teeth, starts):
    """Usual worm face length (DIN 3975 guide values)."""
    m, z2 = float(module), int(wheel_teeth)
    return (11.0 + 0.06 * z2) * m if starts <= 2 else (12.5 + 0.09 * z2) * m


def worm_max_width(module, worm_diameter, starts):
    """Widest wheel the worm still cuts teeth into at both faces (at least 0.5·m deep there),
    and at most 0.85 × the worm tip diameter."""
    m, r1 = float(module), float(worm_diameter) / 2.0
    rim = {1: 1.0, 2: 0.75, 3: 0.75}.get(int(starts), 0.5)          # see worm_geometry "outer"
    hob_tip = r1 + 1.25 * m
    clear = r1 - m - rim * m + 0.5 * m          # worm axis to (wheel rim - 0.5·m)
    return min(1.7 * (r1 + m), 2.0 * math.sqrt(max(hob_tip * hob_tip - clear * clear, 0.0)))


def worm_default_width(module, worm_diameter, starts):
    """Usual wheel face width: 0.75 (≤ 3 starts) or 0.67 × the worm tip diameter, within
    what the worm can cut."""
    usual = (0.75 if starts <= 3 else 0.67) * (float(worm_diameter) + 2.0 * float(module))
    return min(usual, 0.95 * worm_max_width(module, worm_diameter, starts))


def _hand_sign(hand):
    return -1.0 if str(hand).lower().startswith("l") else 1.0


def _worm_axial_radius(g, xc):
    """Worm thread radius at the centred axial position xc (|xc| <= pitch/2)."""
    t, half = g["tan_alpha"], g["worm_half"]
    w_tip, w_root = half - g["module"] * t, half + 1.25 * g["module"] * t
    x = abs(xc)
    if x <= w_tip:
        return g["worm_tip"]
    if x >= w_root:
        return g["worm_root"]
    return g["r1"] - (x - half) / t


def _worm_columns(g, length, hand, x_offset, columns=96):
    """Angular columns [(z, r, angle)] of the worm surface from z = 0 to length. Along a
    column the axial profile is piecewise linear, so its corners are exact vertices."""
    m, pitch, lead = g["module"], g["pitch"], g["lead"]
    t, half = g["tan_alpha"], g["worm_half"]
    corners = (half - m * t, half + 1.25 * m * t)
    sign = _hand_sign(hand)
    out = []
    for j in range(columns):
        angle = 2.0 * math.pi * j / columns
        shift = sign * lead * angle / (2.0 * math.pi) - x_offset
        def radius(z):
            xc = (z - shift + pitch / 2.0) % pitch - pitch / 2.0
            return _worm_axial_radius(g, xc)
        marks = set()
        first = math.floor((0.0 - shift) / pitch) - 1
        for k in range(first, first + int(length / pitch) + 4):
            for w in corners:
                for z in (shift + k * pitch - w, shift + k * pitch + w):
                    if 1e-6 < z < length - 1e-6:
                        marks.add(round(z, 9))
        column = [(0.0, radius(0.0), angle)]
        column += [(z, radius(z), angle) for z in sorted(marks)]
        column.append((length, radius(length), angle))
        out.append(column)
    return out


@lru_cache(maxsize=16)
def _worm_wheel_grid(module, wheel_teeth, starts, worm_diameter, pressure_angle, backlash,
                     width, hand, per_tooth=32):
    """Hob-generated worm wheel as a polar grid: returns (z rows from 0 to width, angles and
    radii, both rows × columns). In every slice across the face width the hob section (exact
    helicoid section in that plane) rolls along the pitch circle; the wheel keeps the material
    the hob never reaches. Columns twist with the tooth helix, so few slices suffice."""
    g = worm_geometry(module, wheel_teeth, starts, worm_diameter, pressure_angle, backlash)
    m, z2 = g["module"], g["wheel_teeth"]
    a, r1, r2 = g["center_distance"], g["r1"], g["r2"]
    pitch, lead, t = g["pitch"], g["lead"], g["tan_alpha"]
    sign = _hand_sign(hand)
    hob_tip, hob_half, hob_root = g["hob_tip"], g["hob_half"], g["worm_root"]
    widest = worm_max_width(module, worm_diameter, starts)
    if not 0.0 < width <= widest + 1e-9:
        raise ValueError(f"The wheel width must be at most {widest:.2f} mm for this worm (further "
                         "out it cannot cut teeth into the wheel).")
    kappa = sign * math.tan(g["lead_angle"]) / r2              # tooth helix twist per mm
    slices = max(13, min(41, int(math.ceil(width / (0.45 * m))) + 1))
    hs = np.linspace(-width / 2.0, width / 2.0, slices)
    period = 2.0 * math.pi / z2
    # samples per tooth: root land, rising flank, tip land, falling flank; every slice uses
    # the same counts between the same four corners, so each corner is one grid line
    n_root, n_flank, n_tip = 4, (per_tooth - 8) // 2, 4
    coarse_n = 48
    angles, radii = [], []
    for h in hs:
        tip = min(g["wheel_outer"], a - math.sqrt(max(g["throat_radius"] ** 2 - h * h, 0.0)))
        root = a - math.sqrt(max(hob_tip * hob_tip - h * h, 0.0))   # rolled by the hob tip line
        lo_r = a - hob_tip - 0.01 * m
        reach = math.sqrt(max(tip * tip - (a - hob_tip) ** 2, 0.0))
        span = math.asin(min(1.0, reach / tip)) + 0.05
        steps = int(math.ceil(2.0 * span * r2 / (0.05 * m))) + 1     # ≤ 0.05·m roll per step
        delta = np.linspace(-span, span, steps)[None, :]
        sin_d, cos_d = np.sin(delta), np.cos(delta)

        def cut(radius, psi):
            """Whether the hob reaches the wheel points (radius, psi) anywhere in the roll."""
            xw, yw = -radius[:, None] * sin_d, radius[:, None] * cos_d
            du = yw - a
            rho = np.hypot(du, h)
            xt = xw - sign * lead * np.arctan2(h, du) / (2.0 * math.pi) + \
                 r2 * (math.pi / 2.0 - psi[:, None] + delta)
            xc = np.abs((xt + pitch / 2.0) % pitch - pitch / 2.0)
            inside = (rho <= hob_tip) & ((rho < hob_root) | (xc <= hob_half + (r1 - rho) * t))
            return inside.any(axis=1)

        def flank_radius(psi):
            lo, hi = np.full(len(psi), lo_r), np.full(len(psi), tip)
            for _ in range(16):                                      # ≈ 1e-4 mm
                mid = (lo + hi) / 2.0
                c = cut(mid, psi)
                hi, lo = np.where(c, mid, hi), np.where(c, lo, mid)
            return lo

        eps = 1e-3 * m
        coarse = kappa * h + np.arange(coarse_n) * period / coarse_n
        in_root = cut(np.full(coarse_n, root + eps), coarse)       # inside the gap bottom
        on_tip = ~cut(np.full(coarse_n, tip - eps), coarse)        # on the tooth's tip land

        def corner(flags, rising, radius, solid_test):
            """Angle where `flags` switches (False -> True if rising), refined by bisection;
            None if it does not switch exactly once per tooth."""
            following = np.roll(flags, -1)
            found = np.nonzero((~flags & following) if rising else (flags & ~following))[0]
            if len(found) != 1:
                return None
            lo_a = coarse[found[0]]
            hi_a = lo_a + period / coarse_n
            low_value = not rising
            for _ in range(22):
                mid = (lo_a + hi_a) / 2.0
                # flag value at mid: "cut" for the root land, "not cut" for the tip land
                value = bool(cut(np.array([radius]), np.array([mid]))[0]) != solid_test
                lo_a, hi_a = (mid, hi_a) if value == low_value else (lo_a, mid)
            return (lo_a + hi_a) / 2.0

        root_end = corner(in_root, False, root + eps, False)
        root_start = corner(in_root, True, root + eps, False)
        if root_end is None or root_start is None:
            raise ValueError("The worm wheel teeth cannot be formed (undercut teeth); use more "
                             "teeth, a smaller pressure angle or a narrower wheel.")
        tip_start = corner(on_tip, True, tip - eps, True)
        tip_end = corner(on_tip, False, tip - eps, True)
        pointed = tip_start is None or tip_end is None
        if pointed:
            # the tooth comes to a point below the tip circle in this slice (where the throat
            # meets the rim cylinder): a very narrow tip strip around its highest point
            fine = np.linspace(root_end, root_end + period, 4 * coarse_n, endpoint=False)
            heights = flank_radius(fine)
            heights[cut(np.full(len(fine), root + eps), fine)] = root
            peak = fine[int(np.argmax(heights))]
            half = 0.25 * period / (4 * coarse_n)
            tip_start, tip_end = peak - half, peak + half
        tip_start = root_end + (tip_start - root_end) % period
        tip_end = root_end + (tip_end - root_end) % period
        root_start = root_end + (root_start - root_end) % period
        if not root_end < tip_start < tip_end < root_start:
            raise ValueError("The worm wheel teeth cannot be formed for these settings.")
        segments = (
            (np.linspace(root_start - period, root_end, n_root, endpoint=False), "root"),
            (np.linspace(root_end, tip_start, n_flank, endpoint=False), "flank"),
            (np.linspace(tip_start, tip_end, n_tip, endpoint=False), "tip"),
            (np.linspace(tip_end, root_start, n_flank, endpoint=False), "flank"),
        )
        psi = np.concatenate([seg for seg, _ in segments])
        r = np.concatenate([
            np.full(len(seg), root) if kind == "root" else
            flank_radius(seg) if kind == "tip" and pointed else
            np.full(len(seg), tip) if kind == "tip" else
            np.r_[root if index == 1 else flank_radius(seg[:1]) if pointed else tip,
                  flank_radius(seg[1:])]
            for index, (seg, kind) in enumerate(segments)])
        angles.append(np.concatenate([psi + k * period for k in range(z2)]))
        radii.append(np.tile(r, z2))
    return hs + width / 2.0, np.asarray(angles), np.asarray(radii)


def _polar_columns_solid(frame, columns, bore=0.0, label="part", faces_per_strip=False):
    """Closed solid around the frame's w axis from angular columns [(z, r, angle), …] in
    counter-clockwise order, every column running from the same bottom z to the same top z.
    Neighbouring columns are zipped by z; the end faces are star-shaped (optional bore).
    The side gets one face per smooth patch (split at sharp creases), or with faces_per_strip
    one face per strip between neighbouring columns, like an extruded profile."""
    O, u, v, w = (np.asarray(axis, float) for axis in frame)
    flip = float(np.dot(np.cross(u, v), w)) < 0
    verts, tris = [], []
    ids = []
    for column in columns:
        col = []
        for z, r, angle in column:
            col.append(len(verts))
            verts.append(tuple(float(c) for c in O + r * (math.cos(angle) * u + math.sin(angle) * v) + z * w))
        ids.append(col)
    def add(a, b, c, bucket):
        bucket.append(len(tris))
        tris.append((a, c, b) if flip else (a, b, c))
    side, strips = [], []
    n = len(columns)
    for j in range(n):
        left, right = columns[j], columns[(j + 1) % n]
        li, ri = ids[j], ids[(j + 1) % n]
        strip_start = len(side)
        i = k = 0
        while i < len(left) - 1 or k < len(right) - 1:
            if i == len(left) - 1 or (k < len(right) - 1 and right[k + 1][0] < left[i + 1][0]):
                add(li[i], ri[k], ri[k + 1], side); k += 1
            else:
                add(li[i], ri[k], li[i + 1], side); i += 1
        strips.append(side[strip_start:])
    z_bottom, z_top = columns[0][0][0], columns[0][-1][0]
    ring_bottom = [col[0] for col in ids]
    ring_top = [col[-1] for col in ids]
    def flat(column, end):
        _, r, angle = column[end]
        return (r * math.cos(angle), r * math.sin(angle))
    outer_bottom = [flat(c, 0) for c in columns]
    outer_top = [flat(c, -1) for c in columns]
    faces, bore_ids = [], []
    hole = []
    if bore > 0:
        if bore / 2.0 >= min(min(c[0][1], c[-1][1]) for c in columns) - 0.3:
            raise ValueError(f"The bore is too large for this {label}.")
        count = max(24, curve_segments(bore / 2.0))
        hole_angles = [2.0 * math.pi * k / count for k in range(count)]
        bottom_hole = [len(verts) + k for k in range(count)]
        verts += [tuple(float(c) for c in O + bore / 2.0 * (math.cos(t) * u + math.sin(t) * v) + z_bottom * w)
                  for t in hole_angles]
        top_hole = [len(verts) + k for k in range(count)]
        verts += [tuple(float(c) for c in O + bore / 2.0 * (math.cos(t) * u + math.sin(t) * v) + z_top * w)
                  for t in hole_angles]
        for k in range(count):
            k1 = (k + 1) % count
            add(bottom_hole[k], top_hole[k1], bottom_hole[k1], bore_ids)
            add(bottom_hole[k], top_hole[k], top_hole[k1], bore_ids)
        hole = [(bore / 2.0 * math.cos(t), bore / 2.0 * math.sin(t)) for t in hole_angles]
    def point(radius, angle, z):
        verts.append(tuple(float(c) for c in O + radius * (math.cos(angle) * u + math.sin(angle) * v) + z * w))
        return len(verts) - 1

    def cap(end, ring, hole_ring, top):
        """End face of a star-shaped outline (the column angles increase around the axis):
        radial quads to an inner circle, then a ring zipped to the bore (or a fan to the
        centre). Exact and fast, unlike a general polygon triangulation."""
        z = columns[0][end][0]
        outer_angles = [c[end][2] for c in columns]
        bucket = []
        def tri(a, b, c):
            add(a, b, c, bucket) if top else add(a, c, b, bucket)
        n_outer = len(ring)
        if not hole:
            centre = point(0.0, 0.0, z)
            for i in range(n_outer):
                tri(centre, ring[i], ring[(i + 1) % n_outer])
            return bucket
        inner_r = (bore / 2.0 + min(c[end][1] for c in columns)) / 2.0
        middle = [point(inner_r, angle, z) for angle in outer_angles]
        for i in range(n_outer):
            j = (i + 1) % n_outer
            tri(ring[i], ring[j], middle[j])
            tri(ring[i], middle[j], middle[i])
        # zip the middle ring (outer) with the bore ring (inner), both convex, by angle
        def unwrapped(values):
            first = min(range(len(values)), key=lambda k: values[k] % (2.0 * math.pi))
            order = values[first:] + values[:first]
            out, base = [], order[0] % (2.0 * math.pi)
            for value in order:
                value = base + (value - order[0]) % (2.0 * math.pi) if out else base
                while out and value < out[-1]:
                    value += 2.0 * math.pi
                out.append(value)
            return first, out
        a_first, a_angles = unwrapped(outer_angles)
        b_first, b_angles = unwrapped(hole_angles)
        A = middle[a_first:] + middle[:a_first]
        B = hole_ring[b_first:] + hole_ring[:b_first]
        nA, nB = len(A), len(B)
        a_next = a_angles[1:] + [a_angles[0] + 2.0 * math.pi]
        b_next = b_angles[1:] + [b_angles[0] + 2.0 * math.pi]
        i = k = 0
        while i < nA or k < nB:
            if k == nB or (i < nA and a_next[i] <= b_next[k]):
                tri(A[i % nA], A[(i + 1) % nA], B[k % nB]); i += 1
            else:
                tri(A[i % nA], B[(k + 1) % nB], B[k % nB]); k += 1
        return bucket

    bottom_ids = cap(0, ring_bottom, bottom_hole if hole else [], False)
    top_ids = cap(-1, ring_top, top_hole if hole else [], True)
    uu = _unit(u)
    for kind, bucket, z, normal, outline in (("bottom", bottom_ids, z_bottom, -w, outer_bottom),
                                             ("top", top_ids, z_top, w, outer_top)):
        normal = _unit(normal)
        boundary = [("line", O + p[0] * u + p[1] * v + z * w, O + q[0] * u + q[1] * v + z * w)
                    for p, q in zip(outline, outline[1:] + outline[:1])]
        if hole:
            boundary.append(("circle", O + z * w, bore / 2.0))
        faces.append({"kind": kind, "tris": bucket, "planar": True,
                      "frame": (O + z * w, uu, np.cross(normal, uu), normal), "boundary": boundary})
    # one face per smooth patch (tip land, flank, root, …), split at the sharp tooth creases,
    # so shading is smoothed within a patch only and the tooth edges show like on other gears
    groups = [strip for strip in strips if strip] if faces_per_strip else \
             _split_at_creases(verts, tris, side)
    faces.extend({"kind": "side", "tris": group, "planar": False} for group in groups)
    if bore_ids:
        faces.append({"kind": "bore", "tris": bore_ids, "planar": False})
    if not _mesh_is_closed(tris):
        raise ValueError(f"The {label} surface could not be closed.")
    return verts, tris, faces


def _split_at_creases(verts, tris, ids, crease_deg=25.0):
    """Group the triangles `ids` into smooth patches: neighbours stay together while their
    normals differ by less than crease_deg."""
    V = np.asarray(verts, float)
    T = np.asarray(tris, np.int64).reshape(-1, 3)[np.asarray(ids, np.int64)]
    N = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])
    N /= np.maximum(np.linalg.norm(N, axis=1), 1e-30)[:, None]
    count = len(T)
    edges = np.sort(np.concatenate([T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]]), axis=1)
    owner = np.tile(np.arange(count), 3)
    order = np.lexsort((edges[:, 1], edges[:, 0]))
    edges, owner = edges[order], owner[order]
    same = np.all(edges[1:] == edges[:-1], axis=1)
    a, b = owner[:-1][same], owner[1:][same]
    smooth = np.einsum("ij,ij->i", N[a], N[b]) >= math.cos(math.radians(crease_deg))
    parent = list(range(count))
    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    for i, j in zip(a[smooth].tolist(), b[smooth].tolist()):
        ri, rj = root(i), root(j)
        if ri != rj:
            parent[rj] = ri
    groups = {}
    for local, tri in enumerate(ids):
        groups.setdefault(root(local), []).append(int(tri))
    return list(groups.values())


def worm_wheel_columns(parameters):
    g_args = (float(parameters["module"]), int(parameters["teeth"]), int(parameters["starts"]),
              float(parameters["worm_diameter"]), float(parameters.get("pressure_angle", 20.0)),
              float(parameters.get("backlash", 0.0)), float(parameters["thickness"]),
              str(parameters.get("hand", "right")))
    zs, angles, radii = _worm_wheel_grid(*g_args)
    return [[(float(zs[k]), float(radii[k, j]), float(angles[k, j])) for k in range(len(zs))]
            for j in range(angles.shape[1])]


def worm_columns(parameters, length=None):
    """Worm columns over `length` (default: its stored length); the thread phase is fixed by
    the stored length, whose middle lies over the wheel centre."""
    g = worm_geometry(parameters["module"], parameters["wheel_teeth"], parameters["starts"],
                      parameters["worm_diameter"], parameters.get("pressure_angle", 20.0),
                      parameters.get("backlash", 0.0))
    stored = float(parameters["worm_length"])
    return _worm_columns(g, float(length or stored), parameters.get("hand", "right"), -stored / 2.0)


def worm_wheel_solid(parameters, frame, z0=0.0):
    columns = worm_wheel_columns(parameters)
    if z0:
        columns = [[(z + z0, r, a) for z, r, a in col] for col in columns]
    return _polar_columns_solid(frame, columns, float(parameters.get("bore_diameter", 0.0)),
                                "worm wheel", faces_per_strip=True)


def worm_solid(parameters, frame, z0=0.0, length=None):
    columns = worm_columns(parameters, length)
    if z0:
        columns = [[(z + z0, r, a) for z, r, a in col] for col in columns]
    return _polar_columns_solid(frame, columns, float(parameters.get("bore_diameter", 0.0)), "worm")


def make_worm_wheel_sketch(name, parameters, frame=None):
    """Bottom face outline of the worm wheel (the solid itself is lofted through slices)."""
    columns = worm_wheel_columns(parameters)
    outline = [(c[0][1] * math.cos(c[0][2]), c[0][1] * math.sin(c[0][2])) for c in columns]
    g = worm_geometry(parameters["module"], parameters["teeth"], parameters["starts"],
                      parameters["worm_diameter"], parameters.get("pressure_angle", 20.0))
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0), g["wheel_root"] - 0.1 * g["module"], "wheel root"))


def make_worm_sketch(name, parameters, frame=None):
    """End face outline of the worm (its cross-section at the start of the thread)."""
    columns = worm_columns(parameters)
    outline = [(c[0][1] * math.cos(c[0][2]), c[0][1] * math.sin(c[0][2])) for c in columns]
    g = worm_geometry(parameters["module"], parameters["wheel_teeth"], parameters["starts"],
                      parameters["worm_diameter"], parameters.get("pressure_angle", 20.0))
    return _polygon_sketch(name, frame, outline, _bore_circles(
        parameters.get("bore_diameter", 0.0), g["worm_root"], "worm root"))


def matching_gear_parameters(parameters, ratio, bore_diameter=0.0, profile_shift=0.0,
                             shaft_angle=90.0):
    """Parameters of the mate at mate/primary tooth ratio: a spur gear (pinion of a rack or
    ring gear, mate of a spur gear), a helical gear of opposite hand, or a Tredgold bevel
    gear whose cones share the primary's apex at the shaft angle. Spur and helical pairs
    get the tip shortening of their profile-shifted centre distance."""
    ratio = float(ratio)
    if not math.isfinite(ratio) or ratio <= 0:
        raise ValueError("The matching gear ratio must be a finite positive number.")
    module = float(parameters["module"])
    primary_teeth = int(parameters["teeth"])
    teeth = int(round(primary_teeth * ratio))
    if not 6 <= teeth <= 200:
        raise ValueError("The ratio must produce a matching gear with 6 to 200 teeth.")
    kind = parameters.get("kind", "spur")
    pressure = float(parameters.get("pressure_angle", 20.0))
    mate = {
        "kind": "spur", "module": module, "teeth": teeth, "pressure_angle": pressure,
        "thickness": float(parameters["thickness"]), "bore_diameter": float(bore_diameter),
        "backlash": float(parameters.get("backlash", 0.0)),
        "profile_shift": 0.0 if kind == "internal" else float(profile_shift),
        "tip_reduction": 0.0,
    }
    if kind in ("spur", "helical", "herringbone"):
        mate["tip_reduction"] = involute_pair_geometry(
            module, primary_teeth, teeth, pressure,
            float(parameters.get("profile_shift", 0.0)), mate["profile_shift"])[2]
    trace = parameters.get("tooth_trace", "straight")
    if kind in ("helical", "herringbone"):
        # external pair: opposite hands
        mate["kind"] = kind
        mate["helix_angle"] = -float(parameters.get("helix_angle", 0.0))
    elif kind in ("rack", "internal") and trace in ("helical", "herringbone"):
        # a pinion in a helical rack or ring gear has the same hand (same signed angle)
        mate["kind"] = trace
        mate["helix_angle"] = float(parameters.get("helix_angle", 0.0))
    elif kind == "bevel":
        primary_angle, mate_angle = bevel_pitch_angles(primary_teeth, teeth, shaft_angle)
        if not (1.0 <= primary_angle <= 75.0 and 1.0 <= mate_angle <= 75.0):
            raise ValueError(f"Shaft angle {shaft_angle:g}° with this ratio gives cone angles "
                             f"{primary_angle:.1f}° / {mate_angle:.1f}°; both must lie in 1–75°.")
        mate.update(kind="bevel", bevel_angle=mate_angle, bevel_profile="tredgold",
                    shaft_angle=float(shaft_angle),
                    profile_shift=-float(parameters.get("profile_shift", 0.0)))
    mate["outside_diameter"] = gear_outside_from_module(
        mate["kind"], module, teeth, mate["profile_shift"], mate.get("bevel_angle", 45.0))
    return mate


def gear_pair_center_distance(primary, mate):
    """Axis distance of a spur / helical / ring pair, or rack pitch line to pinion axis."""
    module = float(primary["module"])
    kind = primary.get("kind", "spur")
    if kind == "rack":
        return module * mate["teeth"] / 2.0 + float(mate.get("profile_shift", 0.0)) * module
    if kind == "internal":
        return module * (primary["teeth"] - mate["teeth"]) / 2.0
    return involute_pair_geometry(module, primary["teeth"], mate["teeth"],
                                  float(primary.get("pressure_angle", 20.0)),
                                  float(primary.get("profile_shift", 0.0)),
                                  float(mate.get("profile_shift", 0.0)))[0]


def bevel_mate_frame(primary, mate, offset=(0.0, 0.0, 0.0)):
    """Local frame (origin, u, v, w) of a bevel mate in its primary's frame: both pitch cones
    share the apex, the axes meet at the shaft angle, and a mate tooth space (even primary
    tooth count) or tooth (odd) faces the primary at the common pitch-cone line (-X)."""
    shaft = math.radians(float(mate.get("shaft_angle", primary.get("shaft_angle", 90.0))))
    apex = np.array([0.0, 0.0, bevel_apex_height(primary)])
    w = np.array([math.sin(shaft), 0.0, math.cos(shaft)])
    e = np.array([-math.cos(shaft), 0.0, math.sin(shaft)])
    y = np.array([0.0, 1.0, 0.0])
    angle = -math.pi / 2.0 - (math.pi / mate["teeth"] if primary["teeth"] % 2 == 0 else 0.0)
    u = math.cos(angle) * y + math.sin(angle) * e
    v = -math.sin(angle) * y + math.cos(angle) * e
    origin = apex - bevel_apex_height(mate) * w + np.asarray(offset, float)
    return origin, u, v, w


