def svg_to_contours(path, text_groups=None):
    """Read SVG geometry in mm; optionally collect text labels and their contour indices."""
    try:
        root = ET.parse(path).getroot()
    except (ET.ParseError, OSError) as ex:
        raise ValueError(f"Could not read SVG: {ex}") from ex
    def number(value, default=0.0):
        match = re.match(r"^\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)", value or "")
        return float(match.group(1)) if match else default

    units = {"mm":1.0, "cm":10.0, "in":25.4, "pt":25.4/72,
             "pc":25.4/6, "px":25.4/96}
    viewbox = [number(v) for v in re.split(r"[\s,]+", root.get("viewBox", "").strip()) if v]
    width_attr, height_attr = root.get("width"), root.get("height")
    if len(viewbox) == 4 and viewbox[2] > 0 and viewbox[3] > 0:
        def physical(value, fallback):
            if not value: return fallback
            m = re.match(r"^\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)\s*([a-zA-Z]*)", value)
            if not m: return fallback
            return float(m.group(1))*units.get(m.group(2), 25.4/96)
        sx = physical(width_attr, viewbox[2]*25.4/96) / viewbox[2]
        sy = physical(height_attr, viewbox[3]*25.4/96) / viewbox[3]
        scale = min(sx, sy)
        origin_x, origin_y = viewbox[:2]
    else:
        scale = units.get(re.sub(r"^[\d.eE+-]+", "", width_attr or "px"), 25.4/96)
        origin_x = origin_y = 0.0

    def matrix_multiply(a, b):
        return (a[0]*b[0]+a[2]*b[1], a[1]*b[0]+a[3]*b[1],
                a[0]*b[2]+a[2]*b[3], a[1]*b[2]+a[3]*b[3],
                a[0]*b[4]+a[2]*b[5]+a[4], a[1]*b[4]+a[3]*b[5]+a[5])

    def parse_transform(text):
        result = (1, 0, 0, 1, 0, 0)
        for name, args in re.findall(r"([A-Za-z]+)\s*\(([^)]*)\)", text or ""):
            values = [float(x) for x in re.findall(
                r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", args)]
            op = (1, 0, 0, 1, 0, 0)
            if name == "matrix" and len(values) == 6: op = tuple(values)
            elif name == "translate" and values:
                op = (1, 0, 0, 1, values[0], values[1] if len(values)>1 else 0)
            elif name == "scale" and values:
                op = (values[0], 0, 0, values[1] if len(values)>1 else values[0], 0, 0)
            elif name == "rotate" and values:
                angle = math.radians(values[0]); c, s = math.cos(angle), math.sin(angle)
                op = (c, s, -s, c, 0, 0)
                if len(values) >= 3:
                    cx, cy = values[1:3]
                    op = matrix_multiply((1,0,0,1,cx,cy),
                                         matrix_multiply(op,(1,0,0,1,-cx,-cy)))
            elif name == "skewX" and values: op = (1,0,math.tan(math.radians(values[0])),1,0,0)
            elif name == "skewY" and values: op = (1,math.tan(math.radians(values[0])),0,1,0,0)
            else: raise ValueError(f"Unsupported SVG transform: {name}")
            result = matrix_multiply(result, op)
        return result

    def path_contours(data):
        tokens = re.findall(
            r"[A-Za-z]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", data or "")
        counts = {"M":2,"L":2,"H":1,"V":1,"C":6,"S":4,"Q":4,"T":2,"A":7}
        result, points = [], []
        i, cmd, cur, start, last_ctrl, prev = 0, None, (0.0,0.0), None, None, ""
        def point(x, y, relative):
            return (x+cur[0], y+cur[1]) if relative else (x,y)
        def append(p):
            points.append(p)
        while i < len(tokens):
            if tokens[i].isalpha():
                cmd = tokens[i]; i += 1
                if cmd.upper() == "Z":
                    if points and points[-1] != start: points.append(start)
                    if len(points)>1: result.append(points)
                    points=[]; cur=start if start is not None else cur
                    last_ctrl=None; prev="Z"; cmd=None
                    continue
            if cmd is None or cmd.upper() not in counts:
                raise ValueError("SVG path contains an invalid or incomplete command")
            upper, rel = cmd.upper(), cmd.islower()
            n = counts[upper]
            if i+n > len(tokens) or any(t.isalpha() for t in tokens[i:i+n]):
                raise ValueError("SVG path contains an incomplete command")
            v = [float(x) for x in tokens[i:i+n]]; i += n
            if upper == "M":
                p = point(v[0],v[1],rel)
                if len(points)>1: result.append(points)
                points=[p]; cur=p; start=p
                cmd = "l" if rel else "L"; last_ctrl=None
            elif upper in ("L","H","V"):
                p = point(v[0],v[1],rel) if upper=="L" else (
                    (cur[0]+v[0] if rel else v[0],cur[1]) if upper=="H" else
                    (cur[0],cur[1]+v[0] if rel else v[0]))
                append(p); cur=p; last_ctrl=None
            elif upper in ("C","S","Q","T"):
                if upper == "C":
                    c1=point(v[0],v[1],rel); c2=point(v[2],v[3],rel); end=point(v[4],v[5],rel)
                elif upper == "S":
                    c1=(2*cur[0]-last_ctrl[0],2*cur[1]-last_ctrl[1]) if prev in ("C","S") and last_ctrl else cur
                    c2=point(v[0],v[1],rel); end=point(v[2],v[3],rel)
                elif upper == "Q":
                    c1=point(v[0],v[1],rel); end=point(v[2],v[3],rel); c2=c1
                else:
                    c1=(2*cur[0]-last_ctrl[0],2*cur[1]-last_ctrl[1]) if prev in ("Q","T") and last_ctrl else cur
                    end=point(v[0],v[1],rel); c2=c1
                p0=cur
                for step in range(1,13):
                    t=step/12; u=1-t
                    if upper in ("C","S"):
                        p=(u**3*p0[0]+3*u*u*t*c1[0]+3*u*t*t*c2[0]+t**3*end[0],
                           u**3*p0[1]+3*u*u*t*c1[1]+3*u*t*t*c2[1]+t**3*end[1])
                    else:
                        p=(u*u*p0[0]+2*u*t*c1[0]+t*t*end[0],
                           u*u*p0[1]+2*u*t*c1[1]+t*t*end[1])
                    append(p)
                cur=end; last_ctrl=c2 if upper in ("C","S") else c1
            else:
                rx, ry, rotation, large, sweep, x, y = v
                end=point(x,y,rel); rx,ry=abs(rx),abs(ry)
                if rx == 0 or ry == 0 or end == cur:
                    append(end)
                else:
                    phi=math.radians(rotation%360); co,si=math.cos(phi),math.sin(phi)
                    dx,dy=(cur[0]-end[0])/2,(cur[1]-end[1])/2
                    xp=co*dx+si*dy; yp=-si*dx+co*dy
                    lam=xp*xp/(rx*rx)+yp*yp/(ry*ry)
                    if lam>1: rx*=math.sqrt(lam); ry*=math.sqrt(lam)
                    sign=-1 if bool(large)==bool(sweep) else 1
                    den=rx*rx*yp*yp+ry*ry*xp*xp
                    factor=sign*math.sqrt(max(0,(rx*rx*ry*ry-den)/max(den,1e-30)))
                    cxp=factor*rx*yp/ry; cyp=-factor*ry*xp/rx
                    cx=co*cxp-si*cyp+(cur[0]+end[0])/2
                    cy=si*cxp+co*cyp+(cur[1]+end[1])/2
                    a0=math.atan2((yp-cyp)/ry,(xp-cxp)/rx)
                    a1=math.atan2((-yp-cyp)/ry,(-xp-cxp)/rx)
                    delta=(a1-a0)%(2*math.pi)
                    if not sweep and delta>0: delta-=2*math.pi
                    elif sweep and delta<0: delta+=2*math.pi
                    steps=max(4,int(math.ceil(abs(delta)/(math.pi/24))))
                    for step in range(1,steps+1):
                        a=a0+delta*step/steps
                        append((cx+rx*co*math.cos(a)-ry*si*math.sin(a),
                                cy+rx*si*math.cos(a)+ry*co*math.sin(a)))
                cur=end
                last_ctrl=None
            prev=upper if upper not in ("M",) else "M"
        if len(points)>1: result.append(points)
        return result

    def text_length(value, font_size=16.0, percentage=False):
        match = re.fullmatch(
            r"\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)\s*([a-zA-Z%]*)\s*",
            value)
        if not match:
            raise ValueError(f"Unsupported SVG text length: {value!r}. Convert text to paths first.")
        unit = match.group(2)
        factors = {key: factor/(25.4/96) for key, factor in units.items()}
        factors.update({"":1.0, "em":font_size})
        if percentage: factors["%"] = font_size/100
        if unit not in factors:
            raise ValueError(f"Unsupported SVG text unit: {unit!r}. Convert text to paths first.")
        return float(match.group(1))*factors[unit]

    def text_contours(element, properties):
        if len(element):
            raise ValueError("SVG text with tspan/textPath or other child elements is not supported. "
                             "Convert this text to paths first.")
        text = re.sub(r"\s+", " ", element.text or "").strip()
        size = properties["font-size"]
        if not text or size <= 0: return []
        if QApplication.instance() is None:
            raise ValueError("SVG text import requires a running Qt application.")
        font = QFont()
        families = [family.strip().strip("'\"")
                    for family in properties.get("font-family", "serif").split(",")]
        font.setFamilies(families)
        font.setPixelSize(max(1, round(size)))
        weight = properties.get("font-weight", "normal")
        if weight in ("normal", "bold"):
            font.setWeight(QFont.Normal if weight == "normal" else QFont.Bold)
        elif weight.isdigit() and 100 <= int(weight) <= 900:
            weights = [QFont.Thin, QFont.ExtraLight, QFont.Light, QFont.Normal, QFont.Medium,
                       QFont.DemiBold, QFont.Bold, QFont.ExtraBold, QFont.Black]
            font.setWeight(weights[max(0, min(8, round(int(weight)/100)-1))])
        else:
            raise ValueError(f"Unsupported SVG font weight: {weight!r}. Convert text to paths first.")
        font.setItalic(properties.get("font-style") in ("italic", "oblique"))
        ratio = size/font.pixelSize()
        metrics = QFontMetricsF(font)
        x = text_length(element.get("x", "0"), size) + text_length(element.get("dx", "0"), size)
        y = text_length(element.get("y", "0"), size) + text_length(element.get("dy", "0"), size)
        anchor = properties.get("text-anchor", "start")
        if anchor not in ("start", "middle", "end"):
            raise ValueError(f"Unsupported SVG text anchor: {anchor!r}")
        x -= metrics.horizontalAdvance(text)*ratio*{"start":0, "middle":0.5, "end":1}[anchor]
        baseline = properties.get("dominant-baseline", "auto")
        if baseline == "middle": y += metrics.xHeight()*ratio/2
        elif baseline == "central": y += (metrics.ascent()-metrics.descent())*ratio/2
        elif baseline in ("hanging", "text-before-edge", "text-top"): y += metrics.ascent()*ratio
        elif baseline in ("text-after-edge", "text-bottom"): y -= metrics.descent()*ratio
        elif baseline not in ("auto", "alphabetic"):
            raise ValueError(f"Unsupported SVG text baseline: {baseline!r}. Convert text to paths first.")
        outline = QPainterPath()
        outline.addText(0, 0, font, text)
        # Scale before flattening to retain fractional SVG font sizes and separate glyph holes.
        outline = QTransform.fromScale(ratio, ratio).map(outline)
        return [[(point.x()+x, point.y()+y) for point in polygon]
                for polygon in outline.toSubpathPolygons() if len(polygon)>1]

    contours=[]
    def walk(element, parent_matrix, hidden=False, inherited=None):
        style = dict(item.split(":", 1) for item in element.get("style", "").split(";") if ":" in item)
        style = {key.strip(): value.strip() for key, value in style.items()}
        invisible = hidden or style.get("display", element.get("display")) == "none"
        if invisible: return
        properties = dict(inherited or {"font-size":16.0})
        for name in ("font-family", "font-size", "font-weight", "font-style",
                     "text-anchor", "dominant-baseline"):
            value = style.get(name, element.get(name))
            if value is not None and value != "inherit":
                properties[name] = text_length(value, properties["font-size"], percentage=True) if name=="font-size" else value
        matrix=matrix_multiply(parent_matrix,parse_transform(element.get("transform")))
        tag=element.tag.rsplit("}",1)[-1]
        attrs=element.attrib
        made=[]
        if tag=="path": made=path_contours(attrs.get("d",""))
        elif tag=="text": made=text_contours(element, properties)
        elif tag in ("polyline","polygon"):
            vals=[float(x) for x in re.findall(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?",
                                               attrs.get("points",""))]
            pts=list(zip(vals[::2],vals[1::2]))
            if tag=="polygon" and len(pts)>1: pts.append(pts[0])
            if len(pts)>1: made=[pts]
        elif tag=="line":
            made=[[(number(attrs.get("x1")),number(attrs.get("y1"))),
                   (number(attrs.get("x2")),number(attrs.get("y2")))]]
        elif tag in ("rect","circle","ellipse"):
            if tag=="rect":
                x,y=number(attrs.get("x")),number(attrs.get("y"))
                w,h=number(attrs.get("width")),number(attrs.get("height"))
                if w>0 and h>0: made=[[(x,y),(x+w,y),(x+w,y+h),(x,y+h),(x,y)]]
            else:
                cx,cy=number(attrs.get("cx")),number(attrs.get("cy"))
                rx=number(attrs.get("r")) if tag=="circle" else number(attrs.get("rx"))
                ry=rx if tag=="circle" else number(attrs.get("ry"))
                if rx>0 and ry>0:
                    pts=[(cx+rx*math.cos(2*math.pi*i/64),
                          cy+ry*math.sin(2*math.pi*i/64)) for i in range(65)]
                    made=[pts]
        text_indices = []
        for contour in made:
            pts=[]
            for x,y in contour:
                a,b,c,d,e,f=matrix
                pts.append((a*x+c*y+e,b*x+d*y+f))
            if len(pts)>1:
                text_indices.append(len(contours))
                contours.append(pts)
        if tag == "text" and text_indices and text_groups is not None:
            text_groups.append({"label":re.sub(r"\s+", " ", element.text or "").strip(),
                                "contours":text_indices})
        for child in element:
            walk(child,matrix,invisible,properties)
    walk(root,(1,0,0,1,0,0))
    if not contours: raise ValueError("The SVG contains no supported visible geometry")
    flat=[p for contour in contours for p in contour]
    lo_x,hi_x=min(p[0] for p in flat),max(p[0] for p in flat)
    lo_y,hi_y=min(p[1] for p in flat),max(p[1] for p in flat)
    cx,cy=(lo_x+hi_x)/2,(lo_y+hi_y)/2
    converted=[[( (x-cx)*scale, -(y-cy)*scale) for x,y in contour] for contour in contours]
    return converted


def dxf_to_contours(path):
    """Read supported DXF model-space geometry into centered sketch coordinates in mm."""
    try:
        import ezdxf
        from ezdxf.disassemble import recursive_decompose
        from ezdxf.path import make_path
        from ezdxf.units import MM, conversion_factor
    except ImportError as ex:
        raise ValueError("DXF import requires ezdxf. Install it with 'python -m pip install ezdxf'.") from ex
    try:
        document = ezdxf.readfile(path)
    except (ezdxf.DXFError, OSError, UnicodeError) as ex:
        raise ValueError(f"Could not read DXF: {ex}") from ex

    source_units = int(document.header.get("$INSUNITS", 0) or 0)
    try:
        scale = conversion_factor(source_units, MM) if source_units else 1.0
    except (TypeError, ValueError) as ex:
        raise ValueError(f"Unsupported DXF drawing units: {source_units}") from ex

    contours = []
    flattening_distance = 0.02 / scale
    for entity in recursive_decompose(document.modelspace()):
        try:
            points = list(make_path(entity).flattening(distance=flattening_distance))
        except (TypeError, ValueError):
            continue
        if len(points) > 1:
            contours.append([(float(point.x), float(point.y)) for point in points])
    if not contours:
        raise ValueError("The DXF contains no supported model-space geometry")

    flat = [point for contour in contours for point in contour]
    lo_x, hi_x = min(point[0] for point in flat), max(point[0] for point in flat)
    lo_y, hi_y = min(point[1] for point in flat), max(point[1] for point in flat)
    cx, cy = (lo_x + hi_x) / 2, (lo_y + hi_y) / 2
    return [[((x - cx) * scale, -(y - cy) * scale) for x, y in contour]
            for contour in contours]


TEXT_FONT_CHOICES = [
    "Arial", "Arial Black", "Times New Roman", "Gothic", "Impact", "Calibri",
    "Cascadia Code", "Century", "Comic Sans MS", "Fixedsys", "Lucida Handwriting",
    "Stencil", "Wide Latin",
]


def text_contours(text, font_family="Arial", font_size=12.0,
                  bold=False, italic=False, underline=False, align="left"):
    """Text outlines in sketch coordinates (mm), centred vertically around y=0.
    Horizontal anchoring follows align: left, center, right."""
    text = str(text or "").strip()
    if not text:
        return []
    family = font_family if font_family in TEXT_FONT_CHOICES else "Arial"
    font = QFont(family)
    font.setPixelSize(max(1, int(round(float(font_size)))))
    font.setBold(bool(bold))
    font.setItalic(bool(italic))
    metrics = QFontMetricsF(font)
    path = QPainterPath()
    path.addText(0.0, 0.0, font, text)
    rect = path.boundingRect()
    if rect.isEmpty():
        return []
    if align == "right":
        shift_x = -rect.right()
    elif align == "center":
        shift_x = -(rect.left() + rect.right())/2.0
    else:
        shift_x = -rect.left()
    shift_y = -(rect.top() + rect.bottom())/2.0

    contours = []
    for poly in path.toSubpathPolygons(QTransform()):
        pts = []
        for q in poly:
            x = float(q.x()) + shift_x
            y = -(float(q.y()) + shift_y)
            pts.append((x, y))
        if len(pts) > 1:
            if math.hypot(pts[0][0]-pts[-1][0], pts[0][1]-pts[-1][1]) > 1e-9:
                pts.append(pts[0])
            contours.append(pts)

    if underline:
        y_ul = metrics.underlinePos()
        x0, x1 = rect.left() + shift_x, rect.right() + shift_x
        y = -(float(y_ul) + shift_y)
        half_thickness = max(0.5, float(font_size)*0.03)
        contours.append([(x0, y-half_thickness), (x1, y-half_thickness),
                         (x1, y+half_thickness), (x0, y+half_thickness),
                         (x0, y-half_thickness)])
    return contours


def sketch_to_dict(sk):
    """Serialise a sketch (geometry + constraints) to plain JSON-able data."""
    dropped = sk.prune_dangling_constraints()     # never let a stale reference break undo / save
    if dropped:
        _dbg(f"sketch_to_dict: dropped {dropped} constraint(s) referring to deleted geometry")
    for v in sk.used_vertices():
        if v not in sk.vertices: sk.vertices.append(v)
    vid = {v: i for i, v in enumerate(sk.vertices)}
    sid = {s: i for i, s in enumerate(sk.segments)}
    cid = {c: i for i, c in enumerate(sk.circles)}
    aid = {a: i for i, a in enumerate(sk.arcs)}
    eid = {e: i for i, e in enumerate(sk.ellipses)}
    sk.prune_groups()
    def ref(o):
        if isinstance(o, Segment) and getattr(o, "sketch_axis", None) is not None:
            return {"axis": o.sketch_axis}
        if isinstance(o, Vertex):  return {"v": vid[o]}
        if isinstance(o, Segment): return {"s": sid[o]}
        if isinstance(o, Circle):  return {"c": cid[o]}
        if isinstance(o, Arc):     return {"a": aid[o]}
        if isinstance(o, tuple):   return {"tuple": [ref(x) for x in o]}
        if isinstance(o, np.generic): return o.item()
        return o
    cons = []
    for c in sk.constraints:
        d = {k: ref(v) for k, v in c.__dict__.items() if not k.startswith("_")}
        d["__type__"] = type(c).__name__
        cons.append(d)
    return {"name": sk.name, "plane": sk.plane,
            "frame": [[float(x) for x in a] for a in sk.frame],
            "face_rotation": list(sk.face_rotation),
            "vertices": [[v.x, v.y, v.locked] for v in sk.vertices],
            "segments": [[vid[s.v0], vid[s.v1], s.construction, s.reference] for s in sk.segments],
            "circles": [[vid[c.center], c.radius, c.construction, c.reference] for c in sk.circles],
            "arcs": [[vid[a.center], vid[a.v_start], vid[a.v_end], a.construction, a.reference]
                     for a in sk.arcs],
            "ellipses": [[vid[ellipse.major_start], vid[ellipse.major_end],
                          vid[ellipse.minor_start], vid[ellipse.minor_end],
                          ellipse.construction, ellipse.reference]
                         for ellipse in sk.ellipses],
            "points_free": [vid[v] for v in sk.points_free],
            "text_groups": [{"label": group.label,
                             "segments": [sid[s] for s in group.segments],
                             "box_points": [vid[v] for v in group.box_vertices if v in vid],
                             "font_family": group.font_family,
                             "font_size": group.font_size,
                             "bold": group.bold,
                             "italic": group.italic,
                             "underline": group.underline,
                             "align": group.align}
                            for group in sk.text_groups],
            "groups": [{"segments": [sid[s] for s in g.segments if s in sid],
                        "circles": [cid[c] for c in g.circles if c in cid],
                        "arcs": [aid[a] for a in g.arcs if a in aid],
                        "ellipses": [eid[e] for e in g.ellipses if e in eid],
                        "points": [vid[v] for v in g.points if v in vid],
                        "ref": [[vid[v], x, y] for v, (x, y) in g.ref.items() if v in vid],
                        "radii": [[cid[c], r] for c, r in g.radii.items() if c in cid]}
                       for g in getattr(sk, "groups", [])],
            "constraints": cons,
            "reference_boundaries": {
                key: {str(i): element.reference_boundary for i, element in enumerate(elements)
                      if hasattr(element, "reference_boundary")}
                for key, elements in (("segments", sk.segments), ("circles", sk.circles),
                                      ("arcs", sk.arcs))},
            "reference_generated_levels": sk.reference_generated_levels,
            "reference_levels": {
                key: {str(i): element.reference_level for i, element in enumerate(elements)
                      if hasattr(element, "reference_level")}
                for key, elements in (("vertices", sk.vertices), ("segments", sk.segments),
                                      ("circles", sk.circles), ("arcs", sk.arcs),
                                      ("ellipses", sk.ellipses))},
            "reference_sources": {
                key: {str(i): list(element.reference_source) for i, element in enumerate(elements)
                      if hasattr(element, "reference_source")}
                for key, elements in (("vertices", sk.vertices), ("segments", sk.segments),
                                      ("circles", sk.circles))}}

def sketch_from_dict(d):
    return sketch_fill(Sketch(d["plane"], name=d["name"], frame=d["frame"]), d)

def sketch_fill(sk, d):
    """Replace the geometry and constraints of sketch sk (in place) by those of dict d."""
    sk.face_rotation = tuple(d.get("face_rotation", (1.0, 0.0)))
    sk.reference_generated_levels = list(d.get("reference_generated_levels", []))
    sk.legacy_reference_levels = "reference_levels" not in d
    V = sk.vertices = [Vertex(x, y, locked) for x, y, locked in d["vertices"]]
    sk.segments = [Segment(V[a], V[b], con, ref) for a, b, con, ref in d["segments"]]
    sk.circles  = [Circle(V[c], r, con, ref) for c, r, con, ref in d["circles"]]
    sk.arcs     = [Arc(V[c], V[s], V[e], con, ref) for c, s, e, con, ref in d["arcs"]]
    for key in ("segments", "circles", "arcs"):
        elements = getattr(sk, key)
        for index, boundary in d.get("reference_boundaries", {}).get(key, {}).items():
            elements[int(index)].reference_boundary = boundary
    sk.ellipses = [Ellipse(V[a], V[b], V[c], V[e], con, ref)
                   for a, b, c, e, con, ref in d.get("ellipses", [])]
    for key in ("vertices", "segments", "circles", "arcs", "ellipses"):
        elements = getattr(sk, key)
        for index, level in d.get("reference_levels", {}).get(key, {}).items():
            elements[int(index)].reference_level = level
    for key in ("vertices", "segments", "circles"):
        elements = getattr(sk, key)
        for index, source in d.get("reference_sources", {}).get(key, {}).items():
            elements[int(index)].reference_source = (str(source[0]), str(source[1]), int(source[2]))
    sk.points_free = [V[i] for i in d["points_free"]]
    sk.text_groups = []
    for group in d.get("text_groups", []):
        segs = [sk.segments[i] for i in group["segments"]]
        box_pts = [V[i] for i in group.get("box_points", []) if 0 <= i < len(V)]
        if len(box_pts) < 9 and segs:
            box_pts = sk._make_text_box_vertices(segs)
        sk.text_groups.append(SketchText(
            group.get("label", ""), segs,
            box_vertices=box_pts,
            font_family=group.get("font_family", "Arial"),
            font_size=group.get("font_size", 12.0),
            bold=group.get("bold", False),
            italic=group.get("italic", False),
            underline=group.get("underline", False),
            align=group.get("align", "left"),
        ))
    sk.groups = []
    for gd in d.get("groups", []):
        pick = lambda items, key: [items[i] for i in gd.get(key, []) if 0 <= i < len(items)]
        g = SketchGroup(pick(sk.segments, "segments"), pick(sk.circles, "circles"),
                        pick(sk.arcs, "arcs"), pick(sk.ellipses, "ellipses"),
                        pick(V, "points"))
        for i, x, y in gd.get("ref", []):
            if 0 <= i < len(V) and V[i] in g.ref: g.ref[V[i]] = (float(x), float(y))
        for i, r in gd.get("radii", []):
            if 0 <= i < len(sk.circles) and sk.circles[i] in g.radii:
                g.radii[sk.circles[i]] = float(r)
        if g.elements(): sk.groups.append(g)
    def deref(o):
        if isinstance(o, dict):
            if "axis" in o: return sk.axis_segment(o["axis"])
            if "v" in o: return V[o["v"]]
            if "s" in o: return sk.segments[o["s"]]
            if "c" in o: return sk.circles[o["c"]]
            if "a" in o: return sk.arcs[o["a"]]
            if "tuple" in o: return tuple(deref(x) for x in o["tuple"])
        return o
    sk.constraints = []
    for cd in d["constraints"]:
        cls = CONSTRAINT_CLASSES[cd["__type__"]]
        c = cls.__new__(cls)
        for k, v in cd.items():
            if k != "__type__": setattr(c, k, deref(v))
        sk.constraints.append(c)
    # older versions kept the midpoint symmetry on a line shortened by Trim; that constraint
    # no longer holds and the next solve would pull the piece back: keep the lines symmetric
    removed = sk.merge_duplicate_geometry()        # shapes mirrored onto themselves before
    if removed:
        _dbg(f"sketch_fill: {sk.name}: removed {removed} duplicate element(s) lying on top of others")
    position = lambda v: (v.x, v.y)
    for c in sk.constraints:
        if isinstance(c, CSymmetric) and isinstance(c.seg_a, Segment) and \
                isinstance(c.seg_b, Segment) and not symmetric_lines_only(c) and \
                symmetric_mid_error(c, position) > 1e-4 and \
                abs(symmetric_line_residual(c, position)) < 1e-4:
            c.lines_only = True
    sk._an_key = None; sk._an = None
    return sk

class History:
    """Snapshot undo / redo. States are strings (JSON); push() only records real changes."""
    def __init__(self, state=None, limit=200):
        self.limit = limit; self.reset(state)
    def reset(self, state):
        self.undo_stack, self.redo_stack, self.cur = [], [], state
    def push(self, state):
        if state == self.cur: return False
        if self.cur is not None:
            self.undo_stack.append(self.cur); del self.undo_stack[:-self.limit]
        self.cur = state; self.redo_stack.clear()
        return True
    def undo(self):
        if not self.undo_stack: return None
        self.redo_stack.append(self.cur); self.cur = self.undo_stack.pop()
        return self.cur
    def redo(self):
        if not self.redo_stack: return None
        self.undo_stack.append(self.cur); self.cur = self.redo_stack.pop()
        return self.cur

def entry_bounds(entry):
    """(min xyz, max xyz) of an entry in world coordinates, or None."""
    if entry["type"] in ("extrusion", "imported"):
        V = np.asarray(entry["solid"][0], float)
        return (V.min(0), V.max(0)) if len(V) else None
    if entry["type"] == "surface":
        origin, u, v, _ = entry["frame"]
        u = np.asarray(u, float) * entry["width"]/2
        v = np.asarray(v, float) * entry["height"]/2
        O = np.asarray(origin, float)
        corners = np.asarray([O-u-v, O+u-v, O+u+v, O-u+v])
        return corners.min(0), corners.max(0)
    if entry["type"] != "sketch": return None
    sk = entry["sketch"]
    pts = [p for pts2, _ in sketch_polylines(sk) for p in pts2] + [v.xy() for v in sk.points_free]
    if not pts: return None
    P = sk.to3d_many(pts)
    return P.min(0), P.max(0)

def _validate_mesh(vertices, triangles):
    """Validate mesh arrays and normalize their vertices and triangle indices."""
    V = np.asarray(vertices, dtype=float)
    T = np.asarray(triangles, dtype=np.int64)
    if V.ndim != 2 or V.shape[1] != 3 or not len(V):
        raise ValueError("The imported file contains no 3-D vertices")
    if T.ndim != 2 or T.shape[1] != 3 or not len(T):
        raise ValueError("The imported file contains no triangles")
    if not np.isfinite(V).all():
        raise ValueError("The imported mesh contains non-finite coordinates")
    if T.min() < 0 or T.max() >= len(V):
        raise ValueError("The imported mesh contains an invalid triangle index")
    return [tuple(map(float, v)) for v in V], [tuple(map(int, t)) for t in T]

def _center_mesh(vertices, triangles):
    """Validate a triangle mesh and center its bounding box at the world origin."""
    vertices, triangles = _validate_mesh(vertices, triangles)
    V = np.asarray(vertices, dtype=float)
    V -= (V.min(axis=0) + V.max(axis=0)) / 2.0
    return [tuple(map(float, v)) for v in V], triangles


_DRAWING_FINGERPRINTS = {}        # id → (object, key): the projected views reuse their lists


def _drawing_fingerprint(items):
    """Cheap content key of drawn geometry (an array or a list of arrays) for caches: count,
    sizes and coordinate sums."""
    known = _DRAWING_FINGERPRINTS.get(id(items))
    if known is not None and known[0] is items:
        return known[1]
    if isinstance(items, np.ndarray):
        key = (items.shape, round(float(items.sum()), 6), round(float(np.abs(items).sum()), 6))
    else:
        parts = []
        for item in items:
            array = np.asarray(item, dtype=float)
            parts.append((array.shape, round(float(array.sum()), 6)))
        key = (len(parts), tuple(parts))
    if len(_DRAWING_FINGERPRINTS) > 256:
        _DRAWING_FINGERPRINTS.clear()
    _DRAWING_FINGERPRINTS[id(items)] = (items, key)
    return key


def _drawing_view_frame(normal, up_hint):
    """Return a right-handed screen basis for an orthographic viewing direction."""
    n = np.asarray(normal, dtype=float)
    n /= np.linalg.norm(n)
    up = np.asarray(up_hint, dtype=float)
    right = np.cross(up, n)
    if np.linalg.norm(right) < 1e-8:
        up = np.array((0.0, 1.0, 0.0))
        right = np.cross(up, n)
    right /= np.linalg.norm(right)
    up = np.cross(n, right)
    up /= np.linalg.norm(up)
    return right, up, n


DRAWING_PAGE_W, DRAWING_PAGE_H = 2376.0, 1680.0      # A2 landscape, 4 page units per mm
# ── Tolerances (Technical Drawing, Phase 1) ──────────────────────────────────
# ISO 286-1 limits and fits, ISO 2768-1 general tolerances, the text of a toleranced dimension
# and the geometric tolerance / datum / surface finish / weld annotations. Sizes are nominal
# sizes in mm (1 … 500), deviations are returned in mm (the standard tables are in µm).
#   holes   D, E, F, G, H, JS, K, M, N, P, R, S      grades IT5 … IT11
#   shafts  d, e, f, g, h, js, k, m, n, p, r, s      (r, s tabulated up to 50 mm)
# A dimension stores its tolerance as {"mode": "none" | "symmetric" | "deviations" | "limits" |
# "fit", "upper", "lower", "fit": "H7", "show_deviations": True} (see tol_normalize_tolerance).
# Annotations are entries of the sheet's dimension list with type "annotation".

TOL_MODES = ("none", "symmetric", "deviations", "limits", "fit")
TOL_MODE_TITLES = {"none": "None", "symmetric": "Symmetric (±)", "deviations": "Deviations (+ / −)",
               "limits": "Limit values (max / min)", "fit": "ISO 286 fit symbol"}


class ToleranceError(ValueError):
    """A fit or tolerance that cannot be evaluated (the message is meant for the user)."""


# ── ISO 286-1 ─────────────────────────────────────────────────────────────────
# nominal size ranges (over, up to and including) in mm
TOL_SIZE_RANGES = ((0, 3), (3, 6), (6, 10), (10, 18), (18, 30), (30, 50), (50, 80), (80, 120),
               (120, 180), (180, 250), (250, 315), (315, 400), (400, 500))

# standard tolerance grades in µm per size range
TOL_IT_TABLE = {
    1: (0.8, 1, 1, 1.2, 1.5, 1.5, 2, 2.5, 3.5, 4.5, 6, 7, 8),
    2: (1.2, 1.5, 1.5, 2, 2.5, 2.5, 3, 4, 5, 7, 8, 9, 10),
    3: (2, 2.5, 2.5, 3, 4, 4, 5, 6, 8, 10, 12, 13, 15),
    4: (3, 4, 4, 5, 6, 7, 8, 10, 12, 14, 16, 18, 20),
    5: (4, 5, 6, 8, 9, 11, 13, 15, 18, 20, 23, 25, 27),
    6: (6, 8, 9, 11, 13, 16, 19, 22, 25, 29, 32, 36, 40),
    7: (10, 12, 15, 18, 21, 25, 30, 35, 40, 46, 52, 57, 63),
    8: (14, 18, 22, 27, 33, 39, 46, 54, 63, 72, 81, 89, 97),
    9: (25, 30, 36, 43, 52, 62, 74, 87, 100, 115, 130, 140, 155),
    10: (40, 48, 58, 70, 84, 100, 120, 140, 160, 185, 210, 230, 250),
    11: (60, 75, 90, 110, 130, 160, 190, 220, 250, 290, 320, 360, 400),
    12: (100, 120, 150, 180, 210, 250, 300, 350, 400, 460, 520, 570, 630),
    13: (140, 180, 220, 270, 330, 390, 460, 540, 630, 720, 810, 890, 970),
    14: (250, 300, 360, 430, 520, 620, 740, 870, 1000, 1150, 1300, 1400, 1550),
    15: (400, 480, 580, 700, 840, 1000, 1200, 1400, 1600, 1850, 2100, 2300, 2500),
    16: (600, 750, 900, 1100, 1300, 1600, 1900, 2200, 2500, 2900, 3200, 3600, 4000),
}
TOL_SUPPORTED_GRADES = tuple(range(5, 12))

# fundamental deviations of shafts in µm per size range: a–h → upper deviation es,
# k–s → lower deviation ei (k for IT4 … IT7 only; other grades 0)
TOL_SHAFT_DEVIATION = {
    "d": (-20, -30, -40, -50, -65, -80, -100, -120, -145, -170, -190, -210, -230),
    "e": (-14, -20, -25, -32, -40, -50, -60, -72, -85, -100, -110, -125, -135),
    "f": (-6, -10, -13, -16, -20, -25, -30, -36, -43, -50, -56, -62, -68),
    "g": (-2, -4, -5, -6, -7, -9, -10, -12, -14, -15, -17, -18, -20),
    "h": (0,) * 13,
    "k": (0, 1, 1, 1, 2, 2, 2, 3, 3, 4, 4, 4, 5),
    "m": (2, 4, 6, 7, 8, 9, 11, 13, 15, 17, 20, 21, 23),
    "n": (4, 8, 10, 12, 15, 17, 20, 23, 27, 31, 34, 37, 40),
    "p": (6, 12, 15, 18, 22, 26, 32, 37, 43, 50, 56, 62, 68),
    # r and s are tabulated here only up to 50 mm (the larger ranges split further)
    "r": (10, 15, 19, 23, 28, 34),
    "s": (14, 19, 23, 28, 35, 43),
}
TOL_UPPER_LETTERS = "defgh"            # a–h: the table value is the upper deviation
TOL_HOLE_LETTERS = ("D", "E", "F", "G", "H", "JS", "K", "M", "N", "P", "R", "S")
TOL_SHAFT_LETTERS = ("d", "e", "f", "g", "h", "js", "k", "m", "n", "p", "r", "s")
# holes K … S: the shaft value is mirrored and Δ = IT(n) − IT(n−1) is added up to this grade
TOL_DELTA_UP_TO = {"K": 8, "M": 8, "N": 8, "P": 7, "R": 7, "S": 7}

# preferred fits (ISO 286 / DIN 7157), hole-basis first
TOL_PREFERRED_FITS = (("H7", "g6"), ("H7", "h6"), ("H7", "f7"), ("H7", "k6"), ("H7", "n6"),
                  ("H7", "p6"), ("H8", "f7"), ("H8", "h9"), ("H11", "h11"), ("H9", "d9"),
                  ("H7", "s6"), ("H7", "e8"), ("G7", "h6"), ("F8", "h6"), ("K7", "h6"),
                  ("N7", "h6"), ("P7", "h6"), ("S7", "h6"))


def tol_size_range_index(size):
    if not (isinstance(size, (int, float)) and math.isfinite(size)) or size <= 0:
        raise ToleranceError("The nominal size must be greater than 0 mm.")
    for index, (low, high) in enumerate(TOL_SIZE_RANGES):
        if low < size <= high:
            return index
    raise ToleranceError(f"ISO 286 fits are available up to 500 mm (nominal size {size:g} mm).")


def tol_it_value(grade, size):
    """Standard tolerance (width of the tolerance zone) in mm."""
    if grade not in TOL_IT_TABLE:
        raise ToleranceError(f"IT{grade} is not available.")
    return TOL_IT_TABLE[grade][tol_size_range_index(size)] / 1000.0


def tol_parse_fit_symbol(symbol):
    """'H7' → ('H', 7, True) for a hole, 'g6' → ('g', 6, False) for a shaft."""
    text = str(symbol).strip().replace(" ", "")
    letters = ""
    while text and text[0].isalpha():
        letters, text = letters + text[0], text[1:]
    if not letters or not text.isdigit():
        raise ToleranceError(f"'{symbol}' is not a fit symbol (for example H7 or g6).")
    grade = int(text)
    is_hole = letters.isupper()
    return letters, grade, is_hole


def tol_table_value(letter, size):
    table = TOL_SHAFT_DEVIATION.get(letter.lower())
    if table is None:
        raise ToleranceError(f"The fit letter '{letter}' is not supported "
                             f"(holes: {', '.join(TOL_HOLE_LETTERS)}; shafts: {', '.join(TOL_SHAFT_LETTERS)}).")
    index = tol_size_range_index(size)
    if index >= len(table):
        raise ToleranceError(f"The fit letter '{letter}' is tabulated up to 50 mm only "
                             f"(nominal size {size:g} mm).")
    return table[index]


def tol_deviations(symbol, size):
    """(upper, lower) deviation in mm of a hole ('H7') or a shaft ('g6') of nominal size `size`."""
    letter, grade, is_hole = tol_parse_fit_symbol(symbol)
    if grade not in TOL_SUPPORTED_GRADES:
        raise ToleranceError(f"Grade IT{grade} is not supported (IT{TOL_SUPPORTED_GRADES[0]} … "
                             f"IT{TOL_SUPPORTED_GRADES[-1]}).")
    it = tol_it_value(grade, size) * 1000.0                        # µm
    if letter.upper() == "JS":
        upper, lower = it / 2.0, -it / 2.0
    elif is_hole:
        if letter not in TOL_HOLE_LETTERS:
            raise ToleranceError(f"The hole letter '{letter}' is not supported "
                                 f"({', '.join(TOL_HOLE_LETTERS)}).")
        value = tol_table_value(letter, size)
        if letter.lower() in TOL_UPPER_LETTERS:                    # D … H: EI = −es
            lower = -value
            upper = lower + it
        else:                                                  # K … S: ES = −ei (+ Δ)
            if letter == "K" and grade > 8:
                upper = 0.0
            else:
                delta = 0.0
                if grade <= TOL_DELTA_UP_TO[letter] and grade > 3:
                    delta = it - tol_it_value(grade - 1, size) * 1000.0
                upper = -value + delta
            lower = upper - it
    else:
        if letter not in TOL_SHAFT_LETTERS:
            raise ToleranceError(f"The shaft letter '{letter}' is not supported "
                                 f"({', '.join(TOL_SHAFT_LETTERS)}).")
        value = tol_table_value(letter, size)
        if letter in TOL_UPPER_LETTERS:                            # d … h: es
            upper = value
            lower = upper - it
        else:                                                  # k … s: ei
            if letter == "k" and not 4 <= grade <= 7:
                value = 0
            lower = value
            upper = lower + it
    return round(upper / 1000.0, 6), round(lower / 1000.0, 6)


def tol_fit_limits(symbol, size):
    """Limits of size (maximum, minimum) of a hole or a shaft symbol."""
    upper, lower = tol_deviations(symbol, size)
    return size + upper, size + lower


def tol_analyse_fit(hole, shaft, size):
    """Hole + shaft symbol → limits, clearances and the kind of fit."""
    hole_letter, _, hole_is_hole = tol_parse_fit_symbol(hole)
    shaft_letter, _, shaft_is_hole = tol_parse_fit_symbol(shaft)
    if not hole_is_hole:
        raise ToleranceError("The hole symbol needs capital letters (for example H7).")
    if shaft_is_hole:
        raise ToleranceError("The shaft symbol needs lower-case letters (for example g6).")
    hole_up, hole_low = tol_deviations(hole, size)
    shaft_up, shaft_low = tol_deviations(shaft, size)
    max_clearance = round(hole_up - shaft_low, 6)             # largest hole − smallest shaft
    min_clearance = round(hole_low - shaft_up, 6)             # smallest hole − largest shaft
    if min_clearance >= 0:
        kind = "clearance"
    elif max_clearance <= 0:
        kind = "interference"
    else:
        kind = "transition"
    return {"size": size, "hole": hole, "shaft": shaft, "hole_dev": (hole_up, hole_low),
            "shaft_dev": (shaft_up, shaft_low),
            "hole_limits": (size + hole_up, size + hole_low),
            "shaft_limits": (size + shaft_up, size + shaft_low),
            "max_clearance": max_clearance, "min_clearance": min_clearance, "kind": kind}


def tol_fit_report(result):
    """Text lines of tol_analyse_fit() for the fit calculator."""
    def mm(value):
        return f"{value:+.3f}".replace("+0.000", "0").replace("-0.000", "0")
    lines = [f"Nominal size {result['size']:g} mm",
             f"Hole {result['hole']}: {mm(result['hole_dev'][0])} / {mm(result['hole_dev'][1])} mm"
             f"  →  {result['hole_limits'][1]:.3f} … {result['hole_limits'][0]:.3f} mm",
             f"Shaft {result['shaft']}: {mm(result['shaft_dev'][0])} / {mm(result['shaft_dev'][1])} mm"
             f"  →  {result['shaft_limits'][1]:.3f} … {result['shaft_limits'][0]:.3f} mm"]
    if result["kind"] == "interference":
        lines.append(f"Maximum interference: {-result['min_clearance']:.3f} mm")
        lines.append(f"Minimum interference: {-result['max_clearance']:.3f} mm")
    else:
        lines.append(f"Maximum clearance: {result['max_clearance']:.3f} mm")
        lines.append(f"Minimum clearance: {result['min_clearance']:.3f} mm"
                     if result["kind"] == "clearance" else
                     f"Maximum interference: {-result['min_clearance']:.3f} mm")
    lines.append(f"Fit type: {result['kind']}")
    return lines


# ── ISO 2768-1 general tolerances (linear sizes) ─────────────────────────────
TOL_GENERAL_CLASSES = {"f": "fine", "m": "medium", "c": "coarse", "v": "very coarse"}
TOL_GENERAL_FORM_CLASSES = {"H": "fine", "K": "medium", "L": "coarse"}      # ISO 2768-2
TOL_GENERAL_RANGES = ((0.5, 3), (3, 6), (6, 30), (30, 120), (120, 400), (400, 1000),
                  (1000, 2000), (2000, 4000))
TOL_GENERAL_TABLE = {
    "f": (0.05, 0.05, 0.1, 0.15, 0.2, 0.3, 0.5, None),
    "m": (0.1, 0.1, 0.2, 0.3, 0.5, 0.8, 1.2, 2.0),
    "c": (0.2, 0.3, 0.5, 0.8, 1.2, 2.0, 3.0, 4.0),
    "v": (None, 0.5, 1.0, 1.5, 2.5, 4.0, 6.0, 8.0),
}
TOL_GENERAL_PRESETS = ["ISO 2768-f", "ISO 2768-m", "ISO 2768-c", "ISO 2768-v",
                   "ISO 2768-mH", "ISO 2768-mK", "ISO 2768-mL", "ISO 2768-fH", "ISO 2768-cL"]


def tol_general_tolerance(designation, size):
    """± tolerance of ISO 2768-1 for a linear size, or None (below 0.5 mm / not tabulated)."""
    text = str(designation).strip().lower().replace("iso 2768-", "").replace("iso2768-", "")
    letter = text[:1]
    if letter not in TOL_GENERAL_TABLE or not size > 0.5:
        return None
    for index, (low, high) in enumerate(TOL_GENERAL_RANGES):
        if low < size <= high:
            return TOL_GENERAL_TABLE[letter][index]
    return None


# ── tolerance on a dimension ──────────────────────────────────────────────────
def tol_normalize_tolerance(raw):
    """A checked tolerance dict (values from a project file are not trusted), or None for none."""
    if not isinstance(raw, dict):
        return None
    mode = raw.get("mode")
    if mode not in TOL_MODES or mode == "none":
        return None
    result = {"mode": mode}

    def number(key):
        value = raw.get(key)
        return float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) \
            and math.isfinite(value) and abs(value) < 1e6 else 0.0
    if mode == "symmetric":
        result["upper"] = abs(number("upper"))
    elif mode in ("deviations", "limits"):
        upper, lower = number("upper"), number("lower")
        if upper < lower:
            upper, lower = lower, upper
        result.update(upper=upper, lower=lower)
    else:
        symbol = str(raw.get("fit", "")).strip()[:12]
        try:
            tol_parse_fit_symbol(symbol)
        except ToleranceError:
            return None
        result.update(fit=symbol, show_deviations=bool(raw.get("show_deviations", True)))
    return result


def tol_decimals(*values):
    count = 0
    for value in values:
        text = f"{abs(value):.5f}".rstrip("0")
        count = max(count, len(text.split(".")[1]) if "." in text else 0)
    return count


def tol_signed(value, places):
    if abs(value) < 0.5 * 10 ** -places:
        return "0"
    return f"{value:+.{places}f}"


def tol_plain(value, places=2):
    text = f"{abs(value):.{max(2, places)}f}"
    text = text.rstrip("0").rstrip(".") if "." in text else text
    return text or "0"


def tol_format_dimension(value, tolerance, prefix="", unit="", factor=1.0, places=2):
    """The printed text of a toleranced dimension: '25 ±0.1', '25 +0.1/-0.2', '25.1/24.9' or
    'Ø25 H7 (+0.021/0)'. `prefix` is R / Ø, `unit` the degree sign of angles. Values and
    tolerances are stored in mm; `factor` converts them to the printed unit (1 / 25.4 for inch)
    with at least `places` decimals."""
    tolerance = tol_normalize_tolerance(tolerance)
    base = f"{prefix}{tol_plain(value * factor, places)}{unit}"
    if tolerance is None:
        return base
    mode = tolerance["mode"]
    try:
        if mode == "symmetric":
            digits = tol_decimals(tolerance["upper"] * factor)
            return f"{base} ±{tol_plain(tolerance['upper'] * factor, digits)}"
        if mode == "deviations":
            upper, lower = tolerance["upper"] * factor, tolerance["lower"] * factor
            digits = tol_decimals(upper, lower)
            return f"{base} {tol_signed(upper, digits)}/{tol_signed(lower, digits)}"
        if mode == "limits":
            high = (value + tolerance["upper"]) * factor
            low = (value + tolerance["lower"]) * factor
            digits = max(places, tol_decimals(high, low))
            return f"{prefix}{high:.{digits}f}{unit}/{prefix}{low:.{digits}f}{unit}"
        # fit: the deviations follow from the nominal size in mm
        text = f"{base} {tolerance['fit'].replace(' ', '')}"
        if tolerance.get("show_deviations", True):
            upper, lower = tol_deviations(tolerance["fit"], value)
            upper, lower = upper * factor, lower * factor
            digits = max(places, tol_decimals(upper, lower))
            text += f" ({tol_signed(upper, digits)}/{tol_signed(lower, digits)})"
        return text
    except ToleranceError:
        return f"{base} {tolerance.get('fit', '')}".rstrip()


def tol_tolerance_summary(value, tolerance):
    """One short line for the dimension list ('H7 +0.021/0', '±0.1', …); '' for none."""
    tolerance = tol_normalize_tolerance(tolerance)
    if tolerance is None:
        return ""
    text = tol_format_dimension(value, tolerance)
    base = tol_plain(value)
    if tolerance["mode"] == "limits":
        return text
    return text[len(base):].strip()


# ── annotations: geometric tolerances, datums, surface finish, weld symbols ────
TOL_ANNOTATION_KINDS = ("gdt", "datum", "surface", "weld", "note", "hole", "thread", "balloon")
TOL_ANNOTATION_TITLES = {"gdt": "Geometric tolerance", "datum": "Datum", "surface": "Surface finish",
                         "weld": "Weld symbol", "note": "Note", "hole": "Hole callout",
                         "thread": "Thread callout", "balloon": "Balloon"}
# ISO 1101 characteristics: key → (title, needs datum, may take a diameter zone)
TOL_GDT_SYMBOLS = {
    "straightness": ("Straightness", False, True), "flatness": ("Flatness", False, False),
    "circularity": ("Circularity", False, False), "cylindricity": ("Cylindricity", False, False),
    "profile_line": ("Profile of a line", False, False),
    "profile_surface": ("Profile of a surface", False, False),
    "parallelism": ("Parallelism", True, True), "perpendicularity": ("Perpendicularity", True, True),
    "angularity": ("Angularity", True, False), "position": ("Position", False, True),
    "concentricity": ("Concentricity / coaxiality", True, True), "symmetry": ("Symmetry", True, False),
    "runout": ("Circular run-out", True, False), "total_runout": ("Total run-out", True, False),
}
TOL_GDT_MODIFIERS = ("", "M", "L", "P")          # none, maximum material, least material, projected
TOL_SURFACE_REMOVAL = {"any": "Any process", "required": "Material removal required",
                   "forbidden": "No material removal"}
TOL_LAY_SYMBOLS = ("", "=", "⊥", "X", "M", "C", "R")
TOL_WELD_TYPES = {"fillet": "Fillet", "square": "Square butt (I)", "v": "V butt", "bevel": "Bevel butt",
              "u": "U butt", "plug": "Plug / slot"}


def tol_clean_text(value, limit=40):
    return str(value if value is not None else "").strip()[:limit]


def tol_number(value):
    """A finite number from a project file, else None."""
    if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) \
            and abs(value) < 1e9:
        return float(value)
    return None


def tol_normalize_annotation(raw):
    """A checked annotation dict (project files are not trusted), or None when unusable."""
    if not isinstance(raw, dict) or raw.get("kind") not in TOL_ANNOTATION_KINDS:
        return None
    kind = raw["kind"]
    offset = raw.get("offset")
    if not (isinstance(offset, (list, tuple)) and len(offset) == 2 and
            all(isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)
                for v in offset)):
        offset = (60.0, -40.0)
    result = {"kind": kind, "offset": [float(offset[0]), float(offset[1])]}
    if kind == "gdt":
        symbol = raw.get("symbol")
        if symbol not in TOL_GDT_SYMBOLS:
            return None
        datums = [tol_clean_text(d, 2).upper() for d in (raw.get("datums") or [])[:3]]
        modifier = raw.get("modifier") if raw.get("modifier") in TOL_GDT_MODIFIERS else ""
        result.update(symbol=symbol, tolerance=tol_clean_text(raw.get("tolerance"), 16),
                      diameter=bool(raw.get("diameter")) and TOL_GDT_SYMBOLS[symbol][2],
                      modifier=modifier, datums=[d for d in datums if d])
    elif kind == "datum":
        letter = tol_clean_text(raw.get("letter"), 2).upper()
        if not letter:
            return None
        result["letter"] = letter
    elif kind == "surface":
        removal = raw.get("removal") if raw.get("removal") in TOL_SURFACE_REMOVAL else "any"
        lay = raw.get("lay") if raw.get("lay") in TOL_LAY_SYMBOLS else ""
        result.update(removal=removal, value=tol_clean_text(raw.get("value"), 16), lay=lay,
                      allowance=tol_clean_text(raw.get("allowance"), 12))
    elif kind == "note":
        text = str(raw.get("text") or "").replace("\r", "").strip()[:400]
        if not text:
            return None
        result.update(text=text, leader=bool(raw.get("leader", True)), frame=bool(raw.get("frame")))
    elif kind == "hole":
        def pair(value):
            if isinstance(value, (list, tuple)) and len(value) == 2 and \
                    all(tol_number(v) is not None and tol_number(v) > 0 for v in value):
                return [float(value[0]), float(value[1])]
            return None
        d = tol_number(raw.get("d"))
        if d is None or d <= 0:
            return None
        result.update(linked=bool(raw.get("linked", True)), d=d,
                      through=bool(raw.get("through", True)),
                      depth=max(0.0, tol_number(raw.get("depth")) or 0.0),
                      cbore=pair(raw.get("cbore")), csk=pair(raw.get("csk")),
                      count=max(1, min(999, int(tol_number(raw.get("count")) or 1))))
    elif kind == "thread":
        label = tol_clean_text(raw.get("label"), 24)
        if not label:
            return None
        result.update(linked=bool(raw.get("linked", True)), label=label,
                      label_pitch=tol_clean_text(raw.get("label_pitch"), 24) or label,
                      show_pitch=bool(raw.get("show_pitch")),
                      cls=tol_clean_text(raw.get("cls"), 8),
                      internal=bool(raw.get("internal", True)),
                      hand="left" if raw.get("hand") == "left" else "right",
                      length=max(0.0, tol_number(raw.get("length")) or 0.0),
                      through=bool(raw.get("through")),
                      count=max(1, min(999, int(tol_number(raw.get("count")) or 1))))
    elif kind == "balloon":
        item = tol_number(raw.get("item"))
        if item is None or not 1 <= item <= 999:
            return None
        result["item"] = int(item)
    else:
        weld = raw.get("type") if raw.get("type") in TOL_WELD_TYPES else "fillet"
        other = raw.get("other") if raw.get("other") in TOL_WELD_TYPES else ""
        result.update({"type": weld, "other": other, "size": tol_clean_text(raw.get("size"), 12),
                       "all_around": bool(raw.get("all_around")), "field": bool(raw.get("field")),
                       "tail": tol_clean_text(raw.get("tail"), 24)})
    return result


def tol_annotation_summary(ann):
    """One line for the dimension list."""
    ann = tol_normalize_annotation(ann)
    if ann is None:
        return "Annotation"
    kind = ann["kind"]
    if kind == "gdt":
        text = f"{TOL_GDT_SYMBOLS[ann['symbol']][0]} {'Ø' if ann['diameter'] else ''}{ann['tolerance']}"
        return text + (" | " + " ".join(ann["datums"]) if ann["datums"] else "")
    if kind == "datum":
        return f"Datum {ann['letter']}"
    if kind == "surface":
        return f"Surface finish {ann['value']}".strip()
    if kind == "note":
        first = ann["text"].splitlines()[0]
        return f"Note: {first[:30]}" + ("…" if len(first) > 30 or "\n" in ann["text"] else "")
    if kind == "hole":
        return "Hole " + " · ".join(_drawing_callout_lines(ann))
    if kind == "thread":
        return "Thread " + " · ".join(_drawing_callout_lines(ann))
    if kind == "balloon":
        return f"Balloon {ann['item']}"
    return f"Weld {TOL_WELD_TYPES[ann['type']].split(' ')[0].lower()} {ann['size']}".strip()


# ── bearings (Technical Drawing, Phase 5) ─────────────────────────────────────
# Standard sizes (d × D × B, chamfer r) of common series. Deep groove ball bearings 60 / 62 / 63
# (ISO 15), angular contact 72 B / 73 B (same envelope as 62 / 63), drawn cup needle roller
# bearings HK (ISO 3245; d = shaft / inner circle Fw) and plain wrapped bushes (ISO 3547, d × D × b).
# Check the manufacturer's catalogue before ordering - the sizes are the common catalogue values.
_BEARING_60 = ((10, 26, 8, 0.3), (12, 28, 8, 0.3), (15, 32, 9, 0.3), (17, 35, 10, 0.3),
               (20, 42, 12, 0.6), (25, 47, 12, 0.6), (30, 55, 13, 1.0), (35, 62, 14, 1.0),
               (40, 68, 15, 1.0), (45, 75, 16, 1.0), (50, 80, 16, 1.0), (55, 90, 18, 1.1),
               (60, 95, 18, 1.1))
_BEARING_62 = ((10, 30, 9, 0.6), (12, 32, 10, 0.6), (15, 35, 11, 0.6), (17, 40, 12, 0.6),
               (20, 47, 14, 1.0), (25, 52, 15, 1.0), (30, 62, 16, 1.0), (35, 72, 17, 1.1),
               (40, 80, 18, 1.1), (45, 85, 19, 1.1), (50, 90, 20, 1.1), (55, 100, 21, 1.5),
               (60, 110, 22, 1.5))
_BEARING_63 = ((10, 35, 11, 0.6), (12, 37, 12, 1.0), (15, 42, 13, 1.0), (17, 47, 14, 1.0),
               (20, 52, 15, 1.1), (25, 62, 17, 1.1), (30, 72, 19, 1.1), (35, 80, 21, 1.5),
               (40, 90, 23, 1.5), (45, 100, 25, 1.5), (50, 110, 27, 2.0), (55, 120, 29, 2.0),
               (60, 130, 31, 2.1))
_BEARING_CODES = ("00", "01", "02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12")
_BEARING_HK = (("HK0808", 8, 12, 8), ("HK1010", 10, 14, 10), ("HK1210", 12, 18, 10),
               ("HK1412", 14, 20, 12), ("HK1512", 15, 21, 12), ("HK1612", 16, 22, 12),
               ("HK2010", 20, 26, 10), ("HK2012", 20, 26, 12), ("HK2512", 25, 32, 12),
               ("HK3012", 30, 37, 12), ("HK3512", 35, 42, 12), ("HK4012", 40, 47, 12))
_BEARING_BUSH = ((8, 10, 8), (10, 12, 10), (12, 14, 12), (15, 17, 15), (16, 18, 15), (20, 23, 20),
                 (25, 28, 20), (30, 34, 30), (35, 39, 30), (40, 44, 40))
BEARING_TYPES = {"deep_groove": "Deep groove ball bearing", "angular": "Angular contact ball bearing",
                 "needle": "Needle roller bearing (drawn cup HK)", "plain": "Plain bush (wrapped)"}


def bearing_catalogue():
    """[{"type", "name", "d", "D", "B", "r"}] of all standard sizes."""
    items = []
    for series, table in (("60", _BEARING_60), ("62", _BEARING_62), ("63", _BEARING_63)):
        for code, (d, D, B, r) in zip(_BEARING_CODES, table):
            items.append({"type": "deep_groove", "name": f"{series}{code}", "d": d, "D": D, "B": B, "r": r})
    for series, table in (("72", _BEARING_62), ("73", _BEARING_63)):
        for code, (d, D, B, r) in zip(_BEARING_CODES, table):
            items.append({"type": "angular", "name": f"{series}{code} B", "d": d, "D": D, "B": B, "r": r})
    for name, d, D, B in _BEARING_HK:
        items.append({"type": "needle", "name": name, "d": d, "D": D, "B": B, "r": 0.3})
    for d, D, b in _BEARING_BUSH:
        items.append({"type": "plain", "name": f"Bush {d}×{D}×{b}", "d": d, "D": D, "B": b, "r": 0.3})
    return items


def bearing_find(name):
    return next((item for item in bearing_catalogue() if item["name"] == name), None)


def bearing_ring_deviations(bearing):
    """(bore (upper, lower), outside (upper, lower)) in mm: the bearing's own tolerances (ISO 492
    normal class for rolling bearings: Δdmp / ΔDmp, always below the nominal size). A plain bush
    is pressed into an H7 housing with its outside s7 and gives an H9 bore when fitted."""
    if bearing.get("type") == "plain":
        return tol_deviations("H9", bearing["d"]), tol_deviations("s7", bearing["D"])
    d, D = float(bearing["d"]), float(bearing["D"])
    bore = next(value for limit, value in ((10, 8), (18, 8), (30, 10), (50, 12), (80, 15), (120, 20),
                                           (1e9, 25)) if d <= limit)
    outside = next(value for limit, value in ((18, 8), (30, 9), (50, 11), (80, 13), (120, 15),
                                              (150, 18), (180, 25), (1e9, 30)) if D <= limit)
    if bearing.get("type") == "needle":           # drawn cup: the inner circle Fw (F8 when fitted)
        return tol_deviations("F8", d), (0.0, -outside / 1000.0)
    return (0.0, -bore / 1000.0), (0.0, -outside / 1000.0)


BEARING_LOAD_CASES = {
    "inner_normal": "Rotating inner ring (shaft turns), normal load",
    "inner_light": "Rotating inner ring, light load",
    "inner_heavy": "Rotating inner ring, heavy / shock load",
    "outer_normal": "Rotating outer ring (housing turns, e.g. a wheel), normal load",
    "outer_light": "Rotating outer ring, light load",
}


def bearing_seat(bearing, load_case="inner_normal"):
    """Recommended seats (ISO 286 classes, after the usual catalogue tables for steel shafts and
    housings): {"shaft", "housing", "shoulder_shaft" (min diameter), "shoulder_housing" (max
    diameter), "fillet" (max radius), "note"}. The ring that turns relative to the load gets
    the tight fit; the other one a sliding fit so it can move axially."""
    d, D, r = float(bearing["d"]), float(bearing["D"]), float(bearing.get("r", 0.3))
    kind = bearing.get("type", "deep_groove")
    note = ""
    if kind == "plain":
        shaft, housing, note = "f7", "H7", "bush pressed in (outside s7), bore H9 after fitting"
    elif kind == "needle":
        shaft, housing, note = "h6", "N7", "drawn cup pressed into the housing; shaft hardened " \
                                           "(58 HRC min) as raceway"
    elif load_case.startswith("outer"):
        shaft = "g6"
        housing = "M7" if load_case == "outer_light" else "N7"
        note = "outer ring tight, inner ring sliding on the shaft"
    else:
        housing = "H7"
        if load_case == "inner_light":
            shaft = "js5" if d <= 17 else "j6"
        elif load_case == "inner_heavy":
            shaft = "m5" if d <= 50 else "n6"
        else:
            shaft = "js5" if d <= 10 else "j5" if d <= 17 else "k5" if d <= 40 else "m5"
        note = "inner ring tight, outer ring sliding in the housing"
    if shaft in ("j5", "j6"):                       # not in the ISO 286 subset: the next one alike
        shaft = "js" + shaft[1:]
    return {"shaft": shaft, "housing": housing, "fillet": r,
            "shoulder_shaft": round(d + 0.2 * (D - d), 1),
            "shoulder_housing": round(D - 0.2 * (D - d), 1), "note": note}


def bearing_mesh(bearing, segments=64):
    """(vertices, triangles) of a bearing in its own frame (axis +Z, from z = 0 to B, centred on
    the axis): inner and outer ring with the balls / needles between them, a plain bush as one
    sleeve. Built with manifold3d."""
    import manifold3d as m3
    d, D, B = float(bearing["d"]), float(bearing["D"]), float(bearing["B"])
    kind = bearing.get("type", "deep_groove")

    def tube(r_in, r_out, z0=0.0, height=B):
        return m3.Manifold.cylinder(height, r_out, r_out, segments).translate([0, 0, z0]) - \
            m3.Manifold.cylinder(height + 2, r_in, r_in, segments).translate([0, 0, z0 - 1])
    if kind == "plain":
        solid = tube(d / 2, D / 2)
    elif kind == "needle":
        wall = (D - d) / 2
        shell = tube(D / 2 - 0.25 * wall, D / 2)
        lips = tube(d / 2 + 0.6 * wall, D / 2, 0.0, 0.08 * B) + tube(d / 2 + 0.6 * wall, D / 2, 0.92 * B, 0.08 * B)
        roller = 0.35 * wall
        pitch_r = d / 2 + roller
        count = max(6, int(2 * math.pi * pitch_r / (2.4 * roller)))
        rollers = [m3.Manifold.cylinder(0.76 * B, roller, roller, 16).translate(
            [pitch_r * math.cos(2 * math.pi * k / count), pitch_r * math.sin(2 * math.pi * k / count), 0.12 * B])
            for k in range(count)]
        solid = shell + lips + m3.Manifold.batch_boolean(rollers, m3.OpType.Add)
    else:
        section = (D - d) / 2
        inner = tube(d / 2, d / 2 + 0.3 * section)
        outer = tube(D / 2 - 0.3 * section, D / 2)
        ball = min(0.46 * section, 0.62 * B)
        pitch_r = (d + D) / 4
        count = max(6, int(2 * math.pi * pitch_r / (2.3 * ball)))
        balls = [m3.Manifold.sphere(ball, 24).translate(
            [pitch_r * math.cos(2 * math.pi * k / count), pitch_r * math.sin(2 * math.pi * k / count), B / 2])
            for k in range(count)]
        # grooves in both rings for the balls, so the parts touch only along the raceways
        groove = m3.Manifold.cylinder(2 * ball * 0.9, pitch_r + 0.75 * ball, pitch_r + 0.75 * ball, segments) - \
            m3.Manifold.cylinder(2 * ball * 0.9, pitch_r - 0.75 * ball, pitch_r - 0.75 * ball, segments)
        groove = groove.translate([0, 0, B / 2 - ball * 0.9])
        solid = (inner - groove) + (outer - groove) + m3.Manifold.batch_boolean(balls, m3.OpType.Add)
    mesh = solid.to_mesh()
    return np.asarray(mesh.vert_properties)[:, :3].astype(float).tolist(), \
        [tuple(int(i) for i in tri) for tri in np.asarray(mesh.tri_verts)]


# ── tolerance stack-up (Technical Drawing, Phase 5) ────────────────────────────
def tol_dimension_deviations(nominal, tolerance, general="ISO 2768-m"):
    """(upper, lower) deviation in mm of a dimension: its own tolerance, else the general
    tolerance of the drawing (ISO 2768-1), else ±0."""
    tolerance = tol_normalize_tolerance(tolerance)
    nominal = abs(float(nominal))
    if tolerance is not None:
        mode = tolerance["mode"]
        if mode == "symmetric":
            return tolerance["upper"], -tolerance["upper"]
        if mode in ("deviations", "limits"):
            return tolerance["upper"], tolerance["lower"]
        try:
            return tol_deviations(tolerance["fit"], nominal)
        except ToleranceError:
            pass
    value = tol_general_tolerance(general, nominal) if general else None
    return (value, -value) if value else (0.0, 0.0)


def tol_stackup(rows, low_limit=None, high_limit=None):
    """Tolerance chain: rows [{"nominal", "upper", "lower", "sign" (+1 / -1)}] add up to a gap.
    Worst case: all deviations at their limits; statistical (RSS): the deviation ranges add as
    the root of their squares around the mean. The gap must lie within low_limit … high_limit."""
    nominal = worst_high = worst_low = mean = 0.0
    squares = 0.0
    for row in rows:
        n, up, low, sign = float(row["nominal"]), float(row["upper"]), float(row["lower"]), \
            (1.0 if float(row.get("sign", 1)) >= 0 else -1.0)
        nominal += sign * n
        if sign > 0:
            worst_high += n + up
            worst_low += n + low
        else:
            worst_high -= n + low
            worst_low -= n + up
        mean += sign * (n + (up + low) / 2.0)
        squares += ((up - low) / 2.0) ** 2
    half = math.sqrt(squares)
    result = {"nominal": nominal, "worst": (worst_low, worst_high), "rss": (mean - half, mean + half),
              "mean": mean}

    def check(low, high):
        return (low_limit is None or low >= low_limit - 1e-12) and \
            (high_limit is None or high <= high_limit + 1e-12)
    result["worst_ok"] = check(*result["worst"])
    result["rss_ok"] = check(*result["rss"])
    return result


DRAWING_UNITS_PER_MM = 4.0
# ISO 216 sheets (landscape size in mm) with the DIN EN ISO 5457 reference grid (50 mm fields)
DRAWING_SHEETS = {"A2": (594, 420, (12, 8)), "A3": (420, 297, (8, 6)),
                  "A4": (297, 210, (6, 4)), "A5": (210, 148, (4, 3))}


def _drawing_sheet(options):
    """Sheet of a drawing: {"name", "orientation", "w", "h" (page units), "zones" (columns,
    rows)}; A2 landscape unless the options name another size."""
    name = str(options.get("sheet", "A2")).upper()
    if name not in DRAWING_SHEETS:
        name = "A2"
    orientation = "portrait" if options.get("orientation") == "portrait" else "landscape"
    width, height, zones = DRAWING_SHEETS[name]
    if orientation == "portrait":
        width, height, zones = height, width, (zones[1], zones[0])
    return {"name": name, "orientation": orientation, "w": width * DRAWING_UNITS_PER_MM,
            "h": height * DRAWING_UNITS_PER_MM, "zones": zones}


_DRAWING_PAGE = _drawing_sheet({})                 # sheet of the drawing being painted
DRAWING_STD_SCALES = (50, 20, 10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001)   # ISO 5455
# scales offered in the editor: the ISO 5455 ones plus every whole step from 10:1 to 1:10
# ("Auto" still picks an ISO 5455 preferred scale)
DRAWING_SELECTABLE_SCALES = (50, 20) + tuple(range(10, 1, -1)) + (1,) + \
    tuple(1.0 / n for n in range(2, 11)) + (0.05, 0.02, 0.01, 0.005, 0.002, 0.001)
