def _drawing_color(role):
    value = _DRAWING_COLORS.get(role)
    return QColor(value) if value else QColor(0, 0, 0, 0)
DRAWING_MIN_CIRCLE_POINTS = 16
DRAWING_THICK, DRAWING_THIN = 2.0, 1.0                  # DIN ISO 128-24, line group 0.5 (0.5 / 0.25 mm)
DRAWING_FRAME_LINE, DRAWING_FIELD_LINE = 2.8, 1.4       # DIN EN ISO 5457: frame 0.7 mm, grid / title block fields 0.35 mm
DRAWING_BORDER = (80.0, 40.0, 40.0, 40.0)               # DIN EN ISO 5457: left 20 mm (filing margin), others 10 mm
DRAWING_TEXT_SMALL, DRAWING_TEXT, DRAWING_TEXT_LARGE = 10.0, 14.0, 20.0   # DIN EN ISO 3098-0: 2.5 / 3.5 / 5 mm lettering
DRAWING_DIM_OFFSET = 40.0                               # DIN 406-11: first dimension line 10 mm from the outline
DRAWING_FONT_FAMILIES = ("ISOCPEUR", "Osifont", "ISO 3098", "Arial")   # type B lettering when installed
DRAWING_DASH = [12, 3]                                  # type 02.1: dash 12 d, gap 3 d
DRAWING_CHAIN = [24, 3, 0.5, 3]                         # type 04.1: dash 24 d, gap 3 d, dot, gap 3 d


def _drawing_orient_triangles(V, T):
    """Make the winding of every connected body consistent and pointing outwards."""
    n = len(T)
    directed = np.concatenate((T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]))
    face_of = np.tile(np.arange(n), 3)
    key = directed.min(axis=1) * len(V) + directed.max(axis=1)
    order = np.argsort(key, kind="stable")
    sorted_key = key[order]
    first = np.flatnonzero(np.r_[True, sorted_key[1:] != sorted_key[:-1]])
    counts = np.diff(np.r_[first, len(order)])
    pair = first[counts == 2]
    i0, i1 = order[pair], order[pair + 1]
    same = (directed[i0] == directed[i1]).all(axis=1)
    adjacency = [[] for _ in range(n)]
    for a, b, s in zip(face_of[i0].tolist(), face_of[i1].tolist(), same.tolist()):
        adjacency[a].append((b, s))
        adjacency[b].append((a, s))
    component = [-1] * n
    flip = [False] * n
    count = 0
    for seed in range(n):
        if component[seed] >= 0:
            continue
        component[seed] = count
        stack = [seed]
        while stack:
            t = stack.pop()
            for u, s in adjacency[t]:
                if component[u] < 0:
                    component[u] = count
                    flip[u] = flip[t] != s
                    stack.append(u)
        count += 1
    flip = np.asarray(flip)
    component = np.asarray(component)
    T = T.copy()
    T[flip] = T[flip][:, [0, 2, 1]]
    P = V[T]
    volume = np.einsum("ij,ij->i", P[:, 0], np.cross(P[:, 1], P[:, 2])) / 6.0
    inverted = np.bincount(component, weights=volume, minlength=count)[component] < 0
    T[inverted] = T[inverted][:, [0, 2, 1]]
    return T


def _drawing_prepare_mesh(vertices, triangles):
    """Weld coincident vertices, drop degenerate triangles and orient the bodies."""
    V = np.asarray(vertices, dtype=float)
    T = np.asarray(triangles, dtype=np.int64).reshape(-1, 3)
    if not len(V) or not len(T):
        raise ValueError("There is no solid geometry to draw.")
    weld = max(float(np.ptp(V, axis=0).max()), 1e-9) * 1e-6
    _, first, inverse = np.unique(np.round(V / weld).astype(np.int64), axis=0,
                                  return_index=True, return_inverse=True)
    V = V[first]
    T = inverse.reshape(-1)[T]
    T = T[(T[:, 0] != T[:, 1]) & (T[:, 1] != T[:, 2]) & (T[:, 0] != T[:, 2])]
    if not len(T):
        raise ValueError("The selected solid has no drawable triangles.")
    return V, _drawing_orient_triangles(V, T)


def _drawing_topology(V, T, threads=None, gears=None):
    """Unique edges with their adjacent faces, sharp-edge flags, detected circles and screw
    threads (found on the mesh, or given: a section keeps the threads of the whole part). The
    edges of threaded surfaces are no sharp edges: views draw the thread symbol instead."""
    used = V[np.unique(T)]
    span = max(float(np.ptp(used, axis=0).max()), 1e-9)
    P = V[T]
    raw = np.cross(P[:, 1] - P[:, 0], P[:, 2] - P[:, 0])
    length = np.linalg.norm(raw, axis=1)
    valid = length > span * span * 1e-12
    normals = np.zeros_like(raw)
    normals[valid] = raw[valid] / length[valid, None]
    pairs = np.concatenate((T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]))
    pairs.sort(axis=1)
    key = pairs[:, 0] * len(V) + pairs[:, 1]
    face_of = np.tile(np.arange(len(T)), 3)
    order = np.argsort(key, kind="stable")
    sorted_key = key[order]
    first = np.flatnonzero(np.r_[True, sorted_key[1:] != sorted_key[:-1]])
    counts = np.diff(np.r_[first, len(order)])
    edges = np.column_stack((sorted_key[first] // len(V), sorted_key[first] % len(V)))
    fa = face_of[order[first]]
    fb = np.where(counts >= 2, face_of[order[np.minimum(first + 1, len(order) - 1)]], -1)
    two = (counts == 2) & valid[fa] & valid[np.maximum(fb, 0)]
    dots = np.ones(len(edges))
    dots[two] = np.einsum("ij,ij->i", normals[fa[two]], normals[fb[two]])
    sharp = ((counts == 1) & valid[fa]) | (counts > 2) | (two & (dots < 0.8))
    topology = {"edges": edges, "counts": counts, "fa": fa, "fb": fb, "two": two,
                "sharp": sharp, "fold": two & (dots < 0.8), "normals": normals, "span": span,
                "V": V, "T": T}
    if threads is None:
        threads = _drawing_find_threads(V, T, topology)
    topology["threads"] = threads
    topology["thread_zone"] = _drawing_thread_zone(V, edges, threads, span) if threads else \
        np.zeros(len(edges), dtype=bool)
    # simplified gears (Phase 4): the teeth are left out like a thread, symbols drawn instead
    topology["gears"] = list(gears or ())
    if topology["gears"]:
        topology["thread_zone"] = topology["thread_zone"] | _drawing_gear_zone(V, edges, topology["gears"], span)
    topology["sharp"] = topology["sharp"] & ~topology["thread_zone"]
    topology["fold"] = topology["fold"] & ~topology["thread_zone"]
    topology["circles"] = _drawing_find_circles(V, topology)
    topology["arcs"] = [
        arc for arc in _drawing_find_arcs(V, topology)
        if not any(abs(arc["radius"] - c["radius"]) <= 1e-3 * span
                   and np.linalg.norm(arc["center"] - c["center"]) <= 1e-3 * span
                   for c in topology["circles"])]        # a split full circle is no fillet
    # the nominal (major) diameter of each thread at both ends: centre marks, centre lines in
    # sections and the circle a diameter dimension picks
    for index, thread in enumerate(threads):
        for end in (thread["low"], thread["high"]):
            topology["circles"].append({"center": thread["point"] + thread["axis"] * end,
                                        "radius": thread["major"], "axis": thread["axis"],
                                        "edges": [], "thread": index})
    # tip, pitch and root circle of simplified gears: centre marks and diameter dimensions
    for gear in topology["gears"]:
        for radius in (gear["r_tip"], gear["r_pitch"], gear["r_root"]):
            topology["circles"].append({"center": np.asarray(gear["origin"], dtype=float) +
                                        np.asarray(gear["axis"], dtype=float) * gear["z1"],
                                        "radius": radius, "axis": np.asarray(gear["axis"], dtype=float),
                                        "edges": [], "gear": True})
    return topology


def _drawing_outline_chains(V, topology):
    """Polylines of fold edges (open chains and closed cycles) as lists of vertex indices."""
    adjacency = collections.defaultdict(list)
    for a, b in topology["edges"][topology["fold"]].tolist():
        adjacency[a].append(b)
        adjacency[b].append(a)
    used = set()
    chains = []

    def walk(start, first):
        path = [start, first]
        used.add((min(start, first), max(start, first)))
        previous, current = start, first
        while len(adjacency[current]) == 2 and current != start:
            following = [n for n in adjacency[current] if n != previous]
            following = following[0] if following else previous
            key = (min(current, following), max(current, following))
            if key in used:
                break
            used.add(key)
            path.append(following)
            previous, current = current, following
        return path

    for vertex in list(adjacency):
        if len(adjacency[vertex]) != 2:
            for neighbour in adjacency[vertex]:
                if (min(vertex, neighbour), max(vertex, neighbour)) not in used:
                    chains.append(walk(vertex, neighbour))
    for vertex in list(adjacency):
        for neighbour in adjacency[vertex]:
            if (min(vertex, neighbour), max(vertex, neighbour)) not in used:
                chains.append(walk(vertex, neighbour))
    return chains


def _drawing_find_arcs(V, topology):
    """Fillets and rounded corners: runs of equal turning angle along sharp-edge outlines."""
    arcs, seen = [], set()
    for chain in _drawing_outline_chains(V, topology):
        closed = chain[0] == chain[-1]
        points = V[chain[:-1] if closed else chain]
        if len(points) < 4:
            continue
        if closed:
            points = np.concatenate((points, points[1:-1]))       # allow arcs across the seam
        keep = [0]
        for i in range(1, len(points) - 1):                       # drop collinear (T-junction) points
            a, b = points[i] - points[keep[-1]], points[i + 1] - points[i]
            if np.linalg.norm(np.cross(a, b)) > 0.0035 * np.linalg.norm(a) * np.linalg.norm(b):
                keep.append(i)
        keep.append(len(points) - 1)
        P = points[keep]
        d = np.diff(P, axis=0)
        length = np.linalg.norm(d, axis=1)
        if (length <= 0).any() or len(P) < 4:
            continue
        cross = np.cross(d[:-1], d[1:])
        turn = np.degrees(np.arctan2(np.linalg.norm(cross, axis=1), (d[:-1] * d[1:]).sum(axis=1)))
        axes = cross / np.maximum(np.linalg.norm(cross, axis=1), 1e-12)[:, None]
        i = 0
        while i < len(turn):
            if not 0.4 <= turn[i] <= 36.0:       # large radii turn by well under 3 degrees per chord
                i += 1
                continue
            j = i
            while (j + 1 < len(turn) and abs(turn[j + 1] - turn[i]) <= 0.12 * turn[i] + min(0.5, 0.25 * turn[i])
                   and float(axes[j + 1] @ axes[i]) > 0.995
                   and 0.6 <= length[j + 1] / length[i] <= 1.67):
                j += 1
            if j > i:
                arc = _drawing_fit_arc(P[i:j + 3], float(turn[i:j + 1].sum()), axes[i:j + 1].mean(axis=0))
                if arc is not None:
                    key = tuple(np.round(arc["center"] / (topology["span"] * 1e-4)).astype(int)) + \
                        (round(arc["radius"] / (topology["span"] * 1e-4)),)
                    if key not in seen:
                        seen.add(key)
                        arcs.append(arc)
            i = j + 1
    return arcs


def _drawing_fit_arc(points, total_turn, axis):
    """Circle through the polyline vertices of one arc (None if they are not on one circle)."""
    if not 20.0 <= total_turn <= 340.0:
        return None
    axis = axis / np.linalg.norm(axis)
    mean = points.mean(axis=0)
    e1 = np.cross(axis, (1.0, 0.0, 0.0) if abs(axis[0]) < 0.9 else (0.0, 1.0, 0.0))
    e1 /= np.linalg.norm(e1)
    e2 = np.cross(axis, e1)
    local = np.column_stack(((points - mean) @ e1, (points - mean) @ e2))
    c = np.linalg.lstsq(np.column_stack((2 * local, np.ones(len(local)))),
                        (local ** 2).sum(axis=1), rcond=None)[0]
    radius = math.sqrt(max(c[2] + c[0] ** 2 + c[1] ** 2, 0.0))
    offsets = local - c[:2]
    if radius <= 0 or float(np.abs(np.hypot(offsets[:, 0], offsets[:, 1]) - radius).max()) > 0.02 * radius \
            or float(np.abs((points - mean) @ axis).max()) > 0.01 * radius:
        return None
    angles = np.unwrap(np.arctan2(offsets[:, 1], offsets[:, 0]))
    middle = (angles[0] + angles[-1]) / 2
    return {"center": mean + c[0] * e1 + c[1] * e2, "radius": radius, "axis": axis,
            "mid": math.cos(middle) * e1 + math.sin(middle) * e2,
            "points": np.asarray(points, dtype=float)}




def _drawing_find_circles(V, topology):
    """Closed, planar loops of sharp edges whose vertices share one radius (holes, bosses)."""
    adjacency = collections.defaultdict(list)
    edges = topology["edges"]
    for edge_id in np.flatnonzero(topology["sharp"]).tolist():
        a, b = int(edges[edge_id, 0]), int(edges[edge_id, 1])
        adjacency[a].append((b, edge_id))
        adjacency[b].append((a, edge_id))
    seen = set()
    circles = []
    for start in list(adjacency):
        if start in seen:
            continue
        seen.add(start)
        stack = [start]
        vertices, edge_ids = [], set()
        while stack:
            vertex = stack.pop()
            vertices.append(vertex)
            for neighbour, edge_id in adjacency[vertex]:
                edge_ids.add(edge_id)
                if neighbour not in seen:
                    seen.add(neighbour)
                    stack.append(neighbour)
        if len(vertices) < DRAWING_MIN_CIRCLE_POINTS:
            continue
        points = V[vertices]
        mean = points.mean(axis=0)
        axis_pair = np.linalg.svd(points - mean)[2]
        axis = axis_pair[2]

        def fit(selected):
            local = np.column_stack(((selected - mean) @ axis_pair[0], (selected - mean) @ axis_pair[1]))
            c = np.linalg.lstsq(np.column_stack((2 * local, np.ones(len(local)))),
                                (local ** 2).sum(axis=1), rcond=None)[0]
            return mean + c[0] * axis_pair[0] + c[1] * axis_pair[1]

        center = fit(points)
        radii = np.linalg.norm(points - center, axis=1)
        corners = radii >= 0.9985 * radii.max()      # CSG adds chord points slightly inside
        if corners.sum() < DRAWING_MIN_CIRCLE_POINTS // 2:
            continue
        center = fit(points[corners])
        radii = np.linalg.norm(points - center, axis=1)
        radius = float(radii[corners].max())
        if radius <= 0 or float(np.abs((points - center) @ axis).max()) > 0.01 * radius \
                or float(radii.min()) < 0.97 * radius or float(radii.max()) > 1.01 * radius:
            continue
        circles.append({"center": center, "radius": radius, "axis": axis,
                        "edges": sorted(edge_ids)})
    return circles


def _drawing_point_inside(V, T, point):
    """True if a point lies inside the closed mesh (ray parity)."""
    direction = np.array((0.31234, 0.52671, 0.79131))
    direction /= np.linalg.norm(direction)
    corners = V[T]
    e1, e2 = corners[:, 1] - corners[:, 0], corners[:, 2] - corners[:, 0]
    h = np.cross(direction, e2)
    a = np.einsum("ij,ij->i", e1, h)
    ok = np.abs(a) > 1e-15
    f = 1.0 / a[ok]
    s = np.asarray(point, dtype=float) - corners[ok, 0]
    u = f * np.einsum("ij,ij->i", s, h[ok])
    q = np.cross(s, e1[ok])
    v = f * (q @ direction)
    t = f * np.einsum("ij,ij->i", e2[ok], q)
    return int(((u >= 0) & (v >= 0) & (u + v <= 1) & (t > 1e-9)).sum()) % 2 == 1


def _drawing_find_threads(V, T, topology):
    """Screw threads of a meshed part (DIN ISO 6410 draws them as symbols, not as helices):
    helical chains of fold edges (crests and roots) of at least about one turn, grouped by their
    axis. [{"axis", "point" (on the axis), "minor", "major" (radii), "pitch", "low", "high"
    (axial range), "internal", "limits" (thread limit line at low / high)}]"""
    span = topology["span"]
    edges = topology["edges"]
    fold_ids = np.flatnonzero(topology["fold"])
    edge_index = {(int(a), int(b)): int(i) for i, (a, b) in zip(fold_ids, edges[fold_ids].tolist())}
    helices = []
    for chain in _drawing_outline_chains(V, topology):
        if len(chain) < 16:
            continue
        points = V[chain]
        steps = np.diff(points, axis=0)
        lengths = np.linalg.norm(steps, axis=1)
        keep = lengths > span * 1e-9
        if keep.sum() < 12:
            continue
        steps = steps[keep] / lengths[keep, None]
        axis = np.linalg.svd(steps - steps.mean(axis=0), full_matrices=False)[2][-1]
        k = int(np.argmax(np.abs(axis)))
        if abs(axis[k]) > math.cos(math.radians(1.0)):
            axis = np.eye(3)[k]                       # an axis along x / y / z is taken exactly
        if axis[k] < 0:
            axis = -axis
        e1 = np.cross(axis, (1.0, 0.0, 0.0) if abs(axis[0]) < 0.9 else (0.0, 1.0, 0.0))
        e1 /= np.linalg.norm(e1)
        e2 = np.cross(axis, e1)
        mean = points.mean(axis=0)
        local = np.column_stack(((points - mean) @ e1, (points - mean) @ e2))
        c = np.linalg.lstsq(np.column_stack((2 * local, np.ones(len(local)))),
                            (local ** 2).sum(axis=1), rcond=None)[0]
        radius = math.sqrt(max(c[2] + c[0] ** 2 + c[1] ** 2, 0.0))
        offsets = local - c[:2]
        if radius <= span * 1e-4 or \
                float(np.abs(np.hypot(offsets[:, 0], offsets[:, 1]) - radius).max()) > 0.03 * radius:
            continue
        angles = np.unwrap(np.arctan2(offsets[:, 1], offsets[:, 0]))
        turn = float(angles[-1] - angles[0])
        z = points @ axis
        rise = float(z[-1] - z[0])
        if abs(turn) < 1.9 * math.pi or abs(rise) < span * 1e-6 or \
                (np.diff(angles) * math.copysign(1.0, turn) < -1e-6).any() or \
                (np.diff(z) * math.copysign(1.0, rise) < -span * 1e-6).any():
            continue                                  # not a helix of about one turn or more
        pitch = abs(rise) / (abs(turn) / (2.0 * math.pi))
        if not 0.02 * radius <= pitch <= 0.8 * radius:
            continue
        if float(np.abs(np.polyval(np.polyfit(angles, z, 1), angles) - z).max()) > 0.1 * pitch:
            continue                                  # the pitch must be constant
        centre = mean + c[0] * e1 + c[1] * e2
        faces = set()
        for a, b in zip(chain[:-1], chain[1:]):
            edge_id = edge_index.get((min(a, b), max(a, b)))
            if edge_id is not None:
                faces.update((int(topology["fa"][edge_id]), int(topology["fb"][edge_id])))
        faces.discard(-1)
        helices.append({"axis": axis, "point": centre - axis * float(centre @ axis),
                        "radius": radius, "pitch": pitch, "faces": faces,
                        "chain": np.asarray(chain),
                        # (e1, e2, axis) is right-handed: a right-hand helix rises turning positive
                        "hand": "right" if turn * rise > 0 else "left"})
    groups = []
    for helix in helices:
        for group in groups:
            if float(helix["axis"] @ group[0]["axis"]) > 0.9999 and \
                    float(np.linalg.norm(np.cross(helix["point"] - group[0]["point"],
                                                  group[0]["axis"]))) <= 0.05 * helix["radius"] and \
                    abs(helix["pitch"] - group[0]["pitch"]) <= 0.1 * group[0]["pitch"]:
                group.append(helix)
                break
        else:
            groups.append([helix])
    threads = []
    for group in groups:
        axis, point = group[0]["axis"], group[0]["point"]
        pitch = float(np.mean([helix["pitch"] for helix in group]))
        faces = np.asarray(sorted(set().union(*(helix["faces"] for helix in group))), dtype=int)
        if not len(faces):
            continue
        corners = V[T[faces]].reshape(-1, 3) - point
        along = corners @ axis
        radial = corners - np.outer(along, axis)
        distance = np.linalg.norm(radial, axis=1)
        minor, major = float(distance.min()), float(distance.max())
        if not 0.2 * pitch <= major - minor <= 1.0 * pitch:
            continue                                  # no thread profile depth (e.g. a spring)
        chain_points = np.concatenate([V[helix["chain"]] for helix in group]) - point
        low = float(min(along.min(), (chain_points @ axis).min()))
        high = float(max(along.max(), (chain_points @ axis).max()))
        # the thread run-out next to the helices (the end of the cut profile, a plain bore or
        # shank at the thread diameter up to the face, a bolt's end chamfer) belongs to the thread
        relative = V[np.unique(T)] - point
        axial = relative @ axis
        reach = np.linalg.norm(relative - np.outer(axial, axis), axis=1)
        tolerance = 0.15 * (major - minor) + span * 1e-6
        band = (reach >= minor - tolerance) & (reach <= major + tolerance) & \
            (axial >= low - 1.5 * pitch) & (axial <= high + 1.5 * pitch)
        if band.any():
            low, high = min(low, float(axial[band].min())), max(high, float(axial[band].max()))
        # material outside (normals pointing to the axis): a tapped hole, else a bolt thread
        face_centres = V[T[faces]].mean(axis=1) - point
        outward = face_centres - np.outer(face_centres @ axis, axis)
        outward /= np.maximum(np.linalg.norm(outward, axis=1), 1e-12)[:, None]
        internal = float(np.einsum("ij,ij->i", topology["normals"][faces], outward).mean()) < 0
        # thread limit line where the part goes on beyond the thread (not at a free end)
        helper = np.cross(axis, (1.0, 0.0, 0.0) if abs(axis[0]) < 0.9 else (0.0, 1.0, 0.0))
        helper /= np.linalg.norm(helper)
        middle = (minor + major) / 2.0
        limits = []
        for end, outwards in ((low, -1.0), (high, 1.0)):
            probe = point + axis * (end + outwards * 1.5 * pitch)
            inside = 0
            for angle in (0.3, 1.9, 3.4, 5.0):
                direction = helper * math.cos(angle) + np.cross(axis, helper) * math.sin(angle)
                inside += _drawing_point_inside(V, T, probe + direction * middle)
            limits.append(inside >= 3)
        hands = [helix["hand"] for helix in group]
        threads.append({"axis": axis, "point": point, "minor": minor, "major": major,
                        "pitch": pitch, "low": low, "high": high, "internal": internal,
                        "limits": limits,
                        "hand": "left" if hands.count("left") > hands.count("right") else "right"})
    return threads


def _drawing_thread_zone(V, edges, threads, span):
    """Edges of the threaded surfaces (both ends between the root and crest radius inside the
    thread length): left out of the views, the thread is drawn as its symbol instead."""
    zone = np.zeros(len(edges), dtype=bool)
    for thread in threads:
        relative = V - thread["point"]
        along = relative @ thread["axis"]
        distance = np.linalg.norm(relative - np.outer(along, thread["axis"]), axis=1)
        tolerance = 0.15 * (thread["major"] - thread["minor"]) + span * 1e-6
        inside = (distance >= thread["minor"] - tolerance) & \
            (distance <= thread["major"] + tolerance) & \
            (along >= thread["low"] - tolerance) & (along <= thread["high"] + tolerance)
        zone |= inside[edges[:, 0]] & inside[edges[:, 1]]
    return zone


def _drawing_thread_radii(thread):
    """(crest, root) radius: the crest is where the material ends (minor diameter of a tapped
    hole, major diameter of a bolt)."""
    if thread["internal"]:
        return thread["minor"], thread["major"]
    return thread["major"], thread["minor"]


def _drawing_thread_section_loops(loops, threads, normal, offset, right, up):
    """Cut-face outlines with the thread profile replaced by the crest line: the hatching of a
    threaded section runs up to the crest (DIN ISO 6410-1)."""
    if not threads or not loops:
        return loops
    normal, right, up = (np.asarray(v, dtype=float) for v in (normal, right, up))
    result = []
    for loop in loops:
        loop = np.asarray(loop, dtype=float)
        points = np.outer(loop[:, 0], right) + np.outer(loop[:, 1], up) + normal * float(offset)
        for thread in threads:
            axis = thread["axis"]
            along_normal = float(axis @ normal)
            crest, _root = _drawing_thread_radii(thread)
            relative = points - thread["point"]
            along = relative @ axis
            radial = relative - np.outer(along, axis)
            distance = np.linalg.norm(radial, axis=1)
            tolerance = 0.15 * (thread["major"] - thread["minor"])
            zone = (distance >= thread["minor"] - tolerance) & \
                (distance <= thread["major"] + tolerance) & \
                (along >= thread["low"] - tolerance) & (along <= thread["high"] + tolerance)
            if not zone.any():
                continue
            if abs(along_normal) < 1e-3:              # axis in the cut plane: lines at the crest
                side = np.cross(axis, normal)
                side /= np.linalg.norm(side)
                depth = float(offset - thread["point"] @ normal)
                if abs(depth) >= crest:
                    continue
                half = math.sqrt(crest * crest - depth * depth)
                sign = np.sign(radial[zone] @ side)
                sign[sign == 0] = 1.0
                points[zone] = thread["point"] + np.outer(along[zone], axis) + normal * depth + \
                    np.outer(sign * half, side)
            elif abs(along_normal) > 0.999:           # cut across the axis: the crest circle
                points[zone] = thread["point"] + np.outer(along[zone], axis) + \
                    radial[zone] / np.maximum(distance[zone], 1e-12)[:, None] * crest
        flat = np.column_stack((points @ right, points @ up))
        keep = np.r_[True, np.linalg.norm(np.diff(flat, axis=0), axis=1) > 1e-9]
        flat = flat[keep]
        if len(flat) >= 3:
            result.append(flat)
    return result


def _drawing_thread_ends(thread, topology):
    """Chamfered free ends of a thread (Phase 4): {"low" / "high": (end radius, chamfer length,
    position of the end face along the axis)}. A bolt's end is chamfered when its end face stays
    inside the crest; a tapped hole's entry when the hole widens beyond the major diameter there
    (45° assumed). Cached on the thread."""
    if "_ends" in thread:
        return thread["_ends"]
    ends = {}
    V = topology.get("V")
    if V is not None and len(V):
        axis, point = np.asarray(thread["axis"], dtype=float), np.asarray(thread["point"], dtype=float)
        relative = V - point
        along = relative @ axis
        distance = np.linalg.norm(relative - np.outer(along, axis), axis=1)
        crest, _root = _drawing_thread_radii(thread)
        profile = thread["major"] - thread["minor"]
        tolerance = 0.05 * profile + topology.get("span", 1.0) * 1e-6
        for name, end, inside, outward in (("low", thread["low"], thread["limits"][0], -1.0),
                                           ("high", thread["high"], thread["limits"][1], 1.0)):
            if inside:                                # the part goes on: a thread limit line
                continue
            # the end face may lie a little beyond the thread's range (the chamfer drops
            # below the root): look up to one profile depth further out
            beyond = (along - end) * outward
            window = (beyond >= -tolerance) & (beyond <= 1.5 * profile + tolerance)
            if thread["internal"]:
                window &= (distance >= thread["minor"] - tolerance) & (distance <= 1.6 * thread["major"])
            else:
                window &= distance <= thread["major"] + tolerance
            if not window.any():
                continue
            face = float(along[window][np.argmax(beyond[window])])
            on_face = window & (np.abs(along - face) <= tolerance)
            if thread["internal"]:
                radius = float(distance[on_face].min())
                if radius > crest + 0.3 * profile:
                    ends[name] = (radius, radius - crest, face)
            else:
                radius = float(distance[on_face].max())
                if radius < crest - 0.3 * profile:
                    ends[name] = (radius, crest - radius, face)
    thread["_ends"] = ends
    return ends


def _drawing_thread_symbols(result, topology, right, up, normal, near, center, extent,
                            resolution, tolerance, cut=None):
    """Threads in a projected view (DIN ISO 6410-1): seen from the side, the crest as thick and
    the root as thin lines with a thick thread limit line where the thread ends inside the part;
    seen along the axis, the crest as a full thick circle and the root as a thin three-quarter
    circle (open in the upper right quadrant). Hidden threads are dashed."""
    threads = topology.get("threads") or []
    result["thin"] = np.zeros((0, 2, 2))
    result["thread_visible"] = {}
    result["thread_lines"] = (np.zeros((0, 2, 2)),) * 3
    if not threads:
        return
    thick, thin, hidden = [], [], []

    def visible(points):
        u, v, w = points @ right, points @ up, points @ normal
        sx = np.clip(np.floor((u - center[0]) / extent * resolution + resolution / 2).astype(int),
                     0, resolution - 1)
        sy = np.clip(np.floor((center[1] - v) / extent * resolution + resolution / 2).astype(int),
                     0, resolution - 1)
        return w >= near[sy, sx] - tolerance

    def flat(points):
        return np.column_stack((points @ right, points @ up))

    def runs(points, shown, visible_list, straight):
        """Pieces of a polyline split where its visibility changes."""
        points2 = flat(points)
        start = 0
        for index in range(1, len(points) + 1):
            if index == len(points) or shown[index] != shown[start]:
                end = min(index, len(points) - 1)
                target = visible_list if shown[start] else hidden
                if straight:
                    if end > start:
                        target.append((points2[start], points2[end]))
                else:
                    for a in range(start, end):
                        target.append((points2[a], points2[a + 1]))
                start = index

    pixel = extent / resolution
    for index, thread in enumerate(threads):
        axis, point = thread["axis"], thread["point"]
        crest, root = _drawing_thread_radii(thread)
        along_normal = float(axis @ normal)
        if abs(along_normal) < 1e-3:                  # the thread seen from the side
            side = np.cross(axis, normal)
            side /= np.linalg.norm(side)
            depth = 0.0 if cut is None else float(cut - point @ normal)
            if abs(depth) >= crest:
                continue
            base = point + normal * depth
            half_crest = math.sqrt(crest * crest - depth * depth)
            half_root = math.sqrt(max(root * root - depth * depth, 0.0))
            count = max(2, int(math.ceil((thread["high"] - thread["low"]) / pixel / 1.5)) + 1)
            # chamfered free ends (Phase 4): the crest line stops where the chamfer begins
            ends = _drawing_thread_ends(thread, topology)
            # a chamfered end: the crest line ends where the chamfer begins
            low_end = ends["low"][2] + ends["low"][1] if "low" in ends else thread["low"]
            high_end = ends["high"][2] - ends["high"][1] if "high" in ends else thread["high"]
            ts = np.linspace(low_end, max(high_end, low_end), count)
            root_ts = np.linspace(thread["low"], thread["high"], count)
            any_visible = False
            for sign in (1.0, -1.0):
                crest_points = base + np.outer(ts, axis) + side * (sign * half_crest)
                shown = visible(crest_points)
                any_visible |= bool(shown.any())
                runs(crest_points, shown, thick, True)
                if half_root > 0:
                    # the root line lies inside the material; it shows where the crest does
                    runs(base + np.outer(root_ts, axis) + side * (sign * half_root), shown, thin, True)
                for name, inward, sample in (("low", 1.0, 0), ("high", -1.0, -1)):
                    if name not in ends:
                        continue
                    end_radius, length, end = ends[name]
                    half_end = math.sqrt(max(end_radius * end_radius - depth * depth, 0.0))
                    a = flat((base + axis * end + side * (sign * half_end))[None])[0]
                    b = flat((base + axis * (end + inward * length) + side * (sign * half_crest))[None])[0]
                    (thick if shown[sample] else hidden).append((a, b))
                    if sign > 0 and not thread["internal"]:      # the chamfered end face
                        c = flat((base + axis * end - side * half_end)[None])[0]
                        (thick if shown[sample] else hidden).append((a, c))
                for end, flag, sample in ((thread["low"], thread["limits"][0], 0),
                                          (thread["high"], thread["limits"][1], -1)):
                    if flag and sign > 0:
                        major = math.sqrt(max(thread["major"] ** 2 - depth * depth, 0.0))
                        a = flat((base + axis * end + side * major)[None])[0]
                        b = flat((base + axis * end - side * major)[None])[0]
                        (thick if shown[sample] else hidden).append((a, b))
            result["thread_visible"][index] = any_visible
        elif abs(along_normal) > 0.999:               # the thread seen along its axis
            if cut is None:
                nearest = thread["high"] if along_normal > 0 else thread["low"]
            else:
                t_cut = float(cut - point @ normal) / along_normal
                nearest = min(thread["high"], t_cut) if along_normal > 0 else \
                    max(thread["low"], t_cut)
            middle = point + axis * nearest
            full = np.linspace(0.0, 2.0 * math.pi, 97)
            crest_points = middle + crest * (np.outer(np.cos(full), right) +
                                             np.outer(np.sin(full), up))
            shown = visible(crest_points)
            runs(crest_points, shown, thick, False)
            three_quarters = np.linspace(0.5 * math.pi, 2.0 * math.pi, 73)
            root_points = middle + root * (np.outer(np.cos(three_quarters), right) +
                                           np.outer(np.sin(three_quarters), up))
            runs(root_points, visible(root_points), thin, False)
            result["thread_visible"][index] = bool(shown.any())
    as_array = lambda items: np.asarray(items, dtype=float).reshape(-1, 2, 2)
    thick, thin, hidden = as_array(thick), as_array(thin), as_array(hidden)
    result["visible"] = np.concatenate((result["visible"], thick))
    result["visible_edges"] = np.concatenate((result["visible_edges"],
                                              np.full(len(thick), -1, dtype=int)))
    result["hidden"] = np.concatenate((result["hidden"], hidden))
    result["hidden_edges"] = np.concatenate((result["hidden_edges"],
                                             np.full(len(hidden), -1, dtype=int)))
    result["thin"] = thin
    result["thread_lines"] = (thick, thin, hidden)


def _drawing_clip(V, T, normal, offset=0.0):
    """Keep the part of the mesh behind a parallel section plane (viewer on +normal)."""
    n = np.asarray(normal, dtype=float)
    span = max(float(np.ptp(V, axis=0).max()), 1e-9)
    plane_tol = span * 1e-9
    weld = span * 1e-6
    T = np.asarray(T, dtype=np.int64).reshape(-1, 3)
    distance = V @ n - float(offset)
    inside = distance <= plane_tol
    inside_count = inside[T].sum(axis=1)
    triangles = [T[inside_count == 3]]           # untouched by the plane: kept as they are
    extra = []
    for tri in T[(inside_count > 0) & (inside_count < 3)].tolist():
        clipped = []
        for k in range(3):
            current, previous = tri[k], tri[k - 1]
            d_current, d_previous = distance[current], distance[previous]
            if inside[current] != inside[previous]:
                t = d_previous / (d_previous - d_current)
                extra.append(V[previous] + (V[current] - V[previous]) * t)
                clipped.append(len(V) + len(extra) - 1)
            if inside[current]:
                clipped.append(current)
        if len(clipped) >= 3:
            triangles.append(np.asarray([(clipped[0], clipped[k], clipped[k + 1])
                                         for k in range(1, len(clipped) - 1)], dtype=np.int64))
    out_triangles = np.concatenate(triangles)
    if not len(out_triangles):
        raise ValueError("The selected section plane removes the entire solid.")
    points = np.vstack([V] + ([np.asarray(extra)] if extra else []))
    used = np.unique(out_triangles)
    _, first, inverse = np.unique(np.rint(points[used] / weld).astype(np.int64), axis=0,
                                  return_index=True, return_inverse=True)
    remap = np.empty(len(points), dtype=np.int64)
    remap[used] = inverse.reshape(-1)
    out_triangles = remap[out_triangles]
    out_triangles = out_triangles[(out_triangles[:, 0] != out_triangles[:, 1]) &
                                  (out_triangles[:, 1] != out_triangles[:, 2]) &
                                  (out_triangles[:, 0] != out_triangles[:, 2])]
    if not len(out_triangles):
        raise ValueError("The selected section plane removes the entire solid.")
    return points[used][first], out_triangles


def _drawing_section_loops(V, topology, normal, right, up, offset=0.0, with_start=False):
    """Closed outlines of the cut face (open mesh edges lying in the section plane); with_start:
    also the first vertex index of every loop."""
    plane_tol = topology["span"] * 1e-6
    boundary = topology["edges"][topology["counts"] == 1]
    boundary = boundary[np.all(np.abs(V[boundary] @ normal - float(offset)) <= plane_tol, axis=1)]
    graph = collections.defaultdict(list)
    for a, b in boundary.tolist():
        graph[a].append(b)
        graph[b].append(a)
    unused = {(min(a, b), max(a, b)) for a, b in boundary.tolist()}
    loops, starts = [], []
    while unused:
        first = next(iter(unused))
        start, current = first
        loop = [start, current]
        unused.discard(first)
        previous = start
        while current != start:
            options = [n for n in graph[current]
                       if (min(current, n), max(current, n)) in unused and n != previous]
            if not options:
                break
            following = options[0]
            unused.discard((min(current, following), max(current, following)))
            previous, current = current, following
            if current != start:
                loop.append(current)
        if current == start and len(loop) >= 3:
            points = V[loop]
            loops.append(np.column_stack((points @ right, points @ up)))
            starts.append(loop[0])
    return (loops, starts) if with_start else loops


def _drawing_rasterize(screen, depth_values, T, valid, resolution, want_ids):
    depth = np.full((resolution, resolution), -np.inf)
    ids = np.full((resolution, resolution), -1, dtype=np.int32) if want_ids else None
    faces = np.flatnonzero(valid)
    if not len(faces):
        return depth, ids
    xy_all = screen[T[faces]]
    area_all = ((xy_all[:, 1, 0] - xy_all[:, 0, 0]) * (xy_all[:, 2, 1] - xy_all[:, 0, 1]) -
                (xy_all[:, 1, 1] - xy_all[:, 0, 1]) * (xy_all[:, 2, 0] - xy_all[:, 0, 0]))
    bx0 = np.maximum(0, np.floor(xy_all[:, :, 0].min(axis=1)).astype(int))
    bx1 = np.minimum(resolution - 1, np.floor(xy_all[:, :, 0].max(axis=1)).astype(int))
    by0 = np.maximum(0, np.floor(xy_all[:, :, 1].min(axis=1)).astype(int))
    by1 = np.minimum(resolution - 1, np.floor(xy_all[:, :, 1].max(axis=1)).astype(int))
    drawable = (bx0 <= bx1) & (by0 <= by1) & (np.abs(area_all) >= 1e-12)
    depth_flat = depth.reshape(-1)
    ids_flat = ids.reshape(-1) if want_ids else None

    # Scanline spans: every (triangle, pixel row) pair gets the x range inside all three edges,
    # so the work is proportional to the covered pixels, not to the triangle bounding boxes.
    tri = np.flatnonzero(drawable)
    if not len(tri):
        return depth, ids
    xy, area = xy_all[tri], area_all[tri]
    x0, y0 = xy[:, 0, 0], xy[:, 0, 1]
    x1, y1 = xy[:, 1, 0], xy[:, 1, 1]
    x2, y2 = xy[:, 2, 0], xy[:, 2, 1]
    # barycentric weight of each vertex = (const + kx*gx + ky*gy) / area
    weights = [((x1 * y2 - y1 * x2), (y1 - y2), (x2 - x1)),
               ((x2 * y0 - y2 * x0), (y2 - y0), (x0 - x2))]
    weights = [tuple(part / area for part in w) for w in weights]
    weights.append((1.0 - weights[0][0] - weights[1][0], -weights[0][1] - weights[1][1],
                    -weights[0][2] - weights[1][2]))
    z = depth_values[T[faces[tri]]]
    rows = by1[tri] - by0[tri] + 1
    pair_tri = np.repeat(np.arange(len(tri)), rows)
    pair_row = by0[tri][pair_tri] + (np.arange(pair_tri.size) - np.repeat(np.cumsum(rows) - rows, rows))
    gy = pair_row + 0.5
    lo = np.full(pair_tri.size, -np.inf)
    hi = np.full(pair_tri.size, np.inf)
    empty = np.zeros(pair_tri.size, dtype=bool)
    for const, kx, ky in weights:
        p = const[pair_tri] + ky[pair_tri] * gy + 1e-9          # weight + eps >= 0
        q = kx[pair_tri]
        with np.errstate(divide="ignore", invalid="ignore"):
            bound = -p / q
        lo = np.where(q > 0, np.maximum(lo, bound), lo)
        hi = np.where(q < 0, np.minimum(hi, bound), hi)
        empty |= (q == 0) & (p < 0)
    start = np.maximum(bx0[tri][pair_tri], np.ceil(np.maximum(lo, -1e9) - 0.5)).astype(np.int64)
    stop = np.minimum(bx1[tri][pair_tri], np.floor(np.minimum(hi, 1e9) - 0.5)).astype(np.int64)
    count = np.where(empty, 0, np.maximum(stop - start + 1, 0))
    keep = np.flatnonzero(count)
    pair_tri, pair_row, start, count = pair_tri[keep], pair_row[keep], start[keep], count[keep]
    # z is linear in the pixel position too
    zc = sum(w[0] * z[:, k] for k, w in enumerate(weights))
    zx = sum(w[1] * z[:, k] for k, w in enumerate(weights))
    zy = sum(w[2] * z[:, k] for k, w in enumerate(weights))
    ends = np.cumsum(count)
    chunk, first = 2_000_000, 0
    while first < len(count):
        last = int(np.searchsorted(ends, (ends[first - 1] if first else 0) + chunk, "right"))
        last = max(last, first + 1)
        c = count[first:last]
        pairs = np.repeat(np.arange(first, last), c)
        offset = np.arange(pairs.size) - np.repeat(np.cumsum(c) - c, c)
        px = start[pairs] + offset
        py = pair_row[pairs]
        t = pair_tri[pairs]
        z_values = zc[t] + zx[t] * (px + 0.5) + zy[t] * (py + 0.5)
        flat = py * resolution + px
        closer = z_values > depth_flat[flat]
        flat, z_values, t = flat[closer], z_values[closer], t[closer]
        order = np.argsort(z_values, kind="stable")
        depth_flat[flat[order]] = z_values[order]
        if want_ids:
            ids_flat[flat[order]] = faces[tri[t[order]]]
        first = last
    return depth, ids


def _drawing_project(V, T, topology, right, up, normal, resolution=900, want_ids=False, cut=None):
    """Orthographic projection with visible and hidden feature / silhouette edges and the thread
    symbols (`cut`: offset of the section plane of a section view)."""
    proj = np.column_stack((V @ right, V @ up, V @ normal))
    used = proj[np.unique(T)]
    low, high = used[:, :2].min(axis=0), used[:, :2].max(axis=0)
    center = (low + high) / 2.0
    extent = max(float((high - low).max()), 1e-9) * 1.04
    screen = np.empty((len(V), 2))
    screen[:, 0] = (proj[:, 0] - center[0]) / extent * resolution + resolution / 2
    screen[:, 1] = (center[1] - proj[:, 1]) / extent * resolution + resolution / 2
    normals = topology["normals"]
    valid = np.any(normals != 0, axis=1)
    depth, ids = _drawing_rasterize(screen, proj[:, 2], T, valid, resolution, want_ids)
    padded = np.pad(depth, 1, constant_values=-np.inf)
    near = np.minimum.reduce([padded[dy:dy + resolution, dx:dx + resolution]
                              for dy in range(3) for dx in range(3)])
    tolerance = 0.5 * extent / resolution + extent * 1e-9

    edges, two = topology["edges"], topology["two"]
    facing = (normals @ normal) > 1e-6
    silhouette = np.zeros(len(edges), dtype=bool)
    silhouette[two] = facing[topology["fa"][two]] != facing[topology["fb"][two]]
    edge_mask = topology["sharp"] | silhouette
    if "thread_zone" in topology:
        edge_mask &= ~topology["thread_zone"]
    edge_ids = np.flatnonzero(edge_mask)
    empty = np.zeros((0, 2, 2))
    result = {"bounds": (low, high), "center": center, "extent": extent,
              "resolution": resolution, "ids": ids, "visible": empty, "hidden": empty,
              "visible_edges": np.zeros(0, dtype=int), "hidden_edges": np.zeros(0, dtype=int),
              "edge_visible": np.zeros(len(edges), dtype=bool),
              "pick_points": np.zeros((0, 2)), "pick_segments": empty,
              "pick_curves": [], "normal": normal,
              "right": right, "up": up}
    if not len(edge_ids):
        _drawing_thread_symbols(result, topology, right, up, normal, near, center, extent,
                                resolution, tolerance, cut)
        _drawing_gear_symbols(result, topology, right, up, normal)
        thick, thin, thread_hidden = result["thread_lines"]
        result["pick_segments"] = np.concatenate((thick, thin, thread_hidden))
        result["visible_picks"] = {"pick_segments": np.concatenate((thick, thin)),
                                   "pick_points": np.zeros((0, 2)), "pick_curves": [],
                                   "pick_arcs": []}
        return result
    A, B = proj[edges[edge_ids, 0]], proj[edges[edge_ids, 1]]
    length = np.linalg.norm(screen[edges[edge_ids, 1]] - screen[edges[edge_ids, 0]], axis=1)
    samples = np.clip(np.ceil(length / 1.5).astype(int) + 2, 3, 1500)
    owner = np.repeat(np.arange(len(edge_ids)), samples)
    local = np.arange(owner.size) - (np.cumsum(samples) - samples)[owner]
    t = local / (samples[owner] - 1)
    pts = A[owner] + (B - A)[owner] * t[:, None]
    sx = np.clip(np.floor((pts[:, 0] - center[0]) / extent * resolution + resolution / 2)
                 .astype(int), 0, resolution - 1)
    sy = np.clip(np.floor((center[1] - pts[:, 1]) / extent * resolution + resolution / 2)
                 .astype(int), 0, resolution - 1)
    visible = pts[:, 2] >= near[sy, sx] - tolerance
    if owner.size > 2:
        gap = visible[:-2] & visible[2:] & (owner[:-2] == owner[2:])
        visible[1:-1] |= gap
    run_start = np.flatnonzero(np.r_[True, (visible[1:] != visible[:-1]) |
                                     (owner[1:] != owner[:-1])])
    run_end = np.r_[run_start[1:], owner.size] - 1
    run_owner, run_visible = owner[run_start], visible[run_start]
    run_samples = samples[run_owner]
    keep = ((run_end - run_start + 1) >= 2) | ((run_end - run_start + 1) == run_samples)
    f0 = np.maximum((local[run_start] - 0.5) / (run_samples - 1), 0.0)
    f1 = np.minimum((local[run_end] + 0.5) / (run_samples - 1), 1.0)
    delta = (B - A)[run_owner, :2]
    p0 = A[run_owner, :2] + delta * f0[:, None]
    p1 = A[run_owner, :2] + delta * f1[:, None]
    segments = np.stack((p0, p1), axis=1)
    show, hide = keep & run_visible, keep & ~run_visible
    visible_ids, hidden_ids = edge_ids[run_owner[show]], edge_ids[run_owner[hide]]
    result["visible"], result["visible_edges"] = segments[show], visible_ids
    result["hidden"], result["hidden_edges"] = segments[hide], hidden_ids
    result["edge_visible"][visible_ids] = True
    _drawing_thread_symbols(result, topology, right, up, normal, near, center, extent,
                            resolution, tolerance, cut)
    _drawing_gear_symbols(result, topology, right, up, normal)
    thick, thin, thread_hidden = result["thread_lines"]

    def seen(points):
        """Depth test of 3-D points: nothing of the part in front of them."""
        points = np.asarray(points, dtype=float).reshape(-1, 3)
        u, v, w = points @ right, points @ up, points @ normal
        sx = np.clip(np.floor((u - center[0]) / extent * resolution + resolution / 2).astype(int),
                     0, resolution - 1)
        sy = np.clip(np.floor((center[1] - v) / extent * resolution + resolution / 2).astype(int),
                     0, resolution - 1)
        return w >= near[sy, sx] - tolerance

    def shown_item(group, item):
        if group == "arcs":
            return bool(seen(item.get("points", item["center"])).any())
        if item.get("thread") is not None:
            return bool(result["thread_visible"].get(item["thread"], False))
        if item.get("gear"):
            return True
        return bool(result["edge_visible"][item["edges"]].any())

    def pick_geometry(chosen_edges, pick_segments, only_visible):
        """What the dimension tools can pick: points (corners, circle and arc centres), straight
        pieces and curves; with `only_visible` just what is seen (no hidden lines)."""
        picks = {"pick_segments": pick_segments, "pick_curves": []}
        corners = np.unique(edges[chosen_edges]) if len(chosen_edges) else np.zeros(0, dtype=int)
        if only_visible and len(corners):
            corners = corners[seen(V[corners])]
        items = [(group, item) for group in ("circles", "arcs") for item in topology.get(group, ())
                 if "axis" in item and "center" in item and abs(float(item["axis"] @ normal)) >= 0.999
                 and (not only_visible or shown_item(group, item))]
        centres = [(float(item["center"] @ right), float(item["center"] @ up)) for _g, item in items]
        picks["pick_points"] = np.unique(np.concatenate((
            proj[corners, :2], np.asarray(centres, dtype=float).reshape(-1, 2))), axis=0)
        projected_arcs = []
        for group, arc in items:                      # an edge-on arc is just a line: left out
            points = np.asarray(arc.get("points", ()), dtype=float).reshape(-1, 3) \
                if group == "arcs" else np.zeros((0, 3))
            if len(points) >= 6:
                projected_arcs.append(np.column_stack((points @ right, points @ up)))
        arc_endpoints = np.asarray([endpoint for curve in projected_arcs
                                    for endpoint in (curve[0], curve[-1])], dtype=float).reshape(-1, 2)
        if len(chosen_edges):
            known_arcs = [(np.array((float(arc["center"] @ right), float(arc["center"] @ up))),
                           float(arc["radius"])) for arc in topology.get("arcs", ())
                          if "center" in arc and "radius" in arc]
            chains = _drawing_group_segments(
                proj[edges[chosen_edges], :2], max(extent / resolution * 0.01, extent * 1e-9),
                split_points=arc_endpoints)
            # silhouettes (e.g. a fillet seen from the side) join arcs and straight edges into one
            # smooth chain; separate them so the arc gives a radius and the lines stay measurable
            for chain in chains:
                for piece, circle in _drawing_split_smooth_chain(chain):
                    if circle is None:
                        picks["pick_curves"].append(piece)
                    elif not any(abs(circle[1] - radius) <= 0.02 * radius and
                                 float(np.linalg.norm(circle[0] - centre)) <= 0.02 * radius
                                 for centre, radius in known_arcs):
                        picks["pick_curves"].append(piece)
                        projected_arcs.append(piece)
        for group, circle in items:
            if group != "circles":
                continue
            middle = np.array((circle["center"] @ right, circle["center"] @ up))
            angles = np.linspace(0.0, 2.0 * math.pi, 65)
            picks["pick_curves"].append(middle + float(circle["radius"]) * np.column_stack(
                (np.cos(angles), np.sin(angles))))
        picks["pick_curves"].extend(projected_arcs)
        picks["pick_arcs"] = projected_arcs
        return picks

    result.update(pick_geometry(
        np.unique(np.concatenate((visible_ids, hidden_ids))),
        np.concatenate((segments[show], segments[hide], thick, thin, thread_hidden)), False))
    # views drawn without hidden lines (and section views) only offer what is drawn
    result["visible_picks"] = pick_geometry(
        np.unique(visible_ids), np.concatenate((segments[show], thick, thin)), True)
    return result


def _drawing_split_smooth_chain(points):
    """Split a smooth projected polyline into straight pieces and circular arcs.
    Returns [(points, (centre, radius) or None)] in order; an arc is a run of equal turning angles."""
    full = np.asarray(points, dtype=float).reshape(-1, 2)
    P = full
    if len(P) < 5:
        return [(full, None)]
    keep = [0]                       # drop collinear subdivision points (T-junctions of the mesh)
    for k in range(1, len(P) - 1):
        a, b = P[k] - P[keep[-1]], P[k + 1] - P[k]
        if abs(a[0] * b[1] - a[1] * b[0]) > 0.0035 * np.hypot(*a) * np.hypot(*b):
            keep.append(k)
    keep.append(len(P) - 1)
    original, P = np.asarray(keep), P[keep]
    if len(P) < 5:
        return [(full, None)]
    d = np.diff(P, axis=0)
    seg = np.hypot(d[:, 0], d[:, 1])
    if (seg <= 1e-12).any():
        return [(full, None)]
    cross = d[:-1, 0] * d[1:, 1] - d[:-1, 1] * d[1:, 0]
    turn = np.degrees(np.arctan2(cross, (d[:-1] * d[1:]).sum(axis=1)))
    runs = []
    i = 0
    while i < len(turn):
        t = turn[i]
        if not 0.4 <= abs(t) <= 36.0:
            i += 1
            continue
        j = i
        while (j + 1 < len(turn) and turn[j + 1] * t > 0
               and abs(turn[j + 1] - t) <= 0.12 * abs(t) + min(0.5, 0.25 * abs(t))
               and 0.6 <= seg[j + 1] / seg[i] <= 1.67):
            j += 1
        if j > i and 15.0 <= abs(float(turn[i:j + 1].sum())) <= 340.0:
            run = P[i:j + 3]
            mean = run.mean(axis=0)
            local = run - mean
            c = np.linalg.lstsq(np.column_stack((2 * local, np.ones(len(local)))),
                                (local ** 2).sum(axis=1), rcond=None)[0]
            radius = math.sqrt(max(c[2] + c[0] ** 2 + c[1] ** 2, 0.0))
            if radius > 0 and float(np.abs(np.hypot(*(local - c[:2]).T) - radius).max()) <= 0.012 * radius:
                runs.append((i, j + 2, (mean + c[:2], radius)))
        i = j + 1
    if not runs:
        return [(full, None)]
    pieces, cursor = [], 0
    for start, end, circle in runs:
        if start > cursor:
            pieces.append((full[original[cursor]:original[start] + 1], None))
        pieces.append((full[original[start]:original[end] + 1], circle))
        cursor = end
    if cursor < len(P) - 1:
        pieces.append((full[original[cursor]:], None))
    return pieces


def _drawing_group_segments(segments, tolerance, split_points=()):
    """Join projected mesh edges into smooth selectable chains, stopping at sharp corners."""
    segments = np.asarray(segments, dtype=float).reshape(-1, 2, 2)
    if len(segments) < 2:
        return []
    keys = np.rint(segments.reshape(-1, 2) / max(float(tolerance), 1e-12)).astype(np.int64)
    incident = collections.defaultdict(list)
    for endpoint, key in enumerate(keys):
        incident[tuple(key)].append((endpoint // 2, endpoint % 2))
    split_points = np.asarray(split_points, dtype=float).reshape(-1, 2)
    continuation = {}
    smooth_dot = -math.cos(math.radians(15.0))
    for endpoints in incident.values():
        point = segments[endpoints[0][0], endpoints[0][1]]
        if len(split_points) and \
                float(np.linalg.norm(split_points - point, axis=1).min()) <= tolerance:
            continue
        candidates = []
        for first_index in range(len(endpoints)):
            first, first_end = endpoints[first_index]
            for second_index in range(first_index + 1, len(endpoints)):
                second, second_end = endpoints[second_index]
                if first == second:
                    continue
                first_direction = segments[first, 1 - first_end] - segments[first, first_end]
                second_direction = segments[second, 1 - second_end] - segments[second, second_end]
                denominator = np.linalg.norm(first_direction) * np.linalg.norm(second_direction)
                if denominator <= 1e-15:
                    continue
                dot = float(first_direction @ second_direction) / denominator
                if dot <= smooth_dot:
                    candidates.append((dot, (first, first_end), (second, second_end)))
        used_endpoints = set()
        for _dot, first, second in sorted(candidates):
            if first in used_endpoints or second in used_endpoints:
                continue
            continuation[first] = second
            continuation[second] = first
            used_endpoints.update((first, second))

    visited = set()
    curves = []
    seeds = [(index, endpoint) for index in range(len(segments)) for endpoint in (0, 1)
             if (index, endpoint) not in continuation]
    seeds.extend((index, 0) for index in range(len(segments)))
    for seed, start_end in seeds:
        if seed in visited:
            continue
        current, entry_end = seed, start_end
        points = [segments[current, entry_end].copy()]
        while current not in visited:
            visited.add(current)
            exit_end = 1 - entry_end
            points.append(segments[current, exit_end].copy())
            following = continuation.get((current, exit_end))
            if following is None:
                break
            current, entry_end = following
        if len(points) > 2:
            curves.append(np.asarray(points))
    return curves


# ── hole and thread callouts, parts list (Technical Drawing, Phase 2) ──────────
# A hole is a group of coaxial rims (sharp circular edges) whose wall faces point at the axis.
# Seen from the entry: its diameter (smallest rim), through or blind with the depth, and a
# counterbore (a shoulder: two radii at one depth) or a countersink (a cone at the entry).
# Threads come from the threads found on the mesh (_drawing_find_threads).

def _drawing_rim_info(topology, circle):
    """Of the faces along a rim: the normal component along the axis of the face around it (the
    flat face or cone: sign of its normal along the axis) and whether its wall faces point at
    the axis (a bore, not a boss). None for rims without edges (thread ends)."""
    edge_ids = circle.get("edges") or []
    if not edge_ids:
        return None
    V, normals = topology["V"], topology["normals"]
    edges = topology["edges"][edge_ids]
    axis, center = circle["axis"], circle["center"]
    middles = (V[edges[:, 0]] + V[edges[:, 1]]) / 2.0 - center
    radial = middles - np.outer(middles @ axis, axis)
    radial /= np.maximum(np.linalg.norm(radial, axis=1), 1e-12)[:, None]
    cap, wall = [], []
    for column in ("fa", "fb"):
        faces = topology[column][edge_ids]
        valid = faces >= 0
        if not valid.any():
            continue
        n = normals[faces[valid]]
        along = n @ axis
        across = np.einsum("ij,ij->i", n, radial[valid])
        cap += along[np.abs(along) >= 0.5].tolist()
        wall += across[np.abs(along) < 0.9].tolist()
    return {"cap": float(np.mean(cap)) if cap else 0.0,
            "inner": bool(wall) and float(np.mean(wall)) < 0.0}


def _drawing_hole_groups(topology):
    """Holes of a part (cached on the topology): [{"axis", "entry" (3-D centre of the opening),
    "d", "through", "depth", "cbore" (D, depth) or None, "csk" (D, angle) or None,
    "both_open"}]. Bosses (wall faces pointing away from the axis) are no holes."""
    if "_holes" in topology:
        return topology["_holes"]
    span = topology["span"]
    tolerance = max(span * 1e-4, 1e-6)
    groups = []
    for circle in topology.get("circles", ()):
        if circle.get("thread") is not None or not circle.get("edges"):
            continue
        axis = np.asarray(circle["axis"], dtype=float)
        axis = axis / max(float(np.linalg.norm(axis)), 1e-12)
        centre = np.asarray(circle["center"], dtype=float)
        for group in groups:
            if abs(float(group["axis"] @ axis)) > 0.9999 and float(np.linalg.norm(
                    np.cross(centre - group["point"], group["axis"]))) <= max(tolerance, 1e-3 * circle["radius"]):
                group["rims"].append(circle)
                break
        else:
            groups.append({"axis": axis, "point": centre, "rims": [circle]})
    holes = []
    for group in groups:
        axis, point = group["axis"], group["point"]
        rims = []
        for circle in group["rims"]:
            info = _drawing_rim_info(topology, dict(circle, axis=axis))
            if info is None:
                continue
            rims.append({"t": float((np.asarray(circle["center"]) - point) @ axis),
                         "r": float(circle["radius"]), **info})
        if not rims or not any(rim["inner"] for rim in rims):
            continue                                   # a boss or a plain outline circle
        radius = min(rim["r"] for rim in rims if rim["inner"]) if any(rim["inner"] for rim in rims) \
            else min(rim["r"] for rim in rims)
        low, high = min(rim["t"] for rim in rims), max(rim["t"] for rim in rims)

        def end_open(t, outward):
            """The face around the rims at this end points away from the hole: an opening."""
            caps = [rim["cap"] * outward for rim in rims if abs(rim["t"] - t) <= tolerance]
            return bool(caps) and max(caps) > 0.3

        def end_radius(t):
            return max(rim["r"] for rim in rims if abs(rim["t"] - t) <= tolerance)

        open_low, open_high = end_open(low, -1.0), end_open(high, 1.0)
        if high - low <= tolerance:                    # one rim only: no length to analyse
            open_low = open_high = True
        if open_low and open_high:
            entry_t, sign = (low, 1.0) if end_radius(low) > end_radius(high) * 1.01 else (high, -1.0)
            if abs(end_radius(low) - end_radius(high)) <= 0.01 * radius:
                entry_t, sign = None, 1.0              # symmetric through hole: entry by the view
        elif open_low:
            entry_t, sign = low, 1.0
        elif open_high:
            entry_t, sign = high, -1.0
        else:
            continue                                   # a closed cavity: not drawn as a hole
        holes.append({"axis": axis, "point": point, "rims": rims, "radius": radius,
                      "low": low, "high": high, "entry_t": entry_t, "sign": sign,
                      "through": open_low and open_high and high - low > tolerance})
    topology["_holes"] = holes
    return holes


def _drawing_hole_data(hole, view_normal=None):
    """Callout values of a hole seen along `view_normal` (the entry faces the viewer when both
    ends are open and alike): {"d", "through", "depth", "cbore", "csk", "entry"}."""
    axis, rims, radius = hole["axis"], hole["rims"], hole["radius"]
    entry_t, sign = hole["entry_t"], hole["sign"]
    if entry_t is None:                                # plain through hole: the end facing the viewer
        facing = view_normal is None or float(np.asarray(view_normal) @ axis) >= 0
        entry_t, sign = (hole["high"], -1.0) if facing else (hole["low"], 1.0)
    span = max(hole["high"] - hole["low"], 1e-9)
    tolerance = max(span * 1e-3, 1e-6)
    steps = sorted(((rim["t"] - entry_t) * sign, rim["r"]) for rim in rims)
    near = lambda a, b: abs(a - b) <= max(0.01 * radius, 1e-6)
    depth = max((s for s, r in steps if near(r, radius)), default=0.0)
    data = {"d": float(2.0 * radius), "through": bool(hole["through"]), "depth": float(depth),
            "cbore": None, "csk": None,
            "entry": (hole["point"] + axis * entry_t).tolist()}
    entry_radius = max((r for s, r in steps if s <= tolerance), default=radius)
    if entry_radius > radius * 1.02:
        shoulder = [s for s, r in steps if s > tolerance and near(r, entry_radius)]
        if shoulder and any(near(r, radius) and abs(s - shoulder[0]) <= tolerance for s, r in steps):
            data["cbore"] = (float(2.0 * entry_radius), float(shoulder[0]))
        else:
            first = min((s for s, r in steps if s > tolerance and near(r, radius)), default=None)
            if first:
                angle = 2.0 * math.degrees(math.atan2(entry_radius - radius, first))
                data["csk"] = (float(2.0 * entry_radius), float(round(angle * 2.0) / 2.0))
    return data


def _drawing_hole_signature(data):
    return (round(data["d"], 3), data["through"], round(data["depth"], 2),
            tuple(round(v, 2) for v in data["cbore"]) if data["cbore"] else None,
            tuple(round(v, 2) for v in data["csk"]) if data["csk"] else None)


def _drawing_view_holes(topology, view):
    """Holes whose axis points at the viewer: [(hole, data, (u, v) of the opening)]."""
    found = []
    for hole in _drawing_hole_groups(topology):
        if abs(float(hole["axis"] @ view["normal"])) < 0.999:
            continue
        data = _drawing_hole_data(hole, view["normal"])
        entry = np.asarray(data["entry"])
        found.append((hole, data, (float(entry @ view["right"]), float(entry @ view["up"]))))
    return found


def _drawing_hole_at(topology, view, uv, reach):
    """The hole callout values at a view point (on the rim or inside it), with the number of
    alike holes in the view; None if no hole is there."""
    best = None
    holes = _drawing_view_holes(topology, view)
    for hole, data, centre in holes:
        distance = math.hypot(uv[0] - centre[0], uv[1] - centre[1])
        outer = max(rim["r"] for rim in hole["rims"])
        if distance <= outer + reach and (best is None or distance < best[0]):
            best = (distance, data)
    if best is None:
        return None
    signature = _drawing_hole_signature(best[1])
    count = sum(1 for _h, data, _c in holes if _drawing_hole_signature(data) == signature)
    return dict(best[1], count=count)


def _drawing_thread_size(thread):
    """(nominal, pitch, family) of a thread: from its Thread tool feature when the drawing has
    it, else the nearest standard size to what the mesh shows (else the measured values)."""
    feature = thread.get("feature")
    if feature:
        return float(feature["nominal"]), float(feature["pitch"]), feature.get("standard", "ISO")
    nominal, pitch = 2.0 * float(thread["major"]), float(thread["pitch"])
    best = None
    for _label, size, size_pitch, family in THREAD_SIZES:
        if abs(size_pitch - pitch) <= 0.02 * size_pitch and abs(size - nominal) <= max(0.08 * size, 0.3):
            if best is None or abs(size - nominal) < abs(best[0] - nominal):
                best = (size, size_pitch, family)
    if best is not None:
        return best
    size = round(nominal * 2.0) / 2.0
    coarse = THREAD_METRIC_COARSE.get(size)
    if coarse is not None and abs(coarse - pitch) <= 0.06 * coarse:
        return size, coarse, "ISO"
    return size, round(pitch, 3), "Custom"


def _drawing_thread_label(thread):
    """Designation of a thread: 'M8' (metric coarse), 'M8×1' (fine), 'Tr20×4', 'G1/2',
    '1/2-14 NPT', a Unified size; and the same with the pitch (for show_pitch)."""
    nominal, pitch, family = _drawing_thread_size(thread)
    return (thread_designation(nominal, pitch, family),
            thread_designation(nominal, pitch, family, show_pitch=True))


def _drawing_thread_data(thread):
    """Callout values of a thread; class, hand and length from its feature where there is one."""
    short, full = _drawing_thread_label(thread)
    feature = thread.get("feature") or {}
    data = {"label": short, "label_pitch": full, "internal": bool(thread["internal"]),
            "length": float(thread["high"] - thread["low"]),
            "through": not any(thread.get("limits") or (False, False)),
            "hand": feature.get("hand") or thread.get("hand") or "right"}
    if feature:
        fit = str(feature.get("fit", ""))
        data["cls"] = "" if fit in ("6", "7") else fit
        if not feature.get("whole") and feature.get("length"):
            data["length"] = float(feature["length"])
    return data


def _drawing_thread_at(topology, view, uv, reach):
    """Thread callout values at a view point: a thread seen end-on (its circle) or from the side
    (within its major diameter of the axis); with the number of alike threads end-on."""
    threads = topology.get("threads") or []
    right, up, normal = (np.asarray(view[key], dtype=float) for key in ("right", "up", "normal"))
    best = None
    for thread in threads:
        axis, point = np.asarray(thread["axis"], dtype=float), np.asarray(thread["point"], dtype=float)
        ends = [point + axis * thread["low"], point + axis * thread["high"]]
        a, b = (np.array((float(end @ right), float(end @ up))) for end in ends)
        target = np.asarray(uv, dtype=float)
        if abs(float(axis @ normal)) > 0.999:
            distance = float(np.linalg.norm(target - a))
        else:
            along = b - a
            span = float(along @ along)
            t = 0.0 if span <= 1e-18 else min(max(float((target - a) @ along) / span, 0.0), 1.0)
            distance = float(np.linalg.norm(target - (a + along * t)))
        if distance <= thread["major"] + reach and (best is None or distance < best[0]):
            best = (distance, thread)
    if best is None:
        return None
    data = _drawing_thread_data(best[1])

    def key(item):
        return (item["label_pitch"], item["internal"], round(item["length"], 1), item["through"])

    count = 1
    if abs(float(np.asarray(best[1]["axis"]) @ normal)) > 0.999:
        count = sum(1 for thread in threads if abs(float(np.asarray(thread["axis"]) @ normal)) > 0.999
                    and key(_drawing_thread_data(thread)) == key(data))
    return dict(data, count=count)


# ── gear and thread data of the model (Technical Drawing, Phase 4) ─────────────
GEAR_KIND_TEXT = {"spur": "Spur gear", "helical": "Helical gear", "herringbone": "Herringbone gear",
                  "internal": "Internal gear", "rack": "Rack", "bevel": "Bevel gear",
                  "planetary": "Planetary set", "worm": "Worm", "worm_wheel": "Worm wheel"}
DRAWING_GEAR_QUALITIES = ("5", "6", "7", "8", "9", "10", "11", "12")     # ISO 1328-1 / DIN 3961


def _drawing_gear_info(entry, objects):
    """Data of a gear made with the Gear tool, for the gear data table and the simplified view
    (ISO 2203): rows [(name, symbol, value text)] and, for cylindrical gears, the axis, origin,
    tip / pitch / root radii and axial extent (model coordinates). None for other bodies."""
    parameters = entry.get("gear_parameters") or {}
    kind = parameters.get("kind")
    if not kind:
        return None
    module = float(parameters.get("module") or 0.0)
    teeth = int(parameters.get("teeth") or 0)
    alpha = float(parameters.get("pressure_angle", 20.0))
    shift = float(parameters.get("profile_shift", 0.0) or 0.0)
    shorten = float(parameters.get("tip_reduction", 0.0) or 0.0)
    width = float(parameters.get("thickness", 0.0) or 0.0)
    trace = kind if kind in ("helical", "herringbone") else \
        parameters.get("tooth_trace", "straight") if kind in ("rack", "internal") else "straight"
    beta = float(parameters.get("helix_angle", 0.0) or 0.0) if trace != "straight" else 0.0
    mm = lambda value: f"{value:.3f}".rstrip("0").rstrip(".") + " mm"
    rows = [("Gear", "", GEAR_KIND_TEXT.get(kind, str(kind).replace("_", " ").title()))]
    info = {"kind": kind, "rows": rows, "name": entry.get("name", "Gear")}
    if module <= 0 or teeth <= 0:
        return info
    if beta:
        rows += [("Normal module", "mn", mm(module * math.cos(math.radians(beta)))),
                 ("Transverse module", "mt", mm(module))]
    else:
        rows.append(("Module", "m", mm(module)))
    rows += [("Number of teeth", "z", f"{teeth}"), ("Pressure angle", "α", f"{alpha:g}°")]
    if beta:
        hand = "right" if beta > 0 else "left"
        rows.append(("Helix angle", "β", f"{abs(beta):g}° {hand}" +
                     (" / opposite (herringbone)" if trace == "herringbone" else "")))
    pitch = module * teeth
    if kind == "rack":
        rows += [("Pitch", "p", mm(math.pi * module)),
                 ("Length", "l", mm(float(parameters.get("rack_length", 0.0) or 0.0)))]
    elif kind == "bevel":
        rows += [("Pitch cone angle", "δ", f"{float(parameters.get('bevel_angle', 45.0)):.2f}°"),
                 ("Shaft angle", "Σ", f"{float(parameters.get('shaft_angle', 90.0)):g}°"),
                 ("Pitch diameter (heel)", "d", mm(pitch)),
                 ("Tip diameter (heel)", "da", mm(float(parameters.get("outside_diameter") or
                                                      gear_outside_from_module("bevel", module, teeth, shift,
                                                                               parameters.get("bevel_angle", 45.0)))))]
    elif kind in ("spur", "helical", "herringbone", "internal"):
        internal = kind == "internal"
        tip = module * (teeth - 2.0) if internal else module * (teeth + 2.0 + 2.0 * shift - 2.0 * shorten)
        root = module * (teeth + 2.5) if internal else module * (teeth - 2.5 + 2.0 * shift)
        if shift and not internal:
            rows.append(("Profile shift coefficient", "x", f"{shift:+.3f}"))
        rows += [("Pitch diameter", "d", mm(pitch)), ("Tip diameter", "da", mm(tip)),
                 ("Root diameter", "df", mm(root)),
                 ("Base diameter", "db", mm(pitch * math.cos(math.radians(alpha))))]
        rotation = _import_rotation_matrix(entry.get("gear_rotation", (0.0, 0.0, 0.0)))
        origin = np.asarray(entry.get("gear_position", (0.0, 0.0, 0.0)), dtype=float)
        axis = rotation[:, 2]
        vertices = np.asarray((entry.get("solid") or ((), ()))[0], dtype=float).reshape(-1, 3)
        along = (vertices - origin) @ axis if len(vertices) else np.array((0.0, width))
        info.update(axis=axis.tolist(), origin=origin.tolist(), r_tip=tip / 2.0,
                    r_pitch=pitch / 2.0, r_root=root / 2.0, z0=float(along.min()),
                    z1=float(along.max()), internal=internal, module=module,
                    helix=beta, trace=trace)
    if width and kind != "rack":
        rows.append(("Face width", "b", mm(width)))
    # the mating gear of a pair made together, with the centre distance
    pair = parameters.get("gear_pair_id")
    if pair:
        mate = next((other for other in objects if other is not entry and
                     (other.get("gear_parameters") or {}).get("gear_pair_id") == pair), None)
        if mate is not None:
            mate_parameters = mate["gear_parameters"]
            rows.append(("Mating gear", "", f"{mate.get('name', 'Gear')}  (z = {int(mate_parameters.get('teeth', 0))})"))
            try:
                primary, other = (parameters, mate_parameters) if \
                    parameters.get("gear_pair_role") == "primary" else (mate_parameters, parameters)
                if primary.get("kind") != "bevel":
                    rows.append(("Centre distance", "a", mm(gear_pair_center_distance(primary, other))))
            except (KeyError, TypeError, ValueError, ZeroDivisionError):
                pass
    return info


def _drawing_assembly_items(assembly):
    """Parts of an assembly grouped for the parts list (same source and shape, Phase 5):
    [{"name", "qty", "material", "components": [component names]}] in item order."""
    items, keys = [], {}
    for component in assembly["components"]:
        if not component.get("visible", True):
            continue
        bodies = [body for body in component["bodies"] if not body.get("fused")]
        name = component.get("source_name") or component["name"]
        signature = tuple(round(float(np.ptp(np.asarray(body["vertices"], dtype=float), axis=0).sum()), 3)
                          if len(body["vertices"]) else 0.0 for body in bodies)
        key = (name, signature)
        if key in keys:
            items[keys[key]]["qty"] += 1
            items[keys[key]]["components"].append(component["name"])
            continue
        keys[key] = len(items)
        material = next((body.get("material") for body in bodies if body.get("material")), "")
        items.append({"name": name, "qty": 1, "material": material or "",
                      "components": [component["name"]]})
    return items


def _drawing_assembly_mesh(entry, explode=0.0):
    """(vertices, triangles) of a project assembly as drawn: every visible component in place,
    with an explode distance the aligned parts moved apart along their explosion direction."""
    assembly = assembly_from_data(entry.get("assembly_data"))
    vertices, triangles = [], []
    for component in assembly["components"]:
        if not component.get("visible", True):
            continue
        offset = None
        if explode:
            direction = assembly_explosion_direction(assembly, component)
            if direction is not None:
                offset = np.asarray(direction, dtype=float) * float(explode)
        V, T = assembly_world_mesh(component, offset)
        triangles += (T + len(vertices)).tolist()
        vertices += V.tolist()
    return vertices, triangles


def _drawing_assembly_info(entry, explode=0.0):
    """Model info of an assembly sheet: the components with their parts-list item and box (for
    balloons that find their part) and the trace lines of an exploded view."""
    assembly = assembly_from_data(entry.get("assembly_data"))
    items = _drawing_assembly_items(assembly)
    item_of = {name: index + 1 for index, item in enumerate(items) for name in item["components"]}
    components, traces = [], []
    for component in assembly["components"]:
        if not component.get("visible", True) or component["name"] not in item_of:
            continue
        box = assembly_bounds(component)
        if box is None:
            continue
        low, high = np.asarray(box[0], dtype=float), np.asarray(box[1], dtype=float)
        shift = np.zeros(3)
        if explode:
            direction = assembly_explosion_direction(assembly, component)
            if direction is not None:
                shift = np.asarray(direction, dtype=float) * float(explode)
                centre = (low + high) / 2.0
                traces.append([centre.tolist(), (centre + shift).tolist()])
        components.append({"name": component["name"], "item": item_of[component["name"]],
                           "low": (low + shift).tolist(), "high": (high + shift).tolist()})
    return {"gears": [], "threads": [], "components": components, "traces": traces}


def _drawing_component_at(topology, view, uv):
    """Parts-list item of the assembly part under a view point: of the parts whose box covers the
    point, the one with the smallest outline there (the most specific); None if there is none."""
    best = None
    right, up = np.asarray(view["right"], dtype=float), np.asarray(view["up"], dtype=float)
    for component in topology.get("components") or ():
        corners = np.asarray(component["corners"], dtype=float)
        us, vs = corners @ right, corners @ up
        if us.min() <= uv[0] <= us.max() and vs.min() <= uv[1] <= vs.max():
            area = float((us.max() - us.min()) * (vs.max() - vs.min()))
            if best is None or area < best[0]:
                best = (area, component["item"])
    return None if best is None else best[1]


def _drawing_model_info(entry, objects, explode=0.0):
    """Gears and thread features of a sheet's model (the solid and its additive bodies), in
    model coordinates: {"gears": [...], "threads": [...]}; an assembly gives its components and
    the trace lines of its exploded view instead."""
    if entry is None:
        return {"gears": [], "threads": []}
    if entry.get("type") == "assembly":
        return _drawing_assembly_info(entry, explode)
    bodies = [entry] + [o for o in entry_descendants(entry, objects)
                        if o.get("type") == "extrusion" and not o.get("cut")
                        and not o.get("preview") and o.get("solid") and entry_visible(o)]
    gears = [info for info in (_drawing_gear_info(body, objects) for body in bodies) if info]
    ids = {id(body) for body in bodies}
    threads = [copy.deepcopy(o["feat"]) for o in objects
               if o.get("type") == "feature" and isinstance(o.get("feat"), dict) and
               o["feat"].get("type") == "thread" and id(o.get("parent")) in ids and
               o["feat"].get("visible", True)]
    return {"gears": gears, "threads": threads}


def _drawing_model_geometry(info, center, rotation):
    """Gears and thread features moved into the drawing's frame (centred, quarter-turned)."""
    if not info:
        return [], []
    move_point = lambda p: rotation @ (np.asarray(p, dtype=float) - center)
    move_vector = lambda d: rotation @ np.asarray(d, dtype=float)
    gears = []
    for gear in info.get("gears") or []:
        if "axis" in gear:
            gears.append(dict(gear, axis=move_vector(gear["axis"]), origin=move_point(gear["origin"])))
    threads = []
    for feature in info.get("threads") or []:
        try:
            threads.append(dict(feature, axis=move_vector(feature["axis"]),
                                point=move_point(feature["point"])))
        except (KeyError, TypeError, ValueError):
            continue
    return gears, threads


def _drawing_assembly_geometry(info, center, rotation):
    """Assembly components (box corners) and exploded-view traces in the drawing's frame."""
    if not info:
        return [], []
    move = lambda p: rotation @ (np.asarray(p, dtype=float) - center)
    components = []
    for component in info.get("components") or []:
        low, high = np.asarray(component["low"], dtype=float), np.asarray(component["high"], dtype=float)
        corners = [move((x, y, z)) for x in (low[0], high[0]) for y in (low[1], high[1])
                   for z in (low[2], high[2])]
        components.append({"name": component["name"], "item": component["item"], "corners": corners})
    traces = [(move(a), move(b)) for a, b in info.get("traces") or []]
    return components, traces


def _drawing_match_thread_features(threads, features):
    """Each thread found on the mesh gets the Thread tool feature it was made with (same axis
    line, nominal diameter within 15 %)."""
    for thread in threads:
        axis, point = np.asarray(thread["axis"], dtype=float), np.asarray(thread["point"], dtype=float)
        for feature in features:
            other = np.asarray(feature["axis"], dtype=float)
            other = other / max(float(np.linalg.norm(other)), 1e-12)
            offset = np.asarray(feature["point"], dtype=float) - point
            off_axis = float(np.linalg.norm(offset - (offset @ axis) * axis))
            nominal = float(feature.get("nominal", 0.0))
            if abs(float(axis @ other)) > 0.999 and off_axis <= 0.1 * thread["major"] + 1e-6 and \
                    abs(nominal / 2.0 - thread["major"]) <= 0.15 * thread["major"]:
                thread["feature"] = feature
                break


def _drawing_gear_zone(V, edges, gears, span):
    """Edges of gear teeth (between root and tip radius over the face width): the simplified
    representation (ISO 2203) draws circles and lines instead."""
    zone = np.zeros(len(edges), dtype=bool)
    for gear in gears:
        axis, origin = np.asarray(gear["axis"], dtype=float), np.asarray(gear["origin"], dtype=float)
        relative = V - origin
        along = relative @ axis
        distance = np.linalg.norm(relative - np.outer(along, axis), axis=1)
        margin = 0.3 * gear.get("module", 1.0) + span * 1e-6
        low = min(gear["r_tip"], gear["r_root"]) - margin
        high = max(gear["r_tip"], gear["r_root"]) + margin
        inside = (distance >= low) & (distance <= high) & \
            (along >= gear["z0"] - margin) & (along <= gear["z1"] + margin)
        zone |= inside[edges[:, 0]] & inside[edges[:, 1]]
    return zone


def _drawing_gear_symbols(result, topology, right, up, normal):
    """Simplified gears (ISO 2203): along the axis the tip circle thick, the pitch circle as a
    chain line and the root circle thin; from the side the tip lines thick, the pitch line as a
    chain line (2 mm beyond the faces) and the root lines thin, the faces as thick lines."""
    thick, thin, chain = [], [], []

    def flat(points):
        points = np.asarray(points, dtype=float).reshape(-1, 3)
        return np.column_stack((points @ right, points @ up))

    for gear in topology.get("gears") or ():
        axis, origin = np.asarray(gear["axis"], dtype=float), np.asarray(gear["origin"], dtype=float)
        along_normal = float(axis @ normal)
        if abs(along_normal) > 0.999:
            angles = np.linspace(0.0, 2.0 * math.pi, 145)
            ring = np.outer(np.cos(angles), right) + np.outer(np.sin(angles), up)
            for radius, target in ((gear["r_tip"], thick), (gear["r_pitch"], chain),
                                   (gear["r_root"], thin)):
                points = flat(origin + radius * ring)
                target.extend(zip(points[:-1], points[1:]))
        elif abs(along_normal) < 1e-3:
            side = np.cross(axis, normal)
            side /= np.linalg.norm(side)
            z0, z1 = gear["z0"], gear["z1"]
            beyond = 2.0 * max(gear.get("module", 1.0), 1.0)
            for sign in (1.0, -1.0):
                for radius, target, a, b in ((gear["r_tip"], thick, z0, z1),
                                             (gear["r_pitch"], chain, z0 - beyond, z1 + beyond),
                                             (gear["r_root"], thin, z0, z1)):
                    ends = flat([origin + axis * a + side * sign * radius,
                                 origin + axis * b + side * sign * radius])
                    target.append((ends[0], ends[1]))
            outer = max(gear["r_tip"], gear["r_root"])
            for end in (z0, z1):
                ends = flat([origin + axis * end + side * outer, origin + axis * end - side * outer])
                thick.append((ends[0], ends[1]))
            # helical / herringbone teeth: three thin lines at the helix angle (ISO 2203)
            beta = math.radians(float(gear.get("helix", 0.0) or 0.0))
            if abs(beta) > 1e-6 and z1 - z0 > 1e-6:
                middle, reach = (z0 + z1) / 2.0, 0.6 * min(gear["r_tip"], gear["r_root"])
                slope = math.tan(beta)
                spacing = 0.18 * reach
                for k in (-1, 0, 1):
                    centre = origin + side * (k * spacing * 2.0)
                    if gear.get("trace") == "herringbone":
                        half = (z1 - z0) / 2.0 * 0.8
                        points = [centre + axis * (middle - half) + side * (half * slope),
                                  centre + axis * middle,
                                  centre + axis * (middle + half) + side * (half * slope)]
                        pts = flat(points)
                        thin.extend([(pts[0], pts[1]), (pts[1], pts[2])])
                    else:
                        half = min((z1 - z0) / 2.0 * 0.8, reach / max(abs(slope), 1e-6))
                        pts = flat([centre + axis * (middle - half) - side * (half * slope),
                                    centre + axis * (middle + half) + side * (half * slope)])
                        thin.append((pts[0], pts[1]))
    as_array = lambda items: np.asarray(items, dtype=float).reshape(-1, 2, 2)
    thick, thin, chain = as_array(thick), as_array(thin), as_array(chain)
    result["visible"] = np.concatenate((result["visible"], thick))
    result["visible_edges"] = np.concatenate((result["visible_edges"], np.full(len(thick), -1, dtype=int)))
    result["thin"] = np.concatenate((result.get("thin", np.zeros((0, 2, 2))), thin))
    result["chain"] = chain


def _drawing_parts(entry, objects):
    """Parts list of a sheet's model: the solid and its additive bodies (as drawn), alike bodies
    (same shape and material) counted together; of an assembly its parts. [{"name", "qty",
    "material"}]"""
    if entry is None:
        return []
    if entry.get("type") == "assembly":
        return [{"name": item["name"], "qty": item["qty"], "material": item["material"]}
                for item in _drawing_assembly_items(assembly_from_data(entry.get("assembly_data")))]
    bodies = [entry] + [o for o in entry_descendants(entry, objects)
                        if o.get("type") == "extrusion" and not o.get("cut")
                        and not o.get("preview") and o.get("solid") and entry_visible(o)]
    parts, keys = [], {}
    for body in bodies:
        vertices = np.asarray(body["solid"][0], dtype=float).reshape(-1, 3)
        extent = tuple(sorted(np.round(np.ptp(vertices, axis=0), 3).tolist())) if len(vertices) else ()
        material = str(body.get("material", DEFAULT_MATERIAL))
        key = (len(vertices), len(body["solid"][1]), extent, material)
        if key in keys:
            parts[keys[key]]["qty"] += 1
            continue
        keys[key] = len(parts)
        parts.append({"name": str(body.get("name", "Part")), "qty": 1, "material": material})
    return parts


def _drawing_view_circles(topology, view):
    """Circles and arcs whose axis points at the viewer, de-duplicated (visible wins)."""
    found = {}
    tolerance = max(topology["span"] * 1e-4, 1e-6)
    for kind, items in (("circle", topology["circles"]), ("arc", topology["arcs"])):
        for item in items:
            if abs(float(item["axis"] @ view["normal"])) < 0.999:
                continue
            u, v = float(item["center"] @ view["right"]), float(item["center"] @ view["up"])
            key = (kind, round(u / tolerance), round(v / tolerance),
                   round(item["radius"] / tolerance))
            if item.get("thread") is not None:          # a thread: drawn as its symbol
                visible = bool(view.get("thread_visible", {}).get(item["thread"], False))
            elif item.get("gear"):                      # a simplified gear's circles
                visible = True
            else:
                visible = bool(view["edge_visible"][item["edges"]].any()) \
                    if kind == "circle" else True
            if key not in found or (visible and not found[key]["visible"]):
                found[key] = {"kind": kind, "u": u, "v": v, "radius": item["radius"],
                              "visible": visible, "edges": item.get("edges", []),
                              "mid": (float(item["mid"] @ view["right"]),
                                      float(item["mid"] @ view["up"])) if kind == "arc" else None}
    return sorted(found.values(), key=lambda c: (
        c["kind"], -c["radius"], 0.0 if c["mid"] is None else c["mid"][0] - c["mid"][1],
        c["u"], c["v"]))      # arcs: the one facing up-left first (dimension lines sit right / below)


def _drawing_cluster(values, tolerance):
    clustered = []
    for value in sorted(values):
        if not clustered or value - clustered[-1] > tolerance:
            clustered.append(value)
    return clustered


def _drawing_axis_values(view, circles, topology, segment_sets):
    """Dimension coordinates of one view: outline, straight edges and circle centres.

    Rounded surfaces (silhouettes of cylinders, fillets) never contribute: a hole is
    dimensioned by its diameter and its centre, a fillet by its radius."""
    low, high = view["bounds"]
    tolerance = max(topology["span"] * 1e-4, 1e-6)
    circle_edges = {e for c in topology["circles"] for e in c["edges"]}
    us, vs = [low[0], high[0]], [low[1], high[1]]
    for segments, edge_ids in segment_sets:
        if not len(segments):
            continue
        keep = (edge_ids < 0) | topology["sharp"][np.maximum(edge_ids, 0)]
        if circle_edges:
            keep &= ~np.isin(edge_ids, list(circle_edges))
        segments = segments[keep]
        du = np.abs(segments[:, 1, 0] - segments[:, 0, 0])
        dv = np.abs(segments[:, 1, 1] - segments[:, 0, 1])
        us += segments[(du <= tolerance) & (dv > tolerance), 0, 0].tolist()
        vs += segments[(dv <= tolerance) & (du > tolerance), 0, 1].tolist()
    for circle in circles:
        if circle["kind"] == "circle":
            us.append(circle["u"])
            vs.append(circle["v"])
    return (_drawing_cluster([min(max(x, low[0]), high[0]) for x in us], tolerance),
            _drawing_cluster([min(max(y, low[1]), high[1]) for y in vs], tolerance))


def _drawing_nice_scale(page_units_per_mm):
    ratio = page_units_per_mm / DRAWING_UNITS_PER_MM
    for scale in DRAWING_STD_SCALES:
        if scale <= ratio * (1 + 1e-9):
            return scale * DRAWING_UNITS_PER_MM
    return DRAWING_STD_SCALES[-1] * DRAWING_UNITS_PER_MM


def _drawing_scale_text(page_units_per_mm):
    ratio = page_units_per_mm / DRAWING_UNITS_PER_MM
    return f"{ratio:g}:1" if ratio >= 1 else f"1:{1 / ratio:g}"


# units of the printed lengths (per sheet): the model is in mm; an inch sheet prints the lengths
# converted, a dual-unit sheet adds the other unit in brackets ("25 [0.984]")
DRAWING_UNITS = {"mm": ("mm", 1.0, 2), "inch": ("in", 1.0 / 25.4, 3)}   # label, factor, decimals
_DRAWING_UNITS = {"unit": "mm", "dual": False}


def _drawing_units_of(options):
    unit = options.get("unit") if options.get("unit") in DRAWING_UNITS else "mm"
    return {"unit": unit, "dual": bool(options.get("dual_units"))}


def _drawing_use_units(units):
    """Make `units` the printed units; returns the previous ones (to restore them)."""
    global _DRAWING_UNITS
    previous = _DRAWING_UNITS
    _DRAWING_UNITS = dict(units) if units else {"unit": "mm", "dual": False}
    return previous


def _drawing_other_unit():
    return "inch" if _DRAWING_UNITS["unit"] == "mm" else "mm"


def _drawing_unit_label():
    """Unit field of the title block: mm, in, mm [in] or in [mm]."""
    label = DRAWING_UNITS[_DRAWING_UNITS["unit"]][0]
    if _DRAWING_UNITS["dual"]:
        label += f" [{DRAWING_UNITS[_drawing_other_unit()][0]}]"
    return label


def _drawing_number(value, unit="mm"):
    """A length in mm printed in `unit` (no trailing zeros)."""
    _label, factor, places = DRAWING_UNITS[unit]
    return tol_plain(abs(float(value)) * factor, places)


def _drawing_fmt(value, convert=True):
    """A printed length (sheet unit, the second unit in brackets on a dual-unit sheet);
    convert=False: a plain number (angles, counts)."""
    if not convert:
        text = f"{abs(value):.2f}".rstrip("0").rstrip(".")
        return text or "0"
    text = _drawing_number(value, _DRAWING_UNITS["unit"])
    if _DRAWING_UNITS["dual"]:
        text += f" [{_drawing_number(value, _drawing_other_unit())}]"
    return text


def _drawing_dimension_value_text(dimension, prefix="", unit=""):
    """Printed value of an added dimension, with its tolerance (ISO 286 fit, deviations, limits),
    in the sheet's units; a reference (auxiliary) dimension is put in brackets."""
    value = float(dimension["value"])
    if unit == "°":                                        # angles are not converted
        text = tol_format_dimension(abs(value), dimension["tol"], prefix, unit) \
            if dimension.get("tol") else f"{prefix}{_drawing_fmt(value, False)}{unit}"
    else:
        _label, factor, places = DRAWING_UNITS[_DRAWING_UNITS["unit"]]
        text = tol_format_dimension(abs(value), dimension.get("tol"), prefix, "", factor, places)
        if _DRAWING_UNITS["dual"]:
            text += f" [{prefix}{_drawing_number(value, _drawing_other_unit())}]"
    return f"({text})" if dimension.get("reference") else text


def _drawing_prune(values, scale, metrics):
    """Drop coordinates whose dimension text would not fit between neighbours."""
    if len(values) < 3:
        return list(values)

    def fits(gap):
        return gap * scale >= metrics.horizontalAdvance(_drawing_fmt(gap)) + 12

    kept = [values[0]]
    for value in values[1:-1]:
        if fits(value - kept[-1]):
            kept.append(value)
    while len(kept) > 1 and not fits(values[-1] - kept[-1]):
        kept.pop()
    kept.append(values[-1])
    return kept


def _drawing_extras(values, reference, tolerance):
    """The outline start plus every coordinate not yet dimensioned in the reference view."""
    extras = [v for v in values[1:-1] if all(abs(v - r) > tolerance for r in reference)]
    return [values[0]] + extras if extras else []


DRAWING_BREAK_GAP = 24.0             # gap of a broken view on the sheet (6 mm)


def _drawing_clean_breaks(breaks, low, high):
    """Breaks of a view [{"axis": "u" / "v", "a", "b"}] inside its bounds, sorted, without overlaps:
    [{"k": 0 / 1, "a", "b"}]."""
    cleaned = []
    for item in breaks or ():
        try:
            k = 1 if item.get("axis") == "v" else 0
            a, b = sorted((float(item["a"]), float(item["b"])))
        except (KeyError, TypeError, ValueError, AttributeError):
            continue
        a, b = max(a, float(low[k])), min(b, float(high[k]))
        if b - a <= 1e-6 * max(float(high[k] - low[k]), 1e-9):
            continue
        if any(other["k"] == k and a < other["b"] and b > other["a"] for other in cleaned):
            continue
        cleaned.append({"k": k, "a": a, "b": b})
    return sorted(cleaned, key=lambda item: (item["k"], item["a"]))


def _drawing_break_map(point, breaks, scale):
    """View coordinates with the broken-out bands removed (the far side moved closer, the gap
    left between them); a point inside a band moves onto its edge."""
    mapped = [float(point[0]), float(point[1])]
    for item in breaks:
        k, value = item["k"], float(point[item["k"]])
        if value >= item["b"]:
            mapped[k] -= (item["b"] - item["a"]) - DRAWING_BREAK_GAP / scale
        elif value > item["a"]:
            mapped[k] -= value - item["a"]
    return mapped[0], mapped[1]


def _drawing_break_unmap(point, breaks, scale):
    """Inverse of _drawing_break_map (a point in a gap goes to the near band edge)."""
    real = [float(point[0]), float(point[1])]
    for item in sorted(breaks, key=lambda b: b["a"], reverse=True):
        k = item["k"]
        if real[k] >= item["a"] + DRAWING_BREAK_GAP / scale:
            real[k] += (item["b"] - item["a"]) - DRAWING_BREAK_GAP / scale
        elif real[k] > item["a"]:
            real[k] = item["a"] if real[k] - item["a"] < DRAWING_BREAK_GAP / scale / 2 else item["b"]
    return real[0], real[1]


def _drawing_break_segments(segments, breaks):
    """Segments (n, 2, 2) without their pieces inside the broken-out bands."""
    segments = np.asarray(segments, dtype=float).reshape(-1, 2, 2)
    for item in breaks:
        k, a, b = item["k"], item["a"], item["b"]
        if not len(segments):
            break
        x0, x1 = segments[:, 0, k], segments[:, 1, k]
        low, high = np.minimum(x0, x1), np.maximum(x0, x1)
        keep = [segments[(high <= a) | (low >= b)]]
        crossing = segments[~((high <= a) | (low >= b))]
        if len(crossing):
            c0, c1 = crossing[:, 0], crossing[:, 1]
            span = c1[:, k] - c0[:, k]
            safe = np.where(np.abs(span) < 1e-12, 1.0, span)

            def at(value):
                t = np.clip((value - c0[:, k]) / safe, 0.0, 1.0)[:, None]
                return c0 + (c1 - c0) * t
            first_low = np.where((c0[:, k] <= c1[:, k])[:, None], c0, c1)
            first_high = np.where((c0[:, k] <= c1[:, k])[:, None], c1, c0)
            below = np.minimum(c0[:, k], c1[:, k]) < a
            above = np.maximum(c0[:, k], c1[:, k]) > b
            moving = np.abs(span) >= 1e-12
            keep.append(np.stack((first_low, at(a)), axis=1)[below & moving])
            keep.append(np.stack((at(b), first_high), axis=1)[above & moving])
        segments = np.concatenate(keep) if keep else np.zeros((0, 2, 2))
    return segments


class _DrawingPlacement:
    """One projected view placed on the sheet (page units, v pointing up)."""

    def __init__(self, view, left, top, scale, bounds=None, breaks=None):
        self.view, self.scale = view, scale
        if bounds is not None:            # a detail view shows a part of its parent view
            self.low, self.high = (np.asarray(bounds[0], dtype=float), np.asarray(bounds[1], dtype=float))
        else:
            self.low, self.high = view["bounds"]
        # broken view (Phase 3): bands of the view left out, the rest moved together
        self.breaks = _drawing_clean_breaks(breaks, self.low, self.high)
        size = (self.high - self.low) * scale
        for item in self.breaks:
            size[item["k"]] -= (item["b"] - item["a"]) * scale - DRAWING_BREAK_GAP
        self.rect = QRectF(left, top, float(size[0]), float(size[1]))
        self.reserved = {"top": 0.0, "bottom": 0.0, "left": 0.0, "right": 0.0}
        self.hz, self.vt, self.circles = [], [], []
        self.centre_lines = []     # drawn centre lines [((u, v), (u, v))]: dimension references

    def add_centre_cross(self, u, v, radius):
        """Centre lines of a circle as drawn by _paint_centre_mark (2 mm beyond the contour)."""
        reach = radius + 9.0 / self.scale
        self.centre_lines += [((u - reach, v), (u + reach, v)), ((u, v - reach), (u, v + reach))]

    def point(self, u, v):
        if self.breaks:
            u, v = _drawing_break_map((u, v), self.breaks, self.scale)
        return QPointF(self.rect.left() + (u - self.low[0]) * self.scale,
                       self.rect.bottom() - (v - self.low[1]) * self.scale)

    def image_rect(self):
        center, extent = self.view["center"], self.view["extent"]
        top_left = self.point(center[0] - extent / 2, center[1] + extent / 2)
        return QRectF(top_left.x(), top_left.y(), extent * self.scale, extent * self.scale)


def _drawing_pen(width, pattern=None, role="dimension"):
    line_scale = _DRAWING_COLORS.get("line_scale")
    if line_scale:              # on screen: thin cosmetic lines, the same pixel width at any zoom
        width = max(1.0, width * line_scale)
    pen = QPen(_drawing_color(role), width, Qt.SolidLine, Qt.FlatCap, Qt.RoundJoin)
    if line_scale:
        pen.setCosmetic(True)
    if pattern:
        pen.setDashPattern(pattern)
    return pen


_DRAWING_CAP_RATIO = {}


_DRAWING_FONT_BASE = {}

def _drawing_font(height, bold=False):
    """Font whose capital letters are `height` page units high (DIN EN ISO 3098-0 lettering height)."""
    base = _DRAWING_FONT_BASE.get(bool(bold))
    if base is None:            # resolving the font family is slow (~10 ms): do it once
        font = QFont()
        if hasattr(font, "setFamilies"):
            font.setFamilies(list(DRAWING_FONT_FAMILIES))
        else:
            font.setFamily(DRAWING_FONT_FAMILIES[-1])
        font.setBold(bold)
        font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
        key = (QFontInfo(font).family(), bool(bold))
        ratio = _DRAWING_CAP_RATIO.get(key)
        if ratio is None:
            probe = QFont(font)
            probe.setPixelSize(100)
            ratio = QFontMetricsF(probe).capHeight() / 100.0
            ratio = _DRAWING_CAP_RATIO[key] = ratio if ratio > 0.3 else 0.716
        base = _DRAWING_FONT_BASE[bool(bold)] = (font, ratio)
    font, ratio = QFont(base[0]), base[1]
    font.setPixelSize(max(1, int(round(height / ratio))))
    return font


def _drawing_segments_path(place, segments):
    """Path of projected segments; built once per view and only transformed for each redraw.
    In a broken view the pieces inside the left-out bands are dropped and the rest moved."""
    if getattr(place, "breaks", None):
        path = QPainterPath()
        for (ax, ay), (bx, by) in _drawing_break_segments(segments, place.breaks).tolist():
            path.moveTo(place.point(ax, ay))
            path.lineTo(place.point(bx, by))
        return path
    cache = place.view.setdefault("_path_cache", {})
    entry = cache.get(id(segments))
    if entry is None or entry[0] is not segments:
        base = QPainterPath()
        last = None
        for (ax, ay), (bx, by) in np.asarray(segments, dtype=float).reshape(-1, 2, 2).tolist():
            # a segment going on from the previous one continues its line (no notches in curves
            # at the joints, dashes run on)
            if last is None or abs(ax - last[0]) > 1e-9 or abs(ay - last[1]) > 1e-9:
                base.moveTo(ax, -ay)
            base.lineTo(bx, -by)
            last = (bx, by)
        entry = cache[id(segments)] = (segments, base)
    s = place.scale
    return QTransform(s, 0.0, 0.0, s, place.rect.left() - place.low[0] * s,
                      place.rect.bottom() + place.low[1] * s).map(entry[1])


def _dimension_text_angle(vector):
    """Rotation of dimension text parallel to a line, readable from the bottom or the right."""
    angle = math.degrees(math.atan2(vector[1], vector[0]))
    if angle >= 90.0:
        angle -= 180.0
    elif angle < -90.0:
        angle += 180.0
    return angle


def _paint_aligned_dimension_text(painter, font, centre, vector, text, gap=4.0, ink=None):
    """Draw dimension text above a dimension line (aligned method); return its bounding rectangle."""
    metrics = QFontMetricsF(font)
    width = metrics.horizontalAdvance(text)
    angle = _dimension_text_angle(vector)
    painter.save()
    painter.translate(centre)
    painter.rotate(angle)
    painter.setFont(font)
    painter.setPen(_drawing_color("dimension") if ink is None else ink)
    painter.drawText(QPointF(-width / 2, -gap), text)
    painter.restore()
    cap = metrics.capHeight()
    box = QRectF(-width / 2 - 3, -gap - cap - 3, width + 6, cap + 6)
    return QTransform().translate(centre.x(), centre.y()).rotate(angle).mapRect(box)


def _paint_dimension_label(painter, font, midpoint, vector, normal, text, shift=0.0, lift=0.0,
                           scale=1.0, ink=None, leader_pen=None):
    """Aligned dimension text slid `shift` along the dimension line and `lift` away from it (page
    units * scale). Far from the line it is tied back by a thin leader; returns the text rectangle."""
    base = QPointF(midpoint.x() + vector[0] * shift * scale, midpoint.y() + vector[1] * shift * scale)
    position = QPointF(base.x() + normal[0] * lift * scale, base.y() + normal[1] * lift * scale)
    if abs(lift) > 28.0 and leader_pen is not None:
        painter.save()
        painter.setPen(leader_pen)
        painter.drawLine(base, position)
        painter.restore()
    return _paint_aligned_dimension_text(painter, font, position, vector, text,
                                         max(2.0, 4.0 * scale), ink)


def _paint_arrow(painter, tip, direction, length=14.0, ink=None):
    """Closed filled arrowhead (DIN 406-11 / ISO 129-1): 15° opening, about 3.5 mm long."""
    d = np.asarray(direction, dtype=float)
    d /= np.linalg.norm(d)
    half = length * math.tan(math.radians(7.5))
    base = QPointF(tip.x() - d[0] * length, tip.y() - d[1] * length)
    painter.save()
    painter.setPen(Qt.NoPen)
    painter.setBrush(_drawing_color("dimension") if ink is None else ink)
    painter.drawPolygon(QPolygonF([tip, QPointF(base.x() - d[1] * half, base.y() + d[0] * half),
                                   QPointF(base.x() + d[1] * half, base.y() - d[0] * half)]))
    painter.restore()


def _drawing_length_frame(first, second, dimension):
    """Dimension line of a length dimension between two page points: (start, end, direction,
    normal, distance). Aligned (default) or horizontal / vertical ("orient" "h" / "v": the
    projected distance, extension lines of different length); None for a zero length."""
    f, s = np.asarray(first, dtype=float), np.asarray(second, dtype=float)
    legacy = np.asarray(dimension.get("offset", (0.0, 0.0)), dtype=float)
    orient = dimension.get("orient")
    if orient in ("h", "v"):
        axis = 0 if orient == "h" else 1
        delta = float(s[axis] - f[axis])
        if abs(delta) <= 1e-9:
            return None
        vector = np.zeros(2)
        vector[axis] = 1.0 if delta > 0 else -1.0
        normal = np.array((-vector[1], vector[0]))
        distance = float(dimension.get("offset_distance", DRAWING_DIM_OFFSET + legacy @ normal))
        level = (max if distance >= 0 else min)(float(f @ normal), float(s @ normal)) + distance
        return (f + normal * (level - float(f @ normal)), s + normal * (level - float(s @ normal)),
                vector, normal, distance)
    vector = s - f
    length = float(np.linalg.norm(vector))
    if length <= 1e-9:
        return None
    vector = vector / length
    normal = np.array((-vector[1], vector[0]))
    distance = float(dimension.get("offset_distance", DRAWING_DIM_OFFSET + legacy @ normal))
    return f + normal * distance, s + normal * distance, vector, normal, distance


def _drawing_chamfer_values(a, b):
    """Leg length and angle (≤ 45°, to the nearer axis of the view) of a chamfer edge a-b."""
    du, dv = abs(float(b[0] - a[0])), abs(float(b[1] - a[1]))
    if du < 1e-9 and dv < 1e-9:
        return 0.0, 0.0
    if du >= dv:          # the edge leans toward the horizontal: its horizontal leg and angle
        return du, math.degrees(math.atan2(dv, du))
    return dv, math.degrees(math.atan2(du, dv))


def _drawing_chamfer_text(dimension):
    """'2 × 45°' (DIN ISO 129: length × angle); a reference chamfer in brackets."""
    angle = float(dimension.get("chamfer_angle", 45.0))
    leg = _drawing_dimension_value_text(dict(dimension, reference=False))
    text = f"{leg} × {round(angle * 2) / 2:g}°"
    return f"({text})" if dimension.get("reference") else text


def _paint_extra_dimension(painter, dimension, to_page, unit, pen, ink, font, background):
    """Chamfer (leader to 'length × angle'), arc length (concentric arc with '⌒ value') and
    ordinate (a line from the point to its coordinate) dimensions. `to_page` maps view
    coordinates to painter coordinates, sizes are page units * `unit`. Returns the text box."""
    kind = dimension.get("type")
    points = dimension.get("points") or []
    metrics = QFontMetricsF(font)
    painter.save()
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)
    painter.setFont(font)
    arrow_length = max(5.0, 14.0 * unit)

    def label(text, centre):
        width = metrics.horizontalAdvance(text) + 8.0 * unit
        height = metrics.height() + 4.0 * unit
        rect = QRectF(centre.x() - width / 2, centre.y() - height / 2, width, height)
        if background is not None:
            painter.fillRect(rect, background)
        painter.setPen(ink)
        painter.drawText(rect, Qt.AlignCenter, text)
        painter.setPen(pen)
        return rect

    try:
        if kind == "chamfer" and len(points) >= 2:
            a, b = to_page(*points[0]), to_page(*points[1])
            middle = QPointF((a.x() + b.x()) / 2, (a.y() + b.y()) / 2)
            offset = dimension.get("text_offset") or (60.0, -50.0)
            target = QPointF(middle.x() + offset[0] * unit, middle.y() + offset[1] * unit)
            text = _drawing_chamfer_text(dimension)
            width = metrics.horizontalAdvance(text) + 8.0 * unit
            # leader to a shelf under the text (DIN ISO 129-1 chamfer callout)
            shelf = QPointF(target.x() + (width if target.x() >= middle.x() else -width), target.y())
            painter.drawLine(middle, target)
            painter.drawLine(target, shelf)
            direction = np.array((middle.x() - target.x(), middle.y() - target.y()))
            if float(np.linalg.norm(direction)) > 1.2 * arrow_length:
                _paint_arrow(painter, middle, direction / float(np.linalg.norm(direction)),
                             arrow_length, ink)
            painter.setPen(ink)
            left = min(target.x(), shelf.x()) + 4.0 * unit
            painter.drawText(QPointF(left, target.y() - 3.0 * unit - metrics.descent()), text)
            return QRectF(min(target.x(), shelf.x()), target.y() - metrics.height() - 4 * unit,
                          width, metrics.height() + 6 * unit)
        if kind == "arc" and len(points) >= 3:
            centre, start, end = (to_page(*point) for point in points[:3])
            angle_a = math.degrees(math.atan2(centre.y() - start.y(), start.x() - centre.x()))
            angle_b = math.degrees(math.atan2(centre.y() - end.y(), end.x() - centre.x()))
            sweep = (angle_b - angle_a) % 360.0
            if dimension.get("sweep_negative"):
                sweep -= 360.0
            radius = math.hypot(start.x() - centre.x(), start.y() - centre.y())
            dimension_radius = float(dimension["offset_distance"]) * unit \
                if "offset_distance" in dimension else radius + 24.0 * unit
            # extension lines along the radius from the arc ends, the dimension arc with arrows
            for angle in (angle_a, angle_a + sweep):
                t = math.radians(angle)
                inner = radius + (8.0 * unit if dimension_radius > radius else -8.0 * unit)
                outer = dimension_radius + (8.0 * unit if dimension_radius > radius else -8.0 * unit)
                painter.drawLine(QPointF(centre.x() + math.cos(t) * inner, centre.y() - math.sin(t) * inner),
                                 QPointF(centre.x() + math.cos(t) * outer, centre.y() - math.sin(t) * outer))
            painter.drawArc(QRectF(centre.x() - dimension_radius, centre.y() - dimension_radius,
                                   2 * dimension_radius, 2 * dimension_radius),
                            int(angle_a * 16), int(sweep * 16))
            direction_sign = 1.0 if sweep >= 0 else -1.0
            for end_angle, outward in ((angle_a, 1.0), (angle_a + sweep, -1.0)):
                t = math.radians(end_angle)
                _paint_arrow(painter, QPointF(centre.x() + math.cos(t) * dimension_radius,
                                              centre.y() - math.sin(t) * dimension_radius),
                             (outward * direction_sign * math.sin(t), outward * direction_sign * math.cos(t)),
                             arrow_length, ink)
            middle = math.radians(angle_a + sweep / 2)
            text = _drawing_dimension_value_text(dimension, "⌒")
            reach = dimension_radius + metrics.height() * 0.9
            offset = dimension.get("text_offset") or (0.0, 0.0)
            anchor = QPointF(centre.x() + math.cos(middle) * reach + offset[0] * unit,
                             centre.y() - math.sin(middle) * reach + offset[1] * unit)
            return label(text, anchor)
        if kind == "ordinate" and len(points) >= 2:
            origin, point = to_page(*points[0]), to_page(*points[1])
            horizontal = dimension.get("axis", "x") == "x"     # an x coordinate: a vertical line
            level = float(dimension.get("level", 40.0)) * unit
            if horizontal:
                end = QPointF(point.x(), origin.y() + level)
                gap = 8.0 * unit if end.y() > point.y() else -8.0 * unit
                start = QPointF(point.x(), point.y() + gap)
            else:
                end = QPointF(origin.x() + level, point.y())
                gap = 8.0 * unit if end.x() > point.x() else -8.0 * unit
                start = QPointF(point.x() + gap, point.y())
            if math.hypot(end.x() - start.x(), end.y() - start.y()) > 2 * unit:
                painter.drawLine(start, end)
            text = _drawing_dimension_value_text(dimension)
            width = metrics.horizontalAdvance(text)
            painter.setPen(ink)
            if horizontal:         # the number continues the line, readable from the right
                painter.save()
                painter.translate(end)
                painter.rotate(-90)
                down = level >= 0
                x0 = -width - 4.0 * unit if down else 4.0 * unit
                painter.drawText(QPointF(x0, metrics.ascent() / 2 - metrics.descent() / 2), text)
                painter.restore()
                return QRectF(end.x() - metrics.height() / 2, end.y() + (0 if down else -width - 4 * unit),
                              metrics.height(), width + 4 * unit)
            left = level < 0
            x0 = end.x() - width - 4.0 * unit if left else end.x() + 4.0 * unit
            painter.drawText(QPointF(x0, end.y() + metrics.ascent() / 2 - metrics.descent() / 2), text)
            return QRectF(x0, end.y() - metrics.height() / 2, width, metrics.height())
        return None
    finally:
        painter.restore()


def _paint_radial_dimension(painter, center, edge, text, diameter, scale, ink, background,
                            font, line_width, text_offset=(0.0, 0.0), leader_length=16.0):
    """Radius: arrow on the arc and a leader outwards (no line to the centre); diameter: line through
    the centre. The leader's length (`leader_length` page units) and direction are draggable."""
    direction = np.array((edge.x() - center.x(), edge.y() - center.y()), dtype=float)
    radius = float(np.linalg.norm(direction))
    if radius <= 1e-12:
        return QRectF()
    direction /= radius
    opposite = QPointF(center.x() - direction[0] * radius,
                       center.y() - direction[1] * radius)
    painter.setPen(QPen(ink, line_width))
    painter.setBrush(Qt.NoBrush)
    arrow_length = 14.0 * scale
    if diameter:
        painter.drawLine(opposite, edge)
        arrow_points = ((opposite, -direction), (edge, direction))
        leader = max(4.0 * scale, float(leader_length) * scale)
    else:
        arrow_points = ((edge, -direction),)
        leader = max(arrow_length + 2.0 * scale, float(leader_length) * scale)

    for tip, arrow_direction in arrow_points:
        _paint_arrow(painter, tip, arrow_direction, arrow_length, ink)
    shoulder = QPointF(edge.x() + direction[0] * leader, edge.y() + direction[1] * leader)
    metrics = QFontMetricsF(font)
    text_width = metrics.horizontalAdvance(text) + 6.0 * scale
    sign = 1.0 if direction[0] >= 0 else -1.0
    shelf = QPointF(shoulder.x() + sign * text_width, shoulder.y())
    painter.setPen(QPen(ink, line_width))
    painter.setBrush(Qt.NoBrush)
    painter.drawLine(edge, shoulder)
    painter.drawLine(shoulder, shelf)
    label_rect = QRectF(min(shoulder.x(), shelf.x()),
                        shoulder.y() - metrics.height() - 1.0 * scale,
                        text_width, metrics.height())
    text_offset = np.asarray(text_offset, dtype=float)
    label_rect.translate(float(text_offset[0]), float(text_offset[1]))
    text_anchor = QPointF(min(max(shelf.x(), label_rect.left()), label_rect.right()),
                          min(max(shelf.y(), label_rect.top()), label_rect.bottom()))
    if float(np.linalg.norm(text_offset)) > 1e-6:
        painter.setPen(QPen(ink, line_width))
        painter.drawLine(shelf, text_anchor)
    painter.fillRect(label_rect, background)
    painter.setFont(font)
    painter.setPen(ink)
    painter.drawText(label_rect, Qt.AlignCenter, text)

    return label_rect


def _paint_gdt_symbol(painter, key, rect):
    """ISO 1101 characteristic symbol drawn with lines inside the square `rect`."""
    h = rect.height()
    c = rect.center()
    cx, cy = c.x(), c.y()

    def line(x0, y0, x1, y1):
        painter.drawLine(QPointF(cx + x0 * h, cy + y0 * h), QPointF(cx + x1 * h, cy + y1 * h))

    def circle(radius, dx=0.0, dy=0.0):
        painter.drawEllipse(QPointF(cx + dx * h, cy + dy * h), radius * h, radius * h)

    def arrow(x0, y0, x1, y1):
        line(x0, y0, x1, y1)
        _paint_arrow(painter, QPointF(cx + x1 * h, cy + y1 * h), (x1 - x0, y1 - y0), 0.22 * h)

    painter.setBrush(Qt.NoBrush)
    if key == "straightness":
        line(-0.3, 0, 0.3, 0)
    elif key == "flatness":
        painter.drawPolyline(QPolygonF([QPointF(cx + x * h, cy + y * h) for x, y in (
            (-0.32, 0.15), (-0.12, -0.15), (0.32, -0.15), (0.12, 0.15), (-0.32, 0.15))]))
    elif key == "circularity":
        circle(0.25)
    elif key == "cylindricity":
        circle(0.17)
        line(-0.36, 0.27, -0.12, -0.27)
        line(0.12, 0.27, 0.36, -0.27)
    elif key in ("profile_line", "profile_surface"):
        painter.drawArc(QRectF(cx - 0.3 * h, cy - 0.2 * h, 0.6 * h, 0.6 * h), 0, 180 * 16)
        if key == "profile_surface":
            line(-0.3, 0.1, 0.3, 0.1)
    elif key == "parallelism":
        line(-0.3, 0.25, -0.05, -0.25)
        line(0.05, 0.25, 0.3, -0.25)
    elif key == "perpendicularity":
        line(0, -0.28, 0, 0.28)
        line(-0.3, 0.28, 0.3, 0.28)
    elif key == "angularity":
        line(-0.3, 0.25, 0.3, 0.25)
        line(-0.3, 0.25, 0.15, -0.28)
    elif key == "position":
        circle(0.2)
        line(-0.33, 0, 0.33, 0)
        line(0, -0.33, 0, 0.33)
    elif key == "concentricity":
        circle(0.12)
        circle(0.25)
    elif key == "symmetry":
        line(-0.25, -0.16, 0.25, -0.16)
        line(-0.33, 0, 0.33, 0)
        line(-0.25, 0.16, 0.25, 0.16)
    elif key == "runout":
        arrow(-0.25, 0.28, 0.25, -0.22)
    elif key == "total_runout":
        arrow(-0.3, 0.28, 0.1, -0.18)
        arrow(-0.05, 0.28, 0.35, -0.18)


def _paint_weld_symbol(painter, kind, x, y, size, side):
    """Weld symbol centred at x on the reference line y; side +1 = below it (arrow side), −1 above."""
    s, d = size, float(side)

    def point(px, py):
        return QPointF(x + px * s, y + py * s * d)

    painter.setBrush(Qt.NoBrush)
    if kind == "fillet":
        painter.drawPolyline(QPolygonF([point(-0.5, 0), point(-0.5, 1), point(0.5, 0), point(-0.5, 0)]))
    elif kind == "square":
        painter.drawLine(point(-0.12, 0), point(-0.12, 1))
        painter.drawLine(point(0.12, 0), point(0.12, 1))
    elif kind == "v":
        painter.drawPolyline(QPolygonF([point(-0.5, 0), point(0, 1), point(0.5, 0)]))
    elif kind == "bevel":
        painter.drawPolyline(QPolygonF([point(-0.25, 0), point(-0.25, 1), point(0.5, 0)]))
    elif kind == "u":
        painter.drawLine(point(-0.5, 0), point(-0.5, 0.5))
        painter.drawLine(point(0.5, 0.5), point(0.5, 0))
        painter.drawArc(QRectF(x - 0.5 * s, y if d > 0 else y - s, s, s),
                        (180 if d > 0 else 0) * 16, 180 * 16)
    elif kind == "plug":
        painter.drawPolyline(QPolygonF([point(-0.5, 0), point(-0.5, 0.7), point(0.5, 0.7),
                                        point(0.5, 0)]))


DRAWING_DEPTH, DRAWING_CBORE, DRAWING_CSK = "↧", "⌴", "⌵"      # ISO 129-1 / ASME Y14.5 symbols


def _drawing_callout_lines(ann):
    """Text lines of a hole or thread callout in the sheet's units ('4× Ø6.6 THRU',
    '⌴ Ø11 ↧6.8', 'M8-6H ↧16')."""
    count = f"{ann['count']}× " if ann.get("count", 1) > 1 else ""
    if ann["kind"] == "hole":
        head = f"{count}Ø{_drawing_fmt(ann['d'])}"
        head += " THRU" if ann["through"] else f" {DRAWING_DEPTH}{_drawing_fmt(ann['depth'])}"
        lines = [head]
        if ann.get("cbore"):
            lines.append(f"{DRAWING_CBORE} Ø{_drawing_fmt(ann['cbore'][0])} "
                         f"{DRAWING_DEPTH}{_drawing_fmt(ann['cbore'][1])}")
        if ann.get("csk"):
            lines.append(f"{DRAWING_CSK} Ø{_drawing_fmt(ann['csk'][0])} × {ann['csk'][1]:g}°")
        return lines
    text = count + (ann["label_pitch"] if ann.get("show_pitch") else ann["label"])
    if ann.get("cls"):
        text += f"-{ann['cls']}"
    if ann.get("hand") == "left":                       # ISO 965 / ASME: left-hand marking
        text += "-LH"
    if ann.get("internal"):
        if ann.get("through"):
            text += " THRU"
        elif ann.get("length", 0.0) > 0:
            text += f" {DRAWING_DEPTH}{_drawing_fmt(ann['length'])}"
    return [text]


def _paint_leader_text(painter, lines, tip, anchor, u, pen, ink, font, leader=True, frame=False):
    """Text lines on a shelf at `anchor`, tied to `tip` by a leader with an arrow (hole / thread
    callouts, notes); without a leader the text block's top left corner is `anchor`. Returns
    its bounding rectangle."""
    metrics = QFontMetricsF(font)
    lines = [line for line in lines] or [""]
    width = max(metrics.horizontalAdvance(line) for line in lines)
    step = metrics.height()
    painter.setFont(font)
    if not leader:
        box = QRectF(anchor.x(), anchor.y(), width + 0.8 * u, step * len(lines) + 0.5 * u)
        painter.setPen(ink)
        for index, line in enumerate(lines):
            painter.drawText(QPointF(box.left() + 0.4 * u, box.top() + 0.25 * u + metrics.ascent()
                                     + index * step), line)
        if frame:
            painter.setPen(pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawRect(box)
        return box
    right_side = anchor.x() >= tip.x()
    shelf_end = QPointF(anchor.x() + (1 if right_side else -1) * (width + 0.8 * u), anchor.y())
    left = min(anchor.x(), shelf_end.x()) + 0.4 * u
    direction = np.array((tip.x() - anchor.x(), tip.y() - anchor.y()), dtype=float)
    length = float(np.linalg.norm(direction))
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)
    if length > 1e-6:
        painter.drawLine(anchor, tip)
        arrow = max(5.0, u)
        if length > 1.2 * arrow:
            _paint_arrow(painter, tip, direction / length, arrow, ink)
    painter.drawLine(anchor, shelf_end)
    painter.setPen(ink)
    # the first line sits on the shelf, the others below it
    painter.drawText(QPointF(left, anchor.y() - 0.3 * u - metrics.descent()), lines[0])
    for index, line in enumerate(lines[1:]):
        painter.drawText(QPointF(left, anchor.y() + 0.3 * u + metrics.ascent() + index * step), line)
    box = QRectF(min(anchor.x(), shelf_end.x()), anchor.y() - step - 0.3 * u,
                 abs(shelf_end.x() - anchor.x()), step * len(lines) + 0.6 * u)
    if frame:
        painter.setPen(pen)
        painter.drawRect(box)
    return box


def _paint_annotation(painter, ann, tip, offset, unit, pen, ink, text_height=None):
    """One geometric tolerance frame, datum, surface finish or weld symbol: its leader ends at
    `tip` (an arrow on the feature), the frame / symbol sits at tip + offset. Sizes are page units
    * `unit` (1 on the sheet, the screen scale in the editor). Returns the bounding rectangle."""
    ann = tol_normalize_annotation(ann)
    if ann is None:
        return QRectF()
    u = (text_height or DRAWING_TEXT) * unit
    font = _drawing_font(max(6.0, u))
    metrics = QFontMetricsF(font)
    anchor = QPointF(tip.x() + offset[0], tip.y() + offset[1])
    arrow_length = max(5.0, 14.0 * unit)
    painter.save()
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)
    painter.setFont(font)
    kind = ann["kind"]
    bounds = QRectF(anchor, anchor)          # the symbol / text only, without its leader

    def leader(target, with_arrow=True):
        direction = np.array((tip.x() - target.x(), tip.y() - target.y()), dtype=float)
        length = float(np.linalg.norm(direction))
        if length < 1e-6:
            return
        painter.setPen(pen)
        painter.drawLine(target, tip)
        if with_arrow and length > arrow_length * 1.2:
            _paint_arrow(painter, tip, direction / length, arrow_length, ink)

    if kind == "gdt":
        h = 1.9 * u
        cells = [h]
        tol_text = ("Ø" if ann["diameter"] else "") + ann["tolerance"] + \
            (f" ({ann['modifier']})" if ann["modifier"] else "")
        cells.append(metrics.horizontalAdvance(tol_text) + 0.9 * u)
        cells += [h] * len(ann["datums"])
        width = sum(cells)
        left = anchor.x() if anchor.x() >= tip.x() else anchor.x() - width
        top = anchor.y() - h / 2
        frame = QRectF(left, top, width, h)
        side_point = QPointF(frame.left() if anchor.x() >= tip.x() else frame.right(), anchor.y())
        leader(side_point)
        painter.setPen(pen)
        painter.drawRect(frame)
        x = left
        for index, cell in enumerate(cells):
            if index:
                painter.drawLine(QPointF(x, top), QPointF(x, top + h))
            rect = QRectF(x, top, cell, h)
            painter.setPen(pen)
            if index == 0:
                _paint_gdt_symbol(painter, ann["symbol"], rect)
            else:
                painter.setPen(ink)
                painter.drawText(rect, Qt.AlignCenter,
                                 tol_text if index == 1 else ann["datums"][index - 2])
            x += cell
        bounds = bounds.united(frame)
    elif kind == "datum":
        h = 1.9 * u
        frame = QRectF(anchor.x() - h / 2, anchor.y() - h / 2, h, h)
        direction = np.array((frame.center().x() - tip.x(), frame.center().y() - tip.y()), dtype=float)
        length = float(np.linalg.norm(direction))
        if length > 1e-6:
            direction /= length
            normal = np.array((-direction[1], direction[0]))
            base_length = min(length, 1.1 * u + 0.0)
            base = QPointF(tip.x() + direction[0] * base_length, tip.y() + direction[1] * base_length)
            half = 0.45 * u
            painter.setPen(pen)
            painter.setBrush(ink)
            painter.drawPolygon(QPolygonF([tip, QPointF(base.x() + normal[0] * half, base.y() + normal[1] * half),
                                           QPointF(base.x() - normal[0] * half, base.y() - normal[1] * half)]))
            painter.setBrush(Qt.NoBrush)
            edge = QPointF(frame.center().x() - direction[0] * h / 2 * (1.0 if abs(direction[0]) >= abs(direction[1]) else 0.0),
                           frame.center().y() - direction[1] * h / 2 * (1.0 if abs(direction[1]) > abs(direction[0]) else 0.0))
            painter.drawLine(base, edge)
        painter.setPen(pen)
        painter.drawRect(frame)
        painter.setPen(ink)
        painter.drawText(frame, Qt.AlignCenter, ann["letter"])
        bounds = bounds.united(frame)
    elif kind == "surface":
        s = 1.5 * u
        far = math.hypot(offset[0], offset[1]) > 2.0 * s
        peak = QPointF(anchor.x(), anchor.y())
        long_leg = QPointF(peak.x() + 0.8 * s, peak.y() - 1.39 * s)
        short_leg = QPointF(peak.x() - 0.4 * s, peak.y() - 0.69 * s)
        text = ann["value"]
        bar_length = max(1.6 * s, metrics.horizontalAdvance(text) + 0.8 * u)
        bar_end = QPointF(long_leg.x() + bar_length, long_leg.y())
        if far:
            leader(peak)
        painter.setPen(pen)
        painter.drawLine(short_leg, peak)
        painter.drawLine(peak, long_leg)
        if ann["removal"] != "forbidden":
            painter.drawLine(long_leg, bar_end)
        else:
            painter.drawLine(long_leg, bar_end)
            painter.drawEllipse(QPointF(peak.x() + 0.2 * s, peak.y() - 0.75 * s), 0.45 * s, 0.45 * s)
        if ann["removal"] == "required":
            painter.drawLine(short_leg, QPointF(peak.x() + 0.4 * s, short_leg.y()))
        painter.setPen(ink)
        painter.drawText(QPointF(long_leg.x() + 0.3 * u, long_leg.y() - 0.25 * u), text)
        extras = "  ".join(item for item in (ann["lay"], ann["allowance"]) if item)
        if extras:
            painter.drawText(QPointF(long_leg.x() + 0.3 * u, long_leg.y() + 1.2 * u), extras)
        bounds = bounds.united(QRectF(short_leg.x(), long_leg.y() - 1.6 * s,
                                      bar_end.x() - short_leg.x(), 3.2 * s))
    elif kind in ("note", "hole", "thread"):
        lines = ann["text"].splitlines() if kind == "note" else _drawing_callout_lines(ann)
        leader_on = kind != "note" or ann["leader"]
        box = _paint_leader_text(painter, lines, tip, anchor, u, pen, ink, font, leader=leader_on,
                                 frame=kind == "note" and ann["frame"])
        bounds = bounds.united(box)
    elif kind == "balloon":
        number = str(ann["item"])
        big = _drawing_font(max(6.0, 1.4 * u))
        radius = max(1.25 * u, QFontMetricsF(big).horizontalAdvance(number) / 2 + 0.4 * u)
        direction = np.array((tip.x() - anchor.x(), tip.y() - anchor.y()), dtype=float)
        length = float(np.linalg.norm(direction))
        painter.setPen(pen)
        if length > radius + 1e-6:
            direction /= length
            start = QPointF(anchor.x() + direction[0] * radius, anchor.y() + direction[1] * radius)
            painter.drawLine(start, tip)
            painter.setBrush(ink)                    # ISO 6433: a dot where the leader ends on the part
            painter.drawEllipse(tip, 0.22 * u, 0.22 * u)
            painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(anchor, radius, radius)
        painter.setFont(big)
        painter.setPen(ink)
        circle = QRectF(anchor.x() - radius, anchor.y() - radius, 2 * radius, 2 * radius)
        painter.drawText(circle, Qt.AlignCenter, number)
        bounds = bounds.united(circle)
    else:
        s = 0.95 * u
        direction = 1.0 if offset[0] >= 0 else -1.0
        symbols = [ann["type"], ann["other"]]
        text_width = max([metrics.horizontalAdvance(ann["tail"]) + u] + [0.0])
        line_length = max(8.0 * s + (text_width if ann["tail"] else 0.0), 6.0 * s)
        end = QPointF(anchor.x() + direction * line_length, anchor.y())
        leader(anchor)
        painter.setPen(pen)
        painter.drawLine(anchor, end)
        centre_x = anchor.x() + direction * 3.2 * s
        painter.setPen(pen)
        if symbols[0]:
            _paint_weld_symbol(painter, symbols[0], centre_x, anchor.y(), s, 1)
        if symbols[1]:
            _paint_weld_symbol(painter, symbols[1], centre_x, anchor.y(), s, -1)
        painter.setPen(ink)
        if ann["size"]:
            width = metrics.horizontalAdvance(ann["size"])
            painter.drawText(QPointF(centre_x - direction * (0.7 * s) - (width if direction > 0 else 0.0),
                                     anchor.y() + 1.1 * s), ann["size"])
        if ann["tail"]:
            painter.drawText(QPointF(end.x() + (0.3 * s if direction > 0 else -0.3 * s -
                                                metrics.horizontalAdvance(ann["tail"])),
                                     anchor.y() + 0.35 * s), ann["tail"])
        painter.setPen(pen)
        if ann["all_around"]:
            painter.drawEllipse(anchor, 0.5 * s, 0.5 * s)
        if ann["field"]:
            painter.setBrush(ink)
            painter.drawPolygon(QPolygonF([anchor, QPointF(anchor.x(), anchor.y() - 1.6 * s),
                                           QPointF(anchor.x() + direction * 1.1 * s, anchor.y() - 1.2 * s)]))
        bounds = bounds.united(QRectF(min(anchor.x(), end.x()), anchor.y() - 1.8 * s,
                                      abs(end.x() - anchor.x()), 3.6 * s))
    painter.restore()
    return bounds.adjusted(-4 * unit, -4 * unit, 4 * unit, 4 * unit)


def _paint_hz_dimension(painter, metrics, x0, x1, y, edge_y, sign, text):
    painter.setPen(_drawing_pen(DRAWING_THIN))
    for x in (x0, x1):
        painter.drawLine(QPointF(x, edge_y + sign * 4), QPointF(x, y + sign * 7))
    painter.drawLine(QPointF(x0, y), QPointF(x1, y))
    if x1 - x0 >= 32:
        _paint_arrow(painter, QPointF(x0, y), (-1, 0))
        _paint_arrow(painter, QPointF(x1, y), (1, 0))
    else:
        painter.drawLine(QPointF(x0 - 16, y), QPointF(x0, y))
        painter.drawLine(QPointF(x1, y), QPointF(x1 + 16, y))
        _paint_arrow(painter, QPointF(x0, y), (1, 0))
        _paint_arrow(painter, QPointF(x1, y), (-1, 0))
    painter.setPen(_drawing_pen(1))
    painter.drawText(QPointF((x0 + x1) / 2 - metrics.horizontalAdvance(text) / 2, y - 4), text)


def _paint_vt_dimension(painter, metrics, y0, y1, x, edge_x, sign, text):
    painter.setPen(_drawing_pen(DRAWING_THIN))
    for y in (y0, y1):
        painter.drawLine(QPointF(edge_x + sign * 4, y), QPointF(x + sign * 7, y))
    painter.drawLine(QPointF(x, y0), QPointF(x, y1))
    top, bottom = min(y0, y1), max(y0, y1)
    if bottom - top >= 32:
        _paint_arrow(painter, QPointF(x, top), (0, -1))
        _paint_arrow(painter, QPointF(x, bottom), (0, 1))
    else:
        painter.drawLine(QPointF(x, top - 16), QPointF(x, top))
        painter.drawLine(QPointF(x, bottom), QPointF(x, bottom + 16))
        _paint_arrow(painter, QPointF(x, top), (0, 1))
        _paint_arrow(painter, QPointF(x, bottom), (0, -1))
    painter.setPen(_drawing_pen(1))
    painter.save()
    painter.translate(x, (y0 + y1) / 2)
    painter.rotate(-90)
    painter.drawText(QPointF(-metrics.horizontalAdvance(text) / 2, -4), text)
    painter.restore()


def _paint_chain(painter, metrics, place, values, side, overall=True):
    """Chain dimension of consecutive coordinates, plus the overall dimension if wanted."""
    if len(values) < 2:
        return
    sign = 1 if side in ("bottom", "right") else -1
    level = place.reserved[side] + DRAWING_DIM_OFFSET
    horizontal = side in ("top", "bottom")
    if horizontal:
        positions = [place.point(v, place.low[1]).x() for v in values]
        edge = place.rect.bottom() if side == "bottom" else place.rect.top()
        paint = _paint_hz_dimension
    else:
        positions = [place.point(place.low[0], v).y() for v in values]
        edge = place.rect.right() if side == "right" else place.rect.left()
        paint = _paint_vt_dimension
    if len(values) > 2 or not overall:
        # with an overall dimension the last step is omitted (no closed dimension chains)
        steps = len(values) - 1 - (1 if overall else 0)
        for i in range(steps):
            paint(painter, metrics, positions[i], positions[i + 1], edge + sign * level,
                  edge, sign, _drawing_fmt(values[i + 1] - values[i]))
        if overall and steps:
            level += 28
    if overall:
        paint(painter, metrics, positions[0], positions[-1], edge + sign * level, edge, sign,
              _drawing_fmt(values[-1] - values[0]))
    place.reserved[side] = level + 12


def _paint_centre_mark(painter, centre, radius):
    """Thin chain centre lines crossing a circle, 2 mm beyond its contour (DIN ISO 128-24)."""
    reach = radius + 9
    painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
    painter.drawLine(QPointF(centre.x() - reach, centre.y()), QPointF(centre.x() + reach, centre.y()))
    painter.drawLine(QPointF(centre.x(), centre.y() - reach), QPointF(centre.x(), centre.y() + reach))


def _paint_circles(painter, metrics, place, topology=None):
    """Centre lines of circles; Ø leaders for circles and R leaders for arcs, grouped by size.
    With the part's `topology` a hole's leader also says THRU or its depth, and a counterbore or
    countersink at its entry on the lines below (hole callout, ISO 129-1)."""
    tolerance = max(place.view["extent"] * 1e-4, 1e-6)
    counts = collections.Counter((c["kind"], round(c["radius"] / tolerance)) for c in place.circles)
    done = set()
    quadrants = ((1, -1), (-1, -1), (1, 1), (-1, 1))
    for circle in place.circles:
        centre = place.point(circle["u"], circle["v"])
        radius = circle["radius"] * place.scale
        if circle["kind"] == "circle":
            _paint_centre_mark(painter, centre, radius)
        key = (circle["kind"], round(circle["radius"] / tolerance))
        if key in done:
            continue
        done.add(key)
        if circle["kind"] == "arc":
            direction = np.array((circle["mid"][0], -circle["mid"][1]), dtype=float)
            direction /= np.linalg.norm(direction)
            prefix, value = "R", circle["radius"]
        else:
            direction = np.asarray(quadrants[(len(done) - 1) % 4], dtype=float) / math.sqrt(2)
            prefix, value = "Ø", 2 * circle["radius"]
        start = QPointF(centre.x() + direction[0] * radius, centre.y() + direction[1] * radius)
        knee = QPointF(start.x() + direction[0] * 30, start.y() + direction[1] * 30)
        text = ("" if counts[key] == 1 else f"{counts[key]}× ") + prefix + _drawing_fmt(value)
        below = []
        if circle["kind"] == "circle" and topology is not None and "normal" in place.view:
            # the leader stands for every circle of this size: only what they all share is added
            found = []
            for other in place.circles:
                if (other["kind"], round(other["radius"] / tolerance)) != key:
                    continue
                hole = _drawing_hole_at(topology, place.view, (other["u"], other["v"]), tolerance)
                found.append(hole if hole is not None and
                             abs(hole["d"] - value) <= max(1e-3 * value, 1e-6) else None)
            if found and all(hole is not None for hole in found):
                lines = _drawing_callout_lines(dict(found[0], kind="hole", count=1))
                if len({_drawing_hole_signature(hole) for hole in found}) == 1:
                    text += lines[0][len("Ø" + _drawing_fmt(found[0]["d"])):]
                    below = lines[1:]
                elif len({(hole["through"], round(hole["depth"], 2)) for hole in found}) == 1:
                    text += lines[0][len("Ø" + _drawing_fmt(found[0]["d"])):]
        width = max([metrics.horizontalAdvance(text)] + [metrics.horizontalAdvance(line) for line in below])
        side = 1 if direction[0] >= 0 else -1
        shelf = QPointF(knee.x() + side * (width + 8), knee.y())
        painter.setPen(_drawing_pen(DRAWING_THIN))
        painter.drawLine(start, knee)
        painter.drawLine(knee, shelf)
        _paint_arrow(painter, start, -direction)
        painter.setPen(_drawing_pen(1))
        left = knee.x() + (4 if side > 0 else -width - 4)
        painter.drawText(QPointF(left, knee.y() - 4), text)
        for index, line in enumerate(below):
            painter.drawText(QPointF(left, knee.y() + 4 + metrics.ascent() + index * metrics.height()), line)


def _drawing_cut_sides(place, cut_normal):
    """Sides of a view where the section plane trace ends (None if it is not edge-on)."""
    view = place.view
    if abs(float(cut_normal @ view["normal"])) > 0.5:
        return None
    vertical = abs(float(cut_normal @ view["right"])) >= abs(float(cut_normal @ view["up"]))
    return ("top", "bottom") if vertical else ("left", "right")


def _drawing_cut_trace(right, up, low, high, cut_normal, offset, margin=0.0):
    """End points (view u, v) of the trace of the section plane (cut_normal · p = offset) across a
    view with the axes right / up and the bounds low / high, `margin` beyond the bounds; None
    if the plane is not seen edge-on in that view."""
    cut_normal = np.asarray(cut_normal, dtype=float)
    cr, cu = float(cut_normal @ np.asarray(right)), float(cut_normal @ np.asarray(up))
    if cr * cr + cu * cu < 0.75:                    # the plane faces the viewer
        return None
    if abs(cr) >= abs(cu):                          # a (near) vertical line
        return [((offset - v * cu) / cr, v) for v in (low[1] - margin, high[1] + margin)]
    return [(u, (offset - u * cr) / cu) for u in (low[0] - margin, high[0] + margin)]


def _paint_cut_line(painter, metrics, place, cut_normal, letter, offset=0.0):
    """Cutting plane (DIN ISO 128-40) at its offset: thin chain line, thick end strokes, sight
    arrows."""
    view = place.view
    sides = _drawing_cut_sides(place, cut_normal)
    if sides is None:
        return
    cr, cu = float(cut_normal @ view["right"]), float(cut_normal @ view["up"])
    trace = _drawing_cut_trace(view["right"], view["up"], place.low, place.high, cut_normal,
                               offset, 24 / place.scale)
    if trace is None:
        return
    ends = tuple(place.point(u, v) for u, v in trace)
    sight = np.array((-cr, cu), dtype=float)
    sight /= np.linalg.norm(sight)
    along = np.array((ends[0].x() - ends[1].x(), ends[0].y() - ends[1].y()))
    along /= np.linalg.norm(along)
    painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
    painter.drawLine(*ends)
    for end, inward in ((ends[0], -along), (ends[1], along)):
        stroke = QPointF(end.x() + inward[0] * 30, end.y() + inward[1] * 30)
        painter.setPen(_drawing_pen(DRAWING_THICK, role="centre"))
        painter.drawLine(end, stroke)
        tip = QPointF(end.x() + sight[0] * 34, end.y() + sight[1] * 34)
        painter.setPen(_drawing_pen(DRAWING_THIN, role="centre"))
        painter.drawLine(end, tip)
        _paint_arrow(painter, tip, sight, ink=_drawing_color("centre"))
        painter.setPen(_drawing_pen(1, role="centre"))
        painter.drawText(QPointF(tip.x() + sight[0] * 18 - metrics.horizontalAdvance(letter) / 2,
                                 tip.y() + sight[1] * 18 + 6), letter)


# section hatching by material (DIN ISO 128-50 general hatching; DIN 201 style variants):
# (title, [(direction 1 = 45° / -1 = 135°, offsets within one period)], period in page units)
DRAWING_HATCHES = {
    "general": ("General (45°)", [(1, (0.0,))], 14.0),
    "metal": ("Steel / metal (45°)", [(1, (0.0,))], 14.0),
    "nonferrous": ("Non-ferrous metal (double lines)", [(1, (0.0, 4.0))], 20.0),
    "plastic": ("Plastic (cross-hatched)", [(1, (0.0,)), (-1, (0.0,))], 16.0),
    "rubber": ("Rubber / seals (dense)", [(1, (0.0,))], 7.0),
}
DRAWING_HATCH_WORDS = (
    ("plastic", ("plastic", "kunststoff", "pa6", "pa 6", "pa12", "pom", "pe-", "pp", "abs", "pla",
                 "petg", "peek", "pvc", "nylon", "ptfe", "acryl", "pmma", "pc ")),
    ("rubber", ("rubber", "gummi", "nbr", "epdm", "silicone", "silikon", "fkm", "viton")),
    ("nonferrous", ("alumin", "alu", "aw-", "en aw", "copper", "kupfer", "brass", "messing",
                    "bronze", "cuzn", "cusn", "titan", "magnes", "zinc", "zink")),
    ("metal", ("steel", "stahl", "s235", "s355", "c45", "42crmo", "1.4", "iron", "eisen", "gj",
               "inox", "x5cr")),
)


def _drawing_hatch_pattern(options):
    """Hatch pattern key of a sheet: chosen, or from its material ('auto')."""
    choice = options.get("hatch") or "auto"
    if choice in DRAWING_HATCHES:
        return choice
    material = f" {str(options.get('material') or options.get('_model_material') or '').lower()} "
    for key, words in DRAWING_HATCH_WORDS:
        if any(word in material for word in words):
            return key
    return "general"


def _paint_section_fill(painter, place, loops, regions=None, pattern="general", to_page=None,
                        outline=DRAWING_THICK, clip_path=None):
    """White cut faces with hatching (even-odd, so holes stay open). `regions` [(loops, bodies,
    (u0, v0, u1, v1) or None)] keep each set of loops in its range of the view; the faces of
    different bodies are hatched in opposite directions. `to_page` maps view coordinates."""
    own_mapping = to_page is None
    to_page = to_page or place.point
    # the cut faces and hatch lines only change with the section and where its view sits: a
    # refresh for anything else (another view dragged, a dimension) reuses them
    key = None
    if own_mapping:
        probe = (to_page(0.0, 0.0), to_page(1.0, 0.0), to_page(0.0, 1.0))
        key = (id(loops), id(regions), pattern,
               tuple((round(p.x(), 6), round(p.y(), 6)) for p in probe),
               repr(getattr(place, "breaks", None)),
               None if clip_path is None else
               tuple(round(v, 6) for v in clip_path.boundingRect().getRect()))
    cached = _SECTION_FILL_CACHE.get(key) if key is not None else None
    if cached is not None and cached[0] is loops and cached[1] is regions:
        shapes = cached[2]
    else:
        shapes = _section_fill_shapes(loops, regions, pattern, to_page, clip_path)
        if key is not None:
            _SECTION_FILL_CACHE[key] = (loops, regions, shapes)
            while len(_SECTION_FILL_CACHE) > 48:
                _SECTION_FILL_CACHE.pop(next(iter(_SECTION_FILL_CACHE)))
    for path, lines in shapes:
        painter.setPen(Qt.NoPen)
        painter.setBrush(_drawing_color("section_fill"))
        painter.drawPath(path)
        painter.setBrush(Qt.NoBrush)
        painter.setPen(_drawing_pen(DRAWING_THIN, role="hatch"))
        if lines:
            painter.drawLines(lines)
        painter.setPen(_drawing_pen(outline, role="visible"))
        painter.drawPath(path)


_SECTION_FILL_CACHE = {}           # key → (loops, regions, [(path, hatch lines)])


def _section_fill_shapes(loops, regions, pattern, to_page, clip_path):
    """The cut faces of _paint_section_fill as page paths with their hatch lines."""
    if regions is None:
        regions = [(loops, [0] * len(loops), None)]
    shapes = []
    groups = {}
    for region_loops, bodies, rect in regions:
        per_body = collections.defaultdict(list)
        for loop, body in zip(region_loops, list(bodies) + [0] * (len(region_loops) - len(bodies))):
            per_body[body].append(loop)
        clip = None
        if rect is not None:
            corners = [to_page(rect[0], rect[1]), to_page(rect[2], rect[1]),
                       to_page(rect[2], rect[3]), to_page(rect[0], rect[3])]
            clip = QPainterPath()
            clip.addPolygon(QPolygonF(corners))
            clip.closeSubpath()
        for body, body_loops in per_body.items():
            path = QPainterPath()
            path.setFillRule(Qt.OddEvenFill)
            for loop in body_loops:
                contour = [to_page(p[0], p[1]) for p in loop]
                path.moveTo(contour[0])
                for point in contour[1:]:
                    path.lineTo(point)
                path.closeSubpath()
            if clip is not None:
                path = path.intersected(clip)
            groups[body] = groups[body].united(path) if body in groups else path
    style = DRAWING_HATCHES.get(pattern, DRAWING_HATCHES["general"])
    for index, body in enumerate(sorted(groups)):
        path = groups[body]
        if clip_path is not None:                  # e.g. the circle of a detail view
            path = path.intersected(clip_path)
        if path.isEmpty():
            continue
        # plain coordinates (QPointF items of a temporary QPolygonF must not outlive it)
        polygons = path.toSubpathPolygons()
        contours = [[(polygon.at(i).x(), polygon.at(i).y()) for i in range(polygon.count())]
                    for polygon in polygons if polygon.count() >= 3]
        lines = []
        bounds = path.boundingRect()
        flip = -1 if index % 2 else 1                 # touching parts: opposite directions
        for direction, offsets in style[1]:
            sign = direction * flip                   # 1: lines x + y = level (45°), -1: x - y
            if sign > 0:
                start, end = bounds.left() + bounds.top(), bounds.right() + bounds.bottom()
            else:
                start, end = bounds.left() - bounds.bottom(), bounds.right() - bounds.top()
            base = start
            while base <= end:
                for shift in offsets:
                    level = base + shift
                    hits = []
                    for contour in contours:
                        for i, (ax, ay) in enumerate(contour):
                            bx, by = contour[i - 1]
                            sa, sb = ax + sign * ay, bx + sign * by
                            if (sa <= level < sb) or (sb <= level < sa):
                                f = (level - sa) / (sb - sa)
                                hits.append(QPointF(ax + (bx - ax) * f, ay + (by - ay) * f))
                    hits.sort(key=lambda p: p.x())
                    # every piece between neighbouring crossings whose middle lies in the face
                    # (robust against the slivers boolean path operations can leave)
                    for a, b in zip(hits, hits[1:]):
                        if abs(b.x() - a.x()) + abs(b.y() - a.y()) < 0.5:
                            continue
                        if path.contains(QPointF((a.x() + b.x()) / 2, (a.y() + b.y()) / 2)):
                            lines.append(QLineF(a, b))
                base += style[2]
        shapes.append((path, lines))
    return shapes


def _drawing_shaded_image(view, face_normals, tint=None):
    """Flat-shaded raster of the isometric view from its id buffer (no triangle seams); grey,
    or tinted with an (r, g, b) solid colour for the on-screen sheet."""
    frame = np.column_stack((view["right"], view["up"], view["normal"]))
    light = np.array((-0.35, 0.55, 0.75))
    light /= np.linalg.norm(light)
    tones = np.append(90 + 155 * np.clip((face_normals @ frame) @ light, 0, 1), 0)
    ids = view["ids"]
    rgba = np.empty(ids.shape + (4,), dtype=np.uint8)
    colour = np.ones(3) if tint is None else np.clip(np.asarray(tint, dtype=float), 0.0, 1.0)
    rgba[..., :3] = (tones[:, None] * colour[None, :]).astype(np.uint8)[ids]
    rgba[..., 3] = np.where(ids >= 0, 255, 0)
    height, width = ids.shape
    return QImage(rgba.data, width, height, width * 4, QImage.Format_RGBA8888).copy()


def _paint_projection_symbol(painter, right_edge, middle_y, first_angle=True):
    """Projection method symbol (ISO 5456-2): the cone elevation lies left of its end view in
    first-angle projection (method 1) and right of it in third-angle projection (method 3)."""
    big, small, length, gap = 13.0, 6.5, 22.0, 8.0
    if first_angle:
        cone_left = right_edge - 2 * big - gap - length
        cone_right = cone_left + length
        circle_x = cone_right + gap + big
    else:
        circle_x = right_edge - length - gap - big
        cone_left = circle_x + big + gap
        cone_right = cone_left + length
    painter.save()
    painter.setPen(_drawing_pen(DRAWING_THIN, role="text"))
    painter.drawPolygon(QPolygonF([QPointF(cone_left, middle_y - big), QPointF(cone_right, middle_y - small),
                                   QPointF(cone_right, middle_y + small), QPointF(cone_left, middle_y + big)]))
    painter.drawEllipse(QPointF(circle_x, middle_y), big, big)
    painter.drawEllipse(QPointF(circle_x, middle_y), small, small)
    painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
    painter.drawLine(QPointF(min(cone_left, circle_x - big) - 6, middle_y),
                     QPointF(max(cone_right, circle_x + big) + 6, middle_y))
    painter.restore()


def _paint_sheet_frame(painter):
    """DIN EN ISO 5457 / ISO 216 sheet (the current A2 … A5 sheet): frame, centring marks and
    reference grid."""
    page_w, page_h = _DRAWING_PAGE["w"], _DRAWING_PAGE["h"]
    left, top, right, bottom = DRAWING_BORDER
    x0, y0 = left, top
    x1, y1 = page_w - right, page_h - bottom
    painter.save()
    painter.setBrush(Qt.NoBrush)
    painter.setPen(_drawing_pen(DRAWING_FRAME_LINE, role="frame"))
    painter.drawRect(QRectF(x0, y0, x1 - x0, y1 - y0))
    # centring marks (0.5 mm): from the sheet edge to 5 mm inside the frame
    painter.setPen(_drawing_pen(2.0, role="frame"))
    mid_x, mid_y = page_w / 2, page_h / 2
    painter.drawLine(QPointF(mid_x, 0), QPointF(mid_x, y0 + 20))
    painter.drawLine(QPointF(mid_x, page_h), QPointF(mid_x, y1 - 20))
    painter.drawLine(QPointF(0, mid_y), QPointF(x0 + 20, mid_y))
    painter.drawLine(QPointF(page_w, mid_y), QPointF(x1 - 20, mid_y))
    # reference grid: 5 mm ticks outside the frame; numbers along the long sides, letters along the short ones
    columns, rows = _DRAWING_PAGE["zones"]
    painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
    painter.setFont(_drawing_font(DRAWING_TEXT))
    strip = 20.0
    for index in range(columns + 1):
        x = x0 + (x1 - x0) * index / columns
        painter.drawLine(QPointF(x, y0), QPointF(x, y0 - strip))
        painter.drawLine(QPointF(x, y1), QPointF(x, y1 + strip))
    for index in range(rows + 1):
        y = y0 + (y1 - y0) * index / rows
        painter.drawLine(QPointF(x0, y), QPointF(x0 - strip, y))
        painter.drawLine(QPointF(x1, y), QPointF(x1 + strip, y))
    painter.setPen(_drawing_color("frame"))
    for index in range(columns):
        cell_x = x0 + (x1 - x0) * index / columns
        cell_w = (x1 - x0) / columns
        label = str(index + 1)
        painter.drawText(QRectF(cell_x, y0 - strip, cell_w, strip), Qt.AlignCenter, label)
        painter.drawText(QRectF(cell_x, y1, cell_w, strip), Qt.AlignCenter, label)
    for index in range(rows):
        cell_y = y0 + (y1 - y0) * index / rows
        cell_h = (y1 - y0) / rows
        label = chr(ord("A") + index)
        painter.drawText(QRectF(x0 - strip, cell_y, strip, cell_h), Qt.AlignCenter, label)
        painter.drawText(QRectF(x1, cell_y, strip, cell_h), Qt.AlignCenter, label)
    painter.restore()


DRAWING_TITLE_W, DRAWING_TITLE_H = 720.0, 200.0         # DIN EN ISO 5457 / ISO 7200: 180 mm wide, in the lower right corner of the frame


def _paint_title_block(painter, options, scale_text):
    # 180 mm wide; on a sheet whose frame is narrower (A5 portrait) it takes the frame's width
    width = min(DRAWING_TITLE_W, _DRAWING_PAGE["w"] - DRAWING_BORDER[0] - DRAWING_BORDER[2])
    height = DRAWING_TITLE_H
    x = _DRAWING_PAGE["w"] - DRAWING_BORDER[2] - width
    y = _DRAWING_PAGE["h"] - DRAWING_BORDER[3] - height
    first_angle = options.get("projection", "third") != "third"
    painter.save()
    painter.setBrush(Qt.NoBrush)
    painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
    logo_width = 160.0 * width / DRAWING_TITLE_W
    logo_rect = QRectF(x, y, logo_width, height)
    painter.drawRect(logo_rect)
    logo = options.get("logo")
    if logo is not None and not logo.isNull():
        fitted = logo_rect.adjusted(8, 8, -8, -8)
        ratio = min(fitted.width() / logo.width(), fitted.height() / logo.height())
        w, h = logo.width() * ratio, logo.height() * ratio
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.drawPixmap(QRectF(fitted.center().x() - w / 2, fitted.center().y() - h / 2, w, h),
                           logo, QRectF(0, 0, logo.width(), logo.height()))
    info_x, info_width = x + logo_width, width - logo_width
    rows = (
        (("Title", options.get("title", ""), 0.62, DRAWING_TEXT_LARGE),
         ("Drawing no.", options.get("number", ""), 0.38, DRAWING_TEXT)),
        (("Project", options.get("project", ""), 0.32, DRAWING_TEXT),
         ("Created by", options.get("author", ""), 0.26, DRAWING_TEXT),
         ("Date", options.get("date", ""), 0.22, DRAWING_TEXT),
         ("Version", options.get("version", ""), 0.20, DRAWING_TEXT)),
        (("Material", options.get("material", ""), 0.40, DRAWING_TEXT),
         ("Surface treatment", options.get("treatment", ""), 0.38, DRAWING_TEXT),
         ("Sheet", options.get("page", ""), 0.22, DRAWING_TEXT)),
        (("General tolerances", options.get("tolerance", ""), 0.27, DRAWING_TEXT),
         ("Surface", options.get("surface", ""), 0.19, DRAWING_TEXT),
         ("Unit", _drawing_unit_label(), 0.15, DRAWING_TEXT),
         ("Scale", scale_text, 0.15, DRAWING_TEXT),
         ("Projection", None, 0.24, DRAWING_TEXT)),
    )
    row_height = height / len(rows)
    label_font = _drawing_font(DRAWING_TEXT_SMALL)
    for row_index, row in enumerate(rows):
        row_y = y + row_index * row_height
        painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
        painter.drawLine(QPointF(info_x, row_y), QPointF(x + width, row_y))
        cursor = info_x
        for label, value, share, value_height in row:
            cell_width = info_width * share
            painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
            painter.drawLine(QPointF(cursor, row_y), QPointF(cursor, row_y + row_height))
            painter.setFont(label_font)
            painter.setPen(_drawing_color("label"))
            painter.drawText(QPointF(cursor + 6, row_y + 6 + DRAWING_TEXT_SMALL), label)
            if value is None:
                painter.setPen(_drawing_color("text"))
                _paint_projection_symbol(painter, cursor + cell_width - 14, row_y + row_height / 2 + 6,
                                         first_angle)
            else:
                value_font = _drawing_font(value_height)
                painter.setFont(value_font)
                painter.setPen(_drawing_color("text"))
                painter.drawText(QPointF(cursor + 6, row_y + row_height - 6),
                                 QFontMetricsF(value_font).elidedText(
                                     str(value), Qt.ElideRight, int(cell_width - 12)))
            cursor += cell_width
    painter.setPen(_drawing_pen(DRAWING_FRAME_LINE, role="frame"))
    painter.drawRect(QRectF(x, y, width, height))
    painter.restore()


def _drawing_title_box():
    """(x, y, width) of the title block on the current sheet."""
    width = min(DRAWING_TITLE_W, _DRAWING_PAGE["w"] - DRAWING_BORDER[0] - DRAWING_BORDER[2])
    return (_DRAWING_PAGE["w"] - DRAWING_BORDER[2] - width,
            _DRAWING_PAGE["h"] - DRAWING_BORDER[3] - DRAWING_TITLE_H, width)


def _paint_table(painter, x, bottom, columns, rows, width=None):
    """A table drawn upwards from `bottom` (ISO 7573 parts lists grow from the title block up):
    `columns` [(heading, share of the width, alignment)], `rows` lists of cell texts (first row
    lowest, the heading row on top). x is the left edge, the width that of the title block
    unless given. Returns the top edge."""
    width = width or _drawing_title_box()[2]
    row_height = 36.0
    font = _drawing_font(DRAWING_TEXT)
    label_font = _drawing_font(DRAWING_TEXT_SMALL)
    painter.save()
    painter.setBrush(Qt.NoBrush)
    y = bottom
    lines = list(rows) + [None]                         # None: the heading row (on top)
    for row in lines:
        top = y - row_height
        cursor = x
        painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
        painter.drawRect(QRectF(x, top, width, row_height))
        for index, (heading, share, align) in enumerate(columns):
            cell = QRectF(cursor, top, width * share, row_height)
            if index:
                painter.setPen(_drawing_pen(DRAWING_FIELD_LINE, role="frame"))
                painter.drawLine(QPointF(cursor, top), QPointF(cursor, top + row_height))
            text = heading if row is None else str(row[index])
            painter.setFont(label_font if row is None else font)
            painter.setPen(_drawing_color("label" if row is None else "text"))
            inner = cell.adjusted(6, 0, -6, 0)
            painter.drawText(inner, (Qt.AlignLeft if row is None else align) | Qt.AlignVCenter,
                             QFontMetricsF(painter.font()).elidedText(text, Qt.ElideRight,
                                                                      int(inner.width())))
            cursor += width * share
        y = top
    painter.setPen(_drawing_pen(DRAWING_FRAME_LINE * 0.5, role="frame"))
    painter.drawRect(QRectF(x, y, width, bottom - y))
    painter.restore()
    return y


def _paint_sheet_tables(painter, options):
    """Above the title block: the parts list (item, name, quantity, material; numbered from the
    bottom up, ISO 7573), above it the general notes of the sheet."""
    x, top, width = _drawing_title_box()
    parts = options.get("parts") if options.get("parts_list") else None
    if parts:
        rows = [(str(index + 1), part.get("name", ""), str(part.get("qty", 1)), part.get("material", ""))
                for index, part in enumerate(parts)]
        top = _paint_table(painter, x, top, (("Item", 0.10, Qt.AlignCenter),
                                             ("Name", 0.48, Qt.AlignLeft),
                                             ("Qty", 0.10, Qt.AlignCenter),
                                             ("Material", 0.32, Qt.AlignLeft)), rows)
    notes = str(options.get("notes") or "").strip()
    if notes:
        font = _drawing_font(DRAWING_TEXT)
        metrics = QFontMetricsF(font)
        lines = []
        for line in notes.splitlines():           # wrapped to the width of the title block
            words, current = line.split(" "), ""
            for word in words:
                trial = f"{current} {word}".strip()
                if current and metrics.horizontalAdvance(trial) > width - 12:
                    lines.append(current)
                    current = word
                else:
                    current = trial
            lines.append(current)
        step = metrics.height() * 1.15
        y = top - 12 - step * (len(lines) - 1)
        painter.save()
        painter.setFont(_drawing_font(DRAWING_TEXT, True))
        painter.setPen(_drawing_color("text"))
        painter.drawText(QPointF(x, y - step), "Notes")
        painter.setFont(font)
        for index, line in enumerate(lines):
            painter.drawText(QPointF(x, y + index * step), line)
        painter.restore()


def _paint_stackup_tables(painter, options):
    """Tolerance stack-ups shown on the sheet (Phase 5): the chain with its deviations and the
    worst-case / statistical totals against the limits. Rows taken from a dimension follow it."""
    general = options.get("tolerance") or "ISO 2768-m"
    dimensions = options.get("dimensions") or []
    for stackup in options.get("stackups") or []:
        if not stackup.get("show") or "x" not in stackup:
            continue
        rows = []
        for row in stackup.get("rows", ()):
            row = dict(row)
            index = row.get("dim")
            if isinstance(index, int) and 0 <= index < len(dimensions) and "value" in dimensions[index]:
                dimension = dimensions[index]
                row["nominal"] = abs(float(dimension["value"]))
                row["upper"], row["lower"] = tol_dimension_deviations(
                    row["nominal"], dimension.get("tol"), general)
            rows.append(row)
        if not rows:
            continue
        result = tol_stackup(rows, stackup.get("min"), stackup.get("max"))
        number = lambda value: f"{value:+.3f}"
        lines = [(row.get("name", ""), "+" if row.get("sign", 1) >= 0 else "−",
                  _drawing_fmt(row["nominal"]), number(row["upper"]), number(row["lower"])) for row in rows]
        limits = f"{'' if stackup.get('min') is None else _drawing_fmt(stackup['min'])} … " \
                 f"{'' if stackup.get('max') is None else _drawing_fmt(stackup['max'])}"
        lines += [(f"{stackup.get('name', 'Gap')} nominal", "=", f"{result['nominal']:.3f}", "", ""),
                  ("Worst case", "", f"{result['worst'][0]:.3f} … {result['worst'][1]:.3f}",
                   "OK" if result["worst_ok"] else "NOT OK", ""),
                  ("Statistical (RSS)", "", f"{result['rss'][0]:.3f} … {result['rss'][1]:.3f}",
                   "OK" if result["rss_ok"] else "NOT OK", ""),
                  ("Required", "", limits, "", "")]
        font = _drawing_font(DRAWING_TEXT)
        metrics = QFontMetricsF(font)
        headings = ("Tolerance stack-up", "±", "Nominal", "Upper", "Lower")
        widths = [max([metrics.horizontalAdvance(heading)] +
                      [metrics.horizontalAdvance(str(line[index])) for line in lines]) + 20.0
                  for index, heading in enumerate(headings)]
        total = sum(widths)
        columns = tuple((heading, width / total, align) for heading, width, align in zip(
            headings, widths, (Qt.AlignLeft, Qt.AlignCenter, Qt.AlignRight, Qt.AlignRight, Qt.AlignRight)))
        x, y = float(stackup["x"]), float(stackup.get("y", 80.0))
        _paint_table(painter, x, y + 36.0 * (len(lines) + 1), columns, list(reversed(lines)), width=total)


def _paint_gear_table(painter, options):
    """Gear data table (DIN 3966-1 / ISO 1340): the values of the sheet's gear made with the Gear
    tool, with the quality class, top left corner at options["gear_table"] {"x", "y"}."""
    table = options.get("gear_table")
    gears = (options.get("_model") or {}).get("gears") or []
    if not isinstance(table, dict) or not gears:
        return
    gear = gears[min(max(int(table.get("index", 0)), 0), len(gears) - 1)]
    rows = [(name, symbol, value) for name, symbol, value in gear.get("rows", ())]
    quality = str(options.get("gear_quality") or "8")
    rows.insert(len(rows) - sum(1 for name, _s, _v in rows if name in ("Mating gear", "Centre distance")),
                ("Quality (ISO 1328)", "", quality))
    font = _drawing_font(DRAWING_TEXT)
    metrics = QFontMetricsF(font)
    headings = ("Gear data", "", "")
    widths = [max([metrics.horizontalAdvance(heading)] +
                  [metrics.horizontalAdvance(str(row[index])) for row in rows]) + 20.0
              for index, heading in enumerate(headings)]
    widths[1] = max(widths[1], 40.0)
    total = sum(widths)
    columns = tuple((heading, width / total, align) for heading, width, align in
                    zip(headings, widths, (Qt.AlignLeft, Qt.AlignCenter, Qt.AlignLeft)))
    x, y = float(table.get("x", 80.0)), float(table.get("y", 80.0))
    height = 36.0 * (len(rows) + 1)
    _paint_table(painter, x, y + height, columns, list(reversed(rows)), width=total)


def _paint_hole_table(painter, options, places, topology):
    """Hole table of one view (options["hole_table"] = {"view", "x", "y"}): every hole facing
    the viewer gets an ID (a letter per size, numbered: A1, A2, B1 …) on the view, and the table
    lists its X / Y position from the view's lower left corner (marked 0,0) and its size."""
    table = options.get("hole_table")
    if not isinstance(table, dict) or topology is None:
        return
    place = places.get(table.get("view"))
    if place is None or "normal" not in place.view:
        return
    holes = _drawing_view_holes(topology, place.view)
    if not holes:
        return
    sizes = []
    for _hole, data, _uv in holes:
        signature = _drawing_hole_signature(data)
        if signature not in sizes:
            sizes.append(signature)
    sizes.sort(key=lambda signature: (signature[0], str(signature[1:])))
    origin = (float(place.low[0]), float(place.low[1]))
    rows, counters = [], collections.Counter()
    ordered = sorted(holes, key=lambda item: (sizes.index(_drawing_hole_signature(item[1])),
                                              round(item[2][1], 3), round(item[2][0], 3)))
    font = _drawing_font(DRAWING_TEXT)
    painter.save()
    painter.setFont(font)
    for _hole, data, (u, v) in ordered:
        group = sizes.index(_drawing_hole_signature(data))
        letter = chr(ord("A") + group % 26)
        counters[letter] += 1
        hole_id = f"{letter}{counters[letter]}"
        centre = place.point(u, v)
        radius = data["d"] / 2.0 * place.scale
        painter.setPen(_drawing_color("dimension"))
        painter.drawText(QPointF(centre.x() + radius * 0.75 + 4, centre.y() - radius * 0.75 - 4), hole_id)
        size = " ".join(_drawing_callout_lines(dict(data, kind="hole", count=1)))
        rows.append((hole_id, _drawing_fmt(u - origin[0]), _drawing_fmt(v - origin[1]), size))
    # the origin of the table's coordinates
    corner = place.point(*origin)
    painter.setPen(_drawing_pen(DRAWING_THIN))
    painter.drawLine(QPointF(corner.x() - 12, corner.y()), QPointF(corner.x() + 12, corner.y()))
    painter.drawLine(QPointF(corner.x(), corner.y() - 12), QPointF(corner.x(), corner.y() + 12))
    painter.setPen(_drawing_color("dimension"))
    painter.drawText(QPointF(corner.x() - 40, corner.y() + 30), "0,0")
    painter.restore()
    x, y = float(table.get("x", 80.0)), float(table.get("y", 80.0))
    metrics = QFontMetricsF(font)
    headings = ("Hole", "X", "Y", "Size")
    widths = [max([metrics.horizontalAdvance(heading)] +
                  [metrics.horizontalAdvance(str(row[index])) for row in rows]) + 20.0
              for index, heading in enumerate(headings)]
    total = sum(widths)
    columns = tuple((heading, width / total, align) for heading, width, align in
                    zip(headings, widths, (Qt.AlignCenter, Qt.AlignRight, Qt.AlignRight, Qt.AlignLeft)))
    height = 36.0 * (len(rows) + 1)
    # rows listed from the top: the table grows downwards from its placed corner
    _paint_table(painter, x, y + height, columns, list(reversed(rows)), width=total)


DRAWING_MAIN_VIEWS = ("front", "top", "bottom", "right", "left")


def _drawing_wants_left(options):
    """The view from the left is projected only when placed or needed by the automatic layout."""
    if "view_placements" in options:
        return any(record.get("name") == "left" for record in options["view_placements"])
    return options.get("projection", "third") != "third"


def _drawing_wants_bottom(options):
    """The bottom view is projected only when placed."""
    return any(record.get("name") == "bottom" for record in options.get("view_placements") or [])


def _prepare_technical_drawing(vertices, triangles, options):
    V, T = _drawing_prepare_mesh(vertices, triangles)
    used = V[np.unique(T)]
    center = (used.min(axis=0) + used.max(axis=0)) / 2.0
    rotation = _import_rotation_matrix(options.get("rotation", (0, 0, 0)))
    V = (V - center) @ rotation.T
    # Phase 4: gears of the Gear tool (simplified, ISO 2203) and Thread tool features
    gears, thread_features = _drawing_model_geometry(options.get("_model"), center, rotation)
    if not options.get("gear_simplified", True):
        gears = []
    topology = _drawing_topology(V, T, gears=gears)
    topology["thread_features"] = thread_features
    # Phase 5: assembly parts (balloons find their item) and exploded-view trace lines
    topology["components"], topology["traces"] = _drawing_assembly_geometry(
        options.get("_model"), center, rotation)
    _drawing_match_thread_features(topology["threads"], thread_features)

    front = np.asarray(options["front"], dtype=float)
    right, up, normal = _drawing_view_frame(
        front, (0.0, 1.0, 0.0) if abs(front[2]) > 0.9 else (0.0, 0.0, 1.0))
    frames = {"front": (right, up, normal),
              "top": _drawing_view_frame(up, -normal),
              "right": _drawing_view_frame(right, up)}
    if _drawing_wants_left(options):
        frames["left"] = _drawing_view_frame(-right, up)
    if _drawing_wants_bottom(options):          # the front side up, as below the front view
        frames["bottom"] = _drawing_view_frame(-up, normal)
    projection_resolution = int(options.get("_projection_resolution", 900))
    iso_resolution = int(options.get("_isometric_resolution", 1200))
    views = {name: _drawing_project(V, T, topology, *frame, resolution=projection_resolution)
             for name, frame in frames.items()}
    iso_frame = _drawing_view_frame(normal + right + up, up)
    iso = _drawing_project(V, T, topology, *iso_frame, resolution=iso_resolution, want_ids=True)
    return V, T, topology, frames, views, iso


DRAWING_SECTION_PLANES = ("front", "top", "right")      # a cut is parallel to one of these views
# kinds of sections (Phase 3): full, half (one half cut, split by a centre line), offset (stepped:
# two parallel planes), aligned (a second leg turned into the plane), removed (the cut face only,
# beside the view) and revolved (the cut face turned 90° on the view itself)
DRAWING_SECTION_KINDS = ("full", "half", "offset", "aligned", "removed", "revolved")
DRAWING_SECTION_KIND_TEXT = {"full": "Full section", "half": "Half section",
                             "offset": "Offset (stepped) section", "aligned": "Aligned section",
                             "removed": "Removed section", "revolved": "Revolved section"}
DRAWING_SECTION_PLANE_TEXT = ("parallel to the front view", "parallel to the top view",
                              "parallel to the right side view")


def _drawing_sections(options):
    """Cut sections of a drawing: [{"letter", "plane" (0 front / 1 top / 2 right), "offset"}].
    Drawings from before several sections were possible ("section", "section_view",
    "cut_offset") give one section A-A."""
    sections = []
    if isinstance(options.get("sections"), list):
        for item in options["sections"]:
            if not isinstance(item, dict):
                continue
            letter = str(item.get("letter", "")).strip().upper()[:1]
            offset = float(item.get("offset", 0.0))
            if not letter.isalpha() or not math.isfinite(offset) or \
                    any(section["letter"] == letter for section in sections):
                continue
            section = {"letter": letter, "offset": offset,
                       "plane": min(2, max(0, int(item.get("plane", 0))))}
            # Phase 3: kind of section and its parameters
            kind = item.get("kind", "full")
            if kind in DRAWING_SECTION_KINDS and kind != "full":
                section["kind"] = kind
                section["axis"] = "v" if item.get("axis") == "v" else "u"
                for key, default in (("split", 0.0), ("offset2", offset), ("angle", 45.0)):
                    value = tol_number(item.get(key))
                    section[key] = value if value is not None else default
                section["side"] = -1 if item.get("side") == -1 else 1
            sections.append(section)
    elif options.get("section"):
        offset = float(options.get("cut_offset", 0.0))
        sections.append({"letter": "A", "offset": offset if math.isfinite(offset) else 0.0,
                         "plane": min(2, max(0, int(options.get("section_view", 0))))})
    return sections


def _section_view_letter(name, sections):
    """Letter of the section a placed view shows ("section-B"; the old "section" is the first)."""
    if name == "section":
        return sections[0]["letter"] if sections else None
    if isinstance(name, str) and name.startswith("section-"):
        return name[len("section-"):]
    return None


def _drawing_section_axes(topology, normal, offset, right, up, tolerance):
    """Centre lines [(start (u, v), end (u, v))] in a section view of the holes and bosses the
    cut runs through lengthwise: circular rims whose axis lies in the cut plane and that the
    plane passes through. Rims on one axis (both ends of a bore, counterbores) give one line
    from the first to the last rim."""
    normal = np.asarray(normal, dtype=float)
    groups = []
    for circle in topology.get("circles", ()):
        axis = np.asarray(circle["axis"], dtype=float)
        length = float(np.linalg.norm(axis))
        if length <= 1e-12:
            continue
        axis = axis / length
        centre = np.asarray(circle["center"], dtype=float)
        radius = float(circle["radius"])
        if abs(float(axis @ normal)) > 1e-3:              # axis not lying in the cut plane
            continue
        if abs(float(centre @ normal) - offset) >= radius - tolerance:   # plane misses the bore
            continue
        for group in groups:
            offset_vector = centre - group["point"]
            if abs(abs(float(group["axis"] @ axis)) - 1.0) < 1e-6 and \
                    float(np.linalg.norm(np.cross(offset_vector, group["axis"]))) <= tolerance:
                group["t"].append(float(offset_vector @ group["axis"]))
                break
        else:
            groups.append({"axis": axis, "point": centre, "t": [0.0]})
    right, up = np.asarray(right, dtype=float), np.asarray(up, dtype=float)
    lines = []
    for group in groups:
        low, high = min(group["t"]), max(group["t"])
        if high - low <= tolerance:                       # a single rim: no length to show
            continue
        a = group["point"] + group["axis"] * low
        b = group["point"] + group["axis"] * high
        lines.append(((float(a @ right), float(a @ up)), (float(b @ right), float(b @ up))))
    return lines


# ── views and sections (Technical Drawing, Phase 3) ────────────────────────────
# Sections other than a full cut are built from pieces: the part is split by helper planes (the
# centre line of a half section, the step of an offset section, the bisector of an aligned one),
# each piece is cut by its own plane and the pieces are joined again. The cut faces are the loops
# of a full cut, kept only in their region of the section view ("regions": loops, the range in
# the view (u0, v0, u1, v1) or None, and the body of every loop for the hatching).

def _drawing_join_meshes(pieces, span):
    """One mesh of several (vertices, triangles) pieces, coincident vertices welded."""
    pieces = [(np.asarray(v, dtype=float).reshape(-1, 3), np.asarray(t, dtype=np.int64).reshape(-1, 3))
              for v, t in pieces if v is not None and len(t)]
    if not pieces:
        raise ValueError("The section removes the entire solid.")
    points = np.vstack([v for v, _t in pieces])
    triangles, base = [], 0
    for v, t in pieces:
        triangles.append(t + base)
        base += len(v)
    triangles = np.concatenate(triangles)
    weld = max(span, 1e-9) * 1e-6
    _key, first, inverse = np.unique(np.rint(points / weld).astype(np.int64), axis=0,
                                     return_index=True, return_inverse=True)
    triangles = inverse.reshape(-1)[triangles]
    triangles = triangles[(triangles[:, 0] != triangles[:, 1]) & (triangles[:, 1] != triangles[:, 2])
                          & (triangles[:, 0] != triangles[:, 2])]
    return points[first], triangles


def _drawing_keep(V, T, normal, offset, below=True):
    """The part of a mesh with normal · p <= offset (below) or >= offset; (None, empty) if none."""
    if V is None or not len(T):
        return None, np.zeros((0, 3), dtype=np.int64)
    normal = np.asarray(normal, dtype=float)
    try:
        return _drawing_clip(V, T, normal if below else -normal, offset if below else -offset)
    except ValueError:
        return None, np.zeros((0, 3), dtype=np.int64)


def _drawing_rotate(V, point, axis, angle):
    """Vertices turned by `angle` (radians) about the line through `point` along `axis`."""
    axis = np.asarray(axis, dtype=float) / np.linalg.norm(axis)
    relative = np.asarray(V, dtype=float) - point
    cos, sin = math.cos(angle), math.sin(angle)
    return point + relative * cos + np.cross(axis, relative) * sin + \
        np.outer(relative @ axis, axis) * (1.0 - cos)


def _drawing_cut_loops(V, T, normal, right, up, offset):
    """Outlines (view u, v) of the cut face of a mesh in the plane normal · p = offset, and for
    each a 3-D vertex of its piece away from the cut (it tells the body of the loop)."""
    cut_v, cut_t = _drawing_keep(V, T, normal, offset)
    if cut_v is None:
        return [], []
    pairs = np.concatenate((cut_t[:, [0, 1]], cut_t[:, [1, 2]], cut_t[:, [2, 0]]))
    pairs.sort(axis=1)
    edges, counts = np.unique(pairs, axis=0, return_counts=True)
    span = max(float(np.ptp(cut_v, axis=0).max()), 1e-9)
    loops, starts = _drawing_section_loops(cut_v, {"edges": edges, "counts": counts, "span": span},
                                           normal, right, up, offset, with_start=True)
    labels = _drawing_component_labels(len(cut_v), cut_t)
    off_plane = np.abs(cut_v @ np.asarray(normal, dtype=float) - offset) > span * 1e-4
    anchors = []
    for start in starts:
        candidates = np.flatnonzero((labels == labels[start]) & off_plane)
        anchors.append(cut_v[candidates[0]] if len(candidates) else cut_v[start])
    return loops, anchors


def _drawing_component_labels(count, T):
    """Connected component of each of `count` vertices of the triangles T (min-label propagation
    with pointer jumping)."""
    T = np.asarray(T, dtype=np.int64).reshape(-1, 3)
    labels = np.arange(count)
    edges = np.concatenate((T[:, [0, 1]], T[:, [1, 2]]))
    while len(edges):
        low = np.minimum(labels[edges[:, 0]], labels[edges[:, 1]])
        updated = labels.copy()
        np.minimum.at(updated, edges[:, 0], low)
        np.minimum.at(updated, edges[:, 1], low)
        updated = updated[updated]
        if np.array_equal(updated, labels):
            break
        labels = updated
    return labels


def _drawing_bodies(topology):
    """Body (connected component) of every vertex of a part, cached: the hatching of touching
    parts runs in opposite directions."""
    if "_bodies" not in topology:
        topology["_bodies"] = _drawing_component_labels(len(topology["V"]), topology["T"])
    return topology["_bodies"]


def _drawing_loop_bodies(topology, anchors, transform=None):
    """Body label of every cut loop from a vertex of its piece away from the cut (`anchors`, 3-D;
    `transform` turns it back into the part, e.g. for the turned leg of an aligned section)."""
    if topology is None or "V" not in topology or not anchors:
        return [0] * len(anchors)
    labels = _drawing_bodies(topology)
    if len(np.unique(labels[np.unique(topology["T"])])) <= 1:
        return [0] * len(anchors)
    V = np.asarray(topology["V"], dtype=float)
    bodies = []
    for point in anchors:
        point = np.asarray(point, dtype=float)
        if transform is not None:
            point = transform(point)
        bodies.append(int(labels[int(np.argmin(np.einsum("ij,ij->i", V - point, V - point)))]))
    return bodies


def _drawing_section_frame(frames, item):
    """Frame of a section: (view name, right, up, normal, split axis s, axis a) - s lies in the
    cut plane along the section view's u (or v) axis, a is the other in-plane axis."""
    name = DRAWING_SECTION_PLANES[int(item["plane"])]
    right, up, normal = frames[name]
    if item.get("axis", "u") == "v":
        return name, right, up, normal, up, right
    return name, right, up, normal, right, up


def _drawing_filter_split_edges(topology, V, planes):
    """Edges lying in the helper planes that split the part are no outline: left out."""
    tolerance = topology["span"] * 1e-6
    edges = topology["edges"]
    mask = np.zeros(len(edges), dtype=bool)
    for normal, offset in planes:
        distance = np.abs(V @ np.asarray(normal, dtype=float) - offset)
        mask |= (distance[edges[:, 0]] <= tolerance) & (distance[edges[:, 1]] <= tolerance)
    for key in ("sharp", "fold"):
        topology[key] = topology[key] & ~mask


def _prepare_drawing_section(V, T, frames, item, threads=None, part_topology=None):
    """Section through the part parallel to one of the main views (item: "plane", "offset" and
    for Phase 3 kinds "kind", "axis", "split", "offset2", "angle", "side"); computed on its own so
    that moving a cut does not project all the other views again. `threads` are those of the
    whole part (the cut-off part has only pieces of their helices)."""
    offset = float(item["offset"])
    if not math.isfinite(offset):
        raise ValueError("The section offset must be a finite measurement.")
    plane = int(item["plane"])
    kind = item.get("kind", "full")
    name, s_right, s_up, s_normal, s_axis, a_axis = _drawing_section_frame(frames, item)
    span = max(float(np.ptp(V[np.unique(T)], axis=0).max()), 1e-9)
    big = 4.0 * span + abs(offset)
    coordinate = 0 if item.get("axis", "u") != "v" else 1   # the split axis in view coordinates

    def band(low, high):
        """Range of the section view (u0, v0, u1, v1) between low and high along the split axis."""
        if coordinate == 0:
            return (low, -big, high, big)
        return (-big, low, big, high)

    split_planes, centre_lines = [], []
    # regions: (cut loops, range of the view they are kept in, plane offset, turn back to the part)
    if kind in ("full", "removed", "revolved"):
        kept_v, kept_t = _drawing_clip(V, T, s_normal, offset)
        loops = _drawing_cut_loops(V, T, s_normal, s_right, s_up, offset)
        regions = [(loops, None, offset, None)]
    elif kind == "half":
        side, split = int(item.get("side", 1)), float(item.get("split", 0.0))
        outside = _drawing_keep(V, T, s_axis, split, below=side > 0)     # the half seen whole
        cut_half = _drawing_keep(V, T, s_axis, split, below=side < 0)
        cut_half = _drawing_keep(*cut_half, s_normal, offset)
        kept_v, kept_t = _drawing_join_meshes([outside, cut_half], span)
        loops = _drawing_cut_loops(V, T, s_normal, s_right, s_up, offset)
        regions = [(loops, band(split, big) if side > 0 else band(-big, split), offset, None)]
        split_planes = [(s_axis, split)]
        centre_lines = [(coordinate, split)]
    elif kind == "offset":
        step, second = float(item.get("split", 0.0)), float(item.get("offset2", offset))
        first_piece = _drawing_keep(*_drawing_keep(V, T, s_axis, step, below=True), s_normal, offset)
        second_piece = _drawing_keep(*_drawing_keep(V, T, s_axis, step, below=False),
                                     s_normal, second)
        kept_v, kept_t = _drawing_join_meshes([first_piece, second_piece], span)
        loops_first = _drawing_cut_loops(V, T, s_normal, s_right, s_up, offset)
        loops_second = _drawing_cut_loops(V, T, s_normal, s_right, s_up, second)
        regions = [(loops_first, band(-big, step), offset, None),
                   (loops_second, band(step, big), second, None)]
        split_planes = [(s_axis, step)]
    elif kind == "aligned":
        split, angle = float(item.get("split", 0.0)), math.radians(float(item.get("angle", 45.0)))
        centre = split * s_axis + offset * s_normal              # on the axis of the aligned cut
        leg = _drawing_rotate((-s_axis)[None, :], np.zeros(3), a_axis, angle)[0]
        first_piece = _drawing_keep(*_drawing_keep(V, T, s_axis, split, below=False),
                                    s_normal, offset)
        turned_v, turned_t = _drawing_keep(V, T, leg, float(centre @ leg), below=False)
        if turned_v is not None:                     # the second leg turned into the cut plane
            turned_v = _drawing_rotate(turned_v, centre, a_axis, -angle)
        second_piece = _drawing_keep(turned_v, turned_t, s_normal, offset)
        kept_v, kept_t = _drawing_join_meshes([first_piece, second_piece], span)
        loops_first = _drawing_cut_loops(V, T, s_normal, s_right, s_up, offset)
        turned_all = _drawing_rotate(V, centre, a_axis, -angle)
        loops_second = _drawing_cut_loops(turned_all, T, s_normal, s_right, s_up, offset)
        regions = [(loops_first, band(split, big), offset, None),
                   (loops_second, band(-big, split), offset,
                    lambda point: _drawing_rotate(point[None, :], centre, a_axis, angle)[0])]
        split_planes = [(s_axis, split)]
        centre_lines = [(coordinate, split)]
    else:
        raise ValueError(f"Unknown section kind {kind}")
    if kind in ("removed", "revolved"):
        # the cut face only: a view of its outlines (no edges behind it)
        s_topology = {"circles": [], "arcs": [], "threads": [], "span": span}
        view = _drawing_loops_view(regions[0][0][0], s_right, s_up, s_normal)
    else:
        s_topology = _drawing_topology(kept_v, kept_t, threads or [])
        if split_planes:
            _drawing_filter_split_edges(s_topology, kept_v, split_planes)
        view = _drawing_project(kept_v, kept_t, s_topology, s_right, s_up, s_normal, cut=offset)
    threads = threads or []
    finished = []
    for (loops, anchors), rect, at, transform in regions:
        bodies = _drawing_loop_bodies(part_topology, anchors, transform)
        if transform is None and threads:   # threaded holes / bolts: hatching up to the crest
            adjusted, adjusted_bodies = [], []
            for loop, body in zip(loops, bodies):
                for piece in _drawing_thread_section_loops([loop], threads, s_normal, at,
                                                           s_right, s_up):
                    adjusted.append(piece)
                    adjusted_bodies.append(body)
            loops, bodies = adjusted, adjusted_bodies
        finished.append((loops, bodies, rect))
    regions = finished
    return {"name": name, "plane": plane, "normal": s_normal, "topology": s_topology,
            "offset": offset, "kind": kind, "view": view, "regions": regions,
            "centre_lines": centre_lines, "axis_vector": s_axis, "a_vector": a_axis,
            "loops": [loop for loops, _bodies, _rect in regions for loop in loops]}


def _prepare_aux_view(V, T, topology, parent_frame, a, b, flip=False, resolution=900):
    """Auxiliary view of an inclined face: the parent view shows the face edge-on as the line
    a-b (view u, v); the view looks at it square on, so its true shape and size show."""
    right, up, normal = (np.asarray(vector, dtype=float) for vector in parent_frame)
    du, dv = float(b[0] - a[0]), float(b[1] - a[1])
    if math.hypot(du, dv) <= 1e-9:
        raise ValueError("The auxiliary view needs an edge of some length.")
    face_normal = -dv * right + du * up
    face_normal /= np.linalg.norm(face_normal)
    if flip:
        face_normal = -face_normal
    frame = _drawing_view_frame(face_normal, normal)
    view = _drawing_project(V, T, topology, *frame, resolution=resolution)
    view["aux_direction"] = face_normal
    return view


def _prepare_broken_out(V, T, frame, rect, depth, threads=None, part_topology=None):
    """Broken-out section of a view: inside the rectangle (u0, v0, u1, v1) the material in front
    of the plane normal · p = depth is taken away, so what is behind it shows in section."""
    right, up, normal = (np.asarray(vector, dtype=float) for vector in frame)
    u0, u1 = sorted((float(rect[0]), float(rect[2])))
    v0, v1 = sorted((float(rect[1]), float(rect[3])))
    span = max(float(np.ptp(V[np.unique(T)], axis=0).max()), 1e-9)
    middle = _drawing_keep(*_drawing_keep(V, T, right, u0, below=False), right, u1, below=True)
    inside = _drawing_keep(*_drawing_keep(*_drawing_keep(*middle, up, v0, below=False),
                                          up, v1, below=True), normal, depth, below=True)
    pieces = [inside, _drawing_keep(V, T, right, u0, below=True),
              _drawing_keep(V, T, right, u1, below=False),
              _drawing_keep(*middle, up, v0, below=True), _drawing_keep(*middle, up, v1, below=False)]
    kept_v, kept_t = _drawing_join_meshes(pieces, span)
    topo = _drawing_topology(kept_v, kept_t, threads or [])
    _drawing_filter_split_edges(topo, kept_v, [(right, u0), (right, u1), (up, v0), (up, v1)])
    view = _drawing_project(kept_v, kept_t, topo, right, up, normal, cut=depth)
    loops, anchors = _drawing_cut_loops(V, T, normal, right, up, depth)
    bodies = _drawing_loop_bodies(part_topology, anchors)
    view["broken_out"] = {"regions": [(loops, bodies, (u0, v0, u1, v1))], "rect": (u0, v0, u1, v1)}
    return view


def _paint_cut_polyline(painter, metrics, place, points, sights, letter):
    """Cutting-plane line along a path of view points (DIN ISO 128-40): thin chain line, thick at
    its ends and where it changes direction, sight arrows and letters at the ends."""
    page = [place.point(u, v) for u, v in points]
    if len(page) < 2:
        return
    painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
    path = QPainterPath(page[0])
    for point in page[1:]:
        path.lineTo(point)
    painter.drawPath(path)

    def toward(a, b, length):
        vector = np.array((b.x() - a.x(), b.y() - a.y()))
        norm = float(np.linalg.norm(vector))
        if norm <= 1e-9:
            return a
        vector *= min(length, norm) / norm
        return QPointF(a.x() + vector[0], a.y() + vector[1])

    painter.setPen(_drawing_pen(DRAWING_THICK, role="centre"))
    painter.drawLine(page[0], toward(page[0], page[1], 30))
    painter.drawLine(page[-1], toward(page[-1], page[-2], 30))
    for index in range(1, len(page) - 1):          # thick corners where the path turns
        painter.drawLine(toward(page[index], page[index - 1], 15), page[index])
        painter.drawLine(page[index], toward(page[index], page[index + 1], 15))
    for end, sight in ((page[0], sights[0]), (page[-1], sights[1])):
        sight = np.asarray(sight, dtype=float)
        if float(np.linalg.norm(sight)) <= 1e-9:
            continue
        sight = sight / float(np.linalg.norm(sight))
        tip = QPointF(end.x() + sight[0] * 34, end.y() + sight[1] * 34)
        painter.setPen(_drawing_pen(DRAWING_THIN, role="centre"))
        painter.drawLine(end, tip)
        _paint_arrow(painter, tip, sight, ink=_drawing_color("centre"))
        painter.setPen(_drawing_pen(1, role="centre"))
        painter.drawText(QPointF(tip.x() + sight[0] * 18 - metrics.horizontalAdvance(letter) / 2,
                                 tip.y() + sight[1] * 18 + 6), letter)


def _paint_section_cut(painter, metrics, place, section):
    """Cutting-plane line of a section in a view that sees its plane edge-on: straight, or
    stepped (offset section) / bent (aligned section) where this view shows the steps."""
    kind = section.get("kind", "full")
    item = section.get("item") or {}
    view = place.view
    right, up, view_normal = view["right"], view["up"], view["normal"]
    a_vector, s_vector = section.get("a_vector"), section.get("axis_vector")
    if kind not in ("offset", "aligned") or a_vector is None or \
            abs(float(np.asarray(a_vector) @ view_normal)) < 0.9:
        _paint_cut_line(painter, metrics, place, section["normal"], section["letter"],
                        section["offset"])
        return
    normal = np.asarray(section["normal"], dtype=float)
    s_vector = np.asarray(s_vector, dtype=float)
    margin = 24.0 / place.scale
    corners = [(u, v) for u in (place.low[0], place.high[0]) for v in (place.low[1], place.high[1])]
    s_view = np.array((float(s_vector @ right), float(s_vector @ up)))
    s_low = min(float(np.dot(corner, s_view)) for corner in corners) - margin
    s_high = max(float(np.dot(corner, s_view)) for corner in corners) + margin

    def at(along, depth):
        point = along * s_vector + depth * normal
        return float(point @ right), float(point @ up)

    def sight_of(vector):
        return (-float(vector @ right), float(vector @ up))     # page y points down

    offset, split = float(section["offset"]), float(item.get("split", 0.0))
    if kind == "offset":
        second = float(item.get("offset2", offset))
        points = [at(s_low, offset), at(split, offset), at(split, second), at(s_high, second)]
        _paint_cut_polyline(painter, metrics, place, points, (sight_of(normal), sight_of(normal)),
                            section["letter"])
        return
    angle = math.radians(float(item.get("angle", 45.0)))
    leg = _drawing_rotate((-s_vector)[None, :], np.zeros(3), a_vector, angle)[0]
    leg_normal = _drawing_rotate(normal[None, :], np.zeros(3), a_vector, angle)[0]
    centre = np.array(at(split, offset))
    leg_view = np.array((float(leg @ right), float(leg @ up)))
    reach = []                         # the second leg runs to the edge of the view (+ margin)
    for k, (low, high) in enumerate(((place.low[0] - margin, place.high[0] + margin),
                                     (place.low[1] - margin, place.high[1] + margin))):
        if abs(leg_view[k]) > 1e-9:
            reach.append(((high if leg_view[k] > 0 else low) - centre[k]) / leg_view[k])
    length = max(min(reach) if reach else 0.0, 0.0)
    end = centre + leg_view * length
    points = [tuple(end), tuple(centre), at(s_high, offset)]
    _paint_cut_polyline(painter, metrics, place, points, (sight_of(leg_normal), sight_of(normal)),
                        section["letter"])


def _paint_revolved_section(painter, place, section, pattern):
    """Revolved section on a view that sees its plane edge-on: the cut face turned by 90° into
    the view, centred on the plane's trace, outlined with thin lines (DIN ISO 128-40)."""
    view = place.view
    right, up, view_normal = view["right"], view["up"], view["normal"]
    normal = np.asarray(section["normal"], dtype=float)
    if abs(float(normal @ view_normal)) > 0.5:
        return
    s_right, s_up = section["view"]["right"], section["view"]["up"]
    trace = s_right if abs(float(s_right @ view_normal)) < 0.1 else s_up
    depth = s_up if trace is s_right else s_right
    if abs(float(depth @ view_normal)) < 0.9:
        return                                     # neither in-plane axis points at the viewer
    offset = float(section["offset"])
    loops3 = [loop[:, :1] * s_right + loop[:, 1:2] * s_up + offset * normal for loop in section["loops"]]
    if not loops3:
        return
    middle = float(np.mean(np.concatenate([points @ depth for points in loops3])))
    loops = []
    for points in loops3:
        turned = np.outer(points @ trace, trace) + np.outer(offset + points @ depth - middle, normal)
        loops.append(np.column_stack((turned @ right, turned @ up)))
    _paint_section_fill(painter, place, loops, None, pattern, outline=DRAWING_THIN)


def _paint_break_lines(painter, place):
    """Break lines of a broken view: thin lines with a zigzag (DIN ISO 128-20) at both edges."""
    painter.save()
    painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
    for item in place.breaks:
        k = item["k"]
        for value, side in ((item["a"], 0.0), (item["b"], 1.0)):
            if k == 0:
                x = place.point(value - 1e-9 if side == 0.0 else value, place.low[1]).x()
                y0, y1 = place.rect.bottom() + 8, place.rect.top() - 8
                mid, z = (y0 + y1) / 2, 7.0
                points = [QPointF(x, y0), QPointF(x, mid + z), QPointF(x - z, mid + z / 2),
                          QPointF(x + z, mid - z / 2), QPointF(x, mid - z), QPointF(x, y1)]
            else:
                y = place.point(place.low[0], value - 1e-9 if side == 0.0 else value).y()
                x0, x1 = place.rect.left() - 8, place.rect.right() + 8
                mid, z = (x0 + x1) / 2, 7.0
                points = [QPointF(x0, y), QPointF(mid - z, y), QPointF(mid - z / 2, y - z),
                          QPointF(mid + z / 2, y + z), QPointF(mid + z, y), QPointF(x1, y)]
            painter.drawPolyline(QPolygonF(points))
    painter.restore()


def _paint_freehand_rect(painter, place, rect):
    """Boundary of a broken-out section: a thin wavy (freehand) line around the rectangle."""
    u0, v0, u1, v1 = rect
    corners = [place.point(u0, v0), place.point(u1, v0), place.point(u1, v1), place.point(u0, v1)]
    points = []
    for index in range(4):
        a, b = corners[index], corners[(index + 1) % 4]
        length = math.hypot(b.x() - a.x(), b.y() - a.y())
        steps = max(4, int(length / 6))
        nx, ny = (-(b.y() - a.y()) / max(length, 1e-9), (b.x() - a.x()) / max(length, 1e-9))
        for step in range(steps):
            t = step / steps
            wave = 2.5 * math.sin(t * length / 9.0)
            points.append(QPointF(a.x() + (b.x() - a.x()) * t + nx * wave,
                                  a.y() + (b.y() - a.y()) * t + ny * wave))
    points.append(points[0])
    painter.save()
    painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
    painter.drawPolyline(QPolygonF(points))
    painter.restore()


def _drawing_clip_segments_circle(segments, centre, radius):
    """The pieces of segments (n, 2, 2) inside a circle."""
    segments = np.asarray(segments, dtype=float).reshape(-1, 2, 2)
    if not len(segments):
        return segments
    a, d = segments[:, 0] - centre, segments[:, 1] - segments[:, 0]
    qa = np.einsum("ij,ij->i", d, d)
    qb = 2.0 * np.einsum("ij,ij->i", a, d)
    qc = np.einsum("ij,ij->i", a, a) - radius * radius
    disc = qb * qb - 4 * qa * qc
    ok = (disc > 0) & (qa > 1e-18)
    root = np.sqrt(np.where(ok, disc, 0.0))
    safe = np.where(qa > 1e-18, qa, 1.0)
    t0 = np.clip((-qb - root) / (2 * safe), 0.0, 1.0)
    t1 = np.clip((-qb + root) / (2 * safe), 0.0, 1.0)
    keep = ok & (t1 > t0 + 1e-9)
    start = segments[:, 0] + d * t0[:, None]
    stop = segments[:, 0] + d * t1[:, None]
    return np.stack((start, stop), axis=1)[keep]


def _paint_detail_view(painter, place, item, parent_section, pattern, options):
    """Detail view: the part of the parent view inside the circle (u, v, r), at its own scale,
    with a thin circle around it and 'B (5:1)' under it; on the parent the circle and letter."""
    view, parent = place.view, place.parent
    centre, radius = np.array((float(item["u"]), float(item["v"]))), float(item["r"])
    letter = str(item.get("letter", "?"))
    thick = DRAWING_THICK * float(options.get("_thick_scale", 1.0))
    painter.save()

    def path_of(segments):
        path = QPainterPath()
        for (ax, ay), (bx, by) in _drawing_clip_segments_circle(segments, centre, radius).tolist():
            path.moveTo(place.point(ax, ay))
            path.lineTo(place.point(bx, by))
        return path
    if place.show_hidden and len(view.get("hidden", ())):
        painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_DASH, "hidden"))
        painter.drawPath(path_of(view["hidden"]))
    painter.setPen(_drawing_pen(thick, role="visible"))
    painter.drawPath(path_of(view["visible"]))
    centre_page = place.point(*centre)
    circle = QPainterPath()
    circle.addEllipse(centre_page, radius * place.scale, radius * place.scale)
    regions = None
    if parent_section is not None:
        regions = parent_section.get("regions")
    elif "broken_out" in view:
        regions = view["broken_out"]["regions"]
    if regions:
        _paint_section_fill(painter, place, [], regions, pattern, clip_path=circle)
    if len(view.get("thin", ())):
        painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
        painter.drawPath(path_of(view["thin"]))
    if len(view.get("chain", ())):
        painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
        painter.drawPath(path_of(view["chain"]))
    painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
    painter.setBrush(Qt.NoBrush)
    painter.drawEllipse(centre_page, radius * place.scale, radius * place.scale)
    painter.setFont(_drawing_font(DRAWING_TEXT_LARGE, True))
    painter.setPen(_drawing_color("text"))
    painter.drawText(QPointF(place.rect.left(), place.rect.bottom() + 36),
                     f"{letter} ({_drawing_scale_text(place.scale)})")
    # the circle and letter on the parent view
    parent_centre = parent.point(*centre)
    parent_radius = radius * parent.scale
    painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
    painter.drawEllipse(parent_centre, parent_radius, parent_radius)
    painter.setPen(_drawing_color("text"))
    painter.drawText(QPointF(parent_centre.x() + parent_radius * 0.72 + 6,
                             parent_centre.y() - parent_radius * 0.72 - 6), letter)
    painter.restore()


def _paint_aux_marks(painter, parent, place, item):
    """Auxiliary view: an arrow on the parent view looking square onto the inclined edge, with
    the view's letter; the letter again above the auxiliary view (DIN ISO 128-30)."""
    a, b = np.asarray(item["a"], dtype=float), np.asarray(item["b"], dtype=float)
    du, dv = b - a
    direction = np.array((-dv, du)) / max(math.hypot(du, dv), 1e-12)
    if item.get("flip"):
        direction = -direction
    middle = parent.point(*((a + b) / 2.0))
    screen = np.array((direction[0], -direction[1]))           # page y points down
    tail = QPointF(middle.x() + screen[0] * 70, middle.y() + screen[1] * 70)
    tip = QPointF(middle.x() + screen[0] * 14, middle.y() + screen[1] * 14)
    letter = str(item.get("letter", "?"))
    painter.save()
    painter.setPen(_drawing_pen(DRAWING_THIN, role="centre"))
    painter.drawLine(tail, tip)
    _paint_arrow(painter, tip, -screen, ink=_drawing_color("centre"))
    painter.setFont(_drawing_font(DRAWING_TEXT_LARGE, True))
    metrics = QFontMetricsF(painter.font())
    painter.setPen(_drawing_color("text"))
    painter.drawText(QPointF(tail.x() + screen[0] * 18 - metrics.horizontalAdvance(letter) / 2,
                             tail.y() + screen[1] * 18 + 7), letter)
    painter.drawText(QPointF(place.rect.left(), place.rect.top() - 24), letter)
    painter.restore()


def _drawing_loops_view(loops, right, up, normal):
    """A view made of cut outlines only (removed / revolved sections): bounds and pick geometry."""
    points = np.concatenate(loops) if loops else np.zeros((1, 2))
    low, high = points.min(axis=0), points.max(axis=0)
    segments = np.concatenate([np.stack((loop, np.roll(loop, -1, axis=0)), axis=1) for loop in loops]) \
        if loops else np.zeros((0, 2, 2))
    empty = np.zeros((0, 2, 2))
    return {"bounds": (low, high), "center": (low + high) / 2.0,
            "extent": max(float((high - low).max()), 1e-9) * 1.04, "visible": empty,
            "hidden": empty, "visible_edges": np.zeros(0, dtype=int),
            "hidden_edges": np.zeros(0, dtype=int), "edge_visible": np.zeros(0, dtype=bool),
            "pick_points": np.unique(points, axis=0), "pick_segments": segments,
            "pick_curves": [], "pick_arcs": [], "normal": normal, "right": right, "up": up}


def _draw_technical_drawing(painter, vertices, triangles, options):
    """Render projected views from a cached geometry package and editable sheet layout, in the
    palette options["_colors"] (default: black on white, as exported and printed)."""
    global _DRAWING_COLORS, _DRAWING_PAGE
    previous = _DRAWING_COLORS, _DRAWING_PAGE
    _DRAWING_COLORS = options.get("_colors") or DRAWING_PRINT_COLORS
    _DRAWING_PAGE = _drawing_sheet(options)
    previous_units = _drawing_use_units(_drawing_units_of(options))
    try:
        if vertices is None or triangles is None or not len(triangles):
            # a sheet without a model: frame, title block, imported graphics and their dimensions
            return _render_drawing_without_model(painter, options)
        return _render_technical_drawing(painter, vertices, triangles, options)
    finally:
        _DRAWING_COLORS, _DRAWING_PAGE = previous
        _drawing_use_units(previous_units)


def _drawing_begin_page(painter, options):
    """Page transform, sheet colour and frame (the caller restores the painter)."""
    painter.save()
    page_scale = options.get("_page_scale")
    page_w, page_h = _DRAWING_PAGE["w"], _DRAWING_PAGE["h"]
    if page_scale is None:
        painter.scale(painter.device().width() / page_w, painter.device().height() / page_h)
    else:
        painter.scale(float(page_scale), float(page_scale))
    painter.setRenderHint(QPainter.Antialiasing, True)
    painter.setRenderHint(QPainter.TextAntialiasing, True)
    if _DRAWING_COLORS.get("sheet"):
        painter.fillRect(QRectF(0, 0, page_w, page_h), _drawing_color("sheet"))
    _paint_sheet_frame(painter)
    painter.setBrush(Qt.NoBrush)


def _render_drawing_without_model(painter, options):
    """Sheet without a 3-D model: frame, imported SVG / DXF graphics, their dimensions and the
    title block. The title block shows the chosen scale, else that of the first graphic."""
    sheet_scale = float(options["scale_ratio"]) * DRAWING_UNITS_PER_MM \
        if options.get("scale_ratio") else None
    _drawing_begin_page(painter, options)
    places = {}
    _paint_drawing_graphics(painter, options, sheet_scale, places)
    dimension_hits = _paint_drawing_dimensions(painter, options, places, [])
    shown_scale = sheet_scale or next((place.scale for place in places.values()),
                                      DRAWING_UNITS_PER_MM)
    _paint_stackup_tables(painter, options)
    _paint_sheet_tables(painter, options)
    _paint_title_block(painter, options, _drawing_scale_text(shown_scale))
    painter.restore()
    return {"placements": _drawing_layout_records(places), "dimension_hits": dimension_hits,
            "plane_normals": [], "sections": [], "page": dict(_DRAWING_PAGE)}


def _render_technical_drawing(painter, vertices, triangles, options):
    cache = options.get("_geometry_cache")
    front = tuple(float(value) for value in options["front"])
    rotation = tuple(float(value) for value in options.get("rotation", (0, 0, 0)))
    geometry_key = (id(vertices), id(triangles), front, rotation, _drawing_wants_left(options),
                    _drawing_wants_bottom(options),
                    int(options.get("_projection_resolution", 900)),
                    int(options.get("_isometric_resolution", 1200)),
                    bool(options.get("gear_simplified", True)),
                    json.dumps(options.get("_model"), sort_keys=True, default=_json_default))
    if cache is not None and cache.get("key") == geometry_key:
        V, T, topology, frames, views, iso = cache["geometry"]
    else:
        geometry = _prepare_technical_drawing(vertices, triangles, options)
        V, T, topology, frames, views, iso = geometry
        if cache is not None:
            cache.clear()
            cache.update(key=geometry_key, geometry=geometry, sections={})
    # sections are cached one by one: moving or adding a cut computes only that section
    section_cache = cache.setdefault("sections", {}) if cache is not None else {}
    sections, used = [], set()
    for item in _drawing_sections(options):
        section_key = (item["plane"], round(float(item["offset"]), 6), item.get("kind", "full"),
                       item.get("axis", "u"), round(float(item.get("split", 0.0)), 6),
                       round(float(item.get("offset2", 0.0)), 6),
                       round(float(item.get("angle", 0.0)), 6), item.get("side", 1))
        used.add(section_key)
        if section_key not in section_cache:
            section_cache[section_key] = _prepare_drawing_section(
                V, T, frames, item, topology.get("threads"), topology)
        sections.append(dict(section_cache[section_key], letter=item["letter"], item=item))
    for section_key in [key for key in section_cache if key not in used]:
        del section_cache[section_key]
    # the automatic layout shows the first section that has a view of its own
    section = next((item for item in sections if item.get("kind") != "revolved"), None)
    pattern = _drawing_hatch_pattern(options)

    page_w, page_h = _DRAWING_PAGE["w"], _DRAWING_PAGE["h"]
    _drawing_begin_page(painter, options)
    metrics = QFontMetricsF(_drawing_font(DRAWING_TEXT))

    def size_of(view):
        low, high = view["bounds"]
        return np.maximum(high - low, 1e-6)

    # DIN ISO 128-30 / ISO 5456-2: first-angle projection puts the top view below the front view and
    # the view from the left to its right; third-angle projection puts the top view above and the view
    # from the right to its right.
    first_angle = options.get("projection", "third") != "third"
    side_name = "left" if first_angle else "right"
    (fw, fh), (_, td), (rd, _) = (size_of(views[n]) for n in ("front", "top", "right"))
    # automatic layout regions of the current sheet (inside the frame, clear of the title block):
    # the main views on the left, a column for the isometric view (and a section) on the right
    frame_x0, frame_y0 = DRAWING_BORDER[0], DRAWING_BORDER[1]
    frame_x1, frame_y1 = page_w - DRAWING_BORDER[2], page_h - DRAWING_BORDER[3]
    title_x0, title_y0, _title_w = _drawing_title_box()
    margin = 10.0
    area_x, area_y = frame_x0 + margin, frame_y0 + margin
    if page_w >= page_h:
        # landscape: a column on the right (isometric on top, a section below it)
        column_w = 0.3 * (frame_x1 - frame_x0)
        column_x = frame_x1 - column_w
        column_y0, column_y1 = frame_y0 + margin, title_y0 - margin
        iso_part = 0.45 if section else 1.0
        iso_rect = (column_x, column_y0, column_w, (column_y1 - column_y0) * iso_part)
        section_rect = (column_x, column_y0 + iso_rect[3] + 10, column_w,
                        column_y1 - column_y0 - iso_rect[3] - 10)
        area_w = column_x - margin - area_x
        # the title block reaches under the main views on narrow sheets: they stop above it
        area_bottom = title_y0 - margin if title_x0 < column_x else frame_y1 - margin
    else:
        # portrait: a band above the title block (isometric left, a section right)
        band_h = 0.32 * (title_y0 - frame_y0)
        band_y = title_y0 - margin - band_h
        band_w = frame_x1 - frame_x0 - 2 * margin
        iso_rect = (area_x, band_y, band_w / 2 if section else band_w, band_h)
        section_rect = (area_x + band_w / 2, band_y, band_w / 2, band_h)
        area_w = band_w
        area_bottom = band_y - margin
    area_h = area_bottom - area_y
    # "Auto" scale: the three main views with their dimensions fit the drawing area
    fit = max(min((area_w - 390) / (fw + rd), (area_h - 410) / (fh + td)), 1e-6)
    scale = _drawing_nice_scale(fit)
    manual_layout = "view_placements" in options
    if options.get("scale_ratio"):
        scale = float(options["scale_ratio"]) * DRAWING_UNITS_PER_MM      # ISO 5455 preferred scale
    elif manual_layout and float(options.get("view_scale", 1.0)) != 1.0:
        scale = _drawing_nice_scale(scale * float(options["view_scale"]))
    section_places = []                # (section, placement) of every section view on the sheet
    if manual_layout:
        places = {}
        projection_resolution = int(options.get("_projection_resolution", 900))
        aux_items = {str(item.get("letter")): item for item in options.get("aux_views") or []
                     if isinstance(item, dict)}
        aux_cache = cache.setdefault("aux", {}) if cache is not None else {}
        broken_cache = cache.setdefault("broken", {}) if cache is not None else {}
        used_aux, used_broken, pending_details = set(), set(), []
        for index, record in enumerate(options.get("view_placements", [])):
            name = record.get("name")
            view = views.get(name)
            shown = None
            letter = _section_view_letter(name, sections)
            if name == "isometric":
                view = iso
            elif letter is not None:
                shown = next((item for item in sections if item["letter"] == letter), None)
                view = shown["view"] if shown is not None else None
                name = f"section-{letter}"
            elif isinstance(name, str) and name.startswith("aux-"):
                item = aux_items.get(name[len("aux-"):])
                if item is not None and item.get("view") in frames:
                    key = (item["view"], tuple(round(float(x), 6) for x in (*item["a"], *item["b"])),
                           bool(item.get("flip")))
                    used_aux.add(key)
                    if key not in aux_cache:
                        aux_cache[key] = _prepare_aux_view(V, T, topology, frames[item["view"]],
                                                           item["a"], item["b"], item.get("flip"),
                                                           projection_resolution)
                    view = aux_cache[key]
            elif isinstance(name, str) and name.startswith("detail-"):
                pending_details.append((index, record))     # after the views they enlarge
                continue
            if view is None:
                continue
            broken_out = record.get("broken_out")
            if name in DRAWING_MAIN_VIEWS and isinstance(broken_out, dict):
                rect, depth = broken_out.get("rect"), broken_out.get("depth", 0.0)
                key = (name, tuple(round(float(x), 6) for x in rect), round(float(depth), 6))
                used_broken.add(key)
                if key not in broken_cache:
                    try:
                        broken_cache[key] = _prepare_broken_out(V, T, frames[name], rect, float(depth),
                                                                topology.get("threads"), topology)
                    except ValueError:
                        broken_cache[key] = None
                if broken_cache[key] is not None:
                    view = broken_cache[key]
            line_view = name in DRAWING_MAIN_VIEWS or str(name).startswith("aux-")
            place = _DrawingPlacement(view, float(record["x"]), float(record["y"]), scale,
                                      breaks=record.get("breaks") if line_view else None)
            place.record_index = index
            place.show_hidden = bool(record.get("hidden_lines", True)) and line_view
            places[name] = place
            if shown is not None:
                section_places.append((shown, place))
        for unused in [key for key in aux_cache if key not in used_aux]:
            del aux_cache[unused]
        for unused in [key for key in broken_cache if key not in used_broken]:
            del broken_cache[unused]
        details = {str(item.get("letter")): item for item in options.get("details") or []
                   if isinstance(item, dict)}
        for index, record in pending_details:
            item = details.get(record["name"][len("detail-"):])
            parent = places.get(item.get("view")) if item else None
            if parent is None:
                continue
            u, v, r = float(item["u"]), float(item["v"]), max(float(item["r"]), 1e-6)
            factor = max(float(item.get("factor", 2.0)), 0.01)
            place = _DrawingPlacement(parent.view, float(record["x"]), float(record["y"]),
                                      parent.scale * factor, bounds=((u - r, v - r), (u + r, v + r)))
            place.record_index = index
            place.show_hidden = getattr(parent, "show_hidden", False)
            place.detail, place.parent = item, parent
            place.parent_name = item.get("view")
            places[record["name"]] = place
        iso_place = places.get("isometric")
        section_place = section_scale = None        # (automatic layout only)
    else:
        total_w = 130 + (rd + fw) * scale + 130 + 130
        total_h = 130 + (fh + td) * scale + 130 + 150
        ox = area_x + (area_w - total_w) / 2
        oy = area_y + (area_h - total_h) / 2
        places = {}
        if first_angle:
            places["front"] = _DrawingPlacement(views["front"], ox + 130, oy + 130, scale)
            places["top"] = _DrawingPlacement(
                views["top"], ox + 130, places["front"].rect.bottom() + 130, scale)
        else:
            places["front"] = _DrawingPlacement(
                views["front"], ox + 130, oy + 130 + td * scale + 130, scale)
            places["top"] = _DrawingPlacement(views["top"], ox + 130, oy + 130, scale)
        places[side_name] = _DrawingPlacement(
            views[side_name], places["front"].rect.right() + 130, places["front"].rect.top(), scale)

    if not manual_layout:
        rx, ry, rw, rh = iso_rect
        iso_w, iso_h = size_of(iso)
        iso_scale = max(min((rw - 60) / iso_w, (rh - 80) / iso_h), 1e-6)
        iso_place = _DrawingPlacement(
            iso, rx + (rw - iso_w * iso_scale) / 2, ry + (rh - 20 - iso_h * iso_scale) / 2, iso_scale)

        section_place = section_scale = None
        if section:
            # room for the cutting-plane letters, its dimensions and the "A-A" label
            sx0, sy0, sw, sh = section_rect
            s_w, s_h = size_of(section["view"])
            avail_w = max(sw - 190, 40.0)
            avail_h = max(sh - 210, 40.0)
            section_scale = min(_drawing_nice_scale(min(avail_w / s_w, avail_h / s_h)), scale)
            section_place = _DrawingPlacement(
                section["view"], sx0 + 130 + (avail_w - s_w * section_scale) / 2,
                sy0 + 60 + (avail_h - s_h * section_scale) / 2, section_scale)
            section_places.append((section, section_place))

    def collect(place, topo, segment_sets):
        place.circles = _drawing_view_circles(topo, place.view)
        hz, vt = _drawing_axis_values(place.view, place.circles, topo, segment_sets)
        place.hz = _drawing_prune(hz, place.scale, metrics)
        place.vt = _drawing_prune(vt, place.scale, metrics)

    if not manual_layout:
        for name in ("front", "top", side_name):
            if name not in places:
                continue
            view = views[name]
            collect(places[name], topology, [(view["visible"], view["visible_edges"]),
                                             (view["hidden"], view["hidden_edges"])])
    reference = None
    if section and section_place is not None and not manual_layout:
        reference = places.get(section["name"])
        reference_circles = reference.circles if reference is not None else \
                            _drawing_view_circles(section["topology"], views[section["name"]])
        circle_tol = max(topology["span"] * 1e-3, 1e-6)

        def is_hole_outline(loop):
            centre = loop.mean(axis=0)
            radius = float(np.hypot(*(loop - centre).T).max())
            return any(c["kind"] == "circle" and abs(c["radius"] - radius) <= circle_tol
                       and math.hypot(c["u"] - centre[0], c["v"] - centre[1]) <= circle_tol
                       for c in _drawing_view_circles(section["topology"], section["view"]))

        outline_loops = [loop for loop in section["loops"] if not is_hole_outline(loop)]
        loop_segments = [np.stack((loop, np.roll(loop, -1, axis=0)), axis=1) for loop in outline_loops]
        loop_segments = np.concatenate(loop_segments) if loop_segments else np.zeros((0, 2, 2))
        collect(section_place, section["topology"],
                [(loop_segments, np.full(len(loop_segments), -1))])
        # cut edges of bores and bosses are already given by their diameter and centre
        for circle in topology["circles"] + topology["arcs"]:
            for axis_vector, coordinates in ((section["view"]["right"], section_place.hz),
                                             (section["view"]["up"], section_place.vt)):
                half = circle["radius"] * math.sqrt(max(1 - float(circle["axis"] @ axis_vector) ** 2, 0.0))
                centre = float(circle["center"] @ axis_vector)
                coordinates[:] = [x for x in coordinates
                                  if abs(x - centre - half) > circle_tol and abs(x - centre + half) > circle_tol
                                  or x in (coordinates[0], coordinates[-1])]
        # the section only shows what the view it is taken from does not already give
        section_place.circles = [
            c for c in section_place.circles
            if not any(c["kind"] == r["kind"] and abs(c["radius"] - r["radius"]) <= circle_tol
                       and math.hypot(c["u"] - r["u"], c["v"] - r["v"]) <= circle_tol
                       for r in reference_circles)]

    tolerance = max(topology["span"] * 1e-3, 1e-6)
    chains = {}
    if not manual_layout:
        chains = {
            ("front", "top"): (places["front"].hz, True),
            ("front", "right"): (places["front"].vt, True),
            ("top", "right"): (places["top"].vt, True),
            ("top", "bottom"): (_drawing_extras(places["top"].hz, places["front"].hz, tolerance), False),
            (side_name, "left"): (_drawing_extras(places[side_name].vt, places["front"].vt, tolerance), False),
            (side_name, "bottom"): (_drawing_extras(places[side_name].hz, places["top"].vt, tolerance), False),
        }

    line_views = [name for name in DRAWING_MAIN_VIEWS if name in places] + \
        [name for name in places if str(name).startswith("aux-")]
    for name in line_views:
        place = places[name]
        record_index = getattr(place, "record_index", None)
        record = options["view_placements"][record_index] \
            if manual_layout and record_index is not None else {}
        painter.save()
        if record.get("hidden_lines", True):          # hidden lines can be switched off per view
            painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_DASH, "hidden"))
            painter.drawPath(_drawing_segments_path(place, place.view["hidden"]))
        painter.setPen(_drawing_pen(DRAWING_THICK * float(options.get("_thick_scale", 1.0)),
                                    role="visible"))
        painter.drawPath(_drawing_segments_path(place, place.view["visible"]))
        if len(place.view.get("thin", ())):           # thread roots: thin continuous lines
            painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
            painter.drawPath(_drawing_segments_path(place, place.view["thin"]))
        if len(place.view.get("chain", ())):          # pitch circles / lines of gears
            painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
            painter.drawPath(_drawing_segments_path(place, place.view["chain"]))
        if topology.get("traces"):                    # exploded assembly: where the parts came from
            right, up = place.view["right"], place.view["up"]
            painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
            for a, b in topology["traces"]:
                start, end = (float(a @ right), float(a @ up)), (float(b @ right), float(b @ up))
                if math.hypot(end[0] - start[0], end[1] - start[1]) * place.scale > 2.0:
                    painter.drawLine(place.point(*start), place.point(*end))
        painter.restore()
        if "broken_out" in place.view:                # broken-out section: its cut face, freehand edge
            painter.save()
            _paint_section_fill(painter, place, [], place.view["broken_out"]["regions"], pattern)
            _paint_freehand_rect(painter, place, place.view["broken_out"]["rect"])
            painter.restore()
        if place.breaks:
            _paint_break_lines(painter, place)
        painter.setFont(_drawing_font(DRAWING_TEXT))
        if not manual_layout:
            _paint_circles(painter, metrics, place, topology)
        else:
            for circle in _drawing_view_circles(topology, place.view):
                if circle["kind"] == "circle" and circle["visible"]:
                    _paint_centre_mark(painter, place.point(circle["u"], circle["v"]),
                                       circle["radius"] * place.scale)
                    place.add_centre_cross(circle["u"], circle["v"], circle["radius"])
        # cutting lines of all sections whose plane this view shows edge-on; revolved sections
        # are drawn on the view itself
        for item in sections:
            if item.get("kind") == "revolved" and item["name"] != name and \
                    name in DRAWING_MAIN_VIEWS:
                painter.save()
                _paint_revolved_section(painter, place, item, pattern)
                painter.restore()
        cuts = [item for item in sections if item["name"] != name and
                item.get("kind") != "revolved" and not str(name).startswith("aux-") and
                _drawing_cut_sides(place, item["normal"]) is not None]
        for side in set(side for item in cuts for side in _drawing_cut_sides(place, item["normal"])):
            place.reserved[side] += 36
        for side in ("bottom", "left", "right", "top"):
            if (name, side) in chains:
                painter.setFont(_drawing_font(DRAWING_TEXT))
                values, overall = chains[(name, side)]
                _paint_chain(painter, metrics, place, values, side, overall)
        for item in cuts:
            painter.setFont(_drawing_font(DRAWING_TEXT_LARGE, True))
            _paint_section_cut(painter, QFontMetricsF(_drawing_font(DRAWING_TEXT_LARGE, True)),
                               place, item)

    if iso_place is not None:
        painter.save()
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        tint = _DRAWING_COLORS.get("iso_tint")
        image_key = "_image" if tint is None else ("_image", tuple(tint))
        if image_key not in iso:
            iso[image_key] = _drawing_shaded_image(iso, topology["normals"], tint)
        # the isometric view shows the shaded part only; its edges are drawn just where no
        # picture can be shown (DXF). The editor's preview takes the image apart: recorded in
        # its QPicture it would be serialised on every refresh (the slowest step by far).
        external = options.get("_external_images")
        if external is not None:
            external.append((QRectF(iso_place.image_rect()), iso[image_key]))
        else:
            painter.drawImage(iso_place.image_rect(), iso[image_key])
        if options.get("_iso_edges"):
            painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
            painter.drawPath(_drawing_segments_path(iso_place, iso["visible"]))
        painter.restore()

    for shown, shown_place in section_places:
        painter.save()
        painter.setPen(_drawing_pen(DRAWING_THICK * float(options.get("_thick_scale", 1.0)),
                                    role="visible"))
        painter.drawPath(_drawing_segments_path(shown_place, shown["view"]["visible"]))
        _paint_section_fill(painter, shown_place, shown["loops"], shown.get("regions"), pattern)
        if len(shown["view"].get("thin", ())):        # thread roots over the hatching
            painter.setPen(_drawing_pen(DRAWING_THIN, role="visible"))
            painter.drawPath(_drawing_segments_path(shown_place, shown["view"]["thin"]))
        # half / aligned section: a centre line between the two halves
        painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
        for coordinate, value in shown.get("centre_lines", ()):
            reach = 12.0 / shown_place.scale
            if coordinate == 0:
                ends = ((value, shown_place.low[1] - reach), (value, shown_place.high[1] + reach))
            else:
                ends = ((shown_place.low[0] - reach, value), (shown_place.high[0] + reach, value))
            painter.drawLine(shown_place.point(*ends[0]), shown_place.point(*ends[1]))
            shown_place.centre_lines.append(ends)
        # centre lines of holes (and bosses) the cut runs through lengthwise (DIN ISO 128)
        painter.setPen(_drawing_pen(DRAWING_THIN, DRAWING_CHAIN, "centre"))
        for start, end in _drawing_section_axes(
                topology, shown["normal"], shown["offset"], shown["view"]["right"],
                shown["view"]["up"], max(topology["span"] * 1e-3, 1e-6)):
            a, b = shown_place.point(*start), shown_place.point(*end)
            along = np.array((b.x() - a.x(), b.y() - a.y()))
            length = float(np.linalg.norm(along))
            if length < 1.0:
                continue
            along *= 8.0 / length                       # 2 mm beyond the contour at each end
            painter.drawLine(QPointF(a.x() - along[0], a.y() - along[1]),
                             QPointF(b.x() + along[0], b.y() + along[1]))
            reach = np.subtract(end, start)
            reach = reach / float(np.linalg.norm(reach)) * 8.0 / shown_place.scale
            shown_place.centre_lines.append((tuple(np.subtract(start, reach)),
                                             tuple(np.add(end, reach))))
        painter.restore()
        if manual_layout:
            for circle in _drawing_view_circles(shown["topology"], shown["view"]):
                if circle["kind"] == "circle" and circle["visible"]:
                    _paint_centre_mark(painter, shown_place.point(circle["u"], circle["v"]),
                                       circle["radius"] * shown_place.scale)
                    shown_place.add_centre_cross(circle["u"], circle["v"], circle["radius"])
        else:
            painter.setFont(_drawing_font(DRAWING_TEXT))
            _paint_circles(painter, metrics, shown_place)
            _paint_chain(painter, metrics, shown_place,
                         _drawing_extras(shown_place.hz, reference.hz, tolerance), "bottom", False)
            _paint_chain(painter, metrics, shown_place,
                         _drawing_extras(shown_place.vt, reference.vt, tolerance), "left", False)
        painter.setPen(_drawing_pen(DRAWING_THIN, role="text"))
        painter.setFont(_drawing_font(DRAWING_TEXT_LARGE, True))
        label = f"{shown['letter']}-{shown['letter']}"
        if abs(shown_place.scale - scale) > 1e-6:
            label += f" ({_drawing_scale_text(shown_place.scale)})"
        painter.drawText(QPointF(shown_place.rect.left(),
                                 shown_place.rect.bottom() + shown_place.reserved["bottom"] + 30), label)

    # detail views (Phase 3): part of a view in a circle, enlarged; the circle on the parent view
    sections_by_name = {f"section-{item['letter']}": item for item in sections}
    for name, place in places.items():
        item = getattr(place, "detail", None)
        if item is not None:
            _paint_detail_view(painter, place, item, sections_by_name.get(place.parent_name),
                               pattern, options)
    # auxiliary views (Phase 3): the viewing direction on the parent view, the letter above
    for name, place in places.items():
        if not str(name).startswith("aux-"):
            continue
        item = next((entry for entry in options.get("aux_views") or []
                     if f"aux-{entry.get('letter')}" == name), None)
        parent = places.get(item.get("view")) if item else None
        if parent is not None:
            _paint_aux_marks(painter, parent, place, item)
    # hole table: hole IDs on the view, positions and sizes in a table (Phase 2)
    _paint_hole_table(painter, options, places, topology)
    _paint_gear_table(painter, options)              # gear data (Phase 4)
    _paint_stackup_tables(painter, options)          # tolerance stack-ups (Phase 5)
    # imported SVG / DXF graphics (placed like views; their geometry can be dimensioned)
    _paint_drawing_graphics(painter, options, scale, places)
    dimension_hits = _paint_drawing_dimensions(painter, options, places, sections, topology)
    _paint_sheet_tables(painter, options)
    _paint_title_block(painter, options, _drawing_scale_text(scale))
    painter.restore()
    layout_records = _drawing_layout_records(places)
    return {"placements": layout_records, "dimension_hits": dimension_hits,
            # the normals of the three section planes (front / top / right) and every section
            "plane_normals": [frames[name][2].tolist() for name in DRAWING_SECTION_PLANES],
            "sections": [{"letter": item["letter"], "name": item["name"], "plane": item["plane"],
                          "offset": item["offset"], "normal": item["normal"].tolist()}
                         for item in sections],
            "page": dict(_DRAWING_PAGE)}


def _drawing_resolve_callout(annotation, topology, view, tip):
    """A hole or thread callout that follows the model gets its values from the geometry at its
    leader point (so the drawing and the model cannot disagree); others are returned as they are."""
    if annotation is None or annotation.get("kind") not in ("hole", "thread") or \
            not annotation.get("linked") or topology is None or "normal" not in view:
        return annotation
    reach = max(float(topology["span"]) * 0.01, 0.5)
    if annotation["kind"] == "hole":
        data = _drawing_hole_at(topology, view, tip, reach)
        if data is None:
            return annotation
        return dict(annotation, d=data["d"], through=data["through"], depth=data["depth"],
                    cbore=list(data["cbore"]) if data["cbore"] else None,
                    csk=list(data["csk"]) if data["csk"] else None, count=data["count"])
    data = _drawing_thread_at(topology, view, tip, reach)
    if data is None:
        return annotation
    resolved = dict(annotation, label=data["label"], label_pitch=data["label_pitch"],
                    internal=data["internal"], length=data["length"], through=data["through"],
                    count=data["count"], hand=data.get("hand", "right"))
    if data.get("cls") is not None:                  # the tolerance class of the thread feature
        resolved["cls"] = data["cls"]
    return resolved


def _paint_drawing_dimensions(painter, options, places, sections, topology=None):
    """Paint the added dimensions on their placed views; returns their hit boxes. Hole and
    thread callouts that follow the model are read from `topology` (the part's geometry)."""
    dimension_hits = []
    for dimension_index, dimension in enumerate(options.get("dimensions", [])):
        place = places.get(dimension.get("view"))
        if place is None and dimension.get("view") == "section" and sections:   # older drawings
            place = places.get(f"section-{sections[0]['letter']}")
        if place is None:
            continue
        kind = dimension.get("type", "length")
        if kind == "annotation":            # GD&T frame, datum, surface finish, weld symbol
            annotation = tol_normalize_annotation(dimension.get("ann"))
            if annotation is not None and dimension.get("points"):
                annotation = _drawing_resolve_callout(annotation, topology, place.view,
                                                      dimension["points"][0])
                _paint_annotation(painter, annotation, place.point(*dimension["points"][0]),
                                  annotation["offset"], 1.0, _drawing_pen(DRAWING_THIN),
                                  _drawing_color("dimension"))
            continue
        dimension_offset = np.asarray(dimension.get("offset", (0.0, 0.0)), dtype=float)
        points = dimension.get("points") or [dimension.get("a"), dimension.get("b")]
        if kind == "angle":
            if len(points) != 3 or any(point is None for point in points):
                continue
            vertex, ray_a, ray_b = [place.point(*point) for point in points]
            vertex += QPointF(*dimension_offset)
            ray_a += QPointF(*dimension_offset)
            ray_b += QPointF(*dimension_offset)
            angle_a = math.degrees(math.atan2(vertex.y() - ray_a.y(), ray_a.x() - vertex.x()))
            angle_b = math.degrees(math.atan2(vertex.y() - ray_b.y(), ray_b.x() - vertex.x()))
            sweep = (angle_b - angle_a + 180.0) % 360.0 - 180.0
            radius = float(dimension.get("offset_distance", min(
                math.hypot(ray_a.x() - vertex.x(), ray_a.y() - vertex.y()),
                math.hypot(ray_b.x() - vertex.x(), ray_b.y() - vertex.y())) * 0.45))
            if radius < 10:
                continue
            painter.setPen(_drawing_pen(DRAWING_THIN))
            painter.drawLine(vertex, ray_a)
            painter.drawLine(vertex, ray_b)
            arc = QRectF(vertex.x() - radius, vertex.y() - radius, 2 * radius, 2 * radius)
            painter.drawArc(arc, int(angle_a * 16), int(sweep * 16))
            direction_sign = 1.0 if sweep >= 0 else -1.0
            for end_angle, outward in ((angle_a, 1.0), (angle_a + sweep, -1.0)):
                t = math.radians(end_angle)
                tip = QPointF(vertex.x() + math.cos(t) * radius, vertex.y() - math.sin(t) * radius)
                _paint_arrow(painter, tip, (outward * direction_sign * math.sin(t),
                                            outward * direction_sign * math.cos(t)))
            mid = math.radians(angle_a + sweep / 2)
            label_text = _drawing_dimension_value_text(dimension, unit="°")
            label = str(dimension.get("label", "")).strip()
            if label and label.lower() != "angle":
                label_text = f"{label} {label_text}"
            anchor = QPointF(vertex.x() + math.cos(mid) * (radius + 18),
                             vertex.y() - math.sin(mid) * (radius + 18))
            text_offset = np.asarray(dimension.get("text_offset", (0.0, 0.0)), dtype=float)
            label_point = anchor + QPointF(*text_offset)
            if np.linalg.norm(text_offset) > 28.0:
                painter.drawLine(anchor, label_point)
            painter.setFont(_drawing_font(14))
            painter.setPen(_drawing_color("dimension"))
            painter.drawText(label_point, label_text)
            label_width = QFontMetricsF(_drawing_font(14)).horizontalAdvance(label_text)
            dimension_hits.append({"index": dimension_index,
                                   "x": min(vertex.x(), label_point.x() - label_width / 2 - 8),
                                   "y": min(vertex.y(), label_point.y() - 20),
                                   "width": max(vertex.x(), label_point.x() + label_width / 2 + 8) -
                                            min(vertex.x(), label_point.x() - label_width / 2 - 8),
                                   "height": max(vertex.y(), label_point.y() + 8) -
                                             min(vertex.y(), label_point.y() - 20)})
            continue
        if len(points) < 2 or points[0] is None or points[1] is None:
            continue
        first = place.point(*points[0])
        second = place.point(*points[1])
        if kind in ("radius", "diameter"):
            value_text = _drawing_dimension_value_text(dimension, "R" if kind == "radius" else "Ø")
            custom_label = str(dimension.get("label", "")).strip()
            if custom_label and custom_label.lower() not in (kind, "length"):
                value_text = f"{custom_label} {value_text}"
            center_values = np.asarray(points[0], dtype=float) if kind == "radius" else \
                (np.asarray(points[0], dtype=float) + np.asarray(points[1], dtype=float)) / 2.0
            edge_values = np.asarray(points[1], dtype=float)
            radius = float(np.linalg.norm(edge_values - center_values))
            if dimension.get("angle") is not None:
                edge_values = center_values + radius * np.array((
                    math.cos(float(dimension["angle"])), math.sin(float(dimension["angle"]))))
            center = place.point(*center_values)
            edge = place.point(*edge_values)
            label_rect = _paint_radial_dimension(
                painter, center, edge, value_text, kind == "diameter", 1.0,
                _drawing_color("dimension"), _drawing_color("label_back"),
                _drawing_font(DRAWING_TEXT), DRAWING_THIN,
                dimension.get("text_offset", (0.0, 0.0)),
                float(dimension.get("leader_length", 16.0)))
            dimension_hits.append({"index": dimension_index, "x": label_rect.x(),
                                   "y": label_rect.y(), "width": label_rect.width(),
                                   "height": label_rect.height()})
            continue
        if kind in ("chamfer", "arc", "ordinate"):
            rect = _paint_extra_dimension(painter, dimension, place.point, 1.0,
                                          _drawing_pen(DRAWING_THIN), _drawing_color("dimension"),
                                          _drawing_font(DRAWING_TEXT), _drawing_color("label_back"))
            if rect is not None:
                dimension_hits.append({"index": dimension_index, "x": rect.x(), "y": rect.y(),
                                       "width": rect.width(), "height": rect.height()})
            continue
        frame = _drawing_length_frame((first.x(), first.y()), (second.x(), second.y()), dimension)
        if frame is None or float(np.linalg.norm(frame[1] - frame[0])) < 1:
            continue
        start_page, end_page, vector, normal, _distance = frame
        length = float(np.linalg.norm(end_page - start_page))
        start, end = QPointF(*start_page), QPointF(*end_page)
        painter.setPen(_drawing_pen(DRAWING_THIN))
        # extension lines: 2 mm gap to the measured point, 2 mm beyond the dimension line (DIN 406-11)
        for anchor, tip in ((first, start), (second, end)):
            reach = np.array((tip.x() - anchor.x(), tip.y() - anchor.y()))
            if float(np.linalg.norm(reach)) > 12.0:
                step = reach / float(np.linalg.norm(reach)) * 8.0
                painter.drawLine(QPointF(anchor.x() + step[0], anchor.y() + step[1]),
                                 QPointF(tip.x() + step[0], tip.y() + step[1]))
        painter.drawLine(start, end)
        _paint_arrow(painter, start, vector)
        _paint_arrow(painter, end, -vector)
        value_text = _drawing_dimension_value_text(dimension)
        label = str(dimension.get("label", "")).strip()
        if label and label.lower() not in (kind, "length"):
            value_text = f"{label} {value_text}"
        label = value_text
        font = _drawing_font(DRAWING_TEXT)
        painter.setFont(font)
        text_metrics = QFontMetricsF(font)
        label_width = text_metrics.horizontalAdvance(label)
        midpoint = QPointF((start.x() + end.x()) / 2, (start.y() + end.y()) / 2)
        text_offset = np.asarray(dimension.get("text_offset", (0.0, 0.0)), dtype=float)
        if np.linalg.norm(text_offset) > 1e-6:
            label_center = midpoint + QPointF(*text_offset)
            label_rect = QRectF(label_center.x() - label_width / 2 - 4,
                                label_center.y() - text_metrics.height() / 2 - 2,
                                label_width + 8, text_metrics.height() + 4)
            target = QPointF(min(max(midpoint.x(), label_rect.left()), label_rect.right()),
                             min(max(midpoint.y(), label_rect.top()), label_rect.bottom()))
            painter.setPen(_drawing_pen(DRAWING_THIN))
            painter.drawLine(midpoint, target)
            painter.fillRect(label_rect, _drawing_color("label_back"))
            painter.setPen(_drawing_color("dimension"))
            painter.drawText(label_rect, Qt.AlignCenter, label)
        else:
            shift = float(dimension.get("text_shift", 0.0))
            if abs(shift) > length / 2:
                # text moved past an end of the dimension line: the line is continued under it
                reach = (abs(shift) + label_width / 2 + 4) * (1.0 if shift > 0 else -1.0)
                painter.setPen(_drawing_pen(DRAWING_THIN))
                painter.drawLine(end if shift > 0 else start,
                                 QPointF(midpoint.x() + vector[0] * reach,
                                         midpoint.y() + vector[1] * reach))
            # text parallel to the dimension line, 1 mm above it, readable from the bottom or the right
            label_rect = _paint_dimension_label(
                painter, font, midpoint, vector, normal, label,
                float(dimension.get("text_shift", 0.0)), float(dimension.get("text_lift", 0.0)),
                leader_pen=_drawing_pen(DRAWING_THIN))
        dimension_hits.append({"index": dimension_index, "x": label_rect.x(),
                       "y": label_rect.y(), "width": label_rect.width(),
                       "height": label_rect.height()})
    return dimension_hits


def _drawing_layout_records(places):
    """What the editor canvas needs of each placed view: frame, scale, axes and the
    geometry that can be picked for dimensions."""
    layout_records = []
    for name, place in places.items():
        # what is not drawn cannot be picked: hidden lines switched off, section views
        show_hidden = getattr(place, "show_hidden", not str(name).startswith("section"))
        picks = place.view if show_hidden or "visible_picks" not in place.view else \
            place.view["visible_picks"]
        layout_records.append({
            "name": name, "record_index": getattr(place, "record_index", None),
            "x": place.rect.left(), "y": place.rect.top(),
            "width": place.rect.width(), "height": place.rect.height(),
            "low": place.low.tolist(), "high": place.high.tolist(), "scale": place.scale,
            "right": place.view["right"].tolist(), "up": place.view["up"].tolist(),
            "hidden_shown": bool(show_hidden),
            "breaks": [dict(item) for item in getattr(place, "breaks", ())],
            # nothing to pick in the shaded isometric view (no edge highlighting there)
            "pick_points": picks.get("pick_points", np.zeros((0, 2)))
                           if name != "isometric" else np.zeros((0, 2)),
            "pick_segments": picks.get("pick_segments", np.zeros((0, 2, 2)))
                             if name != "isometric" else np.zeros((0, 2, 2)),
            "pick_curves": picks.get("pick_curves", []) if name != "isometric" else [],
            "pick_arcs": picks.get("pick_arcs", []) if name != "isometric" else [],
            # drawn centre lines (circle crosses, hole axes): references for dimensions
            "centre_lines": np.asarray(place.centre_lines, dtype=float).reshape(-1, 2, 2),
        })
    return layout_records


def _read_stl_mesh(path, progress=None):
    """Read a binary or ASCII STL as indexed vertices and triangles."""
    if progress is not None:
        progress(None)
    with open(path, "rb") as f:
        data = f.read()
    if progress is not None:
        progress(0)
    facets = []
    if len(data) >= 84:
        count = struct.unpack_from("<I", data, 80)[0]
        if count and 84 + count * 50 == len(data):
            for i in range(count):
                values = struct.unpack_from("<12fH", data, 84 + i * 50)
                facets.append((values[3:6], values[6:9], values[9:12]))
                if progress is not None and (i == count - 1 or i % max(1, count // 35) == 0):
                    progress(35 * (i + 1) // count)
    if not facets:
        try:
            text = data.decode("utf-8-sig")
        except UnicodeDecodeError as ex:
            raise ValueError("The file is neither a valid binary nor ASCII STL") from ex
        points = []
        lines = text.splitlines()
        for line_index, line in enumerate(lines):
            fields = line.strip().split()
            if fields and fields[0].lower() == "vertex":
                if len(fields) != 4:
                    raise ValueError("Malformed vertex in ASCII STL")
                points.append(tuple(float(value) for value in fields[1:]))
            if progress is not None and lines and (line_index == len(lines) - 1
                                                    or line_index % max(1, len(lines) // 35) == 0):
                progress(35 * (line_index + 1) // len(lines))
        if not points or len(points) % 3:
            raise ValueError("ASCII STL must contain complete triangle facets")
        facets = [tuple(points[i:i + 3]) for i in range(0, len(points), 3)]
    vertices = []
    triangles = []
    vertex_ids = {}
    for facet_index, facet in enumerate(facets):
        triangle = []
        for point in facet:
            vertex = tuple(map(float, point))
            if not np.isfinite(vertex).all():
                raise ValueError("The STL contains non-finite coordinates")
            if vertex not in vertex_ids:
                vertex_ids[vertex] = len(vertices)
                vertices.append(vertex)
            triangle.append(vertex_ids[vertex])
        triangles.append(tuple(triangle))
        if progress is not None and (facet_index == len(facets) - 1
                                     or facet_index % max(1, len(facets) // 65) == 0):
            progress(35 + 65 * (facet_index + 1) // len(facets))
    return vertices, triangles

def _mesh_face_records(faces, triangles):
    """Give faceted imports without CAD face metadata one selectable curved surface."""
    if faces or not triangles:
        return faces
    return [{"kind": "mesh", "planar": False, "tris": range(len(triangles))}]

def _json_safe_value(value):
    """Convert mesh metadata containers and NumPy values to JSON-native values."""
    if isinstance(value, np.ndarray):
        return [_json_safe_value(item) for item in value.tolist()]
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, dict):
        return {key: _json_safe_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe_value(item) for item in value]
    return value

def _step_real(value):
    text = repr(float(value)).upper()
    if "." in text: return text
    return text.replace("E", ".E") if "E" in text else text + "."

def _step_faceted_text(verts, tris, name="SimpleCAD", progress=None):
    """AP214 STEP text of a closed triangle mesh: one manifold B-rep solid (planar triangle
    faces with shared vertices / edges) per connected component. Linear time, no OCC."""
    V = np.asarray(verts, dtype=float).reshape(-1, 3)
    T = np.asarray(tris, dtype=np.int64).reshape(-1, 3)
    T = T[(T[:, 0] != T[:, 1]) & (T[:, 1] != T[:, 2]) & (T[:, 2] != T[:, 0])]
    if not len(T):
        raise ValueError("STEP export found no non-degenerate faces")
    r = _step_real
    lines = []

    def add(text):
        lines.append(f"#{len(lines) + 1}={text};")
        return len(lines)

    def direction(d):
        return add(f"DIRECTION('',({r(d[0])},{r(d[1])},{r(d[2])}))")

    context = add("APPLICATION_CONTEXT('automotive design')")
    add(f"APPLICATION_PROTOCOL_DEFINITION('international standard','automotive_design',2000,#{context})")
    product_context = add(f"PRODUCT_CONTEXT('',#{context},'mechanical')")
    product = add(f"PRODUCT('{name}','{name}','',(#{product_context}))")
    formation = add(f"PRODUCT_DEFINITION_FORMATION('','',#{product})")
    definition_context = add(f"PRODUCT_DEFINITION_CONTEXT('part definition',#{context},'design')")
    definition = add(f"PRODUCT_DEFINITION('design','',#{formation},#{definition_context})")
    shape = add(f"PRODUCT_DEFINITION_SHAPE('','',#{definition})")
    length = add("(LENGTH_UNIT()NAMED_UNIT(*)SI_UNIT(.MILLI.,.METRE.))")
    angle = add("(NAMED_UNIT(*)PLANE_ANGLE_UNIT()SI_UNIT($,.RADIAN.))")
    solid_angle = add("(NAMED_UNIT(*)SI_UNIT($,.STERADIAN.)SOLID_ANGLE_UNIT())")
    uncertainty = add(f"UNCERTAINTY_MEASURE_WITH_UNIT(LENGTH_MEASURE(1.E-07),#{length},"
                      "'distance_accuracy_value','confusion accuracy')")
    geometry_context = add(
        f"(GEOMETRIC_REPRESENTATION_CONTEXT(3)GLOBAL_UNCERTAINTY_ASSIGNED_CONTEXT((#{uncertainty}))"
        f"GLOBAL_UNIT_ASSIGNED_CONTEXT((#{length},#{angle},#{solid_angle}))"
        "REPRESENTATION_CONTEXT('Context3D','3D Context'))")
    origin = add("CARTESIAN_POINT('',(0.,0.,0.))")
    world = add(f"AXIS2_PLACEMENT_3D('',#{origin},#{direction((0, 0, 1))},#{direction((1, 0, 0))})")

    point_id, vertex_id = {}, {}
    for i in np.unique(T).tolist():
        x, y, z = V[i]
        point_id[i] = add(f"CARTESIAN_POINT('',({r(x)},{r(y)},{r(z)}))")
        vertex_id[i] = add(f"VERTEX_POINT('',#{point_id[i]})")
    if progress is not None: progress(10)

    E = np.sort(np.concatenate([T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]]), axis=1)
    edges, inverse = np.unique(E, axis=0, return_inverse=True)
    inverse = np.asarray(inverse).reshape(3, len(T))
    span = V[edges[:, 1]] - V[edges[:, 0]]
    span_length = np.linalg.norm(span, axis=1)
    unit = span / np.where(span_length < 1e-30, 1.0, span_length)[:, None]
    edge_id = []
    for (a, b), d, L in zip(edges.tolist(), unit, span_length.tolist()):
        vector = add(f"VECTOR('',#{direction(d)},{r(L)})")
        line = add(f"LINE('',#{point_id[a]},#{vector})")
        edge_id.append(add(f"EDGE_CURVE('',#{vertex_id[a]},#{vertex_id[b]},#{line},.T.)"))
    if progress is not None: progress(40)

    # connected components (min-label propagation over triangle vertices)
    labels = np.arange(len(V))
    while True:
        tri_label = labels[T].min(axis=1)
        new = labels.copy()
        np.minimum.at(new, T.ravel(), np.repeat(tri_label, 3))
        new = new[new]
        if np.array_equal(new, labels): break
        labels = new
    component = labels[T[:, 0]]

    corners = V[T]
    normals = np.cross(corners[:, 1] - corners[:, 0], corners[:, 2] - corners[:, 0])
    normal_length = np.linalg.norm(normals, axis=1, keepdims=True)
    normals = np.where(normal_length < 1e-30, (0.0, 0.0, 1.0), normals / np.maximum(normal_length, 1e-30))
    faces = collections.defaultdict(list)
    step = max(1, len(T) // 50)
    for k, (tri, normal) in enumerate(zip(T.tolist(), normals)):
        oriented = []
        for j, (start, end) in enumerate(((tri[0], tri[1]), (tri[1], tri[2]), (tri[2], tri[0]))):
            oriented.append(add(f"ORIENTED_EDGE('',*,*,#{edge_id[inverse[j, k]]},"
                                f"{'.T.' if start < end else '.F.'})"))
        loop = add(f"EDGE_LOOP('',(#{oriented[0]},#{oriented[1]},#{oriented[2]}))")
        bound = add(f"FACE_OUTER_BOUND('',#{loop},.T.)")
        reference = corners[k, 1] - corners[k, 0]
        reference = reference - (reference @ normal) * normal
        if np.linalg.norm(reference) < 1e-30:
            reference = np.cross(normal, (1.0, 0.0, 0.0) if abs(normal[0]) < 0.9 else (0.0, 1.0, 0.0))
        reference = reference / np.linalg.norm(reference)
        placement = add(f"AXIS2_PLACEMENT_3D('',#{point_id[tri[0]]},#{direction(normal)},"
                        f"#{direction(reference)})")
        plane = add(f"PLANE('',#{placement})")
        faces[int(component[k])].append(add(f"ADVANCED_FACE('',(#{bound}),#{plane},.T.)"))
        if progress is not None and k % step == 0:
            progress(40 + 55 * k // len(T))

    solids = []
    for face_ids in faces.values():
        shell = add("CLOSED_SHELL('',(" + ",".join(f"#{i}" for i in face_ids) + "))")
        solids.append(add(f"MANIFOLD_SOLID_BREP('{name}',#{shell})"))
    representation = add("ADVANCED_BREP_SHAPE_REPRESENTATION('',(" +
                         ",".join(f"#{i}" for i in [world] + solids) + f"),#{geometry_context})")
    add(f"SHAPE_DEFINITION_REPRESENTATION(#{shape},#{representation})")
    stamp = datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
    return ("ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION(('SimpleCAD faceted solid'),'2;1');\n"
            f"FILE_NAME('{name}','{stamp}',(''),(''),'SimpleCAD','SimpleCAD','');\n"
            "FILE_SCHEMA(('AUTOMOTIVE_DESIGN { 1 0 10303 214 1 1 1 1 }'));\nENDSEC;\nDATA;\n" +
            "\n".join(lines) + "\nENDSEC;\nEND-ISO-10303-21;\n")

_STEP_STATEMENT = re.compile(r"#(\d+)\s*=\s*([A-Z0-9_]+)\s*\((.*)\)\s*$", re.S)
_STEP_REF = re.compile(r"#(\d+)")

def _read_faceted_step(path, progress=None):
    """Fast reader for STEP files made only of planar faces with straight edges (e.g. our own
    export or mesh-based CAD exports). Returns (vertices, triangles, faces), or None when the
    file needs the full CAD kernel (curved surfaces, curved edges, holes, unusual units)."""
    try:
        with open(path, "r", encoding="latin-1") as stream:
            text = stream.read()
    except OSError:
        return None
    if "DATA;" not in text:
        return None
    if ".METRE." in text and "SI_UNIT(.MILLI.,.METRE.)" not in text.replace(" ", ""):
        return None
    if "CONVERSION_BASED_UNIT" in text and "LENGTH_UNIT" in text.split("CONVERSION_BASED_UNIT", 1)[1][:200]:
        return None
    entities = {}
    for statement in text.split("DATA;", 1)[1].split(";"):
        match = _STEP_STATEMENT.match(statement.strip())
        if match:
            entities[int(match.group(1))] = (match.group(2), match.group(3))
    refs = lambda args: [int(ref) for ref in _STEP_REF.findall(args)]
    face_ids = [key for key, (name, _) in entities.items() if name in ("ADVANCED_FACE", "FACE_SURFACE")]
    if not face_ids:
        return None
    point_index, vertices = {}, []

    def point(ref):
        index = point_index.get(ref)
        if index is None:
            name, args = entities[ref]
            if name != "CARTESIAN_POINT":
                raise KeyError(name)
            coordinates = args[args.index("(", args.index(",")) + 1:args.rindex(")")]
            index = point_index[ref] = len(vertices)
            vertices.append(tuple(float(value) for value in coordinates.split(",")))
        return index

    def vertex(ref):
        name, args = entities[ref]
        return point(refs(args)[0])

    polygons = []           # (vertex indices, plane normal)
    try:
        for count, face_ref in enumerate(face_ids):
            name, args = entities[face_ref]
            face_refs = refs(args)
            if len(face_refs) != 2:
                return None                    # holes / several bounds: use the CAD kernel
            bound_ref, surface_ref = face_refs
            surface_name, surface_args = entities[surface_ref]
            if surface_name != "PLANE":
                return None
            placement = refs(entities[refs(surface_args)[0]][1])
            if len(placement) < 3:
                return None
            normal = np.asarray([float(value) for value in entities[placement[1]][1].split(
                "(", 1)[1].rsplit(")", 1)[0].split(",")], dtype=float)
            if args.rstrip().endswith(".F."):
                normal = -normal
            bound_name, bound_args = entities[bound_ref]
            loop_ref = refs(bound_args)[0]
            if bound_args.rstrip().endswith(".F."):
                return None
            loop_name, loop_args = entities[loop_ref]
            if loop_name == "POLY_LOOP":
                ids = [point(ref) for ref in refs(loop_args)]
            elif loop_name == "EDGE_LOOP":
                ids = []
                for oriented_ref in refs(loop_args):
                    oriented_args = entities[oriented_ref][1]
                    edge_name, edge_args = entities[refs(oriented_args)[0]]
                    start, end, curve = refs(edge_args)[:3]
                    if edge_name != "EDGE_CURVE" or entities[curve][0] != "LINE":
                        return None
                    ids.append(vertex(start if oriented_args.rstrip().endswith(".T.") else end))
            else:
                return None
            if len(ids) >= 3:
                polygons.append((ids, normal))
            if progress is not None and count % max(1, len(face_ids) // 50) == 0:
                progress(60 * count // len(face_ids))
    except (KeyError, IndexError, ValueError):
        return None

    V = np.asarray(vertices, dtype=float)
    triangles, owner = [], []
    for polygon_index, (ids, normal) in enumerate(polygons):
        if len(ids) == 3:
            tris = [tuple(ids)]
        else:
            u = _unit(np.cross(normal, (1.0, 0.0, 0.0) if abs(normal[0]) < 0.9 else (0.0, 1.0, 0.0)))
            v = np.cross(normal, u)
            flat = [((V[i] @ u), (V[i] @ v)) for i in ids]
            order = ids if poly_area(flat) > 0 else ids[::-1]
            flat = flat if poly_area(flat) > 0 else flat[::-1]
            tris = [tuple(order[k] for k in tri) for tri in triangulate_polygon(flat)]
        for a, b, c in tris:
            if float(np.cross(V[b] - V[a], V[c] - V[a]) @ normal) < 0:
                a, b, c = a, c, b
            triangles.append((a, b, c)); owner.append(polygon_index)
    if not triangles:
        return None

    # adjacent coplanar STEP faces become one sketchable planar face
    parent = list(range(len(polygons)))
    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]; i = parent[i]
        return i
    edge_owner = {}
    neighbours = []
    for polygon_index, (ids, normal) in enumerate(polygons):
        offset = float(normal @ V[ids[0]])
        for a, b in zip(ids, ids[1:] + ids[:1]):
            key = (a, b) if a < b else (b, a)
            other = edge_owner.setdefault(key, polygon_index)
            if other != polygon_index:
                other_normal = polygons[other][1]
                neighbours.append((polygon_index, other, float(other_normal @ normal)))
                if float(other_normal @ normal) > 1 - 1e-9 and \
                        abs(float(other_normal @ V[polygons[other][0][0]]) - offset) < 1e-6:
                    parent[find(polygon_index)] = find(other)
    # tessellated curved surfaces: smoothly joined small facets become one curved face
    size = collections.Counter(find(i) for i in range(len(polygons)))
    curved = set()
    smooth = math.cos(math.radians(20.0))
    for first, second, dot in neighbours:
        a, b = find(first), find(second)
        if a != b and dot > smooth and size[a] <= 4 and size[b] <= 4:
            parent[a] = b
            curved.update((a, b))
    curved = {find(i) for i in curved}
    groups = collections.defaultdict(list)
    for polygon_index in range(len(polygons)):
        groups[find(polygon_index)].append(polygon_index)
    tris_of = collections.defaultdict(list)
    for tri_index, polygon_index in enumerate(owner):
        tris_of[polygon_index].append(tri_index)
    faces = []
    for root, members in groups.items():
        member_tris = [t for member in members for t in tris_of[member]]
        if root in curved:
            faces.append({"kind": "STEP", "surface_type": "MESH", "planar": False,
                          "tris": member_tris})
            continue
        normal = _unit(polygons[members[0]][1])
        edge_count = collections.Counter()
        for member in members:
            ids = polygons[member][0]
            for a, b in zip(ids, ids[1:] + ids[:1]):
                edge_count[(a, b) if a < b else (b, a)] += 1
        used = sorted({i for member in members for i in polygons[member][0]})
        origin = V[used].mean(axis=0)
        ref = [1, 0, 0] if abs(normal[0]) < 0.9 else [0, 1, 0]
        u = _unit(np.cross(ref, normal)); v = np.cross(normal, u)
        faces.append({"kind": "STEP", "surface_type": "PLANE", "planar": True,
                      "tris": member_tris,
                      "frame": [p.tolist() for p in (origin, u, v, normal)],
                      "boundary": [["line", V[a].tolist(), V[b].tolist()]
                                   for (a, b), n in edge_count.items() if n == 1]})
    if progress is not None:
        progress(100)
    return vertices, triangles, faces

def _read_step_mesh(path, progress=None):
    """Read a STEP mesh and its sketchable planar faces using CadQuery/OCP."""
    faceted = _read_faceted_step(path, progress)
    if faceted is not None:
        return faceted
    try:
        import cadquery as cq
    except ImportError as ex:
        raise RuntimeError("STEP import requires CadQuery/OCP to be installed") from ex
    if progress is not None:
        progress(None)
    # every shape of the file (Workplane.val() would be the origin Vector when CadQuery
    # transferred nothing, and only the first shape otherwise)
    shapes = [item for item in cq.importers.importStep(path).vals() if hasattr(item, "Faces")]
    source_faces = [face for shape in shapes for face in shape.Faces()]
    if not source_faces:
        raise ValueError("The STEP file contains no solids or surfaces that can be read (it may "
                         "hold only curves, points or an empty assembly structure)")
    shape = shapes[0] if len(shapes) == 1 else cq.Compound.makeCompound(shapes)
    if hasattr(shape, "mesh"):
        shape.mesh(0.1, 0.1)     # mesh all faces in one (parallel) pass; tessellate() reuses it
    if progress is not None:
        progress(0)
    vertices, triangles, faces = [], [], []
    vertex_ids = {}
    face_count = len(source_faces)
    for face_index, face in enumerate(source_faces):
        points, tris = face.tessellate(0.1)
        first_tri = len(triangles)
        face_vertex_ids = []
        for point in points:
            vertex = tuple(map(float, point.toTuple()))
            vertex_id = vertex_ids.get(vertex)
            if vertex_id is None:
                vertex_id = len(vertices)
                vertex_ids[vertex] = vertex_id
                vertices.append(vertex)
            face_vertex_ids.append(vertex_id)
        triangles.extend(tuple(face_vertex_ids[i] for i in tri) for tri in tris)
        planar = face.geomType() == "PLANE"
        info = {"kind": "STEP", "surface_type": face.geomType().upper(), "planar": planar,
                "tris": list(range(first_tri, len(triangles)))}
        if planar:
            origin = np.asarray(face.Center().toTuple(), float)
            normal = _unit(face.normalAt().toTuple())
            ref = [1, 0, 0] if abs(normal[0]) < 0.9 else [0, 1, 0]
            u = _unit(np.cross(ref, normal)); v = np.cross(normal, u)
            info["frame"] = [p.tolist() for p in (origin, u, v, normal)]
            boundary = []
            for edge in face.Edges():
                kind = edge.geomType()
                if kind == "CIRCLE" and edge.IsClosed():
                    boundary.append(["circle", list(edge.arcCenter().toTuple()), edge.radius()])
                elif kind == "CIRCLE":
                    start = np.asarray(edge.positionAt(0).toTuple())
                    mid = np.asarray(edge.positionAt(0.5).toTuple())
                    end = np.asarray(edge.positionAt(1).toTuple())
                    axis = _unit(np.cross(mid - start, end - start))
                    boundary.append(["arc", list(edge.arcCenter().toTuple()),
                                     start.tolist(), end.tolist(), axis.tolist()])
                else:
                    samples, _ = edge.sample(2 if kind == "LINE" else 0.05)
                    if edge.IsClosed() and samples:
                        samples.append(samples[0])
                    boundary.extend(["line", list(a.toTuple()), list(b.toTuple())]
                                    for a, b in zip(samples, samples[1:]))
            info["boundary"] = boundary
        faces.append(info)
        if progress is not None and (face_index == face_count - 1
                                     or face_index % max(1, face_count // 100) == 0):
            progress(100 * (face_index + 1) // face_count)
    if not triangles:
        raise ValueError("The surfaces of the STEP file could not be meshed")
    return vertices, triangles, faces

def _translate_import_faces(faces, offset):
    """Translate face origins and boundary points, leaving directions unchanged."""
    return _transform_import_faces(faces, (0, 0, 0), offset)

def _import_rotation_matrix(rotation):
    """Rotation matrix for X, then Y, then Z angles in degrees."""
    rx, ry, rz = np.radians(np.asarray(rotation, dtype=float))
    sx, cx = math.sin(rx), math.cos(rx)
    sy, cy = math.sin(ry), math.cos(ry)
    sz, cz = math.sin(rz), math.cos(rz)
    rotate_x = np.array(((1, 0, 0), (0, cx, -sx), (0, sx, cx)), dtype=float)
    rotate_y = np.array(((cy, 0, sy), (0, 1, 0), (-sy, 0, cy)), dtype=float)
    rotate_z = np.array(((cz, -sz, 0), (sz, cz, 0), (0, 0, 1)), dtype=float)
    return rotate_z @ rotate_y @ rotate_x

def _import_euler_angles(matrix):
    """X-then-Y-then-Z Euler angles in degrees for _import_rotation_matrix."""
    matrix = np.asarray(matrix, dtype=float)
    sin_y = min(1.0, max(-1.0, -float(matrix[2, 0])))
    angle_y = math.asin(sin_y)
    cos_y = math.cos(angle_y)
    if abs(cos_y) > 1e-8:
        angle_x = math.atan2(matrix[2, 1], matrix[2, 2])
        angle_z = math.atan2(matrix[1, 0], matrix[0, 0])
    else:
        angle_x = 0.0
        angle_z = math.atan2(-matrix[0, 1], matrix[1, 1])
    return [math.degrees(angle_x), math.degrees(angle_y), math.degrees(angle_z)]

def _transform_import_faces(faces, rotation, offset):
    """Rotate imported face geometry and translate its points by offset."""
    result = copy.deepcopy(faces)
    matrix = _import_rotation_matrix(rotation)
    delta = np.asarray(offset, float)
    for face in result:
        if not face["planar"]: continue
        frame = [(matrix @ np.asarray(face["frame"][0], float) + delta).tolist()]
        frame.extend((matrix @ np.asarray(vector, float)).tolist()
                     for vector in face["frame"][1:])
        face["frame"] = frame
        for index, source_primitive in enumerate(face["boundary"]):
            primitive = list(source_primitive)
            point_indices = (1, 2) if primitive[0] == "line" else \
                            (1, 2, 3) if primitive[0] == "arc" else (1,)
            for i in point_indices:
                primitive[i] = (matrix @ np.asarray(primitive[i], float) + delta).tolist()
            if primitive[0] == "arc":
                primitive[4] = (matrix @ np.asarray(primitive[4], float)).tolist()
            face["boundary"][index] = primitive
    return result


# ── error reporting ───────────────────────────────────────────────────────────
# APP_VERSION is defined at the top of this file
RECENT_ERRORS  = collections.deque(maxlen=20)    # uncaught exceptions of this session
RECENT_ACTIONS = collections.deque(maxlen=200)   # status messages ≈ what the user did
ERROR_LISTENERS = []                             # callbacks(etype, value) for new errors
_GL_INFO = []                                    # GL vendor / renderer / version (set in initializeGL)
_SYSINFO_LOGGED = [False]                        # system information written once per session
_CRASH_LOG_FILE = None
_QT_PREVIOUS_HANDLER = None


def _qt_message_handler(kind, context, message):
    """Only Qt critical / fatal messages are errors; debug, info and warnings go to the
    debug log (if enabled)."""
    try:
        if kind in (QtCriticalMsg, QtFatalMsg):
            with open(_ERROR_LOG, "a", encoding="utf-8") as f:
                f.write(f"[{datetime.datetime.now():%Y-%m-%d %H:%M:%S}] Qt error: {message}\n")
        else:
            _dbg(f"Qt: {message}")
    except Exception:
        pass
    if _QT_PREVIOUS_HANDLER is not None:
        _QT_PREVIOUS_HANDLER(kind, context, message)
    elif sys.__stderr__ is not None:
        sys.__stderr__.write(message + "\n")


def _close_crash_logging():
    """Normal exit: stop faulthandler and drop the error log again if nothing was written."""
    global _CRASH_LOG_FILE
    if _CRASH_LOG_FILE is None:
        return
    try:
        faulthandler.disable()
        _CRASH_LOG_FILE.close()
        if os.path.getsize(_ERROR_LOG) == 0:
            os.remove(_ERROR_LOG)
    except OSError:
        pass
    _CRASH_LOG_FILE = None


def install_crash_logging():
    """Native crashes (faulthandler tracebacks) go to the error log. faulthandler needs an
    open file, so the log is held open while the app runs; nothing is written unless the
    process crashes, and an empty log is removed again on exit."""
    global _CRASH_LOG_FILE, _QT_PREVIOUS_HANDLER
    if _CRASH_LOG_FILE is not None:
        return
    try:
        _CRASH_LOG_FILE = open(_ERROR_LOG, "a", encoding="utf-8", buffering=1)
        faulthandler.enable(file=_CRASH_LOG_FILE, all_threads=True)
        _QT_PREVIOUS_HANDLER = qInstallMessageHandler(_qt_message_handler)
        atexit.register(_close_crash_logging)
    except (OSError, RuntimeError):
        if _CRASH_LOG_FILE is not None:
            _CRASH_LOG_FILE.close()
            _CRASH_LOG_FILE = None

def log_action(msg):
    RECENT_ACTIONS.append(f"{datetime.datetime.now():%H:%M:%S}  {msg}")


def _excepthook(etype, value, tb):
    """Uncaught exceptions are recorded in the session list instead of ending the app."""
    text = "".join(traceback.format_exception(etype, value, tb))
    stamp = f"{datetime.datetime.now():%Y-%m-%d %H:%M:%S}"
    RECENT_ERRORS.append(f"[{stamp}]\n{text.rstrip()}")
    try:
        with open(_ERROR_LOG, "a", encoding="utf-8") as f:
            if not _SYSINFO_LOGGED[0]:
                _SYSINFO_LOGGED[0] = True
                f.write("=" * 70 + f"\nSYSTEM INFORMATION (session of {stamp})\n"
                        + "\n".join(system_info()) + "\n" + "=" * 70 + "\n")
            f.write(f"[{stamp}]\n{text.rstrip()}\n")
    except Exception:
        pass
    if sys.__stderr__ is not None: sys.__stderr__.write(text)
    for cb in list(ERROR_LISTENERS):
        try: cb(etype, value)
        except Exception: pass

def install_error_hook():
    if sys.excepthook is not _excepthook: sys.excepthook = _excepthook

def system_info():
    lines = [f"Application : SimpleCAD {APP_VERSION} ({os.path.abspath(__file__)})",
             f"Python      : {sys.version.split()[0]} ({sys_platform.architecture()[0]})",
             f"OS          : {sys_platform.platform()}",
             f"Qt / PyQt   : {QT_VERSION_STR} / {PYQT_VERSION_STR}",
             f"numpy       : {np.__version__}"]
    try:
        import OpenGL; lines.append(f"PyOpenGL    : {OpenGL.__version__}")
    except Exception:
        pass
    return lines + (_GL_INFO or ["OpenGL info : not initialised yet"])

def sketch_summary(sk, indent="  "):
    segs = sum(not s.reference for s in sk.segments)
    sup  = sum(s.construction and not s.reference for s in sk.segments)
    lines = [f"{indent}plane {sk.plane}; lines {segs} (support {sup}), circles {len(sk.circles)}, "
             f"arcs {len(sk.arcs)}, points {len(sk.points_free)}, vertices {len(sk.vertices)}",
             f"{indent}profile closed: {sk.profile_closed()}; constraints {len(sk.constraints)}"]
    try:
        lines[-1] += f"; DOF {sk.total_dof()} (+{sk.optional_dof()} optional)"
    except Exception as ex:
        lines[-1] += f"; DOF unavailable ({type(ex).__name__}: {ex})"
    return lines


# ── MainWindow ────────────────────────────────────────────────────────────────
class _FeatBlendWorker(QThread):
    """Runs _fillet_corner_blends off the UI thread after a fillet is committed."""
    done = pyqtSignal(object, object)   # (entry, blended_mesh)
    def __init__(self, entry, mesh, r):
        super().__init__()
        self._entry = entry; self._mesh = mesh; self._r = r
        self._cancelled = False
    def cancel(self): self._cancelled = True
    def run(self):
        pass  # corner blending disabled

class _BodyMetricsWorker(QThread):
    done = pyqtSignal(object, object)

    def __init__(self, key, entry, objects):
        super().__init__()
        self._key = key
        self._entry = entry
        self.state = {"objects": objects}
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        if self._cancelled:
            return
        try:
            result = MainWindow._body_metrics(self, self._entry)
        except Exception as ex:
            _dbg(f"Body metrics failed: {type(ex).__name__}: {ex}")
            result = (None, None, None)
        if not self._cancelled:
            self.done.emit(self._key, result)


class _FeatPreviewWorker(QThread):
    """Applies existing features + new feature off the UI thread."""
    done = pyqtSignal(object, object)   # (entry_id, result_mesh)
    def __init__(self, entry_id, base_mesh, new_feat, entry=None, others=None):
        super().__init__()
        self._entry_id = entry_id
        self._base = base_mesh
        self._feat = new_feat
        self._entry = entry
        self._others = others
        self._cancelled = False
        self.notes = []          # sizes made smaller to fit (read by the done handler)
    def cancel(self): self._cancelled = True
    def run(self):
        if self._cancelled:
            return
        try:
            if self._feat.get("type") == "thread":
                result = apply_thread_feature(self._base, self._feat)
            else:
                chains = None
                if self._entry is not None:
                    ec = self._entry.get("_ec")
                    key = (id(self._base[0]), id(self._base[1]))
                    chains = ec[1] if ec and ec[0] == key else mesh_edge_chains(*self._base)
                    self._entry["_ec"] = (key, chains)
                result, _ = apply_edge_feature(
                    self._base, self._feat, chains, self._others,
                    clip_outer=bool(self._entry and self._entry.get("type") in
                                    ("extrusion", "imported", "bridge")),
                    notes=self.notes)
            if self._cancelled:
                return
            if result is not None:
                result = _prepare_preview_mesh(result)
        except ValueError as ex:
            result = ex
        except Exception as ex:
            _dbg(f"_FeatPreviewWorker.run: EXCEPTION {type(ex).__name__}: {ex}")
            result = None
        if not self._cancelled:
            self.done.emit(self._entry_id, result)

def smooth_corner_normals(V, T, N, faces, crease_deg=40.0, tangent_deg=20.0):
    """Shading normals per triangle corner, shape (len(T)*3, 3) float32, for a lit mesh.
    Planar faces stay flat. Curved faces (fillets, cylinders, ...) are shaded smoothly: the
    corner normal is the area-weighted average of the face's triangles at that vertex (never
    across a crease of more than crease_deg). Where a curved face meets a planar face tangentially
    (within tangent_deg, e.g. the end of a fillet) the corner takes the planar normal so the
    shading continues without a visible step. Geometry and triangle count are unchanged."""
    N = np.asarray(N, np.float32); m = len(T)
    flat = np.repeat(N, 3, axis=0)
    if not m or not faces: return flat
    try:
        T = np.asarray(T, np.int64).reshape(-1, 3)
        tri_face = np.full(m, -1, np.int64); curved = np.zeros(m, bool)
        for fi, f in enumerate(faces):
            tr = np.asarray(f.get("tris", ()), np.int64)
            tr = tr[(tr >= 0) & (tr < m)]
            tri_face[tr] = fi
            if not f.get("planar", False): curved[tr] = True
        if not curved.any(): return flat
        V = np.asarray(V, np.float64)
        W = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])    # area-weighted normals
        cv = T.ravel(); ct = np.repeat(np.arange(m), 3)
        sc = np.nonzero(curved[ct])[0]                                    # curved-face corners
        key = cv[sc]*(len(faces) + 1) + tri_face[ct[sc]]
        _, inv = np.unique(key, return_inverse=True)
        S = np.stack([np.bincount(inv, weights=W[ct[sc], k]) for k in range(3)], axis=1)
        S /= np.maximum(np.linalg.norm(S, axis=1, keepdims=True), 1e-30)
        out = flat.copy()
        sn = S[inv]
        ok = (sn*N[ct[sc]]).sum(axis=1) >= math.cos(math.radians(crease_deg))
        out[sc[ok]] = sn[ok].astype(np.float32)
        # tangent joint with a planar face: continue that face's normal
        planar_c = np.nonzero(~curved[ct] & (tri_face[ct] >= 0))[0]
        joint = np.isin(cv[planar_c], np.unique(cv[sc]))
        at_vertex = {}
        for c in planar_c[joint]:
            at_vertex.setdefault(int(cv[c]), {})[int(tri_face[ct[c]])] = N[ct[c]]
        cos_t = math.cos(math.radians(tangent_deg))
        if at_vertex:
            near = sc[ok][np.isin(cv[sc[ok]], np.fromiter(at_vertex, np.int64, len(at_vertex)))]
            for c in near:
                for pn in at_vertex[int(cv[c])].values():
                    if float(pn @ out[c]) > cos_t:
                        out[c] = pn; break
        return out
    except Exception:
        return flat

def _sharp_edge_data(V, T, N):
    """Flat float32 array of the line end points of the sharp / open edges of a triangle mesh
    (V (n,3) float32, T (m,3) ints, N (m,3) triangle normals); None if there are none."""
    keys = np.concatenate([T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]]).astype(np.int64)
    keys.sort(axis=1)
    tri_of = np.tile(np.arange(len(T)), 3)
    code = keys[:, 0]*(len(V) + 1) + keys[:, 1]
    order = np.argsort(code, kind="stable")
    code_s = code[order]; tri_s = tri_of[order]; ek = keys[order]
    first = np.r_[True, code_s[1:] != code_s[:-1]]
    gstart = np.nonzero(first)[0]; gcnt = np.diff(np.r_[gstart, len(code_s)])
    draw = gcnt != 2                                      # open / non-manifold edges
    two = np.nonzero(gcnt == 2)[0]
    if len(two):
        s = gstart[two]
        draw[two] = np.einsum("ij,ij->i", N[tri_s[s]], N[tri_s[s + 1]]) < 0.94   # creases
    ev = ek[gstart[draw]]
    return V[ev.ravel()].astype(np.float32).ravel() if len(ev) else None

def _prepare_preview_mesh(mesh):
    vertices, triangles, faces = mesh
    vertices = np.asarray(vertices, dtype=np.float32).reshape(-1, 3)
    triangles = np.asarray(triangles, dtype=np.int32).reshape(-1, 3)
    first = vertices[triangles[:, 0]]
    normals = np.cross(vertices[triangles[:, 1]] - first,
                       vertices[triangles[:, 2]] - first).astype(np.float32)
    lengths = np.linalg.norm(normals, axis=1, keepdims=True)
    normals /= np.where(lengths < 1e-12, 1.0, lengths)
    corner_normals = smooth_corner_normals(vertices, triangles, normals, faces)
    data = np.hstack([corner_normals, vertices[triangles.ravel()]]).astype(np.float32).ravel()
    edges = _sharp_edge_data(vertices, triangles, normals) if len(triangles) else None
    return {"mesh": mesh, "vbo_data": data, "edge_data": edges}

CUT_BREAKTHROUGH = 0.1   # mm a cut "up to surface" runs past a surface where it leaves the material

def _ray_nearest(origins, d, V, T, eps=1e-4, chunk=24, facing=0):
    """First hit distance t > eps of the rays origin + t*d with the triangle mesh (V, T);
    inf where a ray misses. origins (k,3), d unit (3,). facing +1 only counts triangles the
    ray leaves the (outward-oriented) solid through, -1 only those it enters through."""
    O = np.asarray(origins, float).reshape(-1, 3)
    out = np.full(len(O), np.inf)
    T = np.asarray(T, int).reshape(-1, 3)
    if not len(T): return out
    V = np.asarray(V, float)
    if facing:
        n = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])
        T = T[(n @ np.asarray(d, float))*facing > 0]
        if not len(T): return out
    v0 = V[T[:, 0]]; e1 = V[T[:, 1]] - v0; e2 = V[T[:, 2]] - v0
    h = np.cross(d, e2); a = np.einsum("ij,ij->i", e1, h)
    ok = np.abs(a) > 1e-12
    f = np.where(ok, 1.0/np.where(ok, a, 1.0), 0.0)
    for s in range(0, len(O), chunk):
        o = O[s:s+chunk]
        sv = o[:, None, :] - v0[None]                         # (c, m, 3)
        u = f[None]*np.einsum("cmj,mj->cm", sv, h)
        q = np.cross(sv, e1[None])
        v = f[None]*(q @ d)
        t = f[None]*np.einsum("mj,cmj->cm", e2, q)
        hit = ok[None] & (u >= -1e-9) & (v >= -1e-9) & (u + v <= 1 + 1e-9) & (t > eps)
        out[s:s+chunk] = np.where(hit, t, np.inf).min(axis=1)
    return out

def _pts_touch_mesh(P, V, T, tol):
    """Does any point of P lie on (or inside the tolerance of) a triangle of the mesh?"""
    V = np.asarray(V, float); T = np.asarray(T, int).reshape(-1, 3)
    if not len(P) or not len(T): return False
    v0 = V[T[:, 0]]; e1 = V[T[:, 1]] - v0; e2 = V[T[:, 2]] - v0
    n = np.cross(e1, e2); ln = np.linalg.norm(n, axis=1); ok = ln > 1e-12
    n = n[ok]/ln[ok][:, None]; v0 = v0[ok]; e1 = e1[ok]; e2 = e2[ok]
    d11 = np.einsum("ij,ij->i", e1, e1); d12 = np.einsum("ij,ij->i", e1, e2); d22 = np.einsum("ij,ij->i", e2, e2)
    den = d11*d22 - d12*d12; den = np.where(np.abs(den) < 1e-18, 1e-18, den)
    for s in range(0, len(P), 64):
        w = P[s:s+64, None, :] - v0[None]                      # (c, m, 3)
        dist = np.abs(np.einsum("cmj,mj->cm", w, n))
        w1 = np.einsum("cmj,mj->cm", w, e1); w2 = np.einsum("cmj,mj->cm", w, e2)
        b1 = (d22*w1 - d12*w2)/den; b2 = (d11*w2 - d12*w1)/den
        slack = tol/np.sqrt(np.maximum(d11, 1e-12))
        inside = (b1 >= -slack) & (b2 >= -slack) & (b1 + b2 <= 1 + 2*slack)
        if np.any((dist <= tol) & inside): return True
    return False

def bodies_touch(a, b, tol=1e-3):
    """Do two solids (verts, tris) touch or overlap? Bounding boxes must meet with a contact
    area (or volume); contact by area is confirmed on the surfaces themselves."""
    A = np.asarray(a[0], float); B = np.asarray(b[0], float)
    if not len(A) or not len(B): return False
    lo = np.maximum(A.min(0), B.min(0)); hi = np.minimum(A.max(0), B.max(0))
    inter = hi - lo
    if np.any(inter < -tol): return False
    if np.count_nonzero(inter > tol) < 2: return False
    lo -= tol; hi += tol
    pa = A[np.all((A >= lo) & (A <= hi), axis=1)]; pb = B[np.all((B >= lo) & (B <= hi), axis=1)]
    return _pts_touch_mesh(pa, B, b[1], tol) or _pts_touch_mesh(pb, A, a[1], tol) or \
           bool(np.count_nonzero(inter > tol) == 3)

def halfspace_box(P0, r, center, size):
    """Large box on the side of the plane (P0, normal r) that r points to (a tool body that
    trims an extrusion at a plane). Returns (verts, tris, faces)."""
    r = _unit(r)
    a1 = _unit(np.cross(r, [1.0, 0.0, 0.0]) if abs(r[0]) < 0.9 else np.cross(r, [0.0, 1.0, 0.0]))
    a2 = np.cross(r, a1)
    cen = np.asarray(center, float); P0 = np.asarray(P0, float)
    c0 = cen - r*((cen - P0) @ r)               # centre projected onto the plane
    verts = []
    for sr in (0.0, 1.0):
        for s1 in (-1, 1):
            for s2 in (-1, 1):
                verts.append(tuple(float(x) for x in c0 + r*size*sr + a1*size*s1 + a2*size*s2))
    quads = [(0, 1, 3, 2), (4, 6, 7, 5), (0, 4, 5, 1), (2, 3, 7, 6), (0, 2, 6, 4), (1, 5, 7, 3)]
    tris = [t for q in quads for t in ((q[0], q[1], q[2]), (q[0], q[2], q[3]))]
    if mesh_volume(verts, tris) < 0: tris = [(a, c, b) for a, b, c in tris]
    return verts, tris, [{"kind": "end", "tris": list(range(len(tris))), "planar": False}]

# ── Cut Surface: hides one side of an extrusion behind a movable plane ───────────
SECTION_FACE_LABEL = "section "      # csg label: the face a cut surface creates is "section end"

def cut_surface_frame(position, rotation):
    """(origin, u, v, normal) of a Cut Surface: world XYZ position, rotation about X, then Y,
    then Z in degrees (the same convention as imported models and the assembly)."""
    matrix = _import_rotation_matrix(rotation)
    return (np.asarray(position, float), matrix[:, 0], matrix[:, 1], matrix[:, 2])

def cut_plane_handle_specs(entry, position_controls, rotation_controls):
    """Drag handle specs of a Cut Surface plane {position, rotation}: X / Y / Z move arrows
    and rotation rings that drive the given fields. The angles apply X, then Y, then Z, so
    the world axis each ring turns about is X -> Rz*Ry*e_x, Y -> Rz*e_y, Z -> e_z."""
    anchor = np.asarray(entry["position"], float)
    specs = [(anchor, np.eye(3)[index], position_controls[index],
              "Move Cut Surface along " + "XYZ"[index], " mm", 1.0, None, "axis_" + "xyz"[index])
             for index in range(3)]
    rx, ry, rz = (float(value) for value in entry["rotation"])
    turn_z = _import_rotation_matrix((0.0, 0.0, rz))
    turn_zy = turn_z @ _import_rotation_matrix((0.0, ry, 0.0))
    for index, axis in enumerate((turn_zy[:, 0], turn_z[:, 1], np.array([0.0, 0.0, 1.0]))):
        axis = _unit(np.asarray(axis, float))
        # the ring lies in the plane perpendicular to the axis; its angle grows
        # counter-clockwise about +axis, the way the rotation field grows
        helper = np.eye(3)[int(np.argmin(np.abs(axis)))]
        arm = _unit(np.cross(axis, helper))
        ring = {"center": anchor, "u": arm, "v": np.cross(axis, arm), "start": 20.0, "stop": 290.0}
        specs.append((anchor, axis, rotation_controls[index],
                      "Rotate Cut Surface around " + "XYZ"[index], "°", 1.0, ring,
                      "axis_" + "xyz"[index]))
    return specs

def cut_surface_signature(entry):
    """Everything that influences the geometry a Cut Surface produces (cache key)."""
    return json.dumps([[float(x) for x in entry.get("position", (0, 0, 0))],
                       [float(x) for x in entry.get("rotation", (0, 0, 0))],
                       bool(entry.get("flip")), bool(entry.get("split"))])

def join_mesh_pieces(pieces):
    """One mesh (verts, tris, faces) of several separate meshes: the vertices / triangles are
    appended and each face's triangle indices shifted. Piece 0 keeps its face numbers."""
    verts, tris, faces = [], [], []
    for piece_verts, piece_tris, piece_faces in pieces:
        vertex_offset, tri_offset = len(verts), len(tris)
        verts += [tuple(point) for point in piece_verts]
        tris += [(a + vertex_offset, b + vertex_offset, c + vertex_offset)
                 for a, b, c in piece_tris]
        faces += [dict(face, tris=[index + tri_offset for index in face.get("tris", ())])
                  for face in piece_faces]
    return verts, tris, faces

def apply_cut_surfaces(mesh, sections, key=()):
    """The Cut Surfaces applied one after the other to mesh = (verts, tris, faces). A plain
    Cut Surface removes one side of every piece; one with `split` keeps both sides as separate
    pieces (the side it would keep first). Returns [(side key, piece)] of the non-empty pieces;
    the side key names the splitting Cut Surfaces the piece lies on the other side of (empty =
    the main part). The first piece has the face numbering of the uncut body."""
    pieces = [(tuple(key), mesh)]
    for section in sections:
        result = []
        for piece_key, piece in pieces:
            parts = [(piece_key, apply_cut_surface(piece, section))]
            if section.get("split"):
                parts.append((tuple(sorted(piece_key + (section.get("name", "cut"),))),
                              apply_cut_surface(piece, dict(section, flip=not section.get("flip")))))
            result += [part for part in parts if len(part[1][1])]
        pieces = result
    return pieces

def mesh_pieces_keyed(entry):
    """The separate solids of a body as [(side key, (verts, tris, faces))]: the pieces
    splitting Cut Surfaces made (see apply_cut_surfaces), otherwise [((), the body)]."""
    pieces = entry.get("_pieces")      # (the joined vertex list they belong to, keys, pieces)
    if pieces and pieces[0] is entry["solid"][0]:
        return list(zip(pieces[1], pieces[2]))
    return [((), (entry["solid"][0], entry["solid"][1], entry.get("faces", [])))]

def mesh_pieces_of(entry):
    """The separate solids of a body as [(verts, tris, faces)]."""
    return [piece for _, piece in mesh_pieces_keyed(entry)]

def _earcut_loops(outer, holes):
    """Earcut of an outer 2-D polygon with holes (any orientation). Returns CCW index triples
    into outer + holes (concatenated). Collinear points may be left out of the triangles."""
    def area(poly):
        return 0.5 * sum(a[0]*b[1] - b[0]*a[1] for a, b in zip(poly, poly[1:] + poly[:1]))
    outer = list(outer) if area(list(outer)) > 0 else list(outer)[::-1]
    holes = [list(h) if area(list(h)) < 0 else list(h)[::-1] for h in holes]
    pts = list(outer); starts = []
    for hole in holes:
        starts.append(len(pts)); pts += hole
    outer_node = _ec_ring(outer, 0)
    queue = []
    for start, hole in zip(starts, holes):
        ring = _ec_ring(hole, start)
        if ring is ring.next: ring.steiner = True
        left = ring; p = ring.next
        while p is not ring:
            if p.x < left.x or (p.x == left.x and p.y < left.y): left = p
            p = p.next
        queue.append(left)
    queue.sort(key=lambda n: n.x)
    for hole in queue:
        bridge = _ec_bridge(hole, outer_node)
        if bridge is None: continue
        rev = _ec_split(bridge, hole)
        _ec_filter(rev, rev.next)
        outer_node = _ec_filter(bridge, bridge.next)
    out = []
    _ec_linked(_ec_filter(outer_node), out, 0)
    result = []
    for a, b, c in out:
        (ax, ay), (bx, by), (cx, cy) = pts[a], pts[b], pts[c]
        cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
        if abs(cross) < 1e-18: continue
        result.append((a, b, c) if cross > 0 else (a, c, b))
    return result, pts, outer, holes

def _repair_t_junctions(points, tris, tri_face, tolerance, max_passes=500):
    """Close open seams caused by T-junctions: a triangle edge used only once that has
    endpoints of other open edges lying on it is split there (the triangle becomes a fan).
    Returns (tris, tri_face)."""
    P = np.asarray(points, float)
    tris = [tuple(t) for t in tris]; tri_face = list(tri_face)
    for _ in range(max_passes):
        undirected = {}
        for index, (a, b, c) in enumerate(tris):
            for x, y in ((a, b), (b, c), (c, a)):
                undirected.setdefault((min(x, y), max(x, y)), []).append((index, x, y))
        open_edges = [uses[0] for uses in undirected.values() if len(uses) % 2]
        if not open_edges:
            break
        open_vertices = np.array(sorted({v for _, x, y in open_edges for v in (x, y)}), np.int64)
        changed = False
        for index, a, b in open_edges:
            start, end = P[a], P[b]
            span = end - start
            length2 = float(span @ span)
            if length2 < 1e-30:
                continue
            candidates = open_vertices[(open_vertices != a) & (open_vertices != b)]
            if not len(candidates):
                continue
            offset = P[candidates] - start
            along = offset @ span / length2
            distance = np.linalg.norm(offset - along[:, None] * span, axis=1)
            inside = (along > 1e-9) & (along < 1 - 1e-9) & (distance <= tolerance)
            if not inside.any():
                continue
            order = np.argsort(along[inside])
            chain = [a] + candidates[inside][order].tolist() + [b]
            tri = tris[index]
            apex = next(v for v in tri if v not in (a, b))
            face = tri_face[index]
            fan = [(chain[k], chain[k + 1], apex) for k in range(len(chain) - 1)]
            tris[index] = fan[0]
            tris += fan[1:]; tri_face += [face] * (len(fan) - 1)
            changed = True
            break
        if not changed:
            break
    return tris, tri_face

# the 27 grid cells around a cell (the own cell first)
_NEIGHBOUR_CELLS = [np.array(offset, np.int64) for offset in
                    sorted(((i, j, k) for i in (-1, 0, 1) for j in (-1, 0, 1) for k in (-1, 0, 1)),
                           key=lambda offset: sum(map(abs, offset)))]

def clip_mesh_by_plane(mesh, origin, normal):
    """Keep the part of a triangle mesh on the -normal side of the plane (origin, normal) and
    close it with a planar cap face. A single linear pass instead of a general boolean.
    Tolerant of what booleans leave behind: unused or duplicate vertices and T-junctions (cut
    points at the same place are merged) and small gaps in the cut outline of a not quite
    closed mesh (bridged straight). Returns (verts, tris, faces, cap_face_index); the cap face
    is empty when the plane crosses no triangle."""
    verts, tris, faces = mesh
    V = np.asarray(verts, float).reshape(-1, 3)
    T = np.asarray(tris, np.int64).reshape(-1, 3)
    normal = _unit(normal)
    span = float(np.ptp(V, axis=0).max()) if len(V) else 1.0
    eps = 1e-9 + 1e-7 * span
    d = V @ normal - float(np.asarray(origin, float) @ normal)
    # no vertex may lie on the plane: shift the plane a hair (far below drawing precision)
    for k in range(1, 60):
        if not np.any(np.abs(d) < eps): break
        d = d - eps * 2.5 * k * (1 if k % 2 else -1)
    hidden = d > 0
    count = hidden[T].sum(axis=1)
    tri_face = np.full(len(T), -1, np.int64)
    for fi, face in enumerate(faces):
        if face.get("tris"):
            tri_face[np.asarray(face["tris"], np.int64)] = fi
    new_points = []; edge_point = {}; point_at = {}
    base = len(V)
    quantum = 1e-6 * span + 1e-12

    def cut_point(a, b):
        key = (a, b) if a < b else (b, a)
        index = edge_point.get(key)
        if index is None:
            t = d[a] / (d[a] - d[b])
            point = V[a] + (V[b] - V[a]) * t
            # cut points at the same place (duplicate vertices, T-junctions) are one point; the
            # neighbouring grid cells count too (two almost equal points can round apart)
            cell = np.round(point / quantum).astype(np.int64)
            index = None
            for offset in _NEIGHBOUR_CELLS:
                candidate = point_at.get(tuple((cell + offset).tolist()))
                if candidate is not None and \
                        float(np.abs(new_points[candidate - base] - point).max()) <= quantum:
                    index = candidate
                    break
            if index is None:
                new_points.append(point)
                index = point_at[tuple(cell.tolist())] = base + len(new_points) - 1
            edge_point[key] = index
        return index

    out_tris = [tuple(t) for t in T[count == 0].tolist()]
    out_face = tri_face[count == 0].tolist()
    next_point = {}                          # directed cap outline: start -> end
    for k in np.flatnonzero((count == 1) | (count == 2)).tolist():
        tri = T[k].tolist(); h = [bool(hidden[i]) for i in tri]
        odd = next(j for j in range(3) if h[j] != h[(j + 1) % 3] and h[j] != h[(j + 2) % 3])
        a, b, c = tri[odd], tri[(odd + 1) % 3], tri[(odd + 2) % 3]
        pab, pac = cut_point(a, b), cut_point(a, c)
        face = int(tri_face[k])
        if count[k] == 1:                    # a hidden: the kept part is a quad
            out_tris += [(pab, b, c), (pab, c, pac)]; out_face += [face, face]
            start, end = pab, pac
        else:                                # a kept: the kept part is a triangle
            out_tris.append((a, pab, pac)); out_face.append(face)
            start, end = pac, pab
        if start != end and start not in next_point:     # (non-manifold spots: first wins)
            next_point[start] = end
    all_points = np.vstack([V, np.asarray(new_points, float).reshape(-1, 3)])
    # chain the outline into loops; chains that stay open (a not quite closed mesh) are
    # joined across small gaps
    loops, chains, seen = [], [], set()
    targets = set(next_point.values())
    for first in [p for p in next_point if p not in targets] + list(next_point):
        if first in seen: continue
        chain, point = [], first
        while point is not None and point not in seen:
            seen.add(point); chain.append(point)
            point = next_point.get(point)
        if point == first and len(chain) >= 3: loops.append(chain)
        elif len(chain) >= 2: chains.append(chain)
    gap_limit = 0.05 * span
    while chains:
        chain = chains.pop(0)
        while True:
            end = all_points[chain[-1]]
            closing = float(np.linalg.norm(end - all_points[chain[0]]))
            best = min(((float(np.linalg.norm(end - all_points[other[0]])), k)
                        for k, other in enumerate(chains)), default=None)
            if best is not None and best[0] < closing and best[0] <= gap_limit:
                chain = chain + chains.pop(best[1])
                continue
            if closing <= gap_limit and len(chain) >= 3: loops.append(chain)
            break
    helper = np.eye(3)[int(np.argmin(np.abs(normal)))]
    u = _unit(np.cross(helper, normal)); v = np.cross(normal, u)       # u x v = normal
    flat = [[(float(all_points[i] @ u), float(all_points[i] @ v)) for i in loop] for loop in loops]
    areas = [abs(0.5 * sum(p[0]*q[1] - q[0]*p[1] for p, q in zip(f, f[1:] + f[:1]))) for f in flat]
    depth = [sum(1 for j in range(len(loops)) if j != i and areas[j] > areas[i] and
                 _pt_in_poly(flat[i][0], flat[j])) for i in range(len(loops))]
    cap = []
    for i in range(len(loops)):
        if depth[i] % 2: continue
        holes = [j for j in range(len(loops)) if depth[j] == depth[i] + 1 and
                 areas[j] < areas[i] and _pt_in_poly(flat[j][0], flat[i])]
        ids = [list(loops[i])] + [list(loops[j]) for j in holes]
        triangles, _, outer2d, holes2d = _earcut_loops(flat[i], [flat[j] for j in holes])
        # the vertex ids in the order earcut used them (each loop possibly reversed)
        oriented = [ids[0] if outer2d == flat[i] else ids[0][::-1]]
        for g, j in enumerate(holes):
            oriented.append(ids[g + 1] if holes2d[g] == flat[j] else ids[g + 1][::-1])
        lookup = [vid for loop in oriented for vid in loop]
        tris_ids = [[lookup[a], lookup[b], lookup[c]] for a, b, c in triangles]
        # earcut may skip collinear outline points: split the triangle on that edge so the
        # cap shares every outline vertex with the side faces (the body stays watertight)
        edge_tri = {}
        for t_index, t in enumerate(tris_ids):
            for e in range(3):
                edge_tri[(t[e], t[(e + 1) % 3])] = t_index
        used = {vid for t in tris_ids for vid in t}
        for loop in oriented:
            if all(vid in used for vid in loop): continue
            n = len(loop)
            first_used = next((p for p in range(n) if loop[p] in used), None)
            if first_used is None: continue
            p = first_used
            for _ in range(n):
                q = (p + 1) % n; skipped = []
                while loop[q] not in used:
                    skipped.append(loop[q]); q = (q + 1) % n
                a_id, b_id = loop[p], loop[q]
                chain = [a_id] + skipped + [b_id]
                t_index = edge_tri.get((a_id, b_id)) if skipped else None
                if skipped and t_index is None:         # the triangle runs the other way
                    t_index = edge_tri.get((b_id, a_id))
                    if t_index is not None:
                        a_id, b_id = b_id, a_id; chain = chain[::-1]
                if t_index is not None:                 # (none: leave that spot unrepaired)
                    t = tris_ids[t_index]; e = t.index(a_id); apex = t[(e + 2) % 3]
                    fan = [[chain[m], chain[m + 1], apex] for m in range(len(chain) - 1)]
                    tris_ids[t_index] = fan[0]
                    for extra in fan[1:]:
                        tris_ids.append(extra)
                    for t_new_index in [t_index] + list(range(len(tris_ids) - len(fan) + 1,
                                                              len(tris_ids))):
                        t_new = tris_ids[t_new_index]
                        for e2 in range(3):
                            edge_tri[(t_new[e2], t_new[(e2 + 1) % 3])] = t_new_index
                    used.update(skipped)
                p = q
                if p == first_used: break
        cap += [tuple(t) for t in tris_ids]
    # orient the cap outward (+normal)
    C = np.asarray(cap, np.int64).reshape(-1, 3)
    P0, P1, P2 = all_points[C[:, 0]], all_points[C[:, 1]], all_points[C[:, 2]]
    outward = np.cross(P1 - P0, P2 - P0) @ normal >= 0
    C[~outward] = C[~outward][:, [0, 2, 1]]
    oriented_cap = [tuple(t) for t in C.tolist()]
    cap_index = len(faces)
    all_tris = out_tris + oriented_cap
    all_face = out_face + [cap_index] * len(oriented_cap)
    # cut points merged with each other (a vertex on the plane) leave triangles like (p, c, p):
    # they have no area and their two real edges cancel, so dropping them keeps the mesh closed
    # (and STEP export accepts it)
    keep = [len({a, b, c}) == 3 for a, b, c in all_tris]
    if not all(keep):
        all_tris = [t for t, ok in zip(all_tris, keep) if ok]
        all_face = [fi for fi, ok in zip(all_face, keep) if ok]
    # an earlier cut can leave nearly equal points on this cut's outline; open seams that
    # remain are T-junctions: split the triangle edge at the points lying on it
    if not _mesh_is_closed(all_tris):
        all_tris, all_face = _repair_t_junctions(all_points, all_tris, all_face,
                                                 1e-5 * span + 1e-9)
    # drop vertices that are no longer used and renumber
    flat_ids = np.asarray(all_tris, np.int64).reshape(-1, 3)
    used_ids, inverse = np.unique(flat_ids.ravel(), return_inverse=True)
    new_tris = [tuple(t) for t in inverse.reshape(-1, 3).tolist()]
    new_verts = [tuple(p) for p in all_points[used_ids].tolist()]
    new_faces = [dict(face, tris=[]) for face in faces]
    new_faces.append({"kind": SECTION_FACE_LABEL + "end", "planar": False, "tris": []})
    for t_index, fi in enumerate(all_face):
        if fi >= 0: new_faces[fi]["tris"].append(t_index)
    return new_verts, new_tris, new_faces, cap_index

def apply_cut_surface(mesh, entry):
    """Hide the part of mesh = (verts, tris, faces) lying on the side the Cut Surface's normal
    points to (the opposite side with `flip`). The remaining part is closed by a section face
    (kind "section end", `section` = the plane frame) that is drawn shaded."""
    origin, u, v, normal = cut_surface_frame(entry.get("position", (0, 0, 0)),
                                             entry.get("rotation", (0, 0, 0)))
    if entry.get("flip"): normal = -normal
    return cut_mesh_by_plane(mesh, origin, normal, u, v)

def _mesh_component_labels(T):
    """Label (smallest vertex index) of the connected part each triangle of T (m, 3) belongs
    to; triangles are connected through shared vertex indices."""
    labels = np.arange(int(T.max()) + 1)
    while True:
        tri_label = labels[T].min(axis=1)
        new = labels.copy()
        np.minimum.at(new, T.ravel(), np.repeat(tri_label, 3))
        new = new[new]
        if np.array_equal(new, labels):
            break
        labels = new
    return labels[T[:, 0]]

def cut_mesh_by_plane(mesh, origin, normal, u=None, v=None):
    """Remove the part of mesh = (verts, tris, faces) on the +normal side of the plane through
    origin and close the rest with a section face (`section` = (origin, u, v, normal)).
    A mesh of several separate solids (e.g. an imported STEP whose solids touch) is cut solid by
    solid: cut points of touching solids would otherwise merge and break the cut outline. The
    face numbering stays; all section faces become one face at the end."""
    verts, tris, faces = mesh
    if not len(tris): return mesh
    origin = np.asarray(origin, float)
    normal = _unit(np.asarray(normal, float))
    if u is None or v is None:
        helper = np.eye(3)[int(np.argmin(np.abs(normal)))]
        u = _unit(np.cross(helper, normal)); v = np.cross(normal, u)
    T = np.asarray(tris, np.int64).reshape(-1, 3)
    distance = (np.asarray(verts, float).reshape(-1, 3)[np.unique(T.ravel())] - origin) @ normal
    if float(distance.max()) <= 1e-6:             # the plane does not touch the body: unchanged
        return mesh
    if float(distance.min()) >= -1e-6:            # everything lies on the removed side
        return [], [], [dict(face, tris=[]) for face in faces]
    component = _mesh_component_labels(T)
    groups = np.unique(component)
    if len(groups) > 1:
        tri_face = np.full(len(T), -1, np.int64)
        for fi, face in enumerate(faces):
            if face.get("tris"):
                tri_face[np.asarray(face["tris"], np.int64)] = fi
        out_verts, out_tris, face_tris, cap_tris = [], [], [[] for _ in faces], []
        section = None
        for label in groups.tolist():
            rows = np.flatnonzero(component == label)
            sub_faces = [dict(face, tris=[]) for face in faces]
            for new_index, row in enumerate(rows.tolist()):
                if tri_face[row] >= 0:
                    sub_faces[tri_face[row]]["tris"].append(new_index)
            part = _cut_mesh_by_plane_single((verts, T[rows].tolist(), sub_faces),
                                             origin, normal, u, v)
            part_verts, part_tris, part_faces = part
            if not len(part_tris):
                continue
            if len(part_faces) not in (len(faces), len(faces) + 1):
                return _cut_mesh_by_plane_single(mesh, origin, normal, u, v)   # (fallback)
            vertex_offset, tri_offset = len(out_verts), len(out_tris)
            out_verts += [tuple(point) for point in part_verts]
            out_tris += [(a + vertex_offset, b + vertex_offset, c + vertex_offset)
                         for a, b, c in part_tris]
            for fi in range(len(faces)):
                face_tris[fi] += [index + tri_offset for index in part_faces[fi].get("tris", ())]
            if len(part_faces) == len(faces) + 1:
                cap_tris += [index + tri_offset for index in part_faces[-1].get("tris", ())]
                section = part_faces[-1].get("section", section)
        if not out_tris:
            return [], [], [dict(face, tris=[]) for face in faces]
        # drop the vertices no part uses (each part carried the whole vertex list)
        flat = np.asarray(out_tris, np.int64).reshape(-1, 3)
        used, inverse = np.unique(flat.ravel(), return_inverse=True)
        out_tris = [tuple(t) for t in inverse.reshape(-1, 3).tolist()]
        out_verts = [out_verts[i] for i in used.tolist()]
        out_faces = [dict(face, tris=face_tris[fi]) for fi, face in enumerate(faces)]
        if cap_tris:
            out_faces.append({"kind": SECTION_FACE_LABEL + "end", "planar": False,
                              "tris": cap_tris, "section": section})
        return out_verts, out_tris, out_faces
    return _cut_mesh_by_plane_single(mesh, origin, normal, u, v)

def _cut_mesh_by_plane_single(mesh, origin, normal, u, v):
    """cut_mesh_by_plane for one connected solid."""
    verts, tris, faces = mesh
    if not len(tris): return mesh
    V = np.asarray(verts, float).reshape(-1, 3)
    V = V[np.unique(np.asarray(tris, np.int64).ravel())]   # booleans may leave unused vertices
    distance = (V - origin) @ normal
    tolerance = 1e-6
    if float(distance.max()) <= tolerance:        # the plane does not touch the body: unchanged
        return mesh
    if float(distance.min()) >= -tolerance:       # everything lies on the hidden side
        return [], [], [dict(face, tris=[]) for face in faces]
    frame = (origin, np.asarray(u, float), np.asarray(v, float), normal)
    clipped = clip_mesh_by_plane(mesh, origin, normal)          # fast path (closed meshes)
    if clipped is not None:
        new_verts, new_tris, new_faces, cap = clipped
        new_faces[cap]["section"] = frame
        return new_verts, new_tris, new_faces
    _dbg("cut surface: plane clip needs closed loops, using the general boolean")
    low, high = V.min(0), V.max(0)
    size = float(np.linalg.norm(high - low)) + float(np.linalg.norm(origin - (low + high) / 2.0)) + 10.0
    tool = halfspace_box(origin, normal, (low + high) / 2.0, size)
    result = csg_subtract(mesh, [tool], label=SECTION_FACE_LABEL)
    if not result[1]:
        return result
    new_faces = []
    for face in result[2]:
        if str(face.get("kind", "")).startswith(SECTION_FACE_LABEL):
            face = dict(face, section=frame)
        new_faces.append(face)
    return result[0], result[1], new_faces

def _nice_spacing(value):
    """Round a hatch spacing to 1 / 2 / 2.5 / 5 x 10^n so the hatching looks tidy."""
    if value <= 0: return 1.0
    exponent = math.floor(math.log10(value))
    for step in (1.0, 2.0, 2.5, 5.0, 10.0):
        if step * 10.0 ** exponent >= value * 0.999:
            return step * 10.0 ** exponent
    return 10.0 ** (exponent + 1)

def _face_regions(tri_ids):
    """Connected parts of a face: lists of row indices into tri_ids (m, 3) whose triangles
    share vertices (the separate wall / slab strips of one cut, for example)."""
    parent = {}
    def find(x):
        while parent.setdefault(x, x) != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for a, b, c in tri_ids.tolist():
        ra = find(a)
        for other in (b, c):
            ro = find(other)
            if ro != ra:
                parent[ro] = ra
    groups = {}
    for row, a in enumerate(tri_ids[:, 0].tolist()):
        groups.setdefault(find(a), []).append(row)
    return list(groups.values())

def section_hatch_lines(verts, tris, face_tris, frame, angle=45.0, lines_across=26):
    """Hatching of a planar section face (parallel lines at 45 deg, as in technical drawings).
    Returns a float32 array (2n, 3) of line-segment end points. The lines are anchored in world
    space, so the pattern stays put while the plane is dragged within itself. Each separate
    region of the face (e.g. the strips a cut leaves of several walls) is hatched on its own:
    at 45 degrees to its long axis when it is elongated (measured from the plane's u axis the
    lines could run along a thin strip and vanish in its edges), and dense enough that a narrow
    strip still gets several lines across it."""
    face_tris = np.asarray(face_tris, dtype=int)
    if not len(face_tris): return np.empty((0, 3), np.float32)
    origin, u, v, normal = (np.asarray(a, float) for a in frame)
    tri_ids = np.asarray(tris, int).reshape(-1, 3)[face_tris]
    P_all = np.asarray(verts, float)[tri_ids]                                  # (m, 3, 3)
    flat_all = P_all.reshape(-1, 3)
    extent_all = max(float(np.ptp(flat_all @ u)), float(np.ptp(flat_all @ v)), 1e-6)
    face_spacing = _nice_spacing(extent_all / lines_across)      # one spacing for the face
    out = []
    for rows in _face_regions(tri_ids):
        P = P_all[rows]
        flat = np.column_stack([P.reshape(-1, 3) @ u, P.reshape(-1, 3) @ v])
        base = 0.0                     # compact regions keep the plane's u axis (steady)
        if len(flat) >= 3:
            eigenvalues, eigenvectors = np.linalg.eigh(np.cov(flat.T))
            if eigenvalues[1] > 4.0 * max(eigenvalues[0], 1e-12):     # clearly elongated
                major = eigenvectors[:, 1]
                base = math.atan2(float(major[1]), float(major[0]))
        axis_u = math.cos(base) * u + math.sin(base) * v
        axis_v = -math.sin(base) * u + math.cos(base) * v
        length = max(float(np.ptp(P.reshape(-1, 3) @ axis_u)), 1e-6)
        width = max(float(np.ptp(P.reshape(-1, 3) @ axis_v)), 1e-6)
        spacing = face_spacing
        # a narrow strip (a cut through a thin wall / floor) gets closer lines, but not so close
        # that they merge into a grey band: about 1.5 lines per strip width
        if min(length, width) / 1.5 < spacing:
            spacing = _nice_spacing(max(min(length, width) / 1.5, max(length, width) / 120.0))
        a = base + math.radians(angle)
        along = math.cos(a) * u + math.sin(a) * v
        across = -math.sin(a) * u + math.cos(a) * v
        x, y = P @ along, P @ across
        y_low, y_high = y.min(axis=1), y.max(axis=1)
        first = math.ceil(float(y_low.min()) / spacing)
        last = math.floor(float(y_high.max()) / spacing)
        # lifted a hair off the face (towards the viewer) so the lines never sink into the fill
        plane_shift = normal * (float(origin @ normal) + 0.05 * spacing)
        for k in range(first, last + 1):
            c = (k + 0.0137) * spacing                  # nudged: never exactly through a vertex
            hit = (y_low < c) & (y_high > c)
            if not hit.any(): continue
            xs, ys = x[hit], y[hit]
            crossings = []
            for i, j in ((0, 1), (1, 2), (2, 0)):
                dy = ys[:, j] - ys[:, i]
                valid = (ys[:, i] - c) * (ys[:, j] - c) < 0
                t = np.where(valid, (c - ys[:, i]) / np.where(dy == 0, 1.0, dy), 0.0)
                crossings.append(np.where(valid, xs[:, i] + t * (xs[:, j] - xs[:, i]), np.nan))
            crossings = np.stack(crossings, axis=1)
            low, high = np.nanmin(crossings, axis=1), np.nanmax(crossings, axis=1)
            for x0, x1 in zip(low.tolist(), high.tolist()):
                if x1 - x0 < 1e-9: continue          # sliver triangle: no visible segment
                out.append(x0 * along + c * across + plane_shift)
                out.append(x1 * along + c * across + plane_shift)
    return np.asarray(out, np.float32).reshape(-1, 3)

def profile_samples(loops, n_grid=9, max_edge_pts=96):
    """2-D sample points of an extrusion profile: its outline and a grid inside it."""
    pts = [p for loop in loops for e in loop for p in e["pts"]]
    if len(pts) > max_edge_pts: pts = pts[::max(1, len(pts)//max_edge_pts)]
    polys = [[p for e in loop for p in e["pts"][:-1]] for loop in loops]
    xs = [p[0] for pl in polys for p in pl]; ys = [p[1] for pl in polys for p in pl]
    out = list(pts)
    if xs:
        for gx in np.linspace(min(xs), max(xs), n_grid + 2)[1:-1]:
            for gy in np.linspace(min(ys), max(ys), n_grid + 2)[1:-1]:
                if sum(_pt_in_poly((gx, gy), pl) for pl in polys) % 2 == 1: out.append((gx, gy))
    return out

class TechnicalDrawingCanvas(QWidget):
    """Drawing sheet editor in the look of the sketcher: dark background with its grid, geometry
    and dimensions in the sketcher's colours, white hover glow, orange selection and the
    sketcher's snap markers. Wheel zooms at the cursor, the middle mouse button pans, the right
    mouse button cancels the current tool or deselects, Home fits the sheet."""
    sheetEdited = pyqtSignal()
    viewSelected = pyqtSignal(object)
    dimensionPlaced = pyqtSignal(object)
    annotationPlaced = pyqtSignal(object)      # {"view", "position" (view coordinates), "offset" (page)}
    tablePlaced = pyqtSignal(object)           # [x, y] page position of the hole table
    viewPicked = pyqtSignal(str, str, object)  # purpose, view name, [two view points]
    cutPlaced = pyqtSignal(int, float)            # Cut tool: new section (plane, offset)
    cutMoved = pyqtSignal(str, float)             # section letter, offset (live while dragged)
    cutRotated = pyqtSignal(str, int, float)      # section letter, new plane, offset
    sectionRemoveRequested = pyqtSignal(str)
    statusChanged = pyqtSignal(str)
    dimensionSelected = pyqtSignal(int)           # index in the dimension list, -1 = none
    dimensionRemoveRequested = pyqtSignal(int)
    selectionRemoveRequested = pyqtSignal()       # Delete with several views / dimensions selected

    DESK_COL = QColor(18, 18, 21)                 # around the sheet
    BACK_COL = QColor(28, 28, 32)                 # sketcher background
    GRID_MINOR, GRID_MAJOR = QColor(38, 38, 38), QColor(60, 60, 60)    # sketcher grid
    DIM_COL = QColor(170, 240, 170)               # sketcher dimension colour
    HOT_COL = QColor(255, 255, 255)               # hovered / dragged dimension
    SELECT_COL = QColor(255, 120, 0)              # sketcher selection
    GLOW_COL = QColor(255, 255, 255, 70)          # sketcher hover glow
    ZOOM_RANGE = (0.3, 20.0)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(720, 510)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.StrongFocus)
        self._pixmap = QPixmap()
        self._picture = None
        self._picture_serial = 0
        self._sheet_cache = None
        self._grid_cache = None          # cached layers: hovering and panning only blit them
        self._overlay_cache = None
        self._images = []                # shaded isometric views [(page rect, QImage)]
        # rubber-band selection (as in the sketcher): screen start / rectangle while dragging,
        # the views and dimensions it selected
        self._band_start = None
        self._band_rect = None
        self.selected_views = []
        self.selected_dimensions = set()
        self._group_drag = None          # [(record, x0, y0)] while several views move together
        self._layout = {"placements": [], "cut_normal": None}
        self.view_placements = []
        self._zoom = 1.0
        self._pan = QPointF(0.0, 0.0)
        self._pan_anchor = None
        self._pan_origin = None
        self.mode = None
        self.active_view = None
        self.selected = None
        self._drag_offset = None
        self._drag_info = None
        self._dimension_points = []
        self.dimension_kind = "length"
        self._snap_guides = ()
        self._hover_geometry = None
        self._selected_geometry = None
        self._dimensions = []
        self._dimension_drag = None
        self._hover_dimension = None
        self.selected_dimension = None
        self._cursor_pos = None
        self.page_w, self.page_h, self.sheet_name = DRAWING_PAGE_W, DRAWING_PAGE_H, "A2"
        self._hover_cut = None          # cutting-plane trace under the cursor {view, ends, ...}
        self._cut_drag = None
        # grid and snap in sheet millimetres, as in the sketcher
        self.grid_mm = DEFAULT_GRID
        self.snap_mm = DEFAULT_SNAP
        self.snap_enabled = True
        self.empty_hint = "Choose a view in the toolbar, then click the sheet to place it"

    def set_grid(self, grid_mm=None, snap_mm=None, snap_enabled=None):
        if grid_mm is not None:
            self.grid_mm = max(1.0, float(grid_mm))
        if snap_mm is not None:
            self.snap_mm = max(0.1, float(snap_mm))
        if snap_enabled is not None:
            self.snap_enabled = bool(snap_enabled)
        self.update()

    def _snap(self, value):
        """A page coordinate or distance on the snap step (sheet mm), when snapping is on."""
        if not self.snap_enabled:
            return float(value)
        step = self.snap_mm * DRAWING_UNITS_PER_MM
        return float(round(float(value) / step) * step)

    def select_dimension(self, index):
        """Highlight a dimension (from the dimension list); None / -1 clears it."""
        index = index if isinstance(index, int) and 0 <= index < len(self._dimensions) else None
        if index != self.selected_dimension:
            self.selected_dimension = index
            self.update()

    def _set_selected_dimension(self, index):
        self.select_dimension(index)
        self.dimensionSelected.emit(-1 if self.selected_dimension is None else self.selected_dimension)

    def fit_sheet(self):
        self._zoom = 1.0
        self._pan = QPointF(0.0, 0.0)
        self.update()

    def set_sheet(self, image, layout, view_placements, dimensions=None):
        # a QPicture is replayed as vectors at screen resolution; a QImage is a ready-made raster
        self._picture = image if isinstance(image, QPicture) else None
        self._picture_serial += 1
        self._sheet_cache = None
        self._pixmap = QPixmap() if self._picture is not None else QPixmap.fromImage(image)
        self._layout = layout
        self._images = list(layout.get("images") or [])
        page = layout.get("page")
        if page:
            if (page["w"], page["h"]) != (self.page_w, self.page_h):
                self._sheet_cache = None
            self.page_w, self.page_h = float(page["w"]), float(page["h"])
            self.sheet_name = f"{page['name']} {page['orientation']}"
        self.view_placements = view_placements
        self._dimensions = dimensions if dimensions is not None else []
        if self.selected_dimension is not None and self.selected_dimension >= len(self._dimensions):
            self.selected_dimension = None
        # a multi-selection keeps only what still exists
        self.selected_views = [record for record in self.selected_views
                               if any(record is item for item in view_placements)]
        self.selected_dimensions = {index for index in self.selected_dimensions
                                    if index < len(self._dimensions)}
        self.update()

    def clear_multi_selection(self):
        if self.selected_views or self.selected_dimensions:
            self.selected_views = []
            self.selected_dimensions = set()
            self.update()

    def has_multi_selection(self):
        return len(self.selected_views) + len(self.selected_dimensions) > 1

    def set_mode(self, mode=None, view=None):
        self.mode = mode
        self.active_view = view
        self._band_start = self._band_rect = None
        if mode is not None:                         # a tool ends the multi-selection
            self.clear_multi_selection()
        self.dimension_kind = (view or "length") if mode == "dimension" else "length"
        self._dimension_points = []
        self._annotation_tip = None
        self._series = None
        self._pick_first = None
        self.setFocus()
        self.setCursor(Qt.CrossCursor if mode else Qt.ArrowCursor)
        if mode == "view_pick":
            self.statusChanged.emit({
                "detail": "Detail view: click the centre of the detail on a view",
                "aux": "Auxiliary view: click the inclined straight edge on a main view",
                "break": "Break: click where the left-out part begins",
                "broken_out": "Broken-out section: click the first corner of the rectangle"}.get(
                    view, "Click on a view"))
        elif mode == "annotation":
            self.statusChanged.emit("Annotation: click the feature on a view (the arrow tip)")
        elif mode == "place_table":
            self.statusChanged.emit("Hole table: click where its top left corner should be")
        elif mode == "place_view":
            self.statusChanged.emit("Placement: imported graphic" if _graphic_id(view) else
                                    f"Placement: {view.title()} view")
        elif mode == "dimension":
            self.statusChanged.emit(f"Dimension: {self.dimension_kind.title()}")
        elif mode == "cut":
            self.statusChanged.emit("Cut tool")
        else:
            self.statusChanged.emit("Ready")

    def remove_selected(self):
        if self.selected is None:
            return
        self.view_placements[:] = [record for record in self.view_placements
                                   if record is not self.selected]
        self.selected = None
        self.viewSelected.emit(None)
        self.sheetEdited.emit()

    def _sheet_rect(self):
        bounds = self.rect().adjusted(16, 44, -16, -16)       # status lines above the sheet
        if bounds.width() <= 0 or bounds.height() <= 0:
            return QRectF()
        page_aspect = self.page_w / self.page_h
        width, height = bounds.width(), bounds.height()
        if width / height > page_aspect:
            width = height * page_aspect
        else:
            height = width / page_aspect
        width *= self._zoom
        height *= self._zoom
        center = bounds.center() + self._pan
        return QRectF(center.x() - width / 2, center.y() - height / 2, width, height)

    def wheelEvent(self, event):
        old_rect = self._sheet_rect()
        if old_rect.width() <= 0 or old_rect.height() <= 0:
            return
        page_point = np.array(((event.pos().x() - old_rect.left()) / old_rect.width() * self.page_w,
                               (event.pos().y() - old_rect.top()) / old_rect.height() * self.page_h))
        factor = 1.15 ** (event.angleDelta().y() / 120.0)
        self._zoom = min(self.ZOOM_RANGE[1], max(self.ZOOM_RANGE[0], self._zoom * factor))
        new_rect = self._sheet_rect()
        mapped = QPointF(new_rect.left() + page_point[0] / self.page_w * new_rect.width(),
                         new_rect.top() + page_point[1] / self.page_h * new_rect.height())
        self._pan += event.pos() - mapped
        self.update()
        event.accept()

    def _page_point(self, screen_point):
        rect = self._sheet_rect()
        if not rect.contains(screen_point) or rect.width() <= 0 or rect.height() <= 0:
            return None
        return np.array(((screen_point.x() - rect.left()) / rect.width() * self.page_w,
                         (screen_point.y() - rect.top()) / rect.height() * self.page_h), dtype=float)

    def _hit_view(self, page_point, margin_px=0.0):
        """View under a page point; `margin_px` screen pixels around each view also count, so
        outline edges and corners can be picked from just outside the view. While a dimension
        has its first point, the view of that point wins where views overlap."""
        if page_point is None:
            return None
        margin = margin_px * self.page_w / max(self._sheet_rect().width(), 1.0)
        prefer = self._dimension_points[0]["view"] \
            if self.mode == "dimension" and self._dimension_points else None
        found = None
        for info in reversed(self._layout.get("placements", [])):
            rect = QRectF(info["x"], info["y"], info["width"], info["height"]).adjusted(
                -margin, -margin, margin, margin)
            if rect.contains(QPointF(*page_point)):
                index = info.get("record_index")
                if isinstance(index, int) and 0 <= index < len(self.view_placements):
                    if prefer is None or info.get("name") == prefer:
                        return info, self.view_placements[index]
                    found = found or (info, self.view_placements[index])
        return found

    def _hit_dimension(self, page_point):
        if page_point is None:
            return None
        point = QPointF(*page_point)
        for hit in reversed(self._layout.get("dimension_hits", [])):
            if QRectF(hit["x"], hit["y"], hit["width"], hit["height"]).contains(point):
                index = hit.get("index")
                if isinstance(index, int) and 0 <= index < len(self._dimensions):
                    return hit
        return None

    def _paint_dimensions_overlay(self, painter, sheet_rect, indices=None, hot=frozenset(),
                                  record=True):
        """The added dimensions and annotations, printed in the sheet's units. `indices`: only
        these (default all), `hot`: drawn highlighted, `record`: keep their hit areas."""
        previous = _drawing_use_units(getattr(self, "units", None))
        try:
            self._paint_dimensions_overlay_units(painter, sheet_rect, indices, hot, record)
        finally:
            _drawing_use_units(previous)

    def _paint_dimensions_overlay_units(self, painter, sheet_rect, indices=None, hot=frozenset(),
                                        record=True):
        scale_x = sheet_rect.width() / self.page_w
        scale_y = sheet_rect.height() / self.page_h
        scale = min(scale_x, scale_y)
        # ISO lettering height on the sheet, but never smaller than the sketcher's dimension text
        font = _drawing_font(max(8.0, DRAWING_TEXT * scale))
        metrics = QFontMetricsF(font)
        line_width = 1.0                              # thin as in the sketcher, at any zoom
        ink = self.DIM_COL
        background = QColor(28, 28, 32, 220)          # text box of the sketcher's dimensions
        hits = []
        active = set(hot)

        def screen_page(point):
            return QPointF(sheet_rect.left() + point[0] * scale_x,
                           sheet_rect.top() + point[1] * scale_y)

        def arrow(tip, direction):
            direction = np.asarray(direction, dtype=float)
            length = float(np.linalg.norm(direction))
            if length <= 1e-12:
                return
            _paint_arrow(painter, tip, direction / length, max(5.0, 14.0 * scale), ink)

        def label_box(text, center):
            width = metrics.horizontalAdvance(text) + 10
            height = metrics.height() + 4
            rect = QRectF(center.x() - width / 2, center.y() - height / 2, width, height)
            painter.fillRect(rect, background)
            painter.setFont(font)
            painter.setPen(ink)
            painter.drawText(rect, Qt.AlignCenter, text)
            return rect

        def record_hit(index, label_rect, points):
            all_x = [label_rect.left(), label_rect.right()]
            all_y = [label_rect.top(), label_rect.bottom()]
            for point in points:
                all_x.append(point.x())
                all_y.append(point.y())
            bounds = QRectF(min(all_x) - 7, min(all_y) - 7,
                            max(all_x) - min(all_x) + 14,
                            max(all_y) - min(all_y) + 14)
            hits.append({"index": index,
                         "x": (bounds.left() - sheet_rect.left()) / scale_x,
                         "y": (bounds.top() - sheet_rect.top()) / scale_y,
                         "width": bounds.width() / scale_x,
                         "height": bounds.height() / scale_y,
                         "label_x": (label_rect.left() - sheet_rect.left()) / scale_x,
                         "label_y": (label_rect.top() - sheet_rect.top()) / scale_y,
                         "label_w": label_rect.width() / scale_x,
                         "label_h": label_rect.height() / scale_y})

        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setRenderHint(QPainter.TextAntialiasing, True)
        placements = {}
        for item in self._layout.get("placements", []):
            placements.setdefault(item.get("name"), item)
        for index, dimension in enumerate(self._dimensions):
            if indices is not None and index not in indices:
                continue
            info = placements.get(dimension.get("view"))
            if info is None:
                continue
            ink = self.HOT_COL if index in active else \
                self.SELECT_COL if index == self.selected_dimension or \
                index in self.selected_dimensions else self.DIM_COL
            painter.setPen(QPen(ink, line_width, Qt.SolidLine, Qt.FlatCap, Qt.RoundJoin))
            painter.setBrush(Qt.NoBrush)
            kind = dimension.get("type", "length")
            points = dimension.get("points") or [dimension.get("a"), dimension.get("b")]
            if kind == "annotation":
                annotation = tol_normalize_annotation(dimension.get("ann"))
                if annotation is not None and points and points[0] is not None:
                    tip = self._screen_point(points[0], info, sheet_rect)
                    symbol = _paint_annotation(painter, annotation, tip,
                                               (annotation["offset"][0] * scale_x,
                                                annotation["offset"][1] * scale_y), scale,
                                               QPen(ink, line_width), ink)
                    record_hit(index, symbol, ())   # the symbol is dragged, the leader follows
                continue
            if kind == "angle":
                if len(points) != 3:
                    continue
                vertex, ray_a, ray_b = [self._screen_point(point, info, sheet_rect)
                                        for point in points]
                legacy_offset = np.asarray(dimension.get("offset", (0.0, 0.0)), dtype=float)
                translation = QPointF(legacy_offset[0] * scale_x,
                                      legacy_offset[1] * scale_y)
                vertex += translation
                ray_a += translation
                ray_b += translation
                angle_a = math.degrees(math.atan2(vertex.y() - ray_a.y(),
                                                  ray_a.x() - vertex.x()))
                angle_b = math.degrees(math.atan2(vertex.y() - ray_b.y(),
                                                  ray_b.x() - vertex.x()))
                sweep = (angle_b - angle_a + 180.0) % 360.0 - 180.0
                arm = min(math.hypot(ray_a.x() - vertex.x(), ray_a.y() - vertex.y()),
                          math.hypot(ray_b.x() - vertex.x(), ray_b.y() - vertex.y()))
                radius = float(dimension["offset_distance"]) * scale \
                    if "offset_distance" in dimension else arm * 0.45
                painter.drawLine(vertex, ray_a)
                painter.drawLine(vertex, ray_b)
                painter.drawArc(QRectF(vertex.x() - radius, vertex.y() - radius,
                                       2 * radius, 2 * radius), int(angle_a * 16), int(sweep * 16))
                direction_sign = 1.0 if sweep >= 0 else -1.0
                for end_angle, outward in ((angle_a, 1.0), (angle_a + sweep, -1.0)):
                    t = math.radians(end_angle)
                    arrow(QPointF(vertex.x() + math.cos(t) * radius, vertex.y() - math.sin(t) * radius),
                          (outward * direction_sign * math.sin(t), outward * direction_sign * math.cos(t)))
                mid = math.radians(angle_a + sweep / 2)
                text = _drawing_dimension_value_text(dimension, unit="°")
                custom_label = str(dimension.get("label", "")).strip()
                if custom_label and custom_label.lower() != "angle":
                    text = f"{custom_label} {text}"
                anchor = QPointF(vertex.x() + math.cos(mid) * (radius + 14),
                                 vertex.y() - math.sin(mid) * (radius + 14))
                text_offset = np.asarray(dimension.get("text_offset", (0.0, 0.0)), dtype=float)
                text_center = QPointF(anchor.x() + text_offset[0] * scale_x,
                                      anchor.y() + text_offset[1] * scale_y)
                if np.linalg.norm(text_offset) > 28.0:
                    painter.setPen(QPen(ink, line_width))
                    painter.drawLine(anchor, text_center)
                label_rect = label_box(text, text_center)
                record_hit(index, label_rect, (vertex, ray_a, ray_b))
                continue
            if len(points) < 2:
                continue
            first = self._screen_point(points[0], info, sheet_rect)
            second = self._screen_point(points[1], info, sheet_rect)
            if kind in ("radius", "diameter"):
                center_values = np.asarray(points[0], dtype=float) if kind == "radius" else \
                    (np.asarray(points[0], dtype=float) + np.asarray(points[1], dtype=float)) / 2.0
                edge_values = np.asarray(points[1], dtype=float)
                radius_value = float(np.linalg.norm(edge_values - center_values))
                if dimension.get("angle") is not None:
                    edge_values = center_values + radius_value * np.array((
                        math.cos(float(dimension["angle"])),
                        math.sin(float(dimension["angle"]))))
                center = self._screen_point(center_values, info, sheet_rect)
                edge = self._screen_point(edge_values, info, sheet_rect)
                text = _drawing_dimension_value_text(dimension, "R" if kind == "radius" else "Ø")
                label_rect = _paint_radial_dimension(
                    painter, center, edge, text, kind == "diameter", scale,
                    ink, background, font, line_width,
                    (float(dimension.get("text_offset", (0.0, 0.0))[0]) * scale_x,
                     float(dimension.get("text_offset", (0.0, 0.0))[1]) * scale_y),
                    float(dimension.get("leader_length", 16.0)))
                opposite = QPointF(2 * center.x() - edge.x(), 2 * center.y() - edge.y())
                record_hit(index, label_rect, (opposite, edge) if kind == "diameter" else (edge,))
                continue
            if kind in ("chamfer", "arc", "ordinate"):
                label_rect = _paint_extra_dimension(
                    painter, dimension,
                    lambda u, v, info=info: self._screen_point((u, v), info, sheet_rect), scale,
                    QPen(ink, line_width), ink, font, background)
                if label_rect is not None:
                    record_hit(index, label_rect, ())
                continue
            first_page = np.asarray(self._view_page_point(points[0], info), dtype=float)
            second_page = np.asarray(self._view_page_point(points[1], info), dtype=float)
            frame = _drawing_length_frame(first_page, second_page, dimension)
            if frame is None:
                continue
            start_page, end_page, _direction, _normal, _distance = frame
            length_page = float(np.linalg.norm(end_page - start_page))
            if length_page <= 1e-12:
                continue
            start = screen_page(start_page)
            end = screen_page(end_page)
            # extension lines: 2 mm gap to the measured point, 2 mm beyond the dimension line
            for anchor_page, tip_page in ((first_page, start_page), (second_page, end_page)):
                reach = tip_page - anchor_page
                if float(np.linalg.norm(reach)) > 12.0:
                    step = reach / float(np.linalg.norm(reach)) * 8.0
                    painter.drawLine(screen_page(anchor_page + step), screen_page(tip_page + step))
            painter.drawLine(start, end)
            direction_screen = np.array((end.x() - start.x(), end.y() - start.y()))
            direction_screen /= max(float(np.linalg.norm(direction_screen)), 1e-12)
            arrow(start, direction_screen)
            arrow(end, -direction_screen)
            text = _drawing_dimension_value_text(dimension)
            custom_label = str(dimension.get("label", "")).strip()
            if custom_label and custom_label.lower() != "length":
                text = f"{custom_label} {text}"
            label_center = QPointF((start.x() + end.x()) / 2,
                                   (start.y() + end.y()) / 2)
            anchor = label_center
            text_offset = np.asarray(dimension.get("text_offset", (0.0, 0.0)), dtype=float)
            if np.linalg.norm(text_offset) > 1e-6:
                label_center = QPointF(anchor.x() + text_offset[0] * scale_x,
                                       anchor.y() + text_offset[1] * scale_y)
                label_rect = label_box(text, label_center)
                target = QPointF(min(max(anchor.x(), label_rect.left()), label_rect.right()),
                                 min(max(anchor.y(), label_rect.top()), label_rect.bottom()))
                painter.setPen(QPen(ink, line_width))
                painter.drawLine(anchor, target)
            else:
                shift = float(dimension.get("text_shift", 0.0))
                if abs(shift) > length_page / 2:
                    # number moved past an end: the dimension line runs on under it
                    reach = (abs(shift) * scale + metrics.horizontalAdvance(text) / 2 + 4) * \
                        (1.0 if shift > 0 else -1.0)
                    painter.setPen(QPen(ink, line_width))
                    painter.drawLine(end if shift > 0 else start,
                                     QPointF(anchor.x() + direction_screen[0] * reach,
                                             anchor.y() + direction_screen[1] * reach))
                label_rect = _paint_dimension_label(
                    painter, font, anchor, direction_screen, np.array((-direction_screen[1], direction_screen[0])),
                    text, float(dimension.get("text_shift", 0.0)), float(dimension.get("text_lift", 0.0)),
                    scale, ink, QPen(ink, line_width))
            record_hit(index, label_rect, (first, second, start, end))
        painter.restore()
        if record:
            self._layout["dimension_hits"] = hits

    @staticmethod
    def _info_arrays(info, key, width):
        """info[key] as a float array (n, …, 2), kept in the placement until that list is
        replaced (hovering asks for it on every mouse move)."""
        source = info.get(key, ())
        cache = info.setdefault("_arrays", {})
        entry = cache.get(key)
        if entry is None or entry[0] is not source:
            entry = (source, np.asarray(source, dtype=float).reshape((-1,) + width))
            cache[key] = entry
        return entry[1]

    @staticmethod
    def _info_curves(info, key):
        """The curves of info[key] as arrays with their bounding boxes, kept like _info_arrays:
        [(original, points, low, high, {fitted circle})]."""
        source = info.get(key, ())
        cache = info.setdefault("_arrays", {})
        entry = cache.get(("curves", key))
        if entry is None or entry[0] is not source:
            curves = []
            for original in source:
                points = np.asarray(original, dtype=float).reshape(-1, 2)
                if len(points) >= 2:
                    curves.append((original, points, points.min(axis=0), points.max(axis=0), {}))
            entry = (source, curves)
            cache[("curves", key)] = entry
        return entry[1]

    @staticmethod
    def _geometry_hit(page_point, info, tolerance, include_centre_lines=True):
        view_point = TechnicalDrawingCanvas._view_point(page_point, info)
        best = None
        points = TechnicalDrawingCanvas._info_arrays(info, "reference_points", (2,))
        if len(points):
            distance, index = _projected_points_hit(view_point, points)
            if distance <= tolerance:
                best = {"kind": "point", "position": points[index], "reference": True,
                        "explicit_point": True}
        points = TechnicalDrawingCanvas._info_arrays(info, "pick_points", (2,))
        if len(points):
            distance, index = _projected_points_hit(view_point, points)
            if distance <= tolerance and (best is None or distance <
                                                   np.linalg.norm(best["position"] - view_point)):
                best = {"kind": "point", "position": points[index], "reference": False,
                    "explicit_point": False}

        def segment_hit(key, reference):
            nonlocal best
            segments = TechnicalDrawingCanvas._info_arrays(info, key, (2, 2))
            if not len(segments):
                return
            distance, nearest, index = _projected_segments_hit(view_point, segments)
            if distance <= tolerance and (best is None or distance <
                                                   np.linalg.norm(best["position"] - view_point)):
                best = {"kind": "edge", "position": nearest,
                        "segment": segments[index], "reference": reference}

        segment_hit("reference_segments", True)
        segment_hit("pick_segments", False)

        exact_arcs = info.get("pick_arcs", ())
        for key, reference in (("reference_curves", True), ("pick_curves", False)):
            for original, curve, low, high, fits in TechnicalDrawingCanvas._info_curves(info, key):
                # out of reach of its bounding box: it cannot be the hit
                if view_point[0] < low[0] - tolerance or view_point[0] > high[0] + tolerance or \
                        view_point[1] < low[1] - tolerance or view_point[1] > high[1] + tolerance:
                    continue
                exact = key == "pick_curves" and any(original is arc for arc in exact_arcs)
                closed = np.linalg.norm(curve[0] - curve[-1]) <= max(tolerance * 0.1, 1e-6)
                distance, nearest, _segment_index = _projected_polyline_hit(view_point, curve)
                fitted_circle = None
                if len(curve) >= 6 and distance <= tolerance:
                    if "circle" not in fits:              # the same curve on every mouse move
                        fits["circle"] = TechnicalDrawingCanvas._fit_circle(curve)
                    fitted_circle = fits["circle"]
                    if fitted_circle is not None and closed:
                        distance, nearest = _projected_circle_hit(
                            view_point, fitted_circle[0], fitted_circle[1])
                best_distance = np.inf if best is None else \
                    float(np.linalg.norm(best["position"] - view_point))
                nearer = best is None or distance < best_distance - 1e-9
                tied_edge = best is not None and best["kind"] == "edge" and \
                    distance <= best_distance + 1e-9
                tied_mesh_point = best is not None and best["kind"] == "point" and \
                    not best.get("explicit_point", False)
                preserve_reference_edge = best is not None and best["kind"] == "edge" and \
                    best.get("reference", False) and not reference
                curved_candidate = fitted_circle is not None
                replace_non_circular_curve = best is not None and best["kind"] == "curve" and \
                    curved_candidate and "radius" not in best
                tied_other_curve = best is not None and best["kind"] == "curve" and \
                    reference and not best["reference"] and distance <= best_distance + 1e-9
                # a detected arc beats a polyline that merely runs through it into touching edges
                exact_arc_wins = exact and best is not None and best["kind"] == "curve" and \
                    not best.get("exact") and distance <= best_distance + 1e-9
                if distance <= tolerance and not preserve_reference_edge and \
                    (nearer or tied_edge or tied_mesh_point or tied_other_curve or
                     replace_non_circular_curve or exact_arc_wins):
                    best = {"kind": "curve", "position": nearest,
                            "curve": curve, "reference": reference, "exact": exact}
                    if fitted_circle is not None:
                        best["circle_center"], best["radius"] = fitted_circle
                    else:
                        direction = curve[-1] - curve[0]
                        length = float(np.linalg.norm(direction))
                        if length > 1e-12:
                            offsets = curve - curve[0]
                            deviations = np.abs(direction[0] * offsets[:, 1] -
                                                 direction[1] * offsets[:, 0]) / length
                            best["linear"] = float(deviations.max()) <= max(tolerance * 0.25, 1e-6)
        # centre lines (circle crosses, hole axes) are references for dimensions like edges, but
        # with the lowest priority: only where they are clearly nearer than any part geometry
        centre_lines = TechnicalDrawingCanvas._info_arrays(info, "centre_lines", (2, 2)) \
            if include_centre_lines else np.zeros((0, 2, 2))
        if len(centre_lines):
            distance, nearest, index = _projected_segments_hit(view_point, centre_lines)
            best_distance = np.inf if best is None else \
                float(np.linalg.norm(np.asarray(best["position"]) - view_point))
            if distance <= tolerance and distance < best_distance - 0.5 * tolerance:
                best = {"kind": "edge", "position": nearest, "segment": centre_lines[index],
                        "reference": False, "centre_line": True}
        return best

    @staticmethod
    def _fit_circle(points):
        points = np.unique(np.asarray(points, dtype=float).reshape(-1, 2), axis=0)
        if len(points) < 6:
            return None
        x, y = points.T
        coefficients, *_ = np.linalg.lstsq(
            np.column_stack((2.0 * x, 2.0 * y, np.ones(len(points)))),
            x * x + y * y, rcond=None)
        center = coefficients[:2]
        radius_squared = float(coefficients[2] + center @ center)
        if radius_squared <= 1e-16:
            return None
        radius = math.sqrt(radius_squared)
        residual = np.abs(np.linalg.norm(points - center, axis=1) - radius)
        if float(residual.max()) > max(radius * 0.015, 1e-5):
            return None
        return center, radius

    @staticmethod
    def _view_point(page_point, info):
        if info.get("breaks"):                        # broken view: undo the left-out bands
            mapped = (float(info["low"][0] + (page_point[0] - info["x"]) / info["scale"]),
                      float(info["low"][1] + (info["y"] + info["height"] - page_point[1]) / info["scale"]))
            return list(_drawing_break_unmap(mapped, info["breaks"], info["scale"]))
        return [float(info["low"][0] + (page_point[0] - info["x"]) / info["scale"]),
                float(info["high"][1] - (page_point[1] - info["y"]) / info["scale"])]

    def _cut_traces(self):
        """Cutting-line traces of all sections in the projected views:
        [{letter, plane, offset, view, info, ends (page), cr, cu}]."""
        traces = []
        for section in self._layout.get("sections", []):
            normal = np.asarray(section["normal"], dtype=float)
            for info in self._layout.get("placements", []):
                if info.get("name") not in DRAWING_MAIN_VIEWS or \
                        info.get("name") == section["name"]:
                    continue
                ends = _drawing_cut_trace(info["right"], info["up"], info["low"], info["high"],
                                          normal, float(section["offset"]),
                                          24.0 / max(info["scale"], 1e-9))
                if ends is None:
                    continue
                traces.append({"letter": section["letter"], "plane": section["plane"],
                               "offset": float(section["offset"]),
                               "view": info["name"], "info": info,
                               "ends": [np.asarray(self._view_page_point(end, info)) for end in ends],
                               "cr": float(normal @ np.asarray(info["right"])),
                               "cu": float(normal @ np.asarray(info["up"]))})
        return traces

    def _section_offset(self, letter):
        return next((float(section["offset"]) for section in self._layout.get("sections", [])
                     if section["letter"] == letter), None)

    def _edge_on_plane(self, info, prefer_vertical=True, exclude=None):
        """Section plane (0 front / 1 top / 2 right) seen edge-on in a view: the one giving a
        vertical cutting line (or horizontal), other than `exclude`."""
        best = None
        for plane, normal in enumerate(self._layout.get("plane_normals", [])):
            if plane == exclude:
                continue
            normal = np.asarray(normal, dtype=float)
            cr, cu = float(normal @ np.asarray(info["right"])), float(normal @ np.asarray(info["up"]))
            if cr * cr + cu * cu < 0.75:
                continue
            score = abs(cr) if prefer_vertical else abs(cu)
            if best is None or score > best[0]:
                best = (score, plane)
        return None if best is None else best[1]

    def _plane_offset(self, plane, info, page_point):
        """Offset of a section plane through a page point of a view."""
        u, v = self._view_point(page_point, info)
        world = np.asarray(info["right"]) * u + np.asarray(info["up"]) * v
        return round(float(world @ np.asarray(self._layout["plane_normals"][plane])), 2)

    def _cut_menu(self, trace, page_point, global_pos):
        """Right-click on a cutting line: rotate the cut by 90° in this view or delete it."""
        letter = trace["letter"]
        menu = QMenu(self)
        rotate = menu.addAction(QIcon(os.path.join(_LOG_DIR, "icons", "view_section.png")),
                                f"Rotate {letter}-{letter} by 90°")
        remove = menu.addAction(QIcon(os.path.join(_LOG_DIR, "icons", "delete_selected.png")),
                                f"Delete section {letter}-{letter}")
        chosen = menu.exec_(global_pos)
        if chosen is rotate:
            plane = self._edge_on_plane(trace["info"], abs(trace["cr"]) < abs(trace["cu"]),
                                        exclude=trace["plane"])
            if plane is not None:
                self.cutRotated.emit(letter, plane,
                                     self._plane_offset(plane, trace["info"], page_point))
        elif chosen is remove:
            self.sectionRemoveRequested.emit(letter)

    def _hit_cut(self, page_point):
        """Cutting-plane trace within 8 px of a page point, or None."""
        if page_point is None:
            return None
        tolerance = 8.0 * self.page_w / max(self._sheet_rect().width(), 1.0)
        for trace in self._cut_traces():
            a, b = trace["ends"]
            along = b - a
            span = float(along @ along)
            t = 0.0 if span <= 1e-12 else min(1.0, max(0.0, float((page_point - a) @ along) / span))
            if float(np.linalg.norm(page_point - (a + along * t))) <= tolerance:
                return trace
        return None

    def _cut_offset_at(self, trace, page_point):
        """Offset of the section plane through a page point, on the snap step (sheet mm turned
        into model mm by the view's scale) while snapping is on."""
        u, v = self._view_point(page_point, trace["info"])
        offset = u * trace["cr"] + v * trace["cu"]
        if self.snap_enabled:
            step = self.snap_mm * DRAWING_UNITS_PER_MM / max(trace["info"]["scale"], 1e-9)
            offset = round(offset / step) * step
        return round(float(offset), 2)              # as the Cut offset field shows it

    def _dimension_geometry(self, page_point, info, tolerance):
        """Geometry the dimension tools pick. For lengths and angles a point within reach wins
        over the edge or curve it lies on (the sketcher's vertex snap), so clicking near a corner
        starts a point-to-point dimension instead of instantly dimensioning the whole edge. An
        edge length is only taken when the edge is clicked away from its end points."""
        # centre lines are no use for radius / diameter (those need the circle itself)
        whole = ("radius", "diameter", "arc", "chamfer")     # tools that need the curve / edge itself
        geometry = self._geometry_hit(page_point, info, tolerance, include_centre_lines=
                                      self.dimension_kind not in whole)
        if geometry is None or geometry["kind"] == "point" or self.dimension_kind in whole:
            return geometry
        view_point = np.asarray(self._view_point(page_point, info), dtype=float)
        best = None
        for key, reference in (("reference_points", True), ("pick_points", False)):
            points = np.asarray(info.get(key, ()), dtype=float).reshape(-1, 2)
            if not len(points):
                continue
            distance, index = _projected_points_hit(view_point, points)
            if distance <= 1.5 * tolerance and (best is None or distance < best[0]):
                best = (distance, {"kind": "point", "position": points[index],
                                   "reference": reference, "explicit_point": reference})
        return best[1] if best is not None else geometry

    def mousePressEvent(self, event):
        if event.button() == Qt.MiddleButton:
            self._pan_anchor = event.pos()
            self._pan_origin = QPointF(self._pan)
            self.setCursor(Qt.ClosedHandCursor)
            event.accept()
            return
        if event.button() == Qt.RightButton:
            page_point = self._page_point(event.pos())
            cut = self._hit_cut(page_point) if self.mode is None else None
            if cut is not None:                      # cutting line: rotate by 90° / delete
                self._cut_menu(cut, page_point, event.globalPos())
                event.accept()
                return
            # as in the sketcher: abort the current tool, otherwise deselect
            if self.mode is not None:
                self.set_mode()
            else:
                self.selected = None
                self._selected_geometry = None
                self.clear_multi_selection()
                self.viewSelected.emit(None)
                self._set_selected_dimension(None)
                self.statusChanged.emit("Ready")
            self.update()
            event.accept()
            return
        if event.button() != Qt.LeftButton:
            return
        page_point = self._page_point(event.pos())
        if page_point is None:
            if self.mode is None:                    # beside the sheet: rubber band
                self._begin_band(event.pos())
            return
        if self.mode is None:
            dimension_hit = self._hit_dimension(page_point)
            if dimension_hit is not None:
                self.clear_multi_selection()
                index = dimension_hit["index"]
                dimension = self._dimensions[index]
                self.selected = None
                self._selected_geometry = None
                self._set_selected_dimension(index)
                drag = {"index": index, "start": page_point, "kind": dimension.get("type"),
                        "text_offset": np.asarray(
                            dimension.get("text_offset", (0.0, 0.0)), dtype=float)}
                drag.update(self._dimension_drag_frame(dimension))
                label = QRectF(dimension_hit.get("label_x", 0.0) - 4, dimension_hit.get("label_y", 0.0) - 4,
                               dimension_hit.get("label_w", 0.0) + 8, dimension_hit.get("label_h", 0.0) + 8)
                drag["part"] = "text" if label.contains(QPointF(*page_point)) else "line"
                self._dimension_drag = drag
                self._hover_dimension = index
                self.setCursor(Qt.ClosedHandCursor)
                self.update()
                return
            self._set_selected_dimension(None)
            cut = self._hit_cut(page_point)
            if cut is not None:        # drag the cutting line to move the section through the part
                self.clear_multi_selection()
                self._cut_drag = cut
                self.statusChanged.emit(f"Drag the cutting line {cut['letter']}-{cut['letter']}")
                self.update()
                return
        if self.mode == "place_table":            # hole table: its top left corner
            self.tablePlaced.emit([self._snap(page_point[0]), self._snap(page_point[1])])
            self.set_mode()
            return
        hit = self._hit_view(page_point, 12.0 if self.mode in ("dimension", "annotation", "view_pick")
                             else 0.0)
        if self.mode == "view_pick":
            self._pick_on_view(hit, page_point)
            return
        if self.mode == "annotation":
            tip = getattr(self, "_annotation_tip", None)
            if tip is None:                      # first click: the feature the symbol refers to
                if hit is None or not (hit[0]["name"] in DRAWING_MAIN_VIEWS or
                                       hit[0]["name"].startswith("section") or
                                       _graphic_id(hit[0]["name"])):
                    self.statusChanged.emit("Click on a view")
                    return
                info, _record = hit
                tolerance = max(10.0 * self.page_w / max(self._sheet_rect().width(), 1.0) /
                                max(info["scale"], 1e-9), 8.0 / max(info["scale"], 1e-9))
                geometry = self._dimension_geometry(page_point, info, tolerance)
                position = np.asarray(geometry["position"], dtype=float) if geometry is not None \
                    else np.asarray(self._view_point(page_point, info), dtype=float)
                self._annotation_tip = {"view": info["name"], "position": position.tolist(),
                                        "page": np.asarray(self._view_page_point(position, info),
                                                           dtype=float)}
                self.statusChanged.emit("Annotation: click where the symbol should sit")
            else:                                 # second click: where the frame / symbol goes
                offset = page_point - tip["page"]
                self.annotationPlaced.emit({"view": tip["view"], "position": tip["position"],
                                            "offset": [float(offset[0]), float(offset[1])]})
                self.set_mode()
            return
        if self.mode == "place_view":
            record = next((item for item in self.view_placements
                           if item.get("name") == self.active_view), None)
            x, y = self._snap(page_point[0]), self._snap(page_point[1])   # top-left on the grid
            if record is None:
                record = {"name": self.active_view, "x": x, "y": y}
                self.view_placements.append(record)
            else:
                record["x"], record["y"] = x, y
            self.selected = record
            self.set_mode()
            self.sheetEdited.emit()
            self.viewSelected.emit(record)
            return
        if self.mode == "dimension":
            if hit is None or not (hit[0]["name"] in DRAWING_MAIN_VIEWS or
                                   hit[0]["name"].startswith("section") or
                                   _graphic_id(hit[0]["name"])):
                return
            info, _record = hit
            tolerance = max(10.0 * self.page_w /
                            max(self._sheet_rect().width(), 1.0) / max(info["scale"], 1e-9),
                            8.0 / max(info["scale"], 1e-9))
            geometry = self._dimension_geometry(page_point, info, tolerance)
            if geometry is None:
                self.statusChanged.emit("Select a highlighted sketch point or edge")
                return
            geometry["view"] = info["name"]
            self._selected_geometry = geometry
            kind = self.dimension_kind
            position = np.asarray(geometry["position"], dtype=float)
            if kind in ("radius", "diameter"):
                if geometry["kind"] != "curve" or "radius" not in geometry:
                    self.statusChanged.emit("Select a circular edge or arc")
                    return
                center = np.asarray(geometry["circle_center"], dtype=float)
                direction = position - center
                length = float(np.linalg.norm(direction))
                if length <= 1e-12:
                    return
                direction /= length
                radius = float(geometry["radius"])
                value = _dimension_measurement(kind, geometry)["value"]
                if kind == "radius":
                    positions = [center.tolist(), (center + direction * radius).tolist()]
                else:
                    positions = [(center - direction * radius).tolist(),
                                 (center + direction * radius).tolist()]
                self._emit_dimension(info["name"], kind, positions, value)
                return
            if kind == "length":
                self._pick_length(info["name"], geometry)
                return
            if kind == "chamfer":
                straight = geometry["kind"] == "edge" or (geometry["kind"] == "curve" and
                                                          geometry.get("linear", False))
                if not straight or geometry.get("centre_line"):
                    self.statusChanged.emit("Chamfer: pick the straight edge of the chamfer")
                    return
                ends = geometry["segment"] if "segment" in geometry else \
                    (geometry["curve"][0], geometry["curve"][-1])
                a, b = (np.asarray(end, dtype=float) for end in ends)
                leg, angle = _drawing_chamfer_values(a, b)
                if leg <= 1e-9:
                    return
                self._emit_dimension(info["name"], "chamfer", [a.tolist(), b.tolist()], leg,
                                     {"chamfer_angle": float(angle), "text_offset": [60.0, -50.0]})
                return
            if kind == "arc":
                if geometry["kind"] != "curve" or "radius" not in geometry:
                    self.statusChanged.emit("Arc length: pick an arc")
                    return
                curve = np.asarray(geometry["curve"], dtype=float).reshape(-1, 2)
                centre = np.asarray(geometry["circle_center"], dtype=float)
                angles = np.unwrap(np.arctan2(curve[:, 1] - centre[1], curve[:, 0] - centre[0]))
                sweep = float(angles[-1] - angles[0])
                if abs(sweep) >= math.radians(359.0) or abs(sweep) <= 1e-6:
                    self.statusChanged.emit("Arc length: pick an arc (not a full circle)")
                    return
                radius = float(geometry["radius"])
                self._emit_dimension(info["name"], "arc",
                                     [centre.tolist(), curve[0].tolist(), curve[-1].tolist()],
                                     radius * abs(sweep), {"sweep_negative": sweep < 0})
                return
            if kind in ("baseline", "chain", "ordinate"):
                self._pick_series(info["name"], kind, position)
                return
            if kind == "angle" and geometry["kind"] != "point":
                self.statusChanged.emit("Select three sketch points for an angle")
                return
            point = {"view": info["name"], "position": position.tolist()}
            if self._dimension_points and self._dimension_points[0]["view"] != point["view"]:
                return
            self._dimension_points.append(point)
            needed = 3 if kind == "angle" else 2
            if len(self._dimension_points) < needed:
                self.statusChanged.emit(f"Dimension point {len(self._dimension_points) + 1}")
            else:
                positions = [np.asarray(item["position"], dtype=float)
                             for item in self._dimension_points]
                if kind == "angle":
                    value = _dimension_measurement(kind, points=positions)["value"]
                else:
                    value = _dimension_measurement(kind, points=positions)["value"]
                self._emit_dimension(info["name"], kind,
                                     [point.tolist() for point in positions], value)
            return
        if self.mode == "cut":
            if hit is None or hit[0]["name"] not in DRAWING_MAIN_VIEWS:
                return
            info, _record = hit
            # a new section through the clicked point: a vertical cutting line in this view
            # (right-click the line → Rotate by 90° for a horizontal one)
            plane = self._edge_on_plane(info, prefer_vertical=True)
            if plane is None:
                return
            self.cutPlaced.emit(plane, self._plane_offset(plane, info, page_point))
            self.set_mode()
            return
        if hit is None:
            # empty sheet: a rubber band (a click without dragging deselects on release)
            self._begin_band(event.pos())
            return
        info, record = hit
        if self.has_multi_selection() and any(record is item for item in self.selected_views):
            # pressing one of several selected views drags all of them together
            self._group_drag = [(item, float(item["x"]), float(item["y"]))
                                for item in self.selected_views]
            self._selected_geometry = None
            self.selected = record
            self._drag_offset = page_point - np.asarray((record["x"], record["y"]), dtype=float)
            self._drag_info = info
            self.update()
            return
        self.clear_multi_selection()
        tolerance = max(10.0 * self.page_w /
                        max(self._sheet_rect().width(), 1.0) / max(info["scale"], 1e-9),
                        8.0 / max(info["scale"], 1e-9))
        geometry = self._geometry_hit(page_point, info, tolerance)
        if geometry is not None:
            geometry["view"] = info["name"]
            self.selected = record
            self._selected_geometry = geometry
            self._drag_offset = None
            self.viewSelected.emit(record)
            selection_name = "centre line" if geometry.get("centre_line") else \
                {"point": "sketch point", "curve": "sketch curve",
                 "edge": "drawing edge"}[geometry["kind"]]
            self.statusChanged.emit(f"Selected {selection_name}")
            self.update()
            return
        self._selected_geometry = None
        self.selected = record
        self._drag_offset = page_point - np.asarray((record["x"], record["y"]), dtype=float)
        self._drag_info = info
        self.viewSelected.emit(record)
        self.update()

    def _dimension_drag_frame(self, dimension):
        """Page-space frame a dimension is dragged in: the dimension line moves parallel to itself,
        its text slides along it and takes the line along sideways, a radial leader turns about
        the centre and grows or shrinks with the pointer."""
        info = next((item for item in self._layout.get("placements", [])
                     if item.get("name") == dimension.get("view")), None)
        points = dimension.get("points") or [dimension.get("a"), dimension.get("b")]
        kind = dimension.get("type", "length")
        if kind == "annotation":
            annotation = tol_normalize_annotation(dimension.get("ann"))
            return {"ann_offset": np.asarray(annotation["offset"], dtype=float)} if annotation else {}
        if kind == "ordinate":
            return {"level": float(dimension.get("level", 40.0)), "axis": dimension.get("axis", "x")}
        if kind == "chamfer":
            return {"text_offset": np.asarray(dimension.get("text_offset") or (60.0, -50.0), dtype=float)}
        if info is None or len(points) < 2 or points[0] is None or points[1] is None:
            return {}
        page = [np.asarray(self._view_page_point(point, info), dtype=float) for point in points]
        if kind == "length":
            frame = _drawing_length_frame(page[0], page[1], dimension)
            if frame is None:
                return {}
            _start, _end, direction, normal, distance = frame
            return {"direction": direction, "normal": normal,
                    "length": float(np.linalg.norm(_end - _start)), "distance": distance,
                    "shift": float(dimension.get("text_shift", 0.0)),
                    "lift": float(dimension.get("text_lift", 0.0))}
        if kind in ("angle", "arc"):
            return {"vertex": page[0]}
        centre = page[0] if kind == "radius" else (page[0] + page[1]) / 2.0
        edge_vector = page[1] - centre
        radius = float(np.linalg.norm(edge_vector))
        angle = dimension.get("angle")
        if angle is None:
            angle = math.atan2(-edge_vector[1], edge_vector[0])
        direction = np.array((math.cos(float(angle)), -math.sin(float(angle))))
        leader = float(dimension.get("leader_length", 16.0))
        return {"centre": centre, "radius": radius, "knee": centre + direction * (radius + leader)}

    def _drag_dimension_to(self, dimension, drag, page_point):
        """Move a dragged dimension; with snapping on, its distance from the geometry, the
        position of its number and a leader's length move in whole snap steps."""
        kind = drag.get("kind") or "length"
        delta = page_point - drag["start"]
        snap = self._snap
        if kind == "annotation" and "ann_offset" in drag:
            offset = drag["ann_offset"] + delta
            dimension["ann"] = dict(dimension.get("ann") or {},
                                    offset=[snap(float(offset[0])), snap(float(offset[1]))])
            return
        if kind == "ordinate" and "level" in drag:
            dimension["level"] = snap(drag["level"] + float(delta[1] if drag["axis"] == "x" else delta[0]))
            return
        if kind == "arc" and "vertex" in drag:
            dimension["offset_distance"] = max(10.0, snap(float(np.linalg.norm(page_point - drag["vertex"]))))
            return
        if kind == "length" and "normal" in drag:
            if drag.get("part") == "text":
                # as in the sketcher: the number stays on its dimension line and slides along it;
                # moving it sideways carries the dimension line (and extension lines) with it
                dimension["text_shift"] = snap(drag["shift"] + delta @ drag["direction"])
                dimension["offset_distance"] = snap(drag["distance"] + drag["lift"] +
                                                    delta @ drag["normal"])
                dimension["text_lift"] = 0.0
            else:
                dimension["offset_distance"] = snap(drag["distance"] + delta @ drag["normal"])
            dimension.pop("text_offset", None)
        elif kind in ("radius", "diameter") and "centre" in drag:
            knee = page_point - (drag["start"] - drag["knee"])
            offset = knee - drag["centre"]
            distance = float(np.linalg.norm(offset))
            if distance > 1e-6:
                dimension["angle"] = math.atan2(-offset[1], offset[0])
                dimension["leader_length"] = max(4.0, snap(distance - drag["radius"]))
                dimension.pop("text_offset", None)
        elif kind == "angle" and "vertex" in drag and drag.get("part") != "text":
            dimension["offset_distance"] = max(
                10.0, snap(float(np.linalg.norm(page_point - drag["vertex"]))))
        else:
            dimension["text_offset"] = (drag["text_offset"] + delta).tolist()

    def _pick_length(self, view, geometry):
        """Length dimensions always take two picks, as the sketcher's Length tool: point → point,
        point → line or line → point (perpendicular distance), or two parallel lines (their
        distance). A single click never creates a dimension; an edge's length is dimensioned by
        picking its two end points."""
        position = np.asarray(geometry["position"], dtype=float)
        straight = geometry["kind"] == "edge" or (geometry["kind"] == "curve" and
                                                  geometry.get("linear", False))
        if geometry["kind"] == "curve" and not straight:
            self.statusChanged.emit("Length: pick a point or a straight edge (not a curve)")
            return
        pick = {"view": view, "position": position.tolist()}
        if straight:
            ends = geometry["segment"] if "segment" in geometry else \
                (geometry["curve"][0], geometry["curve"][-1])
            pick["segment"] = [np.asarray(end, dtype=float).tolist() for end in ends]
        if not self._dimension_points:
            self._dimension_points.append(pick)
            line = "centre line" if geometry.get("centre_line") else "line"
            self.statusChanged.emit(
                "Length: now pick the second point" if not straight else
                f"Length: now pick a point (distance to this {line}) or a parallel line / "
                "centre line")
            self.update()
            return
        first = self._dimension_points[0]
        if first["view"] != view:
            self.statusChanged.emit("Length: pick the second element in the same view")
            return

        def foot_on(point, segment):
            a, b = (np.asarray(end, dtype=float) for end in segment)
            along = b - a
            span = float(along @ along)
            if span <= 1e-18:
                return None
            return a + along * float((point - a) @ along) / span

        line_a, line_b = first.get("segment"), pick.get("segment")
        start = np.asarray(first["position"], dtype=float)
        if line_a is None and line_b is None:
            positions = [start, position]
        elif line_a is None or line_b is None:
            point, line = (start, line_b) if line_a is None else (position, line_a)
            foot = foot_on(point, line)
            if foot is None:
                return
            positions = [point, foot]
        else:
            direction_a = np.subtract(line_a[1], line_a[0])
            direction_b = np.subtract(line_b[1], line_b[0])
            cross = float(direction_a[0] * direction_b[1] - direction_a[1] * direction_b[0])
            norms = float(np.linalg.norm(direction_a) * np.linalg.norm(direction_b))
            if norms <= 1e-18 or abs(cross) > 1e-3 * norms:
                self.statusChanged.emit("Length: the two lines are not parallel - pick a point")
                return
            middle = (np.asarray(line_a[0], dtype=float) + np.asarray(line_a[1], dtype=float)) / 2
            foot = foot_on(middle, line_b)
            if foot is None:
                return
            positions = [middle, foot]
        value = float(np.linalg.norm(positions[1] - positions[0]))
        if value <= 1e-9:
            self.statusChanged.emit("Length: pick two different elements")
            return
        self._emit_dimension(view, "length", [p.tolist() for p in positions], value)

    def _emit_dimension(self, view, kind, points, value, extra=None, keep_mode=False):
        self.dimensionPlaced.emit({"view": view, "points": points,
                                   "a": points[0], "b": points[-1],
                                   "type": kind, "value": float(value), "extra": extra or {}})
        if not keep_mode:
            self.set_mode()

    def _pick_on_view(self, hit, page_point):
        """Picks for views made from views: a detail (centre, then a point of its circle), an
        auxiliary view (an inclined straight edge), a break (two points), a broken-out section
        (two corners). The result goes out as viewPicked(purpose, view, [p1, p2])."""
        purpose = self.active_view
        main = DRAWING_MAIN_VIEWS
        if hit is None:
            self.statusChanged.emit("Click on a view")
            return
        info, _record = hit
        name = info["name"]
        allowed = name not in ("isometric",) and not _graphic_id(name) if purpose == "detail" else \
            name in main or (purpose == "break" and str(name).startswith("aux-"))
        if not allowed:
            self.statusChanged.emit(f"Not possible on this view ({purpose.replace('_', '-')})")
            return
        tolerance = max(10.0 * self.page_w / max(self._sheet_rect().width(), 1.0) /
                        max(info["scale"], 1e-9), 8.0 / max(info["scale"], 1e-9))
        if purpose == "aux":
            geometry = self._geometry_hit(page_point, info, tolerance, include_centre_lines=False)
            straight = geometry is not None and (geometry["kind"] == "edge" or (
                geometry["kind"] == "curve" and geometry.get("linear", False)))
            if not straight:
                self.statusChanged.emit("Auxiliary view: click a straight edge")
                return
            ends = geometry["segment"] if "segment" in geometry else \
                (geometry["curve"][0], geometry["curve"][-1])
            self.set_mode()
            self.viewPicked.emit(purpose, name, [np.asarray(end, dtype=float).tolist() for end in ends])
            return
        geometry = self._geometry_hit(page_point, info, tolerance)
        position = np.asarray(geometry["position"], dtype=float) if geometry is not None and \
            geometry["kind"] == "point" else np.asarray(self._view_point(page_point, info), dtype=float)
        first = getattr(self, "_pick_first", None)
        if first is None or first["view"] != name:
            self._pick_first = {"view": name, "position": position.tolist()}
            self.statusChanged.emit({"detail": "Detail view: click a point of its circle",
                                     "break": "Break: click where the left-out part ends",
                                     "broken_out": "Broken-out section: click the opposite corner"}
                                    .get(purpose, "Click the second point"))
            return
        self.set_mode()
        self.viewPicked.emit(purpose, name, [first["position"], position.tolist()])

    def _pick_series(self, view, kind, position):
        """Baseline, chain and ordinate dimensioning: a series of clicks in one view (right-click
        ends it). Baseline: every point from the first one, the dimension lines stacked; chain:
        from point to point on one line; both horizontal or vertical as the first two points
        lie. Ordinate: the first point is the origin (0), every further point gets its X and Y
        coordinate (a coordinate given already is not repeated)."""
        series = getattr(self, "_series", None)
        position = np.asarray(position, dtype=float)
        if series is None or series.get("view") != view:
            self._series = {"view": view, "base": position, "previous": position, "orient": None,
                            "count": 0, "used": ({round(float(position[0]), 6)},
                                                 {round(float(position[1]), 6)})}
            if kind == "ordinate":
                for axis, level in (("x", 40.0), ("y", -40.0)):
                    self._emit_dimension(view, "ordinate", [position.tolist(), position.tolist()],
                                         0.0, {"axis": axis, "level": level}, keep_mode=True)
                self.statusChanged.emit("Ordinate: origin set · click the points to dimension "
                                        "(right-click ends)")
            else:
                self.statusChanged.emit(f"{kind.title()}: base point set · click the next point "
                                        "(right-click ends)")
            self.update()
            return
        if kind == "ordinate":
            made = 0
            for index, axis, level in ((0, "x", 40.0), (1, "y", -40.0)):
                key = round(float(position[index]), 6)
                if key in series["used"][index]:
                    continue
                series["used"][index].add(key)
                self._emit_dimension(view, "ordinate", [series["base"].tolist(), position.tolist()],
                                     abs(float(position[index] - series["base"][index])),
                                     {"axis": axis, "level": level}, keep_mode=True)
                made += 1
            self.statusChanged.emit("Ordinate: next point (right-click ends)" if made else
                                    "Ordinate: both coordinates of this point are given already")
            return
        start = series["base"] if kind == "baseline" else series["previous"]
        delta = position - start
        if series["orient"] is None:
            if float(np.linalg.norm(delta)) <= 1e-9:
                return
            series["orient"] = "h" if abs(delta[0]) >= abs(delta[1]) else "v"
        axis = 0 if series["orient"] == "h" else 1
        if abs(float(delta[axis])) <= 1e-9:
            self.statusChanged.emit(f"{kind.title()}: this point adds no "
                                    f"{'horizontal' if axis == 0 else 'vertical'} distance")
            return
        distance = DRAWING_DIM_OFFSET + (28.0 * series["count"] if kind == "baseline" else 0.0)
        self._emit_dimension(view, "length", [start.tolist(), position.tolist()],
                             abs(float(delta[axis])),
                             {"orient": series["orient"], "offset_distance": distance},
                             keep_mode=True)
        series["count"] += 1
        series["previous"] = position
        self.statusChanged.emit(f"{kind.title()}: next point (right-click ends)")

    def _begin_band(self, screen_point):
        self._band_start = QPointF(screen_point)
        self._band_rect = None

    def _finish_band(self):
        """Select every view and dimension the rubber band touches (partial overlap is enough,
        as in the sketcher). One item is selected as usual; several stay selected together:
        Delete removes them, dragging one of the views moves all selected views."""
        rect = self._sheet_rect()
        band = self._band_rect
        if rect.width() <= 0 or rect.height() <= 0 or band is None:
            return
        sx, sy = self.page_w / rect.width(), self.page_h / rect.height()
        page = QRectF((band.left() - rect.left()) * sx, (band.top() - rect.top()) * sy,
                      band.width() * sx, band.height() * sy)
        views = []
        for info in self._layout.get("placements", []):
            index = info.get("record_index")
            if isinstance(index, int) and 0 <= index < len(self.view_placements) and \
                    QRectF(info["x"], info["y"], info["width"], info["height"]).intersects(page):
                record = self.view_placements[index]
                if not any(record is item for item in views):
                    views.append(record)
        dimensions = {hit["index"] for hit in self._layout.get("dimension_hits", [])
                      if isinstance(hit.get("index"), int) and
                      0 <= hit["index"] < len(self._dimensions) and
                      QRectF(hit["x"], hit["y"], hit["width"], hit["height"]).intersects(page)}
        self._selected_geometry = None
        self.selected_views, self.selected_dimensions = [], set()
        if len(views) == 1 and not dimensions:
            self.selected = views[0]
            self._set_selected_dimension(None)
            self.viewSelected.emit(views[0])
        elif len(dimensions) == 1 and not views:
            self.selected = None
            self.viewSelected.emit(None)
            self._set_selected_dimension(next(iter(dimensions)))
        else:
            self.selected = None
            self.viewSelected.emit(None)
            self._set_selected_dimension(None)
            self.selected_views, self.selected_dimensions = views, dimensions
            if views or dimensions:
                parts = [f"{len(views)} view{'s' if len(views) != 1 else ''}"] if views else []
                parts += [f"{len(dimensions)} dimension{'s' if len(dimensions) != 1 else ''}"] \
                    if dimensions else []
                self.statusChanged.emit(
                    f"Selected {' and '.join(parts)} · Delete removes them" +
                    (" · drag a selected view to move them together" if len(views) > 1 else ""))
            else:
                self.statusChanged.emit("Ready")
        self.update()

    def leaveEvent(self, event):
        self._cursor_pos = None
        self._hover_geometry = None
        self.update()
        super().leaveEvent(event)

    def mouseMoveEvent(self, event):
        self._cursor_pos = QPointF(event.pos())
        if self._pan_anchor is not None:
            self._pan = self._pan_origin + QPointF(event.pos() - self._pan_anchor)
            self.update()
            event.accept()
            return
        if self._band_start is not None:             # rubber band: starts after 3 px
            current = QPointF(event.pos())
            if self._band_rect is not None or \
                    (current - self._band_start).manhattanLength() > 3:
                self._band_rect = QRectF(self._band_start, current).normalized()
                self.update()
            return
        if self._dimension_drag is not None:
            page_point = self._page_point(event.pos())
            if page_point is None:
                return
            drag = self._dimension_drag
            dimension = self._dimensions[drag["index"]]
            self._drag_dimension_to(dimension, drag, page_point)
            # dimensions are the canvas's own overlay: repaint it now, the sheet is refreshed
            # (and the undo step taken) once on release
            self.update()
            return
        if self._cut_drag is not None:
            page_point = self._page_point(event.pos())
            if page_point is not None:
                letter = self._cut_drag["letter"]
                offset = self._cut_offset_at(self._cut_drag, page_point)
                if offset != self._section_offset(letter):
                    self.cutMoved.emit(letter, offset)
                    self.statusChanged.emit(f"Cut {letter}-{letter} at {offset:g} mm")
            return
        if self._drag_offset is None or self.selected is None:
            page_point = self._page_point(event.pos())
            dimension_hit = self._hit_dimension(page_point)
            hover_dimension = dimension_hit["index"] if dimension_hit is not None else None
            hover_cut = self._hit_cut(page_point) if self.mode is None and \
                hover_dimension is None else None
            if hover_dimension != self._hover_dimension or \
                    (hover_cut is None) != (self._hover_cut is None):
                self._hover_dimension = hover_dimension
                self.setCursor(
                    Qt.PointingHandCursor if hover_dimension is not None else
                    (Qt.SizeHorCursor if abs(hover_cut["cr"]) >= abs(hover_cut["cu"])
                     else Qt.SizeVerCursor) if hover_cut is not None else
                    Qt.CrossCursor if self.mode else Qt.ArrowCursor)
                self.update()
            self._hover_cut = hover_cut
            hit = self._hit_view(page_point, 12.0 if self.mode == "dimension" else 0.0)
            geometry = None
            if hit is not None:
                info = hit[0]
                tolerance = max(10.0 * self.page_w /
                                max(self._sheet_rect().width(), 1.0) / max(info["scale"], 1e-9),
                                8.0 / max(info["scale"], 1e-9))
                geometry = self._dimension_geometry(page_point, info, tolerance) \
                    if self.mode == "dimension" else self._geometry_hit(page_point, info, tolerance)
                if geometry is not None:
                    geometry["view"] = info["name"]
            self._hover_geometry = geometry
            self.update()       # cheap: the sheet is cached; also refreshes the cursor read-out
            return
        page_point = self._page_point(event.pos())
        if page_point is None:
            return
        position = page_point - self._drag_offset
        guides = []
        snap_tolerance = 24.0
        moving_index = self._drag_info.get("record_index") if self._drag_info else None
        moving = [item for item, _x, _y in self._group_drag] if self._group_drag else []
        for info in self._layout.get("placements", []):
            index = info.get("record_index")
            if index == moving_index or (
                    moving and isinstance(index, int) and 0 <= index < len(self.view_placements)
                    and any(self.view_placements[index] is item for item in moving)):
                continue                             # views that move along are no targets
            width, height = self._drag_info["width"], self._drag_info["height"]
            x_targets = (info["x"], info["x"] + (info["width"] - width) / 2,
                         info["x"] + info["width"] - width,
                         info["x"] + info["width"] + 30, info["x"] - width - 30)
            y_targets = (info["y"], info["y"] + (info["height"] - height) / 2,
                         info["y"] + info["height"] - height,
                         info["y"] + info["height"] + 30, info["y"] - height - 30)
            for axis, targets in ((0, x_targets), (1, y_targets)):
                nearest = min(targets, key=lambda target: abs(target - position[axis]))
                if abs(nearest - position[axis]) <= snap_tolerance:
                    position[axis] = nearest
                    guides.append((axis, nearest))
        # alignment with another view wins; otherwise the view's corner goes on the snap grid
        aligned = {axis for axis, _value in guides}
        for axis in (0, 1):
            if axis not in aligned:
                position[axis] = self._snap(position[axis])
        self.selected["x"] = float(min(max(position[0], 60.0), self.page_w - 60.0))
        self.selected["y"] = float(min(max(position[1], 60.0), self.page_h - 60.0))
        if self._group_drag:                         # the other selected views keep their distance
            start = next(((x, y) for item, x, y in self._group_drag if item is self.selected), None)
            if start is not None:
                dx, dy = self.selected["x"] - start[0], self.selected["y"] - start[1]
                for item, x, y in self._group_drag:
                    if item is not self.selected:
                        item["x"] = float(min(max(x + dx, 60.0), self.page_w - 60.0))
                        item["y"] = float(min(max(y + dy, 60.0), self.page_h - 60.0))
        self._snap_guides = tuple(guides)
        self.sheetEdited.emit()

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MiddleButton:
            self._pan_anchor = None
            self._pan_origin = None
            self.setCursor(Qt.CrossCursor if self.mode else Qt.ArrowCursor)
            event.accept()
            return
        if event.button() == Qt.LeftButton:
            if self._band_start is not None:
                dragged = self._band_rect is not None
                if dragged:
                    self._finish_band()
                else:                                # a click on the empty sheet deselects
                    self.selected = None
                    self._selected_geometry = None
                    self.clear_multi_selection()
                    self.viewSelected.emit(None)
                self._band_start = self._band_rect = None
                self.update()
                return
            if self._dimension_drag is not None:
                self._dimension_drag = None
                self.setCursor(Qt.ArrowCursor)
                self.sheetEdited.emit()
                self.update()
                return
            if self._cut_drag is not None:
                letter = self._cut_drag["letter"]
                page_point = self._page_point(event.pos())
                offset = self._cut_offset_at(self._cut_drag, page_point) if page_point is not None \
                    else self._section_offset(letter)
                self._cut_drag = None
                if offset is not None:
                    self.cutMoved.emit(letter, offset)
                    self.statusChanged.emit(f"Cut {letter}-{letter} at {offset:g} mm")
                self.sheetEdited.emit()
                self.update()
                return
            was_dragging = self._drag_offset is not None
            self._drag_offset = None
            self._drag_info = None
            self._group_drag = None
            self._snap_guides = ()
            if was_dragging:
                self.sheetEdited.emit()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape:
            self.set_mode()
            event.accept()
            return
        if event.key() == Qt.Key_Home:
            self.fit_sheet()
            event.accept()
            return
        if event.key() in (Qt.Key_Delete, Qt.Key_Backspace):
            if self.has_multi_selection():
                self.selectionRemoveRequested.emit()
            elif self.selected_dimension is not None:
                self.dimensionRemoveRequested.emit(self.selected_dimension)
            else:
                self.remove_selected()
            event.accept()
            return
        super().keyPressEvent(event)

    def _paint_grid(self, painter, rect, visible=None):
        """The sketcher's grid on the sheet: lines every `grid_mm`, every fifth one stronger, and
        the snap dots while snapping is on. Lines that would come closer than 8 px are thinned
        out in a 1-2-5 series and dots that dense are left out, as in the sketcher. `visible`:
        the part of the sheet to paint (default: what the canvas shows)."""
        visible = rect.intersected(QRectF(self.rect()) if visible is None else visible)
        if visible.isEmpty():
            return
        pixels_per_mm = rect.width() / self.page_w * DRAWING_UNITS_PER_MM
        k = 1
        for m in (2, 5, 2, 5):
            if self.grid_mm * k * pixels_per_mm >= 8.0:
                break
            k *= m
        while self.grid_mm * k * pixels_per_mm < 8.0:
            k *= 10
        step = self.grid_mm * k * pixels_per_mm
        minor, major = [], []
        for first, low, high, horizontal in ((rect.left(), visible.left(), visible.right(), False),
                                             (rect.top(), visible.top(), visible.bottom(), True)):
            for i in range(math.ceil((low - first) / step), math.floor((high - first) / step) + 1):
                value = int(first + i * step) + 0.5
                line = QLineF(visible.left(), value, visible.right(), value) if horizontal else \
                    QLineF(value, visible.top(), value, visible.bottom())
                (major if i % 5 == 0 else minor).append(line)
        for colour, lines in ((self.GRID_MINOR, minor), (self.GRID_MAJOR, major)):
            if lines:
                painter.setPen(QPen(colour, 1))
                painter.drawLines(lines)
        snap_step = self.snap_mm * pixels_per_mm
        if self.snap_enabled and snap_step >= 8.0:
            i0, i1 = math.ceil((visible.left() - rect.left()) / snap_step), \
                math.floor((visible.right() - rect.left()) / snap_step)
            j0, j1 = math.ceil((visible.top() - rect.top()) / snap_step), \
                math.floor((visible.bottom() - rect.top()) / snap_step)
            if 0 < (i1 - i0 + 1) * (j1 - j0 + 1) <= 40000:
                dot_pen = QPen(QColor(55, 55, 55), 2)
                dot_pen.setCapStyle(Qt.RoundCap)
                painter.setPen(dot_pen)
                left, top = rect.left(), rect.top()
                xs = [left + i * snap_step for i in range(i0, i1 + 1)]
                ys = [top + j * snap_step for j in range(j0, j1 + 1)]
                painter.drawPoints(QPolygonF([QPointF(x, y) for x in xs for y in ys]))

    def _cached_layer(self, cache_name, rect, key, paint):
        """A transparent layer over the sheet `rect`, kept in `cache_name` until `key` changes.
        At moderate zoom it covers the whole sheet, so panning and hovering only blit it; zoomed
        far in, only the visible part is rendered. `paint(painter, local_rect, local_visible)`
        draws with the sheet at (0, 0). Returns (pixmap, screen position) or None."""
        view = QRectF(self.rect())
        whole = rect.width() * rect.height() <= 3.0 * max(view.width() * view.height(), 1.0)
        target = QRectF(rect) if whole else rect.intersected(view)
        if target.width() < 1 or target.height() < 1:
            return None
        dpr = self.devicePixelRatioF()
        key = (key, dpr, round(rect.width(), 2), round(rect.height(), 2))
        if not whole:
            key += (round(rect.left(), 2), round(rect.top(), 2), view.width(), view.height())
        cache = getattr(self, cache_name)
        if cache is None or cache[0] != key:
            pixmap = QPixmap(max(1, math.ceil(target.width() * dpr)),
                             max(1, math.ceil(target.height() * dpr)))
            pixmap.setDevicePixelRatio(dpr)
            pixmap.fill(Qt.transparent)
            layer = QPainter(pixmap)
            layer.setRenderHint(QPainter.Antialiasing, True)
            layer.setRenderHint(QPainter.TextAntialiasing, True)
            layer.setRenderHint(QPainter.SmoothPixmapTransform, True)
            layer.translate(rect.left() - target.left(), rect.top() - target.top())
            paint(layer, QRectF(0.0, 0.0, rect.width(), rect.height()),
                  target.translated(-rect.left(), -rect.top()))
            layer.end()
            cache = (key, pixmap, target.topLeft() - rect.topLeft())
            setattr(self, cache_name, cache)
        _key, pixmap, offset = cache
        return pixmap, rect.topLeft() + offset

    def _sheet_layer(self, rect):
        """The recorded sheet replayed as vectors (crisp at any zoom and device pixel ratio), with
        the shaded isometric images, which are not recorded in the picture."""
        def paint(layer, local, _visible):
            layer.scale(local.width() / self.page_w, local.height() / self.page_h)
            layer.drawPicture(0, 0, self._picture)
            for image_rect, image in self._images:
                layer.drawImage(image_rect, image)
        return self._cached_layer("_sheet_cache", rect, self._picture_serial, paint)

    def _grid_layer(self, rect):
        return self._cached_layer(
            "_grid_cache", rect, (self.grid_mm, self.snap_mm, self.snap_enabled),
            lambda layer, local, visible: self._paint_grid(layer, local, visible))

    def _overlay_layer(self, rect):
        """Dimensions and annotations: repainted only when they, the selection or the sheet
        change (their hit areas are recorded while painting). The dragged dimension is left out
        and painted live with the hovered one (_paint_live_dimensions)."""
        dragged = self._dimension_drag["index"] if self._dimension_drag is not None else None
        shown = [None if index == dragged else dimension
                 for index, dimension in enumerate(self._dimensions)]
        key = (self._picture_serial, id(self._dimensions),
               json.dumps(shown, sort_keys=True, default=_json_default),
               self.selected_dimension, tuple(sorted(self.selected_dimensions)),
               json.dumps(getattr(self, "units", None), sort_keys=True, default=str))
        indices = None if dragged is None else \
            set(range(len(self._dimensions))) - {dragged}
        return self._cached_layer(
            "_overlay_cache", rect, key,
            lambda layer, local, _visible: self._paint_dimensions_overlay(
                layer, local, indices, record=dragged is None))

    def _paint_live_dimensions(self, painter, rect):
        """The hovered and the dragged dimension, highlighted over the cached overlay."""
        live = {self._hover_dimension}
        if self._dimension_drag is not None:
            live.add(self._dimension_drag["index"])
        live = {index for index in live if isinstance(index, int) and
                0 <= index < len(self._dimensions)}
        if live:
            self._paint_dimensions_overlay(painter, rect, live, live, record=False)

    def _placement(self, name):
        return next((item for item in self._layout.get("placements", [])
                     if item.get("name") == name), None)

    def _stroke_geometry(self, painter, geometry, info, rect):
        if geometry["kind"] == "curve":
            painter.drawPolyline(QPolygonF([self._screen_point(point, info, rect)
                                            for point in geometry["curve"]]))
        elif geometry["kind"] == "edge":
            first, second = geometry["segment"]
            painter.drawLine(self._screen_point(first, info, rect),
                             self._screen_point(second, info, rect))

    def _paint_geometry_marks(self, painter, rect):
        """Selected geometry in the sketcher's selection orange, the hovered one under its white
        glow; while dimensioning also the sketcher's snap marker (square = point, ring = edge)."""
        selected = self._selected_geometry
        info = self._placement(selected["view"]) if selected is not None else None
        if info is not None:
            if selected["kind"] == "point":
                centre = self._screen_point(selected["position"], info, rect)
                painter.setPen(Qt.NoPen)
                painter.setBrush(self.SELECT_COL)
                painter.drawEllipse(centre, 4.0, 4.0)
                painter.setPen(QPen(self.SELECT_COL, 1.5))
                painter.setBrush(Qt.NoBrush)
                painter.drawEllipse(centre, 7.0, 7.0)
            else:
                painter.setPen(QPen(self.SELECT_COL, 3, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
                painter.setBrush(Qt.NoBrush)
                self._stroke_geometry(painter, selected, info, rect)
        hover = self._hover_geometry
        info = self._placement(hover["view"]) if hover is not None else None
        if info is None:
            return
        position = self._screen_point(hover["position"], info, rect)
        if hover["kind"] == "point":
            painter.setPen(Qt.NoPen)
            painter.setBrush(self.GLOW_COL)
            painter.drawEllipse(position, 10.0, 10.0)
            painter.setPen(QPen(QColor(255, 255, 255, 220), 1.5))
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(position, 7.0, 7.0)
        else:
            painter.setPen(QPen(self.GLOW_COL, 10, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            painter.setBrush(Qt.NoBrush)
            self._stroke_geometry(painter, hover, info, rect)
        if self.mode == "dimension":
            painter.setBrush(Qt.NoBrush)
            if hover["kind"] == "point":
                painter.setPen(QPen(QColor(255, 230, 0), 1.5))
                painter.drawRect(QRectF(position.x() - 6, position.y() - 6, 12, 12))
            else:
                painter.setPen(QPen(QColor(255, 90, 255), 1.5))
                painter.drawEllipse(position, 6.0, 6.0)

    def _paint_dimension_picks(self, painter, rect):
        """Points already picked for a dimension (the sketcher's first-pick glow) and a dashed
        guide from the last one to the cursor."""
        last = None
        for point in self._dimension_points:
            info = self._placement(point["view"])
            if info is None:
                continue
            last = self._screen_point(point["position"], info, rect)
            if point.get("segment") is not None:          # a picked line: glow along it
                painter.setPen(QPen(QColor(255, 160, 0, 150), 9, Qt.SolidLine, Qt.RoundCap))
                painter.setBrush(Qt.NoBrush)
                painter.drawLine(self._screen_point(point["segment"][0], info, rect),
                                 self._screen_point(point["segment"][1], info, rect))
                continue
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor(255, 160, 0, 170))
            painter.drawEllipse(last, 9.0, 9.0)
        painter.setBrush(Qt.NoBrush)
        if last is not None and self._cursor_pos is not None:
            painter.setPen(QPen(QColor(255, 120, 0, 160), 1, Qt.DashLine))
            painter.drawLine(last, self._cursor_pos)

    def _paint_hud(self, painter, rect):
        """Status lines in the top left corner, as in the sketcher."""
        painter.setFont(QFont("Arial", 9))
        placing = "imported graphic" if _graphic_id(self.active_view) else             f"{self.active_view or ''} view"
        mode = {None: "select", "place_view": f"place {placing}",
                "dimension": f"{self.dimension_kind} dimension", "cut": "section cut"}.get(
                    self.mode, str(self.mode))
        snap = f"snap:{self.snap_mm:g}mm" if self.snap_enabled else "snap:off"
        text = (f"{self.sheet_name} sheet  [{mode}]  {snap}  grid:{self.grid_mm:g}mm  "
                f"zoom:{self._zoom * 100:.0f}%")
        page = self._page_point(self._cursor_pos) if self._cursor_pos is not None else None
        if page is not None:
            text += (f"  cursor:{page[0] / DRAWING_UNITS_PER_MM:.1f},"
                     f"{(self.page_h - page[1]) / DRAWING_UNITS_PER_MM:.1f}")
        hints = {
            None: ("Drag views, dimensions and cutting lines · drag on the empty sheet to select "
                   "several · right-click a cutting line: rotate 90° / delete · wheel: zoom · "
                   "middle mouse: pan · Home: fit sheet",
                   QColor(170, 170, 170)),
            "place_view": ("Click the sheet to place the view · Esc / right-click to cancel",
                           QColor(80, 225, 240)),
            "cut": ("Click a projected view to add a section cut there (right-click a cutting line "
                    "to rotate it by 90°) · Esc / right-click to cancel",
                    QColor(255, 80, 80)),
            "dimension": ({"length": "Click two points, a point and a line, or two parallel lines "
                                     "(edges and centre lines)",
                           "radius": "Click a circular edge or arc",
                           "diameter": "Click a circular edge or arc",
                           "angle": "Click three points: the vertex first, then one on each leg"
                           }.get(self.dimension_kind, "Click the geometry to dimension") +
                          " · Esc / right-click to cancel", QColor(255, 80, 80)),
        }
        hint, colour = hints.get(self.mode, hints[None])
        metrics = painter.fontMetrics()
        width = max(metrics.horizontalAdvance(text), metrics.horizontalAdvance(hint)) + 16
        painter.fillRect(QRectF(0, 0, width, 42), QColor(18, 18, 21, 200))   # readable when zoomed in
        painter.setPen(QColor(200, 200, 200))
        painter.drawText(8, 18, text)
        painter.setPen(colour)
        painter.drawText(8, 36, hint)

    def paintEvent(self, _event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), self.DESK_COL)
        rect = self._sheet_rect()
        if rect.width() <= 0 or rect.height() <= 0:
            painter.end()
            return
        # the sheet: soft drop shadow, the sketcher's background and grid, then the drawing
        for grow, alpha in ((7, 22), (4, 38), (2, 60)):
            painter.fillRect(rect.adjusted(-grow + 3, -grow + 4, grow + 3, grow + 4), QColor(0, 0, 0, alpha))
        painter.fillRect(rect, self.BACK_COL)
        layer = self._grid_layer(rect)
        if layer is not None:
            painter.drawPixmap(layer[1], layer[0])
        painter.setPen(QPen(QColor(64, 70, 80), 1))
        painter.setBrush(Qt.NoBrush)
        painter.drawRect(rect)
        if self._picture is not None:
            layer = self._sheet_layer(rect)
            if layer is not None:
                painter.drawPixmap(layer[1], layer[0])
        elif not self._pixmap.isNull():
            painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
            painter.drawPixmap(rect, self._pixmap, QRectF(self._pixmap.rect()))
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setRenderHint(QPainter.TextAntialiasing, True)
        if not self._layout.get("placements"):
            painter.setPen(QColor(170, 178, 189))
            painter.setFont(QFont("Arial", 12))
            painter.drawText(rect, Qt.AlignCenter | Qt.TextWordWrap, self.empty_hint)
        layer = self._overlay_layer(rect)
        if layer is not None:
            painter.drawPixmap(layer[1], layer[0])
        self._paint_live_dimensions(painter, rect)
        sx, sy = rect.width() / self.page_w, rect.height() / self.page_h
        if self._snap_guides:
            # alignment with another view: the sketcher's magenta "on a line" snap colour
            painter.setPen(QPen(QColor(255, 90, 255, 200), 1, Qt.DashLine))
            for axis, value in self._snap_guides:
                if axis == 0:
                    x = rect.left() + value * sx
                    painter.drawLine(QPointF(x, rect.top()), QPointF(x, rect.bottom()))
                else:
                    y = rect.top() + value * sy
                    painter.drawLine(QPointF(rect.left(), y), QPointF(rect.right(), y))
        framed = ([self.selected] if self.selected is not None else []) + self.selected_views
        if framed:
            for info in self._layout.get("placements", []):
                index = info.get("record_index")
                if isinstance(index, int) and 0 <= index < len(self.view_placements) and \
                        any(self.view_placements[index] is record for record in framed):
                    frame = QRectF(rect.left() + info["x"] * sx, rect.top() + info["y"] * sy,
                                   info["width"] * sx, info["height"] * sy).adjusted(-6, -6, 6, 6)
                    painter.setPen(QPen(QColor(255, 120, 0, 200), 1, Qt.DashLine))
                    painter.setBrush(QColor(255, 120, 0, 18))
                    painter.drawRect(frame)
                    painter.setPen(Qt.NoPen)
                    painter.setBrush(self.SELECT_COL)
                    for corner in (frame.topLeft(), frame.topRight(),
                                   frame.bottomLeft(), frame.bottomRight()):
                        painter.drawRect(QRectF(corner.x() - 3, corner.y() - 3, 6, 6))
                    painter.setBrush(Qt.NoBrush)
        if self._band_rect is not None:              # rubber band, as in the sketcher
            painter.setPen(QPen(QColor(200, 200, 200, 180), 1, Qt.DashLine))
            painter.setBrush(QColor(180, 180, 180, 30))
            painter.drawRect(self._band_rect)
            painter.setBrush(Qt.NoBrush)
        self._paint_geometry_marks(painter, rect)
        active_cut = self._cut_drag or self._hover_cut
        if active_cut is not None:          # glow along the cutting line that is hovered / dragged
            for trace in self._cut_traces():
                if trace["view"] == active_cut["view"] and trace["letter"] == active_cut["letter"]:
                    a, b = (QPointF(rect.left() + end[0] * sx, rect.top() + end[1] * sy)
                            for end in trace["ends"])
                    painter.setPen(QPen(self.GLOW_COL, 10, Qt.SolidLine, Qt.RoundCap))
                    painter.drawLine(a, b)
        self._paint_dimension_picks(painter, rect)
        self._paint_hud(painter, rect)
        painter.end()

    @staticmethod
    def _view_page_point(position, info):
        if info.get("breaks"):                        # broken view: the bands are left out
            u, v = _drawing_break_map(position, info["breaks"], info["scale"])
            return (info["x"] + (u - info["low"][0]) * info["scale"],
                    info["y"] + info["height"] - (v - info["low"][1]) * info["scale"])
        return (info["x"] + (position[0] - info["low"][0]) * info["scale"],
                info["y"] + (info["high"][1] - position[1]) * info["scale"])

    def _screen_point(self, position, info, sheet_rect):
        page_x, page_y = self._view_page_point(position, info)
        return QPointF(sheet_rect.left() + page_x / self.page_w * sheet_rect.width(),
                       sheet_rect.top() + page_y / self.page_h * sheet_rect.height())


def _drawing_source_mesh(entry, objects):
    """Mesh of an extrusion plus its additive descendant extrusions (child sketches' bodies).
    Bodies are concatenated, not CSG-unioned: a union of filleted bodies takes minutes."""
    parts = [entry] + [o for o in entry_descendants(entry, objects)
                       if o.get("type") == "extrusion" and not o.get("cut")
                       and not o.get("preview") and o.get("solid") and entry_visible(o)]
    verts, tris = [], []
    for part in parts:
        v, t = part["solid"]; offset = len(verts)
        verts += list(v); tris += [(a + offset, b + offset, c + offset) for a, b, c in t]
    return verts, tris


DRAWING_EXPORT_FILTERS = (("PDF document (*.pdf)", ".pdf"), ("SVG drawing (*.svg)", ".svg"),
                          ("DXF drawing (*.dxf)", ".dxf"))


def _ask_drawing_export_path(parent, suggested=""):
    """Save dialog for a drawing; returns (path, ".pdf" | ".svg" | ".dxf") or (None, None)."""
    path, selected_filter = QFileDialog.getSaveFileName(
        parent, "Export Technical Drawing", suggested,
        ";;".join(name for name, _extension in DRAWING_EXPORT_FILTERS))
    if not path:
        return None, None
    extension = os.path.splitext(path)[1].lower()
    if extension not in [ext for _name, ext in DRAWING_EXPORT_FILTERS]:
        path += next((ext for name, ext in DRAWING_EXPORT_FILTERS if name == selected_filter), ".pdf")
        extension = os.path.splitext(path)[1].lower()
    return path, extension


def write_technical_drawing(path, extension, mesh, options):
    """Export a drawing as PDF, SVG or DXF (always black on a white sheet)."""
    writer = {".pdf": write_technical_drawing_pdf, ".svg": write_technical_drawing_svg,
              ".dxf": write_technical_drawing_dxf}.get(extension)
    if writer is None:
        raise ValueError(f"Unsupported drawing format: {extension}")
    writer(path, mesh, options)


def _drawing_svg_generator(sheet, output, title="SimpleCAD Technical Drawing"):
    """SVG generator whose user units are the drawing's page units (0.25 mm)."""
    generator = QSvgGenerator()
    if isinstance(output, str):
        generator.setFileName(output)
    else:
        generator.setOutputDevice(output)
    generator.setResolution(int(round(25.4 * DRAWING_UNITS_PER_MM)))     # 1 unit = 0.25 mm
    generator.setSize(QSize(int(round(sheet["w"])), int(round(sheet["h"]))))
    generator.setViewBox(QRectF(0, 0, sheet["w"], sheet["h"]))
    generator.setTitle(title)
    return generator


def write_technical_drawing_svg(path, mesh, options):
    """SVG of the drawing in the size of its sheet, always black on a white sheet."""
    options = dict(options, _colors=DRAWING_PRINT_COLORS, _page_scale=1.0)
    generator = _drawing_svg_generator(_drawing_sheet(options), path)
    painter = QPainter()
    if not painter.begin(generator):
        raise RuntimeError(f"Could not create SVG drawing:\n{path}")
    try:
        _draw_technical_drawing(painter, *(mesh if mesh is not None else (None, None)),
                                options)
    finally:
        painter.end()


def write_technical_drawing_pdf(path, mesh, options):
    """PDF of the drawing on its sheet (A2 … A5, landscape or portrait), black on white."""
    write_technical_drawing_pdf_pages(path, [(mesh, options)])


# DXF export: the drawing is rendered once more as SVG (page units, print palette) and its lines,
# filled arrowheads, circles and texts are written as an AutoCAD R12 DXF in millimetres, sorted
# into layers by line type. Pictures (the shaded isometric, a logo) are left out.
DXF_LAYERS = (("OUTLINE", 7, "CONTINUOUS"), ("THIN", 7, "CONTINUOUS"),
              ("HIDDEN", 5, "DASHED"), ("CENTER", 1, "CENTER"),
              ("FRAME", 7, "CONTINUOUS"), ("TEXT", 7, "CONTINUOUS"))
DXF_LINETYPES = (("CONTINUOUS", "Solid line", ()),
                 ("DASHED", "Dashed __ __ __", (3.0, -0.75)),                 # DIN type 02.1
                 ("CENTER", "Center ____ _ ____", (6.0, -0.75, 0.0, -0.75)))  # DIN type 04.1


def _svg_matrix(text):
    """3x3 matrix of an SVG transform attribute (matrix / translate / scale / rotate)."""
    result = np.eye(3)
    for name, values in re.findall(r"(\w+)\s*\(([^)]*)\)", text or ""):
        numbers = [float(value) for value in re.split(r"[\s,]+", values.strip()) if value]
        if name == "matrix" and len(numbers) == 6:
            a, b, c, d, e, f = numbers
            m = np.array(((a, c, e), (b, d, f), (0, 0, 1)))
        elif name == "translate" and numbers:
            m = np.array(((1, 0, numbers[0]), (0, 1, numbers[1] if len(numbers) > 1 else 0), (0, 0, 1)))
        elif name == "scale" and numbers:
            sy = numbers[1] if len(numbers) > 1 else numbers[0]
            m = np.diag((numbers[0], sy, 1.0))
        elif name == "rotate" and numbers:
            t = math.radians(numbers[0])
            m = np.array(((math.cos(t), -math.sin(t), 0), (math.sin(t), math.cos(t), 0), (0, 0, 1)))
        else:
            continue
        result = result @ m
    return result


def _svg_arc_points(start, rx, ry, rotation, large, sweep, end):
    """Points (after `start`) of an SVG elliptical arc, by the endpoint parameterisation of
    the SVG specification (appendix F.6)."""
    x1, y1 = start
    x2, y2 = end
    if (x1, y1) == (x2, y2):
        return []
    rx, ry = abs(rx), abs(ry)
    if rx < 1e-12 or ry < 1e-12:
        return [end]
    phi = math.radians(rotation)
    cos_phi, sin_phi = math.cos(phi), math.sin(phi)
    dx, dy = (x1 - x2) / 2.0, (y1 - y2) / 2.0
    xp, yp = cos_phi * dx + sin_phi * dy, -sin_phi * dx + cos_phi * dy
    grow = xp * xp / (rx * rx) + yp * yp / (ry * ry)
    if grow > 1.0:
        rx, ry = rx * math.sqrt(grow), ry * math.sqrt(grow)
    numerator = rx * rx * ry * ry - rx * rx * yp * yp - ry * ry * xp * xp
    denominator = rx * rx * yp * yp + ry * ry * xp * xp
    factor = math.sqrt(max(0.0, numerator / denominator)) if denominator > 1e-24 else 0.0
    if large == sweep:
        factor = -factor
    cxp, cyp = factor * rx * yp / ry, -factor * ry * xp / rx
    cx = cos_phi * cxp - sin_phi * cyp + (x1 + x2) / 2.0
    cy = sin_phi * cxp + cos_phi * cyp + (y1 + y2) / 2.0

    def angle(ux, uy, vx, vy):
        return math.atan2(ux * vy - uy * vx, ux * vx + uy * vy)

    theta = angle(1.0, 0.0, (xp - cxp) / rx, (yp - cyp) / ry)
    delta = angle((xp - cxp) / rx, (yp - cyp) / ry, (-xp - cxp) / rx, (-yp - cyp) / ry)
    if not sweep and delta > 0:
        delta -= 2.0 * math.pi
    elif sweep and delta < 0:
        delta += 2.0 * math.pi
    count = max(2, int(math.ceil(abs(delta) / math.radians(5.0))))
    points = []
    for step in range(1, count + 1):
        t = theta + delta * step / count
        ex, ey = rx * math.cos(t), ry * math.sin(t)
        points.append((cos_phi * ex - sin_phi * ey + cx, sin_phi * ex + cos_phi * ey + cy))
    points[-1] = (x2, y2)
    return points


def _svg_path_polylines(d, pieces=None):
    """Polylines (lists of (x, y)) of an SVG path; curves and arcs are flattened. With a
    `pieces` list, every straight piece is also appended as ("line", a, b) and every curved one
    as ("curve", [points]) (what the drawing editor's dimension tools pick)."""
    tokens = re.findall(r"[MLHVCSQTAZmlhvcsqtaz]|[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?", d or "")
    polylines, current, command, index = [], [], None, 0
    position = start = (0.0, 0.0)
    last_control = None                      # for the smooth curves S / T
    last_kind = None

    def number():
        nonlocal index
        value = float(tokens[index])
        index += 1
        return value

    def add_line(a, b):
        if pieces is not None and a != b:
            pieces.append(("line", a, b))

    def add_curve(points):
        if pieces is not None and len(points) > 1:
            pieces.append(("curve", points))

    while index < len(tokens):
        token = tokens[index]
        if token.isalpha():
            command = token
            index += 1
            if command in "Zz":
                if current:
                    add_line(current[-1], start)
                    current.append(start)
                    polylines.append(current)
                current = []
                position = start
                last_kind = None
            continue
        if command is None:
            index += 1
            continue
        try:
            if command in ("M", "m"):
                if len(current) > 1:
                    polylines.append(current)
                x, y = number(), number()
                position = (x, y) if command == "M" else (position[0] + x, position[1] + y)
                start, current = position, [position]
                command = "L" if command == "M" else "l"
                last_kind = None
            elif command in ("L", "l"):
                x, y = number(), number()
                previous = position
                position = (x, y) if command == "L" else (position[0] + x, position[1] + y)
                add_line(previous, position)
                current.append(position)
                last_kind = None
            elif command in ("H", "h", "V", "v"):
                value = number()
                previous = position
                if command == "H":   position = (value, position[1])
                elif command == "h": position = (position[0] + value, position[1])
                elif command == "V": position = (position[0], value)
                else:                position = (position[0], position[1] + value)
                add_line(previous, position)
                current.append(position)
                last_kind = None
            elif command in ("C", "c", "S", "s", "Q", "q", "T", "t"):
                upper = command.upper()
                given = {"C": 3, "S": 2, "Q": 2, "T": 1}[upper]
                points = [(number(), number()) for _ in range(given)]
                if command.islower():
                    points = [(position[0] + x, position[1] + y) for x, y in points]
                if upper in "ST":               # first control point mirrored from the last curve
                    wanted = "cubic" if upper == "S" else "quadratic"
                    reflected = position
                    if last_control is not None and last_kind == wanted:
                        reflected = (2 * position[0] - last_control[0],
                                     2 * position[1] - last_control[1])
                    points = [reflected] + points
                cubic = upper in "CS"
                control = [position] + points
                curve = [position]
                for step in range(1, 9):
                    t = step / 8.0
                    if cubic:
                        weights = ((1 - t) ** 3, 3 * t * (1 - t) ** 2, 3 * t * t * (1 - t), t ** 3)
                    else:
                        weights = ((1 - t) ** 2, 2 * t * (1 - t), t * t)
                    curve.append((sum(w * p[0] for w, p in zip(weights, control)),
                                  sum(w * p[1] for w, p in zip(weights, control))))
                current.extend(curve[1:])
                add_curve(curve)
                last_control = points[-2]
                last_kind = "cubic" if cubic else "quadratic"
                position = points[-1]
            elif command in ("A", "a"):
                rx, ry, rotation = number(), number(), number()
                large, sweep = number() != 0, number() != 0
                x, y = number(), number()
                end = (x, y) if command == "A" else (position[0] + x, position[1] + y)
                arc = _svg_arc_points(position, rx, ry, rotation, large, sweep, end)
                current.extend(arc)
                add_curve([position] + arc)
                position = end
                last_kind = None
            else:                               # unsupported command: skip its numbers
                index += 1
        except (IndexError, ValueError):
            break
    if len(current) > 1:
        polylines.append(current)
    return polylines


def _svg_drawing_entities(svg_bytes):
    """Lines, solids, circles and texts (page units, SVG orientation) of a drawing's SVG."""
    root = ET.fromstring(svg_bytes)
    entities = []
    inherited = ("fill", "stroke", "stroke-width", "stroke-dasharray", "font-size")

    def layer_of(style):
        dash = [value for value in re.split(r"[\s,]+", style.get("stroke-dasharray", "") or "")
                if value and value != "none"]
        width = float(style.get("stroke-width", "1") or 1)
        if len(dash) >= 4:
            return "CENTER"
        if dash:
            return "HIDDEN"
        if width >= 2.5:
            return "FRAME"
        return "OUTLINE" if width >= 1.9 else "THIN"

    def ink(colour):
        return colour not in (None, "", "none") and colour.lower() not in ("#ffffff", "white")

    def visit(element, style, matrix):
        style = dict(style)
        for key in inherited:
            if element.get(key) is not None:
                style[key] = element.get(key)
        if element.get("transform"):
            matrix = matrix @ _svg_matrix(element.get("transform"))
        tag = element.tag.rsplit("}", 1)[-1]

        def to_page(points):
            return [tuple((matrix @ np.array((x, y, 1.0)))[:2]) for x, y in points]

        polylines, closed = [], False
        if tag == "path":
            polylines = _svg_path_polylines(element.get("d"))
        elif tag in ("polyline", "polygon"):
            values = [float(v) for v in re.split(r"[\s,]+", (element.get("points") or "").strip()) if v]
            points = list(zip(values[0::2], values[1::2]))
            if tag == "polygon" and points:
                points.append(points[0])
                closed = True
            polylines = [points]
        elif tag == "line":
            polylines = [[(float(element.get("x1", 0)), float(element.get("y1", 0))),
                          (float(element.get("x2", 0)), float(element.get("y2", 0)))]]
        elif tag == "rect":
            x, y = float(element.get("x", 0)), float(element.get("y", 0))
            w, h = float(element.get("width", 0)), float(element.get("height", 0))
            polylines = [[(x, y), (x + w, y), (x + w, y + h), (x, y + h), (x, y)]]
            closed = True
        elif tag in ("circle", "ellipse"):
            cx, cy = float(element.get("cx", 0)), float(element.get("cy", 0))
            rx = float(element.get("r", element.get("rx", 0)))
            ry = float(element.get("r", element.get("ry", rx)))
            if ink(style.get("stroke")) and abs(rx - ry) < 1e-9:
                centre = to_page([(cx, cy)])[0]
                scale = math.sqrt(abs(np.linalg.det(matrix[:2, :2])))
                entities.append(("circle", layer_of(style), centre, rx * scale))
            elif ink(style.get("stroke")):
                angles = np.linspace(0.0, 2 * math.pi, 49)
                polylines = [list(zip(cx + rx * np.cos(angles), cy + ry * np.sin(angles)))]
        elif tag == "text":
            content = "".join(element.itertext()).strip()
            if content and ink(element.get("fill", style.get("fill"))):
                position = to_page([(float(element.get("x", 0)), float(element.get("y", 0)))])[0]
                angle = -math.degrees(math.atan2(matrix[1, 0], matrix[0, 0]))
                scale = math.sqrt(abs(np.linalg.det(matrix[:2, :2])))
                size = float(element.get("font-size", style.get("font-size", "14")) or 14) * scale
                entities.append(("text", "TEXT", position, size, angle, content))
            return
        elif tag == "image":
            return
        for points in polylines:
            if len(points) < 2:
                continue
            points = to_page(points)
            filled = ink(style.get("fill")) and not ink(style.get("stroke"))
            unique = points[:-1] if len(points) > 2 and np.allclose(points[0], points[-1]) else points
            if filled and 3 <= len(unique) <= 4:          # arrowheads
                entities.append(("solid", "THIN", unique))
            elif ink(style.get("stroke")) or filled:
                layer = layer_of(style) if ink(style.get("stroke")) else "THIN"
                for a, b in zip(points[:-1], points[1:]):
                    if np.hypot(b[0] - a[0], b[1] - a[1]) > 1e-6:
                        entities.append(("line", layer, a, b))
        for child in element:
            visit(child, style, matrix)

    visit(root, {"fill": "black", "stroke": "none", "stroke-width": "1"}, np.eye(3))
    return entities


def _dxf_text(value):
    """Text for a DXF R12 TEXT entity: CAD codes for Ø ° ±, \\U+ escapes for other characters."""
    value = value.replace("⌀", "%%c").replace("Ø", "%%c").replace("°", "%%d").replace("±", "%%p")
    return "".join(ch if 32 <= ord(ch) < 127 else f"\\U+{ord(ch):04X}" for ch in value)


def write_technical_drawing_dxf(path, mesh, options):
    """DXF (AutoCAD R12, millimetres) of the drawing on its sheet, black on white as printed.
    DXF holds no pictures, so the isometric view is given by its edges."""
    options = dict(options, _colors=DRAWING_PRINT_COLORS, _page_scale=1.0, _iso_edges=True)
    sheet = _drawing_sheet(options)
    buffer = QBuffer()
    buffer.open(QBuffer.ReadWrite)
    generator = _drawing_svg_generator(sheet, buffer)
    painter = QPainter()
    if not painter.begin(generator):
        raise RuntimeError("Could not render the drawing for the DXF export")
    try:
        _draw_technical_drawing(painter, *(mesh if mesh is not None else (None, None)),
                                options)
    finally:
        painter.end()
    entities = _svg_drawing_entities(bytes(buffer.data()))
    unit = 1.0 / DRAWING_UNITS_PER_MM
    height = sheet["h"]
    cap_ratio = (_DRAWING_FONT_BASE.get(False) or (None, 0.716))[1]

    def xy(point, x_code=10):
        return [x_code, f"{point[0] * unit:.4f}", x_code + 10, f"{(height - point[1]) * unit:.4f}",
                x_code + 20, "0.0"]

    out = [0, "SECTION", 2, "HEADER", 9, "$ACADVER", 1, "AC1009", 9, "$INSUNITS", 70, 4,
           9, "$MEASUREMENT", 70, 1,
           9, "$EXTMIN", 10, "0.0", 20, "0.0", 30, "0.0",
           9, "$EXTMAX", 10, f"{sheet['w'] * unit:.4f}", 20, f"{height * unit:.4f}", 30, "0.0",
           9, "$LIMMIN", 10, "0.0", 20, "0.0",
           9, "$LIMMAX", 10, f"{sheet['w'] * unit:.4f}", 20, f"{height * unit:.4f}",
           0, "ENDSEC", 0, "SECTION", 2, "TABLES",
           0, "TABLE", 2, "LTYPE", 70, len(DXF_LINETYPES)]
    for name, description, pattern in DXF_LINETYPES:
        out += [0, "LTYPE", 2, name, 70, 0, 3, description, 72, 65, 73, len(pattern),
                40, f"{sum(abs(p) for p in pattern):.4f}"]
        for element in pattern:
            out += [49, f"{element:.4f}"]
    out += [0, "ENDTAB", 0, "TABLE", 2, "LAYER", 70, len(DXF_LAYERS)]
    for name, colour, linetype in DXF_LAYERS:
        out += [0, "LAYER", 2, name, 70, 0, 62, colour, 6, linetype]
    out += [0, "ENDTAB", 0, "TABLE", 2, "STYLE", 70, 1,
            0, "STYLE", 2, "STANDARD", 70, 0, 40, "0.0", 41, "1.0", 50, "0.0", 71, 0,
            42, "2.5", 3, "txt", 4, "",
            0, "ENDTAB", 0, "ENDSEC", 0, "SECTION", 2, "ENTITIES"]
    for entity in entities:
        kind, layer = entity[0], entity[1]
        if kind == "line":
            out += [0, "LINE", 8, layer] + xy(entity[2]) + xy(entity[3], 11)
        elif kind == "solid":
            corners = list(entity[2])
            if len(corners) == 3:
                corners.append(corners[2])
            else:                                       # SOLID takes its corners crosswise
                corners = [corners[0], corners[1], corners[3], corners[2]]
            out += [0, "SOLID", 8, layer]
            for code, corner in zip((10, 11, 12, 13), corners):
                out += xy(corner, code)
        elif kind == "circle":
            out += [0, "CIRCLE", 8, layer] + xy(entity[2]) + [40, f"{entity[3] * unit:.4f}"]
        elif kind == "text":
            _kind, _layer, position, size, angle, content = entity
            out += [0, "TEXT", 8, layer] + xy(position) + \
                [40, f"{size * cap_ratio * unit:.4f}", 1, _dxf_text(content),
                 50, f"{angle:.3f}", 7, "STANDARD"]
    out += [0, "ENDSEC", 0, "EOF"]
    with open(path, "w", encoding="ascii", errors="replace", newline="\r\n") as stream:
        for index in range(0, len(out), 2):
            stream.write(f"{out[index]:>3}\n{out[index + 1]}\n")


# ── imported 2-D graphics (SVG / DXF) and drawings with several sheets ────────
# An imported SVG or DXF is kept as vector data in millimetres (v pointing up, origin at the lower
# left of its extent) and placed on a sheet like a view: a "graphic-<id>" placement whose data is in
# the drawing's "graphics". It is drawn in the drawing's line roles (outlines, thin lines, hidden
# and centre lines), so the editor shows it in its screen colours and an export prints it black on
# white, and its corners, edges, circles and arcs can be dimensioned like those of a projected view.
GRAPHIC_THICK, GRAPHIC_THIN, GRAPHIC_HIDDEN, GRAPHIC_CENTRE = 0, 1, 2, 3
GRAPHIC_PENS = {GRAPHIC_THICK: (DRAWING_THICK, None, "visible"),
                GRAPHIC_THIN: (DRAWING_THIN, None, "visible"),
                GRAPHIC_HIDDEN: (DRAWING_THIN, DRAWING_DASH, "hidden"),
                GRAPHIC_CENTRE: (DRAWING_THIN, DRAWING_CHAIN, "centre")}
GRAPHIC_PREFIX = "graphic-"
GRAPHIC_MAX_POINTS = 1_500_000
# what each sheet of a drawing keeps for itself; everything else (the title block fields shared by
# all sheets, grid / snap, the logo, imported models and graphics) belongs to the whole drawing
DRAWING_SHEET_KEYS = ("name", "source", "front", "rotation", "scale_ratio", "view_placements",
                      "dimensions", "sections", "sheet", "orientation", "title", "number",
                      "material", "treatment", "notes", "unit", "dual_units", "parts_list",
                      "parts", "hole_table", "details", "aux_views", "hatch", "gear_table",
                      "gear_quality", "gear_simplified", "stackups")


def _graphic_id(name):
    """Graphic id of a "graphic-<id>" placement name, else None."""
    if isinstance(name, str) and name.startswith(GRAPHIC_PREFIX):
        return name[len(GRAPHIC_PREFIX):]
    return None


class _GraphicBuilder:
    """Collects imported 2-D geometry (file units, y pointing up) and turns it into graphic data:
    what is drawn (paths by line style, circles, fills, texts) and what the dimension tools pick
    (straight pieces, curved pieces, corners and centres)."""

    def __init__(self, unit=1.0):
        self.unit = float(unit)               # millimetres per file unit
        self.paths, self.circles, self.fills, self.texts = [], [], [], []
        self.lines, self.curves, self.points = [], [], []
        self.count = 0

    def _grow(self, amount):
        self.count += amount
        if self.count > GRAPHIC_MAX_POINTS:
            raise ValueError(f"The file is too complex to import (more than "
                             f"{GRAPHIC_MAX_POINTS:,} points)")

    def path(self, style, points):
        points = np.asarray(points, dtype=float).reshape(-1, 2)
        if len(points) >= 2 and np.isfinite(points).all():
            self._grow(len(points))
            self.paths.append((int(style), points))

    def pick_line(self, a, b):
        a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
        if np.isfinite(a).all() and np.isfinite(b).all() and float(np.linalg.norm(b - a)) > 1e-9:
            self.lines.append((a, b))
            self.points.extend((a, b))

    def pick_curve(self, points):
        points = np.asarray(points, dtype=float).reshape(-1, 2)
        if len(points) >= 2 and np.isfinite(points).all():
            self.curves.append(points)
            self.points.extend((points[0], points[-1]))

    def circle(self, style, centre, radius):
        if radius > 1e-9 and np.isfinite(centre).all():
            self._grow(1)
            self.circles.append((int(style), float(centre[0]), float(centre[1]), float(radius)))
            self.points.append(np.asarray(centre, dtype=float))

    def fill(self, rings):
        rings = [np.asarray(ring, dtype=float).reshape(-1, 2) for ring in rings if len(ring) >= 3]
        rings = [ring for ring in rings if np.isfinite(ring).all()]
        if rings:
            self._grow(sum(len(ring) for ring in rings))
            self.fills.append(rings)

    def text(self, position, height, angle, content):
        content = str(content).strip()
        if content and height > 1e-9 and np.isfinite(position).all():
            self.texts.append((float(position[0]), float(position[1]), float(height),
                               float(angle), content))

    def data(self, kind, name, path):
        """Graphic data in millimetres, moved so that its extent starts at (0, 0)."""
        extents = [points for _style, points in self.paths]
        extents += [ring for rings in self.fills for ring in rings]
        extents += [np.array(((x - r, y - r), (x + r, y + r))) for _s, x, y, r in self.circles]
        for x, y, height, angle, content in self.texts:
            width = 0.75 * height * len(content)
            a = math.radians(angle)
            extents.append(np.array(((x, y), (x + width * math.cos(a), y + width * math.sin(a)),
                                     (x - height * math.sin(a), y + height * math.cos(a)))))
        if not extents:
            raise ValueError("The file contains no drawable lines, curves or texts")
        everything = np.concatenate([np.asarray(e, dtype=float).reshape(-1, 2) for e in extents])
        low, high = everything.min(axis=0), everything.max(axis=0)
        unit = self.unit

        def mm(points):
            return np.round((np.asarray(points, dtype=float).reshape(-1, 2) - low) * unit, 4)

        size = (high - low) * unit
        lines = np.asarray([np.concatenate(pair) for pair in self.lines], dtype=float).reshape(-1, 4)
        points = mm(np.asarray(self.points, dtype=float).reshape(-1, 2)) if self.points else \
            np.zeros((0, 2))
        return {
            "kind": kind, "name": name, "path": path, "token": os.urandom(8).hex(),
            "width": float(max(size[0], 1e-3)), "height": float(max(size[1], 1e-3)),
            "polylines": [[style, mm(points_).ravel().tolist()] for style, points_ in self.paths],
            "circles": [[style, *mm([(x, y)])[0].tolist(), round(r * unit, 4)]
                        for style, x, y, r in self.circles],
            "fills": [[mm(ring).ravel().tolist() for ring in rings] for rings in self.fills],
            "texts": [[*mm([(x, y)])[0].tolist(), round(height * unit, 4), round(angle, 3), text]
                      for x, y, height, angle, text in self.texts],
            "lines": mm(lines.reshape(-1, 2)).reshape(-1, 4).tolist(),
            "curves": [mm(curve).ravel().tolist() for curve in self.curves],
            "points": (np.unique(points, axis=0) if len(points) else points).tolist(),
        }


# ── SVG import ────────────────────────────────────────────────────────────────
_SVG_UNITS_MM = {"mm": 1.0, "cm": 10.0, "in": 25.4, "pt": 25.4 / 72.0, "pc": 25.4 / 6.0,
                 "px": 25.4 / 96.0, "": 25.4 / 96.0, "q": 0.25}
_SVG_NUMBER = r"[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?"


def _svg_numbers(text):
    return [float(value) for value in re.findall(_SVG_NUMBER, text or "")]


def _svg_length_mm(text):
    """Millimetres of an SVG length ("210mm", "800", "11in"); None for percentages / nothing."""
    match = re.fullmatch(rf"\s*({_SVG_NUMBER})\s*([a-zA-Z%]*)\s*", text or "")
    if not match or match.group(2).lower() not in _SVG_UNITS_MM:
        return None
    return float(match.group(1)) * _SVG_UNITS_MM[match.group(2).lower()]


def _read_svg_graphic(path):
    """Graphic data of an SVG file: strokes become lines (outline or thin by their width, hidden
    or centre lines by their dash pattern), filled shapes fills, texts texts. Sizes follow the
    file's width / height (mm, cm, in, pt; px and plain numbers at 96 dpi)."""
    with open(path, "rb") as stream:
        raw = stream.read()
    try:
        root = ET.fromstring(raw)
    except ET.ParseError as ex:
        raise ValueError(f"Not a valid SVG file: {ex}") from ex
    if root.tag.rsplit("}", 1)[-1] != "svg":
        raise ValueError("The file is not an SVG drawing")
    view_box = _svg_numbers(root.get("viewBox"))
    width, height = _svg_length_mm(root.get("width")), _svg_length_mm(root.get("height"))
    if len(view_box) == 4 and view_box[2] > 0 and view_box[3] > 0:
        sx = width / view_box[2] if width else height / view_box[3] if height else 25.4 / 96.0
        sy = height / view_box[3] if height else sx
        origin = view_box[:2]
    else:
        sx = sy = 25.4 / 96.0
        origin = (0.0, 0.0)
    # millimetres with y pointing up (in the SVG it points down)
    root_matrix = np.array(((sx, 0.0, -sx * origin[0]), (0.0, -sy, sy * origin[1]), (0, 0, 1.0)))
    builder = _GraphicBuilder(1.0)
    ids = {element.get("id"): element for element in root.iter() if element.get("id")}
    inherited = ("fill", "stroke", "stroke-width", "stroke-dasharray", "font-size", "display",
                 "visibility")
    skipped = {"defs", "clipPath", "mask", "symbol", "marker", "metadata", "title", "desc", "style",
               "pattern", "linearGradient", "radialGradient", "filter", "script", "image",
               "namedview"}

    def ink(colour):
        return colour not in (None, "", "none", "transparent") and \
            colour.strip().lower() not in ("#ffffff", "#fff", "white")

    def style_of(element, style):
        style = dict(style)
        for key in inherited:
            if element.get(key) is not None:
                style[key] = element.get(key)
        for item in (element.get("style") or "").split(";"):
            key, _colon, value = item.partition(":")
            if key.strip() in inherited and value.strip():
                style[key.strip()] = value.strip()
        return style

    def line_style(style, matrix):
        dash = style.get("stroke-dasharray") or "none"
        dash = [] if dash.strip() == "none" else [v for v in _svg_numbers(dash) if v > 0]
        if len(dash) >= 4:
            return GRAPHIC_CENTRE
        if dash:
            return GRAPHIC_HIDDEN
        stroke_width = (_svg_numbers(style.get("stroke-width")) or [1.0])[0]
        width_mm = stroke_width * math.sqrt(abs(np.linalg.det(matrix[:2, :2])))
        return GRAPHIC_THICK if width_mm >= 0.4 else GRAPHIC_THIN

    def visit(element, style, matrix, depth=0, as_symbol=False):
        tag = element.tag.rsplit("}", 1)[-1] if isinstance(element.tag, str) else ""
        if depth > 60 or (tag in skipped and not as_symbol):
            return
        style = style_of(element, style)
        if style.get("display", "").strip() == "none" or \
                style.get("visibility", "").strip() in ("hidden", "collapse"):
            return
        if element.get("transform"):
            matrix = matrix @ _svg_matrix(element.get("transform"))

        def page(points):
            points = np.asarray(points, dtype=float).reshape(-1, 2)
            return points @ matrix[:2, :2].T + matrix[:2, 2]

        def number(key, default=0.0):
            values = _svg_numbers(element.get(key))
            return values[0] if values else default

        stroke, filled = ink(style.get("stroke")), ink(style.get("fill"))
        polylines, pieces = [], []
        if tag == "path":
            polylines = _svg_path_polylines(element.get("d"), pieces)
        elif tag in ("polyline", "polygon"):
            values = _svg_numbers(element.get("points"))
            points = list(zip(values[0::2], values[1::2]))
            if tag == "polygon" and points:
                points.append(points[0])
            polylines = [points]
            pieces = [("line", a, b) for a, b in zip(points[:-1], points[1:])]
        elif tag == "line":
            a, b = (number("x1"), number("y1")), (number("x2"), number("y2"))
            polylines, pieces = [[a, b]], [("line", a, b)]
        elif tag == "rect":
            x, y, w, h = number("x"), number("y"), number("width"), number("height")
            if w > 0 and h > 0:
                points = [(x, y), (x + w, y), (x + w, y + h), (x, y + h), (x, y)]
                polylines = [points]
                pieces = [("line", a, b) for a, b in zip(points[:-1], points[1:])]
        elif tag in ("circle", "ellipse"):
            cx, cy = number("cx"), number("cy")
            rx = number("r") if tag == "circle" else number("rx")
            ry = number("r") if tag == "circle" else number("ry", rx)
            if rx > 0 and ry > 0:
                linear = matrix[:2, :2]
                lengths = np.linalg.norm(linear, axis=0)
                uniform = abs(lengths[0] - lengths[1]) <= 1e-9 * max(lengths.max(), 1.0) and \
                    abs(float(linear[:, 0] @ linear[:, 1])) <= 1e-9 * max(lengths.max(), 1.0) ** 2
                if stroke and uniform and abs(rx - ry) <= 1e-9 * max(rx, 1.0):
                    builder.circle(line_style(style, matrix), page([(cx, cy)])[0],
                                   rx * float(lengths[0]))
                    if filled:
                        angles = np.linspace(0.0, 2.0 * math.pi, 73)
                        builder.fill([page(np.column_stack((cx + rx * np.cos(angles),
                                                            cy + ry * np.sin(angles))))])
                    return
                angles = np.linspace(0.0, 2.0 * math.pi, 73)
                points = [tuple(p) for p in np.column_stack((cx + rx * np.cos(angles),
                                                             cy + ry * np.sin(angles)))]
                polylines, pieces = [points], [("curve", points)]
        elif tag == "text":
            content = " ".join("".join(element.itertext()).split())
            if content and (filled or stroke):
                size = (_svg_numbers(style.get("font-size")) or [16.0])[0]
                x = number("x")
                y = number("y")
                if not element.get("x"):        # position on the first <tspan>
                    span = next((child for child in element
                                 if str(child.tag).rsplit("}", 1)[-1] == "tspan"), None)
                    if span is not None:
                        x = (_svg_numbers(span.get("x")) or [x])[0]
                        y = (_svg_numbers(span.get("y")) or [y])[0]
                scale = math.sqrt(abs(np.linalg.det(matrix[:2, :2])))
                builder.text(page([(x, y)])[0], 0.7 * size * scale,
                             math.degrees(math.atan2(matrix[1, 0], matrix[0, 0])), content)
            return
        elif tag == "use":
            reference = element.get("{http://www.w3.org/1999/xlink}href") or element.get("href")
            target = ids.get(reference[1:]) if reference and reference.startswith("#") else None
            if target is not None and target is not element:
                shift = np.array(((1.0, 0.0, number("x")), (0.0, 1.0, number("y")), (0, 0, 1.0)))
                symbol = str(target.tag).rsplit("}", 1)[-1] == "symbol"
                visit(target, style, matrix @ shift, depth + 1, as_symbol=symbol)
            return
        if polylines:
            if filled and not stroke:
                builder.fill([page(points) for points in polylines if len(points) >= 3])
            if stroke:
                kind = line_style(style, matrix)
                for points in polylines:
                    builder.path(kind, page(points))
                for piece in pieces:
                    if piece[0] == "line":
                        a, b = page([piece[1], piece[2]])
                        builder.pick_line(a, b)
                    else:
                        builder.pick_curve(page(piece[1]))
        for child in element:
            visit(child, style, matrix, depth + 1)

    visit(root, {"fill": "black", "stroke": "none", "stroke-width": "1"}, root_matrix)
    return builder.data("svg", os.path.basename(path), path)


# ── DXF import ────────────────────────────────────────────────────────────────
# $INSUNITS → millimetres (0 = unitless: taken as millimetres)
_DXF_UNITS_MM = {0: 1.0, 1: 25.4, 2: 304.8, 4: 1.0, 5: 10.0, 6: 1000.0, 9: 0.0254, 10: 914.4,
                 13: 0.001, 14: 100.0}


def _dxf_value(codes, code, default=None):
    return next((value for c, value in codes if c == code), default)


def _dxf_float(codes, code, default=0.0):
    try:
        value = float(_dxf_value(codes, code, default))
    except (TypeError, ValueError):
        return default
    return value if math.isfinite(value) else default


def _dxf_point_list(codes, x_code=10):
    """(x, y) pairs of a repeated point group (10/20, 11/21, …)."""
    points, x = [], None
    for code, value in codes:
        try:
            if code == x_code:
                x = float(value)
            elif code == x_code + 10 and x is not None:
                points.append((x, float(value)))
                x = None
        except ValueError:
            x = None
    return points


def _dxf_decode_text(text):
    """Plain text of a DXF TEXT / MTEXT value (special characters, MTEXT formatting removed)."""
    text = re.sub(r"\\U\+([0-9A-Fa-f]{4})", lambda m: chr(int(m.group(1), 16)), text or "")
    for code, character in (("%%c", "Ø"), ("%%C", "Ø"), ("%%d", "°"), ("%%D", "°"),
                            ("%%p", "±"), ("%%P", "±"), ("%%%", "%")):
        text = text.replace(code, character)
    text = text.replace("\\P", "\n").replace("\\~", " ").replace("\\\\", "\x00")
    text = re.sub(r"\\[ACcFfHhQqTWwp][^;]*;", "", text)           # font / height / colour codes
    text = re.sub(r"\\S([^;^/#]*)[\^/#]([^;]*);", r"\1/\2", text)  # stacked fractions
    text = re.sub(r"\\[LlOoKkNX]", "", text)
    text = text.replace("{", "").replace("}", "").replace("\x00", "\\")
    return text


def _dxf_bulge_points(a, b, bulge):
    """Points after `a` up to `b` of a polyline segment with a DXF bulge (tan of a quarter of the
    included angle; positive = counter-clockwise)."""
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    chord = b - a
    length = float(np.linalg.norm(chord))
    if abs(bulge) < 1e-9 or length < 1e-12:
        return np.asarray([b])
    theta = 4.0 * math.atan(bulge)
    direction = chord / length
    left = np.array((-direction[1], direction[0]))
    centre = (a + b) / 2.0 + left * (length / 2.0) / math.tan(theta / 2.0)
    radius = float(np.linalg.norm(a - centre))
    start = math.atan2(a[1] - centre[1], a[0] - centre[0])
    count = max(2, int(math.ceil(abs(theta) / math.radians(3.0))))
    angles = start + theta * np.arange(1, count + 1) / count
    points = np.column_stack((centre[0] + radius * np.cos(angles),
                              centre[1] + radius * np.sin(angles)))
    points[-1] = b
    return points


def _dxf_arc_points(centre, radius, start_deg, end_deg):
    """Counter-clockwise arc from start to end angle (degrees), about 3° per segment."""
    sweep = (end_deg - start_deg) % 360.0
    if sweep <= 1e-9:
        sweep = 360.0
    count = max(2, int(math.ceil(sweep / 3.0)))
    angles = np.radians(start_deg + sweep * np.arange(count + 1) / count)
    return np.column_stack((centre[0] + radius * np.cos(angles), centre[1] + radius * np.sin(angles)))


def _bspline_points(degree, knots, controls, weights=None):
    """Points along a (rational) B-spline by de Boor's algorithm; the control polygon when the
    knot vector does not fit."""
    controls = np.asarray(controls, dtype=float).reshape(-1, 2)
    count = len(controls)
    knots = np.asarray(knots, dtype=float)
    if degree < 1 or count <= degree or len(knots) != count + degree + 1 or \
            not np.all(np.diff(knots) >= -1e-12):
        return controls
    weights = np.asarray(weights, dtype=float) if weights is not None and \
        len(weights) == count else np.ones(count)
    homogeneous = np.column_stack((controls * weights[:, None], weights))
    low, high = knots[degree], knots[count]
    result = []
    for t in np.linspace(low, high, max(24, 10 * count)):
        span = int(np.searchsorted(knots, t, side="right")) - 1
        span = min(max(span, degree), count - 1)
        d = [homogeneous[j + span - degree].copy() for j in range(degree + 1)]
        for r in range(1, degree + 1):
            for j in range(degree, r - 1, -1):
                left = knots[j + span - degree]
                denominator = knots[j + 1 + span - r] - left
                alpha = 0.0 if abs(denominator) < 1e-15 else (t - left) / denominator
                d[j] = (1.0 - alpha) * d[j - 1] + alpha * d[j]
        point = d[degree]
        result.append(point[:2] / (point[2] if abs(point[2]) > 1e-15 else 1.0))
    return np.asarray(result)


def _dxf_hatch(codes):
    """Boundary and pattern of a DXF HATCH: (solid, rings [Nx2 in OCS], pattern lines
    [(angle°, base, offset, dashes)], pattern angle°, pattern scale). The boundary paths are
    polylines (with bulges) or edges (lines, circular and elliptic arcs, splines)."""
    count = len(codes)
    index = 0

    def take(code, default=None):
        """Value of `code` at the cursor (and advance), else the default."""
        nonlocal index
        if index < count and codes[index][0] == code:
            index += 1
            try:
                return float(codes[index - 1][1])
            except ValueError:
                return default
        return default

    def arc_points(centre, radius_x, ratio, major_angle, start, end, ccw):
        """Circular / elliptic arc of a boundary edge; clockwise edges store mirrored angles."""
        if not ccw:
            start, end = -start, -end
        sweep = (end - start) % 360.0 if ccw else -((start - end) % 360.0)
        if abs(sweep) < 1e-9:
            sweep = 360.0 if ccw else -360.0
        steps = max(4, int(math.ceil(abs(sweep) / 3.0)))
        t = np.radians(start + sweep * np.arange(steps + 1) / steps)
        local = np.column_stack((radius_x * np.cos(t), radius_x * ratio * np.sin(t)))
        c, s = math.cos(major_angle), math.sin(major_angle)
        return local @ np.array(((c, s), (-s, c))) + np.asarray(centre, dtype=float)

    solid = bool(int(_dxf_float(codes, 70, 0)) & 1) or int(_dxf_float(codes, 450, 0)) == 1
    while index < count and codes[index][0] != 91:
        index += 1
    paths = int(take(91, 0) or 0)
    rings = []
    for _path in range(paths):
        while index < count and codes[index][0] != 92:
            index += 1
        if index >= count:
            break
        flags = int(take(92, 0))
        points = []
        if flags & 2:                                    # polyline path
            has_bulge = bool(take(72, 0))
            take(73)
            vertices = []
            for _vertex in range(int(take(93, 0) or 0)):
                x, y = take(10), take(20)
                if x is None or y is None:
                    break
                vertices.append((x, y, take(42, 0.0) if has_bulge else 0.0))
            if vertices:
                points = [vertices[0][:2]]
                for (x0, y0, bulge), (x1, y1, _b) in zip(vertices, vertices[1:] + vertices[:1]):
                    points.extend(map(tuple, _dxf_bulge_points((x0, y0), (x1, y1), bulge)))
        else:                                            # edge path
            for _edge in range(int(take(93, 0) or 0)):
                kind = int(take(72, 0) or 0)
                if kind == 1:                            # line
                    a = (take(10, 0.0), take(20, 0.0))
                    b = (take(11, 0.0), take(21, 0.0))
                    piece = [a, b]
                elif kind == 2:                          # circular arc
                    centre = (take(10, 0.0), take(20, 0.0))
                    radius = take(40, 0.0)
                    start, end = take(50, 0.0), take(51, 360.0)
                    piece = arc_points(centre, radius, 1.0, 0.0, start, end, bool(take(73, 1)))
                elif kind == 3:                          # elliptic arc
                    centre = (take(10, 0.0), take(20, 0.0))
                    major = (take(11, 1.0), take(21, 0.0))
                    ratio = take(40, 1.0)
                    start, end = take(50, 0.0), take(51, 360.0)
                    piece = arc_points(centre, math.hypot(*major), ratio,
                                       math.atan2(major[1], major[0]), start, end,
                                       bool(take(73, 1)))
                elif kind == 4:                          # spline
                    degree = int(take(94, 3) or 3)
                    take(73); take(74); take(95); take(96)
                    knots, controls, weights, fit = [], [], [], []
                    while index < count and codes[index][0] in (40, 10, 20, 42):
                        code = codes[index][0]
                        value = take(code, 0.0)
                        if code == 40:
                            knots.append(value)
                        elif code == 10:
                            controls.append([value, 0.0])
                        elif code == 20 and controls:
                            controls[-1][1] = value
                        elif code == 42:
                            weights.append(value)
                    if take(97) is not None:
                        while index < count and codes[index][0] in (11, 21):
                            code = codes[index][0]
                            value = take(code, 0.0)
                            if code == 11:
                                fit.append([value, 0.0])
                            elif fit:
                                fit[-1][1] = value
                    for code in (12, 22, 13, 23):
                        take(code)
                    piece = _bspline_points(degree, knots, controls, weights or None) \
                        if len(controls) > degree else np.asarray(fit, dtype=float)
                else:
                    break
                piece = np.asarray(piece, dtype=float).reshape(-1, 2)
                if len(piece):
                    if points and np.allclose(points[-1], piece[0], atol=1e-9):
                        piece = piece[1:]
                    points.extend(map(tuple, piece))
        if len(points) >= 3:
            rings.append(np.asarray(points, dtype=float))
    lines = []
    while index < count and codes[index][0] != 78:
        index += 1
    for _line in range(int(take(78, 0) or 0) if index < count else 0):
        while index < count and codes[index][0] != 53:
            index += 1
        angle = take(53, 0.0)
        base = (take(43, 0.0), take(44, 0.0))
        offset = (take(45, 0.0), take(46, 0.0))
        dashes = [take(49, 0.0) for _dash in range(int(take(79, 0) or 0))]
        lines.append((angle, np.asarray(base), np.asarray(offset), dashes))
    return solid, rings, lines, _dxf_float(codes, 52, 0.0), _dxf_float(codes, 41, 1.0) or 1.0


def _hatch_segments(rings, lines, limit=200_000):
    """Pattern lines of a hatch clipped to its boundary (even-odd: islands stay free), with
    their dash patterns: [(a, b)] in the coordinates of the rings."""
    starts = np.concatenate([ring for ring in rings])
    ends = np.concatenate([np.roll(ring, -1, axis=0) for ring in rings])
    segments = []
    for angle, base, offset, dashes in lines:
        a = math.radians(angle)
        along = np.array((math.cos(a), math.sin(a)))
        normal = np.array((-math.sin(a), math.cos(a)))
        spacing = float(offset @ normal)
        if abs(spacing) < 1e-9:
            continue
        span = starts @ normal - float(base @ normal)
        first = int(math.ceil(min(span.min() / spacing, span.max() / spacing)))
        last = int(math.floor(max(span.min() / spacing, span.max() / spacing)))
        if last - first > 20000:                   # far too dense to be meant: leave it out
            continue
        period = sum(abs(dash) for dash in dashes)
        for k in range(first, last + 1):
            origin = base + k * offset
            side_a, side_b = (starts - origin) @ normal, (ends - origin) @ normal
            crossing = (side_a <= 0) != (side_b <= 0)
            if not crossing.any():
                continue
            fraction = side_a[crossing] / (side_a[crossing] - side_b[crossing])
            u_a, u_b = (starts[crossing] - origin) @ along, (ends[crossing] - origin) @ along
            positions = np.sort(u_a + (u_b - u_a) * fraction)
            for u0, u1 in zip(positions[0::2], positions[1::2]):
                if u1 - u0 < 1e-9:
                    continue
                if not dashes or period < 1e-9:
                    segments.append((origin + along * u0, origin + along * u1))
                else:
                    cursor = math.floor(u0 / period) * period
                    while cursor < u1:
                        for dash in dashes:
                            length = abs(dash) if dash else min(period * 0.05, 0.25)
                            if dash >= 0:
                                low, high = max(cursor, u0), min(cursor + length, u1)
                                if high > low:
                                    segments.append((origin + along * low, origin + along * high))
                            cursor += abs(dash)
                            if cursor >= u1:
                                break
                        if len(segments) > limit:
                            break
                if len(segments) > limit:
                    raise ValueError(f"The file is too complex to import (a hatch with more "
                                     f"than {limit:,} lines)")
    return segments


def _dxf_structure(path):
    """(header, layers, blocks, entities) of an ASCII DXF. An entity is (type, [(code, value)])."""
    with open(path, "rb") as stream:
        raw = stream.read()
    if raw.startswith(b"AutoCAD Binary DXF"):
        raise ValueError("Binary DXF files are not supported; save the drawing as ASCII DXF")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        text = raw.decode("cp1252", errors="replace")
    lines = text.splitlines()
    pairs = []
    for index in range(0, len(lines) - 1, 2):
        try:
            code = int(lines[index].strip())
        except ValueError as ex:
            raise ValueError(f"Not a valid DXF file (line {index + 1})") from ex
        pairs.append((code, lines[index + 1].strip()))
    header, layers, blocks, entities = {}, {}, {}, []
    section, block, index, count = None, None, 0, len(pairs)
    while index < count:
        code, value = pairs[index]
        if code == 0 and value == "SECTION":
            section = pairs[index + 1][1] if index + 1 < count and pairs[index + 1][0] == 2 else None
            index += 2
            continue
        if code == 0 and value in ("ENDSEC", "EOF"):
            section = None
            index += 1
            if value == "EOF":
                break
            continue
        if section == "HEADER":
            if code == 9:
                end = index + 1
                while end < count and pairs[end][0] not in (0, 9):
                    end += 1
                header[value] = pairs[index + 1:end]
                index = end
            else:
                index += 1
            continue
        if code != 0:
            index += 1
            continue
        end = index + 1
        while end < count and pairs[end][0] != 0:
            end += 1
        kind, codes = value, pairs[index + 1:end]
        index = end
        if section == "TABLES" and kind == "LAYER":
            flags = int(_dxf_float(codes, 70, 0))
            colour = int(_dxf_float(codes, 62, 7))
            layers[_dxf_value(codes, 2, "")] = {
                "linetype": str(_dxf_value(codes, 6, "") or ""),
                "lineweight": int(_dxf_float(codes, 370, -3)),
                "hidden": bool(flags & 1) or colour < 0}
        elif section == "BLOCKS":
            if kind == "BLOCK":
                block = {"base": (_dxf_float(codes, 10), _dxf_float(codes, 20)), "entities": []}
                blocks[_dxf_value(codes, 2, "")] = block
            elif kind == "ENDBLK":
                block = None
            elif block is not None:
                block["entities"].append((kind, codes))
        elif section == "ENTITIES":
            entities.append((kind, codes))
    return header, layers, blocks, entities


def _read_dxf_graphic(path):
    """Graphic data of an ASCII DXF (model space): lines, polylines with arcs, circles, arcs,
    ellipses, splines, solids, texts, block references and dimensions. Line types make hidden
    and centre lines; line weights below 0.4 mm, dimensions and annotations thin lines, all
    other lines outlines. Units follow $INSUNITS (unitless: millimetres)."""
    header, layers, blocks, entities = _dxf_structure(path)
    units = header.get("$INSUNITS")
    unit_code = int(_dxf_float(units, 70, 0)) if units else 0
    builder = _GraphicBuilder(_DXF_UNITS_MM.get(unit_code, 1.0))
    model = [entity for entity in entities if _dxf_float(entity[1], 67, 0) != 1]
    entities = model or entities                  # paper space only when there is nothing else

    def style_of(codes, thin):
        layer = layers.get(_dxf_value(codes, 8, "0"), {})
        linetype = str(_dxf_value(codes, 6, "BYLAYER") or "BYLAYER").upper()
        if linetype == "BYLAYER":
            linetype = layer.get("linetype", "").upper()
        if any(word in linetype for word in ("CENTER", "CENTRE", "DASHDOT", "CHAIN", "PHANTOM",
                                              "DIVIDE", "BORDER")):
            return GRAPHIC_CENTRE
        if any(word in linetype for word in ("HIDDEN", "DASH", "DOT")):
            return GRAPHIC_HIDDEN
        if thin:
            return GRAPHIC_THIN
        weight = int(_dxf_float(codes, 370, -1))
        if weight == -1:
            weight = layer.get("lineweight", -3)
        if weight >= 0:
            return GRAPHIC_THICK if weight >= 40 else GRAPHIC_THIN
        return GRAPHIC_THICK

    def transform_of(codes, matrix):
        """Entity coordinate system: a negative extrusion direction mirrors x (OCS)."""
        if _dxf_float(codes, 230, 1.0) < 0:
            return matrix @ np.diag((-1.0, 1.0, 1.0))
        return matrix

    def mapped(matrix, points):
        points = np.asarray(points, dtype=float).reshape(-1, 2)
        return points @ matrix[:2, :2].T + matrix[:2, 2]

    def text_angle(matrix, degrees):
        a = math.radians(degrees)
        direction = matrix[:2, :2] @ np.array((math.cos(a), math.sin(a)))
        return math.degrees(math.atan2(direction[1], direction[0]))

    def linear_scale(matrix):
        return math.sqrt(abs(np.linalg.det(matrix[:2, :2])))

    def polyline(matrix, style, vertices, closed):
        """Vertices [(x, y, bulge)]: straight pieces and arcs."""
        if len(vertices) < 2:
            return
        if closed:
            vertices = list(vertices) + [vertices[0]]
        drawn = [np.asarray(vertices[0][:2], dtype=float)]
        for (x0, y0, bulge), (x1, y1, _next) in zip(vertices[:-1], vertices[1:]):
            if abs(bulge) > 1e-9:
                arc = _dxf_bulge_points((x0, y0), (x1, y1), bulge)
                builder.pick_curve(mapped(matrix, np.vstack(((x0, y0), arc))))
                drawn.extend(arc)
            else:
                a, b = mapped(matrix, [(x0, y0), (x1, y1)])
                builder.pick_line(a, b)
                drawn.append(np.asarray((x1, y1), dtype=float))
        builder.path(style, mapped(matrix, np.asarray(drawn)))

    def text(matrix, position, height, angle, content):
        scale = linear_scale(matrix)
        builder.text(mapped(matrix, [position])[0], height * scale, text_angle(matrix, angle),
                     content)

    def convert(items, matrix, depth, thin):
        index = 0
        while index < len(items):
            kind, codes = items[index]
            index += 1
            vertices = []
            if kind == "POLYLINE":                       # followed by VERTEX … SEQEND
                while index < len(items) and items[index][0] in ("VERTEX", "SEQEND"):
                    vertex_kind, vertex_codes = items[index]
                    index += 1
                    if vertex_kind == "SEQEND":
                        break
                    if int(_dxf_float(vertex_codes, 70, 0)) & 128 and \
                            not int(_dxf_float(vertex_codes, 70, 0)) & 64:
                        continue                         # polyface mesh face records
                    vertices.append((_dxf_float(vertex_codes, 10), _dxf_float(vertex_codes, 20),
                                     _dxf_float(vertex_codes, 42)))
            if layers.get(_dxf_value(codes, 8, "0"), {}).get("hidden"):
                continue
            local = transform_of(codes, matrix)
            try:
                if kind == "LINE":
                    a, b = mapped(matrix, [(_dxf_float(codes, 10), _dxf_float(codes, 20)),
                                           (_dxf_float(codes, 11), _dxf_float(codes, 21))])
                    builder.path(style_of(codes, thin), [a, b])
                    builder.pick_line(a, b)
                elif kind == "LWPOLYLINE":
                    points = []
                    for code, value in codes:
                        if code == 10:
                            points.append([float(value), 0.0, 0.0])
                        elif code == 20 and points:
                            points[-1][1] = float(value)
                        elif code == 42 and points:
                            points[-1][2] = float(value)
                    polyline(local, style_of(codes, thin), [tuple(p) for p in points],
                             bool(int(_dxf_float(codes, 70, 0)) & 1))
                elif kind == "POLYLINE":
                    flags = int(_dxf_float(codes, 70, 0))
                    if not flags & 64:                   # not a polyface mesh
                        polyline(local if not flags & 8 else matrix, style_of(codes, thin),
                                 vertices, bool(flags & 1))
                elif kind in ("CIRCLE", "ARC"):
                    centre = (_dxf_float(codes, 10), _dxf_float(codes, 20))
                    radius = _dxf_float(codes, 40)
                    if radius <= 0:
                        continue
                    style = style_of(codes, thin)
                    linear = local[:2, :2]
                    lengths = np.linalg.norm(linear, axis=0)
                    uniform = abs(lengths[0] - lengths[1]) <= 1e-9 * max(lengths.max(), 1.0)
                    if kind == "CIRCLE" and uniform:
                        builder.circle(style, mapped(local, [centre])[0], radius * lengths[0])
                        continue
                    start, end = (0.0, 360.0) if kind == "CIRCLE" else \
                        (_dxf_float(codes, 50), _dxf_float(codes, 51))
                    points = mapped(local, _dxf_arc_points(centre, radius, start, end))
                    builder.path(style, points)
                    builder.pick_curve(points)
                    builder.points.append(mapped(local, [centre])[0])
                elif kind == "ELLIPSE":
                    centre = np.array((_dxf_float(codes, 10), _dxf_float(codes, 20)))
                    major = np.array((_dxf_float(codes, 11), _dxf_float(codes, 21)))
                    ratio = _dxf_float(codes, 40, 1.0)
                    start, end = _dxf_float(codes, 41, 0.0), _dxf_float(codes, 42, 2 * math.pi)
                    if end <= start:
                        end += 2.0 * math.pi
                    minor = ratio * np.array((-major[1], major[0]))
                    if _dxf_float(codes, 230, 1.0) < 0:
                        minor = -minor
                    t = np.linspace(start, end, max(12, int(math.ceil((end - start) / 0.05))))
                    points = centre + np.outer(np.cos(t), major) + np.outer(np.sin(t), minor)
                    points = mapped(matrix, points)
                    builder.path(style_of(codes, thin), points)
                    builder.pick_curve(points)
                elif kind == "SPLINE":
                    degree = int(_dxf_float(codes, 71, 3))
                    knots = [float(v) for c, v in codes if c == 40]
                    weights = [float(v) for c, v in codes if c == 41]
                    controls = _dxf_point_list(codes, 10)
                    fit = _dxf_point_list(codes, 11)
                    points = _bspline_points(degree, knots, controls, weights) \
                        if len(controls) > degree else np.asarray(fit, dtype=float)
                    if len(points) < 2 and fit:
                        points = np.asarray(fit, dtype=float)
                    if int(_dxf_float(codes, 70, 0)) & 1 and len(points) > 2:
                        points = np.vstack((points, points[:1]))
                    points = mapped(matrix, points)
                    builder.path(style_of(codes, thin), points)
                    builder.pick_curve(points)
                elif kind in ("SOLID", "TRACE"):
                    corners = [(_dxf_float(codes, c), _dxf_float(codes, c + 10))
                               for c in (10, 11, 13, 12)]          # given crosswise
                    builder.fill([mapped(local, corners)])
                elif kind == "HATCH":
                    solid, rings, lines, pattern_angle, pattern_scale = _dxf_hatch(codes)
                    if not rings:
                        continue
                    if solid:
                        builder.fill([mapped(local, ring) for ring in rings])
                        continue
                    if not lines:                       # no pattern data: 45° lines, 3.175 apart
                        a = math.radians(pattern_angle + 45.0)
                        spacing = 3.175 * pattern_scale
                        lines = [(pattern_angle + 45.0, np.zeros(2),
                                  np.array((-math.sin(a), math.cos(a))) * spacing, [])]
                    for a, b in _hatch_segments(rings, lines):
                        builder.path(GRAPHIC_THIN, mapped(local, [a, b]))
                elif kind in ("TEXT", "ATTRIB"):
                    if kind == "ATTRIB" and int(_dxf_float(codes, 70, 0)) & 1:
                        continue                                  # invisible attribute
                    aligned = int(_dxf_float(codes, 72, 0)) or int(_dxf_float(codes, 73, 0))
                    anchor = (_dxf_float(codes, 11), _dxf_float(codes, 21)) if aligned and \
                        _dxf_value(codes, 11) is not None else \
                        (_dxf_float(codes, 10), _dxf_float(codes, 20))
                    height = _dxf_float(codes, 40, 2.5)
                    content = _dxf_decode_text(_dxf_value(codes, 1, ""))
                    horizontal = int(_dxf_float(codes, 72, 0))
                    shift = {1: 0.5, 2: 1.0, 4: 0.5}.get(horizontal, 0.0) * 0.75 * height * \
                        len(content)
                    angle = _dxf_float(codes, 50)
                    a = math.radians(angle)
                    anchor = (anchor[0] - shift * math.cos(a), anchor[1] - shift * math.sin(a))
                    text(local if kind == "TEXT" else matrix, anchor, height, angle, content)
                elif kind == "MTEXT":
                    content = "".join(v for c, v in codes if c == 3) + (_dxf_value(codes, 1, "") or "")
                    content = _dxf_decode_text(content)
                    height = _dxf_float(codes, 40, 2.5)
                    if _dxf_value(codes, 11) is not None:
                        angle = math.degrees(math.atan2(_dxf_float(codes, 21), _dxf_float(codes, 11)))
                    else:
                        angle = _dxf_float(codes, 50)
                    attachment = int(_dxf_float(codes, 71, 1))
                    lines = [line for line in content.split("\n")]
                    spacing = 1.667 * height
                    total = height + spacing * (len(lines) - 1)
                    row, column = (attachment - 1) // 3, (attachment - 1) % 3
                    top = {0: 0.0, 1: total / 2.0, 2: total}.get(row, 0.0)
                    a = math.radians(angle)
                    along, up = np.array((math.cos(a), math.sin(a))), np.array((-math.sin(a), math.cos(a)))
                    insert = np.array((_dxf_float(codes, 10), _dxf_float(codes, 20)))
                    for number, line in enumerate(lines):
                        width = 0.75 * height * len(line)
                        dx = -width * (0.5 if column == 1 else 1.0 if column == 2 else 0.0)
                        position = insert + along * dx + up * (top - height - spacing * number)
                        text(matrix, position, height, angle, line)
                elif kind in ("INSERT", "DIMENSION") and depth < 16:
                    block = blocks.get(_dxf_value(codes, 2, ""))
                    if block is None:
                        continue
                    if kind == "DIMENSION":               # its block holds the drawn dimension
                        convert(block["entities"], matrix, depth + 1, True)
                        continue
                    x, y = _dxf_float(codes, 10), _dxf_float(codes, 20)
                    sx, sy = _dxf_float(codes, 41, 1.0) or 1.0, _dxf_float(codes, 42, 1.0) or 1.0
                    a = math.radians(_dxf_float(codes, 50))
                    base_x, base_y = block["base"]
                    columns = max(1, int(_dxf_float(codes, 70, 1)))
                    rows = max(1, int(_dxf_float(codes, 71, 1)))
                    column_gap, row_gap = _dxf_float(codes, 44), _dxf_float(codes, 45)
                    for row in range(min(rows, 100)):
                        for column in range(min(columns, 100)):
                            place = np.array(((math.cos(a), -math.sin(a), x),
                                              (math.sin(a), math.cos(a), y), (0.0, 0.0, 1.0)))
                            offset = np.array(((1.0, 0.0, column * column_gap),
                                               (0.0, 1.0, row * row_gap), (0.0, 0.0, 1.0)))
                            block_matrix = local @ place @ offset @ np.diag((sx, sy, 1.0)) @ \
                                np.array(((1.0, 0.0, -base_x), (0.0, 1.0, -base_y), (0.0, 0.0, 1.0)))
                            convert(block["entities"], block_matrix, depth + 1, thin)
            except (TypeError, ValueError, ZeroDivisionError, OverflowError) as ex:
                if "too complex" in str(ex):
                    raise
                continue                                  # a broken entity is left out

    convert(entities, np.eye(3), 0, False)
    return builder.data("dxf", os.path.basename(path), path)


def read_drawing_graphic(path):
    """Graphic data of an SVG or DXF file for a technical drawing."""
    extension = os.path.splitext(path)[1].lower()
    if extension == ".svg":
        return _read_svg_graphic(path)
    if extension == ".dxf":
        return _read_dxf_graphic(path)
    raise ValueError("Choose an .svg or a .dxf file")


# ── painting imported graphics ───────────────────────────────────────────────
_GRAPHIC_VIEWS = collections.OrderedDict()     # token → pickable view and painter paths


def _drawing_graphic_view(data):
    """A graphic as a "view" of the drawing (bounds, picking data) with its painter paths in
    graphic millimetres; cached by the graphic's token."""
    token = str(data.get("token") or id(data))
    view = _GRAPHIC_VIEWS.get(token)
    if view is not None:
        _GRAPHIC_VIEWS.move_to_end(token)
        return view
    paths = {}
    for style, flat in data.get("polylines", []):
        points = np.asarray(flat, dtype=float).reshape(-1, 2)
        if len(points) < 2:
            continue
        path = paths.setdefault(int(style), QPainterPath())
        path.moveTo(float(points[0, 0]), float(points[0, 1]))
        for x, y in points[1:]:
            path.lineTo(float(x), float(y))
    circle_curves = []
    angles = np.linspace(0.0, 2.0 * math.pi, 73)
    for style, cx, cy, radius in data.get("circles", []):
        paths.setdefault(int(style), QPainterPath()).addEllipse(
            QPointF(float(cx), float(cy)), float(radius), float(radius))
        circle_curves.append(np.column_stack((cx + radius * np.cos(angles),
                                              cy + radius * np.sin(angles))))
    fills = []                      # one path per fill: its holes (islands) stay open
    for rings in data.get("fills", []):
        fill = QPainterPath()
        fill.setFillRule(Qt.OddEvenFill)
        for flat in rings:
            points = np.asarray(flat, dtype=float).reshape(-1, 2)
            fill.addPolygon(QPolygonF([QPointF(float(x), float(y)) for x, y in points]))
            fill.closeSubpath()
        fills.append(fill)
    curves = [np.asarray(curve, dtype=float).reshape(-1, 2)
              for curve in data.get("curves", [])] + circle_curves
    view = {"bounds": (np.zeros(2), np.array((max(float(data.get("width", 1.0)), 1e-3),
                                              max(float(data.get("height", 1.0)), 1e-3)))),
            "right": np.array((1.0, 0.0, 0.0)), "up": np.array((0.0, 1.0, 0.0)),
            "pick_points": np.asarray(data.get("points", []), dtype=float).reshape(-1, 2),
            "pick_segments": np.asarray(data.get("lines", []), dtype=float).reshape(-1, 2, 2),
            "pick_curves": curves, "pick_arcs": circle_curves,
            "paths": paths, "fills": fills}
    _GRAPHIC_VIEWS[token] = view
    while len(_GRAPHIC_VIEWS) > 48:
        _GRAPHIC_VIEWS.popitem(last=False)
    return view


def _drawing_graphic_scale(record, data, default_scale):
    """Page units per millimetre of a placed graphic: its own scale, else the drawing's, else the
    largest ISO 5455 scale (at most 1:1) at which it fits on the sheet."""
    ratio = record.get("scale")
    if ratio:
        return float(ratio) * DRAWING_UNITS_PER_MM
    if default_scale:
        return float(default_scale)
    room_w = _DRAWING_PAGE["w"] - DRAWING_BORDER[0] - DRAWING_BORDER[2] - 80.0
    room_h = _DRAWING_PAGE["h"] - DRAWING_BORDER[1] - DRAWING_BORDER[3] - DRAWING_TITLE_H - 80.0
    fit = min(room_w / max(float(data["width"]), 1e-3), room_h / max(float(data["height"]), 1e-3))
    return _drawing_nice_scale(min(fit, DRAWING_UNITS_PER_MM))


def _paint_drawing_graphics(painter, options, default_scale, places):
    """Paint the imported graphics placed on the sheet; each one is added to `places` (by its
    placement name) so its geometry can be dimensioned."""
    graphics = options.get("graphics") or {}
    thick_scale = float(options.get("_thick_scale", 1.0))
    for index, record in enumerate(options.get("view_placements", [])):
        data = graphics.get(_graphic_id(record.get("name")))
        if not isinstance(data, dict):
            continue
        view = _drawing_graphic_view(data)
        scale = _drawing_graphic_scale(record, data, default_scale)
        place = _DrawingPlacement(view, float(record.get("x", 60.0)), float(record.get("y", 60.0)),
                                  scale)
        place.record_index = index
        places[record["name"]] = place
        # graphic millimetres (v up) → page units (y down)
        transform = QTransform(scale, 0.0, 0.0, -scale, place.rect.left(), place.rect.bottom())
        painter.save()
        if view["fills"]:
            painter.setPen(Qt.NoPen)
            painter.setBrush(_drawing_color("visible"))
            for fill in view["fills"]:
                painter.drawPath(transform.map(fill))
        painter.setBrush(Qt.NoBrush)
        for style in sorted(view["paths"]):
            width, pattern, role = GRAPHIC_PENS.get(style, GRAPHIC_PENS[GRAPHIC_THIN])
            if style == GRAPHIC_THICK:
                width *= thick_scale
            painter.setPen(_drawing_pen(width, pattern, role))
            painter.drawPath(transform.map(view["paths"][style]))
        painter.setPen(_drawing_color("text"))
        for x, y, height, angle, content in data.get("texts", []):
            painter.save()
            painter.translate(place.point(float(x), float(y)))
            painter.rotate(-float(angle))
            painter.setFont(_drawing_font(float(height) * scale))
            for number, line in enumerate(str(content).split("\n")):
                painter.drawText(QPointF(0.0, number * 1.667 * float(height) * scale), line)
            painter.restore()
        painter.restore()


# ── drawings with several sheets ─────────────────────────────────────────────
def drawing_sheet_options(options):
    """Complete options of every sheet of a drawing: the shared fields with each sheet's own,
    numbered "n / N". A drawing without "sheets" (older files) is one sheet."""
    sheets = options.get("sheets") or [
        {key: options[key] for key in DRAWING_SHEET_KEYS if key in options}]
    shared = {key: value for key, value in options.items()
              if key not in DRAWING_SHEET_KEYS and key not in ("sheets", "active_sheet")}
    result = []
    for number, sheet in enumerate(sheets, 1):
        merged = dict(shared)
        merged.update(sheet)
        merged["page"] = f"{number} / {len(sheets)}"
        result.append(merged)
    return result


def _validated_drawing_sheet(options, graphic_ids, model_ids):
    """One sheet of a drawing read from a project file, with every value checked (older files:
    the top-level fields of the drawing)."""
    rotation = [float(value) for value in options.get("rotation", (0, 0, 0))]
    cut_offset = float(options.get("cut_offset", 0.0))
    dimensions = options.get("dimensions", [])
    placements = options.get("view_placements", [])
    if len(rotation) != 3 or not np.isfinite(rotation).all() or \
            not math.isfinite(cut_offset) or not isinstance(dimensions, list) or \
            not isinstance(placements, list):
        raise ValueError("invalid rotation, views or dimensions")
    options["rotation"] = [int(round(value / 90.0) * 90) % 360 for value in rotation]
    options["cut_offset"] = cut_offset
    options["view_scale"] = min(3.0, max(0.1, float(options.get("view_scale", 1.0))))
    ratio = options.get("scale_ratio")
    options["scale_ratio"] = float(ratio) if ratio is not None and \
        math.isfinite(float(ratio)) and float(ratio) > 0 else None
    if options.get("projection") not in ("first", "third"):
        options.pop("projection", None)
    for key in ("title", "number", "tolerance", "surface", "name"):
        if key in options:
            options[key] = str(options[key])[:200]
    options["section_view"] = min(2, max(0, int(options.get("section_view", 0))))
    # cut sections A-A, B-B, … (older files: one section from section / cut_offset)
    options["sections"] = _drawing_sections(options)
    for key in ("section", "section_view", "cut_offset"):
        options.pop(key, None)
    source = options.get("source")
    if isinstance(source, dict) and source.get("kind") == "project" and source.get("name"):
        options["source"] = {"kind": "project", "name": str(source["name"])}
        try:                                      # exploded assembly view (Phase 5)
            explode = float(source.get("explode") or 0.0)
        except (TypeError, ValueError):
            explode = 0.0
        if math.isfinite(explode) and explode > 0.0:
            options["source"]["explode"] = min(explode, 10000.0)
    elif isinstance(source, dict) and source.get("kind") == "model" and \
            source.get("id") in model_ids:
        options["source"] = {"kind": "model", "id": str(source["id"])}
    elif "source" in options:
        options["source"] = None
    main_views = DRAWING_MAIN_VIEWS
    valid_names = {*DRAWING_MAIN_VIEWS, "isometric", "section"} | \
        {f"section-{item['letter']}" for item in options["sections"]} | \
        {GRAPHIC_PREFIX + graphic_id for graphic_id in graphic_ids}
    # Phase 3: auxiliary views of a main view, detail views of any placed view
    def letter_of(item):
        letter = str(item.get("letter", "")).strip().upper()[:1]
        return letter if letter.isalpha() else None

    def pair_of(value):
        if isinstance(value, (list, tuple)) and len(value) == 2 and \
                all(tol_number(v) is not None for v in value):
            return [float(value[0]), float(value[1])]
        return None
    aux_views = []
    for item in options.get("aux_views") or []:
        if isinstance(item, dict) and letter_of(item) and item.get("view") in main_views and \
                pair_of(item.get("a")) and pair_of(item.get("b")):
            aux_views.append({"letter": letter_of(item), "view": item["view"], "a": pair_of(item["a"]),
                              "b": pair_of(item["b"]), "flip": bool(item.get("flip"))})
    options["aux_views"] = aux_views
    valid_names |= {f"aux-{item['letter']}" for item in aux_views}
    details = []
    for item in options.get("details") or []:
        if not isinstance(item, dict) or not letter_of(item) or item.get("view") not in valid_names:
            continue
        values = [tol_number(item.get(key)) for key in ("u", "v", "r", "factor")]
        if None in values[:3] or values[2] <= 0:
            continue
        factor = values[3] if values[3] is not None and 0.01 <= values[3] <= 100 else 2.0
        details.append({"letter": letter_of(item), "view": item["view"], "u": values[0],
                        "v": values[1], "r": values[2], "factor": factor})
    options["details"] = details
    valid_names |= {f"detail-{item['letter']}" for item in details}
    if options.get("hatch") not in DRAWING_HATCHES:
        options.pop("hatch", None)
    # Phase 4: gear data table, quality, simplified teeth
    table = options.get("gear_table")
    if isinstance(table, dict) and tol_number(table.get("x")) is not None and \
            tol_number(table.get("y")) is not None:
        options["gear_table"] = {"x": float(table["x"]), "y": float(table["y"])}
    else:
        options.pop("gear_table", None)
    if str(options.get("gear_quality")) not in DRAWING_GEAR_QUALITIES:
        options.pop("gear_quality", None)
    options["gear_simplified"] = bool(options.get("gear_simplified", True))
    # Phase 5: tolerance stack-ups
    stackups = []
    for item in (options.get("stackups") or [])[:20]:
        if not isinstance(item, dict):
            continue
        rows = []
        for row in (item.get("rows") or [])[:60]:
            if not isinstance(row, dict) or any(tol_number(row.get(key)) is None
                                                for key in ("nominal", "upper", "lower")):
                continue
            clean = {"name": str(row.get("name", ""))[:60], "nominal": float(row["nominal"]),
                     "upper": float(row["upper"]), "lower": float(row["lower"]),
                     "sign": -1 if tol_number(row.get("sign")) is not None and row["sign"] < 0 else 1}
            if isinstance(row.get("dim"), int) and not isinstance(row.get("dim"), bool):
                clean["dim"] = int(row["dim"])
            rows.append(clean)
        if not rows:
            continue
        stackup = {"name": str(item.get("name", "Gap"))[:60], "rows": rows,
                   "min": tol_number(item.get("min")), "max": tol_number(item.get("max")),
                   "show": bool(item.get("show"))}
        if tol_number(item.get("x")) is not None and tol_number(item.get("y")) is not None:
            stackup.update(x=float(item["x"]), y=float(item["y"]))
        stackups.append(stackup)
    options["stackups"] = stackups
    options["view_placements"] = []
    for item in placements:
        if not isinstance(item, dict) or item.get("name") not in valid_names:
            continue
        x, y = float(item.get("x", 0.0)), float(item.get("y", 0.0))
        if math.isfinite(x) and math.isfinite(y):
            record = {"name": item["name"], "x": x, "y": y,
                      "hidden_lines": bool(item.get("hidden_lines", True))}
            if item["name"] in main_views or str(item["name"]).startswith("aux-"):
                breaks = []
                for entry in (item.get("breaks") or [])[:8]:
                    if isinstance(entry, dict) and tol_number(entry.get("a")) is not None and \
                            tol_number(entry.get("b")) is not None:
                        breaks.append({"axis": "v" if entry.get("axis") == "v" else "u",
                                       "a": float(entry["a"]), "b": float(entry["b"])})
                if breaks:
                    record["breaks"] = breaks
            broken_out = item.get("broken_out")
            if item["name"] in main_views and isinstance(broken_out, dict):
                rect = broken_out.get("rect")
                depth = tol_number(broken_out.get("depth"))
                if isinstance(rect, (list, tuple)) and len(rect) == 4 and depth is not None and \
                        all(tol_number(v) is not None for v in rect):
                    record["broken_out"] = {"rect": [float(v) for v in rect], "depth": depth}
            scale = item.get("scale")
            if _graphic_id(item["name"]) and isinstance(scale, (int, float)) and \
                    math.isfinite(scale) and scale > 0:
                record["scale"] = float(scale)
            options["view_placements"].append(record)
    options["dimensions"] = []
    for item in dimensions[:200]:
        if not isinstance(item, dict):
            continue
        value = float(item.get("value", 0.0))
        if not math.isfinite(value):
            continue
        dimension = {"label": str(item.get("label", "Measurement"))[:80], "value": value}
        kind = item.get("type")
        if kind in ("length", "radius", "diameter", "angle", "chamfer", "arc", "ordinate"):
            dimension["type"] = kind
            needed = 3 if kind == "arc" else 2 if kind in ("chamfer", "ordinate") else None
            if needed and len(item.get("points") or []) != needed:
                continue
        elif kind == "annotation":
            annotation = tol_normalize_annotation(item.get("ann"))
            tip = item.get("points")
            if annotation is None or item.get("view") not in valid_names or \
                    not (isinstance(tip, list) and len(tip) == 1 and isinstance(tip[0], (list, tuple))
                         and len(tip[0]) == 2 and np.isfinite([float(v) for v in tip[0]]).all()):
                continue
            options["dimensions"].append({"type": "annotation", "label": "", "value": 0.0,
                                          "view": item["view"], "ann": annotation,
                                          "points": [[float(v) for v in tip[0]]]})
            continue
        if item.get("view") in valid_names:
            raw_points = item.get("points")
            if raw_points is None and isinstance(item.get("a"), (list, tuple)) and \
                    isinstance(item.get("b"), (list, tuple)):
                raw_points = [item["a"], item["b"]]
            if isinstance(raw_points, list) and len(raw_points) in (2, 3) and \
                    all(isinstance(point, (list, tuple)) and len(point) == 2
                        for point in raw_points):
                points = [[float(v) for v in point] for point in raw_points]
                if np.isfinite(points).all():
                    dimension.update(view=item["view"], points=points)
                    if len(points) == 2:
                        dimension.update(a=points[0], b=points[1])
        # where the dimension line and its text were dragged to
        for key in ("offset_distance", "text_shift", "text_lift", "angle", "leader_length",
                    "chamfer_angle", "level"):
            if isinstance(item.get(key), (int, float)) and math.isfinite(item[key]):
                dimension[key] = float(item[key])
        if item.get("orient") in ("h", "v"):
            dimension["orient"] = item["orient"]
        if item.get("axis") in ("x", "y"):
            dimension["axis"] = item["axis"]
        for key in ("reference", "sweep_negative"):
            if item.get(key):
                dimension[key] = True
        for key in ("offset", "text_offset"):
            pair = item.get(key)
            if isinstance(pair, (list, tuple)) and len(pair) == 2 and \
                    all(isinstance(v, (int, float)) and math.isfinite(v) for v in pair):
                dimension[key] = [float(v) for v in pair]
        tolerance = tol_normalize_tolerance(item.get("tol"))
        if tolerance:
            dimension["tol"] = tolerance
        options["dimensions"].append(dimension)
    # Phase 2: title block fields, notes, units, parts list, hole table of the sheet
    for key, limit in (("material", 120), ("treatment", 120), ("notes", 2000)):
        if key in options:
            options[key] = str(options[key] or "")[:limit]
    if options.get("unit") not in DRAWING_UNITS:
        options.pop("unit", None)
    options["dual_units"] = bool(options.get("dual_units"))
    options["parts_list"] = bool(options.get("parts_list"))
    parts = options.get("parts")
    options["parts"] = [
        {"name": str(part.get("name", ""))[:80], "qty": max(1, min(9999, int(tol_number(part.get("qty")) or 1))),
         "material": str(part.get("material", ""))[:60]}
        for part in (parts if isinstance(parts, list) else [])[:200] if isinstance(part, dict)]
    table = options.get("hole_table")
    if isinstance(table, dict) and table.get("view") in valid_names and \
            tol_number(table.get("x")) is not None and tol_number(table.get("y")) is not None:
        options["hole_table"] = {"view": table["view"], "x": float(table["x"]), "y": float(table["y"])}
    else:
        options.pop("hole_table", None)
    return options


def _validated_graphic(data):
    """An imported SVG / DXF graphic read from a project file, or None when it is unusable."""
    if not isinstance(data, dict):
        return None
    try:
        width, height = float(data["width"]), float(data["height"])
        if not (math.isfinite(width) and math.isfinite(height) and width > 0 and height > 0):
            return None
        for style, flat in data.get("polylines", []):
            if int(style) not in GRAPHIC_PENS or len(flat) % 2:
                return None
        for item in data.get("circles", []):
            if len(item) != 4:
                return None
        for item in data.get("texts", []):
            if len(item) != 5:
                return None
        for item in data.get("lines", []):
            if len(item) != 4:
                return None
    except (KeyError, TypeError, ValueError):
        return None
    data = dict(data)
    data["token"] = str(data.get("token") or os.urandom(8).hex())
    data["name"] = str(data.get("name") or "graphic")[:200]
    return data


def _validated_drawing_options(options):
    """Drawing options read from a project file: the sheets, the imported models (checked
    meshes) and graphics. Raises ValueError for broken settings."""
    if not isinstance(options, dict):
        raise ValueError("not a settings object")
    options = {key: (value if key in ("models", "graphics") else copy.deepcopy(value))
               for key, value in options.items()}
    graphics = {}
    for graphic_id, data in (options.get("graphics") or {}).items():
        checked = _validated_graphic(data)
        if checked is not None:
            graphics[str(graphic_id)] = checked
    models = {}
    for model_id, model in (options.get("models") or {}).items():
        if not isinstance(model, dict):
            continue
        vertices, triangles = _validate_mesh(model.get("vertices"), model.get("triangles"))
        models[str(model_id)] = {"name": str(model.get("name") or "Model")[:200],
                                 "path": str(model.get("path") or ""),
                                 "vertices": [list(v) for v in vertices],
                                 "triangles": [list(t) for t in triangles]}
    options = _validated_drawing_sheet(options, graphics, models)
    sheets = options.get("sheets")
    if isinstance(sheets, list) and sheets:
        options["sheets"] = [_validated_drawing_sheet(dict(sheet), graphics, models)
                             for sheet in sheets[:100] if isinstance(sheet, dict)]
        if not options["sheets"]:
            options.pop("sheets")
        active = options.get("active_sheet", 0)
        options["active_sheet"] = min(max(int(active), 0), len(options.get("sheets", [0])) - 1) \
            if isinstance(active, (int, float)) else 0
    else:
        options.pop("sheets", None)
        options.pop("active_sheet", None)
    options["graphics"] = graphics
    options["models"] = models
    return options


def write_technical_drawing_sheets(path, extension, jobs):
    """Export the sheets of a drawing, `jobs` = [(mesh or None, sheet options)]. A PDF gets one
    page per sheet; an SVG or DXF file holds one sheet, so the second one goes to "<name>-2.svg",
    and so on. Returns the written paths."""
    if not jobs:
        raise ValueError("The drawing has no sheets")
    if extension == ".pdf":
        write_technical_drawing_pdf_pages(path, jobs)
        return [path]
    stem, suffix = os.path.splitext(path)
    written = []
    for number, (mesh, options) in enumerate(jobs, 1):
        target = path if number == 1 else f"{stem}-{number}{suffix}"
        write_technical_drawing(target, extension, mesh, options)
        written.append(target)
    return written


def _drawing_page_size(sheet):
    return QPageSize(QSizeF(sheet["w"] / DRAWING_UNITS_PER_MM, sheet["h"] / DRAWING_UNITS_PER_MM),
                     QPageSize.Millimeter, f"{sheet['name']} {sheet['orientation']}",
                     QPageSize.ExactMatch)


def write_technical_drawing_pdf_pages(path, jobs):
    """PDF with one page per sheet (each in its own size and orientation), black on white."""
    writer = QPdfWriter(path)
    writer.setResolution(150)
    writer.setPageSize(_drawing_page_size(_drawing_sheet(jobs[0][1])))
    writer.setPageMargins(QMarginsF(0, 0, 0, 0))
    painter = QPainter()
    if not painter.begin(writer):
        raise RuntimeError(f"Could not create PDF drawing:\n{path}")
    try:
        for number, (mesh, options) in enumerate(jobs):
            options = dict(options, _colors=DRAWING_PRINT_COLORS)
            sheet = _drawing_sheet(options)
            if number:
                writer.setPageSize(_drawing_page_size(sheet))
                writer.setPageMargins(QMarginsF(0, 0, 0, 0))
                writer.newPage()
            # the page in sheet units, independent of the device size of each page
            options["_page_scale"] = writer.width() / sheet["w"]
            vertices, triangles = mesh if mesh is not None else (None, None)
            _draw_technical_drawing(painter, vertices, triangles, options)
    finally:
        painter.end()


class FitCalculatorDialog(QDialog):
    """ISO 286 fit calculator: hole + shaft symbol → limits, clearance / interference, fit type.
    `chosen` is the symbol the user wants to put on the dimension (hole or shaft), or None."""

    def __init__(self, parent, size=25.0):
        super().__init__(parent)
        self.setWindowTitle("Fit calculator (ISO 286)")
        self.chosen = None
        layout = QVBoxLayout(self)
        form = QFormLayout()
        self.size = QDoubleSpinBox()
        self.size.setRange(0.1, 500.0)
        self.size.setDecimals(3)
        self.size.setSuffix(" mm")
        self.size.setValue(min(500.0, max(0.1, abs(float(size)))))
        self.preferred = QComboBox()
        self.preferred.addItem("Choose a preferred fit", None)
        for hole, shaft in TOL_PREFERRED_FITS:
            self.preferred.addItem(f"{hole}/{shaft}", (hole, shaft))
        self.hole = QLineEdit("H7")
        self.shaft = QLineEdit("g6")
        self.hole.setToolTip("Hole symbol, capital letter (e.g. H7, F8, K7, JS6)")
        self.shaft.setToolTip("Shaft symbol, lower-case letter (e.g. g6, h6, k6, p6)")
        form.addRow("Nominal size:", self.size)
        form.addRow("Preferred fits:", self.preferred)
        form.addRow("Hole:", self.hole)
        form.addRow("Shaft:", self.shaft)
        layout.addLayout(form)
        self.report = QLabel()
        self.report.setTextFormat(Qt.PlainText)
        self.report.setMinimumWidth(380)
        self.report.setWordWrap(True)
        layout.addWidget(self.report)
        buttons = QHBoxLayout()
        use_hole = QPushButton("Use hole symbol")
        use_shaft = QPushButton("Use shaft symbol")
        close = QPushButton("Close")
        use_hole.clicked.connect(lambda: self._choose(self.hole.text()))
        use_shaft.clicked.connect(lambda: self._choose(self.shaft.text()))
        close.clicked.connect(self.reject)
        for button in (use_hole, use_shaft):
            button.setToolTip("Put this symbol on the selected dimension")
            buttons.addWidget(button)
        buttons.addStretch(1)
        buttons.addWidget(close)
        layout.addLayout(buttons)
        self.size.valueChanged.connect(self._update)
        self.hole.textChanged.connect(self._update)
        self.shaft.textChanged.connect(self._update)
        self.preferred.currentIndexChanged.connect(self._choose_preferred)
        self._update()
        _style_dialog_widgets(self)

    def _choose_preferred(self):
        pair = self.preferred.currentData()
        if pair:
            self.hole.setText(pair[0])
            self.shaft.setText(pair[1])

    def _choose(self, symbol):
        try:
            tol_deviations(symbol.strip(), self.size.value())
        except ToleranceError as ex:
            self.report.setText(f"⚠ {ex}")
            return
        self.chosen = symbol.strip()
        self.accept()

    def _update(self, *_):
        try:
            result = tol_analyse_fit(self.hole.text().strip(), self.shaft.text().strip(),
                                            self.size.value())
            self.report.setText("\n".join(tol_fit_report(result)))
        except ToleranceError as ex:
            self.report.setText(f"⚠ {ex}")


class BearingDialog(QDialog):
    """Bearing library (Phase 5): type, size and load case with the bearing's own tolerances
    and the recommended shaft / housing seats. `diameter` preselects a bearing whose bore or
    outside diameter it is (for a seat on a drawing)."""

    def __init__(self, parent, title="Bearing", diameter=None, button_text="Insert"):
        super().__init__(parent)
        self.setWindowTitle(title)
        self.catalogue = bearing_catalogue()
        layout = QVBoxLayout(self)
        form = QFormLayout()
        self.kind = QComboBox()
        for key, text in BEARING_TYPES.items():
            self.kind.addItem(text, key)
        self.size = QComboBox()
        self.load = QComboBox()
        for key, text in BEARING_LOAD_CASES.items():
            self.load.addItem(text, key)
        self.info = QLabel()
        self.info.setTextFormat(Qt.PlainText)
        self.info.setWordWrap(True)
        self.info.setMinimumWidth(430)
        form.addRow("Type:", self.kind)
        form.addRow("Size:", self.size)
        form.addRow("Load case:", self.load)
        layout.addLayout(form)
        layout.addWidget(self.info)
        note = QLabel("Sizes are the common catalogue values; check them against the "
                      "manufacturer's data sheet.")
        note.setWordWrap(True)
        note.setStyleSheet("color:#aab2bd;")
        layout.addWidget(note)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.button(QDialogButtonBox.Ok).setText(button_text)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)
        self.kind.currentIndexChanged.connect(self._fill_sizes)
        self.size.currentIndexChanged.connect(self._update)
        self.load.currentIndexChanged.connect(self._update)
        if diameter is not None:                      # the bearing that fits this diameter
            match = next((item for item in self.catalogue
                          if abs(item["d"] - diameter) < 0.01 or abs(item["D"] - diameter) < 0.01), None)
            if match is not None:
                self.kind.setCurrentIndex(self.kind.findData(match["type"]))
                self._fill_sizes()
                self.size.setCurrentIndex(self.size.findText(self._size_text(match)))
        self._fill_sizes(keep=True)
        _style_dialog_widgets(self)

    @staticmethod
    def _size_text(item):
        return f"{item['name']}   d {item['d']:g} × D {item['D']:g} × B {item['B']:g}"

    def _fill_sizes(self, *_, keep=False):
        current = self.size.currentText() if keep else None
        self.size.blockSignals(True)
        self.size.clear()
        for item in self.catalogue:
            if item["type"] == self.kind.currentData():
                self.size.addItem(self._size_text(item), item["name"])
        if current:
            index = self.size.findText(current)
            if index >= 0:
                self.size.setCurrentIndex(index)
        self.size.blockSignals(False)
        plain = self.kind.currentData() in ("plain", "needle")
        self.load.setEnabled(not plain)
        self._update()

    def bearing(self):
        return bearing_find(self.size.currentData()) if self.size.currentData() else None

    def seat(self):
        bearing = self.bearing()
        return bearing_seat(bearing, self.load.currentData()) if bearing else None

    def _update(self, *_):
        bearing, seat = self.bearing(), self.seat()
        if bearing is None:
            self.info.setText("")
            return
        (bore_up, bore_low), (out_up, out_low) = bearing_ring_deviations(bearing)
        dev = lambda up, low: f"{up * 1000:+.0f} / {low * 1000:+.0f} µm".replace("+0 ", "0 ").replace("+0 /", "0 /")
        lines = [f"{bearing['name']}: bore d = {bearing['d']:g} mm ({dev(bore_up, bore_low)}), "
                 f"outside D = {bearing['D']:g} mm ({dev(out_up, out_low)}), width {bearing['B']:g} mm, "
                 f"chamfer r = {bearing['r']:g} mm",
                 "",
                 f"Shaft seat:    Ø{bearing['d']:g} {seat['shaft']}   "
                 f"({dev(*tol_deviations(seat['shaft'], bearing['d']))})",
                 f"Housing seat:  Ø{bearing['D']:g} {seat['housing']}   "
                 f"({dev(*tol_deviations(seat['housing'], bearing['D']))})",
                 f"Shoulders:     shaft Ø ≥ {seat['shoulder_shaft']:g} mm, housing Ø ≤ "
                 f"{seat['shoulder_housing']:g} mm, fillet r ≤ {seat['fillet']:g} mm"]
        for side, diameter, symbol, ring in (("shaft", bearing["d"], seat["shaft"], (bore_up, bore_low)),
                                             ("housing", bearing["D"], seat["housing"], (out_up, out_low))):
            up, low = tol_deviations(symbol, diameter)
            if side == "shaft":                       # bore (hole) on the shaft
                gap_max, gap_min = ring[0] - low, ring[1] - up
            else:                                     # housing (hole) on the outer ring
                gap_max, gap_min = up - ring[1], low - ring[0]
            kind = "clearance" if gap_min >= 0 else "interference" if gap_max <= 0 else "transition"
            lines.append(f"{side.title()} fit: {kind}, clearance {gap_min * 1000:+.0f} … "
                         f"{gap_max * 1000:+.0f} µm")
        if seat["note"]:
            lines += ["", seat["note"]]
        self.info.setText("\n".join(lines))


class StackupDialog(QDialog):
    """Tolerance stack-up (Phase 5): a chain of dimensions of the sheet (or typed in) with a sign
    each; worst-case and statistical (RSS) totals of the gap and the check against its limits.
    `stackup` {"name", "rows", "min", "max", "show"} is edited and returned by result()."""

    def __init__(self, parent, dimensions, general, stackup=None):
        super().__init__(parent)
        self.setWindowTitle("Tolerance stack-up")
        self.resize(760, 520)
        self.dimensions, self.general = dimensions, general
        stackup = stackup or {"name": "Gap", "rows": [], "min": 0.0, "max": None, "show": False}
        layout = QVBoxLayout(self)
        top = QFormLayout()
        self.name = QLineEdit(stackup.get("name", "Gap"))
        top.addRow("Name of the gap:", self.name)
        layout.addLayout(top)
        self.table = QTableWidget(0, 6)
        self.table.setHorizontalHeaderLabels(["Dimension", "Nominal", "Upper", "Lower", "Sign", "From"])
        self.table.horizontalHeader().setSectionResizeMode(0, QHeaderView.Stretch)
        layout.addWidget(self.table, 1)
        buttons = QHBoxLayout()
        self.pick = QComboBox()
        self.pick.addItem("Add a dimension of the sheet", None)
        for index, dimension in enumerate(dimensions):
            if dimension.get("type", "length") in ("length", "diameter", "radius", "ordinate", "chamfer", "arc"):
                text = TechnicalDrawingDialog._dimension_list_text(dimension)
                self.pick.addItem(f"{index + 1}: {text}", index)
        self.pick.activated.connect(self._add_dimension)
        add_manual = QPushButton("Add a row")
        add_manual.clicked.connect(lambda: self._add_row({"name": "Part", "nominal": 10.0, "upper": 0.1,
                                                         "lower": -0.1, "sign": 1}))
        remove = QPushButton("Remove row")
        remove.clicked.connect(lambda: self.table.removeRow(self.table.currentRow()) or self._update())
        buttons.addWidget(self.pick, 1)
        buttons.addWidget(add_manual)
        buttons.addWidget(remove)
        layout.addLayout(buttons)
        limits = QFormLayout()
        self.low = QLineEdit("" if stackup.get("min") is None else f"{stackup['min']:g}")
        self.high = QLineEdit("" if stackup.get("max") is None else f"{stackup['max']:g}")
        for edit in (self.low, self.high):
            edit.setPlaceholderText("no limit")
            edit.editingFinished.connect(self._update)
        limits.addRow("Smallest allowed gap (mm):", self.low)
        limits.addRow("Largest allowed gap (mm):", self.high)
        self.show_table = QCheckBox("Show the stack-up as a table on the sheet")
        self.show_table.setChecked(bool(stackup.get("show")))
        limits.addRow(self.show_table)
        layout.addLayout(limits)
        self.report = QLabel()
        self.report.setTextFormat(Qt.PlainText)
        self.report.setWordWrap(True)
        layout.addWidget(self.report)
        ok = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        ok.accepted.connect(self.accept)
        ok.rejected.connect(self.reject)
        layout.addWidget(ok)
        self.table.itemChanged.connect(lambda _item: self._update())
        for row in stackup.get("rows", ()):
            self._add_row(row)
        self._update()
        _style_dialog_widgets(self)

    def _add_dimension(self, *_):
        index = self.pick.currentData()
        self.pick.setCurrentIndex(0)
        if index is None:
            return
        dimension = self.dimensions[index]
        upper, lower = tol_dimension_deviations(dimension["value"], dimension.get("tol"), self.general)
        label = str(dimension.get("label", "")).strip()
        self._add_row({"dim": index, "name": f"#{index + 1} {label}".strip(),
                       "nominal": abs(float(dimension["value"])), "upper": upper, "lower": lower,
                       "sign": 1})

    def _add_row(self, row):
        self.table.blockSignals(True)
        index = self.table.rowCount()
        self.table.insertRow(index)
        values = (row.get("name", ""), f"{float(row['nominal']):g}", f"{float(row['upper']):+g}",
                  f"{float(row['lower']):+g}", "+" if float(row.get("sign", 1)) >= 0 else "−",
                  "dimension" if row.get("dim") is not None else "typed in")
        for column, value in enumerate(values):
            item = QTableWidgetItem(value)
            if column == 5:
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)
                item.setData(Qt.UserRole, row.get("dim"))
            self.table.setItem(index, column, item)
        self.table.blockSignals(False)
        self._update()

    def rows(self):
        rows = []
        for index in range(self.table.rowCount()):
            text = lambda column: (self.table.item(index, column).text()
                                   if self.table.item(index, column) else "").replace("−", "-")
            try:
                row = {"name": text(0)[:60], "nominal": float(text(1)), "upper": float(text(2)),
                       "lower": float(text(3)), "sign": -1 if text(4).strip().startswith("-") else 1}
            except ValueError:
                continue
            dim = self.table.item(index, 5).data(Qt.UserRole) if self.table.item(index, 5) else None
            if dim is not None:
                row["dim"] = int(dim)
            rows.append(row)
        return rows

    def _limit(self, edit):
        try:
            return float(edit.text().replace(",", "."))
        except ValueError:
            return None

    def _update(self, *_):
        rows = self.rows()
        if not rows:
            self.report.setText("Add the dimensions of the chain; a minus sign subtracts a dimension.")
            return
        result = tol_stackup(rows, self._limit(self.low), self._limit(self.high))
        mark = lambda ok: "✔ within the limits" if ok else "✘ outside the limits"
        self.report.setText(
            f"Nominal gap: {result['nominal']:.3f} mm\n"
            f"Worst case: {result['worst'][0]:.3f} … {result['worst'][1]:.3f} mm   {mark(result['worst_ok'])}\n"
            f"Statistical (RSS): {result['rss'][0]:.3f} … {result['rss'][1]:.3f} mm   {mark(result['rss_ok'])}")

    def result(self):
        return {"name": self.name.text().strip()[:60] or "Gap", "rows": self.rows(),
                "min": self._limit(self.low), "max": self._limit(self.high),
                "show": self.show_table.isChecked()}


class AnnotationDialog(QDialog):
    """Parameters of a geometric tolerance frame, datum, surface finish, weld symbol, note, hole
    or thread callout or balloon. `parts` (names) label the balloon numbers."""

    def __init__(self, parent, kind, annotation=None, parts=None, item=1):
        super().__init__(parent)
        self.kind = kind
        self.setWindowTitle(TOL_ANNOTATION_TITLES[kind])
        annotation = tol_normalize_annotation(annotation) if annotation else None
        self._annotation = annotation
        self._offset = annotation["offset"] if annotation else [60.0, -40.0]
        self._parts = list(parts or [])
        form = QFormLayout()

        def length_spin(value, minimum=0.0):
            spin = QDoubleSpinBox()
            spin.setRange(minimum, 100000.0)
            spin.setDecimals(3)
            spin.setSuffix(" mm")
            spin.setValue(float(value))
            return spin

        def count_spin(value):
            spin = QSpinBox()
            spin.setRange(1, 999)
            spin.setPrefix("× ")
            spin.setValue(int(value))
            return spin
        if kind == "note":
            self.note_text = QPlainTextEdit(annotation["text"] if annotation else "")
            self.note_text.setPlaceholderText("Text of the note (several lines possible)")
            self.note_text.setMinimumSize(320, 110)
            self.note_leader = QCheckBox("Leader with an arrow to the clicked feature")
            self.note_leader.setChecked(annotation["leader"] if annotation else True)
            self.note_frame = QCheckBox("Frame around the text")
            self.note_frame.setChecked(bool(annotation and annotation["frame"]))
            form.addRow("Text:", self.note_text)
            form.addRow(self.note_leader)
            form.addRow(self.note_frame)
        elif kind == "hole":
            a = annotation or {"linked": True, "d": 6.6, "through": True, "depth": 10.0,
                               "cbore": None, "csk": None, "count": 1}
            self.linked = QCheckBox("Follow the model (values read from the hole)")
            self.linked.setChecked(a["linked"])
            self.hole_count = count_spin(a["count"])
            self.hole_d = length_spin(a["d"], 0.001)
            self.hole_through = QCheckBox("Through (THRU)")
            self.hole_through.setChecked(a["through"])
            self.hole_depth = length_spin(a["depth"])
            self.cbore = QCheckBox("Counterbore")
            self.cbore.setChecked(bool(a["cbore"]))
            self.cbore_d = length_spin((a["cbore"] or (11.0, 6.8))[0], 0.001)
            self.cbore_depth = length_spin((a["cbore"] or (11.0, 6.8))[1], 0.001)
            self.csk = QCheckBox("Countersink")
            self.csk.setChecked(bool(a["csk"]))
            self.csk_d = length_spin((a["csk"] or (12.0, 90.0))[0], 0.001)
            self.csk_angle = QDoubleSpinBox()
            self.csk_angle.setRange(10.0, 170.0)
            self.csk_angle.setSuffix("°")
            self.csk_angle.setValue(float((a["csk"] or (12.0, 90.0))[1]))
            form.addRow(self.linked)
            form.addRow("Number of holes:", self.hole_count)
            form.addRow("Diameter:", self.hole_d)
            form.addRow(self.hole_through)
            form.addRow("Depth:", self.hole_depth)
            form.addRow(self.cbore)
            form.addRow("Counterbore Ø / depth:", self._pair(self.cbore_d, self.cbore_depth))
            form.addRow(self.csk)
            form.addRow("Countersink Ø / angle:", self._pair(self.csk_d, self.csk_angle))
            self._linked_widgets = (self.hole_count, self.hole_d, self.hole_through, self.hole_depth,
                                    self.cbore, self.cbore_d, self.cbore_depth, self.csk,
                                    self.csk_d, self.csk_angle)
        elif kind == "thread":
            a = annotation or {"linked": True, "label": "M8", "label_pitch": "M8×1.25",
                               "show_pitch": False, "cls": "6H", "internal": True,
                               "length": 16.0, "through": False, "count": 1}
            self.linked = QCheckBox("Follow the model (size, length read from the thread)")
            self.linked.setChecked(a["linked"])
            self.thread_count = count_spin(a["count"])
            self.thread_label = QLineEdit(a["label"])
            self.thread_label.setToolTip("Designation without the pitch (metric coarse: M8)")
            self.thread_label_pitch = QLineEdit(a["label_pitch"])
            self.thread_label_pitch.setToolTip("Designation with the pitch (M8×1.25)")
            self.show_pitch = QCheckBox("Print the pitch (always for fine threads)")
            self.show_pitch.setChecked(a["show_pitch"])
            self.thread_cls = QComboBox()
            self.thread_cls.setEditable(True)
            self.thread_cls.addItems(["6H", "6g", "7H", "6e", "5H", "4h", "2B", "2A", ""])
            self.thread_cls.setCurrentText(a["cls"])
            self.thread_cls.setToolTip("Tolerance class: capital letter for internal threads (6H), "
                                       "lower case for external ones (6g); Unified: 2B / 2A")
            self.thread_internal = QCheckBox("Internal thread (tapped hole)")
            self.thread_internal.setChecked(a["internal"])
            self.thread_length = length_spin(a["length"])
            self.thread_through = QCheckBox("Through (THRU)")
            self.thread_through.setChecked(a["through"])
            form.addRow(self.linked)
            form.addRow("Number of threads:", self.thread_count)
            form.addRow("Designation:", self.thread_label)
            form.addRow("With pitch:", self.thread_label_pitch)
            form.addRow(self.show_pitch)
            form.addRow("Tolerance class:", self.thread_cls)
            form.addRow(self.thread_internal)
            form.addRow("Thread depth / length:", self.thread_length)
            form.addRow(self.thread_through)
            self._linked_widgets = (self.thread_count, self.thread_label, self.thread_label_pitch,
                                    self.thread_internal, self.thread_length, self.thread_through)
        elif kind == "balloon":
            self.balloon_item = QSpinBox()
            self.balloon_item.setRange(1, 999)
            self.balloon_item.setValue(annotation["item"] if annotation else int(item))
            self.balloon_part = QLabel()
            self.balloon_item.valueChanged.connect(self._update_balloon_part)
            form.addRow("Item number:", self.balloon_item)
            form.addRow("Part:", self.balloon_part)
            self._update_balloon_part()
        elif kind == "gdt":
            self.symbol = QComboBox()
            for key, (title, _datum, _diameter) in TOL_GDT_SYMBOLS.items():
                self.symbol.addItem(title, key)
            self.tolerance = QLineEdit()
            self.tolerance.setPlaceholderText("0.05")
            self.diameter = QCheckBox("Cylindrical tolerance zone (Ø)")
            self.modifier = QComboBox()
            for key, title in (("", "No modifier"), ("M", "(M) maximum material"),
                               ("L", "(L) least material"), ("P", "(P) projected zone")):
                self.modifier.addItem(title, key)
            self.datums = [QLineEdit() for _ in range(3)]
            for index, edit in enumerate(self.datums):
                edit.setMaxLength(2)
                edit.setPlaceholderText("A")
                edit.setMaximumWidth(48)
            datum_row = QHBoxLayout()
            for edit in self.datums:
                datum_row.addWidget(edit)
            datum_row.addStretch(1)
            form.addRow("Characteristic:", self.symbol)
            form.addRow("Tolerance (mm):", self.tolerance)
            form.addRow(self.diameter)
            form.addRow("Modifier:", self.modifier)
            form.addRow("Datums:", datum_row)
            if annotation:
                self.symbol.setCurrentIndex(max(0, self.symbol.findData(annotation["symbol"])))
                self.tolerance.setText(annotation["tolerance"])
                self.diameter.setChecked(annotation["diameter"])
                self.modifier.setCurrentIndex(max(0, self.modifier.findData(annotation["modifier"])))
                for edit, letter in zip(self.datums, annotation["datums"]):
                    edit.setText(letter)
        elif kind == "datum":
            self.letter = QLineEdit(annotation["letter"] if annotation else "A")
            self.letter.setMaxLength(2)
            form.addRow("Datum letter:", self.letter)
        elif kind == "surface":
            self.removal = QComboBox()
            for key, title in TOL_SURFACE_REMOVAL.items():
                self.removal.addItem(title, key)
            self.roughness = QLineEdit()
            self.roughness.setPlaceholderText("Ra 1.6")
            self.lay = QComboBox()
            for symbol in TOL_LAY_SYMBOLS:
                self.lay.addItem(symbol or "No lay symbol", symbol)
            self.allowance = QLineEdit()
            self.allowance.setPlaceholderText("Machining allowance, e.g. 0.5")
            form.addRow("Machining:", self.removal)
            form.addRow("Roughness:", self.roughness)
            form.addRow("Lay:", self.lay)
            form.addRow("Allowance:", self.allowance)
            if annotation:
                self.removal.setCurrentIndex(max(0, self.removal.findData(annotation["removal"])))
                self.roughness.setText(annotation["value"])
                self.lay.setCurrentIndex(max(0, self.lay.findData(annotation["lay"])))
                self.allowance.setText(annotation["allowance"])
        elif kind == "weld":
            self.weld_type = QComboBox()
            self.weld_other = QComboBox()
            self.weld_other.addItem("None", "")
            for key, title in TOL_WELD_TYPES.items():
                self.weld_type.addItem(title, key)
                self.weld_other.addItem(title, key)
            self.weld_size = QLineEdit()
            self.weld_size.setPlaceholderText("a4")
            self.all_around = QCheckBox("All around")
            self.field_weld = QCheckBox("Field weld")
            self.tail = QLineEdit()
            self.tail.setPlaceholderText("Process / note, e.g. 111")
            form.addRow("Arrow side:", self.weld_type)
            form.addRow("Other side:", self.weld_other)
            form.addRow("Size:", self.weld_size)
            form.addRow(self.all_around)
            form.addRow(self.field_weld)
            form.addRow("Tail:", self.tail)
            if annotation:
                self.weld_type.setCurrentIndex(max(0, self.weld_type.findData(annotation["type"])))
                self.weld_other.setCurrentIndex(max(0, self.weld_other.findData(annotation["other"])))
                self.weld_size.setText(annotation["size"])
                self.all_around.setChecked(annotation["all_around"])
                self.field_weld.setChecked(annotation["field"])
                self.tail.setText(annotation["tail"])
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout = QVBoxLayout(self)
        layout.addLayout(form)
        layout.addWidget(buttons)
        if kind in ("hole", "thread"):
            self.linked.toggled.connect(self._sync_linked)
            self._sync_linked()
        _style_dialog_widgets(self)

    @staticmethod
    def _pair(first, second):
        row = QHBoxLayout()
        row.addWidget(first)
        row.addWidget(second)
        return row

    def _sync_linked(self, *_):
        """Values that follow the model are not typed in."""
        for widget in self._linked_widgets:
            widget.setEnabled(not self.linked.isChecked())

    def _update_balloon_part(self, *_):
        index = self.balloon_item.value() - 1
        self.balloon_part.setText(self._parts[index] if 0 <= index < len(self._parts) else
                                  "(not in the parts list)")

    def annotation(self):
        data = {"kind": self.kind, "offset": list(self._offset)}
        if self.kind == "note":
            data.update(text=self.note_text.toPlainText(), leader=self.note_leader.isChecked(),
                        frame=self.note_frame.isChecked())
        elif self.kind == "hole":
            data.update(linked=self.linked.isChecked(), count=self.hole_count.value(),
                        d=self.hole_d.value(), through=self.hole_through.isChecked(),
                        depth=self.hole_depth.value(),
                        cbore=[self.cbore_d.value(), self.cbore_depth.value()] if self.cbore.isChecked() else None,
                        csk=[self.csk_d.value(), self.csk_angle.value()] if self.csk.isChecked() else None)
        elif self.kind == "thread":
            data.update(linked=self.linked.isChecked(), count=self.thread_count.value(),
                        label=self.thread_label.text(), label_pitch=self.thread_label_pitch.text(),
                        show_pitch=self.show_pitch.isChecked(), cls=self.thread_cls.currentText(),
                        internal=self.thread_internal.isChecked(), length=self.thread_length.value(),
                        through=self.thread_through.isChecked())
        elif self.kind == "balloon":
            data["item"] = self.balloon_item.value()
        elif self.kind == "gdt":
            data.update(symbol=self.symbol.currentData(), tolerance=self.tolerance.text(),
                        diameter=self.diameter.isChecked(), modifier=self.modifier.currentData(),
                        datums=[edit.text() for edit in self.datums if edit.text().strip()])
        elif self.kind == "datum":
            data["letter"] = self.letter.text()
        elif self.kind == "surface":
            data.update(removal=self.removal.currentData(), value=self.roughness.text(),
                        lay=self.lay.currentData(), allowance=self.allowance.text())
        elif self.kind == "weld":
            data.update({"type": self.weld_type.currentData(), "other": self.weld_other.currentData(),
                         "size": self.weld_size.text(), "all_around": self.all_around.isChecked(),
                         "field": self.field_weld.isChecked(), "tail": self.tail.text()})
        return tol_normalize_annotation(data)


class TechnicalDrawingDialog(QDialog):
    _workspace_state = None          # panel position / visibility, kept for the program session

    def __init__(self, parent=None, project_name="", mesh=None, options=None,
                 source_entries=None, source_entry=None, source_locked=False, mesh_for=None,
                 parts_for=None, model_info_for=None):
        super().__init__(parent)
        self._mesh_for = mesh_for or (lambda entry: entry.get("solid"))
        # gears and thread features of a sheet's model (Phase 4; the main window adds the bodies)
        self._model_info_for = model_info_for or (lambda entry: _drawing_model_info(entry, [entry]))
        # parts list of a sheet's model (the main window adds the child bodies)
        self._parts_for = parts_for or (lambda entry: [
            {"name": entry.get("name", "Part"), "qty": 1,
             "material": str(entry.get("material", DEFAULT_MATERIAL))}])
        # a window of its own like the assembly window (dark title bar: see showEvent)
        self.setWindowFlags(Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowMaximizeButtonHint |
                            Qt.WindowCloseButtonHint | Qt.WindowSystemMenuHint)
        self.setWindowIcon(QIcon(os.path.join(_LOG_DIR, "icons", "technical_drawing.png")))
        self.setWindowTitle("Technical Drawing")
        self.setMinimumSize(1120, 780)
        self.resize(1400, 900)
        # project solids a sheet can show (extrusions and imported models, chosen by name)
        self.source_entries = list(source_entries or [])
        self.current_source_entry = None
        self.mesh = None
        self.sheet_source = None             # model of the sheet being edited (None: no model)
        self._meshes = {}                    # source key → mesh
        self._geometry_caches = {}           # source key → projected geometry
        self._geometry_cache = {}
        self._options = dict(options or {})
        # STEP / STL models and SVG / DXF graphics imported into this drawing (never changed in
        # place, so copies of the drawing share them)
        self.models = dict(self._options.get("models") or {})
        self.graphics = dict(self._options.get("graphics") or {})
        # the sheets of the drawing; the one being edited lives in the widgets below
        self.sheets = self._initial_sheets(source_entry)
        self.active_sheet = min(max(int(self._options.get("active_sheet", 0) or 0), 0),
                                len(self.sheets) - 1)
        self._options.update(copy.deepcopy(self.sheets[self.active_sheet]))
        self.logo_pixmap = self._options.get("logo") or QPixmap()
        self.logo_path = self._options.get("logo_path", "")
        self.dimensions = [dict(value) for value in self._options.get("dimensions", [])]
        self.view_placements = [dict(value) for value in self._options.get("view_placements", [])]
        self._pending_dimension = None
        self._preview_timer = QTimer(self)
        self._preview_timer.setSingleShot(True)
        self._preview_timer.setInterval(40)
        self._preview_timer.timeout.connect(self._refresh_preview)

        # ── window frame like the main window and the assembly window: menu bar, flat icon
        # toolbars, dock panels and a status bar with the dark title bar ──────────────────
        icon_dir = os.path.join(_LOG_DIR, "icons")

        def action(icon, text, tip, slot=None, checkable=False, shortcut=None):
            """Action shared by the menu bar and the toolbars (as in the assembly window)."""
            act = QAction(icon if isinstance(icon, QIcon) else QIcon(os.path.join(icon_dir, icon)),
                          text, self)
            act.setToolTip(f"{text} - {tip}")
            act.setStatusTip(tip)
            act.setCheckable(checkable)
            if slot is not None:
                act.triggered.connect(lambda _checked=False: slot())
            if shortcut is not None:
                act.setShortcut(QKeySequence(shortcut))
                act.setShortcutContext(Qt.WindowShortcut)
                self.addAction(act)
            return act

        self.act_import_logo = action("import.png", "Import Logo",
                                      "Load an image for the logo field of the title block",
                                      self._load_logo)
        self.act_import_graphic = action("import_svg_dxf.png", "Import SVG / DXF",
                                         "Place an SVG or DXF drawing on the sheet (it can be "
                                         "moved, scaled and dimensioned like a view)",
                                         self._import_graphic, shortcut="Ctrl+Shift+I")
        self.act_add_sheet = action("add_sheet.png", "Add Sheet",
                                    "Add a sheet to the drawing (it can show another model)",
                                    lambda: self._add_sheet(False), shortcut="Ctrl+T")
        self.act_duplicate_sheet = action("save_as.png", "Duplicate Sheet",
                                          "Add a copy of this sheet with its views and dimensions",
                                          lambda: self._add_sheet(True))
        self.act_rename_sheet = action("edit_sheet.png", "Rename Sheet",
                                       "Rename this sheet", self._rename_sheet)
        self.act_delete_sheet = action("remove_sheet.png", "Delete Sheet",
                                       "Remove this sheet from the drawing", self._delete_sheet)
        self.act_export = action("export.png", "Export",
                                 "Export the drawing as PDF, SVG or DXF (black on a white sheet)",
                                 self._export_drawing, shortcut="Ctrl+E")
        self.act_finish = action("technical_drawing.png", "Finish Drawing",
                                 "Keep the drawing in the project and close the editor",
                                 self.accept, shortcut="Ctrl+Return")
        self.act_cancel = action("exit.png", "Cancel", "Close the editor without keeping changes",
                                 self.reject)
        self.act_delete = action("delete_selected.png", "Delete Selected",
                                 "Remove the selected dimension or view (Del)", self._delete_selected)
        self.act_undo = action("undo.png", "Undo", "Undo the last change of the drawing (Ctrl+Z)",
                               self._undo, shortcut="Ctrl+Z")
        self.act_redo = action("redo.png", "Redo",
                               "Redo the last undone change (Ctrl+Y / Ctrl+Shift+Z)", self._redo,
                               shortcut="Ctrl+Y")
        self.act_redo.setShortcuts([QKeySequence("Ctrl+Y"), QKeySequence("Ctrl+Shift+Z")])
        self.act_undo.setEnabled(False)
        self.act_redo.setEnabled(False)
        self.act_select = action("select.png", "Select", "Select or drag placed views and dimensions",
                                 lambda: self.canvas.set_mode(), checkable=True)
        self.act_cut = action("scissor.png", "Cut", "Place the section cut by clicking a projected view",
                              self._begin_cut_placement, checkable=True)
        self.view_actions = {}
        for label, name, icon in (("Top", "top", "view_top.png"),
                                  ("Bottom", "bottom", "view_bottom.png"),
                                  ("Front", "front", "view_front.png"),
                                  ("Left", "left", "view_left.png"),
                                  ("Right", "right", "view_right.png"),
                                  ("Isometric", "isometric", "view_isometric.png"),
                                  ("Section", "section", "view_section.png")):
            tip = "Place the section A-A (enable it in the Views panel under Section)" \
                if name == "section" else f"Place the {label.lower()} view on the sheet"
            self.view_actions[name] = action(icon, f"{label} View", tip,
                                             lambda view=name: self._begin_view_placement(view),
                                             checkable=True)
        self.dimension_actions = {}
        dimension_tips = {
            "chamfer": "Chamfer: pick the chamfer's straight edge ('2 × 45°' on a leader)",
            "arc": "Arc length: pick an arc (concentric dimension with ⌒)",
            "baseline": "Baseline dimensions: click the base point, then every point measured "
                        "from it (horizontal or vertical as the first two lie; right-click ends)",
            "chain": "Chain dimensions: click point after point on one line (horizontal or "
                     "vertical as the first two lie; right-click ends)",
            "ordinate": "Ordinate dimensions: click the origin (0), then the points; each gets its "
                        "X and Y coordinate (right-click ends)"}
        for label, kind, icon in (("Length", "length", "length.png"),
                                  ("Radius", "radius", "radius.png"),
                                  ("Diameter", "diameter", "diameter.png"),
                                  ("Angle", "angle", "angle.png"),
                                  ("Chamfer", "chamfer", "chamfer.png"),
                                  ("Arc Length", "arc", "arc.png"),
                                  ("Baseline", "baseline", "multiple.png"),
                                  ("Chain", "chain", "point_to_point.png"),
                                  ("Ordinate", "ordinate", "origin.png")):
            self.dimension_actions[kind] = action(
                icon, label, dimension_tips.get(kind, f"Place a {label.lower()} dimension on a view"),
                lambda value=kind: self._add_dimension(value), checkable=True)
        self.act_fit = action("show_all_objects.png", "Fit Sheet", "Show the whole sheet (Home)",
                              lambda: self.canvas.fit_sheet())
        self.act_panels = action("objects.png", "Panels",
                                 "Show / hide the Views, Dimensions and Sheet panels",
                                 self._toggle_panels, checkable=True)

        # grid and snap, as in the sketcher toolbar (sheet millimetres)
        self.sp_grid = QDoubleSpinBox()
        self.sp_grid.setRange(1, 100)
        self.sp_grid.setSuffix(" mm")
        self.sp_grid.setToolTip("Grid spacing on the sheet (mm)")
        self.sp_grid.setMinimumWidth(112)
        self.sp_grid.setValue(min(100.0, max(1.0, float(self._options.get("grid_mm", DEFAULT_GRID)))))
        self.sp_snap = QDoubleSpinBox()
        self.sp_snap.setRange(0.1, 50)
        self.sp_snap.setSuffix(" mm")
        self.sp_snap.setToolTip("Snap step on the sheet (mm)")
        self.sp_snap.setMinimumWidth(112)
        self.sp_snap.setValue(min(50.0, max(0.1, float(self._options.get("snap_mm", DEFAULT_SNAP)))))
        self._snap_icon = QIcon(os.path.join(icon_dir, "snap_to_grid.png"))
        self.act_snap = action(self._snap_icon, "Snap to Grid",
                               "Snap placing and dragging views and dimensions to the grid",
                               checkable=True)
        self.act_snap.setChecked(bool(self._options.get("snap", True)))
        self._update_snap_icon(self.act_snap.isChecked())
        grid_icon = QLabel()
        grid_icon.setPixmap(QIcon(os.path.join(icon_dir, "grid.png")).pixmap(QSize(32, 32)))
        grid_icon.setToolTip("Grid")

        self.rotation = []
        for axis, value in zip("XYZ", self._options.get("rotation", (0, 0, 0))):
            spin = QSpinBox()
            spin.setRange(0, 270)
            spin.setSingleStep(90)
            spin.setSuffix(f"° {axis}")
            spin.setValue(int(value) % 360)
            spin.setToolTip(f"Rotate the model around {axis} in 90 degree steps")
            spin.valueChanged.connect(self._refresh_preview)
            self.rotation.append(spin)

        self.view_scale = QComboBox()
        self.view_scale.addItem("Auto", None)
        for ratio in DRAWING_SELECTABLE_SCALES:
            self.view_scale.addItem(_drawing_scale_text(ratio * DRAWING_UNITS_PER_MM), ratio)
        stored_ratio = self._options.get("scale_ratio")
        if stored_ratio:
            index = min(range(1, self.view_scale.count()),
                        key=lambda i: abs(math.log(self.view_scale.itemData(i) / float(stored_ratio))))
            self.view_scale.setCurrentIndex(index)
        self.view_scale.setToolTip("Scale of all placed views: the preferred scales of DIN ISO 5455 "
                                   "and every whole step from 10:1 to 1:10 (Auto: ISO 5455)")
        self.view_scale.currentIndexChanged.connect(self._refresh_preview)

        # the model whose views the sheet shows: a solid of the project (an extrusion or a STEP /
        # STL part imported in the 3-D construction) or none; each sheet has its own
        self.model_combo = QComboBox()
        self.model_combo.setMinimumWidth(160)
        self.model_combo.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
        self.model_combo.setToolTip("Model whose views are placed on this sheet: an extrusion or "
                                    "a part imported in the 3-D construction (File → Import)")
        self.model_combo.activated.connect(self._on_model_chosen)
        model_row = QHBoxLayout()
        model_row.setSpacing(4)
        model_row.addWidget(self.model_combo, 1)
        # scale of a selected imported SVG / DXF graphic
        self.graphic_scale = QComboBox()
        self.graphic_scale.addItem("Sheet scale", None)
        for ratio in DRAWING_SELECTABLE_SCALES:
            self.graphic_scale.addItem(_drawing_scale_text(ratio * DRAWING_UNITS_PER_MM), ratio)
        self.graphic_scale.setToolTip("Scale of the selected imported SVG / DXF graphic (Sheet "
                                      "scale: the scale of the sheet)")
        self.graphic_scale.setEnabled(False)
        self.graphic_scale.currentIndexChanged.connect(self._on_graphic_scale_changed)

        form = QFormLayout()
        self.front_view = QComboBox()
        for label, vector in (
                ("From +Y (front)", (0, 1, 0)), ("From -Y", (0, -1, 0)),
                ("From +X", (1, 0, 0)), ("From -X", (-1, 0, 0)),
                ("From +Z (top)", (0, 0, 1)), ("From -Z (bottom)", (0, 0, -1))):
            self.front_view.addItem(label, vector)
        # cut sections A-A, B-B, …: listed in the Views panel; each can be placed as a view
        self.sections = [dict(item) for item in _drawing_sections(self._options)]
        # Phase 3: detail and auxiliary views of this sheet
        self.details = [dict(item) for item in self._options.get("details") or []]
        self.stackups = [copy.deepcopy(item) for item in self._options.get("stackups") or []]
        self.aux_views = [dict(item) for item in self._options.get("aux_views") or []]
        if self.sections:          # older drawings: the placed "section" view is section A-A
            for record in self.view_placements:
                if record.get("name") == "section":
                    record["name"] = f"section-{self.sections[0]['letter']}"
        self.section_list = QListWidget()
        self.section_list.setMaximumHeight(120)
        self.section_list.setToolTip("Cut sections of the part. Drag a cutting line on the sheet "
                                     "to move it; right-click it to rotate it by 90° or delete it.")
        self.section_list.currentRowChanged.connect(self._on_section_row)
        QShortcut(QKeySequence.Delete, self.section_list, self._remove_section,
                  context=Qt.WidgetShortcut)
        self.section_plane = QComboBox()
        for plane, text in enumerate(DRAWING_SECTION_PLANE_TEXT):
            self.section_plane.addItem(text[0].upper() + text[1:], plane)
        self.section_plane.setToolTip("Plane of the selected cut")
        self.cut_offset = QDoubleSpinBox()
        self.cut_offset.setRange(-100000, 100000)
        self.cut_offset.setDecimals(2)
        self.cut_offset.setSuffix(" mm")
        self.cut_offset.setMinimumWidth(110)
        self.cut_offset.setToolTip("Distance of the selected cut from the centre of the part")
        self.section_plane.currentIndexChanged.connect(self._on_section_edited)
        self.cut_offset.valueChanged.connect(self._on_section_edited)
        # Phase 3: kind of section and its parameters
        self.section_kind = QComboBox()
        for kind in DRAWING_SECTION_KINDS:
            self.section_kind.addItem(DRAWING_SECTION_KIND_TEXT[kind], kind)
        self.section_kind.setToolTip(
            "Full: the whole part cut · Half: one half cut, a centre line between · Offset: a "
            "stepped cut through two parallel planes · Aligned: a second leg at an angle turned "
            "into the plane (flanges, wheels) · Removed: only the cut face, placed beside · "
            "Revolved: the cut face turned 90° on the views (ribs, spokes)")
        self.section_axis = QComboBox()
        self.section_axis.addItem("Horizontal in the section view", "u")
        self.section_axis.addItem("Vertical in the section view", "v")
        self.section_axis.setToolTip("Direction along which the half / step / bend lies")

        def spin(suffix, low, high, tip):
            box = QDoubleSpinBox()
            box.setRange(low, high)
            box.setDecimals(2)
            box.setSuffix(suffix)
            box.setToolTip(tip)
            box.valueChanged.connect(self._on_section_edited)
            return box
        self.section_split = spin(" mm", -100000, 100000, "Half: position of the centre line · "
                                  "Offset: where the cut steps · Aligned: position of the axis "
                                  "(from the centre of the part)")
        self.section_offset2 = spin(" mm", -100000, 100000, "Offset section: the plane after the step")
        self.section_angle = spin("°", -179, 179, "Aligned section: angle of the second leg")
        self.section_side = QComboBox()
        self.section_side.addItem("Cut the positive side", 1)
        self.section_side.addItem("Cut the negative side", -1)
        for widget in (self.section_kind, self.section_axis, self.section_side):
            widget.currentIndexChanged.connect(self._on_section_edited)
        section_button_list = []
        for text, icon, tip, slot in (
                ("Add", "view_section.png", "Add a cut section through the middle of the part",
                 self._add_section),
                ("Rotate 90°", "view_section.png",
                 "Rotate the selected cut by 90° (front → right side → top plane)",
                 self._rotate_section),
                ("Remove", "delete_selected.png", "Remove the selected cut and its section view",
                 self._remove_section)):
            button = QPushButton(text)
            button.setIcon(QIcon(os.path.join(icon_dir, icon)))
            button.setToolTip(tip)
            button.clicked.connect(slot)
            section_button_list.append(button)
            if text == "Rotate 90°":
                self.btn_rotate_section = button
            elif text == "Remove":
                self.btn_remove_section = button
        section_buttons = _right_aligned_buttons(section_button_list, columns=3)
        self.project = QLineEdit(project_name)
        self.project.setText(self._options.get("project", project_name))
        self.author = QLineEdit()
        self.author.setText(self._options.get("author", ""))
        self.date = QLineEdit(datetime.date.today().isoformat())
        self.date.setText(self._options.get("date", self.date.text()))
        self.version = QLineEdit()
        self.version.setText(self._options.get("version", ""))
        self.page = QLineEdit(f"{self.active_sheet + 1} / {len(self.sheets)}")
        self.page.setReadOnly(True)          # the sheets are numbered automatically
        self.page.setToolTip("Sheet number of this sheet / number of sheets (set automatically)")
        self.title = QLineEdit(self._options.get("title", ""))
        self.number = QLineEdit(self._options.get("number", ""))
        self.tolerance = QLineEdit(self._options.get("tolerance", "ISO 2768-mK"))
        self.tolerance.setToolTip(
            "General tolerances (DIN ISO 2768): f / m / c / v for linear sizes, H / K / L for form "
            "and position, e.g. ISO 2768-mK")
        completer = QCompleter(TOL_GENERAL_PRESETS, self.tolerance)
        completer.setCaseSensitivity(Qt.CaseInsensitive)
        completer.setCompletionMode(QCompleter.UnfilteredPopupCompletion)
        self.tolerance.setCompleter(completer)
        self.surface = QLineEdit(self._options.get("surface", ""))
        self.surface.setToolTip("General surface finish note of the title block, e.g. Ra 3.2")
        # per sheet (Phase 2): material and treatment of the part, units, notes, tables
        self.material = QLineEdit(self._options.get("material", ""))
        self.material.setToolTip("Material of the part in the title block, e.g. EN AW-6082 T6")
        material_completer = QCompleter(sorted(MATERIAL_DENSITIES_G_CM3), self.material)
        material_completer.setCaseSensitivity(Qt.CaseInsensitive)
        self.material.setCompleter(material_completer)
        self.material_from_model = QToolButton()
        self.material_from_model.setText("↺")
        self.material_from_model.setToolTip("Take the material of the sheet's model")
        self.material_from_model.clicked.connect(self._material_from_model)
        self.material_row = QHBoxLayout()
        self.material_row.setContentsMargins(0, 0, 0, 0)
        self.material_row.addWidget(self.material, 1)
        self.material_row.addWidget(self.material_from_model)
        self.treatment = QLineEdit(self._options.get("treatment", ""))
        self.treatment.setToolTip("Surface treatment / coating, e.g. anodised black, zinc plated")
        self.unit = QComboBox()
        self.unit.addItem("Millimetres (mm)", "mm")
        self.unit.addItem("Inches (in)", "inch")
        self.unit.setCurrentIndex(max(0, self.unit.findData(self._options.get("unit", "mm"))))
        self.unit.setToolTip("Unit of the printed lengths on this sheet (the model is in mm)")
        self.dual_units = QCheckBox("Second unit in brackets")
        self.dual_units.setChecked(bool(self._options.get("dual_units")))
        self.dual_units.setToolTip("Dual dimensioning: every length also in the other unit, "
                                   "e.g. 25 [0.984]")
        self.notes = QPlainTextEdit(str(self._options.get("notes", "") or ""))
        self.notes.setPlaceholderText("General notes, printed above the title block\n"
                                      "e.g. 1. Deburr all edges")
        self.notes.setMaximumHeight(110)
        self.parts_list = QCheckBox("Parts list above the title block")
        self.parts_list.setChecked(bool(self._options.get("parts_list")))
        self.parts_list.setToolTip("Item, name, quantity and material of the sheet's model and its "
                                   "bodies (alike bodies counted together); balloons use its numbers")
        self.hole_table_button = QPushButton("Hole table of the selected view")
        self.hole_table_button.setToolTip("Select a view in the Views panel, then click where the "
                                          "table should sit: every hole of the view gets an ID and "
                                          "its X / Y position and size are listed")
        self.hole_table_button.clicked.connect(self._begin_hole_table)
        self.hole_table_remove = QPushButton("Remove hole table")
        self.hole_table_remove.clicked.connect(self._remove_hole_table)
        self.hole_table = copy.deepcopy(self._options.get("hole_table")) \
            if isinstance(self._options.get("hole_table"), dict) else None
        # gears (Phase 4): data table, quality class, simplified teeth
        self.gear_table = copy.deepcopy(self._options.get("gear_table")) \
            if isinstance(self._options.get("gear_table"), dict) else None
        self.gear_quality = QComboBox()
        for quality in DRAWING_GEAR_QUALITIES:
            self.gear_quality.addItem(quality, quality)
        self.gear_quality.setCurrentIndex(max(0, self.gear_quality.findData(
            str(self._options.get("gear_quality", "8")))))
        self.gear_quality.setToolTip("Accuracy grade of the gear (ISO 1328-1 / DIN 3961), printed "
                                     "in the gear data table")
        self.gear_simplified = QCheckBox("Simplified gear teeth (ISO 2203)")
        self.gear_simplified.setChecked(bool(self._options.get("gear_simplified", True)))
        self.gear_simplified.setToolTip("Gears made with the Gear tool: tip circle thick, pitch "
                                        "circle chain line, root circle thin instead of every tooth")
        self.gear_table_button = QPushButton("Gear data table")
        self.gear_table_button.setToolTip("Click where the table of the gear's data (module, "
                                          "teeth, diameters, mate, centre distance) should sit")
        self.gear_table_button.clicked.connect(lambda: self._begin_table_placement("gear"))
        self.gear_table_remove = QPushButton("Remove gear table")
        self.gear_table_remove.clicked.connect(self._remove_gear_table)
        self.hatch = QComboBox()
        self.hatch.addItem("Automatic (from the material)", "auto")
        for key, (title, _lines, _period) in DRAWING_HATCHES.items():
            self.hatch.addItem(title, key)
        self.hatch.setCurrentIndex(max(0, self.hatch.findData(self._options.get("hatch", "auto"))))
        self.hatch.setToolTip("Hatching of cut faces; touching parts are hatched in opposite "
                              "directions")
        self.tolerance_presets = QToolButton()
        self.tolerance_presets.setText("▾")
        self.tolerance_presets.setToolTip("Choose a general tolerance class")
        self.tolerance_presets.setPopupMode(QToolButton.InstantPopup)
        presets_menu = QMenu(self.tolerance_presets)
        for preset in TOL_GENERAL_PRESETS:
            class_letter = preset[len("ISO 2768-"):][:1]
            form_letter = preset[len("ISO 2768-"):][1:]
            hint = TOL_GENERAL_CLASSES.get(class_letter, "")
            if form_letter:
                hint += f", form {TOL_GENERAL_FORM_CLASSES.get(form_letter, '')}"
            presets_menu.addAction(f"{preset}   ({hint})",
                                   lambda checked=False, text=preset: self._set_general_tolerance(text))
        self.tolerance_presets.setMenu(presets_menu)
        self.tolerance_row = QHBoxLayout()
        self.tolerance_row.setContentsMargins(0, 0, 0, 0)
        self.tolerance_row.addWidget(self.tolerance, 1)
        self.tolerance_row.addWidget(self.tolerance_presets)
        self.projection = QComboBox()
        self.projection.addItem("First angle (DIN ISO 128-30, method 1)", "first")
        self.projection.addItem("Third angle (method 3)", "third")
        stored_projection = self._options.get(
            "projection", "third" if self._options.get("view_placements") else "first")
        self.projection.setCurrentIndex(max(0, self.projection.findData(stored_projection)))

        form.addRow("Front orientation:", self.front_view)
        rotation_row = QHBoxLayout()
        rotation_row.setSpacing(2)
        for spin in self.rotation:
            rotation_row.addWidget(spin)
        form.addRow("Model rotation:", rotation_row)
        section_form = QFormLayout()
        section_form.addRow("Cut plane:", self.section_plane)
        section_form.addRow("Cut offset:", self.cut_offset)
        section_form.addRow("Kind:", self.section_kind)
        section_form.addRow("Split along:", self.section_axis)
        section_form.addRow("Split / step at:", self.section_split)
        section_form.addRow("Offset after step:", self.section_offset2)
        section_form.addRow("Leg angle:", self.section_angle)
        section_form.addRow("Half to cut:", self.section_side)
        self.section_form = section_form
        # views made from other views (Phase 3)
        derived_button_list = []
        for text, tip, slot in (
                ("Detail view", "Click the centre of the detail on a view, then a point of its "
                 "circle; place the enlarged view on the sheet", lambda: self._begin_view_pick("detail")),
                ("Auxiliary view", "Click an inclined straight edge on a main view: the new view "
                 "looks square onto that face (its true shape)", lambda: self._begin_view_pick("aux")),
                ("Break view", "Click two points on a view: the part between them is left out "
                 "(long parts; dimensions keep the real length)", lambda: self._begin_view_pick("break")),
                ("Broken-out section", "Click two corners of a rectangle on a main view: inside it "
                 "the material in front of the chosen depth is cut away",
                 lambda: self._begin_view_pick("broken_out")),
                ("Clear breaks / broken-out", "Remove the breaks and the broken-out section of the "
                 "selected view", self._clear_view_cuts)):
            button = QPushButton(text)
            button.setToolTip(tip)
            button.clicked.connect(slot)
            derived_button_list.append(button)
        self.derived_buttons = _right_aligned_buttons(derived_button_list, columns=2)

        logo_row = QHBoxLayout()
        self.logo_field = QLineEdit()
        self.logo_field.setReadOnly(True)
        self.logo_field.setPlaceholderText("No logo selected")
        if self.logo_path:
            self.logo_field.setText(os.path.basename(self.logo_path))
        logo_button = QPushButton("Load logo")
        logo_button.setIcon(QIcon(os.path.join(icon_dir, "import.png")))
        logo_button.clicked.connect(self._load_logo)
        logo_row.addWidget(self.logo_field, 1)
        logo_row.addWidget(logo_button)
        self.logo_row = logo_row

        # sheet format (ISO 216), orientation and scale: in the Sheet panel
        sheet = _drawing_sheet(self._options)
        self.sheet_size = QComboBox()
        for name, (width, height, _zones) in DRAWING_SHEETS.items():
            self.sheet_size.addItem(f"{name}  ({width} × {height} mm)", name)
        self.sheet_size.setCurrentIndex(max(0, self.sheet_size.findData(sheet["name"])))
        self.sheet_size.setToolTip("Sheet size (ISO 216) with frame, grid and title block "
                                   "of DIN EN ISO 5457")
        self.sheet_orientation = QComboBox()
        self.sheet_orientation.addItem("Landscape (horizontal)", "landscape")
        self.sheet_orientation.addItem("Portrait (vertical)", "portrait")
        self.sheet_orientation.setCurrentIndex(
            max(0, self.sheet_orientation.findData(sheet["orientation"])))
        self.sheet_orientation.setToolTip("Horizontal (landscape) or vertical (portrait) sheet")
        self.sheet_size.currentIndexChanged.connect(self._on_sheet_changed)
        self.sheet_orientation.currentIndexChanged.connect(self._on_sheet_changed)
        format_form = QFormLayout()
        format_form.addRow("Sheet:", self.sheet_size)
        format_form.addRow("Orientation:", self.sheet_orientation)
        format_form.addRow("Scale:", self.view_scale)

        sheet_form = QFormLayout()
        sheet_form.addRow("Title:", self.title)
        sheet_form.addRow("Drawing no.:", self.number)
        sheet_form.addRow("Project:", self.project)
        sheet_form.addRow("Author:", self.author)
        sheet_form.addRow("Date:", self.date)
        sheet_form.addRow("Version:", self.version)
        sheet_form.addRow("Page:", self.page)
        sheet_form.addRow("General tolerances:", self.tolerance_row)
        sheet_form.addRow("Surface finish:", self.surface)
        sheet_form.addRow("Material:", self.material_row)
        sheet_form.addRow("Surface treatment:", self.treatment)
        sheet_form.addRow("Projection:", self.projection)

        view_page = QWidget()
        view_layout = QVBoxLayout(view_page)
        view_layout.setContentsMargins(6, 6, 6, 6)
        view_layout.addWidget(QLabel("<b>Model of this sheet</b>"))
        view_layout.addLayout(model_row)
        # an assembly as the sheet's model (Phase 5): exploded view with trace lines
        explode_row = QHBoxLayout()
        self.explode_check = QCheckBox("Exploded view")
        self.explode_check.setToolTip("Assembly sheets: the aligned parts moved apart along their "
                                      "alignment, with chain lines from where they sit")
        self.explode_distance = QDoubleSpinBox()
        self.explode_distance.setRange(1.0, 1000.0)
        self.explode_distance.setValue(20.0)
        self.explode_distance.setSuffix(" mm")
        self.explode_check.toggled.connect(self._on_explode_changed)
        # the arrows redraw after a short pause (an assembly sheet takes a moment to project)
        self._explode_timer = QTimer(self)
        self._explode_timer.setSingleShot(True)
        self._explode_timer.setInterval(400)
        self._explode_timer.timeout.connect(self._on_explode_changed)
        self.explode_distance.valueChanged.connect(lambda *_: self._explode_timer.start())
        explode_row.addWidget(self.explode_check)
        explode_row.addWidget(self.explode_distance, 1)
        view_layout.addLayout(explode_row)
        self._sync_explode_controls()
        view_layout.addWidget(QLabel("<b>Placed views</b>"))
        self.view_list = QListWidget()
        self.view_list.currentRowChanged.connect(self._select_view_row)
        view_layout.addWidget(self.view_list, 1)
        self.hidden_lines = QCheckBox("Show hidden lines")
        self.hidden_lines.setToolTip(
            "Dashed hidden edges of the selected view (DIN ISO 128). Untick to leave them out, "
            "also in the export.")
        self.hidden_lines.setChecked(True)
        self.hidden_lines.setEnabled(False)
        _style_checkbox_like_explorer(self.hidden_lines)       # as the object explorer
        self.hidden_lines.toggled.connect(self._on_hidden_lines_toggled)
        view_layout.addWidget(self.hidden_lines)
        graphic_row = QHBoxLayout()
        graphic_row.addWidget(QLabel("Imported graphic scale:"))
        graphic_row.addWidget(self.graphic_scale, 1)
        view_layout.addLayout(graphic_row)
        remove_view = QPushButton("Remove Selected View")
        remove_view.setIcon(QIcon(os.path.join(icon_dir, "delete_selected.png")))
        remove_view.clicked.connect(self._remove_selected_view)
        view_layout.addLayout(_right_aligned_buttons([remove_view]))
        QShortcut(QKeySequence.Delete, self.view_list, self._remove_selected_view,
                  context=Qt.WidgetShortcut)
        view_layout.addWidget(QLabel("<b>Orientation</b>"))
        view_layout.addLayout(form)
        view_layout.addWidget(QLabel("<b>Sections</b>"))
        view_layout.addWidget(self.section_list)
        view_layout.addLayout(section_buttons)
        view_layout.addLayout(section_form)
        view_layout.addWidget(QLabel("<b>Details, auxiliary views, breaks</b>"))
        view_layout.addLayout(self.derived_buttons)

        dimensions_page = QWidget()
        dimension_layout = QVBoxLayout(dimensions_page)
        dimension_layout.setContentsMargins(6, 6, 6, 6)
        dimension_row = QHBoxLayout()
        self.dimension_label = QLineEdit()
        self.dimension_label.setPlaceholderText("Optional label")
        self.dimension_value = QDoubleSpinBox()
        self.dimension_value.setRange(0.0, 1000000)
        self.dimension_value.setDecimals(2)
        self.dimension_value.setSuffix(" mm")
        self.dimension_value.setReadOnly(True)
        self.dimension_value.setMinimumWidth(100)
        self.dimension_value.setToolTip("Measured value of the selected drawing geometry")
        dimension_row.addWidget(self.dimension_label, 1)
        dimension_row.addWidget(self.dimension_value)
        dimension_layout.addLayout(dimension_row)
        self.dimension_list = ToggleListWidget()
        self.dimension_list.setToolTip("Select a dimension to highlight it on the sheet; "
                                       "Delete removes it.")
        self.dimension_list.currentRowChanged.connect(self._on_dimension_row)
        dimension_layout.addWidget(self.dimension_list, 1)
        dimension_layout.addWidget(self._build_tolerance_editor())
        remove_dimension = QPushButton("Remove selected measurement")
        remove_dimension.setIcon(QIcon(os.path.join(icon_dir, "delete_selected.png")))
        remove_dimension.clicked.connect(self._remove_dimension)
        dimension_layout.addLayout(_right_aligned_buttons([remove_dimension]))
        QShortcut(QKeySequence.Delete, self.dimension_list, self._remove_dimension,
                  context=Qt.WidgetShortcut)

        sheet_page = QWidget()
        sheet_layout = QVBoxLayout(sheet_page)
        sheet_layout.setContentsMargins(6, 6, 6, 6)
        sheet_layout.addWidget(QLabel("<b>Format</b>"))
        sheet_layout.addLayout(format_form)
        sheet_layout.addWidget(QLabel("<b>Title block</b>"))
        sheet_layout.addLayout(sheet_form)
        sheet_layout.addWidget(QLabel("<b>Logo</b>"))
        sheet_layout.addLayout(logo_row)
        sheet_layout.addWidget(QLabel("<b>Section hatching</b>"))
        sheet_layout.addWidget(self.hatch)
        sheet_layout.addWidget(QLabel("<b>Units</b>"))
        unit_form = QFormLayout()
        unit_form.addRow("Lengths in:", self.unit)
        unit_form.addRow(self.dual_units)
        sheet_layout.addLayout(unit_form)
        sheet_layout.addWidget(QLabel("<b>Notes</b>"))
        sheet_layout.addWidget(self.notes)
        sheet_layout.addWidget(QLabel("<b>Tables</b>"))
        sheet_layout.addWidget(self.parts_list)
        sheet_layout.addLayout(_right_aligned_buttons([self.hole_table_button,
                                                       self.hole_table_remove]))
        sheet_layout.addWidget(QLabel("<b>Gears</b>"))
        sheet_layout.addWidget(self.gear_simplified)
        gear_form = QFormLayout()
        gear_form.addRow("Quality:", self.gear_quality)
        sheet_layout.addLayout(gear_form)
        sheet_layout.addLayout(_right_aligned_buttons([self.gear_table_button,
                                                       self.gear_table_remove]))
        sheet_layout.addStretch(1)

        self.canvas = TechnicalDrawingCanvas()
        self.canvas.sheetEdited.connect(self._queue_refresh_preview)
        self.canvas.viewSelected.connect(self._on_view_selected)
        self.canvas.dimensionPlaced.connect(self._on_dimension_placed)
        self.canvas.annotationPlaced.connect(self._on_annotation_placed)
        self.dimension_list.itemDoubleClicked.connect(self._edit_dimension_item)
        self.canvas.cutPlaced.connect(self._on_cut_placed)
        self.canvas.cutMoved.connect(self._on_cut_moved)
        self.canvas.statusChanged.connect(self._on_canvas_status)
        self.canvas.dimensionSelected.connect(self._on_canvas_dimension_selected)
        self.canvas.dimensionRemoveRequested.connect(self._remove_dimension_at)
        self.canvas.selectionRemoveRequested.connect(self._remove_canvas_selection)
        self.canvas.set_grid(self.sp_grid.value(), self.sp_snap.value(), self.act_snap.isChecked())
        self.sp_grid.valueChanged.connect(lambda value: self.canvas.set_grid(grid_mm=value))
        self.sp_snap.valueChanged.connect(lambda value: self.canvas.set_grid(snap_mm=value))
        self.act_snap.toggled.connect(self._on_snap_toggled)

        workspace = self._workspace = QMainWindow()
        workspace.setWindowFlags(Qt.Widget)
        workspace.setDockOptions(QMainWindow.AnimatedDocks | QMainWindow.AllowTabbedDocks)
        workspace.setTabPosition(Qt.AllDockWidgetAreas, QTabWidget.North)
        # the sheet in the middle, the tabs of all sheets below it (drag a tab to reorder, double-
        # click to rename, right-click for more; + adds a sheet)
        self.sheet_tabs = QTabBar()
        self.sheet_tabs.setObjectName("drawing_sheet_tabs")
        self.sheet_tabs.setMovable(True)
        self.sheet_tabs.setExpanding(False)
        self.sheet_tabs.setDrawBase(False)
        self.sheet_tabs.setShape(QTabBar.RoundedSouth)
        self.sheet_tabs.setUsesScrollButtons(True)
        self.sheet_tabs.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Fixed)
        self.sheet_tabs.setContextMenuPolicy(Qt.CustomContextMenu)
        self.sheet_tabs.setStyleSheet(
            "QTabBar::tab{background:#2a2e35;color:#c8ccd2;padding:4px 16px;margin-right:2px;"
            "border:1px solid #3a3f47;border-top:0;border-bottom-left-radius:3px;"
            "border-bottom-right-radius:3px;}"
            "QTabBar::tab:selected{background:#315f94;color:#ffffff;border-color:#548ac2;}"
            "QTabBar::tab:hover:!selected{background:#353a43;}")
        self.sheet_tabs.currentChanged.connect(self._on_sheet_tab_changed)
        self.sheet_tabs.tabMoved.connect(self._on_sheet_tab_moved)
        self.sheet_tabs.tabBarDoubleClicked.connect(lambda _index: self._rename_sheet())
        self.sheet_tabs.customContextMenuRequested.connect(self._sheet_tab_menu)
        add_sheet = QToolButton()
        add_sheet.setDefaultAction(self.act_add_sheet)
        add_sheet.setAutoRaise(True)
        add_sheet.setIconSize(QSize(18, 18))
        tab_strip = QWidget()
        tab_strip.setObjectName("drawing_tab_strip")
        tab_strip.setStyleSheet("QWidget#drawing_tab_strip{background:#202329;}")
        tab_row = QHBoxLayout(tab_strip)
        tab_row.setContentsMargins(16, 0, 8, 2)
        tab_row.setSpacing(4)
        tab_row.addWidget(self.sheet_tabs)
        tab_row.addWidget(add_sheet)
        tab_row.addStretch(1)
        centre = QWidget()
        centre_layout = QVBoxLayout(centre)
        centre_layout.setContentsMargins(0, 0, 0, 0)
        centre_layout.setSpacing(0)
        centre_layout.addWidget(self.canvas, 1)
        centre_layout.addWidget(tab_strip)
        workspace.setCentralWidget(centre)

        # toolbars: file / edit / view actions in the first row, drawing tools in the second,
        # styled and spaced as the main window's first toolbar (both rows alike, so the buttons
        # line up), with the main window's gap strips between the rows and above the sheet.
        # Both can be moved (top / bottom edge or floating); their place is saved in .settings.
        def toolbar(title, name):
            bar = QToolBar(title, workspace)
            bar.setObjectName(name)
            bar.setMovable(True)
            bar.setFloatable(True)
            bar.setAllowedAreas(Qt.TopToolBarArea | Qt.BottomToolBarArea)
            bar.setContentsMargins(0, 0, 0, 0)
            bar.setIconSize(QSize(32, 32))
            bar.setToolButtonStyle(Qt.ToolButtonIconOnly)
            bar.setStyleSheet(f"QToolBar#{name}{{margin:0;padding:2px 4px;border:0;spacing:4px;}}"
                              "QToolButton:checked{background:#315f94;border:1px solid #548ac2;"
                              "border-radius:3px;}")
            bar.layout().setContentsMargins(4, 4, 4, 4)
            workspace.addToolBar(Qt.TopToolBarArea, bar)
            return bar

        def toolbar_gap(name, height):
            gap = QToolBar(workspace)
            gap.setObjectName(name)
            gap.setMovable(False)
            gap.setFloatable(False)
            gap.setFixedHeight(height)
            gap.toggleViewAction().setVisible(False)
            gap.setStyleSheet(f"QToolBar#{name}{{background:#202329;border:0;padding:0;}}")
            workspace.addToolBarBreak(Qt.TopToolBarArea)
            workspace.addToolBar(Qt.TopToolBarArea, gap)
            workspace.addToolBarBreak(Qt.TopToolBarArea)

        self.tb_file = toolbar("File", "tb_drawing_file")
        for act in (self.act_import_graphic, self.act_export, None, self.act_add_sheet,
                    self.act_rename_sheet, self.act_delete_sheet, None, self.act_delete, None,
                    self.act_fit, self.act_panels, None):
            self.tb_file.addSeparator() if act is None else self.tb_file.addAction(act)
        self.tb_file.addAction(self.act_undo)          # as in the main window's first toolbar
        self.tb_file.addAction(self.act_redo)
        toolbar_gap("tb_drawing_toolbar_gap", 10)
        self.tb_tools = toolbar("Drawing Tools", "tb_drawing_tools")
        basic = ("length", "radius", "diameter", "angle")
        for act in [self.act_select, self.act_cut, None, *self.view_actions.values(), None,
                    *(self.dimension_actions[kind] for kind in basic)]:
            self.tb_tools.addSeparator() if act is None else self.tb_tools.addAction(act)
        # chamfer, arc length, baseline, chain, ordinate: one drop-down button
        more = QToolButton()
        more.setIcon(QIcon(os.path.join(icon_dir, "dimension.png")))
        more.setToolTip("More dimensions: chamfer, arc length, baseline, chain, ordinate")
        more.setPopupMode(QToolButton.InstantPopup)
        more_menu = QMenu(more)
        for kind, act in self.dimension_actions.items():
            if kind not in basic:
                more_menu.addAction(act)
        more.setMenu(more_menu)
        self.tb_tools.addWidget(more)
        self.tb_tools.addSeparator()
        self.tb_tools.addWidget(tool_group("", [grid_icon, QLabel("Grid"), self.sp_grid,
                                                QLabel("Snap"), self.sp_snap], framed=False))
        self.tb_tools.addAction(self.act_snap)
        toolbar_gap("tb_drawing_view_gap", 12)
        for bar in (self.tb_file, self.tb_tools):        # icons as large as the buttons allow
            enlarge_toolbar_icons(bar)

        # panels: docks like the main window's panels; tabbed together on the right, each one
        # can be moved to the left or right, closed and shown again (View menu / Panels button)
        def panel(title, name, page, icon):
            dock = QDockWidget(title, workspace)
            dock.setObjectName(name)
            dock.setWindowIcon(QIcon(os.path.join(icon_dir, icon)))
            dock.setFeatures(QDockWidget.DockWidgetMovable | QDockWidget.DockWidgetClosable)
            dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
            scroll = QScrollArea()
            scroll.setWidgetResizable(True)
            scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            scroll.setWidget(page)
            # never narrower than its contents (nothing is cut off at the right edge)
            scroll.setMinimumWidth(max(270, page.minimumSizeHint().width() +
                                       scroll.verticalScrollBar().sizeHint().width() + 4))
            dock.setWidget(scroll)
            workspace.addDockWidget(Qt.RightDockWidgetArea, dock)
            dock.toggleViewAction().toggled.connect(lambda _visible: self._sync_panels_action())
            return dock

        # explorer-style check boxes, spin boxes that fit their numbers (before the panels take
        # their minimum width from the pages)
        for page in (view_page, dimensions_page, sheet_page, self.tb_tools):
            _style_dialog_widgets(page)
        self.views_dock = panel("Views", "dock_drawing_views", view_page, "view_isometric.png")
        self.dimensions_dock = panel("Dimensions", "dock_drawing_dimensions", dimensions_page,
                                     "dimension.png")
        self.sheet_dock = panel("Sheet", "dock_drawing_sheet", sheet_page, "technical_drawing.png")
        workspace.tabifyDockWidget(self.views_dock, self.dimensions_dock)
        workspace.tabifyDockWidget(self.dimensions_dock, self.sheet_dock)
        self.views_dock.raise_()
        self.panel_docks = (self.views_dock, self.dimensions_dock, self.sheet_dock)

        # menu bar with the same actions as the toolbars (checked / enabled states stay in sync)
        menu_bar = QMenuBar(workspace)
        file_menu = menu_bar.addMenu("&File")
        for act in (self.act_import_graphic, self.act_import_logo, None,
                    self.act_export, None, self.act_finish, self.act_cancel):
            file_menu.addSeparator() if act is None else file_menu.addAction(act)
        edit_menu = menu_bar.addMenu("&Edit")
        for act in (self.act_undo, self.act_redo, None, self.act_delete):
            edit_menu.addSeparator() if act is None else edit_menu.addAction(act)
        sheet_menu = menu_bar.addMenu("&Sheet")
        for act in (self.act_add_sheet, self.act_duplicate_sheet, self.act_rename_sheet, None,
                    self.act_delete_sheet):
            sheet_menu.addSeparator() if act is None else sheet_menu.addAction(act)
        view_menu = menu_bar.addMenu("&View")
        view_menu.addAction(self.act_fit)
        view_menu.addSeparator()
        for dock in self.panel_docks:
            view_menu.addAction(dock.toggleViewAction())
        view_menu.addSeparator()
        for bar in (self.tb_file, self.tb_tools):
            view_menu.addAction(bar.toggleViewAction())
        tools_menu = menu_bar.addMenu("&Tools")
        tools_menu.addAction(self.act_select)
        tools_menu.addAction(self.act_cut)
        place_menu = tools_menu.addMenu(QIcon(os.path.join(icon_dir, "view_front.png")), "Place View")
        for act in self.view_actions.values():
            place_menu.addAction(act)
        dimension_menu = tools_menu.addMenu(QIcon(os.path.join(icon_dir, "dimension.png")),
                                            "Dimension")
        for act in self.dimension_actions.values():
            dimension_menu.addAction(act)
        tools_menu.addSeparator()
        tools_menu.addAction(self.act_snap)
        workspace.setMenuBar(menu_bar)

        # status bar: drawing status on the left, Finish / Cancel on the right
        status_bar = QStatusBar(workspace)
        status_bar.setSizeGripEnabled(False)
        self.drawing_status = QLabel("Ready")
        self.drawing_status.setStyleSheet("color:#80c8ff;font-size:10px;")
        status_bar.addWidget(self.drawing_status, 1)
        self.object_info = QLabel()          # the extrusion being drawn, with its size
        self.object_info.setStyleSheet("color:#aab2bd;font-size:10px;padding:0 8px;")
        status_bar.addPermanentWidget(self.object_info)
        self._update_object_info()
        finish = QPushButton("✔ Finish Drawing")
        finish.setToolTip("Keep the drawing in the project and close the editor (Ctrl+Enter)")
        finish.clicked.connect(self.accept)
        cancel = QPushButton("✖ Cancel")
        cancel.setToolTip("Close the editor without keeping changes")
        cancel.clicked.connect(self.reject)
        status_bar.addPermanentWidget(finish)
        status_bar.addPermanentWidget(cancel)
        workspace.setStatusBar(status_bar)

        state = self._saved_workspace_state()        # toolbar / panel layout from .settings
        if state is not None:
            workspace.restoreState(state, self.WORKSPACE_STATE_VERSION)
        self._sync_panels_action()
        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.addWidget(workspace, 1)

        self.front_view.setCurrentIndex(max(0, self.front_view.findData(
            tuple(self._options.get("front", (0, 1, 0))))))
        self.canvas.cutRotated.connect(self._on_cut_rotated)
        self.canvas.sectionRemoveRequested.connect(self._remove_section_by_letter)
        self._refresh_dimension_list()
        self._refresh_view_list()
        self._refresh_section_list(0 if self.sections else -1)
        for widget in [self.front_view, self.view_scale]:
            widget.currentIndexChanged.connect(self._refresh_preview)
        for widget in (self.project, self.author, self.date, self.version, self.page,
                       self.title, self.number, self.tolerance, self.surface, self.material,
                       self.treatment):
            widget.editingFinished.connect(self._refresh_preview)
        self.unit.currentIndexChanged.connect(self._refresh_preview)
        self.dual_units.toggled.connect(self._refresh_preview)
        self.parts_list.toggled.connect(self._refresh_preview)
        self.hatch.currentIndexChanged.connect(self._refresh_preview)
        self.gear_quality.currentIndexChanged.connect(self._refresh_preview)
        self.gear_simplified.toggled.connect(self._refresh_preview)
        self.canvas.viewPicked.connect(self._on_view_picked)
        self.notes.textChanged.connect(self._queue_refresh_preview)
        self.canvas.tablePlaced.connect(self._on_table_placed)
        self.projection.currentIndexChanged.connect(self._refresh_preview)
        self._activate_source(self.sheets[self.active_sheet].get("source"))
        self._fill_model_combo()
        self._rebuild_sheet_tabs()
        self._sync_tool_buttons()
        self._restoring_history = False
        self._refresh_preview()
        # undo / redo: snapshots of the drawing, recorded after every finished change
        self._history = History(self._history_state())
        self._sync_history_actions()

    WORKSPACE_STATE_VERSION = 3

    # ── sheets and their models ──────────────────────────────────────────────
    def _initial_sheets(self, source_entry):
        """The sheets of the drawing. Older drawings have one, made of the top-level fields and
        showing the extrusion they belong to."""
        stored = self._options.get("sheets")
        if isinstance(stored, list) and stored:
            sheets = [copy.deepcopy(sheet) for sheet in stored if isinstance(sheet, dict)]
            if sheets:
                for number, sheet in enumerate(sheets, 1):
                    sheet.setdefault("name", f"Sheet {number}")
                return sheets
        sheet = {key: copy.deepcopy(self._options[key]) for key in DRAWING_SHEET_KEYS
                 if key in self._options}
        sheet["sections"] = _drawing_sections(self._options)
        sheet["name"] = sheet.get("name") or "Sheet 1"
        sheet["source"] = self._source_of_entry(source_entry)
        return [sheet]

    @staticmethod
    def _source_of_entry(entry):
        return {"kind": "project", "name": entry["name"]} if entry is not None else None

    @staticmethod
    def _source_key(source):
        return json.dumps(source, sort_keys=True) if source else "none"

    def _project_entry(self, name):
        return next((entry for entry in self.source_entries if entry.get("name") == name), None)

    def _source_name(self, source):
        if not source:
            return None
        if source.get("kind") == "model":
            model = self.models.get(source.get("id"))
            return model.get("name", "Model") if model else "Imported model"
        return str(source.get("name", "Extrusion"))

    def _mesh_of(self, source):
        """Mesh of a sheet's model (None: no model, or the model is gone)."""
        if not source:
            return None
        key = self._source_key(source)
        if key not in self._meshes:
            mesh = None
            if source.get("kind") == "project":
                entry = self._project_entry(source.get("name"))
                if entry is not None and entry.get("type") == "assembly":     # Phase 5
                    mesh = _drawing_assembly_mesh(entry, float(source.get("explode") or 0.0))
                elif entry is not None:
                    mesh = self._mesh_for(entry)
            elif source.get("kind") == "model":
                model = self.models.get(source.get("id"))
                if model:
                    mesh = (model["vertices"], model["triangles"])
            if mesh is not None and (not mesh[1] if isinstance(mesh[1], list) else
                                     not len(mesh[1])):
                mesh = None
            self._meshes[key] = mesh
        return self._meshes[key]

    def _activate_source(self, source):
        """Make `source` the model of the sheet being edited (mesh and projection cache)."""
        self.sheet_source = copy.deepcopy(source) if source else None
        self._geometry_cache = self._geometry_caches.setdefault(self._source_key(source), {})
        self.mesh = self._mesh_of(source)
        self.current_source_entry = self._project_entry(source.get("name")) \
            if source and source.get("kind") == "project" else None
        if hasattr(self, "explode_check"):
            self._sync_explode_controls()
        self._update_object_info()
        self.canvas.empty_hint = (
            "Choose a view in the toolbar, then click the sheet to place it" if self.mesh else
            f"The model '{self._source_name(source)}' is no longer in the project · choose "
            "another one in the Views panel" if source else
            "No model on this sheet · choose an extrusion or imported part in the Views panel, "
            "or place an SVG / DXF drawing (Ctrl+Shift+I)")

    def _fill_model_combo(self):
        """Model choices: none, the project's solids, the imported STEP / STL files."""
        icon_dir = os.path.join(_LOG_DIR, "icons")
        choices = [(None, "No model", "")]
        for entry in self.source_entries:
            choices.append((self._source_of_entry(entry),
                            entry.get("name", "Extrusion") + ("  (assembly)" if entry.get("type") == "assembly" else ""),
                            "assembly.png" if entry.get("type") == "assembly" else
                            "import.png" if entry.get("type") == "imported" else "extrusion.png"))
        for model_id, model in self.models.items():
            choices.append(({"kind": "model", "id": model_id},
                            f"{model.get('name', 'Model')}  (imported file)", "import.png"))
        # (an exploded assembly is the same model choice)
        current = self._source_key(self._source_base(self.sheet_source))
        if self.sheet_source and all(self._source_key(source) != current
                                     for source, _text, _icon in choices):
            choices.append((self.sheet_source, f"{self._source_name(self.sheet_source)}  (missing)",
                            "delete_selected.png"))
        self.model_combo.blockSignals(True)
        self.model_combo.clear()
        for source, text, icon in choices:
            self.model_combo.addItem(QIcon(os.path.join(icon_dir, icon)) if icon else QIcon(),
                                     text, self._source_key(source))
            self.model_combo.setItemData(self.model_combo.count() - 1, source, Qt.UserRole + 1)
        self.model_combo.setCurrentIndex(max(0, self.model_combo.findData(current)))
        self.model_combo.blockSignals(False)

    @staticmethod
    def _source_base(source):
        """A sheet's model without the exploded-view distance of an assembly."""
        if not source:
            return source
        return {key: value for key, value in source.items() if key != "explode"}

    def _on_model_chosen(self, index):
        source = self.model_combo.itemData(index, Qt.UserRole + 1)
        if self._source_key(source) == self._source_key(self._source_base(self.sheet_source)):
            return
        self._set_sheet_model(source)

    def _sync_explode_controls(self):
        entry = self.current_source_entry
        is_assembly = entry is not None and entry.get("type") == "assembly"
        can_explode = False
        if is_assembly:
            assembly = assembly_from_data(entry.get("assembly_data"))
            can_explode = any(assembly_explosion_direction(assembly, component) is not None
                              for component in assembly["components"])
        explode = float((self.sheet_source or {}).get("explode") or 0.0)
        for widget in (self.explode_check, self.explode_distance):
            widget.blockSignals(True)
        self.explode_check.setChecked(explode > 0)
        if explode > 0:
            self.explode_distance.setValue(explode)
        self.explode_check.setEnabled(can_explode or explode > 0)
        self.explode_distance.setEnabled(is_assembly and explode > 0)
        self.explode_check.setToolTip(
            "Assembly sheets: the aligned parts moved apart along their alignment, with chain "
            "lines from where they sit" if can_explode or not is_assembly else
            "Only parts with an alignment (e.g. mate, flush, concentric) move apart - this assembly "
            "has none yet. Add them in the Assembly window.")
        for widget in (self.explode_check, self.explode_distance):
            widget.blockSignals(False)

    def _on_explode_changed(self, *_):
        """Exploded view of an assembly sheet: the aligned parts apart, with trace lines."""
        if self.sheet_source is None or self.current_source_entry is None or \
                self.current_source_entry.get("type") != "assembly":
            return
        source = self._source_base(self.sheet_source)
        if self.explode_check.isChecked():
            source["explode"] = float(self.explode_distance.value())
        self._activate_source(source)
        self._sync_explode_controls()
        self.drawing_status.setText(
            f"Exploded view: aligned parts {self.explode_distance.value():g} mm apart"
            if self.explode_check.isChecked() else "Assembly fitted together")
        self._refresh_preview()

    def _set_sheet_model(self, source):
        """Show another model on this sheet: the placed views stay where they are and show the new
        model; dimensions on the old model's views are removed (graphics keep theirs)."""
        self._activate_source(source)
        self.dimensions[:] = [d for d in self.dimensions if _graphic_id(d.get("view"))]
        self.canvas.select_dimension(None)
        self.canvas._selected_geometry = self.canvas._hover_geometry = None
        self._fill_model_combo()
        self._rebuild_sheet_tabs()
        self._refresh_dimension_list()
        self._refresh_view_list()
        name = self._source_name(source)
        self.drawing_status.setText(f"This sheet shows {name}" if name else
                                    "This sheet has no model")
        self._refresh_preview()
        self.canvas.fit_sheet()

    def _import_graphic(self):
        """Import an SVG / DXF drawing; it is placed with the next click on the sheet."""
        path, _filter = QFileDialog.getOpenFileName(
            self, "Import SVG or DXF", "",
            "2-D drawings (*.svg *.dxf);;SVG (*.svg);;DXF (*.dxf);;All files (*)")
        if not path:
            return
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            data = read_drawing_graphic(path)
        except (OSError, ValueError) as ex:
            QApplication.restoreOverrideCursor()
            QMessageBox.critical(self, "Import failed", f"{os.path.basename(path)}:\n{ex}")
            self.drawing_status.setText(f"Import failed: {ex}")
            return
        QApplication.restoreOverrideCursor()
        graphic_id = "g" + os.urandom(4).hex()
        self.graphics[graphic_id] = data
        self.canvas.set_mode("place_view", GRAPHIC_PREFIX + graphic_id)
        self._sync_tool_buttons()
        self.drawing_status.setText(
            f"{data['name']}: {_drawing_number(data['width'])} × {_drawing_number(data['height'])} mm · "
            "click the sheet to place it (Esc cancels)")

    def _on_graphic_scale_changed(self, _index):
        record = self.canvas.selected
        if record is None or not _graphic_id(record.get("name")):
            return
        ratio = self.graphic_scale.currentData()
        if ratio:
            record["scale"] = float(ratio)
        else:
            record.pop("scale", None)
        self._refresh_view_list()
        self._refresh_preview()

    def _placement_label(self, record):
        name = record.get("name")
        graphic = self.graphics.get(_graphic_id(name))
        if graphic is not None:
            return f"Imported: {graphic.get('name', 'graphic')}"
        letter = _section_view_letter(name, self.sections)
        if letter:
            return f"Section {letter}-{letter}"
        if str(name).startswith("detail-"):
            return f"Detail {name[len('detail-'):]}"
        if str(name).startswith("aux-"):
            return f"Auxiliary view {name[len('aux-'):]}"
        return {"top": "Top View", "bottom": "Bottom View", "front": "Front View", "left": "Left Side",
                "right": "Right Side", "isometric": "Isometric"}.get(
                    name, str(name or "View").title())

    # sheet list ----------------------------------------------------------------
    def _sheet_from_widgets(self):
        """The sheet being edited, as stored in the drawing."""
        return {
            "name": self.sheets[self.active_sheet].get("name") or f"Sheet {self.active_sheet + 1}",
            "source": copy.deepcopy(self.sheet_source),
            "front": self.front_view.currentData(),
            "rotation": [spin.value() for spin in self.rotation],
            "scale_ratio": self.view_scale.currentData(),
            "view_placements": [dict(value) for value in self.view_placements],
            "dimensions": [dict(value) for value in self.dimensions],
            "sections": [dict(section) for section in self.sections],
            "sheet": self.sheet_size.currentData(),
            "orientation": self.sheet_orientation.currentData(),
            "title": self.title.text().strip(),
            "number": self.number.text().strip(),
            "material": self.material.text().strip(),
            "treatment": self.treatment.text().strip(),
            "notes": self.notes.toPlainText().strip(),
            "unit": self.unit.currentData(),
            "dual_units": self.dual_units.isChecked(),
            "parts_list": self.parts_list.isChecked(),
            "parts": self._current_parts() if self.parts_list.isChecked() else [],
            "hole_table": copy.deepcopy(self.hole_table),
            "details": [dict(item) for item in self.details],
            "aux_views": [dict(item) for item in self.aux_views],
            "hatch": self.hatch.currentData(),
            "gear_table": copy.deepcopy(self.gear_table),
            "gear_quality": self.gear_quality.currentData(),
            "gear_simplified": self.gear_simplified.isChecked(),
            "stackups": copy.deepcopy(self.stackups),
            "_model_material": (self.current_source_entry or {}).get("material", ""),
        }

    def _current_parts(self):
        """Parts list of the sheet's model (the solid and its bodies, or the imported file)."""
        source = self.sheet_source
        if not source:
            return []
        if source.get("kind") == "model":
            model = self.models.get(source.get("id"))
            return [{"name": model.get("name", "Model") if model else "Imported model",
                     "qty": 1, "material": ""}]
        entry = self._project_entry(source.get("name"))
        return self._parts_for(entry) if entry is not None else []

    def _material_from_model(self):
        entry = self.current_source_entry
        material = entry.get("material", DEFAULT_MATERIAL) if entry is not None else ""
        if not material:
            self.drawing_status.setText("The sheet's model has no material")
            return
        self.material.setText(str(material))
        self._refresh_preview()

    def _begin_hole_table(self):
        record = self.canvas.selected
        if record is None or record.get("name") not in DRAWING_MAIN_VIEWS and \
                not str(record.get("name", "")).startswith("section"):
            QMessageBox.information(self, "Hole table", "Select a placed view (front, top, side or "
                                    "section) in the Views panel or on the sheet first.")
            return
        self._hole_table_view = record.get("name")
        self._table_kind = "hole"
        self.canvas.set_mode("place_table")

    def _begin_table_placement(self, kind):
        """Gear data table (Phase 4): click where its top left corner should sit."""
        if not self._model_info(self.sheet_source).get("gears"):
            QMessageBox.information(self, "Gear data table", "The model of this sheet is no gear "
                                    "made with the Gear tool.")
            return
        self._table_kind = kind
        self.canvas.set_mode("place_table")
        self.drawing_status.setText("Gear data table: click where its top left corner should be")

    def _remove_gear_table(self):
        if self.gear_table is None:
            return
        self.gear_table = None
        self.drawing_status.setText("Gear data table removed")
        self._refresh_preview()

    def _on_table_placed(self, point):
        kind = getattr(self, "_table_kind", None)
        if isinstance(kind, tuple) and kind[0] == "stackup":
            self._table_kind = None
            if 0 <= kind[1] < len(self.stackups):
                self.stackups[kind[1]].update(x=float(point[0]), y=float(point[1]))
                self.drawing_status.setText("Stack-up table placed")
                self._refresh_preview()
            return
        if kind == "gear":
            self._table_kind = None
            self.gear_table = {"x": float(point[0]), "y": float(point[1])}
            self.drawing_status.setText("Gear data table placed")
            self._refresh_preview()
            return
        view = getattr(self, "_hole_table_view", None)
        if not view:
            return
        self.hole_table = {"view": view, "x": float(point[0]), "y": float(point[1])}
        self.drawing_status.setText(f"Hole table of the {self._placement_label({'name': view})} "
                                    "placed")
        self._refresh_preview()

    def _remove_hole_table(self):
        if self.hole_table is None:
            return
        self.hole_table = None
        self.drawing_status.setText("Hole table removed")
        self._refresh_preview()

    def _store_active_sheet(self):
        self.sheets[self.active_sheet] = self._sheet_from_widgets()

    def _load_sheet_into_widgets(self, sheet):
        """Show a stored sheet in the editor (fields, views, dimensions, sections, model)."""
        widgets = (self.front_view, self.view_scale, self.sheet_size, self.sheet_orientation,
                   *self.rotation, self.title, self.number, self.material, self.treatment,
                   self.notes, self.unit, self.dual_units, self.parts_list, self.hatch,
                   self.gear_quality, self.gear_simplified)
        for widget in widgets:
            widget.blockSignals(True)
        try:
            self.material.setText(str(sheet.get("material") or ""))
            self.treatment.setText(str(sheet.get("treatment") or ""))
            self.notes.setPlainText(str(sheet.get("notes") or ""))
            self.unit.setCurrentIndex(max(0, self.unit.findData(sheet.get("unit") or "mm")))
            self.dual_units.setChecked(bool(sheet.get("dual_units")))
            self.parts_list.setChecked(bool(sheet.get("parts_list")))
            self.hole_table = copy.deepcopy(sheet.get("hole_table")) \
                if isinstance(sheet.get("hole_table"), dict) else None
            self.details[:] = [dict(item) for item in sheet.get("details") or []]
            self.stackups[:] = [copy.deepcopy(item) for item in sheet.get("stackups") or []]
            self.aux_views[:] = [dict(item) for item in sheet.get("aux_views") or []]
            self.hatch.setCurrentIndex(max(0, self.hatch.findData(sheet.get("hatch") or "auto")))
            self.gear_table = copy.deepcopy(sheet.get("gear_table")) \
                if isinstance(sheet.get("gear_table"), dict) else None
            self.gear_quality.setCurrentIndex(max(0, self.gear_quality.findData(
                str(sheet.get("gear_quality") or "8"))))
            self.gear_simplified.setChecked(bool(sheet.get("gear_simplified", True)))
            self.canvas.set_mode()
            self.front_view.setCurrentIndex(max(0, self.front_view.findData(
                tuple(sheet.get("front") or (0, 1, 0)))))
            for spin, value in zip(self.rotation, sheet.get("rotation") or (0, 0, 0)):
                spin.setValue(int(value) % 360)
            ratio = sheet.get("scale_ratio")
            self.view_scale.setCurrentIndex(0 if not ratio else min(
                range(1, self.view_scale.count()),
                key=lambda i: abs(math.log(self.view_scale.itemData(i) / float(ratio)))))
            self.sheet_size.setCurrentIndex(max(0, self.sheet_size.findData(
                _drawing_sheet(sheet)["name"])))
            self.sheet_orientation.setCurrentIndex(max(0, self.sheet_orientation.findData(
                _drawing_sheet(sheet)["orientation"])))
            self.title.setText(str(sheet.get("title") or ""))
            self.number.setText(str(sheet.get("number") or ""))
            # the lists are changed in place: the canvas works on the same objects
            self.view_placements[:] = [dict(item) for item in sheet.get("view_placements") or []]
            self.dimensions[:] = [dict(item) for item in sheet.get("dimensions") or []]
            self.sections[:] = [dict(item) for item in _drawing_sections(sheet)]
            self.canvas.selected = None
            self.canvas._selected_geometry = None
            self.canvas._hover_geometry = None
            self.canvas.select_dimension(None)
            self._activate_source(sheet.get("source"))
            self._fill_model_combo()
        finally:
            for widget in widgets:
                widget.blockSignals(False)
        self.page.setText(f"{self.active_sheet + 1} / {len(self.sheets)}")

    def _rebuild_sheet_tabs(self):
        self.sheet_tabs.blockSignals(True)
        while self.sheet_tabs.count():
            self.sheet_tabs.removeTab(0)
        for index, sheet in enumerate(self.sheets):
            self.sheet_tabs.addTab(sheet.get("name") or f"Sheet {index + 1}")
            source = self.sheet_source if index == self.active_sheet else sheet.get("source")
            self.sheet_tabs.setTabToolTip(
                index, f"{self._source_name(source) or 'No model'} · "
                       f"{_drawing_sheet(sheet)['name']} {_drawing_sheet(sheet)['orientation']}")
        self.sheet_tabs.setCurrentIndex(self.active_sheet)
        self.sheet_tabs.blockSignals(False)
        # the + button right after the last tab (the bar would otherwise keep a minimum width)
        self.sheet_tabs.setMaximumWidth(sum(self.sheet_tabs.tabRect(index).width()
                                            for index in range(self.sheet_tabs.count())) + 2)
        self.act_delete_sheet.setEnabled(len(self.sheets) > 1)
        self.page.setText(f"{self.active_sheet + 1} / {len(self.sheets)}")

    def _show_sheet(self, index, record_history=True):
        """Switch to another sheet. A switch alone is not an undo step."""
        self.active_sheet = index
        self._load_sheet_into_widgets(self.sheets[index])
        self._rebuild_sheet_tabs()
        self._refresh_view_list()
        self._refresh_dimension_list()
        self._refresh_section_list(0 if self.sections else -1)
        if record_history:
            self._refresh_preview()
        else:
            self._restoring_history = True
            try:
                self._refresh_preview()
            finally:
                self._restoring_history = False
            if getattr(self, "_history", None) is not None:
                self._history.cur = self._history_state()
        self.canvas.fit_sheet()
        self._sync_tool_buttons()

    def _on_sheet_tab_changed(self, index):
        if index == self.active_sheet or not 0 <= index < len(self.sheets):
            return
        self._store_active_sheet()
        self._show_sheet(index, record_history=False)
        self.drawing_status.setText(f"{self.sheets[index].get('name')} · "
                                    f"{self._source_name(self.sheet_source) or 'no model'}")

    def _on_sheet_tab_moved(self, source, target):
        """A tab was dragged to another place: the sheets are renumbered."""
        self._store_active_sheet()
        sheet = self.sheets.pop(source)
        self.sheets.insert(target, sheet)
        self.active_sheet = self.sheet_tabs.currentIndex()
        self.page.setText(f"{self.active_sheet + 1} / {len(self.sheets)}")
        self._refresh_preview()

    def _new_sheet_name(self):
        used = {sheet.get("name") for sheet in self.sheets}
        return next(f"Sheet {number}" for number in range(1, len(self.sheets) + 2)
                    if f"Sheet {number}" not in used)

    def _add_sheet(self, duplicate=False):
        """Add a sheet after the current one: a copy of it, or an empty sheet in the same format
        showing the same model (choose another one in the Views panel)."""
        self._store_active_sheet()
        current = self.sheets[self.active_sheet]
        if duplicate:
            sheet = copy.deepcopy(current)
            sheet["name"] = f"{current.get('name') or 'Sheet'} (copy)"
        else:
            sheet = {key: copy.deepcopy(current.get(key)) for key in
                     ("source", "front", "rotation", "scale_ratio", "sheet", "orientation")}
            sheet.update(name=self._new_sheet_name(), view_placements=[], dimensions=[],
                         sections=[], title=current.get("title", ""), number="")
        self.sheets.insert(self.active_sheet + 1, sheet)
        self._show_sheet(self.active_sheet + 1)
        self.drawing_status.setText(f"{sheet['name']} added · page {self.active_sheet + 1} of "
                                    f"{len(self.sheets)}")

    def _delete_sheet(self, index=None):
        index = self.active_sheet if index is None else index
        if len(self.sheets) < 2 or not 0 <= index < len(self.sheets):
            self.drawing_status.setText("A drawing keeps at least one sheet")
            return
        self._store_active_sheet()
        sheet = self.sheets[index]
        name = sheet.get("name") or f"Sheet {index + 1}"
        content = []
        for key, word in (("view_placements", "view"), ("dimensions", "dimension"),
                          ("sections", "section")):
            count = len(sheet.get(key) or [])
            if count:
                content.append(f"{count} {word}{'s' if count != 1 else ''}")
        question = QMessageBox(QMessageBox.Question, "Delete Sheet",
                               f"Delete the sheet '{name}'?", QMessageBox.Yes | QMessageBox.No, self)
        question.setInformativeText(
            ("It holds " + ", ".join(content) + ". " if content else "The sheet is empty. ") +
            "The other sheets are renumbered.")
        question.setDefaultButton(QMessageBox.No)
        if question.exec_() != QMessageBox.Yes:
            self.drawing_status.setText(f"{name} kept")
            return
        del self.sheets[index]
        target = min(self.active_sheet if index != self.active_sheet else index,
                     len(self.sheets) - 1)
        if index < self.active_sheet:
            target = self.active_sheet - 1
        self._show_sheet(target)
        self.drawing_status.setText(f"{name} deleted (Ctrl+Z brings it back)")

    def _rename_sheet(self, index=None):
        index = self.active_sheet if index is None else index
        if not 0 <= index < len(self.sheets):
            return
        old = self.sheets[index].get("name") or f"Sheet {index + 1}"
        name, ok = QInputDialog.getText(self, "Rename Sheet", "Sheet name:", text=old)
        name = name.strip()[:60]
        if not ok or not name or name == old:
            return
        self._store_active_sheet()
        self.sheets[index]["name"] = name
        self._rebuild_sheet_tabs()
        self._commit_history()

    def _sheet_tab_menu(self, position):
        index = self.sheet_tabs.tabAt(position)
        if index < 0:
            return
        if index != self.active_sheet:
            self.sheet_tabs.setCurrentIndex(index)       # switches the sheet
        menu = QMenu(self)
        for act in (self.act_add_sheet, self.act_duplicate_sheet, self.act_rename_sheet, None,
                    self.act_delete_sheet):
            menu.addSeparator() if act is None else menu.addAction(act)
        menu.exec_(self.sheet_tabs.mapToGlobal(position))

    def sheet_sources(self):
        """The model of every sheet (None for a sheet without one)."""
        self._store_active_sheet()
        return [sheet.get("source") for sheet in self.sheets]

    def sheet_jobs(self):
        """(mesh, complete options) of every sheet, as exported."""
        options = self.drawing_options()
        jobs = []
        for index, sheet_options in enumerate(drawing_sheet_options(options)):
            source = sheet_options.get("source")
            sheet_options["_geometry_cache"] = self._geometry_caches.setdefault(
                self._source_key(source), {})
            sheet_options["_model"] = self._model_info(source)
            jobs.append((self._mesh_of(source), sheet_options))
        return jobs

    def _model_info(self, source):
        """Gears and thread features of a sheet's model (only project solids have them)."""
        if not source or source.get("kind") != "project":
            return {"gears": [], "threads": []}
        entry = self._project_entry(source.get("name"))
        if entry is not None and entry.get("type") == "assembly":
            return _drawing_assembly_info(entry, float(source.get("explode") or 0.0))
        return self._model_info_for(entry) if entry is not None else {"gears": [], "threads": []}

    # ── undo / redo ───────────────────────────────────────────────────────────
    # what a snapshot holds: the content of the drawing, i.e. every sheet and the shared title
    # block fields (not grid / snap or the panel layout; imported files are kept apart, they are
    # never changed)
    SHARED_HISTORY_KEYS = ("projection", "project", "author", "date", "version", "tolerance",
                           "surface", "logo_path")

    def _history_state(self):
        options = self.drawing_options()
        return json.dumps({"shared": {key: options.get(key) for key in self.SHARED_HISTORY_KEYS},
                           "sheets": options["sheets"], "active": self.active_sheet},
                          sort_keys=True, default=_json_default)

    def _commit_history(self):
        """Record the drawing after a change; not while restoring or in the middle of a drag
        (a drag is one step)."""
        if getattr(self, "_history", None) is None or self._restoring_history:
            return
        canvas = self.canvas
        if canvas._drag_offset is not None or canvas._dimension_drag is not None or \
                canvas._cut_drag is not None:
            return
        if self._history.push(self._history_state()):
            self._sync_history_actions()

    def _sync_history_actions(self):
        self.act_undo.setEnabled(bool(self._history.undo_stack))
        self.act_redo.setEnabled(bool(self._history.redo_stack))

    def _undo(self):
        state = self._history.undo()
        if state is not None:
            self._apply_history_state(state)
            self.drawing_status.setText("Undo")
        self._sync_history_actions()

    def _redo(self):
        state = self._history.redo()
        if state is not None:
            self._apply_history_state(state)
            self.drawing_status.setText("Redo")
        self._sync_history_actions()

    def _apply_history_state(self, text):
        """Put a recorded drawing back into the editor (fields, views, dimensions, sections)."""
        state = json.loads(text)
        shared = state.get("shared") or {}
        self._restoring_history = True
        widgets = (self.projection, self.project, self.author, self.date, self.version,
                   self.tolerance, self.surface)
        for widget in widgets:
            widget.blockSignals(True)
        try:
            self.projection.setCurrentIndex(max(0, self.projection.findData(shared.get("projection"))))
            for key in ("project", "author", "date", "version", "tolerance", "surface"):
                getattr(self, key).setText(str(shared.get(key) or ""))
            path = shared.get("logo_path") or ""
            if path != self.logo_path:
                self.logo_path = path
                self.logo_pixmap = QPixmap(path) if path and os.path.isfile(path) else QPixmap()
                self.logo_field.setText(os.path.basename(path) if path else "")
            self.sheets = [dict(sheet) for sheet in state.get("sheets") or []] or \
                [self._sheet_from_widgets()]
            self.active_sheet = min(max(int(state.get("active", 0)), 0), len(self.sheets) - 1)
            self._load_sheet_into_widgets(self.sheets[self.active_sheet])
            self._rebuild_sheet_tabs()
            self._refresh_view_list()
            self._refresh_dimension_list()
            self._refresh_section_list()
            self._refresh_preview()
        finally:
            for widget in widgets:
                widget.blockSignals(False)
            self._restoring_history = False

    def source_entry(self):
        """The project solid of the first sheet that shows one, else None."""
        for source in self.sheet_sources():
            if source and source.get("kind") == "project":
                entry = self._project_entry(source.get("name"))
                if entry is not None:
                    return entry
        return None

    def showEvent(self, event):
        super().showEvent(event)
        _set_dark_title_bar(self)          # dark Windows title bar, as the other windows

    def _settings_owner(self):
        """The main window, whose .settings file also keeps the editor's layout."""
        owner = self.parent()
        return owner if hasattr(owner, "_settings") and hasattr(owner, "_save_settings") else None

    def _saved_workspace_state(self):
        owner = self._settings_owner()
        text = owner._settings.get("session", {}).get("drawing_layout") if owner else ""
        if text:
            try:
                return QByteArray.fromHex(text.encode("ascii"))
            except (UnicodeEncodeError, ValueError):
                pass
        return TechnicalDrawingDialog._workspace_state

    def done(self, result):
        """Keep the toolbar and panel layout: for this session and in .settings."""
        state = self._workspace.saveState(self.WORKSPACE_STATE_VERSION)
        TechnicalDrawingDialog._workspace_state = state
        owner = self._settings_owner()
        if owner is not None:
            owner._settings["session"]["drawing_layout"] = bytes(state.toHex()).decode("ascii")
            owner._save_settings()
        super().done(result)

    def _toggle_panels(self):
        """Panels button: show all panels when none is open, otherwise close them all."""
        show = not any(dock.toggleViewAction().isChecked() for dock in self.panel_docks)
        for dock in self.panel_docks:
            dock.setVisible(show)
        if show:
            self.views_dock.raise_()
        self._sync_panels_action()

    def _sync_panels_action(self):
        if hasattr(self, "panel_docks"):
            self.act_panels.setChecked(
                any(dock.toggleViewAction().isChecked() for dock in self.panel_docks))

    def _delete_selected(self):
        """Edit → Delete Selected: everything the rubber band selected, else the selected
        dimension, otherwise the selected view."""
        if self.canvas.has_multi_selection():
            self._remove_canvas_selection()
        elif self.canvas.selected_dimension is not None:
            self._remove_dimension_at(self.canvas.selected_dimension)
        elif self.canvas.selected is not None:
            self._remove_selected_view()

    # ── cut sections A-A, B-B, … ──────────────────────────────────────────────
    SECTION_LETTERS = "ABCDEFGHJKLMNPQRSTUVWXYZ"     # without I and O (mistaken for 1 and 0)
    SECTION_ROTATION = {0: 2, 2: 1, 1: 0}             # 90° turns: front → right side → top plane

    def _section_index(self, letter):
        return next((index for index, item in enumerate(self.sections)
                     if item["letter"] == letter), -1)

    def _current_section(self):
        row = self.section_list.currentRow()
        return self.sections[row] if 0 <= row < len(self.sections) else None

    def _section_text(self, section):
        letter = section["letter"]
        placed = any(record.get("name") == f"section-{letter}" for record in self.view_placements)
        kind = section.get("kind", "full")
        note = "" if placed or kind == "revolved" else "  (view not placed)"
        kind_text = "" if kind == "full" else f"  ·  {DRAWING_SECTION_KIND_TEXT[kind]}"
        return (f"{letter}-{letter}  ·  {DRAWING_SECTION_PLANE_TEXT[section['plane']]}  ·  "
                f"{section['offset']:g} mm{kind_text}{note}")

    def _refresh_section_list(self, select_row=None):
        row = self.section_list.currentRow() if select_row is None else select_row
        self.section_list.blockSignals(True)
        self.section_list.clear()
        for section in self.sections:
            self.section_list.addItem(self._section_text(section))
        row = min(row, len(self.sections) - 1)
        self.section_list.setCurrentRow(row)
        self.section_list.blockSignals(False)
        self._on_section_row(row)

    def _on_section_row(self, row):
        """Show the selected cut in the plane / offset fields."""
        section = self.sections[row] if 0 <= row < len(self.sections) else None
        for widget in (self.section_plane, self.cut_offset, self.btn_rotate_section,
                       self.btn_remove_section, self.section_kind):
            widget.setEnabled(section is not None)
        self.view_actions["section"].setEnabled(bool(self.sections))
        parameters = (self.section_axis, self.section_split, self.section_offset2,
                      self.section_angle, self.section_side)
        if section is None:
            for widget in parameters:
                widget.setEnabled(False)
            return
        widgets = (self.section_plane, self.cut_offset, self.section_kind) + parameters
        for widget in widgets:
            widget.blockSignals(True)
        self.section_plane.setCurrentIndex(max(0, self.section_plane.findData(section["plane"])))
        self.cut_offset.setValue(float(section["offset"]))
        kind = section.get("kind", "full")
        self.section_kind.setCurrentIndex(max(0, self.section_kind.findData(kind)))
        self.section_axis.setCurrentIndex(max(0, self.section_axis.findData(section.get("axis", "u"))))
        self.section_split.setValue(float(section.get("split", 0.0)))
        self.section_offset2.setValue(float(section.get("offset2", section["offset"])))
        self.section_angle.setValue(float(section.get("angle", 45.0)))
        self.section_side.setCurrentIndex(max(0, self.section_side.findData(section.get("side", 1))))
        for widget in widgets:
            widget.blockSignals(False)
        # only the parameters of this kind
        uses = {"axis": kind in ("half", "offset", "aligned"), "split": kind in ("half", "offset", "aligned"),
                "offset2": kind == "offset", "angle": kind == "aligned", "side": kind == "half"}
        for widget, key in zip(parameters, ("axis", "split", "offset2", "angle", "side")):
            widget.setEnabled(uses[key])

    def _on_section_edited(self, *_):
        section = self._current_section()
        if section is None:
            return
        section["plane"] = int(self.section_plane.currentData())
        section["offset"] = float(self.cut_offset.value())
        kind = self.section_kind.currentData()
        for key in ("kind", "axis", "split", "offset2", "angle", "side"):
            section.pop(key, None)
        if kind != "full":
            section.update(kind=kind, axis=self.section_axis.currentData(),
                           split=float(self.section_split.value()),
                           offset2=float(self.section_offset2.value()),
                           angle=float(self.section_angle.value()),
                           side=int(self.section_side.currentData()))
        if kind == "revolved":            # drawn on the views: no section view of its own
            view = f"section-{section['letter']}"
            self.view_placements[:] = [r for r in self.view_placements if r.get("name") != view]
            self.dimensions[:] = [d for d in self.dimensions if d.get("view") != view]
            self._refresh_view_list()
            self._refresh_dimension_list()
        self._refresh_section_list()
        self._refresh_preview()

    def _next_letter(self):
        """A letter not used by a section, detail or auxiliary view of this sheet."""
        used = {item["letter"] for item in self.sections} | \
            {item["letter"] for item in self.details} | {item["letter"] for item in self.aux_views}
        return next((letter for letter in self.SECTION_LETTERS if letter not in used), None)

    # views made from other views (Phase 3) ---------------------------------------
    PICK_VIEWS = {"detail": "a view", "aux": "a main view", "break": "a main or auxiliary view",
                  "broken_out": "a main view"}

    def _begin_view_pick(self, purpose):
        if self.mesh is None:
            self.drawing_status.setText("This sheet has no model")
            return
        self.canvas.set_mode("view_pick", purpose)

    def _view_record(self, name):
        return next((record for record in self.view_placements if record.get("name") == name), None)

    def _on_view_picked(self, purpose, view, points):
        record = self._view_record(view)
        if purpose in ("detail", "aux"):
            letter = self._next_letter()
            if letter is None:
                self.drawing_status.setText("No more letters available")
                return
            if purpose == "detail":
                centre, edge = np.asarray(points[0], dtype=float), np.asarray(points[1], dtype=float)
                radius = float(np.linalg.norm(edge - centre))
                if radius <= 1e-6:
                    self.drawing_status.setText("Detail: click the centre, then a point of the circle")
                    return
                factor, ok = QInputDialog.getDouble(
                    self, "Detail view", "Enlargement (detail scale / view scale):", 2.0, 0.1, 50.0, 1)
                if not ok:
                    return
                self.details.append({"letter": letter, "view": view, "u": float(centre[0]),
                                     "v": float(centre[1]), "r": radius, "factor": float(factor)})
                name = f"detail-{letter}"
            else:
                self.aux_views.append({"letter": letter, "view": view,
                                       "a": [float(v) for v in points[0]],
                                       "b": [float(v) for v in points[1]], "flip": False})
                name = f"aux-{letter}"
            self.canvas.set_mode("place_view", name)     # (kept while it waits to be placed)
            self._refresh_preview()
            self.drawing_status.setText(f"Click where the view {letter} should go")
            return
        if record is None:
            return
        first, second = np.asarray(points[0], dtype=float), np.asarray(points[1], dtype=float)
        if purpose == "break":
            du, dv = abs(second[0] - first[0]), abs(second[1] - first[1])
            k = 0 if du >= dv else 1
            a, b = sorted((float(first[k]), float(second[k])))
            if b - a <= 1e-6:
                return
            record.setdefault("breaks", []).append({"axis": "u" if k == 0 else "v", "a": a, "b": b})
            self.drawing_status.setText("Break added (dimensions keep the real length)")
        else:
            depth, ok = QInputDialog.getDouble(
                self, "Broken-out section",
                "Depth of the cut plane (from the centre of the part, toward the viewer +):",
                0.0, -100000.0, 100000.0, 2)
            if not ok:
                return
            record["broken_out"] = {"rect": [float(first[0]), float(first[1]), float(second[0]),
                                             float(second[1])], "depth": float(depth)}
            self.drawing_status.setText("Broken-out section added")
        self._refresh_preview()

    def _clear_view_cuts(self):
        record = self.canvas.selected
        if record is None or not ("breaks" in record or "broken_out" in record):
            self.drawing_status.setText("Select a view with a break or broken-out section first")
            return
        record.pop("breaks", None)
        record.pop("broken_out", None)
        self.drawing_status.setText("Breaks and broken-out section removed")
        self._refresh_preview()

    def _prune_derived_views(self):
        """Details and auxiliary views whose view was removed are dropped (with their parent)."""
        placed = {record.get("name") for record in self.view_placements}
        pending = self.canvas.active_view if self.canvas.mode == "place_view" else None
        self.aux_views[:] = [item for item in self.aux_views if item["view"] in placed and
                             (f"aux-{item['letter']}" in placed or f"aux-{item['letter']}" == pending)]
        placed = {record.get("name") for record in self.view_placements}
        self.details[:] = [item for item in self.details if item["view"] in placed and
                           (f"detail-{item['letter']}" in placed or f"detail-{item['letter']}" == pending)]

    def _add_section(self, plane=0, offset=0.0):
        letter = self._next_letter()
        if letter is None:
            self.drawing_status.setText("No more section letters available")
            return
        self.sections.append({"letter": letter, "plane": int(plane), "offset": float(offset)})
        self._refresh_section_list(len(self.sections) - 1)
        self.drawing_status.setText(
            f"Section {letter}-{letter} added · place its view with the Section View tool")
        self._refresh_preview()

    def _rotate_section(self):
        section = self._current_section()
        if section is not None:
            self._on_cut_rotated(section["letter"], self.SECTION_ROTATION[section["plane"]],
                                 section["offset"])

    def _remove_section(self):
        section = self._current_section()
        if section is not None:
            self._remove_section_by_letter(section["letter"])

    def _remove_section_by_letter(self, letter):
        """Remove a cut with its section view and the dimensions on that view."""
        index = self._section_index(letter)
        if index < 0:
            return
        view = f"section-{letter}"
        del self.sections[index]
        self.view_placements[:] = [r for r in self.view_placements if r.get("name") != view]
        self.dimensions[:] = [d for d in self.dimensions if d.get("view") != view]
        if self.canvas.selected is not None and self.canvas.selected.get("name") == view:
            self.canvas.selected = None
        self.canvas.select_dimension(None)
        self._refresh_section_list(min(index, len(self.sections) - 1))
        self._refresh_view_list()
        self._refresh_dimension_list()
        self.drawing_status.setText(f"Section {letter}-{letter} removed")
        self._refresh_preview()

    def _on_cut_rotated(self, letter, plane, offset):
        index = self._section_index(letter)
        if index < 0:
            return
        self.sections[index].update(plane=int(plane), offset=float(offset))
        self._refresh_section_list(index)
        self.drawing_status.setText(
            f"Section {letter}-{letter} rotated: {DRAWING_SECTION_PLANE_TEXT[int(plane)]}")
        self._refresh_preview()

    def _update_snap_icon(self, enabled):
        """Greyed snap icon while snapping is off, as in the sketcher toolbar."""
        mode = QIcon.Normal if enabled else QIcon.Disabled
        self.act_snap.setIcon(QIcon(self._snap_icon.pixmap(QSize(64, 64), mode)))

    def _on_snap_toggled(self, enabled):
        self._update_snap_icon(enabled)
        self.canvas.set_grid(snap_enabled=enabled)
        self.drawing_status.setText("Snap to grid on" if enabled else "Snap to grid off")

    def drawing_options(self):
        """The whole drawing: the fields of the sheet being edited at the top level (what the
        sheet is rendered from), every sheet under "sheets", the shared title block fields and
        the imported models and graphics."""
        sheet = self._sheet_from_widgets()
        self.sheets[self.active_sheet] = sheet
        options = dict(sheet)
        options.update({
            "view_scale": 1.0,
            "project": self.project.text().strip(),
            "author": self.author.text().strip(),
            "date": self.date.text().strip(),
            "version": self.version.text().strip(),
            "page": f"{self.active_sheet + 1} / {len(self.sheets)}",
            "tolerance": self.tolerance.text().strip(),
            "surface": self.surface.text().strip(),
            "projection": self.projection.currentData(),
            "logo": self.logo_pixmap,
            "logo_path": self.logo_path,
            "grid_mm": self.sp_grid.value(),
            "snap_mm": self.sp_snap.value(),
            "snap": self.act_snap.isChecked(),
            "sheets": [dict(item) for item in self.sheets],
            "active_sheet": self.active_sheet,
            "models": self.models,
            "graphics": self.graphics,
        })
        return options

    def _refresh_preview(self, *_):
        self._prune_derived_views()
        picture = QPicture()
        sheet = _drawing_sheet(self.drawing_options())
        picture.setBoundingRect(QRect(0, 0, int(sheet["w"]), int(sheet["h"])))
        painter = QPainter(picture)
        try:
            options = self.drawing_options()
            options["dimensions"] = []
            options["_model"] = self._model_info(self.sheet_source)
            images = []                            # shaded isometric views, drawn by the canvas
            options.update(_geometry_cache=self._geometry_cache, _page_scale=1.0,
                           _projection_resolution=900, _isometric_resolution=1200,
                           _colors=DRAWING_SCREEN_COLORS, _external_images=images)
            vertices, triangles = self.mesh if self.mesh is not None else (None, None)
            layout = _draw_technical_drawing(painter, vertices, triangles, options)
            layout["images"] = images
            source_sketch = self.current_source_entry.get("parent") \
                if self.current_source_entry is not None and self.mesh is not None else None
            if source_sketch is not None and source_sketch.get("type") == "sketch":
                self._attach_sketch_references(layout, source_sketch["sketch"], options)
        except (ValueError, RuntimeError, KeyError) as ex:
            painter.end()
            self.drawing_status.setText(f"Preview unavailable: {ex}")
            return
        painter.end()
        self._resolve_callouts()                 # hole / thread callouts follow the model
        self.canvas.units = _drawing_units_of(options)
        self.canvas.set_sheet(picture, layout, self.view_placements, self.dimensions)
        self._commit_history()                   # every finished change is one undo step

    def _queue_refresh_preview(self):
        if not self._preview_timer.isActive():
            dragging = self.canvas._drag_offset is not None or \
                self.canvas._dimension_drag is not None or self.canvas._cut_drag is not None
            # short while dragging: a refresh takes ~20 ms now, the view follows the mouse
            self._preview_timer.start(15 if dragging else 40)

    def _update_object_info(self):
        """Status bar: name and overall size of the sheet's model (with its child bodies)."""
        if not hasattr(self, "object_info"):
            return
        name = self._source_name(self.sheet_source)
        if name is None:
            text = "No model on this sheet"
        elif self.mesh is None:
            text = f"Model missing: {name}"
        else:
            kind = "Imported file" if self.sheet_source.get("kind") == "model" else "Object"
            text = f"{kind}: {name}"
            vertices = np.asarray(self.mesh[0], dtype=float).reshape(-1, 3)
            used = vertices[np.unique(np.asarray(self.mesh[1], dtype=int))]
            size = used.max(axis=0) - used.min(axis=0)
            text += "  ·  " + " × ".join(_drawing_number(float(value)) for value in size) + " mm"
        self.object_info.setText(text)
        self.object_info.setToolTip("Model drawn on this sheet (choose another one in the Views "
                                    "panel; each sheet has its own)")

    def _on_sheet_changed(self, *_):
        """New sheet format: the placed views keep their relative position on the sheet (and
        stay on it), then the sheet is redrawn and fitted into the window."""
        sheet = _drawing_sheet(self.drawing_options())
        old_w, old_h = self.canvas.page_w, self.canvas.page_h
        for record in self.view_placements:
            x = float(record.get("x", 60.0)) * sheet["w"] / old_w
            y = float(record.get("y", 60.0)) * sheet["h"] / old_h
            record["x"] = float(min(max(x, 60.0), sheet["w"] - 120.0))
            record["y"] = float(min(max(y, 60.0), sheet["h"] - 120.0))
        self.drawing_status.setText(f"Sheet {sheet['name']} {sheet['orientation']}")
        self._refresh_preview()
        self.canvas.fit_sheet()

    def _on_cut_moved(self, letter, offset):
        """Cutting line dragged: move that section live (preview refreshes are throttled)."""
        index = self._section_index(letter)
        if index < 0:
            return
        self.sections[index]["offset"] = float(offset)
        item = self.section_list.item(index)
        if item is not None:
            item.setText(self._section_text(self.sections[index]))
        if self.section_list.currentRow() != index:
            self.section_list.blockSignals(True)
            self.section_list.setCurrentRow(index)
            self.section_list.blockSignals(False)
        self._on_section_row(index)
        self._queue_refresh_preview()

    def _attach_sketch_references(self, layout, sketch, options):
        vertices, triangles = self.mesh
        used = np.asarray(vertices, dtype=float)[np.unique(np.asarray(triangles, dtype=int))]
        center = (used.min(axis=0) + used.max(axis=0)) / 2.0
        rotation = _import_rotation_matrix(options.get("rotation", (0, 0, 0)))
        reference_points = [vertex.xy() for vertex in sketch.vertices]
        reference_points.extend(point.xy() for point in getattr(sketch, "points_free", ()))
        reference_segments = [(segment.v0.xy(), segment.v1.xy()) for segment in sketch.segments]
        reference_curves = []

        def append_curve(points):
            if len(points) < 2:
                return
            reference_curves.append(np.asarray(points, dtype=float))

        for circle in sketch.circles:
            angles = np.linspace(0.0, 2.0 * math.pi, 65)
            points = np.column_stack((circle.center.x + circle.radius * np.cos(angles),
                                      circle.center.y + circle.radius * np.sin(angles)))
            append_curve(points.tolist())
            reference_points.append(circle.center.xy())
        for arc in sketch.arcs:
            start, sweep = arc.angles()
            count = max(8, int(abs(sweep) / (2.0 * math.pi) * 64))
            angles = np.linspace(start, start + sweep, count + 1)
            radius = arc.radius()
            points = np.column_stack((arc.center.x + radius * np.cos(angles),
                                      arc.center.y + radius * np.sin(angles)))
            append_curve(points.tolist())
            reference_points.extend((arc.center.xy(), arc.v_start.xy(), arc.v_end.xy()))

        if reference_points:
            world_points = sketch.to3d_many(reference_points)
            rotated_points = (world_points - center) @ rotation.T
        else:
            rotated_points = np.zeros((0, 3))
        if reference_segments:
            flat = [point for segment in reference_segments for point in segment]
            world_segments = sketch.to3d_many(flat).reshape(-1, 2, 3)
            rotated_segments = (world_segments - center) @ rotation.T
        else:
            rotated_segments = np.zeros((0, 2, 3))
        if reference_curves:
            counts = [len(curve) for curve in reference_curves]
            world_points = sketch.to3d_many(np.concatenate(reference_curves))
            rotated = (world_points - center) @ rotation.T
            starts = np.cumsum([0, *counts])
            rotated_curves = [rotated[starts[index]:starts[index + 1]]
                              for index in range(len(counts))]
        else:
            rotated_curves = []

        # the references of a view only change with the sketch, the model's orientation and that
        # view's drawn lines; moving views (or anything else) reuses them (the filter for views
        # without hidden lines was the slowest step of a refresh)
        cache = getattr(self, "_reference_cache", None)
        if cache is None or cache.get("sketch") is not sketch or cache.get("mesh") is not self.mesh:
            cache = self._reference_cache = {"sketch": sketch, "mesh": self.mesh, "views": {}}
        used_keys = set()
        for info in layout.get("placements", []):
            # the shaded isometric is not picked from; imported graphics have their own geometry
            if info.get("name") == "isometric" or _graphic_id(info.get("name")):
                continue
            right, up = np.asarray(info["right"]), np.asarray(info["up"])
            key = (info.get("name"), tuple(np.round(right, 9)), tuple(np.round(up, 9)),
                   tuple(np.round(rotation, 9).ravel()), tuple(np.round(center, 9)),
                   bool(info.get("hidden_shown", True)),
                   _drawing_fingerprint(info.get("pick_segments", ())),
                   _drawing_fingerprint(info.get("pick_curves", ())))
            used_keys.add(key)
            if key not in cache["views"]:
                info["reference_points"] = np.column_stack((rotated_points @ right,
                                                             rotated_points @ up))
                info["reference_segments"] = np.stack((rotated_segments @ right,
                                                        rotated_segments @ up), axis=-1)
                info["reference_curves"] = [np.column_stack((curve @ right, curve @ up))
                                             for curve in rotated_curves]
                if not info.get("hidden_shown", True):
                    self._keep_drawn_references(info)
                cache["views"][key] = (info["reference_points"], info["reference_segments"],
                                       info["reference_curves"])
            info["reference_points"], info["reference_segments"], info["reference_curves"] = \
                cache["views"][key]
        for stale in [key for key in cache["views"] if key not in used_keys]:
            del cache["views"][stale]

    @staticmethod
    def _keep_drawn_references(info):
        """Without hidden lines only the sketch references that lie on drawn lines can be
        picked (a sketch edge behind the part is not shown, so it is not offered either)."""
        drawn = [np.asarray(info.get("pick_segments", ()), dtype=float).reshape(-1, 2, 2)]
        for curve in info.get("pick_curves", ()):
            curve = np.asarray(curve, dtype=float).reshape(-1, 2)
            if len(curve) >= 2:
                drawn.append(np.stack((curve[:-1], curve[1:]), axis=1))
        drawn = np.concatenate(drawn) if drawn else np.zeros((0, 2, 2))
        extent = float(np.max(np.subtract(info["high"], info["low"]))) or 1.0
        tolerance = extent * 1e-3

        def on_drawn(points):
            points = np.asarray(points, dtype=float).reshape(-1, 2)
            if not len(drawn) or not len(points):
                return np.zeros(len(points), dtype=bool)
            a, b = drawn[:, 0], drawn[:, 1]
            ab = b - a
            length = np.maximum((ab * ab).sum(axis=1), 1e-24)
            t = np.clip(((points[:, None, :] - a[None]) * ab[None]).sum(axis=2) / length, 0.0, 1.0)
            nearest = a[None] + t[..., None] * ab[None]
            return np.linalg.norm(points[:, None, :] - nearest, axis=2).min(axis=1) <= tolerance

        points = np.asarray(info["reference_points"], dtype=float).reshape(-1, 2)
        info["reference_points"] = points[on_drawn(points)]
        segments = np.asarray(info["reference_segments"], dtype=float).reshape(-1, 2, 2)
        if len(segments):
            checks = np.stack((segments[:, 0], (segments[:, 0] + segments[:, 1]) / 2,
                               segments[:, 1]), axis=1)
            info["reference_segments"] = segments[on_drawn(checks.reshape(-1, 2)).reshape(-1, 3)
                                                  .all(axis=1)]
        info["reference_curves"] = [curve for curve in info["reference_curves"]
                                    if on_drawn(curve[::max(1, len(curve) // 8)]).all()]

    def _begin_view_placement(self, name):
        if self.mesh is None:
            self.canvas.set_mode()
            self._sync_tool_buttons()
            self.drawing_status.setText(
                "This sheet has no model · choose one in the Views panel (Model of this sheet); "
                "STEP / STL parts are imported in the 3-D construction (File → Import)")
            if self.views_dock.isHidden():
                self.views_dock.show()
            self.views_dock.raise_()
            return
        if name == "section":
            # the section selected in the Views panel, else the first one without a view
            section = self._current_section() or next(
                (item for item in self.sections if not any(
                    record.get("name") == f"section-{item['letter']}"
                    for record in self.view_placements)), None)
            if section is None:
                self.drawing_status.setText("Add a section first (Cut tool or Views panel)")
                self._sync_tool_buttons()
                return
            if section.get("kind") == "revolved":
                self.drawing_status.setText("A revolved section is drawn on the views themselves "
                                            "(no view of its own to place)")
                self._sync_tool_buttons()
                return
            name = f"section-{section['letter']}"
        self.canvas.set_mode("place_view", name)

    def _begin_cut_placement(self):
        self.canvas.set_mode("cut")
        self._sync_tool_buttons()

    def _on_canvas_status(self, text):
        self.drawing_status.setText(text)
        self._sync_tool_buttons()

    def _sync_tool_buttons(self):
        mode = self.canvas.mode
        self.act_select.setChecked(mode is None)
        self.act_cut.setChecked(mode == "cut")
        for name, act in self.view_actions.items():
            active = str(self.canvas.active_view or "")
            act.setChecked(mode == "place_view" and (
                active == name or name == "section" and active.startswith("section-")))
        for kind, act in self.dimension_actions.items():
            act.setChecked(mode == "dimension" and self.canvas.dimension_kind == kind)

    def _refresh_view_list(self):
        current = self.canvas.selected if hasattr(self, "canvas") else None
        self.view_list.blockSignals(True)
        self.view_list.clear()
        selected_row = -1
        for index, record in enumerate(self.view_placements):
            label = self._placement_label(record)
            if record.get("name") in self.HIDDEN_LINE_VIEWS and not record.get("hidden_lines", True):
                label += "  (no hidden lines)"
            if _graphic_id(record.get("name")) and record.get("scale"):
                label += f"  ({_drawing_scale_text(float(record['scale']) * DRAWING_UNITS_PER_MM)})"
            self.view_list.addItem(label)
            if record is current:
                selected_row = index
        self.view_list.setCurrentRow(selected_row)
        self.view_list.blockSignals(False)
        self._sync_hidden_lines_box()

    HIDDEN_LINE_VIEWS = DRAWING_MAIN_VIEWS

    def _sync_hidden_lines_box(self):
        record = self.canvas.selected if hasattr(self, "canvas") else None
        applies = record is not None and record.get("name") in self.HIDDEN_LINE_VIEWS
        self.hidden_lines.blockSignals(True)
        self.hidden_lines.setEnabled(applies)
        self.hidden_lines.setChecked(bool(record.get("hidden_lines", True)) if applies else True)
        self.hidden_lines.blockSignals(False)
        graphic = record is not None and bool(_graphic_id(record.get("name")))
        self.graphic_scale.blockSignals(True)
        self.graphic_scale.setEnabled(graphic)
        ratio = record.get("scale") if graphic else None
        self.graphic_scale.setCurrentIndex(0 if not ratio else min(
            range(1, self.graphic_scale.count()),
            key=lambda i: abs(math.log(self.graphic_scale.itemData(i) / float(ratio)))))
        self.graphic_scale.blockSignals(False)

    def _on_hidden_lines_toggled(self, checked):
        record = self.canvas.selected
        if record is None or record.get("name") not in self.HIDDEN_LINE_VIEWS:
            return
        record["hidden_lines"] = bool(checked)
        self._refresh_view_list()
        self.drawing_status.setText(
            f"{record['name'].title()} view: hidden lines {'shown' if checked else 'hidden'}")
        self._refresh_preview()

    def _select_view_row(self, row):
        if 0 <= row < len(self.view_placements):
            self.canvas.selected = self.view_placements[row]
            self.canvas.update()
            self._on_view_selected(self.canvas.selected)

    def _remove_selected_view(self):
        self.canvas.remove_selected()
        self._refresh_view_list()

    def _on_view_selected(self, record):
        if record is None:
            self._sync_hidden_lines_box()
            return
        self._refresh_view_list()
        self.drawing_status.setText(f"Selected: {self._placement_label(record)}")
        self.view_list.blockSignals(True)
        row = next((index for index, item in enumerate(self.view_placements)
                    if item is record), -1)
        self.view_list.setCurrentRow(row)
        self.view_list.blockSignals(False)
        self._sync_tool_buttons()

    def _on_dimension_placed(self, points):
        if self._pending_dimension is None:
            return
        tool, label = self._pending_dimension
        kind = points.get("type") or tool     # baseline / chain make lengths, ordinate ordinates
        value = float(points["value"])
        dimension = {"type": kind, "label": label, "value": value,
                     "view": points["view"], "points": points["points"]}
        if kind not in ("angle", "arc"):
            dimension.update(a=points["a"], b=points["b"])
        dimension.update(points.get("extra") or {})
        self.dimensions.append(dimension)
        if self.canvas.mode != "dimension" or tool not in ("baseline", "chain", "ordinate"):
            self._pending_dimension = None    # a series stays on until right-click
        self.dimension_value.setSuffix("°" if kind == "angle" else " mm")
        self.dimension_value.setValue(value)
        self.canvas.select_dimension(len(self.dimensions) - 1)     # the new one stays highlighted
        self._refresh_dimension_list()
        self._load_tolerance_editor(len(self.dimensions) - 1)
        self._refresh_preview()

    def _on_cut_placed(self, plane, offset):
        """Cut tool: a new section through the clicked point."""
        self._add_section(plane, offset)

    def _refresh_dimension_list(self):
        self.dimension_list.blockSignals(True)
        self.dimension_list.clear()
        for dimension in self.dimensions:
            self.dimension_list.addItem(self._dimension_list_text(dimension))
        selected = self.canvas.selected_dimension if hasattr(self, "canvas") else None
        self.dimension_list.setCurrentRow(-1 if selected is None else selected)
        if selected is None:
            self.dimension_list.clearSelection()
        self.dimension_list.blockSignals(False)

    def _on_dimension_row(self, row):
        """List → sheet: highlight the dimension chosen in the list."""
        if hasattr(self, "canvas"):
            self.canvas.select_dimension(row)
            self._show_dimension_value(row)

    def _on_canvas_dimension_selected(self, index):
        """Sheet → list: select the clicked dimension's row (and bring up the Dimensions panel)."""
        self.dimension_list.blockSignals(True)
        self.dimension_list.setCurrentRow(index)
        if index < 0:
            self.dimension_list.clearSelection()
            self._load_tolerance_editor(-1)
        self.dimension_list.blockSignals(False)
        if index >= 0:
            if self.dimensions_dock.isHidden():
                self.dimensions_dock.show()
            self.dimensions_dock.raise_()
            self.dimension_list.scrollToItem(self.dimension_list.item(index))
            self._show_dimension_value(index)

    # ── tolerance of the selected dimension (Phase 1) ────────────────────────
    def _build_tolerance_editor(self):
        box = QFrame()
        layout = QFormLayout(box)
        layout.setContentsMargins(0, 4, 0, 4)
        title = QLabel("<b>Selected dimension</b>")
        layout.addRow(title)
        self.dim_orient = QComboBox()
        for text, key in (("Aligned (point to point)", None), ("Horizontal", "h"), ("Vertical", "v")):
            self.dim_orient.addItem(text, key)
        self.dim_orient.setToolTip("Length dimensions: along the measured points, or their "
                                   "horizontal / vertical distance")
        self.dim_reference = QCheckBox("Reference dimension (in brackets, not toleranced)")
        self.dim_reference.setToolTip("Auxiliary dimension for information only (ISO 129-1)")
        self.dim_orient.currentIndexChanged.connect(self._apply_dimension_style)
        self.dim_reference.toggled.connect(self._apply_dimension_style)
        layout.addRow("Orientation:", self.dim_orient)
        layout.addRow(self.dim_reference)
        layout.addRow(QLabel("<b>Tolerance</b>"))
        self.tol_mode = QComboBox()
        for mode in TOL_MODES:
            self.tol_mode.addItem(TOL_MODE_TITLES[mode], mode)
        self.tol_mode.setToolTip("How the tolerance is printed. It is stored with the dimension, "
                                 "so the fit calculator and the export read the same numbers.")
        self.tol_upper = QDoubleSpinBox()
        self.tol_lower = QDoubleSpinBox()
        for spin, text in ((self.tol_upper, "Upper deviation (+); ± value when symmetric"),
                           (self.tol_lower, "Lower deviation (−)")):
            spin.setRange(-1000.0, 1000.0)
            spin.setDecimals(3)
            spin.setSingleStep(0.01)
            spin.setSuffix(" mm")
            spin.setToolTip(text)
        self.tol_fit = QLineEdit()
        self.tol_fit.setPlaceholderText("e.g. H7, g6")
        self.tol_fit.setToolTip("ISO 286 fit symbol: capital letters for a hole (H7), lower case "
                                "for a shaft (g6)")
        self.tol_show_dev = QCheckBox("Print the deviations after the symbol")
        self.tol_show_dev.setChecked(True)
        self.tol_status = QLabel("")
        self.tol_status.setWordWrap(True)
        calculator = QPushButton("Fit calculator")
        calculator.clicked.connect(self._open_fit_calculator)
        self.bearing_seat_button = QPushButton("Bearing seat")
        self.bearing_seat_button.setToolTip(
            "For a bearing seat: choose the bearing and load case; the selected diameter gets the "
            "recommended shaft or housing fit, and a note gives the shoulder diameter and the "
            "largest fillet radius")
        self.bearing_seat_button.clicked.connect(self._apply_bearing_seat)
        self.stackup_button = QPushButton("Tolerance stack-up")
        self.stackup_button.setToolTip("Add up a chain of toleranced dimensions (worst case and "
                                       "statistical) and check a gap against its limits")
        self.stackup_button.clicked.connect(self._open_stackup)
        layout.addRow("Mode:", self.tol_mode)
        layout.addRow("Upper:", self.tol_upper)
        layout.addRow("Lower:", self.tol_lower)
        layout.addRow("Fit:", self.tol_fit)
        layout.addRow(self.tol_show_dev)
        layout.addRow(self.tol_status)
        layout.addRow(_right_aligned_buttons([calculator, self.bearing_seat_button,
                                              self.stackup_button]))
        layout.addRow(QLabel("<b>Annotations</b>"))
        annotation_buttons = []
        for kind in TOL_ANNOTATION_KINDS:
            button = QPushButton(TOL_ANNOTATION_TITLES[kind])
            button.setToolTip(
                "Click the hole on a view, then where the callout should sit: the values are read "
                "from the model" if kind == "hole" else
                "Click the thread on a view (its circle or from the side), then where the callout "
                "should sit: the designation is read from the model" if kind == "thread" else
                "Click the part, then where the balloon should sit. On an assembly sheet the item "
                "number is taken from the clicked part, otherwise you choose it from the parts "
                "list" if kind == "balloon" else
                "Set the values, click the feature on a view, then click where the symbol should "
                "sit. Drag it on the sheet, double-click an entry in the list to edit it.")
            button.clicked.connect(lambda checked=False, k=kind: self._start_annotation(k))
            annotation_buttons.append(button)
        layout.addRow(_right_aligned_buttons(annotation_buttons, columns=2))
        self._tol_widgets = (self.tol_mode, self.tol_upper, self.tol_lower, self.tol_fit,
                             self.tol_show_dev)
        self.tol_mode.currentIndexChanged.connect(self._apply_tolerance)
        self.tol_upper.valueChanged.connect(self._apply_tolerance)
        self.tol_lower.valueChanged.connect(self._apply_tolerance)
        self.tol_fit.editingFinished.connect(self._apply_tolerance)
        self.tol_show_dev.toggled.connect(self._apply_tolerance)
        self._load_tolerance_editor(-1)
        return box

    def _load_tolerance_editor(self, row):
        """Show the tolerance of dimension `row` in the editor (disabled without a selection)."""
        valid = 0 <= row < len(self.dimensions) and \
            self.dimensions[row].get("type") != "annotation"
        tolerance = tol_normalize_tolerance(self.dimensions[row].get("tol")) if valid else None
        for widget in self._tol_widgets:
            widget.blockSignals(True)
            widget.setEnabled(valid)
        self.tol_mode.setCurrentIndex(self.tol_mode.findData(tolerance["mode"] if tolerance else "none"))
        self.tol_upper.setValue(float(tolerance.get("upper", 0.0)) if tolerance else 0.0)
        self.tol_lower.setValue(float(tolerance.get("lower", 0.0)) if tolerance else 0.0)
        self.tol_fit.setText(tolerance.get("fit", "") if tolerance else "")
        self.tol_show_dev.setChecked(bool(tolerance.get("show_deviations", True)) if tolerance else True)
        for widget in self._tol_widgets:
            widget.blockSignals(False)
        dimension = self.dimensions[row] if valid else {}
        for widget in (self.dim_orient, self.dim_reference):
            widget.blockSignals(True)
        self.dim_orient.setCurrentIndex(max(0, self.dim_orient.findData(dimension.get("orient"))))
        self.dim_orient.setEnabled(valid and dimension.get("type", "length") == "length")
        self.dim_reference.setChecked(bool(dimension.get("reference")))
        self.dim_reference.setEnabled(valid and dimension.get("type") != "ordinate")
        for widget in (self.dim_orient, self.dim_reference):
            widget.blockSignals(False)
        self._update_tolerance_fields(row)

    def _apply_dimension_style(self, *_):
        """Orientation and reference flag of the selected dimension; a horizontal / vertical
        length measures the projected distance of its points."""
        row = self.dimension_list.currentRow()
        if not 0 <= row < len(self.dimensions) or self.dimensions[row].get("type") == "annotation":
            return
        dimension = self.dimensions[row]
        if self.dim_reference.isChecked():
            dimension["reference"] = True
        else:
            dimension.pop("reference", None)
        if dimension.get("type", "length") == "length":
            orient = self.dim_orient.currentData()
            points = dimension.get("points") or [dimension.get("a"), dimension.get("b")]
            if len(points) >= 2 and points[0] is not None and points[1] is not None:
                delta = np.subtract(points[1], points[0])
                value = abs(float(delta[0])) if orient == "h" else abs(float(delta[1])) \
                    if orient == "v" else float(np.linalg.norm(delta))
                if value <= 1e-9:
                    self.drawing_status.setText("The points have no distance in this direction")
                    self._load_tolerance_editor(row)
                    return
                dimension["value"] = value
                if orient:
                    dimension["orient"] = orient
                else:
                    dimension.pop("orient", None)
        self._refresh_dimension_list_texts()
        self._show_dimension_value(row)
        self._refresh_preview()

    def _update_tolerance_fields(self, row):
        mode = self.tol_mode.currentData()
        valid = 0 <= row < len(self.dimensions) and \
            self.dimensions[row].get("type") != "annotation"
        self.tol_upper.setEnabled(valid and mode in ("symmetric", "deviations", "limits"))
        self.tol_lower.setEnabled(valid and mode in ("deviations", "limits"))
        self.tol_fit.setEnabled(valid and mode == "fit")
        self.tol_show_dev.setEnabled(valid and mode == "fit")
        message = ""
        if valid and mode == "fit":
            try:
                value = float(self.dimensions[row]["value"])
                upper, lower = tol_deviations(self.tol_fit.text().strip(), value)
                message = (f"{self.tol_fit.text().strip()} at {value:g} mm: {upper:+.3f} / "
                           f"{lower:+.3f} mm → {value + lower:.3f} … {value + upper:.3f} mm")
            except ToleranceError as ex:
                message = f"⚠ {ex}"
            except (KeyError, ValueError):
                message = ""
        self.tol_status.setText(message)

    def _apply_tolerance(self, *_):
        """Editor → the selected dimension (stored on the dimension, not typed as text)."""
        row = self.dimension_list.currentRow()
        if not 0 <= row < len(self.dimensions):
            return
        mode = self.tol_mode.currentData()
        tolerance = {"mode": mode, "upper": self.tol_upper.value(), "lower": self.tol_lower.value(),
                     "fit": self.tol_fit.text().strip(), "show_deviations": self.tol_show_dev.isChecked()}
        if mode == "symmetric":
            tolerance["upper"] = abs(tolerance["upper"])
        elif mode in ("deviations", "limits") and tolerance["upper"] < tolerance["lower"]:
            self.tol_status.setText("⚠ The upper deviation is below the lower one.")
            return
        tolerance = tol_normalize_tolerance(tolerance)
        if tolerance:
            self.dimensions[row]["tol"] = tolerance
        else:
            self.dimensions[row].pop("tol", None)
        self._update_tolerance_fields(row)
        self._refresh_dimension_list_texts()
        self._refresh_preview()

    def _refresh_dimension_list_texts(self):
        for row, dimension in enumerate(self.dimensions):
            item = self.dimension_list.item(row)
            if item is not None:
                item.setText(self._dimension_list_text(dimension))

    @staticmethod
    def _dimension_list_text(dimension):
        if dimension.get("type") == "annotation":
            return "Annotation · " + tol_annotation_summary(dimension.get("ann"))
        kind = dimension.get("type", "length").title()
        unit = "°" if kind == "Angle" else " mm"
        label = str(dimension.get("label", "")).strip() or kind
        text = f"{kind} · {label}: {float(dimension['value']):.2f}{unit}"
        summary = tol_tolerance_summary(abs(float(dimension["value"])), dimension.get("tol"))
        return f"{text}  [{summary}]" if summary else text

    def _open_stackup(self):
        """Tolerance stack-up (Phase 5): edit one of the sheet's chains or start a new one."""
        names = [f"{index + 1}: {item.get('name', 'Gap')}" for index, item in enumerate(self.stackups)]
        index = len(self.stackups)
        if names:
            choice, ok = QInputDialog.getItem(self, "Tolerance stack-up", "Stack-up:",
                                              names + ["New stack-up"], 0, False)
            if not ok:
                return
            index = names.index(choice) if choice in names else len(self.stackups)
        current = self.stackups[index] if index < len(self.stackups) else None
        dialog = StackupDialog(self, self.dimensions, self.tolerance.text().strip(), current)
        if dialog.exec_() != QDialog.Accepted:
            return
        result = dialog.result()
        if not result["rows"]:
            if current is not None:
                del self.stackups[index]
            self._refresh_preview()
            return
        if current is not None:
            result.update({key: current[key] for key in ("x", "y") if key in current})
            self.stackups[index] = result
        else:
            self.stackups.append(result)
        if result["show"] and "x" not in result:
            self._table_kind = ("stackup", index)
            self.canvas.set_mode("place_table")
            self.drawing_status.setText("Stack-up table: click where its top left corner should be")
        self._refresh_preview()

    def _apply_bearing_seat(self):
        """Bearing seat (Phase 5): recommended fit on the selected diameter, plus a note with the
        shoulder diameter and the fillet radius."""
        row = self.dimension_list.currentRow()
        if not 0 <= row < len(self.dimensions) or \
                self.dimensions[row].get("type", "length") not in ("diameter", "length"):
            QMessageBox.information(self, "Bearing seat", "Select the diameter of the shaft or "
                                    "housing seat (a diameter or length dimension) first.")
            return
        dimension = self.dimensions[row]
        value = float(dimension["value"])
        dialog = BearingDialog(self, "Bearing seat", diameter=value, button_text="Apply")
        if dialog.exec_() != QDialog.Accepted or dialog.bearing() is None:
            return
        bearing, seat = dialog.bearing(), dialog.seat()
        housing = abs(value - bearing["D"]) < abs(value - bearing["d"])
        nominal = bearing["D"] if housing else bearing["d"]
        if abs(value - nominal) > 0.05 * nominal:
            if QMessageBox.question(self, "Bearing seat", f"The dimension is Ø{value:g} mm, the "
                                    f"bearing's {'outside' if housing else 'bore'} Ø{nominal:g} mm. "
                                    "Apply the fit anyway?") != QMessageBox.Yes:
                return
        symbol = seat["housing"] if housing else seat["shaft"]
        dimension["tol"] = {"mode": "fit", "fit": symbol, "show_deviations": True}
        text = (f"Bearing {bearing['name']}: housing shoulder Ø ≤ {seat['shoulder_housing']:g}"
                if housing else
                f"Bearing {bearing['name']}: shaft shoulder Ø ≥ {seat['shoulder_shaft']:g}") + \
            f", fillet r ≤ {seat['fillet']:g}"
        points = dimension.get("points") or [dimension.get("a")]
        if points and points[0] is not None:
            self.dimensions.append({"type": "annotation", "label": "", "value": 0.0,
                                    "view": dimension.get("view"), "points": [list(points[0])],
                                    "ann": tol_normalize_annotation(
                                        {"kind": "note", "text": text, "leader": True,
                                         "offset": [70.0, 70.0]})})
        self._refresh_dimension_list()
        self._load_tolerance_editor(row)
        self.drawing_status.setText(f"{'Housing' if housing else 'Shaft'} seat Ø{nominal:g} {symbol} "
                                    f"for bearing {bearing['name']}")
        self._refresh_preview()

    def _open_fit_calculator(self):
        row = self.dimension_list.currentRow()
        size = float(self.dimensions[row]["value"]) if 0 <= row < len(self.dimensions) else 25.0
        dialog = FitCalculatorDialog(self, size)
        if dialog.exec_() == QDialog.Accepted and dialog.chosen and \
                0 <= row < len(self.dimensions):
            self.dimensions[row]["tol"] = {"mode": "fit", "fit": dialog.chosen,
                                           "show_deviations": True}
            self._load_tolerance_editor(row)
            self._refresh_dimension_list_texts()
            self._refresh_preview()

    def _part_names(self):
        return [part.get("name", "") for part in self._current_parts()]

    def _start_annotation(self, kind):
        if kind in ("hole", "thread"):
            # placed first; the values are read from the model at the clicked point
            self._pending_annotation = {"kind": kind}
            self.canvas.set_mode("annotation")
            self.drawing_status.setText(f"{TOL_ANNOTATION_TITLES[kind]}: click the "
                                        f"{kind} on a view, then where the callout should sit")
            return
        geometry = (self._geometry_cache or {}).get("geometry")
        if kind == "balloon" and geometry and geometry[2].get("components"):
            # assembly sheet: the item number comes from the clicked part (Phase 5)
            self._pending_annotation = {"kind": "balloon", "auto": True}
            self.canvas.set_mode("annotation")
            self.drawing_status.setText("Balloon: click a part on a view, then where the balloon "
                                        "should sit")
            return
        used = [int((d.get("ann") or {}).get("item", 0)) for d in self.dimensions
                if (d.get("ann") or {}).get("kind") == "balloon"]
        dialog = AnnotationDialog(self, kind, parts=self._part_names(),
                                  item=next(n for n in range(1, 1000) if n not in used))
        if dialog.exec_() != QDialog.Accepted:
            return
        annotation = dialog.annotation()
        if annotation is None:
            QMessageBox.information(self, "Annotation", "The annotation needs its main value "
                                    "(for example the datum letter or the text of a note).")
            return
        self._pending_annotation = annotation
        self.canvas.set_mode("annotation")

    def _callout_view(self, name):
        """(topology of the sheet's model, frame of the view `name`) for reading holes and threads;
        (None, None) without a model or for imported graphics."""
        geometry = (self._geometry_cache or {}).get("geometry")
        if not geometry or not isinstance(name, str):
            return None, None
        topology, frames = geometry[2], geometry[3]
        plane_name = name
        letter = _section_view_letter(name, self.sections)
        if letter is not None:
            section = next((item for item in self.sections if item["letter"] == letter), None)
            if section is None:
                return None, None
            plane_name = DRAWING_SECTION_PLANES[int(section["plane"])]
        frame = frames.get(plane_name)
        if frame is None:
            return None, None
        right, up, normal = frame
        return topology, {"right": right, "up": up, "normal": normal}

    def _resolve_callouts(self):
        """Hole and thread callouts that follow the model take its current values."""
        changed = False
        for dimension in self.dimensions:
            annotation = dimension.get("ann") if dimension.get("type") == "annotation" else None
            if not annotation or annotation.get("kind") not in ("hole", "thread") or \
                    not annotation.get("linked") or not dimension.get("points"):
                continue
            topology, view = self._callout_view(dimension.get("view"))
            if topology is None:
                continue
            resolved = _drawing_resolve_callout(tol_normalize_annotation(annotation), topology,
                                                view, dimension["points"][0])
            if resolved is not None and resolved != tol_normalize_annotation(annotation):
                dimension["ann"] = resolved
                changed = True
        if changed:
            self._refresh_dimension_list_texts()

    def _on_annotation_placed(self, data):
        annotation = getattr(self, "_pending_annotation", None)
        if annotation is None:
            return
        self._pending_annotation = None
        if annotation.get("auto"):
            topology, view = self._callout_view(data["view"])
            item = None if topology is None else \
                _drawing_component_at(topology, view, data["position"])
            if item is None:
                used = [int((d.get("ann") or {}).get("item", 0)) for d in self.dimensions
                        if (d.get("ann") or {}).get("kind") == "balloon"]
                dialog = AnnotationDialog(self, "balloon", parts=self._part_names(),
                                          item=next(n for n in range(1, 1000) if n not in used))
                if dialog.exec_() != QDialog.Accepted or dialog.annotation() is None:
                    self.drawing_status.setText("Balloon not placed")
                    return
                annotation = dialog.annotation()
            else:
                annotation = tol_normalize_annotation({"kind": "balloon", "item": item})
        elif annotation["kind"] in ("hole", "thread") and "label" not in annotation and "d" not in annotation:
            # read the hole / thread at the clicked point, then let the user check the values
            topology, view = self._callout_view(data["view"])
            found = None
            if topology is not None:
                reach = max(float(topology["span"]) * 0.02, 0.5)
                found = (_drawing_hole_at if annotation["kind"] == "hole" else _drawing_thread_at)(
                    topology, view, data["position"], reach)
            if found is None:
                QMessageBox.information(
                    self, TOL_ANNOTATION_TITLES[annotation["kind"]],
                    f"No {annotation['kind']} was found at the clicked point - enter the values "
                    "yourself (they then do not follow the model).")
                raw = {"kind": annotation["kind"], "linked": False}
                raw.update({"d": 6.6} if annotation["kind"] == "hole" else
                           {"label": "M8", "label_pitch": "M8×1.25", "cls": "6H"})
            else:
                raw = dict(found, kind=annotation["kind"], linked=True)
                if annotation["kind"] == "thread" and found.get("cls") is None:
                    raw["cls"] = "6H" if found["internal"] else "6g"     # no feature: a default
            raw["offset"] = data["offset"]
            dialog = AnnotationDialog(self, annotation["kind"], tol_normalize_annotation(raw))
            if dialog.exec_() != QDialog.Accepted or dialog.annotation() is None:
                self.drawing_status.setText("Callout not placed")
                return
            annotation = dialog.annotation()
        annotation = dict(annotation, offset=data["offset"])
        self.dimensions.append({"type": "annotation", "label": "", "value": 0.0,
                                "view": data["view"], "points": [data["position"]],
                                "ann": annotation})
        self.canvas.select_dimension(len(self.dimensions) - 1)
        self._refresh_dimension_list()
        self._load_tolerance_editor(len(self.dimensions) - 1)
        self._refresh_preview()

    def _edit_dimension_item(self, item):
        """Double-click in the list: change the values of an annotation."""
        row = self.dimension_list.row(item)
        if not 0 <= row < len(self.dimensions) or self.dimensions[row].get("type") != "annotation":
            return
        annotation = self.dimensions[row].get("ann")
        dialog = AnnotationDialog(self, (annotation or {}).get("kind", "gdt"), annotation,
                                  parts=self._part_names())
        if dialog.exec_() == QDialog.Accepted and dialog.annotation() is not None:
            self.dimensions[row]["ann"] = dialog.annotation()
            self._refresh_dimension_list_texts()
            self._refresh_preview()

    def _set_general_tolerance(self, text):
        self.tolerance.setText(text)
        self._refresh_preview()

    def _show_dimension_value(self, row):
        self._load_tolerance_editor(row)
        if 0 <= row < len(self.dimensions):
            dimension = self.dimensions[row]
            self.dimension_value.setSuffix("°" if dimension.get("type") == "angle" else " mm")
            self.dimension_value.setValue(float(dimension.get("value", 0.0)))
            self.drawing_status.setText(f"Selected dimension {row + 1} · Delete removes it")

    def _add_dimension(self, kind):
        label = self.dimension_label.text().strip()
        self.dimension_value.setSuffix("°" if kind == "angle" else " mm")
        self._pending_dimension = (kind, label)
        self.canvas.set_mode("dimension", kind)

    def _remove_dimension(self):
        self._remove_dimension_at(self.dimension_list.currentRow())

    def _remove_canvas_selection(self):
        """Delete with several views / dimensions selected (rubber band): all of them at once."""
        views = list(self.canvas.selected_views)
        rows = sorted(self.canvas.selected_dimensions, reverse=True)
        self.canvas.clear_multi_selection()
        for row in rows:                              # from the end: the indices stay valid
            self._remove_dimension_at(row, refresh=False)
        self.view_placements[:] = [record for record in self.view_placements
                                   if not any(record is view for view in views)]
        if self.canvas.selected is not None and any(self.canvas.selected is view for view in views):
            self.canvas.selected = None
        self._refresh_view_list()
        parts = ([f"{len(views)} view{'s' if len(views) != 1 else ''}"] if views else []) + \
            ([f"{len(rows)} dimension{'s' if len(rows) != 1 else ''}"] if rows else [])
        self.drawing_status.setText(f"Removed {' and '.join(parts)}" if parts else "Ready")
        self._refresh_preview()

    def _remove_dimension_at(self, row, refresh=True):
        if not 0 <= row < len(self.dimensions):
            return
        self.dimensions.pop(row)
        for stackup in self.stackups:                 # stack-up rows keep pointing at their dimension
            for item in stackup.get("rows", ()):
                if item.get("dim") == row:
                    item.pop("dim")                   # the values stay, typed in from now on
                elif isinstance(item.get("dim"), int) and item["dim"] > row:
                    item["dim"] -= 1
        self.canvas.select_dimension(None)
        self.canvas._hover_dimension = None
        self.canvas._dimension_drag = None
        self._refresh_dimension_list()
        self._load_tolerance_editor(-1)
        if refresh:
            self.drawing_status.setText("Dimension removed")
            self._refresh_preview()

    def _load_logo(self):
        path, _ = QFileDialog.getOpenFileName(
            self, "Load drawing logo", "",
            "Images (*.png *.jpg *.jpeg *.bmp *.gif *.tif *.tiff *.svg);;All files (*)")
        if not path:
            return
        pixmap = QPixmap(path)
        if pixmap.isNull():
            QMessageBox.warning(self, "Invalid logo", f"Could not load image:\n{path}")
            return
        self.logo_pixmap = pixmap
        self.logo_path = path
        self.logo_field.setText(os.path.basename(path))
        self.logo_field.setToolTip(path)
        self.drawing_status.setText(f"Logo loaded: {os.path.basename(path)}")
        self._refresh_preview()

    def _export_drawing(self):
        """Export the current state of the drawing (all sheets) directly from the editor: a PDF
        with one page per sheet, or one SVG / DXF file per sheet."""
        suggested = self.number.text().strip() or self.title.text().strip() or \
            self.project.text().strip() or "drawing"
        suggested = re.sub(r'[\\/:*?"<>|]+', "_", suggested)
        path, extension = _ask_drawing_export_path(self, suggested + ".pdf")
        if not path:
            return
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            written = write_technical_drawing_sheets(path, extension, self.sheet_jobs())
        except (OSError, ValueError, RuntimeError) as ex:
            QApplication.restoreOverrideCursor()
            QMessageBox.critical(self, "Drawing export failed", str(ex))
            self.drawing_status.setText(f"Export failed: {ex}")
            return
        QApplication.restoreOverrideCursor()
        pages = f" ({len(self.sheets)} pages)" if extension == ".pdf" and len(self.sheets) > 1 else ""
        self.drawing_status.setText(
            f"Exported {os.path.basename(path)}{pages}" if len(written) == 1 else
            f"Exported {len(written)} files: " + ", ".join(os.path.basename(p) for p in written))


def clamp_window_geometry(rect, available, minimum):
    """Clamp a saved (x, y, width, height) rectangle to an available screen rectangle."""
    x, y, width, height = (int(value) for value in rect)
    left, top, screen_width, screen_height = (int(value) for value in available)
    min_width, min_height = (int(value) for value in minimum)
    width = min(screen_width, max(min_width, min(width, screen_width)))
    height = min(screen_height, max(min_height, min(height, screen_height)))
    x = min(max(x, left), left + screen_width - width)
    y = min(max(y, top), top + screen_height - height)
    return x, y, width, height


# ── assembly ──────────────────────────────────────────────────────────────────
# An assembly holds components and alignment constraints. A component is a placed snapshot of a
# parent solid (with all solids built on it), of an imported STEP / STL / OBJ file or of a parent
# solid of a SimpleCAD project file. Geometry is never edited in the assembly; Update re-reads
# the source and keeps the placement. An alignment is a coincident constraint: a reference point
# of the moving part (stored in its own coordinates) is kept on a reference point of the target.
ASSEMBLY_GAP_MM = 20.0
ASSEMBLY_FORMAT = "cad3d-assembly"
ASSEMBLY_EXTENSION = ".asby"
_ASSEMBLY_SOLID_TYPES = ("extrusion", "imported")
_ASSEMBLY_CACHE_KEYS = ("_ec", "_mc", "_np", "_fo", "_fe", "_face_vertex_cache",
                        "_face_outline_cache", "_face_ref")
_ASSEMBLY_TOLERANCE = 1e-7
ASSEMBLY_ROTATION_STEP = 15.0         # degrees; Ctrl while dragging a ring rotates freely
ASSEMBLY_MOVE_STEP = 1.0              # mm; Ctrl reduces the translation step to 0.1 mm
ASSEMBLY_EXPLOSION_DISTANCE = 10.0    # mm; initial separation for an aligned component

ASSEMBLY_DEFAULT_NAME = "Untitled"       # like an unsaved project in the main window

def assembly_new(name=ASSEMBLY_DEFAULT_NAME):
    return {"name": name, "components": [], "constraints": [],
            "explosion_distance": ASSEMBLY_EXPLOSION_DISTANCE}

def _assembly_is_solid(entry):
    return entry.get("type") in _ASSEMBLY_SOLID_TYPES and not entry.get("cut") \
        and not entry.get("preview") and bool(entry.get("solid", (None, []))[1])

def _assembly_solid_root(entry):
    """The first-level solid (not built on another solid) an entry belongs to."""
    root, ancestor = entry, entry.get("parent")
    while ancestor is not None:
        if ancestor.get("type") in _ASSEMBLY_SOLID_TYPES:
            root = ancestor
        ancestor = ancestor.get("parent")
    return root

def _assembly_first_level_solids(objects):
    roots = []
    for entry in objects:
        if not _assembly_is_solid(entry):
            continue
        ancestor = entry.get("parent")
        while ancestor is not None and ancestor.get("type") not in _ASSEMBLY_SOLID_TYPES:
            ancestor = ancestor.get("parent")
        if ancestor is None:
            roots.append(entry)
    return roots

def assembly_root_entries(objects):
    """The parent solids that make the objects of an assembly: first-level extrusions / imports
    (not built on another solid). A solid fused into a Bridge of another one belongs to that
    one's object (assembly_part_entries), so it is not a parent solid of its own; when two
    solids each hold a Bridge with the other one, the first in the project is kept."""
    candidates = _assembly_first_level_solids(objects)
    members = {id(root): {id(part) for part in assembly_part_entries(root, objects)}
               for root in candidates}
    absorbed = {id(root) for root in candidates
                if any(id(root) in members[id(other)] for other in candidates if other is not root)}
    roots, claimed = [], set()
    for root in candidates:                     # not part of another object: always a root
        if id(root) not in absorbed:
            roots.append(root); claimed |= members[id(root)]
    for root in candidates:                     # only Bridges among each other: the first one
        if id(root) in absorbed and id(root) not in claimed:
            roots.append(root); claimed |= members[id(root)]
    order = {id(entry): index for index, entry in enumerate(objects)}
    return sorted(roots, key=lambda root: order.get(id(root), 0))

def assembly_part_entries(root, objects):
    """A parent solid followed by every visible solid that depends on it. A Bridge in it brings
    the solids it fused (and what is built on them): they are one object with it. Cut tools are
    left out: their effect is already part of the solids."""
    present = {id(entry) for entry in objects}
    parts, seen, pending = [], set(), [root]
    while pending:
        base = pending.pop(0)
        for entry in [base] + entry_descendants(base, objects):
            if id(entry) in seen or not _assembly_is_solid(entry):
                continue
            if entry is not base and not entry.get("visible", True):
                continue
            seen.add(id(entry)); parts.append(entry)
            if entry.get("source_format") == "bridge" and entry.get("visible", True):
                for source in entry.get("bridge_sources", []):
                    other = source.get("entry")
                    if other is not None and id(other) in present and id(other) not in seen:
                        pending.append(_assembly_solid_root(other))
    return parts

def _assembly_mesh_signature(vertices, triangles):
    V = np.asarray(vertices, float).reshape(-1, 3)
    return [len(V), len(triangles), round(float(V.sum()), 6), round(float((V*V).sum()), 6)]

def assembly_signature(parts):
    """Cheap fingerprint of the meshes of a source; changes when the geometry changes."""
    return [_assembly_mesh_signature(*part["solid"][:2]) for part in parts]

def assembly_project_groups(root, objects):
    """The assembly objects a parent solid gives: [{"key", "bodies", "signature"}]. Normally
    one (key ()); a splitting Cut Surface makes the parts on its far side separate objects
    (key = the names of the Cut Surfaces they lie behind), so they can be placed on their own.
    The main part (key ()) comes first."""
    parts = assembly_part_entries(root, objects)
    fused = {id(source["entry"]) for part in parts if part.get("source_format") == "bridge"
             for source in part.get("bridge_sources", []) if source.get("entry") is not None}
    groups = {}
    for part in parts:
        for key, (vertices, triangles, faces) in mesh_pieces_keyed(part):
            group = groups.setdefault(tuple(key), {"key": tuple(key), "bodies": [],
                                                    "signature": []})
            group["bodies"].append(assembly_body(
                part["name"], vertices, triangles, faces, part.get("color", DEFAULT_SOLID_COLOR),
                part.get("opacity", 1.0), id(part) in fused, part.get("material"),
                assembly_gear_data(part)))
            group["signature"].append(_assembly_mesh_signature(vertices, triangles))
    return [groups[key] for key in sorted(groups, key=lambda key: (len(key), key))]

def assembly_group_name(root_name, groups, group):
    """"name" for the only object of a parent solid, "name part N" for split parts."""
    if len(groups) == 1:
        return root_name
    return f"{root_name} part {next(i for i, g in enumerate(groups, 1) if g is group)}"

def _assembly_faces(faces):
    """Faces of an assembly snapshot: planar flag, triangles and - for faces a cut made - the
    cut plane frame (origin, u, v, normal) as lists in the body's own coordinates (hatching)."""
    out = []
    for face in faces or []:
        record = {"planar": bool(face.get("planar", False)),
                  "tris": [int(index) for index in face.get("tris", ())]}
        if face.get("section") is not None:
            record["section"] = [[float(x) for x in vector] for vector in face["section"]]
        out.append(record)
    return out

def assembly_world_faces(component, faces, offset=None):
    """The faces with their cut plane frames moved / rotated like the component (world)."""
    if not any(face.get("section") is not None for face in faces):
        return faces
    rotation = _import_rotation_matrix(component["rotation"])
    pivot = np.asarray(component["pivot"], float)
    shift = np.asarray(component["position"], float) + \
        (np.asarray(offset, float) if offset is not None else 0.0)
    out = []
    for face in faces:
        if face.get("section") is not None:
            origin, u, v, normal = (np.asarray(vector, float) for vector in face["section"])
            face = dict(face, section=((origin - pivot) @ rotation.T + pivot + shift,
                                       rotation @ u, rotation @ v, rotation @ normal))
        out.append(face)
    return out

def assembly_body(name, vertices, triangles, faces, color=DEFAULT_SOLID_COLOR, opacity=1.0,
                  fused=False, material=None, gear=None):
    """Snapshot of a solid. `material` is the project object's material (None for files);
    `gear` the data of a gear made with the Gear tool (assembly_gear_data), used for motion."""
    body = {"name": name, "color": [float(c) for c in list(color)[:3]], "opacity": float(opacity),
            "vertices": np.asarray(vertices, float).reshape(-1, 3).copy(),
            "triangles": [tuple(int(i) for i in tri) for tri in triangles],
            "faces": _assembly_faces(faces), "fused": bool(fused),
            "material": material if material in MATERIAL_DENSITIES_G_CM3 else None}
    gear = _assembly_gear_clean(gear)
    if gear:
        body["gear"] = gear
    return body

def _assembly_gear_clean(gear):
    """A JSON-safe copy of a body's gear data, or None."""
    if not isinstance(gear, dict) or not gear.get("kind"):
        return None
    out = {"kind": str(gear["kind"])}
    for key in ("teeth", "module", "starts", "ring_teeth", "sun_teeth", "planet_teeth"):
        if gear.get(key) is not None:
            try:
                out[key] = float(gear[key])
            except (TypeError, ValueError):
                pass
    for key in ("origin", "axis", "x_axis"):
        if gear.get(key) is not None:
            out[key] = [float(x) for x in gear[key]][:3]
    return out

def assembly_gear_data(entry):
    """Kind, teeth, module and the axis (in the entry's coordinates) of a gear made with the Gear
    tool, or None for other bodies."""
    parameters = entry.get("gear_parameters")
    if not parameters or not parameters.get("kind"):
        return None
    rotation = _import_rotation_matrix(entry.get("gear_rotation", (0.0, 0.0, 0.0)))
    gear = {key: parameters.get(key) for key in ("kind", "teeth", "module", "starts", "ring_teeth",
                                                 "sun_teeth", "planet_teeth")}
    gear["origin"] = list(entry.get("gear_position", (0.0, 0.0, 0.0)))
    gear["axis"] = rotation[:, 2].tolist()
    gear["x_axis"] = rotation[:, 0].tolist()
    return _assembly_gear_clean(gear)

def assembly_body_from_entry(entry, fused=False):
    return assembly_body(entry["name"], entry["solid"][0], entry["solid"][1], entry.get("faces", []),
                         entry.get("color", DEFAULT_SOLID_COLOR), entry.get("opacity", 1.0), fused,
                         entry.get("material"), assembly_gear_data(entry))

def assembly_bodies_from_parts(parts):
    """Snapshots of the parts (all pieces); solids already contained in a Bridge are flagged
    so they are not exported twice."""
    fused = {id(source["entry"]) for part in parts if part.get("source_format") == "bridge"
             for source in part.get("bridge_sources", []) if source.get("entry") is not None}
    return [assembly_body(part["name"], vertices, triangles, faces,
                          part.get("color", DEFAULT_SOLID_COLOR), part.get("opacity", 1.0),
                          id(part) in fused, part.get("material"), assembly_gear_data(part))
            for part in parts for vertices, triangles, faces in mesh_pieces_of(part)]

def assembly_world_vertices(component, vertices):
    """Rotation about the component pivot, then translation by its position."""
    rotation = _import_rotation_matrix(component["rotation"])
    pivot = np.asarray(component["pivot"], float)
    return (np.asarray(vertices, float) - pivot) @ rotation.T + pivot \
        + np.asarray(component["position"], float)

def assembly_world_point(component, local):
    return assembly_world_vertices(component, np.asarray(local, float)[None])[0]

def assembly_world_direction(component, local):
    return _import_rotation_matrix(component["rotation"]) @ np.asarray(local, float)

def assembly_local_direction(component, world):
    return _import_rotation_matrix(component["rotation"]).T @ np.asarray(world, float)

def assembly_local_point(component, world):
    rotation = _import_rotation_matrix(component["rotation"])
    return rotation.T @ (np.asarray(world, float) - np.asarray(component["pivot"], float)
                         - np.asarray(component["position"], float)) \
        + np.asarray(component["pivot"], float)

def assembly_bounds(component):
    boxes = []
    for body in component["bodies"]:
        world = assembly_world_vertices(component, body["vertices"])
        if len(world):
            boxes.append((world.min(0), world.max(0)))
    if not boxes:
        return None
    return np.min([box[0] for box in boxes], axis=0), np.max([box[1] for box in boxes], axis=0)

def assembly_axis_rotation(axis, degrees):
    """Rotation matrix about a world axis, specified by index or direction."""
    a = np.eye(3)[int(axis)] if np.ndim(axis) == 0 else np.asarray(axis, float)
    a = a / np.linalg.norm(a)
    phi = math.radians(degrees)
    cross = np.array([[0, -a[2], a[1]], [a[2], 0, -a[0]], [-a[1], a[0], 0]])
    return math.cos(phi)*np.eye(3) + math.sin(phi)*cross + (1 - math.cos(phi))*np.outer(a, a)

def assembly_rotate_about(component, base, centre, axis, degrees):
    """Placement of a component rotated about a world axis through `centre`, starting from the
    placement `base` ({"position", "rotation"})."""
    turn = assembly_axis_rotation(axis, degrees)
    pivot = np.asarray(component["pivot"], float)
    centre = np.asarray(centre, float)
    component["rotation"] = [float(x) for x in
                             _import_euler_angles(turn @ _import_rotation_matrix(base["rotation"]))]
    component["position"] = [float(x) for x in
                             turn @ (pivot + np.asarray(base["position"], float) - centre)
                             + centre - pivot]

def assembly_add_component(assembly, name, kind, bodies, **fields):
    """Append a component, placed to the right of the existing ones so parts do not overlap."""
    names = {component["name"] for component in assembly["components"]}
    unique, number = name, 2
    while unique in names:
        unique = f"{name} ({number})"; number += 1
    filled = [body["vertices"] for body in bodies if len(body["vertices"])]
    pivot = (np.min([v.min(0) for v in filled], axis=0) +
             np.max([v.max(0) for v in filled], axis=0)) / 2 if filled else np.zeros(3)
    component = {"name": unique, "kind": kind, "visible": True, "bodies": bodies,
                 "position": [0.0, 0.0, 0.0], "rotation": [0.0, 0.0, 0.0],
                 "pivot": [float(x) for x in pivot]}
    component.update(fields)
    own = assembly_bounds(component)
    others = [box for box in map(assembly_bounds, assembly["components"]) if box is not None]
    if own is not None and others:
        component["position"][0] = float(
            max(box[1][0] for box in others) + ASSEMBLY_GAP_MM - own[0][0])
    assembly["components"].append(component)
    return component

def assembly_component(assembly, name):
    return next((c for c in assembly["components"] if c["name"] == name), None)

def assembly_find_source(name, objects):
    return next((o for o in objects if o.get("name") == name and _assembly_is_solid(o)), None)

def assembly_add_split_components(assembly, first, groups, make):
    """Components for split parts: placed exactly like `first` (same position, rotation and
    pivot), so the parts still fit together. make(group) -> (name, bodies, fields)."""
    added = []
    for group in groups:
        name, bodies, fields = make(group)
        component = assembly_add_component(assembly, name, first["kind"], bodies, **fields)
        for key in ("position", "rotation", "pivot"):
            component[key] = list(first[key])
        added.append(component)
    return added

def assembly_add_project_components(assembly, root, objects):
    """The components of a parent solid: one, or one per split part (assembly_project_groups)."""
    groups = assembly_project_groups(root, objects)
    def make(group):
        return (assembly_group_name(root["name"], groups, group), group["bodies"],
                {"source_name": root["name"], "source_piece": list(group["key"]),
                 "signature": group["signature"]})
    name, bodies, fields = make(groups[0])
    first = assembly_add_component(assembly, name, "project", bodies, **fields)
    return [first] + assembly_add_split_components(assembly, first, groups[1:], make)

def assembly_add_project_component(assembly, root, objects):
    return assembly_add_project_components(assembly, root, objects)[0]

def assembly_file_stamp(path):
    stat = os.stat(path)
    return [int(stat.st_size), int(stat.st_mtime_ns)]

def _read_wavefront_obj(path):
    """Vertices and triangles of a Wavefront OBJ (polygons are fan-triangulated)."""
    vertices, triangles = [], []
    with open(path, "r", encoding="utf-8", errors="replace") as stream:
        for number, line in enumerate(stream, 1):
            fields = line.split()
            if not fields:
                continue
            if fields[0] == "v":
                if len(fields) < 4:
                    raise ValueError(f"Malformed vertex in line {number} of the OBJ file")
                vertices.append(tuple(float(value) for value in fields[1:4]))
            elif fields[0] == "f":
                corners = []
                for token in fields[1:]:
                    index = int(token.split("/")[0])
                    corners.append(index - 1 if index > 0 else len(vertices) + index)
                triangles += [(corners[0], corners[k], corners[k + 1])
                              for k in range(1, len(corners) - 1)]
    if not vertices or not triangles:
        raise ValueError("The OBJ file contains no triangles")
    return vertices, triangles

def assembly_is_project_file(path):
    """True for a SimpleCAD project (these also use the .obj extension)."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            head = stream.read(512)
    except OSError:
        return False
    return head.lstrip().startswith("{") and PROJECT_FORMAT in head

def assembly_read_file(path, progress=None):
    """(vertices, triangles, faces) of a STEP / STL / OBJ mesh file, bounding box centred at the origin."""
    lower = path.lower()
    faces = []
    if lower.endswith(".stl"):
        vertices, triangles = _read_stl_mesh(path, progress)
    elif lower.endswith((".step", ".stp")):
        vertices, triangles, faces = _read_step_mesh(path, progress)
    elif lower.endswith(".obj"):
        vertices, triangles = _read_wavefront_obj(path)
    else:
        raise ValueError("Choose a .step, .stp, .stl or .obj file")
    vertices, triangles = _center_mesh(vertices, triangles)
    return vertices, triangles, _mesh_face_records(faces, triangles)

def assembly_add_file_components(assembly, path, window=None, progress=None):
    """Components for one file: a mesh file gives one, a SimpleCAD project file (.obj) one per
    parent solid (read through `window`, which rebuilds the project's solids)."""
    stamp = assembly_file_stamp(path)
    if path.lower().endswith(".obj") and assembly_is_project_file(path):
        if window is None:
            raise ValueError("A SimpleCAD project can only be imported by the application")
        specs = window._read_project_solids(path)
        if not specs:
            raise ValueError("The project contains no parent solids")
        added = []
        for spec in specs:
            component = assembly_add_component(
                assembly, spec["name"], "file", spec["bodies"], path=path, file_stamp=stamp,
                file_root=spec["root"], file_piece=list(spec["key"]))
            first = next((c for c in added if c.get("file_root") == spec["root"]), None)
            if first is not None:          # a split part: placed like the main part
                for key in ("position", "rotation", "pivot"):
                    component[key] = list(first[key])
            added.append(component)
        return added
    vertices, triangles, faces = assembly_read_file(path, progress)
    stem = os.path.splitext(os.path.basename(path))[0] or "Imported"
    return [assembly_add_component(assembly, stem, "file",
                                   [assembly_body(stem, vertices, triangles, faces)],
                                   path=path, file_stamp=stamp)]

def assembly_add_file_component(assembly, path, progress=None):
    return assembly_add_file_components(assembly, path, None, progress)[0]

def assembly_component_status(component, objects, assembly=None):
    """"ok", "outdated" (the source changed after the snapshot, or - with `assembly` - it was
    split and a split part has no component yet) or "missing" (source gone)."""
    if component["kind"] == "project":
        root = assembly_find_source(component.get("source_name"), objects)
        if root is None:
            return "missing"
        groups = assembly_project_groups(root, objects)
        key = tuple(component.get("source_piece") or ())
        group = next((g for g in groups if g["key"] == key), None)
        if group is None:
            return "outdated" if not key else "missing"
        if assembly is not None and len(groups) > 1:
            present = {tuple(c.get("source_piece") or ()) for c in assembly["components"]
                       if c.get("kind") == "project" and
                       c.get("source_name") == component.get("source_name")}
            if any(g["key"] not in present for g in groups):
                return "outdated"          # Update adds the missing split parts
        return "ok" if group["signature"] == component.get("signature") else "outdated"
    path = component.get("path")
    try:
        stamp = assembly_file_stamp(path) if path else None
    except OSError:
        stamp = None
    if stamp is None:
        return "missing"
    return "ok" if stamp == component.get("file_stamp") else "outdated"

def assembly_keep_appearance(old_bodies, new_bodies):
    """Update re-reads only the shape: the colour and transparency the bodies have in the
    assembly stay. A new body takes them from the old body of the same name (or, if the names
    changed, the one at the same place when the count is the same); a body that is new (e.g. an
    extrusion added to the source since) gets the object's colour / transparency when all its
    old bodies had the same one — the Assembly window sets both for the whole object."""
    if not old_bodies:
        return
    by_name = {}
    for body in old_bodies:
        by_name.setdefault(body.get("name"), body)
    by_index = len(old_bodies) == len(new_bodies)
    opacities = {round(float(body.get("opacity", 1.0)), 6) for body in old_bodies}
    common = float(old_bodies[0].get("opacity", 1.0)) if len(opacities) == 1 else None
    colors = {tuple(round(float(c), 6) for c in list(body.get("color", DEFAULT_SOLID_COLOR))[:3])
              for body in old_bodies}
    common_color = [float(c) for c in list(old_bodies[0].get("color", DEFAULT_SOLID_COLOR))[:3]] \
        if len(colors) == 1 else None
    for index, body in enumerate(new_bodies):
        old = by_name.get(body.get("name"))
        if old is None and by_index:
            old = old_bodies[index]
        if old is not None:
            body["color"] = [float(c) for c in list(old.get("color", body["color"]))[:3]]
            body["opacity"] = float(old.get("opacity", body["opacity"]))
        else:
            if common is not None:
                body["opacity"] = common
            if common_color is not None:
                body["color"] = list(common_color)

def assembly_refresh_component(component, objects, window=None):
    """Re-read the source of a component; position, rotation, applied cuts and the colour /
    transparency of its bodies stay (only the shape changes). Returns [(group, make)] of split
    parts the assembly has no component for yet (the caller adds them with
    assembly_add_split_components)."""
    shown = list(component.get("bodies") or [])
    names = {body.get("name") for body in shown}
    # bodies a cut removed completely are only in the uncut snapshot
    old = shown + [body for body in component.get("uncut_bodies") or []
                   if body.get("name") not in names]
    new_parts = _assembly_refresh_source(component, objects, window)
    assembly_keep_appearance(old, component["bodies"])
    for group, _make in new_parts:              # new split parts look like the object
        assembly_keep_appearance(old, group.get("bodies") or [])
    if component.get("cuts"):
        component["uncut_bodies"] = component["bodies"]       # cut again when the code improves
        component["bodies"] = assembly_apply_cuts(component["bodies"], component["cuts"])
    else:
        component.pop("uncut_bodies", None)
    return new_parts

def _assembly_refresh_source(component, objects, window=None):
    if component["kind"] == "project":
        root = assembly_find_source(component.get("source_name"), objects)
        if root is None:
            raise ValueError(f"'{component.get('source_name')}' no longer exists in the project")
        groups = assembly_project_groups(root, objects)
        key = tuple(component.get("source_piece") or ())
        group = next((g for g in groups if g["key"] == key), None)
        if group is None:
            if key:
                raise ValueError("this split part no longer exists (the Cut Surface no longer "
                                 "splits the object)")
            group = groups[0]
        component["bodies"] = group["bodies"]
        component["signature"] = group["signature"]
        component["source_piece"] = list(group["key"])
        def make(new_group):
            return (assembly_group_name(root["name"], groups, new_group), new_group["bodies"],
                    {"source_name": root["name"], "source_piece": list(new_group["key"]),
                     "signature": new_group["signature"]})
        return [(g, make) for g in groups if g is not group]
    path = component.get("path")
    if not path or not os.path.isfile(path):
        raise ValueError(f"the file is missing: {path}")
    if component.get("file_root") is not None:
        if window is None:
            raise ValueError("A SimpleCAD project can only be updated by the application")
        key = tuple(component.get("file_piece") or ())
        specs = [s for s in window._read_project_solids(path) if s["root"] == component["file_root"]]
        spec = next((s for s in specs if s["key"] == key), None)
        if spec is None and not key and specs:
            spec = specs[0]
        if spec is None:
            raise ValueError(f"'{component['file_root']}' is no longer in {os.path.basename(path)}")
        component["bodies"] = spec["bodies"]
        component["file_piece"] = list(spec["key"])
        component["file_stamp"] = assembly_file_stamp(path)
        stamp = component["file_stamp"]
        def make(new_spec):
            return (new_spec["name"], new_spec["bodies"],
                    {"path": path, "file_stamp": stamp, "file_root": new_spec["root"],
                     "file_piece": list(new_spec["key"])})
        return [(s, make) for s in specs if s is not spec]
    else:
        vertices, triangles, faces = assembly_read_file(path)
        stem = os.path.splitext(os.path.basename(path))[0] or "Imported"
        component["bodies"] = [assembly_body(stem, vertices, triangles, faces)]
    component["file_stamp"] = assembly_file_stamp(path)
    return []

def assembly_reference_point(item):
    """(world point, description) a picked corner / edge / surface / object centre stands for."""
    if item["kind"] == "face":
        return np.asarray(item["P"], float), "surface"
    if item["kind"] == "point":
        return np.asarray(item["P"], float), item.get("ref", "corner")
    fit = _fit_circle(item["P"], item["closed"])
    if fit is not None:
        return np.asarray(fit[0], float), "hole centre" if item["closed"] else "arc centre"
    if item["axis"] is not None:
        start, end, _ = item["axis"]
        return (np.asarray(start, float) + np.asarray(end, float)) / 2, "edge midpoint"
    return np.asarray(item["label"], float), "edge midpoint"

def assembly_reference_axis(item):
    """Unit normal of a picked closed circular rim, or None for other references."""
    if item["kind"] != "edge" or not item.get("closed") or \
            _fit_circle(item["P"], True) is None:
        return None
    points = np.asarray(item["P"], float)
    if len(points) > 1 and float(np.linalg.norm(points[0] - points[-1])) < 1e-9:
        points = points[:-1]
    _, singular, vectors = np.linalg.svd(points - points.mean(0), full_matrices=False)
    if len(singular) < 3 or singular[1] < 1e-9 or singular[2] > 1e-6 * singular[0]:
        return None
    axis = vectors[-1]
    return axis / np.linalg.norm(axis)

# alignment constraints ---------------------------------------------------------
def assembly_add_constraint(assembly, moving, target, moving_point, moving_label,
                            target_point, target_label):
    """Coincident constraint: `moving_point` of the moving part follows `target_point` of the
    target part. Both world points are stored in the coordinates of their own part."""
    constraint = {
        "kind": "coincident", "enabled": True, "moving": moving["name"], "target": target["name"],
        "moving_ref": {"point": [float(x) for x in assembly_local_point(moving, moving_point)],
                       "label": moving_label},
        "target_ref": {"point": [float(x) for x in assembly_local_point(target, target_point)],
                       "label": target_label}}
    assembly["constraints"].append(constraint)
    return constraint

def assembly_add_mate(assembly, moving, target, moving_point, moving_normal,
                      target_point, target_normal, moving_label="surface", target_label="surface"):
    """Mate two planar faces or circular axes, keeping the moving reference aligned to target."""
    moving_normal = np.asarray(moving_normal, float) / np.linalg.norm(moving_normal)
    target_normal = np.asarray(target_normal, float) / np.linalg.norm(target_normal)
    constraint = {
        "kind": "mate", "enabled": True, "moving": moving["name"], "target": target["name"],
        "opposed": bool(moving_normal @ target_normal < 0.0),
        "moving_ref": {"point": [float(x) for x in assembly_local_point(moving, moving_point)],
                       "normal": [float(x) for x in assembly_local_direction(moving, moving_normal)],
                       "label": moving_label},
        "target_ref": {"point": [float(x) for x in assembly_local_point(target, target_point)],
                       "normal": [float(x) for x in assembly_local_direction(target, target_normal)],
                       "label": target_label}}
    assembly["constraints"].append(constraint)
    return constraint

def assembly_constraint_gap(assembly, constraint):
    """World vector that would close the constraint: from the moving to the target reference
    point, or for a surface mate the offset between the two planes along the target normal.
    None if a part is gone."""
    moving = assembly_component(assembly, constraint["moving"])
    target = assembly_component(assembly, constraint["target"])
    if moving is None or target is None:
        return None
    gap = assembly_world_point(target, constraint["target_ref"]["point"]) \
        - assembly_world_point(moving, constraint["moving_ref"]["point"])
    return gap

def _assembly_mate_normals(assembly, constraint):
    """(current moving normal, wanted moving normal) of a surface mate in world coordinates."""
    moving = assembly_component(assembly, constraint["moving"])
    target = assembly_component(assembly, constraint["target"])
    current = assembly_world_direction(moving, constraint["moving_ref"]["normal"])
    wanted = assembly_world_direction(target, constraint["target_ref"]["normal"])
    return current, (-wanted if constraint.get("opposed", True) else wanted)

def assembly_constraint_angle(assembly, constraint):
    """Angle in degrees by which a surface mate is turned out of place (0 for point constraints)."""
    if assembly_constraint_gap(assembly, constraint) is None:
        return None
    if constraint["kind"] != "mate":
        return 0.0
    current, wanted = _assembly_mate_normals(assembly, constraint)
    return math.degrees(math.acos(max(-1.0, min(1.0, float(current @ wanted)))))

def _assembly_rotation_between(a, b):
    """Smallest rotation matrix taking the unit vector a onto the unit vector b."""
    axis, cosine = np.cross(a, b), float(a @ b)
    if cosine > 1.0 - 1e-12:
        return np.eye(3)
    if cosine < -1.0 + 1e-12:
        helper = np.array([1.0, 0.0, 0.0]) if abs(a[0]) < 0.9 else np.array([0.0, 1.0, 0.0])
        side = np.cross(a, helper); side /= np.linalg.norm(side)
        return 2.0 * np.outer(side, side) - np.eye(3)
    cross = np.array([[0, -axis[2], axis[1]], [axis[2], 0, -axis[0]], [-axis[1], axis[0], 0]])
    return np.eye(3) + cross + cross @ cross / (1.0 + cosine)

def assembly_enforce_constraint(assembly, constraint):
    """Move the moving part so the constraint holds (a surface mate also turns it so the two
    surfaces are parallel); True if it moved."""
    gap = assembly_constraint_gap(assembly, constraint)
    if gap is None:
        return False
    moving = assembly_component(assembly, constraint["moving"])
    moved = False
    if constraint["kind"] == "mate":
        current, wanted = _assembly_mate_normals(assembly, constraint)
        if float(np.linalg.norm(np.cross(current, wanted))) > _ASSEMBLY_TOLERANCE or \
                float(current @ wanted) < 0.0:
            local = np.asarray(constraint["moving_ref"]["point"], float)
            anchor = assembly_world_point(moving, local)       # the surface turns about its centre
            turned = _assembly_rotation_between(current, wanted) @ _import_rotation_matrix(
                moving["rotation"])
            pivot = np.asarray(moving["pivot"], float)
            moving["rotation"] = [float(x) for x in _import_euler_angles(turned)]
            moving["position"] = [float(x) for x in anchor - pivot - turned @ (local - pivot)]
            moved = True
            gap = assembly_constraint_gap(assembly, constraint)
    if float(np.linalg.norm(gap)) >= _ASSEMBLY_TOLERANCE:
        moving["position"] = [float(p + d) for p, d in zip(moving["position"], gap)]
        moved = True
    return moved

def assembly_solve(assembly, changed=None):
    """Enforce enabled constraints and return the names of the parts that moved."""
    constraints = [c for c in assembly["constraints"] if c.get("enabled", True)]
    moved = set()
    if changed is None:
        for _ in range(len(constraints) + 1):
            progress = False
            for constraint in constraints:
                if assembly_enforce_constraint(assembly, constraint):
                    moved.add(constraint["moving"]); progress = True
            if not progress:
                break
        return moved
    frontier, done = set(changed), set()
    while frontier:
        following = set()
        for index, constraint in enumerate(constraints):
            if index in done or constraint["target"] not in frontier:
                continue
            done.add(index)
            if assembly_enforce_constraint(assembly, constraint):
                moved.add(constraint["moving"]); following.add(constraint["moving"])
        frontier = following
    return moved

def assembly_explosion_direction(assembly, component):
    """Direction away from the adjacent part for the first enabled alignment of a component."""
    for constraint in assembly["constraints"]:
        if not constraint.get("enabled", True):
            continue
        moving = assembly_component(assembly, constraint["moving"])
        target = assembly_component(assembly, constraint["target"])
        if moving is None or target is None or (component is not moving and component is not target):
            continue
        if constraint["kind"] == "mate":
            direction = assembly_world_direction(target, constraint["target_ref"]["normal"])
        else:
            moving_bounds, target_bounds = assembly_bounds(moving), assembly_bounds(target)
            if moving_bounds is None or target_bounds is None:
                continue
            moving_centre = (moving_bounds[0] + moving_bounds[1]) / 2
            target_centre = (target_bounds[0] + target_bounds[1]) / 2
            direction = moving_centre - target_centre
            if float(np.linalg.norm(direction)) < _ASSEMBLY_TOLERANCE:
                direction = assembly_world_direction(moving, (0.0, 0.0, 1.0))
            axis = int(np.argmax(np.abs(direction)))
            direction = np.eye(3)[axis] * (1.0 if direction[axis] >= 0.0 else -1.0)
        if component is target:
            direction = -direction
        length = float(np.linalg.norm(direction))
        if length > _ASSEMBLY_TOLERANCE:
            return direction / length
    return None

def assembly_explosion_handle_origin(component, direction, clearance=2.0):
    """Point outside the component at the farthest extent along an explosion direction."""
    vertices = [assembly_world_vertices(component, body["vertices"])
                for body in component["bodies"] if len(body["vertices"])]
    if not vertices:
        return None
    vertices = np.concatenate(vertices, axis=0)
    direction = np.asarray(direction, float)
    point = vertices[int(np.argmax(vertices @ direction))]
    return point + direction * clearance

def assembly_active_section(assembly):
    """The assembly's Cut Surface {position, rotation, flip, size, active} while it is switched
    on, else None."""
    section = assembly.get("section")
    return section if section and section.get("active") else None

def assembly_cut_body(component, body, section, offset=None):
    """(world vertices, triangles, faces) of an assembly body, cut by `section` (None = whole;
    with `split` both sides stay). `offset` moves the body first (exploded view)."""
    world = assembly_world_vertices(component, body["vertices"])
    if offset is not None:
        world = world + offset
    vertices = [tuple(point) for point in world.tolist()]
    faces = assembly_world_faces(component, body["faces"], offset)
    if section is None or not body["triangles"]:
        return vertices, body["triangles"], faces
    mesh = (vertices, body["triangles"], faces)
    kept = apply_cut_surface(mesh, section)
    if not section.get("split"):
        return kept
    other = apply_cut_surface(mesh, dict(section, flip=not section.get("flip")))
    return join_mesh_pieces([piece for piece in (kept, other) if len(piece[1])])

def assembly_plane_to_local(component, origin, normal):
    """A world plane (origin, normal) in the component's own (snapshot) coordinates."""
    rotation = _import_rotation_matrix(component["rotation"])
    pivot = np.asarray(component["pivot"], float)
    local_origin = (np.asarray(origin, float) - pivot -
                    np.asarray(component["position"], float)) @ rotation + pivot
    return local_origin, np.asarray(normal, float) @ rotation

def assembly_apply_cuts(bodies, cuts):
    """The bodies cut by the planes {origin, normal} (local coordinates; the +normal side is
    removed). Bodies that are cut away completely are left out; the cut faces are planar
    (they can be used for alignments)."""
    out = []
    for body in bodies:
        mesh = (body["vertices"], body["triangles"], body["faces"])
        for cut in cuts:
            mesh = cut_mesh_by_plane(mesh, cut["origin"], cut["normal"])
        if not len(mesh[1]):
            continue
        faces = [dict(face, planar=True) if face.get("section") is not None else face
                 for face in mesh[2]]
        out.append(assembly_body(body["name"], mesh[0], mesh[1], faces, body["color"],
                                 body["opacity"], body.get("fused", False), body.get("material"),
                                 body.get("gear")))
    return out

# Version of the cutting code the stored cut bodies were made with. Assemblies saved with an
# older one are cut again from their uncut geometry when loaded (better section faces).
ASSEMBLY_CUT_VERSION = 2

def assembly_recut(component, previous=None):
    """Cut the component's uncut bodies by its cuts again (current cutting code). Colour,
    opacity and material of the bodies it had (`previous`, same order) are kept."""
    uncut = component.get("uncut_bodies")
    if not uncut or not component.get("cuts"):
        return False
    bodies = assembly_apply_cuts(uncut, component["cuts"])
    previous = previous if previous is not None else component.get("bodies") or []
    if len(previous) == len(bodies):
        for body, old in zip(bodies, previous):
            if body["name"] == old["name"]:
                for key in ("color", "opacity", "material", "fused"):
                    if key in old:
                        body[key] = old[key]
    component["bodies"] = bodies
    return True

def assembly_upgrade_legacy_cuts(assembly, objects, window=None):
    """Components cut in an assembly saved before the uncut geometry was stored: their cut
    faces may come from older cutting code. If their source is unchanged, read it again as the
    uncut geometry and cut it anew. Returns the names of the upgraded components."""
    upgraded = []
    for component in assembly["components"]:
        if not component.get("cuts") or component.get("uncut_bodies"):
            continue
        try:
            if assembly_component_status(component, objects) != "ok":
                continue                          # changed / missing source: Update does it
            previous = component["bodies"]
            work = dict(component)
            _assembly_refresh_source(work, objects, window)
        except (OSError, ValueError, KeyError, TypeError, IndexError) as ex:
            _dbg(f"assembly: cannot upgrade the cut of {component.get('name')}: {ex}")
            continue
        component["uncut_bodies"] = work["bodies"]
        assembly_recut(component, previous)
        upgraded.append(component["name"])
    return upgraded

def assembly_export_mesh(assembly, components=None):
    """(vertices, triangles) in assembly coordinates of the given components (default: all
    visible parts), or None. An active Cut Surface cuts them as in the view: only the remaining
    part is exported."""
    section = assembly_active_section(assembly)
    vertices, triangles = [], []
    chosen = None if components is None else {id(component) for component in components}
    for component in assembly["components"]:
        if (not component["visible"]) if chosen is None else id(component) not in chosen:
            continue
        for body in component["bodies"]:
            if body.get("fused") or not body["triangles"]:
                continue
            body_vertices, body_triangles, _ = assembly_cut_body(component, body, section)
            offset = len(vertices)
            vertices += list(body_vertices)
            triangles += [(a + offset, b + offset, c + offset) for a, b, c in body_triangles]
    return (vertices, triangles) if triangles else None

# fits and clearances (Technical Drawing Phase 5) --------------------------------
def assembly_component_cylinders(component):
    """Cylindrical surfaces of a placed component (world coordinates), from coaxial circular
    rims of its meshes: [{"axis", "point", "radius", "low", "high", "inner" (a bore)}]."""
    cylinders = []
    for body in component["bodies"]:
        if body.get("fused") or not body["triangles"]:
            continue
        world = assembly_world_vertices(component, body["vertices"])
        V, T = _drawing_prepare_mesh(world.tolist(), body["triangles"])
        topology = _drawing_topology(V, T, threads=[])
        tolerance = max(topology["span"] * 1e-4, 1e-6)
        rims = []
        for circle in topology["circles"]:
            if not circle.get("edges"):
                continue
            axis = np.asarray(circle["axis"], dtype=float)
            axis = axis / max(float(np.linalg.norm(axis)), 1e-12)
            info = _drawing_rim_info(topology, dict(circle, axis=axis))
            rims.append((np.asarray(circle["center"], dtype=float), axis, float(circle["radius"]),
                         bool(info and info["inner"])))
        used = set()
        for i, (centre, axis, radius, inner) in enumerate(rims):
            if i in used:
                continue
            group = [i]
            for j in range(i + 1, len(rims)):
                other = rims[j]
                offset = other[0] - centre
                if j not in used and abs(float(other[1] @ axis)) > 0.9999 and \
                        abs(other[2] - radius) <= max(1e-3 * radius, tolerance) and \
                        float(np.linalg.norm(offset - (offset @ axis) * axis)) <= max(1e-3 * radius, tolerance):
                    group.append(j)
            if len(group) < 2:
                continue
            used.update(group)
            ts = [float((rims[k][0] - centre) @ axis) for k in group]
            cylinders.append({"axis": axis, "point": centre, "radius": radius, "low": min(ts),
                              "high": max(ts), "inner": any(rims[k][3] for k in group)})
    return cylinders


def assembly_fit_pairs(assembly):
    """Shaft / bore pairs of different visible components: coaxial cylinders of about the same
    diameter (one a bore, one a shaft) that overlap along the axis."""
    components = [c for c in assembly["components"] if c.get("visible", True)]
    cylinders = {id(c): assembly_component_cylinders(c) for c in components}
    pairs, seen = [], set()
    for shaft_part in components:
        for hole_part in components:
            if shaft_part is hole_part:
                continue
            for shaft in cylinders[id(shaft_part)]:
                if shaft["inner"]:
                    continue
                for hole in cylinders[id(hole_part)]:
                    if not hole["inner"]:
                        continue
                    axis = shaft["axis"]
                    offset = hole["point"] - shaft["point"]
                    if abs(float(hole["axis"] @ axis)) < 0.9995 or \
                            float(np.linalg.norm(offset - (offset @ axis) * axis)) > 0.02 * hole["radius"] + 0.05 or \
                            abs(hole["radius"] - shaft["radius"]) > max(0.02 * hole["radius"], 0.05):
                        continue
                    sign = 1.0 if float(hole["axis"] @ axis) > 0 else -1.0
                    base = float(offset @ axis)
                    h0, h1 = sorted((base + sign * hole["low"], base + sign * hole["high"]))
                    if min(shaft["high"], h1) - max(shaft["low"], h0) <= 1e-6:
                        continue
                    key = (shaft_part["name"], hole_part["name"], round(2 * hole["radius"], 2))
                    if key in seen:
                        continue
                    seen.add(key)
                    pairs.append({"shaft_part": shaft_part, "hole_part": hole_part,
                                  "shaft_d": 2 * shaft["radius"], "hole_d": 2 * hole["radius"],
                                  "axis": axis, "point": shaft["point"]})
    return pairs


def assembly_fit_result(hole_d, hole_dev, shaft_d, shaft_dev):
    """Clearance range and kind of a shaft / bore pair from their nominal sizes and deviations."""
    largest = (hole_d + hole_dev[0]) - (shaft_d + shaft_dev[1])
    smallest = (hole_d + hole_dev[1]) - (shaft_d + shaft_dev[0])
    kind = "clearance" if smallest >= 0 else "interference" if largest <= 0 else "transition"
    return {"max": largest, "min": smallest, "kind": kind}


def _point_triangle_distance(points, a, b, c):
    """Distances from points (n, 3) to triangles (m, 3 each): (n, m) (Ericson, vectorised)."""
    p = points[:, None, :]
    ab, ac, ap = b - a, c - a, p - a
    d1, d2 = np.einsum("ijk,jk->ij", ap, ab), np.einsum("ijk,jk->ij", ap, ac)
    bp, cp = p - b, p - c
    d3, d4 = np.einsum("ijk,jk->ij", bp, ab), np.einsum("ijk,jk->ij", bp, ac)
    d5, d6 = np.einsum("ijk,jk->ij", cp, ab), np.einsum("ijk,jk->ij", cp, ac)
    va, vb, vc = d3 * d6 - d5 * d4, d5 * d2 - d1 * d6, d1 * d4 - d3 * d2
    denominator = va + vb + vc
    denominator = np.where(np.abs(denominator) < 1e-30, 1e-30, denominator)
    v, w = vb / denominator, vc / denominator
    closest = a + v[..., None] * ab + w[..., None] * ac                          # inside the face
    # regions outside: vertices and edges
    with np.errstate(divide="ignore", invalid="ignore"):
        t_ab = np.clip(d1 / np.where(d1 - d3 == 0, 1e-30, d1 - d3), 0, 1)
        t_ac = np.clip(d2 / np.where(d2 - d6 == 0, 1e-30, d2 - d6), 0, 1)
        t_bc = np.clip((d4 - d3) / np.where((d4 - d3) + (d5 - d6) == 0, 1e-30, (d4 - d3) + (d5 - d6)), 0, 1)
    on_ab = a + t_ab[..., None] * ab
    on_ac = a + t_ac[..., None] * ac
    on_bc = b + t_bc[..., None] * (c - b)
    outside = (va <= 0) | (vb <= 0) | (vc <= 0)
    candidates = np.stack([closest, on_ab, on_ac, on_bc,
                           np.broadcast_to(a, closest.shape), np.broadcast_to(b, closest.shape),
                           np.broadcast_to(c, closest.shape)])
    distances = np.linalg.norm(candidates - p[None], axis=-1)
    inside_face = distances[0]
    edge_best = distances[1:].min(axis=0)
    return np.where(outside, edge_best, np.minimum(inside_face, edge_best))


def assembly_world_mesh(component, offset=None):
    """(vertices, triangles) of a component's shown bodies in assembly coordinates."""
    vertices, triangles = [], []
    for body in component["bodies"]:
        if body.get("fused") or not body["triangles"]:
            continue
        world = assembly_world_vertices(component, body["vertices"])
        if offset is not None:
            world = world + offset
        triangles += [(a + len(vertices), b + len(vertices), c + len(vertices)) for a, b, c in body["triangles"]]
        vertices += world.tolist()
    return np.asarray(vertices, dtype=float).reshape(-1, 3), np.asarray(triangles, dtype=np.int64).reshape(-1, 3)


def assembly_min_distance(first, second, reach=5.0, samples=2500):
    """Smallest distance between two components' meshes (closer than `reach`, else None) and
    whether they overlap (a point of one lies inside the other). Vertices of one mesh near the
    other are tested against its nearby triangles, both ways."""
    meshes = [assembly_world_mesh(first), assembly_world_mesh(second)]
    if not all(len(T) for _V, T in meshes):
        return None, False
    lows = [V[np.unique(T)].min(axis=0) for V, T in meshes]
    highs = [V[np.unique(T)].max(axis=0) for V, T in meshes]
    if np.any(lows[0] > highs[1] + reach) or np.any(lows[1] > highs[0] + reach):
        return None, False
    best, overlap = None, False
    for (P, PT), (Q, QT), q_low, q_high in ((meshes[0], meshes[1], lows[1], highs[1]),
                                             (meshes[1], meshes[0], lows[0], highs[0])):
        points = P[np.unique(PT)]
        near = np.all((points >= q_low - reach) & (points <= q_high + reach), axis=1)
        points = points[near]
        if not len(points):
            continue
        if len(points) > samples:
            points = points[np.linspace(0, len(points) - 1, samples).astype(int)]
        corners = Q[QT]
        box_low, box_high = points.min(axis=0) - reach, points.max(axis=0) + reach
        keep = np.all((corners.max(axis=1) >= box_low) & (corners.min(axis=1) <= box_high), axis=1)
        corners = corners[keep]
        if not len(corners):
            continue
        a, b, c = corners[:, 0], corners[:, 1], corners[:, 2]
        nearest = np.full(len(points), np.inf)
        chunk = max(1, 200_000 // max(len(corners), 1))          # about 35 MB of work arrays
        for start in range(0, len(points), chunk):
            block = _point_triangle_distance(points[start:start + chunk], a, b, c)
            nearest[start:start + chunk] = block.min(axis=1)
        distance = float(nearest.min())
        best = distance if best is None else min(best, distance)
        # overlap: points clearly away from the other surface (not just touching it, where the
        # facets of two round parts cross) that lie inside the other mesh
        clear = np.argsort(nearest)
        clear = clear[nearest[clear] > 0.02]
        probes = list(clear[:6]) + list(clear[np.linspace(0, len(clear) - 1, 6).astype(int)]) \
            if len(clear) else []
        for index in dict.fromkeys(probes):
            if _drawing_point_inside(Q, QT, points[index]):
                overlap = True
                break
    if best is not None and best > reach:
        best = None
    return best, overlap


def assembly_part_drawings(source_name, objects):
    """Sheets of the project's technical drawings that show the solid `source_name`, with the
    general tolerance of their drawing: [(sheet options, general tolerance text)]."""
    sheets = []
    for entry in objects:
        if entry.get("type") != "technical_drawing":
            continue
        options = entry.get("options") or {}
        for sheet in drawing_sheet_options(options):
            source = sheet.get("source") if "source" in sheet else \
                ({"kind": "project", "name": entry["parent"]["name"]} if entry.get("parent") else None)
            if source and source.get("kind") == "project" and source.get("name") == source_name:
                sheets.append((sheet, options.get("tolerance") or "ISO 2768-m"))
    return sheets


def assembly_part_tolerance(component, diameter, objects):
    """(upper, lower) deviation of a diameter of a component and where it comes from: the
    bearing's own tolerance (ISO 492), a toleranced dimension of the part's drawing, else the
    drawing's general tolerance (ISO 2768-m if the part has no drawing)."""
    source = assembly_find_source(component.get("source_name"), objects) \
        if component.get("kind") == "project" else None
    bearing = (source or {}).get("bearing")
    if bearing:
        bore, outside = bearing_ring_deviations(bearing)
        if abs(diameter - bearing["d"]) <= 0.05:
            return bore, f"bearing {bearing['name']} bore"
        if abs(diameter - bearing["D"]) <= 0.05:
            return outside, f"bearing {bearing['name']} outside"
    general = "ISO 2768-m"
    if source is not None:
        for sheet, sheet_general in assembly_part_drawings(source["name"], objects):
            general = sheet_general
            for dimension in sheet.get("dimensions") or []:
                if dimension.get("type", "length") in ("diameter", "length") and dimension.get("tol") and \
                        abs(abs(float(dimension.get("value", 0.0))) - diameter) <= 0.02:
                    tolerance = tol_normalize_tolerance(dimension["tol"])
                    label = tolerance.get("fit") if tolerance and tolerance["mode"] == "fit" else \
                        tol_tolerance_summary(diameter, tolerance)
                    return tol_dimension_deviations(diameter, tolerance), f"drawing: {label}"
    upper, lower = tol_dimension_deviations(diameter, None, general)
    return (upper, lower), f"general ({general})"


class AssemblyCheckDialog(QDialog):
    """Fits and clearances of the assembly (Phase 5). Fits: every shaft in a bore of another
    part with the tolerances of both (bearing data, the parts' drawings, else general
    tolerances): fit type and the clearance range. Clearances: the smallest gap between parts at
    nominal size and with the worst general tolerances; pairs below the required gap or
    overlapping are marked, a click selects the part in the view."""

    def __init__(self, assembly_window):
        super().__init__(assembly_window)
        self.window_ = assembly_window
        self.setWindowTitle("Fits and clearances")
        self.resize(900, 560)
        layout = QVBoxLayout(self)
        tabs = QTabWidget()
        layout.addWidget(tabs, 1)
        fits_page = QWidget()
        fits_layout = QVBoxLayout(fits_page)
        self.fits = QTableWidget(0, 7)
        self.fits.setHorizontalHeaderLabels(["Shaft (part)", "Bore (part)", "Ø nominal", "Shaft tolerance",
                                             "Bore tolerance", "Clearance min … max", "Fit"])
        self.fits.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeToContents)
        self.fits.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.fits.cellClicked.connect(lambda row, _col: self._select_row(self._fit_rows, row))
        fits_layout.addWidget(self.fits)
        tabs.addTab(fits_page, "Fits")
        clear_page = QWidget()
        clear_layout = QVBoxLayout(clear_page)
        form = QFormLayout()
        self.required = QDoubleSpinBox()
        self.required.setRange(0.0, 100.0)
        self.required.setDecimals(2)
        self.required.setSuffix(" mm")
        self.required.setValue(0.5)
        self.required.setToolTip("Smallest gap moving or neighbouring parts must keep")
        self.reach = QDoubleSpinBox()
        self.reach.setRange(0.5, 100.0)
        self.reach.setValue(5.0)
        self.reach.setSuffix(" mm")
        self.reach.setToolTip("Only pairs closer than this are listed")
        form.addRow("Required gap:", self.required)
        form.addRow("Look up to:", self.reach)
        clear_layout.addLayout(form)
        run = QPushButton("Check clearances")
        run.clicked.connect(self._check_clearances)
        clear_layout.addWidget(run)
        self.clearances = QTableWidget(0, 5)
        self.clearances.setHorizontalHeaderLabels(["Part", "Part", "Gap (nominal)", "Gap (worst case)", "Result"])
        self.clearances.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeToContents)
        self.clearances.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.clearances.cellClicked.connect(lambda row, _col: self._select_row(self._clear_rows, row))
        clear_layout.addWidget(self.clearances, 1)
        tabs.addTab(clear_page, "Clearances")
        self.status = QLabel()
        self.status.setWordWrap(True)
        layout.addWidget(self.status)
        close = QDialogButtonBox(QDialogButtonBox.Close)
        close.rejected.connect(self.reject)
        layout.addWidget(close)
        self._fit_rows, self._clear_rows = [], []
        self._check_fits()

    def _objects(self):
        return self.window_._window.state.get("objects", [])

    def _select_row(self, rows, row):
        if 0 <= row < len(rows):
            first, second = rows[row]
            self.window_._select(first)
            self.window_.view.update()
            self.status.setText(f"Selected {first['name']} (with {second['name']})")

    @staticmethod
    def _item(text, bad=False):
        item = QTableWidgetItem(text)
        if bad:
            item.setForeground(QColor("#ff6b6b"))
        return item

    def _check_fits(self):
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            pairs = assembly_fit_pairs(self.window_.assembly)
        finally:
            QApplication.restoreOverrideCursor()
        objects = self._objects()
        self.fits.setRowCount(0)
        self._fit_rows = []
        for pair in pairs:
            shaft_dev, shaft_from = assembly_part_tolerance(pair["shaft_part"], round(pair["shaft_d"], 3), objects)
            hole_dev, hole_from = assembly_part_tolerance(pair["hole_part"], round(pair["hole_d"], 3), objects)
            result = assembly_fit_result(pair["hole_d"], hole_dev, pair["shaft_d"], shaft_dev)
            row = self.fits.rowCount()
            self.fits.insertRow(row)
            mm = lambda value: f"{value:+.3f}"
            values = (pair["shaft_part"]["name"], pair["hole_part"]["name"], f"{pair['hole_d']:.3f}",
                      f"{mm(shaft_dev[0])} / {mm(shaft_dev[1])}  ({shaft_from})",
                      f"{mm(hole_dev[0])} / {mm(hole_dev[1])}  ({hole_from})",
                      f"{result['min']:+.3f} … {result['max']:+.3f}", result["kind"])
            general = "general" in shaft_from or "general" in hole_from
            for column, value in enumerate(values):
                self.fits.setItem(row, column, self._item(value, column == 6 and general))
            self._fit_rows.append((pair["shaft_part"], pair["hole_part"]))
        self.status.setText(
            f"{len(pairs)} shaft / bore pair(s). Tolerances come from bearings, then from the parts' "
            "drawings (a toleranced diameter of the same size), else from the general tolerance "
            "(marked red: give these diameters a fit on the part's drawing)." if pairs else
            "No shaft / bore pairs found (coaxial cylinders of about the same diameter on two parts).")

    def _check_clearances(self):
        components = [c for c in self.window_.assembly["components"] if c.get("visible", True)]
        objects = self._objects()
        fitted = {(a["name"], b["name"]) for a, b in self._fit_rows} | \
            {(b["name"], a["name"]) for a, b in self._fit_rows}
        self.clearances.setRowCount(0)
        self._clear_rows = []
        failing = 0
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            for index, first in enumerate(components):
                for second in components[index + 1:]:
                    gap, overlap = assembly_min_distance(first, second, float(self.reach.value()))
                    if gap is None:
                        continue
                    # worst case: both parts at the limits of their general tolerance (largest size)
                    widen = 0.0
                    for part in (first, second):
                        box = assembly_bounds(part)
                        source = assembly_find_source(part.get("source_name"), objects) \
                            if part.get("kind") == "project" else None
                        general = next((g for _s, g in assembly_part_drawings(source["name"], objects)),
                                       "ISO 2768-m") if source else "ISO 2768-m"
                        size = float(np.max(box[1] - box[0])) if box is not None else 0.0
                        widen += tol_general_tolerance(general, size) or 0.0
                    worst = gap - widen
                    if (first["name"], second["name"]) in fitted and gap < 0.05:
                        result, bad = "touching: shaft / bore fit (see Fits)", False
                    elif overlap:
                        result, bad = "OVERLAP (interference)", True
                    elif gap < 1e-3:
                        result, bad = "touching", False
                    elif worst < self.required.value():
                        result, bad = f"too small (< {self.required.value():g} mm worst case)", True
                    else:
                        result, bad = "OK", False
                    failing += bad
                    row = self.clearances.rowCount()
                    self.clearances.insertRow(row)
                    for column, value in enumerate((first["name"], second["name"], f"{gap:.3f}",
                                                    f"{worst:.3f}", result)):
                        self.clearances.setItem(row, column, self._item(value, bad))
                    self._clear_rows.append((first, second))
        finally:
            QApplication.restoreOverrideCursor()
        self.status.setText(
            f"{len(self._clear_rows)} pair(s) closer than {self.reach.value():g} mm, {failing} failing. "
            "Worst case: the gap less the ISO 2768 general tolerances of both parts (their largest size)."
            if self._clear_rows else f"No parts closer than {self.reach.value():g} mm to each other.")
        failing_row = next((row for row in range(self.clearances.rowCount())
                            if self.clearances.item(row, 4).foreground().color() == QColor("#ff6b6b")), None)
        if failing_row is not None:                    # the first failing pair is selected
            self.clearances.selectRow(failing_row)
            self._select_row(self._clear_rows, failing_row)


# persistence -------------------------------------------------------------------
def assembly_to_data(assembly, keep_empty=False):
    if not assembly["components"] and not keep_empty:
        return None
    components = []
    for component in assembly["components"]:
        data = {key: component[key] for key in (
            "name", "kind", "visible", "position", "rotation", "pivot", "source_name", "path",
            "signature", "file_stamp", "file_root", "source_piece", "file_piece", "cuts")
            if key in component}
        data["bodies"] = [{
            "name": body["name"], "color": body["color"], "opacity": body["opacity"],
            "fused": body.get("fused", False), "material": body.get("material"),
            "vertices": body["vertices"].tolist(), "triangles": [list(t) for t in body["triangles"]],
            "faces": body["faces"], **({"gear": copy.deepcopy(body["gear"])} if body.get("gear") else {})}
            for body in component["bodies"]]
        if component.get("cuts") and component.get("uncut_bodies"):
            data["uncut_bodies"] = [{
                "name": body["name"], "color": body["color"], "opacity": body["opacity"],
                "fused": body.get("fused", False), "material": body.get("material"),
                "vertices": np.asarray(body["vertices"], float).tolist(),
                "triangles": [list(t) for t in body["triangles"]],
                "faces": body["faces"], **({"gear": copy.deepcopy(body["gear"])} if body.get("gear") else {})}
                for body in component["uncut_bodies"]]
            data["cut_version"] = ASSEMBLY_CUT_VERSION
        components.append(data)
    return {"name": assembly["name"], "alignment_direction": "second-follows-first",
            "components": components,
            "constraints": copy.deepcopy(assembly["constraints"]),
            "explosion_distance": float(assembly.get(
                "explosion_distance", ASSEMBLY_EXPLOSION_DISTANCE)),
            # motion studies of the Motion add-on (kept as they are without it)
            **({"motion": copy.deepcopy(assembly["motion"])} if assembly.get("motion") else {}),
            **({"section": {"position": [float(x) for x in assembly["section"]["position"]],
                            "rotation": [float(x) for x in assembly["section"]["rotation"]],
                            "flip": bool(assembly["section"].get("flip")),
                            "split": bool(assembly["section"].get("split")),
                            "size": float(assembly["section"].get("size", 100.0)),
                            "active": bool(assembly["section"].get("active"))}}
               if assembly.get("section") else {})}

def assembly_from_data(data):
    assembly = assembly_new()
    if not data:
        return assembly
    migrate_legacy_direction = data.get("alignment_direction") != "second-follows-first"
    assembly["name"] = str(data.get("name", assembly["name"]))
    assembly["explosion_distance"] = max(
        0.0, float(data.get("explosion_distance", ASSEMBLY_EXPLOSION_DISTANCE)))
    section = data.get("section")
    if section:
        position = [float(x) for x in section.get("position", (0, 0, 0))]
        rotation = [float(x) for x in section.get("rotation", (0, 0, 0))]
        size = float(section.get("size", 100.0))
        if len(position) == 3 and len(rotation) == 3 and \
                np.isfinite(position + rotation + [size]).all() and size > 0:
            assembly["section"] = {"position": position, "rotation": rotation,
                                   "flip": bool(section.get("flip")),
                                   "split": bool(section.get("split")), "size": size,
                                   "active": bool(section.get("active"))}
    for item in data.get("components", []):
        if item.get("kind") not in ("project", "file"):
            raise ValueError("invalid assembly component")
        component = {
            "name": str(item["name"]), "kind": item["kind"], "visible": bool(item.get("visible", True)),
            "position": [float(x) for x in item.get("position", (0, 0, 0))],
            "rotation": [float(x) for x in item.get("rotation", (0, 0, 0))],
            "pivot": [float(x) for x in item.get("pivot", (0, 0, 0))],
            "bodies": [assembly_body(body["name"], body["vertices"], body["triangles"],
                                     body.get("faces", []), body.get("color", DEFAULT_SOLID_COLOR),
                                     body.get("opacity", 1.0), body.get("fused", False),
                                     body.get("material"), body.get("gear"))
                       for body in item.get("bodies", [])]}
        for key in ("source_name", "path", "signature", "file_stamp", "file_root",
                    "source_piece", "file_piece"):
            if key in item:
                component[key] = item[key]
        if item.get("cuts"):
            component["cuts"] = [{"origin": [float(x) for x in cut["origin"]],
                                  "normal": [float(x) for x in cut["normal"]]}
                                 for cut in item["cuts"]]
            if item.get("uncut_bodies"):
                component["uncut_bodies"] = [
                    assembly_body(body["name"], body["vertices"], body["triangles"],
                                  body.get("faces", []), body.get("color", DEFAULT_SOLID_COLOR),
                                  body.get("opacity", 1.0), body.get("fused", False),
                                  body.get("material"), body.get("gear"))
                    for body in item["uncut_bodies"]]
                if item.get("cut_version") != ASSEMBLY_CUT_VERSION:
                    assembly_recut(component)     # made with older cutting code
        assembly["components"].append(component)
    if isinstance(data.get("motion"), dict):
        assembly["motion"] = copy.deepcopy(data["motion"])
    for item in data.get("constraints", []):
        if item.get("kind") not in ("coincident", "mate"):
            raise ValueError("invalid assembly constraint")
        moving_ref, target_ref = item["moving_ref"], item["target_ref"]
        moving, target = item["moving"], item["target"]
        if migrate_legacy_direction:
            moving, target = target, moving
            moving_ref, target_ref = target_ref, moving_ref
        refs = {}
        for key, item_ref in (("moving_ref", moving_ref), ("target_ref", target_ref)):
            refs[key] = {"point": [float(x) for x in item_ref["point"]],
                         "label": str(item_ref.get("label", ""))}
            if item["kind"] == "mate":
                refs[key]["normal"] = [float(x) for x in item_ref["normal"]]
        constraint = {
            "kind": item["kind"], "enabled": bool(item.get("enabled", True)),
            "moving": str(moving), "target": str(target),
            **refs}
        if item["kind"] == "mate":
            constraint["opposed"] = bool(item.get("opposed", True))
        assembly["constraints"].append(constraint)
    return assembly

def assembly_save_file(assembly, path):
    if not os.fspath(path).lower().endswith(ASSEMBLY_EXTENSION):
        raise ValueError(f"assembly files must end in {ASSEMBLY_EXTENSION}")
    with open(path, "w", encoding="utf-8") as stream:
        json.dump({"format": ASSEMBLY_FORMAT, "version": 1,
                   "assembly": assembly_to_data(assembly, keep_empty=True)}, stream,
                  default=_json_default)

def assembly_load_file(path):
    if not os.fspath(path).lower().endswith(ASSEMBLY_EXTENSION):
        raise ValueError(f"assembly files must end in {ASSEMBLY_EXTENSION}")
    with open(path, "r", encoding="utf-8") as stream:
        data = json.load(stream)
    if not isinstance(data, dict) or data.get("format") != ASSEMBLY_FORMAT:
        raise ValueError("not a SimpleCAD assembly file")
    return assembly_from_data(data.get("assembly"))


_GIZMO_EXPLODE = (0.72, 0.32, 0.96)
_GIZMO_EXPLODE_HOT = (0.9, 0.62, 1.0)
# move / rotate handles use AXIS_HANDLE_COLORS (red / green / blue), as in the main window
_GIZMO_ARC = (20.0, 290.0)          # degrees of the ring drawn for a rotation handle


class AssemblyView3D(View3D):
    """3-D view of an assembly. Clicking selects a component; the selected one carries yellow
    move arrows and green rotation rings (rotation snaps every 15 degrees, Ctrl = free). The
    measure picker supplies the surfaces, corners, edges, hole centres and object centres used
    for alignment (Alt + click on a surface = object centre)."""
    selection_color = (1.0, 0.55, 0.55)
    bodyClicked = pyqtSignal(object)     # render entry of the clicked body, or None
    gizmoStarted = pyqtSignal()
    gizmoMoved = pyqtSignal(str, int, float)   # "move" (mm) / "rotate" (degrees), axis, total since press
    gizmoFinished = pyqtSignal()
    explosionMoved = pyqtSignal(float)
    explosionFinished = pyqtSignal(float)

    def __init__(self, state, parent=None):
        super().__init__(state, parent)
        self.gizmo_center = None            # world centre of the selected component
        self.gizmo_twist = None             # world axis of a selected surface mate's free twist
        self.gizmo_standard_handles = True
        self.marker_points = []             # [(world point, rgb)] shown for the selected alignment
        self._gizmo_hover = None
        self._gizmo_drag = None
        self.explosion_arrow = None
        self._explosion_drag = None
        self._pick_modifiers = Qt.NoModifier
        self.alignment_picking = False       # Align on: references in neon orange
        self.overlay_painters = []           # callables drawing extras (Motion: trace curves)
        self.mouse_handlers = []             # objects with press / move / release(view, event) -> True = used

    # ── picking ───────────────────────────────────────────────────────────────
    def _click_select3d(self, pos, ctrl=False, shift=False):
        hit = self._pick_face(*self._ray(pos)) if self._mvp is not None else None
        self.bodyClicked.emit(hit[1] if hit else None)

    @staticmethod
    def _face_reference(entry, face):
        """(centre, outward unit normal) of a planar face in world coordinates, or None."""
        faces = entry.get("faces", [])
        if not 0 <= face < len(faces) or not faces[face].get("planar") or not faces[face]["tris"]:
            return None
        cache = entry.setdefault("_face_ref", {})
        if face not in cache:
            vertices = np.asarray(entry["solid"][0], float)
            corners = vertices[np.asarray(entry["solid"][1], int)[faces[face]["tris"]]]
            cross = np.cross(corners[:, 1] - corners[:, 0], corners[:, 2] - corners[:, 0])
            area = np.linalg.norm(cross, axis=1)
            total = float(area.sum())
            if total < 1e-12:
                cache[face] = None
            else:
                cache[face] = ((corners.mean(axis=1) * area[:, None]).sum(0) / total,
                               cross.sum(0) / float(np.linalg.norm(cross.sum(0))))
        return cache[face]

    def _measure_pick(self, pos, thr_edge=8.0, thr_point=10.0):
        item = super()._measure_pick(pos, thr_edge, thr_point)
        if item is not None or self._mvp is None:
            return item
        hit = self._pick_face(*self._ray(pos))     # nothing but a face under the cursor
        if hit is None:
            return None
        entry = hit[1]
        reference = None if self._pick_modifiers & Qt.AltModifier \
            else self._face_reference(entry, hit[2])
        if reference is not None:
            return {"kind": "face", "entry": entry, "solid": entry["solid"], "face": hit[2],
                    "P": reference[0], "normal": reference[1], "label": reference[0],
                    "key": ("f", id(entry), hit[2])}
        if entry.get("_centre") is None:
            return None
        item = measure_point_item(entry, entry["_centre"])
        item["ref"] = "object centre"
        return item

    # alignment references in the assembly: neon orange (edges, corners, surfaces), so Align
    # and Measure (brown, the inverted body colour as in the main window) are told apart
    ALIGN_HIGHLIGHT = (1.0, 0.37, 0.0)
    ALIGN_HIGHLIGHT_HOT = (1.0, 0.6, 0.2)

    @staticmethod
    def _outline_probes(entry, face):
        """Outline pieces of a planar face and, for each, a probe point just inside the face
        beside it (NaN where no side lies in the face). Depends on the geometry only: cached on
        the body until its mesh changes."""
        reference = AssemblyView3D._face_reference(entry, face)
        vertices = View3D._face_outline_array(entry, face)
        if reference is None or not len(vertices):
            return None
        cache = entry.get("_outline_probes")
        if cache is None or cache[0] is not entry["solid"][0]:   # only the current mesh
            cache = (entry["solid"][0], {})
            entry["_outline_probes"] = cache
        if face in cache[1]:
            return cache[1][face]
        normal = np.asarray(reference[1], float)
        segments = np.asarray(vertices, float).reshape(-1, 2, 3)
        direction = segments[:, 1] - segments[:, 0]
        length = np.linalg.norm(direction, axis=1)
        real = length > 1e-9
        segments, direction, length = segments[real], direction[real], length[real]
        # long edges are checked in pieces (only the seen part of an edge is drawn)
        counts = np.clip(np.ceil(length / 2.0), 1, 48).astype(int)
        rows = np.repeat(np.arange(len(segments)), counts)
        index = np.concatenate([np.arange(c) for c in counts]) if len(counts) else np.zeros(0, int)
        fraction = counts[rows].astype(float)
        starts = segments[rows, 0] + direction[rows] * (index / fraction)[:, None]
        ends = segments[rows, 0] + direction[rows] * ((index + 1) / fraction)[:, None]
        across = np.cross(normal, direction[rows]) / length[rows][:, None]
        # far enough inside that a wall standing on the edge clearly hides a covered probe
        step = np.clip(0.1 * length[rows] / fraction, 0.1, 0.5)[:, None]
        middle = (starts + ends) / 2
        candidates = np.stack([middle + across * step, middle - across * step], axis=1)
        triangles = View3D._face_vertex_array(entry, face).astype(float).reshape(-1, 3, 3)
        u = triangles[0, 1] - triangles[0, 0]
        u /= max(float(np.linalg.norm(u)), 1e-12)
        v = np.cross(normal, u)
        tri = np.stack([triangles @ u, triangles @ v], axis=-1)              # (m, 3, 2)
        q = np.stack([candidates @ u, candidates @ v], axis=-1).reshape(-1, 2)  # (2k, 2)
        def side(points, i, j):
            a, b = tri[None, :, i], tri[None, :, j]
            return (b[..., 0] - a[..., 0]) * (points[:, None, 1] - a[..., 1]) - \
                   (b[..., 1] - a[..., 1]) * (points[:, None, 0] - a[..., 0])
        inside = np.zeros(len(q), bool)
        for chunk in range(0, len(q), 512):           # (bounded memory for big faces)
            points = q[chunk:chunk + 512]
            d1, d2, d3 = side(points, 0, 1), side(points, 1, 2), side(points, 2, 0)
            inside[chunk:chunk + 512] = (((d1 >= 0) & (d2 >= 0) & (d3 >= 0)) |
                                         ((d1 <= 0) & (d2 <= 0) & (d3 <= 0))).any(axis=1)
        inside = inside.reshape(-1, 2)
        probes = np.where(inside[:, :1], candidates[:, 0],
                          np.where(inside[:, 1:], candidates[:, 1], np.nan))
        # lifted a little off the face so its own surface never hides it
        result = (np.stack([starts, ends], axis=1).astype(np.float32), probes + normal * 0.03)
        cache[1][face] = result
        return result

    def _seen_points(self, points):
        """Which world points are not hidden behind what the view has drawn (depth buffer of
        this frame). NaN points count as seen."""
        seen = np.ones(len(points), bool)
        valid = ~np.isnan(points).any(axis=1)
        if not valid.any() or self._mvp is None:
            return seen
        clip = np.c_[points[valid], np.ones(int(valid.sum()))] @ self._mvp.T
        w = clip[:, 3]
        front = w > 1e-6
        ndc = clip[:, :3] / np.where(front, w, 1.0)[:, None]
        x0, y0, width, height = (int(value) for value in glGetIntegerv(GL_VIEWPORT))
        px = np.floor((ndc[:, 0] + 1) / 2 * width).astype(int)
        py = np.floor((ndc[:, 1] + 1) / 2 * height).astype(int)
        on = front & (px >= 0) & (px < width) & (py >= 0) & (py < height)
        result = np.ones(len(w), bool)
        if on.any():
            left, right = int(px[on].min()), int(px[on].max())
            bottom, top = int(py[on].min()), int(py[on].max())
            depth = np.frombuffer(glReadPixels(x0 + left, y0 + bottom, right - left + 1,
                                               top - bottom + 1, GL_DEPTH_COMPONENT, GL_FLOAT),
                                  np.float32).reshape(top - bottom + 1, right - left + 1)
            buffer = depth[py[on] - bottom, px[on] - left].astype(float)
            if self._ortho_plane:
                result[on] = (ndc[on, 2] + 1) / 2 <= buffer + 1e-5
            else:                                    # compare eye distances (mm)
                near, far = 0.1, 10000.0
                drawn = 2 * near * far / (far + near - (2 * buffer - 1) * (far - near))
                result[on] = w[on] <= drawn + 0.01 + 0.0002 * w[on]
        seen[valid] = result
        return seen

    def _visible_outline(self, entry, face):
        """Outline pieces of a planar face whose neighbouring part of the face is seen (a face
        edge can lie on another body's visible wall while the face beside it is hidden inside
        that body)."""
        probes = self._outline_probes(entry, face)
        if probes is None:
            return View3D._face_outline_array(entry, face)
        segments, points = probes
        return segments[self._seen_points(points)].reshape(-1, 3)

    def _draw_visible_face(self, entry, face, color, fill_alpha, width, line_color=None):
        """A picked surface, but only where it is seen: the parts of a part's bodies overlap
        (a body built into another one keeps its whole face), and without a depth test the
        hidden rest of the face lit up too. Pulled a hair forward to win over its own surface."""
        glEnable(GL_DEPTH_TEST); glDepthFunc(GL_LEQUAL)
        # its own triangles: equal depth passes LEQUAL; a tiny constant pull (no slope term,
        # which poked through neighbouring walls at grazing angles)
        glEnable(GL_POLYGON_OFFSET_FILL); glPolygonOffset(0.0, -2.0)
        glColor4f(*color, fill_alpha)
        self._draw_face_triangles(entry, face)
        glDisable(GL_POLYGON_OFFSET_FILL); glPolygonOffset(0.0, 0.0)
        glDepthFunc(GL_LESS); glDisable(GL_DEPTH_TEST)
        outline = self._visible_outline(entry, face)
        if len(outline):                          # drawn on top: only the edges that are seen
            glColor3f(*(line_color or color)); glLineWidth(width)
            glBindBuffer(GL_ARRAY_BUFFER, 0)
            glEnableClientState(GL_VERTEX_ARRAY)
            glVertexPointer(3, GL_FLOAT, 0, np.ascontiguousarray(outline, np.float32))
            glDrawArrays(GL_LINES, 0, len(outline))
            glDisableClientState(GL_VERTEX_ARRAY)

    def _draw_measure_item(self, it, label, font=None, hot=False):
        if not self.alignment_picking:
            if it["kind"] != "face":
                return super()._draw_measure_item(it, label, font, hot)
            self._draw_visible_face(it["entry"], it["face"], measure_highlight_color(it["entry"]),
                                    0.5 if hot else 0.35, 5 if hot else 3)
            if label:
                glColor3f(1.0, 1.0, 1.0)
                self.renderText(float(it["P"][0]), float(it["P"][1]), float(it["P"][2]), "S", font)
            return
        color = self.ALIGN_HIGHLIGHT_HOT if hot else self.ALIGN_HIGHLIGHT
        if it["kind"] != "face":
            glColor3f(*color)
            if it["kind"] == "edge":
                glLineWidth(7 if hot else 4)
                glBegin(GL_LINE_STRIP)
                for pt in it["P"]: glVertex3f(*pt)
                glEnd()
            else:
                glPushAttrib(GL_ENABLE_BIT)
                glDisable(GL_MULTISAMPLE)
                glPointSize(15 if hot else 11)
                glBegin(GL_POINTS); glVertex3f(*it["P"]); glEnd()
                glPopAttrib()
            if label:
                glColor3f(1.0, 1.0, 1.0)
                self.renderText(float(it["label"][0]), float(it["label"][1]),
                                float(it["label"][2]), label, font)
            return
        # (weaker fills turned grey on the blue body); the outline always in the strong orange,
        # so it stays visible on a surface that is picked and hovered at once
        self._draw_visible_face(it["entry"], it["face"], color, 0.75 if hot else 0.6,
                                5 if hot else 3, line_color=self.ALIGN_HIGHLIGHT)
        if label:
            glColor3f(1.0, 1.0, 1.0)
            self.renderText(float(it["P"][0]), float(it["P"][1]), float(it["P"][2]), "S", font)

    def fit_all(self):
        boxes = [box for box in (entry_bounds(o) for o in self.state["objects"] if entry_visible(o))
                 if box is not None]
        if not boxes:
            self.pan = [0.0, 0.0]; self.zoom = 300.0; self.update(); return
        low = np.min([box[0] for box in boxes], axis=0)
        high = np.max([box[1] for box in boxes], axis=0)
        centre = (low + high) / 2
        size = float(np.linalg.norm(high - low)) or 50.0
        rx, rz = math.radians(self.rot_x), math.radians(self.rot_z)
        Rz = np.array([[math.cos(rz), -math.sin(rz), 0], [math.sin(rz), math.cos(rz), 0], [0, 0, 1]])
        Rx = np.array([[1, 0, 0], [0, math.cos(rx), -math.sin(rx)], [0, math.sin(rx), math.cos(rx)]])
        eye = Rx @ Rz @ centre
        self.pan = [-float(eye[0]), -float(eye[1])]
        self.zoom = max(10.0, min(5000.0, size*1.8 + float(eye[2])))
        self.update()

    def set_camera(self, rot_x, rot_z):
        self.rot_x, self.rot_z = rot_x, rot_z
        self.fit_all()

    # ── gizmo geometry ────────────────────────────────────────────────────────
    # ── Cut Surface of the assembly (plane + move / rotate handles of the dialog's fields) ──
    section_editor = None          # the AssemblyDialog; it decides when the plane is shown

    def _dimension_handle_data(self, all_handles=False):
        editor = self.section_editor
        if self._mvp is None or editor is None or not editor.section_editing():
            return [] if all_handles else None
        specs = cut_plane_handle_specs(editor.assembly["section"], editor.sp_cut_position,
                                       editor.sp_cut_rotation)
        specs = self._visible_move_rotate(specs, editor.chk_cut_show_move,
                                          editor.chk_cut_show_rotate)
        handles = self._handles_from_specs(specs)
        return handles if all_handles else (handles[0] if handles else None)

    def _handle_drag_options(self, control):
        editor = self.section_editor
        rotation = editor is not None and any(control is spin for spin in editor.sp_cut_rotation)
        return (1.0 if rotation else None), Qt.ControlModifier | Qt.ShiftModifier, None

    def _draw_cut_surface(self):
        editor = self.section_editor
        if editor is not None and editor.section_editing():
            self._draw_cut_plane(editor.assembly["section"])

    def _gizmo_active(self):
        return self.gizmo_center is not None and self._mvp is not None

    def _gizmo_pickable(self):
        return self._gizmo_active() and not self._measure_mode

    def _explosion_active(self):
        return self.explosion_arrow is not None and self._mvp is not None and not self._measure_mode

    def _explosion_pick(self, pos, threshold=9.0):
        if not self._explosion_active():
            return False
        handle = self._explosion_handle_data()
        if handle is None:
            return False
        point = np.array([pos.x(), pos.y()], float)
        return min_seg_dist(point, np.array([handle["start"]]),
                            np.array([handle["tip"]])) < threshold

    def _explosion_handle_data(self):
        if not self._explosion_active():
            return None
        arrow = self.explosion_arrow
        origin = np.asarray(arrow["origin"], float)
        direction = np.asarray(arrow["direction"], float)
        screen, valid = self._project(np.array([origin, origin + direction]))
        if not valid.all():
            return None
        projected = screen[1] - screen[0]
        pixels_per_mm = float(np.linalg.norm(projected))
        if pixels_per_mm < 0.25:
            depth = float((self._mvp @ np.r_[origin, 1.0])[3])
            pixels_per_mm = (self.height() / (2.0 * max(depth, 0.1) *
                              math.tan(math.radians(22.5))) * float(np.linalg.norm(direction)))
            screen_direction = np.array([0.0, -1.0])
        else:
            screen_direction = projected / pixels_per_mm
        start = screen[0] + 10.0 * screen_direction
        tip = screen[0] + 68.0 * screen_direction
        lower = np.minimum(start, tip) - 12.0
        upper = np.maximum(start, tip) + 12.0
        shift = np.maximum(8.0 - lower, 0.0) + np.minimum(
            np.array([self.width() - 8.0, self.height() - 8.0]) - upper, 0.0)
        return {"screen_origin": screen[0], "screen_direction": screen_direction,
                "pixels_per_mm": pixels_per_mm, "start": start + shift, "tip": tip + shift}

    def _explosion_param(self, drag, pos):
        return float((np.array([pos.x(), pos.y()]) - drag["screen_origin"]) @
                     drag["screen_direction"] / drag["pixels_per_mm"])

    # the same on-screen size as the main window's handles (_dimension_handle_data /
    # _ring_handle): arrows end 68 px from the centre, rings have a 38 px radius
    GIZMO_ARROW_PIXELS = 68.0
    GIZMO_RING_RATIO = View3D.RING_HANDLE_PIXELS / GIZMO_ARROW_PIXELS

    def _gizmo_pixel(self, point=None):
        """World length of one screen pixel at the gizmo centre (or `point`)."""
        point = self.gizmo_center if point is None else point
        clip = self._mvp @ np.append(np.asarray(point, float), 1.0)
        depth = max(float(clip[3]), 0.1)
        return 2.0 * depth * math.tan(math.radians(22.5)) / max(1, self.height())

    def _gizmo_length(self):
        return self.GIZMO_ARROW_PIXELS * self._gizmo_pixel()

    @staticmethod
    def _gizmo_ring(axis, centre, length, start, stop, count):
        """Points of a ring about the axis; the angle grows counter-clockwise about +axis."""
        u, v = np.eye(3)[(axis + 1) % 3], np.eye(3)[(axis + 2) % 3]
        angles = np.radians(np.linspace(start, stop, count))
        return centre + AssemblyView3D.GIZMO_RING_RATIO*length*(
            np.cos(angles)[:, None]*u + np.sin(angles)[:, None]*v)

    def _gizmo_twist_handle_data(self):
        if self.gizmo_twist is None or not self._gizmo_active():
            return None
        axis = np.asarray(self.gizmo_twist["axis"], float)
        axis /= np.linalg.norm(axis)
        helper = np.eye(3)[int(np.argmin(np.abs(axis)))]
        u = np.cross(axis, helper)
        u /= np.linalg.norm(u)
        v = np.cross(axis, u)
        origin = np.asarray(self.gizmo_twist["origin"], float)
        length = self.GIZMO_ARROW_PIXELS * self._gizmo_pixel(origin)
        radius = self.GIZMO_RING_RATIO * length
        arc_angles = np.radians(np.linspace(*_GIZMO_ARC, 49))
        circle_angles = np.radians(np.arange(361.0))
        arc = origin + radius * (np.cos(arc_angles)[:, None] * u +
                     np.sin(arc_angles)[:, None] * v)
        circle = origin + radius * (np.cos(circle_angles)[:, None] * u +
                        np.sin(circle_angles)[:, None] * v)
        end = math.radians(_GIZMO_ARC[1])
        tangent = -math.sin(end) * u + math.cos(end) * v
        return {"ring": arc, "circle": circle, "tip": arc[-1], "tangent": tangent,
            "axis": axis, "length": length}

    def _gizmo_pick(self, pos, threshold=9.0, mate_only=False):
        """("move" | "rotate", axis) of the handle under the cursor, or None."""
        centre, length = np.asarray(self.gizmo_center, float), self._gizmo_length()
        point = np.array([pos.x(), pos.y()], float)
        best = None
        for axis in (range(3) if self.gizmo_standard_handles and not mate_only else ()):
            candidates = (
                ("move", np.array([centre, centre + np.eye(3)[axis]*length])),
                ("rotate", self._gizmo_ring(axis, centre, length, *_GIZMO_ARC, 49)))
            for kind, points in candidates:
                distance = self._polyline_dist(point, points)
                if distance < threshold and (best is None or distance < best[0]):
                    best = (distance, kind, axis)
        twist = self._gizmo_twist_handle_data()
        if twist is not None:
            distance = self._polyline_dist(point, twist["ring"])
            if distance < threshold and (best is None or distance < best[0]):
                best = (distance, "mate_rotate", 0)
        return None if best is None else (best[1], best[2])

    def _gizmo_param(self, drag, pos):
        """Position of the cursor along the dragged handle: mm along the arrow, or the angle
        (degrees) of the nearest point of the ring."""
        point = np.array([pos.x(), pos.y()], float)
        centre, length, axis = drag["centre"], drag["length"], drag["axis"]
        if drag["kind"] == "mate_rotate":
            handle = self._gizmo_twist_handle_data()
            if handle is None:
                return None
            screen, valid = self._project(handle["circle"])
            distance = np.where(valid, np.hypot(screen[:, 0] - point[0],
                                                screen[:, 1] - point[1]), np.inf)
            return float(np.argmin(distance))
        if drag["kind"] == "move":
            screen, valid = self._project(np.array([centre, centre + np.eye(3)[axis]*length]))
            direction = screen[1] - screen[0]
            squared = float(direction @ direction)
            if not valid.all() or squared < 1e-6:
                return None
            return float((point - screen[0]) @ direction / squared * length)
        screen, valid = self._project(self._gizmo_ring(axis, centre, length, 0.0, 360.0, 361))
        distance = np.where(valid, np.hypot(screen[:, 0] - point[0], screen[:, 1] - point[1]), np.inf)
        return float(np.argmin(distance))

    # ── gizmo mouse handling ──────────────────────────────────────────────────
    def _handled(self, method, e):
        """An add-on's mouse handler (Motion: drag handles) took the event."""
        for handler in list(self.mouse_handlers):
            try:
                if getattr(handler, method)(self, e):
                    return True
            except Exception as ex:
                _dbg(f"assembly mouse handler failed: {ex}")
        return False

    def mousePressEvent(self, e):
        self._pick_modifiers = e.modifiers()
        if self._handled("press", e):
            return
        if e.button() == Qt.LeftButton and self._explosion_active() and self._explosion_pick(e.pos()):
            arrow = self.explosion_arrow
            drag = self._explosion_handle_data()
            drag["start_distance"] = float(arrow["distance"])
            start = self._explosion_param(drag, e.pos())
            if start is not None:
                drag["start"] = start
                self._explosion_drag = drag
                self._last_pos = self._press_pos = None
                self.setCursor(QCursor(Qt.ClosedHandCursor))
                return
        if e.button() == Qt.LeftButton and self._gizmo_active():
            hit = self._gizmo_pick(e.pos(), mate_only=self._measure_mode)
            if hit is not None and (self._gizmo_pickable() or hit[0] == "mate_rotate"):
                drag = {"kind": hit[0], "axis": hit[1],
                        "centre": np.array(self.gizmo_center, float), "length": self._gizmo_length()}
                start = self._gizmo_param(drag, e.pos())
                if start is not None:
                    drag.update(start=start, last=start, total=0.0)
                    self._gizmo_drag = drag
                    self._last_pos = self._press_pos = None
                    self.setCursor(QCursor(Qt.ClosedHandCursor))
                    self.gizmoStarted.emit()
                    return
        super().mousePressEvent(e)
        if e.button() == Qt.RightButton:
            self.bodyClicked.emit(None)

    def mouseMoveEvent(self, e):
        self._pick_modifiers = e.modifiers()
        if self._handled("move", e):
            return
        if self._explosion_drag is not None:
            drag = self._explosion_drag
            if not e.buttons() & Qt.LeftButton:
                self.explosionFinished.emit(drag["start_distance"])
                self._explosion_drag = None
                self.setCursor(self._default_cursor())
                self.update()
                return
            position = self._explosion_param(drag, e.pos())
            if position is not None:
                step = 0.1 if e.modifiers() & Qt.ControlModifier else ASSEMBLY_MOVE_STEP
                distance = max(0.0, round((drag["start_distance"] + position - drag["start"]) / step) * step)
                self.explosionMoved.emit(float(distance))
            return
        drag = self._gizmo_drag
        if drag is not None:
            if not e.buttons() & Qt.LeftButton:
                self._gizmo_end()
                return
            param = self._gizmo_param(drag, e.pos())
            if param is not None:
                if drag["kind"] == "move":
                    value = param - drag["start"]
                    step = 0.1 if e.modifiers() & Qt.ControlModifier else ASSEMBLY_MOVE_STEP
                    value = round(value / step) * step
                else:
                    drag["total"] += (param - drag["last"] + 180.0) % 360.0 - 180.0
                    drag["last"] = param
                    value = drag["total"]
                    if not e.modifiers() & Qt.ControlModifier:
                        value = round(value / ASSEMBLY_ROTATION_STEP) * ASSEMBLY_ROTATION_STEP
                self.gizmoMoved.emit(drag["kind"], drag["axis"], float(value))
            return
        if not e.buttons() and (self._gizmo_active() or self._explosion_active()):
            hover = self._explosion_pick(e.pos()) if self._explosion_active() else \
                self._gizmo_pick(e.pos(), mate_only=self._measure_mode)
            if hover != self._gizmo_hover:
                self._gizmo_hover = hover
                self.setCursor(QCursor(Qt.PointingHandCursor if hover else Qt.ArrowCursor))
                self.update()
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        self._pick_modifiers = e.modifiers()
        if self._handled("release", e):
            return
        if e.button() == Qt.LeftButton and self._explosion_drag is not None:
            self.explosionFinished.emit(self._explosion_drag["start_distance"])
            self._explosion_drag = None
            self._gizmo_hover = None
            self.setCursor(self._default_cursor())
            self.update()
            return
        if e.button() == Qt.LeftButton and self._gizmo_drag is not None:
            self._gizmo_end()
            return
        super().mouseReleaseEvent(e)

    def _gizmo_end(self):
        self._gizmo_drag = None
        self._gizmo_hover = None
        self.setCursor(self._default_cursor())
        self.gizmoFinished.emit()
        self.update()

    # ── drawing ───────────────────────────────────────────────────────────────
    def paintGL(self):
        super().paintGL()
        for painter in list(self.overlay_painters):
            try:
                painter()
            except Exception as ex:                   # an add-on never breaks the view
                _dbg(f"assembly overlay failed: {ex}")
        if not self._measure_mode:
            self._draw_markers()
        if self._explosion_active():
            self._draw_explosion_arrow()
        if self._gizmo_active():
            self._draw_gizmo()

    @staticmethod
    def _draw_cone(base, direction, height, radius):
        direction = direction / np.linalg.norm(direction)
        helper = np.array([1.0, 0.0, 0.0]) if abs(direction[0]) < 0.9 else np.array([0.0, 1.0, 0.0])
        u = np.cross(direction, helper); u /= np.linalg.norm(u)
        v = np.cross(direction, u)
        glBegin(GL_TRIANGLE_FAN)
        glVertex3f(*(base + direction*height))
        for step in range(13):
            angle = 2*math.pi*step/12
            glVertex3f(*(base + radius*(math.cos(angle)*u + math.sin(angle)*v)))
        glEnd()

    def _draw_markers(self):
        if not self.marker_points:
            return
        glPushAttrib(GL_ENABLE_BIT | GL_POINT_BIT | GL_CURRENT_BIT)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST); glDisable(GL_MULTISAMPLE)
        glPointSize(13)
        glBegin(GL_POINTS)
        for point, color in self.marker_points:
            glColor3f(*color); glVertex3f(*point)
        glEnd()
        glPopAttrib()

    def _draw_gizmo(self):
        """Move arrows and rotation rings in the style of the main window's handles (Surface /
        Cut Surface): red / green / blue per axis with a dark outline; the touched handle is
        lighter and wider; rings carry an arrowhead at both ends."""
        centre, length = np.asarray(self.gizmo_center, float), self._gizmo_length()
        pixel = self._gizmo_pixel()
        drag, hover = self._gizmo_drag, self._gizmo_hover
        font = QFont("Arial", 9, QFont.Bold)
        outline_color = (0.07, 0.08, 0.09)
        glPushAttrib(GL_ENABLE_BIT | GL_COLOR_BUFFER_BIT | GL_LINE_BIT | GL_CURRENT_BIT)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)

        def strokes(color, active):
            """(outline?, line width, colour) passes, as _draw_dimension_handle draws them."""
            if active: color = tuple(0.45 + 0.55*c for c in color)
            return ((True, 11.0 if active else 8.0, outline_color),
                    (False, 6.0 if active else 4.0, color))

        def draw_ring(ring, start_tangent, end_tangent, outline):
            glBegin(GL_LINE_STRIP)
            for point in ring:
                glVertex3f(*point)
            glEnd()
            for tip, tangent in ((ring[0], start_tangent), (ring[-1], end_tangent)):
                self._draw_cone(tip, tangent, (16.0 if outline else 12.0)*pixel,
                                (9.0 if outline else 6.0)*pixel)

        labels = []
        kinds = ("move", "rotate") if self.gizmo_standard_handles else ()
        for kind in kinds:
            for axis in range(3):
                color = AXIS_HANDLE_COLORS["axis_" + "xyz"[axis]][:3]
                active = (drag["kind"], drag["axis"]) == (kind, axis) if drag is not None \
                    else hover == (kind, axis)
                if kind == "move":
                    direction = np.eye(3)[axis]
                    start_point = centre + direction*10.0*pixel        # as the main window
                    shaft = centre + direction*(length - 16.0*pixel)
                    label_at = centre + direction*(length + 12.0*pixel)
                else:
                    ring = self._gizmo_ring(axis, centre, length, *_GIZMO_ARC, 49)
                    u, v = np.eye(3)[(axis + 1) % 3], np.eye(3)[(axis + 2) % 3]
                    start, end = (math.radians(a) for a in _GIZMO_ARC)
                    start_tangent = math.sin(start)*u - math.cos(start)*v   # backwards
                    end_tangent = -math.sin(end)*u + math.cos(end)*v
                    label_at = ring[-1] + end_tangent*14.0*pixel
                for outline, width, stroke in strokes(color, active):
                    glColor3f(*stroke); glLineWidth(width)
                    if kind == "move":
                        glBegin(GL_LINES); glVertex3f(*start_point); glVertex3f(*shaft); glEnd()
                        self._draw_cone(shaft, direction, 16.0*pixel,
                                        (9.0 if outline else 6.0)*pixel)
                    else:
                        draw_ring(ring, start_tangent, end_tangent, outline)
                labels.append((label_at, "XYZ"[axis], strokes(color, active)[1][2]))
        twist = self._gizmo_twist_handle_data()
        if twist is not None:
            active = (drag["kind"] == "mate_rotate") if drag is not None \
                else hover == ("mate_rotate", 0)
            ring = twist["ring"]
            start_tangent = ring[0] - ring[1]
            start_tangent = start_tangent / max(float(np.linalg.norm(start_tangent)), 1e-12)
            # a mate's free twist is no world axis: the main window's rotation green
            for outline, width, stroke in strokes((0.25, 1.0, 0.35), active):
                glColor3f(*stroke); glLineWidth(width)
                draw_ring(ring, start_tangent, twist["tangent"], outline)
            labels.append((twist["tip"] + twist["tangent"]*14.0*pixel, "R",
                           strokes((0.25, 1.0, 0.35), active)[1][2]))
        glLineWidth(1.0)
        # letters in the handle colour on a dark shadow, like the main window's value labels
        for point, text, color in labels:
            screen, valid = self._project(np.array([point], float))
            if not valid[0]:
                continue
            x, y = (int(round(float(c))) for c in screen[0])
            glColor3f(*outline_color); self.renderText(x + 1, y + 1, text, font)
            glColor3f(*color); self.renderText(x, y, text, font)
        glPopAttrib()

    def _draw_explosion_arrow(self):
        handle = self._explosion_handle_data()
        if handle is None:
            return
        start, tip, direction = handle["start"], handle["tip"], handle["screen_direction"]
        sideways = np.array([-direction[1], direction[0]])
        active = self._explosion_drag is not None or self._gizmo_hover is True
        glPushAttrib(GL_ENABLE_BIT | GL_COLOR_BUFFER_BIT | GL_LINE_BIT | GL_CURRENT_BIT)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glMatrixMode(GL_PROJECTION); glPushMatrix(); glLoadIdentity()
        glOrtho(0, self.width(), self.height(), 0, -1, 1)
        glMatrixMode(GL_MODELVIEW); glPushMatrix(); glLoadIdentity()
        for width, color in ((8.0, (0.08, 0.09, 0.10, 0.9)),
                             (4.0, (*(_GIZMO_EXPLODE_HOT if active else _GIZMO_EXPLODE), 1.0))):
            glColor4f(*color); glLineWidth(width)
            glBegin(GL_LINES); glVertex2f(*start); glVertex2f(*(tip - 10.0 * direction)); glEnd()
            head_width = 9.0 if width == 8.0 else 6.0
            glBegin(GL_TRIANGLES)
            glVertex2f(*tip)
            glVertex2f(*(tip - 16.0 * direction + head_width * sideways))
            glVertex2f(*(tip - 16.0 * direction - head_width * sideways))
            glEnd()
        glPopMatrix(); glMatrixMode(GL_PROJECTION); glPopMatrix(); glMatrixMode(GL_MODELVIEW)
        value = f"{self.explosion_arrow['distance']:.2f}".rstrip("0").rstrip(".") + " mm"
        font = self.font(); font.setBold(True)
        label = tip + np.array([12.0, -8.0])
        label[0] = np.clip(label[0], 4.0,
                           max(4.0, self.width() - QFontMetricsF(font).horizontalAdvance(value) - 4.0))
        label[1] = np.clip(label[1], QFontMetricsF(font).height(), self.height() - 4.0)
        glPushAttrib(GL_ENABLE_BIT | GL_CURRENT_BIT)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
        glColor3f(0.05, 0.05, 0.05)
        self.renderText(int(label[0] + 1), int(label[1] + 1), value, font)
        glColor3f(*(_GIZMO_EXPLODE_HOT if active else _GIZMO_EXPLODE))
        self.renderText(int(label[0]), int(label[1]), value, font)
        glPopAttrib()
        glLineWidth(1.0)
        glPopAttrib()


class AssemblyDialog(QDialog):
    """Assembly window (a window of its own, not tied to the main window): component explorer,
    placement fields, a 3-D view and a panel with the alignments (constraints)."""

    def __init__(self, window):
        super().__init__(None)
        self._window = window
        self.assembly = window._assembly
        self.changed = False
        self._selected = None
        self._selected_body = None
        self._selected_alignment = None
        self._loading = False
        self._ready = False
        self._status = {}
        self._scene = []
        self._drag_base = None
        self._explosion_offsets = {}
        self._alignment_axes_visibility = {}
        self._component_axes_visibility = {}
        self._undo_history = []
        self._undo_index = -1
        self._restoring_history = False
        self.setWindowIcon(QIcon(os.path.join(_LOG_DIR, "icons", "assembly.png")))
        self.setWindowFlags(Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowMaximizeButtonHint |
                            Qt.WindowCloseButtonHint | Qt.WindowSystemMenuHint)
        self.resize(1400, 860)
        self._motion = None
        self._build_ui()
        addon = load_addon("simplecad_motion")      # Motion mode (optional add-on)
        if addon is not None:
            try:
                self._motion = addon.attach(self)
            except Exception:
                _trace(f"Motion add-on could not attach:\n{traceback.format_exc()}")
                self._motion = None
        # Enter in a number field must only confirm the value: no button of this window is the
        # dialog's default button (otherwise Enter "clicks" e.g. the colour button)
        for button in self.findChildren(QPushButton):
            button.setAutoDefault(False); button.setDefault(False)
        self._upgrade_legacy_cuts()
        self._update_title()
        self._refresh_status()
        self._rebuild_scene()
        self._rebuild_tree()
        self._rebuild_constraints()
        self.view.fit_all()
        self._ready = True
        self._reset_history()
        self._mark_saved()
        self._set_status("Add parent objects from the project or import STEP / STL / OBJ files.")

    # ── UI ────────────────────────────────────────────────────────────────────
    def _build_ui(self):
        icon_dir = os.path.join(_LOG_DIR, "icons")

        def action(icon, text, tip, slot, checkable=False):
            act = QAction(QIcon(os.path.join(icon_dir, icon)), text, self,
                          toolTip=tip, checkable=checkable)
            if checkable:
                act.toggled.connect(slot)
            else:
                act.triggered.connect(lambda _checked=False: slot())
            return act

        def collapsible_panel(title_text, content):
            panel = QWidget()
            panel_layout = QVBoxLayout(panel)
            panel_layout.setContentsMargins(0, 0, 0, 0)
            panel_layout.setSpacing(0)
            title_bar = QWidget(panel)
            title_bar.setObjectName("assemblyPanelTitleBar")
            title_bar.setStyleSheet(
                "QWidget#assemblyPanelTitleBar { background:#292e36; border-bottom:1px solid #3b424d; }"
                "QLabel { color:#e2e5e9; font-weight:bold; }"
                "QToolButton { padding:0; margin:0; min-width:16px; max-width:16px; "
                "min-height:16px; max-height:16px; }")
            title_bar.setFixedHeight(24)
            title_bar.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            title_layout = QHBoxLayout(title_bar)
            title_layout.setContentsMargins(6, 1, 4, 1)
            title_layout.setSpacing(4)
            title = QLabel(title_text, title_bar)
            title.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
            title_layout.addWidget(title)
            button = QToolButton(title_bar)
            button.setFixedSize(18, 18)
            button.setAutoRaise(True)
            button.setArrowType(Qt.DownArrow)
            button.setToolTip("Collapse panel")
            button.setAccessibleName("Collapse panel")
            title_layout.addWidget(button)
            panel_layout.addWidget(title_bar, 0, Qt.AlignTop)
            panel_layout.addWidget(content, 1)
            state = {
                "panel": panel, "content": content, "title": title, "title_bar": title_bar,
                "button": button,
                "collapsed": False, "expanded_width": None,
                "minimum_width": panel.minimumWidth(), "maximum_width": panel.maximumWidth(),
                "collapsed_width": title_layout.contentsMargins().left() + button.width() +
                                   title_layout.contentsMargins().right(),
            }
            return panel, state

        toolbar = QToolBar(self)
        toolbar.setMovable(False)
        toolbar.setIconSize(QSize(32, 32))
        toolbar.setToolButtonStyle(Qt.ToolButtonIconOnly)
        toolbar.setStyleSheet("QToolButton:checked{background:#315f94;border:1px solid #548ac2;"
                              "border-radius:3px;}")
        self.act_new = action("new_file.png", "New assembly", "New — start an empty assembly",
                              self._new_file)
        self.act_open = action("open.png", "Open assembly", "Open an .asby assembly file",
                               self._open_file)
        self.act_save = action("save.png", "Save assembly", "Save the assembly to its file", self._save)
        self.act_save_as = action("save_as.png", "Save assembly as",
                                  "Save the assembly under a new name", lambda: self._save(True))
        self.act_export = action(
            "export.png", "Export", "Export the chosen parts of the assembly as one STEP or STL file",
            lambda: self._export())
        self.act_undo = action("undo.png", "Undo", "Undo the last assembly change", self._undo)
