    def _install_dock_collapse_button(self, dock):
        content = dock.widget()
        title_bar = QWidget(dock)
        title_bar.setObjectName("dockTitleBar")
        title_bar.setStyleSheet(
            "QWidget#dockTitleBar { background: #292e36; border-bottom: 1px solid #3b424d; }"
            "QLabel { color: #e2e5e9; font-weight: bold; }"
            "QToolButton { padding: 0; margin: 0; min-width: 16px; max-width: 16px; "
            "min-height: 16px; max-height: 16px; }")
        title_layout = QHBoxLayout(title_bar)
        title_layout.setContentsMargins(6, 1, 4, 1)
        title_layout.setSpacing(4)
        title = QLabel(dock.windowTitle(), title_bar)
        title.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        title_layout.addWidget(title)
        dock.windowTitleChanged.connect(title.setText)

        collapse_button = QToolButton(title_bar)
        collapse_button.setFixedSize(18, 18)
        collapse_button.setIconSize(QSize(12, 12))
        collapse_button.setAutoRaise(True)
        collapse_button.setArrowType(Qt.DownArrow)
        collapse_button.setToolTip("Collapse panel")
        collapse_button.setAccessibleName("Collapse panel")
        title_layout.addWidget(collapse_button)
        self._dock_collapse_buttons[dock] = collapse_button

        close_button = None
        if dock.features() & QDockWidget.DockWidgetClosable:
            close_button = QToolButton(title_bar)
            close_button.setFixedSize(18, 18)
            close_button.setIconSize(QSize(12, 12))
            close_button.setAutoRaise(True)
            close_button.setIcon(dock.style().standardIcon(QStyle.SP_TitleBarCloseButton))
            close_button.setToolTip("Close panel")
            close_button.setAccessibleName("Close panel")
            close_button.clicked.connect(dock.close)
            title_layout.addWidget(close_button)

        collapsed_height = title_bar.sizeHint().height() + 2 * dock.style().pixelMetric(
            QStyle.PM_DockWidgetFrameWidth)
        side_dock = self.dockWidgetArea(dock) in (Qt.LeftDockWidgetArea, Qt.RightDockWidgetArea)

        def toggle_collapsed():
            state["collapsed"] = not state["collapsed"]
            if state["collapsed"]:
                content.hide()
                if side_dock:
                    title.hide()
                    if close_button is not None:
                        close_button.hide()
                    margins = title_layout.contentsMargins()
                    frame_width = dock.style().pixelMetric(QStyle.PM_DockWidgetFrameWidth)
                    collapsed_width = margins.left() + collapse_button.width() + margins.right() + \
                        2 * frame_width
                    dock.setMaximumWidth(collapsed_width)
                    dock.setMinimumWidth(collapsed_width)
                else:
                    dock.setMaximumHeight(collapsed_height)
                    dock.setMinimumHeight(collapsed_height)
                collapse_button.setArrowType(Qt.RightArrow)
                collapse_button.setToolTip("Expand panel")
                collapse_button.setAccessibleName("Expand panel")
            else:
                dock.setMaximumSize(state["maximum"])
                dock.setMinimumSize(state["minimum"])
                content.show()
                title.show()
                if close_button is not None:
                    close_button.show()
                collapse_button.setArrowType(Qt.DownArrow)
                collapse_button.setToolTip("Collapse panel")
                collapse_button.setAccessibleName("Collapse panel")
            dock.updateGeometry()

        collapse_button.clicked.connect(toggle_collapsed)
        dock.setTitleBarWidget(title_bar)
        expanded_minimum = dock.minimumSizeHint()
        if dock is self._dock_gear:
            form_minimum = self._gear_scroll_area.widget().minimumSizeHint()
            expanded_minimum = QSize(
                max(expanded_minimum.width(), form_minimum.width()),
                max(expanded_minimum.height(), form_minimum.height() + title_bar.sizeHint().height() +
                    2 * dock.style().pixelMetric(QStyle.PM_DockWidgetFrameWidth)))
        state = {"collapsed": False, "minimum": expanded_minimum,
             "maximum": dock.maximumSize()}
        self._dock_collapse_states[dock] = state
        dock.setMinimumSize(state["minimum"])

    @staticmethod
    def _align_layout_widget_right(layout, widget):
        if layout.indexOf(widget) >= 0:
            layout.setAlignment(widget, Qt.AlignRight | Qt.AlignVCenter)
            return True
        for index in range(layout.count()):
            nested = layout.itemAt(index).layout()
            if nested is not None and MainWindow._align_layout_widget_right(nested, widget):
                return True
        return False

    def _apply_editor_field_width(self):
        """Give the number fields of every editor panel the same width as the Extrusion /
        Gear / Thread fields. The widget style sheet also lifts the theme's 63 px cap, so the
        value and its unit fit."""
        width = getattr(self, "_editor_field_width", None)
        if width is None: return
        rule = "min-width: %dpx; max-width: %dpx;" % (width, width)
        for name in ("_dock_ext", "_dock_surface", "_dock_feat", "_dock_angle_draft",
                     "_dock_cut", "_dock_gear", "_dock_thread", "_dock_pump"):
            dock = getattr(self, name, None)
            if dock is None: continue
            for spin in dock.findChildren(QDoubleSpinBox) + dock.findChildren(QSpinBox):
                if spin.styleSheet() != rule: spin.setStyleSheet(rule)
            self._refresh_dock_minimum(dock)

    def _align_editor_inputs(self):
        for dock in (self._dock_ext, self._dock_surface, self._dock_feat,
                 self._dock_angle_draft, self._dock_cut, self._dock_gear, self._dock_thread,
                 self._dock_pump):
            for spin in dock.findChildren(QDoubleSpinBox) + dock.findChildren(QSpinBox):
                layout = spin.parentWidget().layout()
                if layout is not None:
                    self._align_layout_widget_right(layout, spin)
            for combo in dock.findChildren(QComboBox):
                combo.setSizeAdjustPolicy(QComboBox.AdjustToContents)
                combo.ensurePolished()
                combo.setFixedWidth(combo.sizeHint().width())
                layout = combo.parentWidget().layout()
                if layout is not None:
                    self._align_layout_widget_right(layout, combo)
        self._apply_editor_field_width()      # (no-op until the shared width is known)

    def _build_props(self):
        """Properties of the selected object: name, type, transform, size, colour."""
        w=QFrame(); w.setFrameShape(QFrame.StyledPanel)
        lay=QVBoxLayout(w); lay.setContentsMargins(6,6,6,6); lay.setSpacing(4)
        lay.addWidget(QLabel("<b>Properties</b>"))
        # laid out like the Assembly window's part panel: labels on the left, values next to
        # them, compact rows; free width stays empty on the right
        form=QFormLayout(); form.setLabelAlignment(Qt.AlignLeft | Qt.AlignVCenter)
        form.setFormAlignment(Qt.AlignLeft | Qt.AlignTop)
        # The row spacing comes from the labels' padding, not the layout: rows hidden for the
        # selected object (import position / rotation …) then leave no gap.
        form.setHorizontalSpacing(8); form.setVerticalSpacing(0)
        form.setContentsMargins(0, 0, 0, 0)
        w.setStyleSheet("QLabel { padding-top: 3px; padding-bottom: 3px; }")
        self.p_name=QLineEdit(); self.p_name.setMaximumWidth(200)
        self.p_name.editingFinished.connect(self._on_prop_name)
        self.p_type=QLabel(); self.p_parent=QLabel(); self.p_pos=QLabel(); self.p_center=QLabel()
        self.p_size=QLabel(); self.p_extra=QLabel(); self.p_children=QLabel()
        self.lbl_prop_extra=QLabel("Details:")
        self.p_pos.setMaximumWidth(220); self.p_extra.setMaximumWidth(220)
        self.p_children.setMaximumWidth(220)
        self.lbl_prop_surface_area=QLabel("Surface area:")
        self.p_surface_area=QLabel("—"); self.p_volume=QLabel("—"); self.p_weight=QLabel("—")
        self.lbl_prop_material=QLabel("Material:")
        self.cb_prop_material=QComboBox()
        self.cb_prop_material.setMaximumWidth(200)
        for material in MATERIAL_DENSITIES_G_CM3:
            self.cb_prop_material.addItem(material, material)
        self.cb_prop_material.setToolTip("Approximate material densities; actual grades and moisture content vary.")
        self.cb_prop_material.currentIndexChanged.connect(self._on_prop_material_changed)
        self.import_position=[]
        self.w_import_position=QWidget(); pos_lay=QHBoxLayout(self.w_import_position)
        pos_lay.setContentsMargins(0,0,0,0); pos_lay.setSpacing(3)
        for axis in "XYZ":
            spin=QDoubleSpinBox(); spin.setRange(-1000000000,1000000000)
            spin.setDecimals(3); spin.setSingleStep(1.0); spin.setFixedWidth(88)
            spin.setToolTip(f"Imported object {axis} position in millimetres")
            spin.valueChanged.connect(self._on_import_transform_changed)
            self.import_position.append(spin); pos_lay.addWidget(QLabel(axis)); pos_lay.addWidget(spin)
        self.w_import_position.setMaximumWidth(320)
        self.lbl_import_position=QLabel("Position (mm):")
        self.w_import_position.hide(); self.lbl_import_position.hide()
        self.import_rotation=[]
        self.w_import_rotation=QWidget(); rot_lay=QHBoxLayout(self.w_import_rotation)
        rot_lay.setContentsMargins(0,0,0,0); rot_lay.setSpacing(3)
        for axis in "XYZ":
            spin=QDoubleSpinBox(); spin.setRange(-360000,360000)
            spin.setDecimals(3); spin.setSingleStep(1.0); spin.setFixedWidth(88)
            spin.setToolTip(f"Imported object rotation around {axis} axis in degrees")
            spin.valueChanged.connect(self._on_import_transform_changed)
            self.import_rotation.append(spin); rot_lay.addWidget(QLabel(axis)); rot_lay.addWidget(spin)
        self.w_import_rotation.setMaximumWidth(320)
        self.lbl_import_rotation=QLabel("Rotation (deg):")
        self.lbl_import_rotation.setToolTip(
            "Applied around the model centre in X, then Y, then Z order")
        self.w_import_rotation.hide(); self.lbl_import_rotation.hide()
        self.chk_import_fixed=QCheckBox("Fixed position/orientation")
        self.chk_import_fixed.toggled.connect(self._on_import_fixed_changed)
        self.chk_import_fixed.hide()
        for lbl in (self.p_type, self.p_parent, self.p_pos, self.p_center, self.p_size,
                    self.p_extra, self.p_children):
            lbl.setTextInteractionFlags(Qt.TextSelectableByMouse); lbl.setWordWrap(True)
        self.p_color=QPushButton("Choose color"); self.p_color.setFixedWidth(140)   # as in Assembly
        self.p_color.setToolTip("Change the colour (extrusions and imported bodies). With several "
                                "objects selected (Shift+click in the explorer) all selected "
                                "bodies get it - not cut extrusions, sketches, assemblies or "
                                "technical drawings")
        self.p_color.clicked.connect(self._choose_color)
        form.addRow("Name:", self.p_name)
        form.addRow(self.lbl_prop_surface_area, self.p_surface_area)
        form.addRow("Volume:", self.p_volume)
        form.addRow("Weight:", self.p_weight)
        form.addRow("Type:", self.p_type)
        form.addRow("Parent:", self.p_parent)
        form.addRow("Children:", self.p_children)
        form.addRow("Bounds min:", self.p_pos)
        form.addRow(self.lbl_import_position, self.w_import_position)
        form.addRow(self.lbl_import_rotation, self.w_import_rotation)
        form.addRow(self.chk_import_fixed)      # (no empty label row left behind when hidden)
        form.addRow("Centre:", self.p_center)
        form.addRow("Size:", self.p_size)
        form.addRow(self.lbl_prop_extra, self.p_extra)
        form.addRow(self.lbl_prop_material, self.cb_prop_material)
        for field in (self.w_import_position, self.w_import_rotation, self.cb_prop_material):
            form.setAlignment(field, Qt.AlignLeft)
        self.lbl_prop_material.hide(); self.cb_prop_material.hide()
        from PyQt5.QtWidgets import QSlider
        # shown as transparency (0 % = solid, as in the assembly); stored as "opacity" = 1 - it
        self.sl_prop_opacity=QSlider(Qt.Horizontal); self.sl_prop_opacity.setRange(0,90)
        self.sl_prop_opacity.setMaximumWidth(100)
        self.sl_prop_opacity.setValue(0)
        self.sl_prop_opacity.setToolTip("Transparency of the selected object (extrusions, imported "
                                        "bodies and sketches): 0 % = solid. With several objects "
                                        "selected (Shift+click in the explorer) all selected bodies "
                                        "get it - not cut extrusions, sketches, assemblies or "
                                        "technical drawings")
        self.lbl_prop_opacity=QLabel("0%")
        self.sl_prop_opacity.valueChanged.connect(self._on_prop_opacity)
        orow=QHBoxLayout(); orow.setContentsMargins(0,0,0,0)
        orow.addWidget(self.sl_prop_opacity); orow.addWidget(self.lbl_prop_opacity)
        self.w_prop_opacity=QWidget(); self.w_prop_opacity.setLayout(orow)
        self.lbl_prop_opacity_title=QLabel("Transparency:")
        appearance = QLabel("<b>Appearance</b>")      # as "Object appearance" in the Assembly
        appearance.setContentsMargins(0, 6, 0, 0)
        form.addRow(appearance)
        form.addRow(self.lbl_prop_opacity_title, self.w_prop_opacity)
        form.addRow("Colour:", self.p_color)
        self._show_prop_opacity(False)
        lay.addLayout(form); lay.addStretch()
        return w

    def _build_measure_panel(self):
        """Measurement results of the Measure tool (the Measurement panel on the right)."""
        w=QWidget()
        lay=QVBoxLayout(w); lay.setContentsMargins(8,8,8,8); lay.setSpacing(6)
        lay.addWidget(QLabel("<b>Measurement</b>"))
        hint=QLabel("Click edges, corners, hole rims or surfaces in the 3-D view to measure them.")
        hint.setWordWrap(True); hint.setStyleSheet("color:#aab2bd;font-size:9pt;")
        lay.addWidget(hint)
        self.txt_measure=QPlainTextEdit(); self.txt_measure.setReadOnly(True)
        self.txt_measure.setLineWrapMode(QPlainTextEdit.NoWrap)
        self.txt_measure.setFont(QFont("Consolas",9))
        self.txt_measure.setMinimumWidth(260)
        lay.addWidget(self.txt_measure, 1)
        return w

    def _set_measure_mode(self, on):
        on=bool(on)
        if on and (self.state["mode"]!=MODE_NORMAL or self._ext_pending is not None
                   or self.view3d._feat_mode or self.view3d._bridge_mode
                   or self._gear_preview is not None or self._pump_preview is not None):
            self._st("Finish or cancel the current sketch / extrusion / bridge / chamfer / fillet / gear first")
            on=False
        if self.act_measure.isChecked()!=on:
            self.act_measure.blockSignals(True); self.act_measure.setChecked(on)
            self.act_measure.blockSignals(False)
        if on==self.view3d._measure_mode: return
        self.view3d.set_measure_mode(on)
        self._dock_measure.setVisible(on)
        self.txt_measure.clear()
        if on: self._on_measure_changed()

    def _on_measure_changed(self):
        if not self.view3d._measure_mode: return
        lines, summary = measurement_report(self.view3d._meas_sel)
        self.txt_measure.setPlainText("\n".join(lines))
        self._st(summary)

